											DATEDIFF(DATA_BAIXA, DATAI), MOTIU_BAIXA, DNI,
											FACTURA_RELACIONADA, CERTIFICAT, IDPAG
											FROM inscripcions AS i INNER JOIN jornades AS j ON
											i.ANY=j.ANY AND i.CURS=j.CODI_CURS AND i.MES=j.MES
											WHERE i.ID = ?",
			"buscarCanvisUser"	=> "SELECT i.ANY, i.MES, DATA_INSC, PAGAMENT, i.OBSERVACIONS,
											`DATA PAG`, MOTIU_BAIXA, DATAI, DATEDIFF(DATA_BAIXA,DATA_INSC),
											DATEDIFF(DATA_BAIXA,DATAI)
											FROM inscripcions AS i INNER JOIN curs AS c ON
											i.ANY=c.ANY AND i.CURS=c.CURS AND i.MES=c.MES
											WHERE DNI = ? AND i.CURS = ? AND ID != ? AND UPPER(`INSC CURS`) != 'D'
											AND ((i.ANY>=2015 AND i.FACTURA_RELACIONADA=?) OR
											(i.ANY<2015 AND `DATA PAG` IS NOT NULL))
											ORDER BY i.ANY DESC, i.MES DESC",
			"buscarAnysDispoCurs"	=> "SELECT ANY FROM curs WHERE ANY >= ?  AND ESTAT != '0' GROUP BY ANY ORDER BY ANY",
			"buscarMesosDispoCurs"	=> "SELECT MES FROM curs WHERE CURS = ? AND ANY = ?  AND ESTAT != '0' GROUP BY MES ORDER BY MES",
			"buscarCursosDispoAnyMes"=> "SELECT CURS FROM curs WHERE ANY = ? AND MES = ?  AND ESTAT != '0' GROUP BY CURS ORDER BY CURS",
			"buscarCursosDispoAny"=> "SELECT CURS FROM curs WHERE ANY = ? AND ESTAT != '0' GROUP BY CURS ORDER BY CURS",
			"buscarHoresDisponibles" => "SELECT HORES FROM curs WHERE ESTAT != '0'
											GROUP BY HORES ORDER BY HORES ",
			"buscarAnysDispoJor"		=> "SELECT ANY FROM jornades WHERE ANY >= ? GROUP BY ANY ORDER BY ANY",
			"buscarMesosDispoJor"	=> "SELECT MES FROM jornades WHERE CODI_CURS = ? AND ANY = ? GROUP BY MES ORDER BY MES",
			"buscarJorDispoAnyMes"	=> "SELECT CODI_CURS FROM jornades WHERE ANY = ? AND MES = ? GROUP BY CODI_CURS ORDER BY CODI_CURS",
			"buscarInfoMostraInfo" => "SELECT ANY, MES, CURS, Grup, NOM, COGNOMS, DNI, CORREU,
						 					TELEFON, ADRECA, Codi_Postal, Poblacio, PERFIL, Titulacio,
											DATA_INSC, `INSC CURS`, TIPUS_INSC, PERENNE, INSC_MAILING, CERTIFICAT,
											`OBS CERT`, GENERAT, OBSERVACIONS, COMENTARIS,  DATA_BAIXA,
											MOTIU_BAIXA, QUI_BAIXA, A_PAGAR, PAGAMENT, `DATA PAG`, IDPAG,
											pag_observacions, forma_pagament, ENTITAT,FRACCIONAT, FRACCIO,
											FACTURA_RELACIONADA, data_reclamacio, reclamat, usuari
											FROM inscripcions WHERE ID = ?",
			"buscarInfoInscripcions" => "SELECT ANY, MES, CURS, Grup, NOM, COGNOMS, DNI, CORREU,
						 					TELEFON, ADRECA, Codi_Postal, Poblacio, PERFIL, Titulacio,
											DATA_INSC, `INSC CURS`, TIPUS_INSC, TIPUS_DESC, VALID_DESC,
											PERENNE, INSC_MAILING, CERTIFICAT,
											`OBS CERT`, GENERAT, OBSERVACIONS, COMENTARIS,  DATA_BAIXA,
											MOTIU_BAIXA, QUI_BAIXA, A_PAGAR, PAGAMENT, `DATA PAG`, IDPAG,
											pag_observacions, forma_pagament, ENTITAT,FRACCIONAT, FRACCIO,
											FACTURA_RELACIONADA, data_reclamacio, reclamat, usuari
											FROM inscripcions WHERE ID = ?",
			"buscarInfoCursHono"	=> "SELECT c.NOM_CURS, c.HORES, c.DATAI, c.DATAF,
											DATEDIFF(CURRENT_DATE, c.DATAI) AS diesi,
											DATEDIFF(CURRENT_DATE, c.DATAF) AS diesf, a.GTAF_AULA,
											c.CURS_ESCOLAR, p.NOM, p.COGNOMS, p.DNI
											FROM curs as c INNER JOIN aula as a ON c.ID_AULA = a.ID_AULA
											INNER JOIN rel_cuho as r ON a.ID_CUHO = r.id_cuho INNER JOIN
											honoraris as h ON h.ID = r.id_hono INNER JOIN personal as p
											ON h.DNI_TUTOR = p.DNI
											WHERE c.ID_CURS = ? AND a.AULA = ? AND h.PERFIL = 'tutor'",
			"buscarInfoJorHono"	=> "SELECT j.TITOL, j.HORES, j.DATAI, j.DATAF,
											DATEDIFF(CURRENT_DATE, j.DATAI) AS diesi,
											DATEDIFF(CURRENT_DATE, j.DATAF) AS diesf, j.GTAF,
											j.CURS_ESCOLAR FROM jornades as j
											WHERE j.ANY = ? AND j.MES = ? AND j.CODI_CURS = ? AND ESTAT = 1",
			"buscarNomPerfil"		=> "SELECT NCURT FROM perfils as p INNER JOIN
											perfils_list as l ON p.ID_PERFIL = l.ID
											WHERE codi = ? AND curs_escolar = ? AND codi_gtaf = ?",
			"buscarNInscrits"		=> "SELECT COUNT(*) AS ninscrits
											FROM inscripcions
											WHERE (`INSC CURS`='0' OR `INSC CURS`='1') AND
											ANY = ? AND MES = ? AND CURS = ? AND Grup = ?",
			"buscarConegut"	=> "SELECT CONEGUT FROM inscripcions WHERE ID = ?",
			"buscarAnysDisponibles"	=> "SELECT ANY FROM curs GROUP BY ANY ORDER BY ANY DESC",
			"buscarMesosDiponibles"	=> "SELECT MES FROM curs GROUP BY MES",
			"buscarCursosDisponibles" => "SELECT CURS FROM curs GROUP BY CURS",
			"buscarAnysJorDisponibles"	=> "SELECT ANY FROM jornades GROUP BY ANY ORDER BY ANY DESC",
			"buscarMesosJorDiponibles"	=> "SELECT MES FROM jornades GROUP BY MES ORDER BY MES ASC",
			"buscarCursosJorDisponibles" => "SELECT CODI_CURS FROM jornades GROUP BY CODI_CURS",
			"buscarOpcionsInscrits"	=> "SELECT `INSC CURS` FROM inscripcions GROUP BY `INSC CURS`",
			"buscarOpcionsComHaPagat"	=> "SELECT forma_pagament FROM factures GROUP BY forma_pagament",
			"buscarOpcionsInscritsAO"	=> "SELECT `PERENNE` FROM inscripcions GROUP BY PERENNE",
			"buscarOpcionsInscritsAO"	=> "SELECT `PERENNE` FROM inscripcions GROUP BY PERENNE",
			"buscarDadesBaixaInsc"	=> "SELECT ANY, MES, CURS, Grup, A_PAGAR, PAGAMENT,
											usuari, `INSC CURS`, PERENNE, NOM, CORREU
											FROM inscripcions WHERE ID = ?",
			"buscarSiTeCursFutur"	=> "SELECT DATAF FROM inscripcions AS i INNER JOIN curs AS c
											ON ( i.ANY=c.ANY AND i.MES=c.MES AND i.CURS=c.CURS )
											INNER JOIN aula AS a ON c.ID_AULA=a.ID_AULA AND i.Grup = a.AULA
											WHERE usuari = ? AND (`INSC CURS`='0' OR `INSC CURS`='1')
											AND DATAF > now() ORDER BY i.ANY DESC, i.MES DESC LIMIT 1",
			"buscarFactura"			=> "SELECT FACTURA_RELACIONADA FROM inscripcions WHERE ID = ?",
			"buscarLastOrdreFact"	=> "SELECT ordre FROM factures WHERE ANY=? AND TIPUS = ?
											ORDER BY any DESC, ordre DESC LIMIT 1",
			"buscarLastFact"			=> "SELECT factura_relacionada FROM factures
											ORDER BY factura_relacionada DESC LIMIT 1",
			"buscarInfoFactura"		=> "SELECT id, any, ordre, num, data, data_pagament,
											generada, rao, cif, adreca, cp, poblacio, concepte1,
											concepte2, import, entitat, curs, hores, observacions
											FROM factures WHERE factura_relacionada = ?",
			"buscarInfoFacturaByNum" => "SELECT id, any, ordre, num, data, data_pagament,
											generada, rao, cif, adreca, cp, poblacio, concepte1,
											concepte2, import, entitat, curs, hores, observacions
											FROM factures WHERE num = ?",
			"buscarInfoFacturaGener"=> "SELECT id, any, ordre, num, data, generada, rao,
											cif, adreca, cp, poblacio, concepte1, concepte2, import
											FROM factures WHERE factura_relacionada = ? AND
											generada IS NOT NULL",
			"buscarInfoCert"			=> "SELECT NOM_CURS, c.ANY, c.CURS, c.MES, i.Grup,
											HORES, aula.GTAF_AULA, FISS, CURS_ESCOLAR,
											DATAI, DATAF, aula.DATA_RES, CERTIFICAT, NOM, COGNOMS,
											DNI, `OBS CERT` FROM inscripcions as i INNER JOIN curs as c
											ON i.ANY = c.ANY AND i.MES = c.MES AND i.CURS = c.CURS
											INNER JOIN aula ON c.ID_AULA = aula.ID_AULA AND i.Grup = aula.AULA
											WHERE i.ID = ?",
			"buscarCodiGtaf"			=> "SELECT GTAF_AULA, DATA_RES, DATA_VALORACIO_AULA FROM aula
											INNER JOIN curs ON curs.ID_AULA = aula.ID_AULA
											WHERE ANY = ? AND MES = ? AND CURS = ? AND AULA = ?",
			"buscarInfoCertAlumne"	=> "SELECT ANY, CURS, MES, DNI, NOM, COGNOMS, ADRECA, Codi_Postal, Poblacio
											FROM inscripcions WHERE ID = ?",
			"buscaIdFactCorreu" 		=> "SELECT f.ID FROM factures AS f INNER JOIN inscripcions as i
											ON f.factura_relacionada=i.FACTURA_RELACIONADA
											WHERE CORREU LIKE ? GROUP BY f.ID",
			"buscaIdFactCorreuID" 	=> "SELECT f.ID FROM factures AS f INNER JOIN inscripcions as i
											ON f.factura_relacionada=i.FACTURA_RELACIONADA
											WHERE f.ID LIKE ? AND CORREU LIKE ? GROUP BY f.ID",
			"buscaIdFactRel" 			=> "SELECT ID FROM factures AS f
											WHERE factura_relacionada LIKE ? GROUP BY ID",
			"buscaIdFactRelID" 		=> "SELECT ID FROM factures AS f WHERE ID LIKE ? AND
											factura_relacionada LIKE ? GROUP BY ID",
			"buscaIdFactNum" 			=> "SELECT ID FROM factures AS f WHERE num = ? GROUP BY ID",
			"buscaIdFactNumID" 		=> "SELECT ID FROM factures AS f WHERE ID LIKE ? AND
											num = ? GROUP BY ID",
			"buscaDniIdFact"			=> "SELECT CIF FROM factures WHERE ID LIKE ?",
			"buscaFactRelInsc"		=> "SELECT FACTURA_RELACIONADA FROM inscripcions WHERE DNI LIKE ? GROUP BY FACTURA_RELACIONADA",
			"buscaFactRelFact"		=> "SELECT factura_relacionada FROM factures WHERE cif LIKE ? GROUP BY FACTURA_RELACIONADA",
			"buscaIdFactCif"			=> "SELECT ID FROM factures WHERE cif LIKE ? GROUP BY factura_relacionada",
			"buscarIdFact"				=> "SELECT ID FROM factures WHERE factura_relacionada LIKE ? ORDER BY rao, any DESC, num DESC",
			"buscarTotesFactId"		=> "SELECT f.ID, f.factura_relacionada, f.any, num, rao,
											cif, f.import, f.curs, f.observacions, GENERAT, `INSC CURS`
											fROM factures AS f INNER JOIN inscripcions as i
											ON f.factura_relacionada=i.FACTURA_RELACIONADA
											WHERE f.ID LIKE ? GROUP BY f.id ORDER BY rao, any DESC, num DESC",
			"buscarInfoFacturaId"	=> "SELECT id, factura_relacionada, any, ordre,
											num, data, data_pagament, generada, rao, cif,
											adreca, cp, poblacio, concepte1, concepte2,
											import, entitat, forma_pagament, curs, hores,
											observacions, E_FACT
											FROM factures WHERE id = ?",
			"buscarInfoFacturaByFact"	=> "SELECT id, factura_relacionada, any, ordre,
											num, data, data_pagament, generada, rao, cif,
											adreca, cp, poblacio, concepte1, concepte2,
											import, entitat, forma_pagament, curs, hores,
											observacions, E_FACT
											FROM factures WHERE factura_relacionada = ? ORDER BY DATA_PAGAMENT DESC",
			"buscarInfoFactInsc"		=> "SELECT DNI, FRACCIONAT, FRACCIO, A_PAGAR, PAGAMENT, pag_observacions
											fROM factures AS f INNER JOIN inscripcions as i
											ON f.factura_relacionada=i.FACTURA_RELACIONADA
											WHERE f.ID LIKE ?",
			"buscarInfoFactInsc2"	=> "SELECT DNI, TIPUS_INSC, FRACCIONAT, FRACCIO, SUM(A_PAGAR), SUM(PAGAMENT), IDPAG, pag_observacions
											FROM factures AS f INNER JOIN inscripcions as i ON
											f.factura_relacionada=i.FACTURA_RELACIONADA WHERE
											f.ID LIKE ? GROUP BY IDPAG ORDER BY A_PAGAR DESC",
			"IniciPujarGTAF_vella"	=> "SELECT i.ID, c.ANY, c.CURS, c.MES, c.`Codi GTAF`,
											i.NOM, i.COGNOMS, i.CORREU, i.DNI, i.TELEFON, i.CERTIFICAT,
											i.`OBS CERT`, i.PERFIL, i.Titulacio, i.A_PAGAR, i.PAGAMENT,
											i.`INSC CURS`, DATEDIFF(c.`DATA FIN`,CURRENT_DATE) AS diesCursAcabat,
											i.A_PAGAR-i.PAGAMENT AS faltaPagar, i.pag_observacions, i.ENTITAT
											FROM (inscripcions AS i INNER JOIN cursos AS c ON c.ANY = i.ANY AND
											c.MES = i.MES AND c.CURS = i.CURS and c.AULA = i.Grup)
											WHERE c.ANY > 2019 AND (i.CERTIFICAT IS NULL OR i.CERTIFICAT = '')
											AND (`INSC CURS` = '1' OR `INSC CURS` = 'M') AND c.data_qualificacions IS NOT NULL AND
											DATEDIFF(c.`DATA FIN`,CURRENT_DATE) <= 0 AND
											( (DATA_VALORACIO IS NULL ) OR (DATA_VALORACIO IS NOT NULL AND i.A_PAGAR-i.PAGAMENT <= 0) )
											ORDER BY c.CURS, c.MES, c.`Codi GTAF`, i.COGNOMS",
			"buscarOpcionsCertificat"	=> "SELECT CERTIFICAT FROM inscripcions WHERE
											ANY > 2019 AND CERTIFICAT IS NOT NULL AND
											CERTIFICAT != '' AND CERTIFICAT != 'PAPER' GROUP BY CERTIFICAT ORDER BY CERTIFICAT DESC",
			"IniciBloqueigCursos_vella"	=> "SELECT c.id_Curs, c.ANY, c.MES, c.HORES, c.CURS, c.AULA,
											c.`NOM CURS`, c.`DATA FIN`, DATEDIFF(c.`DATA FIN`,CURRENT_DATE) AS diesCursAcabat,
											c.DNI_TUTOR, c.`Codi GTAF`, c.data_bloqueig
											FROM cursos AS c
											WHERE DATEDIFF(c.`DATA FIN`,CURRENT_DATE) < -2 AND
											DATEDIFF(c.`DATA FIN`,CURRENT_DATE) > -30 AND
											DNI_TUTOR != '0' AND c.data_bloqueig IS NULL
											GROUP BY c.CURS, c.`Codi GTAF`
											ORDER BY c.HORES, c.CURS, DATEDIFF(c.`DATA FIN`,CURRENT_DATE) DESC",
			"IniciBloqueigCurs"	=> "SELECT c.ID_CURS, c.ANY, c.MES, c.HORES, c.CURS,
											a.AULA, c.NOM_CURS, c.DATAF, DATEDIFF(c.DATAF,CURRENT_DATE) AS diesCursAcabat,
											a.GTAF_AULA, a.DATA_BLOQUEIG
											FROM curs AS c INNER JOIN aula AS a ON c.ID_AULA = a.ID_AULA
											WHERE DATEDIFF(c.DATAF,CURRENT_DATE) < -2 AND
											DATEDIFF(c.DATAF,CURRENT_DATE) > -30 AND c.ESTAT != '0' AND
											a.data_bloqueig IS NULL
											GROUP BY c.CURS, a.GTAF_AULA
											ORDER BY c.HORES, c.CURS, DATEDIFF(c.DATAF,CURRENT_DATE) DESC",
			"IniciAlumnPujatAltaCert"	=> "SELECT ID FROM inscripcions WHERE
											ANY = ? AND MES LIKE ? AND CURS LIKE ? AND Grup = ? AND `INSC CURS`='1' AND
											(CERTIFICAT LIKE 'PUJAT' OR CERTIFICAT LIKE 'ALTA' OR CERTIFICAT LIKE 'ALTA_PUJAT')",
			"cnsCursosCertGtaf"	=> "SELECT AULA FROM curs AS c INNER JOIN aula AS a
											ON c.ID_AULA = a.ID_AULA
			 								WHERE c.ANY = ? AND c.CURS = ? AND c.MES = ? AND a.GTAF_AULA = ?
											ORDER BY AULA",
			"cnsCursosCertGtafById"	=> "SELECT AULA FROM curs AS c INNER JOIN aula AS a
											ON c.ID_AULA = a.ID_AULA
			 								WHERE c.ID_CURS = ? AND a.GTAF_AULA = ?
											ORDER BY AULA",
			"IniciInformesENSE_vella"	=> "SELECT c.id_Curs, c.ANY, c.MES, c.CURS, c.AULA,
											c.`NOM CURS`, p.NOM, p.COGNOMS, c.`Codi GTAF`, c.`DATA INICI`,
											c.`DATA FIN`, c.`Data Resol`, c.data_informe,
											DATEDIFF(c.`DATA FIN`,Now()) AS diesCursAcabat, DNI_TUTOR FROM cursos as c
											INNER JOIN personal as p ON c.DNI_TUTOR = p.DNI
											WHERE (c.ANY>=? AND c.data_valoracio IS NULL
											AND c.`Codi GTAF` IS NOT NULL AND c.`Codi GTAF`!=''
											AND DATEDIFF(c.`DATA FIN`,Now())<0)
											GROUP BY c.CURS, c.ANY, c.MES, c.`Codi GTAF`
											ORDER BY c.ANY, c.`DATA FIN`, c.CURS, c.AULA",
			"IniciInformesFISS_vella"	=> "SELECT c.id_Curs, c.ANY, c.MES, c.CURS, c.AULA,
											c.`NOM CURS`, p.NOM, p.COGNOMS, c.FISS, c.`DATA INICI`,
											c.`DATA FIN`, c.`Data Resol`, c.data_informe,
											DATEDIFF(c.`DATA FIN`,Now()) AS diesCursAcabat, DNI_TUTOR FROM cursos as c
											INNER JOIN personal as p ON c.DNI_TUTOR = p.DNI
											WHERE (c.ANY>=? AND  c.data_valoracio_fiss IS NULL
											AND c.FISS IS NOT NULL AND c.FISS != ''
											AND DATEDIFF(c.`DATA FIN`,Now())<-20)
											GROUP BY c.CURS, c.ANY, c.MES
											ORDER BY c.ANY, c.`DATA FIN`, c.CURS",
			"IniciCursSuperat_vella" => "SELECT c.id_Curs, c.ANY, c.MES, c.HORES, c.CURS, c.AULA, c.`NOM CURS`,
											c.`DATA FIN`, DATEDIFF(c.`DATA FIN`,Now()) AS diesCursAcabat, c.DNI_TUTOR
											FROM cursos as c INNER JOIN personal as p ON c.DNI_TUTOR = p.DNI
											WHERE c.DNI_TUTOR!='0' AND c.data_qualificacions IS NULL
											AND DATEDIFF(c.`DATA FIN`,Now())>=-15 AND DATEDIFF(c.`DATA FIN`,Now())<=2
											GROUP BY c.CURS, c.ANY, c.MES
											ORDER BY c.HORES, c.CURS, c.`DATA FIN`, diesCursAcabat DESC",
			"IniciIniciCursos"		=> "",
			"exPujadaAO"				=> "SELECT DISTINCTROW ID FROM inscripcions AS i WHERE i.PERENNE='0' AND i.`INSC CURS`='1' ORDER BY i.COGNOMS",
			"IniciPujarAO_vella"		=> "SELECT DISTINCTROW c.id_Curs, c.ANY, c.MES, c.CURS, i.Grup, i.NOM, i.COGNOMS,
											i.CORREU, i.usuari, i.Poblacio,
											c.`Codi GTAF`, c.`DATA FIN`, i.CERTIFICAT, i.`OBS CERT`,
											i.PERFIL, i.Titulacio, i.A_PAGAR, i.PAGAMENT,
											p.NOM, p.COGNOMS, i.a_pagar-i.pagament AS pendent, i.reclamat
											FROM cursos as c INNER JOIN inscripcions as i ON
											c.ANY = i.ANY AND c.MES = i.MES AND c.CURS = i.CURS AND c.AULA = i.Grup
											INNER JOIN personal as p ON c.DNI_TUTOR = p.DNI
											WHERE i.PERENNE='0' AND i.`INSC CURS`='1'
											ORDER BY c.CURS, c.MES, i.COGNOMS",
			"IniciPujadaInsc_vella"	=> "SELECT c.id_Curs, i.ANY, i.MES, i.CURS, i.Grup, c.HORES,
											i.NOM, i.COGNOMS, i.CORREU, i.usuari, i.Poblacio,
											i.COMENTARIS, DATEDIFF(c.`DATA INICI`,Now()) as diesCursAcabat, i.ID, i.DNI
											FROM inscripcions as i INNER JOIN cursos as c ON
											i.ANY = c.ANY AND i.MES = c.MES AND i.CURS = c.CURS AND i.Grup = c.AULA
											WHERE DATEDIFF(c.`DATA INICI`,Now())<=? AND i.`INSC CURS`='0' AND
											(c.codi_udg != '#' OR c.codi_udg IS NULL OR c.codi_udg = '') AND
											c.CURS NOT LIKE '%JOR%' AND c.CURS NOT LIKE '%0%'
											ORDER BY i.ANY, i.MES, c.HORES, c.CURS, i.Grup, i.COGNOMS, i.NOM",
			"searchTramit"			=> "SELECT TRAMIT FROM tramitsDep WHERE DATA_RESOL = ? AND ESTAT = 1",
			"obtLastDateTrobada"	=> "SELECT DATA_INICI FROM trobades WHERE ESTAT=1 ORDER BY DATA_INICI DESC LIMIT 1",
			"obtTrobadesAnyActual"	=> "SELECT ID, TITOL, DATA_INICI, MAILING_ENVIAT  FROM trobades
											WHERE DATA_INICI LIKE ? AND ESTAT = 1 ORDER BY DATA_INICI ASC",
			"obtTrobadesAnysAnt"	=> "SELECT ID, TITOL, MAILING_ENVIAT  FROM trobades
											WHERE DATA_INICI < '2021-01-01' AND ESTAT = 1 ORDER BY DATA_INICI ASC",
			"obtInscTrob"			=> "SELECT EMAIL FROM mailing_trobades WHERE ID_TROBADA = ? AND ENVIAT IS NULL GROUP BY EMAIL",
			"obtInfoTrob"			=> "SELECT TITOL, DATA_INICI, URL FROM trobades
											INNER JOIN amigable ON trobades.ID_URL = amigable.ID WHERE trobades.ID = ?",
			"updMailTrob"			=> "UPDATE mailing_trobades SET ENVIAT = CURRENT_TIME WHERE EMAIL = ? AND ID_TROBADA = ?",
			"buscaDadesAltresInsc"	=> "SELECT ID, DATA_INSC, NOM, COGNOMS, DNI, CORREU,
											TELEFON, ADRECA, Codi_Postal, Poblacio, PERFIL, Titulacio
											FROM inscripcions
											WHERE DNI = ? AND ID != ? GROUP BY NOM, COGNOMS,
											CORREU, DNI, ADRECA, Codi_Postal, Poblacio, PERFIL, TITULACIO
											ORDER BY DATA_INSC DESC",
			"buscaAulesEdicio_vella"	=> "SELECT AULA FROM cursos WHERE ANY = ? AND MES LIKE ? AND CURS LIKE ? ORDER BY AULA",
			"buscaAulesEdicio"	=> "SELECT aula.AULA FROM curs INNER JOIN aula ON curs.ID_AULA = aula.ID_AULA WHERE ANY = ? AND MES LIKE ? AND CURS LIKE ? ORDER BY AULA",
			"nInscritsEdicio"		=> "SELECT ID FROM inscripcions WHERE ANY=? AND MES=? AND CURS=? AND Grup=? AND (`INSC CURS`='0' OR `INSC CURS`='1')",
			"buscarHaRealitzatCurs"	=> "SELECT ANY, MES FROM inscripcions WHERE CURS=? AND DNI LIKE ? AND GENERAT=1 AND ID != ?",
			"buscarInscrDupl"		=> "SELECT ANY, MES FROM inscripcions WHERE CURS=? AND DNI LIKE ? AND (`INSC CURS`='0' OR `INSC CURS`='1') AND COMENTARIS NOT LIKE '%REVISAT DUPLICAT%' AND ID != ?",
			"buscarCursDeriva"	=> "SELECT DERIVA FROM informacio WHERE CODI_CURS=? AND ESTAT=1",
			"buscarCursUrlRel"	=> "SELECT URL FROM informacio INNER JOIN amigable
			 								ON informacio.ID_AMIGABLE = amigable.ID WHERE CODI_CURS=? AND ESTAT=1",
			"buscarPagaments"		=> "SELECT TIPUS_INSC, ID, ANY, MES, CURS, NOM, COGNOMS, CORREU, DNI,
											A_PAGAR, PAGAMENT, FACTURA_RELACIONADA,
											FRACCIONAT, FRACCIO, pag_observacions, IDPAG
											FROM inscripcions WHERE DNI LIKE ? AND A_PAGAR>0 AND
											A_PAGAR>PAGAMENT AND (`INSC CURS`='1' OR
											`INSC CURS`='0' OR `INSC CURS`='M')
											AND TIPUS_INSC = ? ORDER BY DATA_INSC",
			"buscarPagamentsPack"	=> "SELECT TIPUS_INSC, ID, NOM, COGNOMS, CORREU, DNI,
											SUM(A_PAGAR) AS A_PAGAR, SUM(PAGAMENT) AS PAGAMENT, FACTURA_RELACIONADA,
											FRACCIONAT, FRACCIO, pag_observacions, OBSERVACIONS, IDPAG
											FROM inscripcions WHERE DNI LIKE ? AND A_PAGAR>0 AND
											(`INSC CURS`='1' OR `INSC CURS`='0' OR `INSC CURS`='M')
											AND TIPUS_INSC = ?  GROUP BY IDPAG ORDER BY DATA_INSC",
			"buscarInfoPack"			=> "SELECT ip.CODI FROM info_pack AS ip
											WHERE ip.ID_PACK = ? AND ip.ESTAT = 1",
			"buscarPersRespGrup2"	=> "SELECT r.IDPAG, r.DNI
											FROM inscripcions as i INNER JOIN respGrups as r ON i.IDPAG = r.IDPAG
											WHERE TIPUS_INSC = 'G' AND (`INSC CURS` = '0'
												OR `INSC CURS` = '1' OR `INSC CURS` = 'M') AND
											(r.DNI = ? OR i.DNI = ?) GROUP BY r.IDPAG",
			"buscarPersGrup"			=> "SELECT NOM, COGNOMS, DNI, CORREU FROM inscripcions
											WHERE TIPUS_INSC = 'G' AND IDPAG = ? AND
											(`INSC CURS` = '0' OR `INSC CURS` = '1' OR `INSC CURS` = 'M')
											ORDER BY COGNOMS, NOM",
			"buscarPagamentsGrup"	=> "SELECT TIPUS_INSC, ID, ANY, MES, CURS, NOM, COGNOMS, CORREU, DNI,
											SUM(A_PAGAR) AS total, SUM(PAGAMENT) AS PAGAMENT, FACTURA_RELACIONADA,
											FRACCIONAT, FRACCIO, pag_observacions, IDPAG
											FROM inscripcions WHERE IDPAG LIKE ? AND (`INSC CURS`='1' OR `INSC CURS`='0')
											AND TIPUS_INSC = ? GROUP BY IDPAG ORDER BY DATA_INSC",
			"buscarPagamentsByFact" => "SELECT TIPUS_INSC, i.ID,i.ANY, MES, i.CURS,
											SUM(A_PAGAR) AS TOTAL, SUM(PAGAMENT) AS PAGAMENT,
											i.FACTURA_RELACIONADA, FRACCIONAT, FRACCIO, pag_observacions,
											IDPAG, i.OBSERVACIONS, f.cif, f.E_FACT FROM inscripcions as i
											INNER JOIN factures as f ON i.FACTURA_RELACIONADA = f.factura_relacionada
											WHERE NUM = ? AND A_PAGAR>0 AND A_PAGAR > PAGAMENT AND
											(i.`INSC CURS`='1' OR i.`INSC CURS`='0' OR i.`INSC CURS`='M')
											GROUP BY FACTURA_RELACIONADA ORDER BY i.DATA_INSC",
			"buscarNomResPagamentsByFact" => "SELECT NOM, COGNOMS, CORREU FROM inscripcions
											WHERE FACTURA_RELACIONADA = ? AND A_PAGAR>0 AND A_PAGAR > PAGAMENT AND
											(i.`INSC CURS`='1' OR i.`INSC CURS`='0' OR i.`INSC CURS`='M') AND
											i.TIPUS_INSC = ? GROUP BY FACTURA_RELACIONADA ORDER BY i.DATA_INSC",
			"buscarRegNoPayByCodi"	=> "SELECT ID, NIFC, NOMC, MAILC, CCURS, NOM_CURS,
											IMPORT, FACT_REL, OBSERVACIONS FROM regal
											WHERE (CODI=? AND FACT_REL = 0)",
			"buscarRegNoPayByDni"	=> "SELECT ID, NIFC, NOMC, MAILC, CCURS, NOM_CURS,
											IMPORT, FACT_REL, OBSERVACIONS FROM regal
											WHERE (NIFC LIKE ? AND FACT_REL = 0)",
			"buscarRegalById"		=> "SELECT NOM_CURS, CCURS, NOMC, NIFC, MAILC, ADRECAC,
											POBLEC, CPC, CODI, FACT_REL, ORIGEN, DESTI FROM regal WHERE ID=?",
			"buscarHoresCursGen"	=> "SELECT HORES FROM curs WHERE
											( (DATAI+8>CURRENT_DATE AND (HORES=30 OR HORES=40 OR HORES=60 OR HORES=50)) OR
											(DATAI+15>CURRENT_DATE AND (HORES=100)) ) AND CURS LIKE ? AND PUBLIC=1
											AND (CURS NOT LIKE '%JOR%') AND (CURS NOT LIKE '%0%')
											ORDER BY ANY, MES LIMIT 1",
			"buscarHoresCurs"		=> "SELECT HORES FROM curs WHERE
											DATAI+?>CURRENT_DATE AND CURS LIKE ? AND PUBLIC=1
											AND (CURS NOT LIKE '%JOR%') AND (CURS NOT LIKE '%0%')
											ORDER BY ANY, MES LIMIT 1",
			"buscarHoresLastEd"	=> "SELECT HORES FROM curs WHERE CURS LIKE ? AND PUBLIC=1
											AND (CURS NOT LIKE '%JOR%') AND (CURS NOT LIKE '%0%')
											ORDER BY ANY DESC, MES DESC LIMIT 1",
			"buscarPersRespGrup"	=> "SELECT r.NOM, r.COGNOMS, r.DNI, r.CORREU, r.ADRECA, r.Codi_Postal,
											r.Poblacio, i.FACTURA_RELACIONADA, i.FRACCIONAT, i.FRACCIO, SUM(i.A_PAGAR) as total, SUM(i.PAGAMENT) as pagat
											FROM inscripcions as i INNER JOIN respGrups as r ON i.IDPAG = r.IDPAG
											WHERE TIPUS_INSC = 'G' AND (`INSC CURS` = '0' OR
											`INSC CURS` = '1' OR `INSC CURS` = 'M') AND
											r.IDPAG = ? GROUP BY r.IDPAG",
			"buscarInfoPersRespGrup"	=> "SELECT r.NOM, r.COGNOMS, r.DNI, r.CORREU
											FROM respGrups as r WHERE	r.IDPAG = ?",
			"buscarInfoEdGrup"	=> "SELECT i.ANY, i.MES, i.CURS, c.NOM_CURS, c.HORES, c.DATAI, c.DATAF
											FROM inscripcions as i INNER JOIN curs as c
											ON i.ANY = c.ANY and i.MES = c.MES and i.CURS = c.CURS
											WHERE IDPAG = ? AND (`INSC CURS` = '0' OR
											`INSC CURS` = '1' OR `INSC CURS` = 'M')
											AND GTAF IS NOT NULL AND GTAF!='' GROUP BY i.CURS, i.MES, i.ANY, c.HORES",
			"buscarInfoEdGrupByFact" => "SELECT i.ANY, i.MES, i.CURS, c.NOM_CURS, c.HORES, c.DATAI, c.DATAF
											FROM inscripcions as i INNER JOIN curs as c
											ON i.ANY = c.ANY and i.MES = c.MES and i.CURS = c.CURS
											WHERE FACTURA_RELACIONADA = ? AND (`INSC CURS` = '0'
											OR `INSC CURS` = '1' OR `INSC CURS` = 'M')
											AND GTAF IS NOT NULL AND GTAF!='' GROUP BY i.CURS, i.MES, i.ANY, c.HORES",
			"searchMembresGrup"	=> "SELECT ID, A_PAGAR, PAGAMENT, FACTURA_RELACIONADA
											FROM inscripcions WHERE TIPUS_INSC = ? AND
											(`INSC CURS` = '0' OR `INSC CURS` = '1' OR
											`INSC CURS` = 'M') AND IDPAG = ? ORDER BY ID",
			"searchMembresGrup2"	=> "SELECT ID, A_PAGAR, PAGAMENT, FACTURA_RELACIONADA
											FROM inscripcions WHERE TIPUS_INSC = ? AND
											(`INSC CURS` = '0' OR `INSC CURS` = '1' OR
											`INSC CURS` = 'M') AND IDPAG = ? ORDER BY ID DESC",
			"cnsInscsPack"			=> "SELECT NOM, COGNOMS, DNI, CORREU, ADRECA,
											Codi_Postal, Poblacio, FACTURA_RELACIONADA,
											SUM(A_PAGAR), `INSC CURS`, SUM(PAGAMENT), FRACCIO,
											FRACCIONAT, OBSERVACIONS, pag_observacions
											FROM inscripcions WHERE IDPAG=? AND
											(`INSC CURS` = '0' OR `INSC CURS` = '1' OR
											`INSC CURS` = 'M') GROUP BY IDPAG",
			"cnsDadesCursPack"	=> "SELECT c.DATAI, c.DATAF, c.CURS_ESCOLAR, c.FISS,
											c.GTAF, c.DATA_RESOL, c.ANY, c.MES, c.CURS, c.HORES,
											 i.ID, i.ID_AMIGABLE, i.TITOL, c.ESTAT, ip.TITOL
											FROM packs AS p INNER JOIN info_pack AS ip ON
											p.ID_PACK = ip.ID_PACK INNER JOIN curs AS c ON
											p.ID_CURS = c.ID_CURS INNER JOIN informacio AS i ON
											c.CURS = i.CODI_CURS WHERE ip.ID_PACK = ? AND
											p.PUBLIC=1 AND c.PUBLIC=1 AND c.CURS!='PROVA' AND
											c.CURS NOT LIKE '%0%' AND c.ESTAT!='0' AND i.ESTAT = 1
											AND c.CURS NOT LIKE '%JOR%' ORDER BY c.DATAI",
			"buscarDadesUrlAmig"	=> "SELECT NAME, TITLE, TARGET, URL FROM amigable WHERE ID=?",
			"searchMembresFactRel"	=> "SELECT ID, A_PAGAR, PAGAMENT, FACTURA_RELACIONADA FROM inscripcions
											WHERE (`INSC CURS` = '0' OR `INSC CURS` = '1' OR `INSC CURS` = 'M') AND
											FACTURA_RELACIONADA = ? ORDER BY ID",
			"buscarDadesCursAlByIdPag"	=> "SELECT ANY, MES, CURS, NOM, COGNOMS, DNI,
											CORREU, ADRECA, Codi_Postal, Poblacio, FACTURA_RELACIONADA,
											A_PAGAR, `INSC CURS`, PAGAMENT, FRACCIO, FRACCIONAT
											FROM inscripcions WHERE IDPAG=? AND (`INSC CURS`='0' OR `INSC CURS`='1' OR `INSC CURS`='M')",
			"buscarDadesCursAllByIdPag"	=> "SELECT ANY, MES, CURS, NOM, COGNOMS, DNI,
											CORREU, ADRECA, Codi_Postal, Poblacio, FACTURA_RELACIONADA,
											A_PAGAR, `INSC CURS`, PAGAMENT, FRACCIO, FRACCIONAT, 	pag_observacions, ENTITAT
											FROM inscripcions WHERE IDPAG=? AND
											(`INSC CURS`='0' OR `INSC CURS`='1' OR `INSC CURS`='M')",
			"buscaIdsCursosAntic"	=> "SELECT id_Curs FROM cursos WHERE ID_CURS LIKE ? AND ANY LIKE ? AND MES LIKE ? AND CURS LIKE ? GROUP BY ANY, MES, CURS ORDER BY id_Curs",
			"buscaIdsCursos"			=> "SELECT ID_CURS FROM curs WHERE ID_CURS LIKE ? AND ANY LIKE ? AND MES LIKE ? AND CURS LIKE ? ORDER BY ID_CURS",
			"buscaDadesCursByIdOrdAntic"	=> "SELECT id_Curs, ANY, MES, CURS, codi_udg, `DATA INICI`,`DATA FIN` FROM cursos WHERE ID_CURS LIKE ?",
			"buscaDadesCursByIdOrd"	=> "SELECT ID_CURS, ANY, MES, CURS, ESTAT, DATAI, DATAF FROM curs WHERE ID_CURS LIKE ?",
			"buscarDadesEdCursByIdAntic"	=> "SELECT ANY, MES, CURS, `NOM CURS`,
											`DATA INICI`,`DATA FIN`, HORES, curs_escolar,`Codi GTAF`,
											FISS, `Data Resol`, data_qualificacions, data_bloqueig, `data_valoracio`,
											`data_valoracio_fiss`, `DNI_TUTOR`, codi_udg, OBSERVACIONS FROM cursos
											WHERE id_Curs LIKE ? AND AULA = 'A'",
			"buscarDadesEdCursById"	=> "SELECT ANY, MES, CURS, NOM_CURS, DATAI, DATAF,
											HORES, CURS_ESCOLAR, aula.GTAF_AULA, FISS,
											aula.DATA_RES, DATA_QUAL, aula.DATA_BLOQUEIG,
											aula.DATA_VALORACIO_AULA, DATA_VALORACIO_FISS,
											aula.ID_AULA, ESTAT, PUBLIC, OBSERVACIONS
											FROM curs INNER JOIN aula ON curs.ID_AULA = aula.ID_AULA
											WHERE ID_CURS = ? AND AULA = 'A'",
			"cnsHaRealitzatCurs"	=> "SELECT ANY, MES FROM inscripcions WHERE CURS=? AND DNI=? AND GENERAT=1",
			"buscarNumAulesByIdAntic"	=> "SELECT AULA FROM cursos WHERE ANY = ? AND MES = ? AND CURS = ?",
			"buscarNumAulesById"	=> "SELECT AULA FROM aula WHERE ID_AULA = ?",
			"buscarDadesAulaByIdCursAntic"	=> "SELECT AULA, ANY, MES, CURS,
											`Codi GTAF`, `Data Resol`, data_bloqueig, `data_valoracio`,
											DATA_REVISIO, DATA_INFORME, cursos.OBSERVACIONS, DNI_TUTOR
											FROM cursos
											WHERE ID_CURS LIKE ? ORDER BY AULA",
			"cnsAulaByIdCursAntic"	=> "SELECT AULA, ANY, MES, CURS, DATA_REVISIO,
											DATA_INFORME, cursos.OBSERVACIONS, DNI_TUTOR,
											personal.NOM, personal.COGNOMS FROM cursos
											INNER JOIN personal ON personal.DNI = cursos.DNI_TUTOR
											WHERE ID_CURS LIKE ? ORDER BY AULA",
			"buscarDadesAulaById"	=> "SELECT AULA, curs.ANY, curs.MES, curs.CURS,
											aula.GTAF_AULA, aula.DATA_RES, aula.DATA_BLOQUEIG, aula.DATA_VALORACIO_AULA,
											DATA_REVISIO, DATA_INFORME, aula.OBS, DNI_TUTOR,
											personal.NOM, personal.COGNOMS, curs.ID_AULA
											FROM curs INNER JOIN aula ON curs.ID_AULA = aula.ID_AULA
											INNER JOIN rel_cuho ON rel_cuho.id_cuho = aula.ID_CUHO
											INNER JOIN honoraris on honoraris.ID = rel_cuho.id_hono
											INNER JOIN personal ON personal.DNI = honoraris.DNI_TUTOR
											WHERE ID_CURS LIKE ? AND ACTIU = 1 AND perfil = 'tutor'
											ORDER BY AULA",
			"cnsAulaById"				=> "SELECT AULA, curs.ANY, curs.MES, curs.CURS,
											DATA_REVISIO, DATA_INFORME, aula.OBS, DNI_TUTOR,
											personal.NOM, personal.COGNOMS, curs.ID_AULA
											FROM curs INNER JOIN aula ON curs.ID_AULA = aula.ID_AULA
											INNER JOIN rel_cuho ON rel_cuho.id_cuho = aula.ID_CUHO
											INNER JOIN honoraris on honoraris.ID = rel_cuho.id_hono
											INNER JOIN personal ON personal.DNI = honoraris.DNI_TUTOR
											WHERE ID_CURS LIKE ? AND AULA = ? AND ACTIU = 1 AND perfil = 'tutor'
											ORDER BY AULA",
			"buscarInscrCursGrup"	=> "SELECT NOM, COGNOMS, DNI, CORREU, CERTIFICAT,
											A_PAGAR, PAGAMENT, `INSC CURS`
											FROM inscripcions
											WHERE ANY = ? AND MES = ? AND CURS = ? AND
											Grup LIKE ? ORDER BY `INSC CURS`, COGNOMS, NOM",
			"buscarInscrCursByCursInsc"			=> "SELECT i.ID, NOM, COGNOMS, DNI, CORREU, TELEFON, CERTIFICAT, A_PAGAR, PAGAMENT, FACTURA_RELACIONADA, `INSC CURS`, i.OBSERVACIONS FROM inscripcions as i WHERE ANY = ? AND MES = ? AND CURS = ? AND `INSC CURS` = ? ORDER BY `INSC CURS`, COGNOMS, NOM",
			"buscarInscrPendentCursByCursInsc"		=> "SELECT i.ID, NOM, COGNOMS, DNI, CORREU, TELEFON, CERTIFICAT,
											A_PAGAR, PAGAMENT, IDPAG, FACTURA_RELACIONADA, `INSC CURS`, i.OBSERVACIONS, TIPUS_INSC
											FROM inscripcions as i INNER JOIN curs AS c ON
											c.ANY = i.ANY AND c.MES = i.MES AND c.CURS = i.CURS
											WHERE i.ANY = ? AND i.MES = ? AND i.CURS = ?
											AND `INSC CURS` = ? AND (correu_pendent_inici='1' OR correu_pendent_inici_gen = '1')
											ORDER BY `INSC CURS`, COGNOMS, NOM",
			"buscarProxEdObertInsc"	=> "SELECT ANY, MES FROM curs AS c INNER JOIN aula AS a ON
											c.ID_AULA=a.ID_AULA INNER JOIN rel_cuho AS r ON r.ID_CUHO=a.ID_CUHO
											INNER JOIN honoraris AS h ON r.ID_HONO=h.ID WHERE c.CURS=? AND PUBLIC=1
											AND c.CURS NOT LIKE '%0%' AND c.ESTAT!='0' AND r.ACTIU=1 AND
											(DATEDIFF(DATAI + ?,CURRENT_DATE)>0) AND c.CURS NOT LIKE '%JOR%' AND
											(a.ID_CUHO=17 OR a.ID_CUHO=13 OR (a.ID_CUHO!=17 AND h.DNI_TUTOR='GENERIC')
											OR (a.ID_CUHO!=17 AND  h.DNI_TUTOR!='GENERIC' AND AULA='A' AND perfil='tutor'
											AND ORDRE_TUTOR is not NULL)) ORDER BY ANY, MES LIMIT ?",
			"buscarDadesPersonalByCurs"	=> "SELECT p.DNI, p.NOM, p.COGNOMS, p.MAIL_PRISMA, p.MAIL_PERSONAL
											FROM curs AS c INNER JOIN aula ON aula.ID_AULA = c.ID_AULA
											INNER JOIN rel_cuho AS r ON aula.ID_CUHO = r.id_cuho
											INNER JOIN honoraris AS h ON r.id_hono=h.ID
											INNER JOIN personal AS p ON h.DNI_TUTOR=p.DNI
											WHERE c.ANY = ? AND c.MES = ? AND c.CURS = ? AND AULA = ? AND h.PERFIL = ? AND p.ESTAT = ?",
			"buscarNumEdicio"	=> "SELECT COUNT(ID) FROM inscripcions WHERE
											( OBSERVACIONS LIKE ? OR TIPUS_INSC = ? ) AND
											( `INSC CURS` = '1' OR `INSC CURS` = '0' ) AND ANY = ? AND MES = ? AND CURS = ?",
			"buscarNumInscEntitats"	=> "SELECT COUNT(ID) FROM inscripcions WHERE
											ENTITAT NOT LIKE '' and ENTITAT IS NOT NULL AND ( `INSC CURS` = '1' OR `INSC CURS` = '0' )
											AND ANY = ? AND MES = ? AND CURS = ?",
			"buscar1ProxEd"			=> "SELECT ANY, MES AS di FROM curs where CURS != 'prova' and ESTAT = '1' and DATAI >= CURRENT_DATE ORDER BY DATAI ASC LIMIT 1",
			"buscar1EdNoFinaltizada"=> "SELECT ANY, MES, HORES FROM curs where
											CURS != 'prova' and ESTAT != '0' and
											DATAF <= CURRENT_DATE ORDER BY DATAI DESC LIMIT 1",
			"cnsIdImgInfo"				=> "SELECT CODI_CURS, ID_IMG_LARGE, ID_IMG_SMALL, ID_IMG_PERFIL FROM informacio ORDER BY ID DESC",
			"cnsPrimeraEdicio"		=> "SELECT DATAI FROM curs WHERE CURS=? AND ESTAT!=0 ORDER BY ANY, MES LIMIT 1",
			"cnsImatgeWebById"		=> "SELECT ALT, URL FROM imatges WHERE ID = ?",
			"cnsImatgeWebVersById"		=> "SELECT ALT, URL, VERSIO FROM imatges WHERE ID = ?",
			"cnsCursos"						=> "SELECT CURS, NOM_CURS, ESTAT FROM curs WHERE ANY=? AND MES = ? ORDER BY CURS ASC",
			"cnsCursosOberts"				=> "SELECT NOM_CURS, CURS, HORES, AULA, ESTAT FROM curs INNER JOIN aula ON aula.ID_AULA = curs.ID_AULA WHERE ANY=? AND MES = ? ORDER BY CURS ASC",
			"cnsNumInsc"					=> "SELECT count(*) FROM inscripcions WHERE ANY = ? AND MES = ? AND CURS = ? AND (`INSC CURS`='0' OR `INSC CURS`='1')",
			"cnsNumInscAula"					=> "SELECT count(*) FROM inscripcions WHERE ANY = ? AND MES = ? AND CURS = ? AND Grup = ? AND (`INSC CURS`='0' OR `INSC CURS`='1')",
			"cnsNumInscGrup"				=> "SELECT count(*) FROM inscripcions WHERE ANY = ? AND MES = ? AND CURS = ? AND GRUP = ? AND (`INSC CURS`='0' OR `INSC CURS`='1')",
			"cnsNumPag"						=> "SELECT count(*) FROM inscripcions WHERE ANY = ? AND MES = ? AND CURS = ? AND PAGAMENT > 0 AND A_PAGAR > 0 AND (`INSC CURS`='0' OR `INSC CURS`='1')",
			"cnsCursosPendents"		=> "SELECT CURS, NOM_CURS, ANY, MES, DATAI FROM curs WHERE ESTAT = ? AND CURS NOT LIKE '%0%' ORDER BY ANY, MES, CURS",
			"cnsAlumnesAmbCursosPendents"		=> "SELECT ID, NOM, COGNOMS, CORREU, DATA_INSC, OBSERVACIONS, A_PAGAR, PAGAMENT, correu_pendent_inici, ENTITAT, TIPUS_INSC
												FROM inscripcions AS i WHERE `INSC CURS`='0'
												AND i.ANY=? AND i.MES=? AND CURS = ? ORDER BY CURS, COGNOMS, NOM",
			"cnsAlumnesAmbCursosPendentsTots"		=> "SELECT ID, NOM, COGNOMS, CORREU, DATA_INSC, OBSERVACIONS, A_PAGAR, PAGAMENT, correu_pendent_inici_gen, ENTITAT, TIPUS_INSC
											FROM inscripcions AS i WHERE `INSC CURS`='0'
											AND i.ANY=? AND i.MES=? AND CURS = ? ORDER BY CURS, COGNOMS, NOM",
			"cnsCursosConfTut"	=> "SELECT NOM_CURS, ID_CURS, c.CURS, c.ID_AULA, AULA,
											aula.ID_CUHO, aula.CONFIRMAT, p.NOM, p.COGNOMS, p.ID_IMG_SMALL
											FROM curs as c INNER JOIN aula ON c.ID_AULA = aula.ID_AULA
											INNER JOIN rel_cuho ON rel_cuho.id_cuho = aula.ID_CUHO
											INNER JOIN honoraris as h ON h.ID = rel_cuho.id_hono
											INNER JOIN personal as p ON p.DNI = h.DNI_TUTOR
											WHERE ANY = ? AND MES = ? AND c.ESTAT != '0'
											AND c.CURS NOT LIKE '%PROVA%' AND c.CURS NOT LIKE '%0%'AND
											rel_cuho.ACTIU = 1 AND h.ESTAT = 1 AND h.PERFIL = 'tutor' AND aula.ID_CUHO != ?",
			"cnsCursPendentAssig"	=> "SELECT NOM_CURS, ID_CURS, c.CURS, aula.ID_AULA, AULA, aula.ID_CUHO, p.NOM, p.COGNOMS
											FROM curs as c INNER JOIN aula ON c.ID_AULA = aula.ID_AULA
											INNER JOIN rel_cuho ON rel_cuho.id_cuho = aula.ID_CUHO
											INNER JOIN honoraris as h ON h.ID = rel_cuho.id_hono
											INNER JOIN personal as p ON p.DNI = h.DNI_TUTOR
											WHERE ANY = ? AND MES = ? AND c.ESTAT != '0'
											AND CONFIRMAT = ? AND c.CURS NOT LIKE '%PROVA%' AND c.CURS NOT LIKE '%0%'AND
											rel_cuho.ACTIU = 1 AND h.ESTAT = 1 AND h.PERFIL = 'tutor' AND aula.ID_CUHO = ?",
			"cnsCursPendConfTutor"	=> "SELECT NOM_CURS, ID_CURS, c.CURS, DATAI, DATAF, aula.ID_AULA, AULA,
											aula.ID_CUHO, p.NOM, p.COGNOMS, p.MAIL_PRISMA, p.MAIL_PERSONAL
											FROM curs as c INNER JOIN aula ON c.ID_AULA = aula.ID_AULA
											INNER JOIN rel_cuho ON rel_cuho.id_cuho = aula.ID_CUHO
											INNER JOIN honoraris as h ON h.ID = rel_cuho.id_hono
											INNER JOIN personal as p ON p.DNI = h.DNI_TUTOR
											WHERE ANY = ? AND MES = ? AND c.ESTAT != '0' AND CONFIRMAT = 0 AND
											c.CURS NOT LIKE '%PROVA%' AND c.CURS NOT LIKE '%0%' AND
											rel_cuho.ACTIU = 1 AND h.ESTAT = 1 AND h.PERFIL = 'tutor'",
			"cnsTutorsPortarCurs"	=> "SELECT ID_CUHO, NOM, COGNOMS, DNI_TUTOR, ID_IMG_LARGE, TITULACIO, h.ORDRE_TUTOR, MAIL_PRISMA, MAIL_PERSONAL
											FROM honoraris AS h INNER JOIN rel_cuho AS r ON h.ID = r.id_hono
											INNER JOIN personal AS p ON p.DNI = h.DNI_TUTOR
											WHERE h.ESTAT='1' AND r.ACTIU=1 AND h.PERFIL='tutor' AND h.CURS=?
											ORDER BY h.ORDRE_TUTOR, COGNOMS, NOM",
			"cnsInfoByIdCuhoCurs"	=> "SELECT DNI_TUTOR FROM honoraris AS h INNER JOIN rel_cuho AS r
											ON h.ID = r.id_hono INNER JOIN personal AS p ON p.DNI = h.DNI_TUTOR
											WHERE h.ESTAT='1' AND r.ACTIU=1 AND h.PERFIL='tutor' AND h.CURS=? AND r.id_cuho=?",
			"cnsIdAula"					=> "SELECT ID_AULA FROM curs WHERE ID_CURS = ?",
			"cnsInfoTutor"				=> "SELECT NOM, COGNOMS, MAIL_PRISMA, MAIL_PERSONAL,
											CURRICULUM, TITULACIO, ID_IMG_LARGE, ID_IMG_SMALL, ID_URL
											FROM personal WHERE DNI = ?",
			"cnsDuplicateIdPag"		=> "SELECT COUNT(ID) AS NPAG, IDPAG FROM inscripcions
											WHERE IDPAG != 0  AND TIPUS_INSC = 'I' AND UPPER(`INSC CURS`) != 'D'
											AND UPPER(`INSC CURS`) != 'C' AND UPPER(`INSC CURS`) != 'X'
											GROUP BY IDPAG HAVING NPAG > 1 ORDER BY NPAG DESC",
			"cnsInfoInscByIdPag"		=> "SELECT ANY, MES, CURS, DNI, NOM, COGNOMS, CORREU,
											`INSC CURS`, A_PAGAR, PAGAMENT, FACTURA_RELACIONADA
											FROM inscripcions WHERE IDPAG = ? AND UPPER(`INSC CURS`) != 'D'
											AND UPPER(`INSC CURS`) != 'C' AND UPPER(`INSC CURS`) != 'X'",
			"cnsInscFaUnMes"			=> "SELECT ID, ANY, MES, CURS, DNI, CORREU, DATA_INSC, `INSC CURS`, A_PAGAR, PAGAMENT, usuari FROM inscripcions
											WHERE DATA_INSC >= DATE_SUB(CURDATE(),INTERVAL 60 DAY)
											AND ( `INSC CURS`='0' OR `INSC CURS` = '1')
											AND COMENTARIS NOT LIKE '%REVISAT DUPLICAT%'
											ORDER BY DNI, CURS, DATA_INSC DESC",
			"cnsCursosAlumnesCert"	=> "SELECT c.CURS, NOM_CURS, DATAF FROM inscripcions AS i INNER JOIN
											curs AS c ON i.ANY = c.ANY AND i.MES = c.MES
											AND i.CURS = c.CURS WHERE c.ANY = ? AND c.MES = ? AND
											c.HORES = ? AND `INSC CURS` = '1' AND c.CURS NOT LIKE '%0%'
											AND (CERTIFICAT = 'ALTA' || CERTIFICAT = 'GTAF')
											AND correu_info_certificat = 0
											GROUP BY c.ANY, c.MES, c.CURS
											ORDER BY NOM_CURS",
			"cnsCursosAlumnesCertCurs"	=> "SELECT c.CURS, NOM_CURS, DATAF FROM inscripcions AS i INNER JOIN
											curs AS c ON i.ANY = c.ANY AND i.MES = c.MES
											AND i.CURS = c.CURS WHERE c.ANY = ? AND c.MES = ? AND
											c.CURS = ? AND `INSC CURS` = '1' AND c.CURS NOT LIKE '%0%'
											AND (CERTIFICAT = 'ALTA' || CERTIFICAT = 'GTAF')
											AND correu_info_certificat = 0
											GROUP BY c.ANY, c.MES, c.CURS
											ORDER BY NOM_CURS",
			"cnsInfoAlumnesCertif"	=> "SELECT ID, Grup, `OBS CERT`, CERTIFICAT, NOM,
											COGNOMS, CORREU, ADRECA, Codi_Postal, Poblacio,
											A_PAGAR, PAGAMENT, ENTITAT FROM inscripcions WHERE ANY = ? AND
											MES = ? AND CURS = ? AND `INSC CURS` = '1' AND CURS NOT LIKE '%0%'
											AND (CERTIFICAT = 'ALTA' || CERTIFICAT = 'GTAF')
											AND correu_info_certificat = 0
											ORDER BY COGNOMS, NOM",
			"cnsCursosAlumnesCursSuperat"	=> "SELECT c.CURS, NOM_CURS, DATAF
											FROM inscripcions AS i INNER JOIN
											curs AS c ON i.ANY = c.ANY AND i.MES = c.MES
											AND i.CURS = c.CURS WHERE c.ANY = ? AND c.MES = ? AND
											c.HORES = ? AND `INSC CURS` = '1' AND c.CURS NOT LIKE '%0%'
											AND (CERTIFICAT = '' || CERTIFICAT IS NULL)
											AND correu_curs_superat = 0
											GROUP BY c.ANY, c.MES, c.CURS
											ORDER BY NOM_CURS",
			"cnsCursosAlumnesCursSuperatCursAula"	=> "SELECT c.CURS, NOM_CURS, DATAF
											FROM inscripcions AS i INNER JOIN
											curs AS c ON i.ANY = c.ANY AND i.MES = c.MES
											AND i.CURS = c.CURS WHERE c.ANY = ? AND c.MES = ? AND
											c.CURS = ? AND i.Grup = ?
											AND `INSC CURS` = '1' AND c.CURS NOT LIKE '%0%'
											AND (CERTIFICAT = '' || CERTIFICAT IS NULL)
											AND correu_curs_superat = 0
											GROUP BY c.ANY, c.MES, c.CURS
											ORDER BY NOM_CURS",
			"cnsInfoAlumnesCursSuperat"	=> "SELECT ID, Grup, OBSERVACIONS, `OBS CERT`, CERTIFICAT, NOM,
											COGNOMS, CORREU, ADRECA, Codi_Postal, Poblacio, USUARI, TIPUS_INSC,
											A_PAGAR, PAGAMENT, IDPAG, ENTITAT FROM inscripcions WHERE ANY = ? AND
											MES = ? AND CURS = ? AND `INSC CURS` = '1' AND CURS NOT LIKE '%0%'
											AND (CERTIFICAT = '' || CERTIFICAT IS NULL)
											AND correu_curs_superat = 0
											ORDER BY COGNOMS, NOM",
			"cnsInfoAlumnesCursSuperatCursAula"	=> "SELECT ID, Grup, OBSERVACIONS, `OBS CERT`, CERTIFICAT, NOM,
											COGNOMS, CORREU, ADRECA, Codi_Postal, Poblacio, USUARI, TIPUS_INSC,
											A_PAGAR, PAGAMENT, IDPAG, ENTITAT FROM inscripcions
											WHERE ANY = ? AND MES = ? AND CURS = ? AND Grup = ?
											AND `INSC CURS` = '1' AND CURS NOT LIKE '%0%'
											AND (CERTIFICAT = '' || CERTIFICAT IS NULL)
											AND correu_curs_superat = 0
											ORDER BY COGNOMS, NOM",
			"cnsCursosAlumnesCursNoSuperat"	=> "SELECT c.CURS, NOM_CURS, DATAF
											FROM inscripcions AS i INNER JOIN
											curs AS c ON i.ANY = c.ANY AND i.MES = c.MES
											AND i.CURS = c.CURS WHERE c.ANY = ? AND c.MES = ? AND
											c.HORES = ? AND `INSC CURS` = '1' AND c.CURS NOT LIKE '%0%'
											AND CERTIFICAT LIKE '%no ap%'
											AND correu_curs_superat = 0
											GROUP BY c.ANY, c.MES, c.CURS
											ORDER BY NOM_CURS",
			"cnsInfoAlumnesCursNoSuperat"	=> "SELECT ID, Grup, OBSERVACIONS, `OBS CERT`, CERTIFICAT, NOM,
											COGNOMS, CORREU, ADRECA, Codi_Postal, Poblacio, USUARI, TIPUS_INSC,
											A_PAGAR, PAGAMENT, IDPAG, ENTITAT FROM inscripcions WHERE ANY = ? AND
											MES = ? AND CURS = ? AND `INSC CURS` = '1' AND CURS NOT LIKE '%0%'
											AND CERTIFICAT LIKE '%no ap%'
											AND correu_curs_superat = 0
											ORDER BY COGNOMS, NOM",
			"cnsSeguimentNoAprove"	=> "SELECT seguiment FROM cursos INNER JOIN suspesos ON
											cursos.id_Curs = suspesos.codicurs WHERE usuari=? AND id_Curs=?",
			"buscarDadesContacte"	=> "SELECT ADRECA, CP, POBLE, FIX, MBL, EMAIL, HORARI, HESTIU, MAPA
											FROM contacte WHERE ESTAT = 1",
			"cnsCursDifAlumnesCampusBD"	=> "SELECT c.CURS, NOM_CURS, DATAF
											FROM inscripcions AS i INNER JOIN
											curs AS c ON i.ANY = c.ANY AND i.MES = c.MES
											AND i.CURS = c.CURS WHERE c.ANY = ? AND c.MES = ? AND
											c.HORES = ? AND `INSC CURS` = '1' AND c.CURS NOT LIKE '%0%'
											AND (CERTIFICAT = '' || CERTIFICAT IS NULL)
											AND correu_curs_superat = 0
											GROUP BY c.ANY, c.MES, c.CURS
											ORDER BY NOM_CURS",
			"cnsInfoDifAlumnesCampusBD"	=> "SELECT ID, Grup, OBSERVACIONS, `OBS CERT`, CERTIFICAT, NOM,
											COGNOMS, CORREU, ADRECA, Codi_Postal, Poblacio, USUARI, TIPUS_INSC,
											A_PAGAR, PAGAMENT, IDPAG, ENTITAT FROM inscripcions WHERE ANY = ? AND
											MES = ? AND CURS = ? AND `INSC CURS` = '1' AND CURS NOT LIKE '%0%'
											AND (CERTIFICAT = '' || CERTIFICAT IS NULL)
											AND correu_curs_superat = 0
											ORDER BY COGNOMS, NOM",
			"cnsCursDifAlumnesCampusAOBD"	=> "SELECT c.CURS, NOM_CURS, DATAF
											FROM inscripcions AS i INNER JOIN
											curs AS c ON i.ANY = c.ANY AND i.MES = c.MES
											AND i.CURS = c.CURS WHERE c.ANY = ? AND c.MES = ? AND
											c.HORES = ? AND `INSC CURS` = '1' AND c.CURS NOT LIKE '%0%'
											AND (CERTIFICAT = '' || CERTIFICAT IS NULL)
											AND correu_curs_superat = 0
											GROUP BY c.ANY, c.MES, c.CURS
											ORDER BY NOM_CURS",
			"cnsInfoDifAlumnesCampusAOBD"	=> "SELECT ID, Grup, OBSERVACIONS, `OBS CERT`, CERTIFICAT, NOM,
											COGNOMS, CORREU, ADRECA, Codi_Postal, Poblacio, USUARI, TIPUS_INSC,
											A_PAGAR, PAGAMENT, IDPAG, ENTITAT FROM inscripcions WHERE ANY = ? AND
											MES = ? AND CURS = ? AND `INSC CURS` = '1' AND CURS NOT LIKE '%0%'
											AND (CERTIFICAT = '' || CERTIFICAT IS NULL)
											AND correu_curs_superat = 0
											ORDER BY COGNOMS, NOM",
			"cnsCursosByAny"			=> "SELECT ANY, MES, CURS, AULA FROM curs INNER JOIN aula ON curs.ID_AULA = aula.ID_AULA
											WHERE ANY = ? AND CURS NOT LIKE '%0%' GROUP BY ANY, MES, CURS, AULA",
			"cnsCursosByAnyMes"		=> "SELECT CURS, Grup AS NUM FROM inscripcions
											WHERE `INSC CURS` = '1' AND ANY = ? AND MES = ? AND CURS NOT LIKE '%0%' GROUP BY CURS, Grup",
			"buscarUsuarisBD"			=> "SELECT usuari, CORREU FROM inscripcions
											WHERE (`INSC CURS`)='1' AND ANY=? AND MES = ? AND CURS = ? AND Grup = ? ORDER BY usuari",
			"cnsAulesObertes"		=> "SELECT DISTINCT CURS FROM curs
											WHERE CURS NOT LIKE '%0%' AND CURS != 'JOR' AND CURS != 'PROVA' GROUP BY CURS ORDER BY CURS",
			"buscarUsuarisBDAO"		=> "SELECT usuari, CORREU FROM inscripcions
											WHERE PERENNE='1' AND (A_PAGAR - PAGAMENT <= 0 OR ENTITAT != '' ) AND CURS = ? ORDER BY usuari",
			"buscarCursDerivat"		=> "SELECT DERIVA FROM informacio WHERE CODI_CURS = ?",
			"cnsCursosAlumnesMatrNoEnvCorreuConf"	=> "SELECT ID, DNI, NOM, COGNOMS, CORREU, USUARI
                                 FROM inscripcions WHERE UPPER(`INSC CURS`)='1' AND ANY=? AND MES=? AND CURS NOT LIKE '%0%' AND enviat_correu_confirmacio=0",
			"cnsAlumnesInscrByAnyMes"	=> "SELECT ID, CURS, DNI, NOM, COGNOMS, CORREU, USUARI
											FROM inscripcions WHERE ANY=? AND MES=? AND CURS NOT LIKE '%0%' AND UPPER(`INSC CURS`)='1'",
			"cnsSiTePromocioDispo"	=> "SELECT CODI_DESCOMPTE, DNI, MES, CURS, PERCENTATGE, USED, DATAI, DATAF
											FROM promocions
											WHERE CODI_DESCOMPTE LIKE ? AND DNI = ? AND USED = 0 AND DATAI<=CURRENT_TIME AND DATAF>=CURRENT_TIME",
			"cnsAlumnDescNoValidat" => "SELECT ID, NOM, COGNOMS, DNI, CORREU, TIPUS_DESC, ANY, CURS, MES
											FROM inscripcions WHERE VALID_DESC = 0 AND ( UPPER(`INSC CURS`)='1' OR UPPER(`INSC CURS`)='0') ORDER BY COGNOMS, NOM, TIPUS_DESC",
			"cnsAlumnProfNovellNoValidat" => "SELECT ID, ID_INSC FROM recent_titulat WHERE VALIDAT = 0 ORDER BY ID_INSC",
			"cnsAlumnProfNovell" => "SELECT ID, VALIDAT FROM recent_titulat WHERE ID_INSC = ?",
			"cnsTipusCursnfo"	=> "SELECT TIPUS_CURS FROM informacio WHERE CODI_CURS = ? AND ESTAT = 1",
			"cnsGtafsSubv"		=> "SELECT GTAF FROM gtafs_subv WHERE ANY = ? AND MES = ? AND CURS = ? AND AULA = ?",
			"buscarConegut"	=> "SELECT CONEGUT FROM inscripcions WHERE ID = ?",
			"cnsCursosAmbForumsPreguntesRespostes"	=> "SELECT ID_CURS, ANY, MES, CURS, AULA, HORES, NOM_CURS
									        FROM curs INNER JOIN aula ON curs.ID_AULA = aula.ID_AULA
									        WHERE ANY >= ? AND (DATA_CANVI_FORUM IS NULL)
									        AND CURS NOT LIKE '%0%' AND DATAF < CURRENT_DATE
											  ORDER BY ANY, MES, HORES, NOM_CURS",
			"cnsReclamacions"			=> "SELECT ID, inscripcions.ANY, inscripcions.MES, inscripcions.CURS,
											DNI, NOM, COGNOMS, CORREU, pag_observacions, TIPUS_INSC, ENTITAT, IDPAG
											FROM inscripcions INNER JOIN curs ON inscripcions.ANY = curs.ANY AND
											inscripcions.MES = curs.MES AND inscripcions.CURS = curs.CURS
											WHERE PAGAMENT = 0 AND `INSC CURS` = '1' AND (reclamat IS NULL OR reclamat = '') AND
											A_PAGAR > 0 AND (DATEDIFF(CURRENT_DATE, DATAI)>6) AND
											(DATEDIFF(CURRENT_DATE,DATA_INSC)>3) ORDER BY ANY, MES, CURS, COGNOMS",
			"cnsRegBaixesSegonaSetnaba" => "SELECT ID, inscripcions.ANY, inscripcions.MES, inscripcions.CURS,
											Grup, TELEFON, DNI, NOM, COGNOMS, CORREU, reclamat,
											pag_observacions, PERENNE, USUARI, TIPUS_INSC, ENTITAT, IDPAG
											FROM inscripcions INNER JOIN curs ON inscripcions.ANY = curs.ANY AND
											inscripcions.MES = curs.MES AND inscripcions.CURS = curs.CURS
											WHERE PAGAMENT = 0 AND `INSC CURS` = '1' AND (reclamat IS NOT NULL OR reclamat != '')
											AND A_PAGAR > 0 AND (DATEDIFF(CURRENT_DATE, data_reclamacio)>=5) AND inscripcions.ANY > 2024
											ORDER BY ANY, MES, CURS, COGNOMS",
			"buscarInfoTaller" 	=> "SELECT DATAI, HORES, ID_PREU
											FROM info_taller WHERE ANY = ? AND MES = ? AND CURS = ?",
			"cnsCursosRecordarPag"	=> "SELECT ANY, MES, CURS FROM curs WHERE (DATEDIFF(CURRENT_DATE,DATAF)>=-3) AND (DATEDIFF(CURRENT_DATE, DATAF)<=7)",
			"cnsAlumnesRecordarPag"	=> "SELECT ID, DNI, NOM, COGNOMS, CORREU, A_PAGAR,
											PAGAMENT, A_PAGAR-PAGAMENT, TIPUS_INSC,
											ENTITAT, data_reclamacio, reclamat, pag_observacions
											FROM inscripcions WHERE ANY = ? AND MES = ? AND CURS = ?
											AND A_PAGAR-PAGAMENT > 0 AND `INSC CURS` = '1' AND
											(pag_observacions IS NULL OR pag_observacions NOT LIKE '%Reclamat fi de curs%')",
			"cnsCursosClaimBaixes"	=> "SELECT ANY, MES, CURS FROM curs WHERE
											(DATEDIFF(CURRENT_DATE, DATAF)>7)",
			"cnsAlumnClaimPag"		=> "SELECT ID, DNI, NOM, COGNOMS, CORREU, A_PAGAR,
											PAGAMENT, A_PAGAR-PAGAMENT, TIPUS_INSC,
											ENTITAT, data_reclamacio, reclamat, pag_observacions, CERTIFICAT, IDPAG
											FROM inscripcions WHERE ANY = ? AND MES = ? AND CURS = ?
											AND A_PAGAR-PAGAMENT > 0 AND `INSC CURS` = '1'",
			"cnsAlumnClaimEntMoros"	=> "SELECT ID, ANY, MES, CURS, DNI, NOM, COGNOMS,
											CORREU, A_PAGAR, PAGAMENT, A_PAGAR-PAGAMENT,
											data_reclamacio, reclamat, pag_observacions
											FROM inscripcions WHERE A_PAGAR-PAGAMENT > 0 AND `INSC CURS` = 'M'
											AND ENTITAT != '' AND ENTITAT IS NOT NULL ",
			"cnsAlumnClaimAlumnNoCertMoros"	=> "SELECT ID, ANY, MES, CURS, DNI, NOM, COGNOMS,
											CORREU, A_PAGAR, PAGAMENT, A_PAGAR-PAGAMENT,
											data_reclamacio, reclamat, pag_observacions
											FROM inscripcions WHERE A_PAGAR-PAGAMENT > 0 AND `INSC CURS` = 'M'
											AND (ENTITAT = '' OR ENTITAT IS NULL)
											AND (CERTIFICAT = '' OR CERTIFICAT IS NULL)
											ORDER BY ANY DESC, MES DESC, CURS",
			"cnsAlumnClaimAlumnCertMoros"	=> "SELECT ID, ANY, MES, CURS, DNI, NOM, COGNOMS,
											CORREU, A_PAGAR, PAGAMENT, A_PAGAR-PAGAMENT,
											data_reclamacio, reclamat, pag_observacions
											FROM inscripcions WHERE A_PAGAR-PAGAMENT > 0 AND `INSC CURS` = 'M'
											AND (ENTITAT = '' OR ENTITAT IS NULL)
											AND (CERTIFICAT != '' AND CERTIFICAT IS NOT NULL)
											ORDER BY ANY DESC, MES DESC, CURS",
			"cnsEntMoros"				=> "SELECT ENTITAT, SUM(A_PAGAR-PAGAMENT)
											FROM inscripcions WHERE A_PAGAR-PAGAMENT > 0 AND `INSC CURS` = 'M'
											AND ENTITAT != '' AND ENTITAT IS NOT NULL
											GROUP BY ENTITAT",
			"cnsCoursesByYearMonth"	=> "SELECT ID_CURS, ANY, MES, CURS, AULA, NOM_CURS, HORES, ESTAT
											FROM curs INNER JOIN aula ON aula.ID_AULA = curs.ID_AULA
											WHERE ANY = ? AND MES = ? AND ESTAT != '0' AND
											CURS NOT LIKE '%PROVA%' AND CURS NOT LIKE '%0%' ORDER BY HORES, CURS, AULA",
			"cnsCoursesByYearMonthHours" => "SELECT ID_CURS, ANY, MES, CURS, AULA, NOM_CURS, HORES, ESTAT
											FROM curs INNER JOIN aula ON aula.ID_AULA = curs.ID_AULA
											WHERE ANY = ? AND MES = ? AND HORES = ? AND ESTAT != '0' AND
											CURS NOT LIKE '%PROVA%' AND CURS NOT LIKE '%0%' ORDER BY HORES, CURS, AULA",
			"cnsDataSessioMixt"		=> "SELECT DATA_SESSIO FROM sessions_sincrones WHERE
											ANY = ? AND MES = ? AND CURS = ? AND NUM_SESSIO = ? AND ESTAT = 1",

			"xxx"							=> "xxx",
			"insertRegInscCanvi"		=> "INSERT INTO inscripcions (ANY, MES, CURS,
											DATA_INSC, NOM, COGNOMS, CORREU, DNI, ADRECA,
											Codi_Postal, Poblacio, PERFIL, Titulacio, TELEFON,
											A_PAGAR, FRACCIO, PAGAMENT, `DATA PAG`,
