											OBSERVACIONS, COMENTARIS, pag_observacions,
											FRACCIONAT, usuari, INSC_MAILING, CONEGUT,
											IDPAG, TIPUS_DESC, VALID_DESC)
											VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
			"insertObsGeneral"		=> "INSERT INTO aobservacions (dni, observacio, data, qui)
