											CP, POBLACIO, CONCEPTE1, CONCEPTE2, IMPORT, ENTITAT,
											FORMA_PAGAMENT, CURS, HORES, observacions, E_FACT)
											VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
			"insertCurs"				=> "INSERT INTO curs (ID_CURS, ANY, MES, CURS, ID_AULA,
											NOM_CURS, DATAI, DATAF, HORES, ID_PREU, CURS_ESCOLAR,
											GTAF, DATA_RESOL, PUBLIC) VALUES (?,?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
			"insertAula"				=> "INSERT INTO aula (ID_AULA, AULA) VALUES (?,?)",
			"insertCursos"				=> "INSERT INTO cursos (id_Curs, ANY, MES, CURS, AULA,
