	/*
   * @brief Afegir Client de Google $client
   * @return Afegir Client de Google $client
   */
	public function setGoogleClient( $client ) {
		$this->googleClient = unserialize( $client );
	}

	/*
   * @brief Assigno menuext a la info del usuari. MenuExt m'indica si vull que per defecti tinguem el menu lateral desplegat o no.
   * @return Assigno menuext a la info del usuari. MenuExt m'indica si vull que per defecti tinguem el menu lateral desplegat o no.
   */
	public function actualitzarDesplegable_MenuLateral($menuExt) {
		$usuariPerfil = $this->usuari->getUsuari()->get();

		$conIntra = new ConnexioIntranet();
		$conIntra->connectarBD();

		if ( $stmt=$conIntra->prepare( $this->consultesBD_Intra["updMenuExt"] ) ) {
			$stmt->bind_param("ds", $menuExt, $usuariPerfil);
			$stmt->execute();
			$conIntra->closeStmt();
		}
		else
			throw new Exception('',4402);

		echo  $this->consultesBD_Intra["updMenuExt"]."<br />";
		echo  $menuExt."<br />";
		echo  $usuariPerfil."<br />";
		$conIntra->desconectarBD();
	}

	/*
   * @brief Consulto el menuext del usuari. MenuExt m'indica si vull que per defecti tinguem el menu lateral desplegat o no.
	* @return Consulto el menuext del usuari. MenuExt m'indica si vull que per defecti tinguem el menu lateral desplegat o no.
   */
	public function consultaMenuLateralDesplegat_Perfil() {
		$conIntra = new ConnexioIntranet();
		$conIntra->connectarBD();

		$usuariPerfil = $this->usuari->getUsuari()->get();

		if ( $stmt=$conIntra->prepare( $this->consultesBD_Intra["cnsInfoMenuExtUsuari"] ) ) {
			$stmt->bind_param("s", $usuariPerfil);
			$stmt->execute();
			$stmt->bind_result($menuExt);
			$stmt->fetch();
			$conIntra->closeStmt();
		}
		else
			throw new Exception('',4403);

		$conIntra->desconectarBD();

		return $menuExt;
	}

	/*
   * @brief Consulto els rols d'edició de la pàgina
	* @return Consulto els rols d'edició de la pàgina
   */
	public function consultaRolsEdiicio($page) {
		$conIntra = new ConnexioIntranet();
		$conIntra->connectarBD();

		if ( $stmt=$conIntra->prepare( $this->consultesBD_Intra["cnsRolsEditarApartat"] ) ) {
			$stmt->bind_param("s", $page);
			$stmt->execute();
			$stmt->bind_result($rolsPage);
			$stmt->fetch();
			$conIntra->closeStmt();
		}
		else
			throw new Exception('',4405);

		$conIntra->desconectarBD();

		return $rolsPage;
	}

	/*
   * @brief Consulto els rols d'edició de l'usuari
	* @return Consulto els rols d'edició de l'usuari
   */
	public function consultaRolsUsuari() {
		$conIntra = new ConnexioIntranet();
		$conIntra->connectarBD();

		$usuariPerfil = $this->usuari->getUsuari()->get();

		if ( $stmt=$conIntra->prepare( $this->consultesBD_Intra["cnsInfoUsuari"] ) ) {
			$stmt->bind_param("s", $usuariPerfil);
			$stmt->execute();
			$stmt->bind_result($rolsPerfil, $nomPerfil, $cogPerfil, $imgPerfil, $deptPerfil);
			$stmt->fetch();
			$conIntra->closeStmt();
		}
		else
			throw new Exception('',4404);

		$conIntra->desconectarBD();

		return $rolsPerfil;
	}

	/*********************************** FUNCIONS MOSTRAR ***********************************/
	/**
   * @brief Mostra l'estructura de la pàgina principal que pertoca a la url.
   * @return Mostra l'estructura de la pàgina principal que pertoca a la url.
   */
	public function mostrarPage( $user ) {
		$this->usuari = $user;
		$mostrar = '';
		if ( $this->url->get() == '/home/' || $this->url->get() == '/home_prova/' ) {
			$mostrar = $this->__mostrarPage_Inici( $this->url->get() );
		}
		else if ( $this->url->get() == '/perfil/mostra-perfil/' ) {
			$mostrar = $this->__mostrarPage_Perfil_MostrarPerfil();
		}
		else if ( $this->url->get() == '/alumnes/mostrar-alumne/' ) {
			$mostrar = $this->__mostrarPage_Alumnes_MostrarAlumne();
		}
		else if ( $this->url->get() == '/alumnes/mostrar-alumne-prova/' ) {
			$mostrar = $this->__mostrarPage_Alumnes_MostrarAlumne();
		}
		else if ( $this->url->get() == '/alumnes/pagaments/' ) {
			$mostrar = $this->__mostrarPage_Alumnes_Pagaments();
		}
		else if ( $this->url->get() == '/alumnes/genera-factura-abans-pagar/' ) {
			$mostrar = $this->__mostrarPage_Alumnes_GeneraFacturaAbansPagar();
		}
		else if ( $this->url->get() == '/alumnes/genera-entitat/' ) {
			$mostrar = $this->__mostrarPage_Alumnes_GeneraEntitat();
