				"cp"	 		=> $cp,
				"poble" 		=> $poble,
				"fix" 		=> $fix,
				"mbl" 		=> $mbl,
				"email" 		=> $email,
				"horari" 	=> $horari,
				"hestiu" 	=> $hestiu,
				"mapa" 		=> $mapa,
			];
			$conWeb->closeStmt();
		}
		else
			throw new Exception('',447);

		$conWeb->desconectarBD();

		return $mostrar;
	}

	/* ############################## INTRANET INICI ############################## */
	private function __mostrarPage_Inici( $url ) {
		$rolsUser = $this->usuari->getRols();

		$rols = "";
		for ($i = 0; $i < count($rolsUser); $i++) {
			if ( $rols != '' )  $rols .= " OR ";
			$rols .= "ROLS LIKE '%".$rolsUser[$i]."%'";
		}

		$funcionalitats = [];

		$conIntra = new ConnexioIntranet();
		$conIntra->connectarBD();

		/* ##### Busquem l'apartat corresponent a la pàgina d'inici */
		if ( $stmt=$conIntra->prepare( $this->consultesBD_Intra['buscarApartat'] ) ) {
			$stmt->bind_param("s", $url);
			$stmt->execute();
			$stmt->bind_result($idApartat);
			$stmt->fetch();
			$conIntra->closeStmt();
		}
		else
			throw new Exception('',4196);

		$mostrar = '';
		/* ##### Busquem les funcionalitats d'inici corresponent als rols $rols ##### */
		$cnsRols = "SELECT ID_FUNCIO, NOM_FUNCIO, DESC_FUNCIO, ID_APARTAT_FUNCIO FROM funcionalitats
		WHERE APARTAT = ? AND ( ".$rols." ) ORDER BY ORDRE";
		if ( $stmt=$conIntra->prepare( $cnsRols ) ) {
			$stmt->bind_param("d", $apartat);
			$apartat = $idApartat;
			$stmt->execute();
			$stmt->bind_result($idFuncio, $nomFuncio, $descFuncio, $idApartatFuncio);
			while ($stmt->fetch()) {
				$funcionalitats[] = [$idFuncio, $nomFuncio, $descFuncio, $idApartatFuncio];

				$mostrar .= $this->mostrarApartatFuncionalitat( $idFuncio, $nomFuncio, $descFuncio, $idApartatFuncio);
			}
			$conIntra->closeStmt();
		}
		else
			throw new Exception('',4197);

		$conIntra->desconectarBD();

		if ( count($funcionalitats) <= 0 )
			$mostrar = "<p class='text-center'>No disposes de cap funcionalitat.</p>";

		return $mostrar;
	}

