	public function getAllCalendarsGoogle() {
		require_once 'lib/google-api-php-client/vendor/autoload.php';

		$client = new Google_Client();
		$client->setAuthConfig('../fitxers/auth/client_secret_1012851982408-eljcsv49bs1hfl5l64s3inah23pg7caf.apps.googleusercontent.com.json');
		$client->addScope(Google_Service_Calendar::CALENDAR_READONLY);

		$tokenPath = '../auth/token-'.$this->usuari->getUsuari()->get().'.json';
		if (file_exists($tokenPath)) {
			 $accessToken = json_decode(file_get_contents($tokenPath), true);
			 $client->setAccessToken($accessToken);
		}
		else {
			$mostrar .= "<p>
			No existeix el token ".$tokenPath."
			</p>";
		}

		$service = new Google_Service_Calendar($client);

		$dateToday1 = "2010-".date("m")."-".date('d')." 00:00:00";
		$dateFirstNow = new DateTime($dateToday1);
		$dateNow = $dateFirstNow->getTimestamp();

		// Print the next 10 events on the user's calendar.
		$calendarId = 'i5spt4i80k6vdgvmup9f0equ2c@group.calendar.google.com';
		$optParams = array(
			'maxResults' => 100,
			'orderBy' => 'startTime',
			'singleEvents' => true,
			'timeMin' => date('c', $dateNow),
		);

		$results2 = $service->calendarList->listCalendarList();
		$calendaris = $results2->getItems();

		$calendari = "";

		foreach ($calendaris as $calendariP) {
			$calendarColorId = $calendariP->getColorId();
			$calendarId = $calendariP->getId();
			// $calendarId = $calendar->getId();

			$results = $service->events->listEvents($calendarId, $optParams);
			$events = $results->getItems();

			if (empty($events)) {
				$calendari .= "<p>No s'han trobat events</p>";
				$calendari .= "###";
			}
			else {
				foreach ($events as $event) {
					$eventId = $event->getId();
					$summary = $event->getSummary();
					$start = $event->getStart()->getDateTime();
					if (empty($start)) {
						$start = $event->getStart()->getDate();
					}
					$end = $event->getEnd()->getDateTime();
					if (empty($end)) {
						$end = $event->getEnd()->getDate();
					}
					if (empty($end)) {
						$end = '';
					}
					$eventColorId = $event->getColorId();
					$calendari .= "###".$eventId."$$$".$summary."$$$".$start."$$$".$end."$$$".$calendarColorId."$$$".$eventColorId."$$$".$calendarId."$$$".$calendarColorId;
				}
			}
		}

		return $calendari;
	}

