   */
	private function __mostrarPage_Cursos_Bloqueig_Cursos($nomFuncio, $descFuncio) {
		$table = "";
		$button = "";
		$classTr = "";

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();
		$conWeb2 = new ConnexioWeb();
		$conWeb2->connectarBD();
		$conWeb3 = new ConnexioWeb();
		$conWeb3->connectarBD();
		$conWeb4 = new ConnexioWeb();
		$conWeb4->connectarBD();

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["IniciBloqueigCurs"] ) ) {
			/* s/ha de canviar per buscar per aula */
			if ( $stmt2=$conWeb2->prepare( $this->consultesBD_Web["IniciAlumnPujatAltaCert"] ) ) {
				$stmt->execute();
				$stmt->store_result();
				if ( $stmt->num_rows() > 0 ) {
					$table .= "<table class='table table-hover table-striped table-hover text-center w-100 mb-0'>
					<thead>
					<tr>
						<th>Any</th>
						<th>Mes</th>
						<th>Hores</th>
						<th>Curs</th>
						<th>Aules</th>
						<th>Codi Gtaf</th>
						<th>Nom del curs</th>
						<th>Data fin</th>
						<th>Dies desde fi</th>
						<th>DNI del tutor</th>
						<th>Codi GTAF</th>
						<th>Núm. usuaris</th>
						<th>Bloqueig</th>
					</tr>
					</thead>
					<tbody>";

					$stmt->bind_result($id, $any, $mes, $hores, $curs, $aula, $nomCurs,
					$dataFin, $diesCursAcabat, $codiGTAF, $dataBloq);

					while ( $stmt->fetch() ) {
						$numPersones = 0;
						$tutorsAnt = [];
						$cntTutorsAnt = 0;
						$tutorsNou = [];
					   $cntTutorsNou = 0;
						$cntAules = 0;
						$textAules = "";

						/* buscar totes les aules amb el mateix codi gtaf */
						if ( $stmt4=$conWeb4->prepare( $this->consultesBD_Web["cnsCursosCertGtaf"] ) ) {
							$stmt4->bind_param("dsss",  $any, $curs, $mes, $codiGTAF);
					      $stmt4->execute();
					      $stmt4->bind_result($aulaACercar);
					      while ( $stmt4->fetch() ) {
								$stmt2->bind_param("dsss",  $any, $mes, $curs, $aulaACercar);
								$stmt2->execute();
								$stmt2->store_result();

								if ( $cntAules > 0 ) $textAules .= ' - ';
								$textAules .= $aulaACercar;

								$numPersones += $stmt2->num_rows();
								$cntAules++;

								/* buscar Tutors del Curs d'aquestes aules */
								// $idCursSenseAula = $any.$curs.$mes;
								// $likeIdCursSenseAula = $idCursSenseAula."%";
								$idCurs = $any.$curs.$mes.$aulaACercar;

								/* Canviar i buscar per aules */
								if ( $stmt3=$conWeb3->prepare( $this->consultesBD_Web["cnsAulaByIdCursAntic"] ) ) {
									$stmt3->bind_param("s", $idCurs);
									$stmt3->execute();
									$stmt3->bind_result($aulaAnt, $anyAnt, $mesAnt, $cursAnt,
									$dataRevisioAnt, $dataInfAnt, $obsAnt, $dniTutorAnt, $nomTutAnt, $cogTutAnt);
									while ( $stmt3->fetch() ) {
										$tutorsAnt[$cntTutorsAnt] = $dniTutorAnt;
										$cntTutorsAnt++;
									}
								}
								$conWeb3->closeStmt();

								if ( $stmt3=$conWeb3->prepare( $this->consultesBD_Web["cnsAulaById"] ) ) {
									$stmt3->bind_param("ss", $idCurs, $aulaACercar);
									$stmt3->execute();
									$stmt3->bind_result($aulaNou, $anyNou, $mesNou, $cursNou,
									$dataRevisioNou, $dataInfNou, $obsNou, $dniTutorNou, $nomTutNou, $cogTutNou, $idAulaNou);
									while ( $stmt3->fetch() ) {
										$tutorsNou[$cntTutorsNou] = $dniTutorNou;
										$cntTutorsNou++;
									}
								}
								$conWeb3->closeStmt();
					      }
						}
						else {
							throw new Exception('', 4204);
						}
						$conWeb4->closeStmt();

						$textTutors = ""; $error = 0;
						if ( $cntTutorsAnt > $cntTutorsNou ) {
							for ( $i = 0; $i < $cntTutorsAnt; $i++ ) {
								$textTutors .= "<p class='mb-0'>".$tutorsAnt[$i]."</p>";
							}
						}
						else if ( $cntTutorsAnt == $cntTutorsNou ) {
							for ( $i = 0; $i < $cntTutorsNou; $i++ ) {
								$textTutors .= "<p class='mb-0'>".$tutorsNou[$i]."</p>";
								if ( $tutorsAnt[$i] != $tutorsNou[$i] ) {
									$error = 1;
								}
							}
							if ( $error ) {
								$textTutors .= "<div class='d-flex flex-column flex-sm-row justify-content-center align-items-center w-100'>
									<label class='label lightRed d-flex justify-content-center align-items-center position-relative font-weight-bold px-2 py-2'></label>
								</div>";
							}
						}
						else {
							for ( $i = 0; $i < $cntTutorsNou; $i++ ) {
								$textTutors .= "<p class='mb-0'>".$tutorsNou[$i]."</p>";
							}
						}
						/* FI buscar Tutors del Curs */

						$objDataF = new Date($dataFin);
						$dataFTr = $objDataF->getDataFomatDDMMYYYY_HHMMSS();

						$table .= "<tr class='".$classTr."'>
							<td id='any-".$id."'>".$any."</td>
							<td id='mes-".$id."'>".$mes."</td>
							<td id='hores-".$id."'>".$hores."</td>
							<td id='curs-".$id."'>".$curs."</td>
							<td>".$textAules."</td>
							<td>".$codiGTAF."</td>
							<td>".$nomCurs."</td>
							<td>".$dataFTr."</td>
							<td>".$diesCursAcabat."</td>
							<td>".$textTutors."</td>
							<td>".$codiGTAF."</td>
							<td>".$numPersones."</td>
							<td>
								<div class='d-flex flex-column flex-sm-row justify-content-center align-items-center w-100'>
									<button id='bloqueig-cursos-".$id.$aula."-".$codiGTAF."' class='no_marcat boto-blau px-4 d-flex'></button>
								</div>
							</td>
						</tr>";
					}

					$table .= "</tbody></table>";

					$button .= "<button id='confirmar-bloqueig-cursos' class='boto-blau mt-2 px-4 d-flex'>Confirma</button>";
				}
				else {
					$table = "<p class='text-center'>No hi ha resultats.</p>";
				}
				$conWeb2->closeStmt();
			}
			else {
				throw new Exception('', 4204);
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('', 4201);
		}

		$conWeb3->desconectarBD();
		$conWeb2->desconectarBD();
		$conWeb->desconectarBD();

		if ( $descFuncio != '' ) $descFuncio = "<p class='desc-apartat'>".$descFuncio."</p>";


		$mostrar = "<div id='bloqueig-cursos' class='card card-blau mt-5 d-flex flex-column justify-content-center align-items-center'>
			<div class='d-flex flex-column justify-content-center align-items-center w-100 text-center border-bottom card-header'>
				<p class='title font-weight-bold text-center py-3 mb-0 align-items-center
