	/**
   * @brief S'actualitza la data de bloqueig a la taula de cursos el registre amb id $id amb la data actual
   * @return S'actualitza la data de bloqueig a la taula de cursos el registre amb id $id amb la data actual
   */
	public function actualitzaDataBloqueig($id, $codiGTAF) {
		$id2 = substr($id, 0, -1);
		/* Calcular aula a partir de $id */
		$aula = substr($id, strlen($id2));

		// esperant confirmació pero s'hauria de  canviar data bloqueig per aula
		// hauria de  duplicar l'actualització per cada aula amb el mateix codi gtaf que l'aula $aula
		// si es aixi, millor rebre aula i codigtaf com a arguments

		echo $id2;
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();
		$conWeb2 = new ConnexioWeb();
		$conWeb2->connectarBD();
		$conWeb3 = new ConnexioWeb();
		$conWeb3->connectarBD();

		/* Obtenir id aula */
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["cnsIdAula"] ) ) {
			$stmt->bind_param("s", $id2);
			$stmt->execute();
			$stmt->store_result();
			$stmt->bind_result($idAula);
			$stmt->fetch();
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('', 4635);
		}

		echo $this->consultesBD_Web["cnsCursosCertGtafById"]."<br />";
		echo $this->consultesBD_Web["updDataBloqueigAula"]."<br />";
		echo $this->consultesBD_Web["updDataBloqueigVella"]."<br />";
		/* cerco totes les aules de idcurs $id amb codigtaf $codigtaf*/
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["cnsCursosCertGtafById"] ) ) {
			if ( $stmt3=$conWeb3->prepare( $this->consultesBD_Web["updDataBloqueigVella"] ) ) {
				if ( $stmt2=$conWeb2->prepare( $this->consultesBD_Web["updDataBloqueigAula"] ) ) {
					$stmt->bind_param("ss", $id2, $codiGTAF);
					$stmt->execute();
					$stmt->store_result();
					$stmt->bind_result($aula);
					/* per cada cerca de aula trobada, actualitzar data de bloqueig per aula */
					while ( $stmt->fetch() ) {
						$stmt2->bind_param("ds", $idAula, $aula);
						$stmt2->execute();

						$idCursAula = $id2.$aula;

						$stmt3->bind_param("s", $idCursAula);
						$stmt3->execute();

						$mostrar = "OK";
					}
					$conWeb3->closeStmt();
					$conWeb2->closeStmt();
					$conWeb->closeStmt();
				}
				else {
					throw new Exception('', 4637);
				}
			}
			else {
				throw new Exception('', 4202);
			}
		}
		else {
			throw new Exception('', 4636);
		}
		$conWeb3->desconectarBD();
		$conWeb2->desconectarBD();

		/* segueixo actualitzant la data de bloqueig per curs mentre fem el canvi per aula */
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["updDataBloqueig"] ) ) {
			$stmt->bind_param("s", $id2);
			$stmt->execute();
			$conWeb->closeStmt();

			$mostrar = "OK";
		}
		else {
			throw new Exception('', 4203);
		}

		$conWeb->desconectarBD();

		return $mostrar;
	}

