	private function __mostrarPage_Cursos_Informes_Ensenyament($nomFuncio, $descFuncio) {
		$table = "";
		$button = "";

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		// $anyActual = date("Y");
