			$stmt->bind_param("d", $anyActual);
			$stmt->execute();
			$stmt->store_result();
			if ( $stmt->num_rows() > 0 ) {
				$diesCursAcabatAnt = "";

				$stmt->bind_result($id, $any, $mes, $curs, $aula, $nomCurs, $nomTutor,
				$cogTutor, $codiGTAF, $dataI, $dataF, $dataResol, $dataInfo,
				$diesCursAcabat, $dniTutor);

				while ( $stmt->fetch() ) {
					$dataInici = $dataFi = $dataResolucio = $dataInforme = "";
					if ( $dataI ) {
						$objDataI = new Date($dataI);
						$dataInici = $objDataI->getDataFomatDDMMYYYY_HHMMSS();
					}
					if ( $dataF )  {
						$objDataF = new Date($dataF);
						$dataFi = $objDataF->getDataFomatDDMMYYYY_HHMMSS();
					}
					if ( $dataResol ) {
						$objDataRes = new Date($dataResol);
						$dataResolucio = $objDataRes->getDataFomatDDMMYYYY_HHMMSS();
					}
					if ($dataInfo) {
						$objDataInf = new Date($dataInfo);
						$dataInforme = $objDataInf->getDataFomatDDMMYYYY_HHMMSS();
					}

					$tramitResolucio = "";

					$conWeb2 = new ConnexioWeb();
					$conWeb2->connectarBD();

					if ( $stmt2=$conWeb2->prepare( $this->consultesBD_Web["searchTramit"] ) ) {
						$stmt2->bind_param("s", $dataResol);
						$stmt2->execute();
						$stmt2->bind_result($tramitResolucio);
						$stmt2->fetch();
					}

					$conWeb2->closeStmt();

					$conWeb2->desconectarBD();

					if ( $diesCursAcabatAnt == "" or $diesCursAcabatAnt != $diesCursAcabat ) {
						if ( $diesCursAcabatAnt != "" ) {
							$table .= "</tbody></table>";
						}
						$table .= "<table class='table table-hover table-striped table-hover text-center w-100 mb-4'>
						<thead>
						<tr>
							<th>Any</th>
							<th>Mes</th>
							<th>Curs</th>
							<th>Aula</th>
							<th>Nom del curs</th>
							<th>Nom i cognoms tutor</th>
							<th>Codi GTAF</th>
							<th>Data inici</th>
							<th>Data fi</th>
							<th>Data resol.</th>
							<th>Data informe</th>
							<th>Dies desde fi</th>
							<th>Fitxer valoració</th>
							<th>Data valoració</th>
						</tr>
						</thead>
						<tbody>";
					}

					$trobat = false;
					$csv_file = "valoracions-ensenyament-".$any."-".$mes.".txt";
					$path_file = "../fitxers/".$csv_file;

					if ( file_exists($path_file) ) {
						if (!$handle = fopen($path_file, "r")) {
							 echo "Cannot open file valoracions ensenyament";
							 exit;
						}
						else {
							$content = fread($handle, filesize($path_file));
							$cursos = explode('|', $content);
							$lcursos = count($cursos);
							$cnt = 0;

							while ( $cnt < $lcursos && !$trobat ) {
								if ( $cursos[$cnt] == $id )
									$trobat = true;
								else
									$cnt++;
							}
						}

						fclose($handle);
					}

					if ( $trobat ) {
						$botoFitxerGenerat = "<div class='d-flex flex-column flex-sm-row justify-content-center align-items-center w-100'>
							<button class='generat boto-blau px-4 d-flex'></button>
						</div>";
					}
					else {
						$botoFitxerGenerat = "<div class='d-flex flex-column flex-sm-row justify-content-center align-items-center w-100'>
							<button id='he-generat-fitxerense-".$id."' class='no_generat boto-blau px-4 d-flex'></button>
						</div>";

						if ( $dniTutor == '0' ) {
							$botoFitxerGenerat = "<div class='d-flex flex-column flex-sm-row justify-content-center align-items-center w-100'>
								<label class='no_es_pot_generar label lightOrange d-flex justify-content-center align-items-center position-relative font-weight-bold px-2 py-2'>
								</label>
							</div>";
						}
					}

					$textAules = "";
					$cntAules = 0;

					$conWeb4 = new ConnexioWeb();
					$conWeb4->connectarBD();

					if ( $stmt4=$conWeb4->prepare( $this->consultesBD_Web["cnsCursosCertGtaf"] ) ) {
						$stmt4->bind_param("dsss",  $any, $curs, $mes, $codiGTAF);
						$stmt4->execute();
						$stmt4->bind_result($aulaACercar);
						while ( $stmt4->fetch() ) {
							if ( $cntAules > 0 ) $textAules .= ' - ';
							$textAules .= $aulaACercar;
							$cntAules++;
						}
					}
					$conWeb4->closeStmt();

					$conWeb4->desconectarBD();

					$table .= "<tr>
						<td id='any-".$id."'>".$any."</td>
						<td id='mes-".$id."'>".$mes."</td>
						<td id='curs-".$id."'>".$curs."</td>
						<td>".$textAules."</td>
						<td>".$nomCurs."</td>
						<td>".$nomTutor." ".$cogTutor."</td>
						<td>".$codiGTAF."</td>
						<td>".$dataInici."</td>
						<td>".$dataFi."</td>
						<td>".$dataResolucio." ".$tramitResolucio."</td>
						<td>".$dataInforme."</td>
						<td>".$diesCursAcabat."</td>
						<td>".$botoFitxerGenerat."</td>
						<td>
							<div class='d-flex flex-column flex-sm-row justify-content-center align-items-center w-100'>
								<button id='valora-cursos-ense-".$id."' class='no_marcat boto-blau px-4 d-flex'></button>
							</div>
						</td>
					</tr>";

					$diesCursAcabatAnt = $diesCursAcabat;
				}

				$table .= "</tbody></table>";

				$button .= "<button id='confirmar-valora-cursos-ense' class='boto-blau mt-2 px-4 d-flex'>Confirma</button>";
			}
			else {
				$table = "<p class='text-center'>No hi ha resultats.</p>";
			}
		}
		else {
			throw new Exception('', 4206);
		}
		$conWeb->closeStmt();

		$conWeb->desconectarBD();

		if ( $descFuncio != '' ) $descFuncio = "<p class='desc-apartat'>".$descFuncio."</p>";


		$mostrar = "<div id='valora-cursos-ense' class='card card-blau mt-5 d-flex flex-column justify-content-center align-items-center'>
			<div class='d-flex flex-column justify-content-center align-items-center w-100 text-center border-bottom card-header'>
