	/**
   * @brief Es crea un fitxer per indicar quan s'ha generat el fitxer de valoracions d'ensenyament
   * @return Es crea un fitxer anomenat valoracions-ensenyament-ANY-MES per per indicar
	* quan s'ha generat el fitxer de valoracions d'ensenyament del curs $idCurs on ANY
	* és el paràmetre $any i el MES és el paràmetre $mes
   */
	public function generatFitxerValoracionsEnse($any, $mes, $idCurs) {
		$csv_file = "valoracions-ensenyament-".$any."-".$mes.".txt";
		$path_file = "../../fitxers/".$csv_file;

		$csv = $idCurs."|";
		echo $path_file;

		//Si el fitxer no existeix, generem el fitxer
		if (!$handle = fopen($path_file, "a+")) {
		    echo "Cannot open file valoraciones ensyament (generar)";
		    exit;
		}
		//Omplim el fitxer
		if (fwrite($handle, mb_convert_encoding($csv, 'ISO-8859-1', 'UTF-8')) === FALSE) {
		    echo "Cannot write to file";
		    exit;
		}
		fclose($handle);

		$mostrar = $csv_file;

		return $mostrar;
	}

	/**
   * @brief Es crea un fitxer per indicar quan s'ha generat el fitxer de valoracions del fiss
