	/**
   * @brief Mostra un text els camps disponibles a CERTIFICAT de inscripciond separats amb un |
   * @return Mostra un text de les diferents opcions disponibles a CERTIFICAT a partir del 2019
	* on CERTIFIACT és diferent de NULL, DEMANAT, PAPER i no aprovat de inscripciond separats amb un |
   */
	public function buscarOpcionsCertificat() {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();
		$cursos = '';

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarOpcionsCertificat"] ) ) {
			$stmt->execute();
			$stmt->bind_result($curs);
			$i = 0;
			while ($stmt->fetch()) {
				if ( $i > 0 ) $cursos .= "|";
				$cursos .= $curs;
				$i++;
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4199);
		}
		$cursos = "PUJAT|NO TROBAT|DIGITAL|ESTUDIANT|DEMANAT|ALTA|GTAF";

		$conWeb->desconectarBD();

		return $cursos;
	}

