	/**
   * @brief Mostra una taula amb tota la informació necessària per la consulta diària «Pujar Aules Obertes»
   * @return Mostra una taula amb tota la informació necessària per la consulta diària «Pujar Aules Obertes»
   */
	private function __mostrarPage_Cursos_Pujada_AO($nomFuncio, $descFuncio) {
		$table = "";
		$button = "";

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["exPujadaAO"] ) ) {
			$stmt->execute();
			$stmt->store_result();
			if ( $stmt->num_rows() > 0 ) {
				$ids = ''; $cnt = 0;
				$stmt->bind_result($id);
				while ( $stmt->fetch() ) {
					if ( $ids != '' && $cnt < $stmt->num_rows()-1 ) $ids .= " OR ";
					$ids .= "i.ID = ".$id;
				}
			}
			else {
				$button = "<p class='text-center'>No hi han registres.</p>";
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('', 4484);
		}

		$cnsInterna = "SELECT c.ID_CURS, c.ANY, c.MES, c.CURS, i.Grup, i.NOM, i.COGNOMS,
			i.CORREU, i.usuari, i.Poblacio, aula.GTAF_AULA, c.DATAF, i.CERTIFICAT, i.`OBS CERT`,
			i.PERFIL, i.Titulacio, i.A_PAGAR, i.PAGAMENT,
			p.NOM, p.COGNOMS, i.a_pagar-i.pagament AS pendent, i.reclamat
			FROM curs as c INNER JOIN aula ON c.ID_AULA = aula.ID_AULA
			INNER JOIN rel_cuho ON rel_cuho.id_cuho = aula.ID_CUHO INNER JOIN
			honoraris on honoraris.ID = rel_cuho.id_hono AND PERFIL = 'TUTOR'
			INNER JOIN personal AS p ON p.DNI = honoraris.DNI_TUTOR INNER JOIN inscripcions as i ON
			c.ANY = i.ANY AND c.MES = i.MES AND c.CURS = i.CURS AND aula.AULA = i.Grup
			WHERE ".$ids." ORDER BY c.CURS, c.MES, i.COGNOMS";

		if ( $stmt=$conWeb->prepare( $cnsInterna ) ) {
			$stmt->execute();
			$stmt->store_result();
			if ( $stmt->num_rows() > 0 ) {
				$cursAnt = "";

				$stmt->bind_result($idCurs, $any, $mes, $curs, $aula, $nom, $cognoms,
				$correu, $usuari, $poblacio, $codiGTAF, $dataF, $cert, $obsCert, $perfil,
				$titulacio, $apagar, $pagament, $nomTutor, $cogTutor, $pendent, $reclament);

				while ( $stmt->fetch() ) {
					$dataFi = "";
					if ( $dataF )  {
						$objDataF = new Date($dataF);
						$dataFi = $objDataF->getDataFomatDDMMYYYY_HHMMSS();
					}

					if ( $cursAnt == "" or $cursAnt != $curs ) {
						if ( $cursAnt != "" ) {
							$table .= "</tbody></table>";
						}
						$table .= "<table class='table table-hover table-striped table-hover text-center mb-4' style='width: 2500px'>
						<thead>
						<tr>
							<th style='width: 2%'>Any</th>
							<th style='width: 2%'>Mes</th>
							<th style='width: 3%'>Curs</th>
							<th style='width: 6%'>Nom</th>
							<th style='width: 7%'>Cognoms</th>
							<th style='width: 8%'><em>Email</em></th>
							<th style='width: 3%'>User</th>
							<th style='width: 5%'>Perenne</th>
							<th style='width: 7%'>Població</th>
							<th style='width: 4%'>Codi GTAF</th>
							<th style='width: 3%'>Data fi</th>
							<th style='width: 3%'>Certificat</th>
							<th style='width: 5%'>Obs cert</th>
							<th style='width: 9%'>Perfil</th>
							<th style='width: 9%'>Titulació</th>
							<th style='width: 3%'>A pagar</th>
							<th style='width: 3%'>Pagament</th>
							<th style='width: 8%'>Nom i cognoms tutor</th>
							<th style='width: 3%'>Pendent</th>
							<th style='width: 7%'>Reclamat</th>
						</tr>
						</thead>
						<tbody>";
					}

					$table .= "<tr>
						<td id='any-".$idCurs."-".$usuari."'>".$any."</td>
						<td id='mes-".$idCurs."-".$usuari."'>".$mes."</td>
						<td id='curs-".$idCurs."-".$usuari."'>".$curs."</td>
						<td id='nom-".$idCurs."-".$usuari."'>".$nom."</td>
						<td id='cognoms-".$idCurs."-".$usuari."'>".$cognoms."</td>
						<td id='email-".$idCurs."-".$usuari."'>".$correu."</td>
