	/**
   * @brief Es crea un fitxer per la pujada de les aules obertes
   * @return Es crea un fitxer per la pujada de les aules obertes
   */
	public function crearFitxerAO() {
		$fecha = new DateTime();
		$tmp = $fecha->getTimestamp();
		$dataHora = $fecha->format('d-m-Y_H:i:s');

		$csv_file = "pujada-ao-".$dataHora.".csv";
		$path_file = "../../fitxers/".$csv_file;

		//Posem la capçalera de ¡l fitxer de les aules obertes
		$csv="username;password;firstname;lastname;email;city;lang;course1;autosubscribe;maildisplay";
		//Generem el fitxer
		if (!$handle = fopen($path_file, "a+")) {
		    echo "Cannot open file";
		    exit;
		}
		//Omplim el fitxer
		if (fwrite($handle, mb_convert_encoding($csv, 'ISO-8859-1', 'UTF-8')) === FALSE) {
		    echo "Cannot write to file";
		    exit;
		}
		fclose($handle);

		$mostrar = $csv_file;

		return $mostrar;
	}

	/**
   * @brief S'actualitza el perenne a 1 a la taula d'inscripcions el registre amb dni $usuari
	* any $any, mes $mes, curs $curs on perenne = 0 i INSC CURS = 1
   * @return S'actualitza el perenne a 1 a la taula d'inscripcions el registre amb dni $usuari
	* any $any, mes $mes, curs $curs on perenne = 0 i INSC CURS = 1 i s'insereix un registre
	* per la pujada de les aules obertes en el fitxer $fitxer
   */
	public function pujar_AO($usuari, $any, $mes, $curs, $fitxer, $nom, $cognoms, $email, $poblacio) {
		$perenne = '0';
		$incCurs = '1';

		echo $this->consultesBD_Web["updPujadaAO"]."<br />";
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["updPujadaAO"] ) ) {
			$stmt->bind_param("ssdsss", $usuari, $curs, $any, $mes, $incCurs, $perenne);
			$stmt->execute();
			$conWeb->closeStmt();

			$mostrar = "OK";
		}
		else {
			throw new Exception('', 4213);
		}

		$conWeb->desconectarBD();

		$csv_end = "";
		$csv_sep = ";";
		$csv_file = $fitxer;
		$path_file = "../../fitxers/".$csv_file;
		$csv.= "
		".$usuari.$csv_sep."".$csv_sep.$nom.$csv_sep.$cognoms.$csv_sep;
		$csv.= $email.$csv_sep.$poblacio.$csv_sep."ca".$csv_sep.$curs.$csv_sep."0".$csv_sep."2".$csv_end;

		// //Generamos el csv de todos los datos
		if (!$handle = fopen($path_file, "a+")) {
		    echo "Cannot open file";
		    exit;
		}
		if (fwrite($handle, mb_convert_encoding($csv, 'ISO-8859-1', 'UTF-8')) === FALSE) {
		    echo "Cannot write to file";
		    exit;
		}
		fclose($handle);

		$mostrar = $csv_file;

		return $mostrar;
	}

