	*/
	private function __mostrarPage_Inici_Pujada_Inscripcions($idFuncio, $idApartatFuncio) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarParam"] ) ) {
			$stmt->bind_param("s", $parametre);
			$parametre = "oberturaAules";
			$stmt->execute();
			$stmt->store_result();
			if ( $stmt->num_rows() > 0 ) {
				$stmt->bind_result($diesAbansPujada);
				$stmt->fetch();
			}
			else {
				throw new Exception('', 4217);
			}
		}
		else {
			throw new Exception('', 4216);
		}
		$conWeb->closeStmt();

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["IniciPujadaInsc_vella"] ) ) {
			$stmt->bind_param("d", $diesAbansPujada);
			$stmt->execute();
			$stmt->store_result();
			if ( $stmt->num_rows() > 0 ) {
				$button = "<p>Hi han alumnes per pujar en els cursos.</p>
				<button id='pujar-inscr-".$idApartatFuncio."' class='pujada-inscripcions boto-blau mt-2 px-4 d-flex'>Pujar alumnes en els cursos</button>";
			}
			else {
				$button = "<p class='text-center'>No hi ha resultats.</p>";
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('', 4214);
		}

		$conWeb->desconectarBD();

		return $button;
	}


	/**
   * @brief Mostra una taula amb tota la informació necessària per la consulta diària «Pujada Inscripcions»
   * @return Mostra una taula amb tota la informació necessària per la consulta diària «Pujada Inscripcions»
   */
	private function __mostrarPage_Cursos_Pujada_Inscripcions($nomFuncio, $descFuncio) {
		$table = "";
		$button = "";

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarParam"] ) ) {
			$stmt->bind_param("s", $parametre);
			$parametre = "oberturaAules";
			$stmt->execute();
			$stmt->store_result();
			if ( $stmt->num_rows() > 0 ) {
				$stmt->bind_result($diesAbansPujada);
				$stmt->fetch();
			}
			else {
				throw new Exception('', 4217);
			}
		}
		else {
			throw new Exception('', 4216);
		}
		$conWeb->closeStmt();

		$alertaCursRealitzat = '';

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["IniciPujadaInsc_vella"] ) ) {
			$stmt->bind_param("d", $diesAbansPujada);
			$stmt->execute();
			$stmt->store_result();
			if ( $stmt->num_rows() > 0 ) {
				$diesCursComencatAnt = "";
				$inici = 1;

				$stmt->bind_result($idCurs, $any, $mes, $curs, $aula, $hores, $nom, $cognoms,
				$correu, $usuari, $poblacio, $comentaris, $diesCursComencat, $id, $dni);

				while ( $stmt->fetch() ) {
					$exMoros = $this->comprovaAlumnaEsMoros($dni);
					if ( $inici || $diesCursComencatAnt != $diesCursComencat ) {
						if ( !$inici ) {
							$table .= "</tbody></table>";
						}
						$table .= "<table class='table table-hover table-striped table-hover text-center w-100 mb-4'>
						<thead>
						<tr>
							<th class='p-0'></th>
							<th style='width: 6%'>Any</th>
							<th style='width: 6%'>Mes</th>
							<th style='width: 7%'>Curs</th>
							<th style='width: 5%'>Grup</th>
							<th style='width: 6%'>Hores</th>
							<th style='width: 10%'>Nom</th>
							<th style='width: 10%'>Cognoms</th>
							<th style='width: 12%'><em>Email</em></th>
							<th style='width: 8%'>User</th>
							<th style='width: 10%'>Població</th>
							<th style='width: 10%'>Comentaris</th>
							<th style='width: 10%'>Accions</th>
						</tr>
						</thead>
						<tbody>";
					}

					$mesUnaAula = true;

					$conWeb2 = new ConnexioWeb();
					$conWeb2->connectarBD();

					if ( $stmt2=$conWeb2->prepare( $this->consultesBD_Web["buscaAulesEdicio_vella"] ) ) {
						$stmt2->bind_param("dss", $any, $mes, $curs);
						$stmt2->execute();
						$stmt2->store_result();
						if ( $stmt2->num_rows() > 0 ) {
							$stmt2->bind_result($aulaSearch);
							$i = 0; $aulesSearch = ""; $aulaSearchA = "";
							while ( $stmt2->fetch() ) {
								//Per cada aula: s'hauria de buscar la quantitat d'alumnes que hi ha

								$conWeb3 = new ConnexioWeb();
								$conWeb3->connectarBD();

								if ( $stmt3=$conWeb3->prepare( $this->consultesBD_Web["nInscritsEdicio"] ) ) {
									$stmt3->bind_param("dsss", $any, $mes, $curs, $aulaSearch);
									$stmt3->execute();
									$stmt3->store_result();
									$numInscrits = $stmt3->num_rows();
								}
								else {
									throw new Exception('', 4223	);
								}
								$conWeb3->closeStmt();

								$conWeb3->desconectarBD();

								if ( $stmt2->num_rows() > 1 ) {
									if ( $aulesSearch != '' ) $aulesSearch .= "|";
									$aulesSearch .= "<span class='aula mr-1'>".$aulaSearch."</span>(".$numInscrits.")";
									if ( $aulaSearch == "A" )
										$aulaSearchA = "<span class='aula mr-1'>".$aulaSearch."</span>(".$numInscrits.")";
									if ( $aulaSearch == $aula )
										$aulaSearchA = "<span class='aula mr-1'>".$aulaSearch."</span>(".$numInscrits.")";
									$i++;
								}
								else {
									$mesUnaAula = false;
									$aulaSearchA = "<span class='aula mr-1'>".$aulaSearch."</span>(".$numInscrits.")";
								}
							}
						}
					}
					else {
						throw new Exception('', 4222);
					}
					$conWeb2->closeStmt();

					$conWeb2->desconectarBD();

					if ( !$mesUnaAula ) {
						$cntAula = "<td id='aula-".$idCurs."-".$usuari."'>".$aulaSearchA."</td>";
					}
					else {
						$cntAula = "<td id='aula-".$idCurs."-".$usuari."'>".$this->mostrarSelect('', "Aula", 'hide', "aules-dispo-".$idCurs."-".$usuari, '', $aulaSearchA, '', explode('|', $aulesSearch))."</td>";
					}

					/* Buscar si s'ha realitzat el curs actual */
					if ( $this->__buscarSiHaRealtizatCurs($curs, $usuari, $id) ) {
						$alertaCursRealitzat =  "<label class='estat danger ml-2 position-relative font-weight-bold px-2 py-1'>REALITZAT</label>";
					}
					else {
						$cursDderivat = $this->__buscarSiExCursDerivat($curs);
						if ( $cursDderivat !=null AND $cursDderivat != '' ) {
							if ( $this->__buscarSiHaRealtizatCurs($cursDderivat, $usuari, $id) ) {
								$alertaCursRealitzat =  "<label class='estat danger ml-2 position-relative font-weight-bold px-2 py-1'>REALITZAT</label>";
							}
						}
					}

					if ( $alertaCursRealitzat == '' ) {
						if ( $this->__buscarIncripcioDuplicada($curs, $dni, $id) ) {
							$alertaCursRealitzat =  "<label class='estat danger ml-2 position-relative font-weight-bold px-2 py-1'>DUPLICADA</label>";
						}
					}

					$alertaMoros = '';
					if ( $exMoros ) $alertaMoros = "<label class='estat bg-danger text-white ml-2 position-relative font-weight-bold px-2 py-1'>DEUTOR!</label>";

					$buttons = "<div class='d-flex flex-column flex-sm-row justify-content-center align-items-center w-100'>
					".$alertaMoros.$alertaCursRealitzat."
					<button id='edit-inscr-".$id."-".$idCurs."-".$usuari."' class='edit-inscr boto-blau mt-2 ml-2 px-2 d-flex'><i class='material-icons text-white'>edit</i></button>
					<button id='search-inscr-".$id."-".$idCurs."-".$usuari."' class='search boto-blau mt-2 ml-2 px-2 d-flex'><i class='material-icons text-white'>search</i></button>
					</div>";

					$btnPujar = "<button id='pujada-inscr-".$idCurs."-".$usuari."' class='marcat boto-blau mt-2 px-4 d-flex'>Pujar</button>";
					if ( $exMoros ) $btnPujar = "<button id='pujada-inscr-".$idCurs."-".$usuari."' class='no_marcat boto-blau mt-2 px-4 d-flex'>No Pujar</button>";

					$table .= "<tr>
						<td class='p-0'>".$buttons."</td>
						<td id='any-".$idCurs."-".$usuari."'>".$any."</td>
						<td id='mes-".$idCurs."-".$usuari."'>".$mes."</td>
						<td id='curs-".$idCurs."-".$usuari."'>".$curs."</td>
						".$cntAula."
						<td>".$hores."</td>
						<td id='nom-".$idCurs."-".$usuari."'>".$nom."</td>
						<td id='cognoms-".$idCurs."-".$usuari."'>".$cognoms."</td>
						<td id='email-".$idCurs."-".$usuari."'>".$correu."</td>
						<td>".$usuari."</td>
						<td id='poblacio-".$idCurs."-".$usuari."'>".$poblacio."</td>
						<td>".$comentaris."</td>
						<td>".$btnPujar."</td>
					</tr>";

					$alertaCursRealitzat = "";

					$diesCursComencatAnt = $diesCursComencat;
					$inici = 0;
				}

				$table .= "</tbody></table>";

				$button .= "<button id='confirmar-pujada-inscr' class='boto-blau mt-2 px-4 d-flex'>Confirma</button>";
			}
			else {
				$table = "<p class='text-center'>No hi ha resultats.</p>";
			}
		}
		else {
			throw new Exception('', 4214);
		}
		$conWeb->closeStmt();

		$conWeb->desconectarBD();

		if ( $descFuncio != '' ) $descFuncio = "<p class='desc-apartat'>".$descFuncio."</p>";

		$mostrar = "<div id='pujada-inscr' class='card card-blau mt-5 d-flex flex-column justify-content-center align-items-center'>
			<div class='d-flex flex-column justify-content-center align-items-center w-100 text-center border-bottom card-header'>
				<p class='title font-weight-bold text-center py-3 mb-0 align-items-center
				justify-content-center d-flex'>".$nomFuncio."</p>
			</div>
			<div class='card-body px-0 w-100 ps2'>
				<div class='d-flex flex-column justify-content-center my-2'>
					".$table."
					".$this->__modalEditaDadesInscripcions_Inici()."
					".$this->__modalActualitzarPujadaInscripcions_Inici()."
				</div>
			</div>
			".$button."
		</div>";

		return $mostrar;
	}

	/*
		* @brief Retorna cert si l'usari $dni ha realitzat el curs $curs
		* @return Retorna cert si l'usari $dni ha realitzat el curs $curs, altrament false
	*/
	private function __buscarSiHaRealtizatCurs($curs, $usuari, $id) {
		$conWeb2 = new ConnexioWeb();
		$conWeb2->connectarBD();

		$alertaCursRealitzat = 0;

		if ( $stmt2=$conWeb2->prepare( $this->consultesBD_Web["buscarHaRealitzatCurs"] ) ) {
			$stmt2->bind_param("ssd", $curs, $dni, $id);
			$dni = $usuari."%";
			$stmt2->execute();
			$stmt2->store_result();
			if ( $stmt2->num_rows() > 0 ) {
				$alertaCursRealitzat = 1;
			}
		}
		else {
			throw new Exception('', 4224);
		}
		$conWeb2->closeStmt();

		$conWeb2->desconectarBD();

		return $alertaCursRealitzat;
	}

	/*
		* @brief Retorna cert si l'usari $dni esta inscrita en el curs $curs
		* @return Retorna cert si l'usari $dni esta inscrita en el curs $curs, altrament false
	*/
	private function __buscarIncripcioDuplicada($curs, $usuari, $id) {
		$conWeb2 = new ConnexioWeb();
		$conWeb2->connectarBD();

		$alertaCursRealitzat = 0;

		if ( $stmt2=$conWeb2->prepare( $this->consultesBD_Web["buscarInscrDupl"] ) ) {
			$stmt2->bind_param("ssd", $curs, $dni, $id);
			$dni = $usuari."%";
			$stmt2->execute();
			$stmt2->store_result();
			if ( $stmt2->num_rows() > 0 ) {
				$alertaCursRealitzat = 1;
			}
		}
		else {
			throw new Exception('', 4414);
		}
		$conWeb2->closeStmt();

		$conWeb2->desconectarBD();

		return $alertaCursRealitzat;
	}

	/*
		* @brief Si el curs $curs deriva d'algun curs, retorna el curs del qual deriva
		* @return Si el curs $curs deriva d'algun curs, retorna el curs del qual deriva, altrament retorna buit o null
	*/
	private function __buscarSiExCursDerivat($curs) {
		$conWeb2 = new ConnexioWeb();
		$conWeb2->connectarBD();

		if ( $stmt2=$conWeb2->prepare( $this->consultesBD_Web["buscarCursDeriva"] ) ) {
			$stmt2->bind_param("s", $curs);
			$stmt2->execute();
			$stmt2->bind_result($deriva);
			$stmt2->fetch();
		}
		else {
			throw new Exception('', 4225);
		}
		$conWeb2->closeStmt();

		$conWeb2->desconectarBD();

		return $deriva;
	}

