	/**
	* @brief Mostra les dades d'inscrició de $idInsc i els registres que tenen el mateix dni que la inscripció
	* @return Mostra les dades d'inscrició de $idInsc i els registres que tenen el mateix dni que la inscripció
	*/
	public function modalEditaInscripcio_pujadaAlumnes( $idInscActual ) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		//Consulta BD per obtenir el NOM, COGNOMS, DNI, EMAIL, TELEFON, ADREÇA, CODI POSTAL, POBLACIÓ, PERFIL, TITULACIO de la inscripcio idInsc
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarInfoMostraInfo"] ) ) {
			$stmt->bind_param("d", $idInscActual);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($any, $mes, $curs, $aula, $nomActual, $cognomsActual,
				$dniActual, $correuActual,	$telefonActual, $adrecaActual, $cpActual,
