	/**
   * @brief Es crea un fitxer per la pujada de les inscripcions
   * @return Es crea un fitxer per la pujada de les inscripcions
   */
	public function crearFitxerPujadaInscripcions() {
		$fecha = new DateTime();
		$tmp = $fecha->getTimestamp();
		$dataHora = $fecha->format('d-m-Y_H:i:s');

		$csv_file = "pujada-inscripcions-".$dataHora.".csv";
		$path_file = "../../fitxers/".$csv_file;

		//Posem la capçalera del fitxer de la puajda de les inscripcions
		$csv="username;password;firstname;lastname;email;city;lang;course1;autosubscribe;maildisplay";
		//Generem el fitxer
		if (!$handle = fopen($path_file, "a+")) {
		    echo "Cannot open file";
		    exit;
		}
		//Omplim el fitxer
		if (fwrite($handle, mb_convert_encoding($csv, 'ISO-8859-1', 'UTF-8')) === FALSE) {
		    echo "Cannot write to file";
		    exit;
		}
		fclose($handle);

		$mostrar = $csv_file;

		return $mostrar;
	}

	/**
   * @brief S'actualitza el INSC CURS a 1 a la taula d'inscripcions el registre amb dni $usuari
	* any $any, mes $mes, curs $curs on INSC CURS = 0
   * @return S'actualitza el INSC CURS a 1 a la taula d'inscripcions el registre amb dni $usuari
	* any $any, mes $mes, curs $curs on INSC CURS = 0 i s'insereix un registre
	* per la pujada de les inscripcions en el fitxer $fitxer
   */
	public function pujar_Inscripcions($usuari, $any, $mes, $curs, $aula, $fitxer, $nom, $cognoms, $email, $poblacio) {
		$incCurs = '0';

		echo $this->consultesBD_Web["updPujadaInsc"]."<br />";
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["updPujadaInsc"] ) ) {
			$stmt->bind_param("sssdss", $aula, $usuari, $curs, $any, $mes, $incCurs);
			$stmt->execute();
			$conWeb->closeStmt();

			$mostrar = "OK";
		}
		else {
			throw new Exception('', 4215);
		}

		$conWeb->desconectarBD();

		$idCurs = $any.$curs.$mes.$aula;

		$csv_end = "";
		$csv_sep = ";";
		$csv_file = $fitxer;
		$path_file = "../../fitxers/".$csv_file;
		$csv.= "
		".$usuari.$csv_sep."".$csv_sep.$nom.$csv_sep.$cognoms.$csv_sep;
		$csv.= $email.$csv_sep.$poblacio.$csv_sep."ca".$csv_sep.$idCurs.$csv_sep."0".$csv_sep."2".$csv_end;

		// //Generamos el csv de todos los datos
		if (!$handle = fopen($path_file, "a+")) {
		    echo "Cannot open file";
		    exit;
		}
		if (fwrite($handle, mb_convert_encoding($csv, 'ISO-8859-1', 'UTF-8')) === FALSE) {
		    echo "Cannot write to file";
		    exit;
		}
		fclose($handle);

		$mostrar = $csv_file;

		return $mostrar;
	}

