	/**
   * @brief Mostra un text dels anys disponibles separats amb un |
   * @return Mostra un text dels anys disponibles de la taula cursos on cada any esta separat del següent amb un |
   */
	public function buscarAnysDisponibles() {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		$anysCURS = [];
		$anysJOR = [];
		$anys = "";

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarAnysDisponibles"] ) ) {
			$stmt->execute();
			$stmt->bind_result($any);
			$i = 0;
			while ($stmt->fetch()) {
				$anysCURS[] = $any;
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4075);
		}
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarAnysJorDisponibles"] ) ) {
			$stmt->execute();
			$stmt->bind_result($any);
			$i = 0;
			while ($stmt->fetch()) {
				$anysJOR[] = $any;
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4164);
		}

		$i=0; $j=0; $trobat=false;
		while ( $i<count($anysCURS) || $j<count($anysJOR) ) {
			if ( $i<count($anysCURS) && $j<count($anysJOR) ) {
				// echo "i:".$i."<br />";
				// echo "j:".$j."<br />";
				if ( $anysCURS[$i] < $anysJOR[$j] ) {
					if ( $anys!='' ) $anys .= "|";
					// echo "any:".$anysJOR[$j]."<br />";
					$anys .= $anysJOR[$j];
					$j++;
				}
				else if ( $anysCURS[$i] == $anysJOR[$j] ) {
					if ( $anys!='' ) $anys .= "|";
					// echo "any:".$anysCURS[$i]."<br />";
					$anys .= $anysCURS[$i];
					$i++;
					$j++;
				}
				else {
					if ( $anys!='' ) $anys .= "|";
					// echo "any:".$anysCURS[$i]."<br />";
					$anys .= $anysCURS[$i];
					$i++;
				}
			}
			else if ( $i<count($anysCURS) ) {
				if ( $anys!='' ) $anys .= "|";
				// echo "any:".$anysCURS[$i]."<br />";
				$anys .= $anysCURS[$i];
				$i++;
			}
			else if ( $j<count($anysJOR) ) {
				if ( $anys!='' ) $anys .= "|";
				// echo "any:".$anysJOR[$j]."<br />";
				$anys .= $anysJOR[$j];
				$j++;
			}
		}

		$conWeb->desconectarBD();

		return $anys;
	}

	/**
   * @brief Mostra un text dels mesos disponibles separats amb un |
   * @return Mostra un text dels mesos disponibles de la taula cursos on cada any esta separat del següent amb un |
   */
	public function buscarMesosDisponibles() {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		$mesosCURS = [];
		$mesosJOR = [];
		$mesos = "";

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarMesosDiponibles"] ) ) {
			$stmt->execute();
			$stmt->bind_result($mes);
			$i = 0;
			while ($stmt->fetch()) {
				$mesosCURS[] = $mes;
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4076);
		}

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarMesosJorDiponibles"] ) ) {
			$stmt->execute();
			$stmt->bind_result($mes);
			$i = 0;
			while ($stmt->fetch()) {
				$mesosJOR[] = $mes;
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4165);
		}

		$i=0; $j=0; $trobat=false;
		while ( $i<count($mesosCURS) || $j<count($mesosJOR) ) {
			if ( $i<count($mesosCURS) && $j<count($mesosJOR) ) {
				if ( $mesosCURS[$i] < $mesosJOR[$j] ) {
					if ( $mesos!='' ) $mesos .= "|";
					$mesos .= $mesosCURS[$i];
					$i++;
				}
				else if ( $mesosCURS[$i] == $mesosJOR[$j] ) {
					if ( $mesos!='' ) $mesos .= "|";
					$mesos .= $mesosCURS[$i];
					$i++;
					$j++;
				}
				else {
					if ( $mesos!='' ) $mesos .= "|";
					$mesos .= $mesosJOR[$j];
					$j++;
				}
			}
			else if ( $i<count($mesosCURS) ) {
				if ( $mesos!='' ) $mesos .= "|";
				$mesos .= $mesosCURS[$i];
				$i++;
			}
			else if ( $j<count($mesosJOR) ) {
				if ( $mesos!='' ) $mesos .= "|";
				$mesos .= $mesosJOR[$j];
				$j++;
			}
		}

		$conWeb->desconectarBD();

		return $mesos;
	}

