	public function searUserByParam( $function, $param) {
		$dniDefinitius = '';

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		$likeParam = "%".$param."%";
		/* Busco totes les inscripcions on el param correspont a $param */
		if ( $param != '' ) {
			/* busquem totes les ids possibles amb el filtre de param == param
			i els posem a dniDefinitius; */
			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web[$function] ) ) {
				$stmt->bind_param("s", $likeParam);
				$stmt->execute();
				$stmt->bind_result($dniRes);
				while ($stmt->fetch()) {
					if ( $dniDefinitius != '' ) $dniDefinitius .= '|';
					$dniDefinitius .= $dniRes;
				}
				$conWeb->closeStmt();
			}
			else {
				throw new Exception('', 4008);
			}
		}

		$conWeb->desconectarBD();

		return $dniDefinitius;

	}

	/**
   * @brief Mostra els usuaris corresponents als dnies $dnies ordents per $oderby
   * @return Retorna una taula mostrant la informació dels usuaris (dni, nom, cognoms)
	*			 dels dnies $dnies ordenats per cognoms si $orderby == 'cog',
	*			 per dni si $order by == dni o per nom si $orderby == nom.
	* 			 Si $asc == 1, s'ordena ascendentment.
	* 			 Si $asc == 0, s'ordena ascendentment.
	* 			 Per defecte s'ordenarà per cognoms ascendents
   */
	public function mostrarTaulaUsuaris_Alumnes($dnies, $orderby, $asc) {
		if ($orderby != 'cog' && $orderby!='dni' && $orderby!='nom')
			$orderby = 'cog';
		if ($asc!=1 and $asc!=0)
			$asc = 1;

		$vectDni = json_decode($dnies);

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		for ($i = 0; $i<count($vectDni); $i++) {
			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscaNomCogInscOrd"] ) ) {
				$stmt->bind_param("s", $vectDni[$i]);
				$stmt->execute();
				$stmt->bind_result($nom, $cog);
				$stmt->fetch();
				$conWeb->closeStmt();
			}
			else {
				throw new Exception('', 4012);
			}

			$resultats[$i][0] = $vectDni[$i];
			$resultats[$i][1] = $nom;
			$resultats[$i][2] = $cog;
		}

		function cmpDni($a, $b) {
		    if ($a[0] == $b[0]) {
		        return 0;
		    }
		    return ($a[0] < $b[0]) ? -1 : 1;
		}

		function cmpNom($a, $b) {
		    if ($a[1] == $b[1]) {
		        return 0;
		    }
		    return ($a[1] < $b[1]) ? -1 : 1;
		}

		function cmpCog($a, $b) {
		    if ($a[2] == $b[2]) {
		        return 0;
		    }
		    return ($a[2] < $b[2]) ? -1 : 1;
		}

		if ($orderby == 'cog') usort($resultats, "cmpCog");
		else if ($orderby == 'nom') usort($resultats, "cmpNom");
		else if ($orderby == 'dni') usort($resultats, "cmpDni");

		$conWeb->desconectarBD();

		$classCog = '';
		$classNom = '';
		$classDni = '';

		if ($asc == 1) { //s'ordena ascendentment
			if ($orderby == 'cog') $classCog = ' asc';
			else if ($orderby == 'nom') $classNom = ' asc';
			else if ($orderby == 'dni') $classDni = ' asc';
		}
		else { //s'ordena desscendentment
			if ($orderby == 'cog') $classCog = ' desc';
			else if ($orderby == 'nom') $classNom = ' desc';
			else if ($orderby == 'dni') $classDni = ' desc';
		}

		//Mostra usuaris en format d'una taula ordenats per dni;
		$mostrar = "<table class='table table-striped table-hover table-order text-center'>
		<thead>
			<tr>
				<th id='th-dni' class='sorting".$classDni."'>DNI</th>
				<th id='th-nom' class='sorting".$classNom."'>NOM</th>
				<th id='th-cog' class='sorting".$classCog."'>COGNOMS</th>
				<th></th>
			</tr>
		</thead>
		<tbody>";

		if ($asc == 1) {
			$inici = 0;
			$fi = count($resultats);
			for ($i = $inici; $i<$fi; $i++) {
				$mostrar .= "<tr>";
				$mostrar .= "<td>".$resultats[$i][0]."</td>";
				$mostrar .= "<td>".$resultats[$i][1]."</td>";
				$mostrar .= "<td>".$resultats[$i][2]."</td>";
				$mostrar .= "<td><button class='boto-blau seleccionar' id='".$resultats[$i][0]."'>Selecciona</button></td>";
				$mostrar .= "</tr>";
			}
		}
		else {
			$inici = count($resultats);
			$fi = 0;
			for ($i = $inici-1; $i>=$fi; $i--) {
				$mostrar .= "<tr>";
				$mostrar .= "<td>".$resultats[$i][0]."</td>";
				$mostrar .= "<td>".$resultats[$i][1]."</td>";
				$mostrar .= "<td>".$resultats[$i][2]."</td>";
				$mostrar .= "<td><button class='boto-blau seleccionar' id='".$resultats[$i][0]."'>Selecciona</button></td>";
				$mostrar .= "</tr>";
			}
		}

		$mostrar .= "</tbody></table>";

		return $mostrar;
	}

