	/**
	* @brief Substitueix els camp NOM per $nom, COGNOMS per $cognoms,
	* 			CORREU per $correu, DNI per $dni, Codi_Postal per $cp,
	* 			Poblacio per $poblacio, PERFIL per $perfil, Titulacio per $titulacio,
	*			TELEFON per $telefon on la id d'inscripció és $idInsc
	* @return Substitueix els camp NOM per $nom, COGNOMS per $cognoms,
	* 			CORREU per $correu, DNI per $dni, Codi_Postal per $cp,
	* 			Poblacio per $poblacio, PERFIL per $perfil, Titulacio per $titulacio,
	*			TELEFON per $telefon on la id d'inscripció és $idInsc
	*/
	public function guardarDadesPersonals_resultatCerca($idInsc, $nom, $cognoms,
	$email, $dni, $adreca, $cp, $poblacio, $perfil, $titulacio, $telefon) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["updInscDadesPersCerca"] ) ) {
			$stmt->bind_param("ssssdsssssd", $nom, $cognoms, $email,
			$dni, $telefon, $adreca, $cp, $poblacio, $perfil, $titulacio, $idInsc);
			$stmt->execute();
			$conWeb->closeStmt();

			$mostrar = "OK";
		}
		else {
			throw new Exception('', 4024);
		}
		$conWeb->desconectarBD();

		return $mostrar;
	}

	/**
	* @brief Mostra la informació de tots els cursos corresponent a la ultima inscripció del dni $dni
	* @return  Mostra la informació de tots els cursos corresponent a la ultima inscripció del dni $dni
	*/
	private function __mostrarTotsCursos_resultatCerca($dni) {
		$mostrar = "";
		$registresCursos = "";
		$registresJornades = "";

		$existeixenInscripcions = false;
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarTotsRegistres"] ) ) {
			$stmt->bind_param("s", $dni);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$existeixenInscripcions = true;
				$stmt->bind_result($id, $tipusInsc, $any, $mes, $curs, $aula, $generat, $certificat,
				$titol, $estat, $pendent, $pagat, $idPag, $inscrit, $factura, $usuari);
				while ( $stmt->fetch() ) {
