	/**
	* @brief Mostra la fila de la taula del registre $id
	* @return Mostra la fila de la taula del registre $id. Si tipus >= 2 i $certificat
	* és 'no aprovat' i $pendent > 0, la fila es marcarà amb la classe 'text-danger'.
	* Si tipus >= 2 i certificat és 'no aprovat', la fila es marcarà amb la classe
	* 'text-warning'. Si tipus >= 2 i $pendent > 0, la fila es marcarà amb la classe
	* 'text-danger'. Si tipus >= 2 i $estat == 'P', la fila es marcarà amb la classe
	* 'text-info'. Mostra el any $any, el mes $mes, el curs $curs, si està inscrit o
	* no ($inscrit), el titol $titol, el certificat $certificat (si tipus >= 2 i
	* $certificat no està buit) o REVISAR (si tipus >= 2 i $certificat està buit)
	* o res (si tipus != 2), i les accions de mostra la informació de la inscripció,
	* canvia de curs/edició, dona de baixa, consulta la factura. El botó de la
	* consulta factura no està disponible si $factura == null o està en blanc i
	* estarà marcat si està generada. Si $tipus >= 2, es mostra també l'acció del
	* certificat. El botó de canvi de curs/edició no estarà disponible si $generat
	* és 1 o 2, o $inscrit == 'C' i $tipus >= 2. El botó de baixa no estarà disponible
	* si $generat és 1 o 2 i $tipus >= 2.
	*/
	private function __mostrarFilaResultatCerca($tipus, $id, $tipusI, $any, $mes, $curs, $aula,
	$generat, $certificat, $titol, $estat, $pendent, $pagat, $idPag, $inscrit, $factura, $usuari) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();
		$mostrar = '';
		if ( $inscrit == "1" )
			$textInscrit = "<span class='text-success'>INSCRIT</span>";
		else if ( $inscrit == "0" )
			$textInscrit = "<span class='text-alert'>NO INSCRIT</span>";
		else if ( $inscrit == "X" )
			$textInscrit = "<span class='text-success'>BAIXA</span>";
		else if ( $inscrit == "C" )
			$textInscrit = "<span class='text-success'>CANVI</span>";
		else if ( $inscrit == "D" )
				$textInscrit = "<span class='text-success'>DUPLICAT</span>";
		else if ( $inscrit == "M" )
				$textInscrit = "<span class='text-danger'>MORÒS</span>";
		else
			$textInscrit = "<span class='text-success'>".$inscrit."</span>";

		$facturaGenerada = false;
		if ($factura!=null and $factura!='') {
			echo $factura;
			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarInfoFacturaGener"] ) ) {
				$stmt->bind_param("d", $factura);
				$stmt->execute();
				$stmt->store_result();
				if ($stmt->num_rows() > 0) {
					$facturaGenerada = true;
				}
				$conWeb->closeStmt();
			}
			else {
				throw new Exception('', 4122);
			}
		}

		$classFactura='';
		$titleFactura='Consulta la factura de la inscripció';
		if ( $factura==null or $factura=='' or $pagat==0 ) {
			$classFactura = "-hide no-disponible";
			$titleFactura = "La factura de la inscripció no està disponible";
		}
		else if ( $facturaGenerada ) {
			$classFactura = " generada";
			$titleFactura = "La factura de la inscripció està generada";
		}

		$classCanvi='';
		$titleCanvi='Canvi de curs/edició';

		$classBaixa='';
		$titleBaixa='Dona de baixa';

		$classCert='';
		$titleCert='Consulta el certificat de la inscripció';
		$botoCert='';



		if ( $tipus >= 2 ) {
			if ( ($tipus == 3 || $tipus == 4) && ($generat == 1 || $generat == 2) && $inscrit == "X" ) {
				$mostrar .= "<tr class='text-success'>";
			}
			else if ( $certificat == 'no aprovat' && $pendent > 0 ) {
				$mostrar .= "<tr class='text-danger'>";
			}
			else if ( $certificat == 'no aprovat' ) {
				$mostrar .= "<tr class='text-warning'>";
			}
			else if ( $pendent > 0 ) {
				$mostrar .= "<tr class='text-danger'>";
			}
			else if ( $estat == 'P' ) {
				$mostrar .= "<tr class='text-info'>";
			}
			else {
				$mostrar .= "<tr>";
			}

			if ( $tipus == 3 && ($certificat == '' || $certificat == null) ) {
				$nomCert = "<span class='text-danger mr-2 text-accio'>REVISAR!</span>";
				if ( $tipus == 3 ) {
					$nomCert = "<span class='text-accio mr-2";
					if ( ( ($generat == 1 || $generat == 2) && $inscrit == "X" ) || $inscrit == "C" ) {
						$nomCert .= "'>CANVI";
					}
					else if ( !($generat == 1 || $generat == 2) && $inscrit == "X" ) {
						$nomCert .= " text-danger'>BAIXA";
					}
					else if ( $inscrit == "X" ) {
						$nomCert .= "'>BAIXA";
					}
					else if ( $inscrit == "C" ) {
						$nomCert .= "'>CANVI";
					}
					else {
						$nomCert .= " text-danger'>REVISAR!";
					}
					$nomCert .= "</span>";
				}
			}
			else {
				$nomCert = "<span class='mr-2 text-accio'>".$certificat."</span>";
				if ( $tipus == 3 ) {
					$nomCert = "<span class='mr-2 text-accio'>";
					if ( $inscrit == "X" ) {
						$nomCert .= "BAIXA";
					}
					else if ( $inscrit == "C" ) {
						$nomCert .= "CANVI";
					}
					else {
						$nomCert .= $certificat;
					}
					$nomCert .= "</span>";
				}
			}

			if ( $generat == 1 || $generat == 2 || $inscrit == "C" ) {
				$classCanvi = "-hide no-disponible";
				$titleCanvi = "El canvi de curs/edició no està disponible";
			}

			if ( $generat == 1 || $generat == 2 || ($tipus == 3 && $inscrit == "X") || ($tipus == 3 && $inscrit == "M") ) {
				$classBaixa = "-hide no-disponible";
				$titleBaixa = "La baixa no està disponible";
			}

			if ( ($certificat == 'no aprovat' || $pendent > 0 || $estat == 'P' ||
			($tipus == 3 && $inscrit == "X") || ($tipus == 3 && $inscrit == "M") || ($tipus == 3 && $inscrit == "C") ) ) {
				$classCert = "-hide no-disponible";
				$titleCert = "El certificat no està disponible";
			}
			if ( $tipus == 3 ) {
				$botoCert = "<i id='certificat-".$id."' class='fa-solid fa-file-signature ms-2 cns-certificat";
				$botoCert.= $classCert."' title='".$titleCert."'></i>";
			}

			if ( $tipus == 4 or $tipus == 2 ) {
				if ( $tipus == 4 ) {
					$nomClassCert = "cns-certificat-inscrit";
					$classCert = "";
					$titleCert = "";
				}
				else {
					$nomClassCert = "cns-certificat";
				}

				if ( !($pendent <= 0 || $pagat > 0 ) ) {
					$classCert = "-hide no-disponible";
					$titleCert = "El certificat no està disponible";
				}


				$botoCert = "<i id='certificat-".$id."' class='fa-solid fa-file-signature ms-2 ".$nomClassCert;
				$botoCert.= $classCert."' title='".$titleCert."'></i>";
			}

		}
		else {
			$mostrar .= "<tr>";
			$nomCert = "";

			if ( !($pendent <= 0 || $pagat > 0 ) ) {
				$classCert = "-hide no-disponible";
				$titleCert = "El certificat no està disponible";
			}
			$botoCert = "<i id='certificat-".$id."' class='fa-solid fa-file-signature ms-2 cns-certificat-inscrit";
			$botoCert.= $classCert."' title='".$titleCert."'></i>";

		}

		if ( $tipusI == 'I' ) {
			$idCercat = $idPag;
			$classTipus = "lightBlue";
			$iconTipus = "<i class='material-icons' aria-hidden='true'>person</i>";
		}
		else if ( $tipusI == 'R' ) {
			$idCercat = $id;
			$classTipus = "lightGreen";
			$iconTipus = "<i class='fas fa-gift' aria-hidden='true'></i>";
		}
		else if ( $tipusI == 'P' ) {
			$idCercat = $idPag;
			$classTipus = "lightPurple";
			$iconTipus = "<i class='fas fa-cubes' aria-hidden='true'></i>";
		}
		else if ( $tipusI == 'G' ) {
			$idCercat = $idPag;
			$classTipus = "lightOrange";
			$iconTipus = "<i class='material-icons aria-hidden='true'>group</i>";
		}

		$labelTipus = "<label id='labelType-".$idCercat."-".$tipus."' class='label tipus ".$classTipus." d-flex
		justify-content-center align-items-center position-relative
		font-weight-bold px-2 py-2 pointer'>".$iconTipus."</label>";

		$mostrar .= "<td>".$labelTipus."</td>
		<td>".$any."</td>
		<td>".$mes."</td>
		<td>".$curs."</td>
		<td>".$textInscrit."</td>
		<td>".$titol."</td>
		<td>
			<div class='d-flex flex-column flex-md-row justify-content-center align-items-center w-100'>
				<div class='d-flex flex-column flex-sm-row justify-content-end align-items-center w-100'>
					".$nomCert."
					<i id='info-".$id."' class='material-icons cns-informacio' title='Consulta la informació'>info</i>
					<i id='canvi-".$id."' class='material-icons ms-2 canvi-curs".$classCanvi."' title='".$titleCanvi."'>swap_horizontal_circle</i>
				</div>
				<div class='d-flex flex-column flex-sm-row justify-content-start align-items-center w-100'>
					<i id='baixa-".$id."' class='material-icons ms-2 donar-baixa".$classBaixa."' title='".$titleBaixa."'>cancel</i>
					<i id='factura-".$id."' class='fa-solid fa-file-invoice-dollar ms-2 cns-factura".$classFactura."' title='".$titleFactura."'></i>
					".$botoCert."
				</div>
			</div>
		</td>
		<td id='tipus-".$idCercat."' class='d-none'>".$tipusI."</td>

		</tr>";
		$mostrar .= $this->__mostrarModalConsulta("infoPag".$tipus, 1, 1, '', '');

		$conWeb->desconectarBD();
		return $mostrar;
	}

