	/**
   * @brief Mostra les observacions generals corresponent a la ultima inscripció del dni $dni
   * @return  Mostra les observacions generals corresponent a la ultima inscripció del dni $dni
   */
	public function mostrarObservacionsGenerals_resultatCerca($dni) {
		/*
		Busco les observacions que té la persona amb dni $dni.
		Si existeix alguna coservació, es mostra els valors en una taula.
		Si no existeix, indica que "No n'hi ha cap"
		*/
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarObsGeneral"] ) ) {
			$stmt->bind_param("s", $dni);
			$stmt->execute();
			$stmt->store_result();
			$mostrar = "<p class='titol-apartat d-flex'>Observacions generals<i class='material-icons ml-2 afegir-observacio'>add_circle</i></p>";
			$mostrar .= "<div class='d-flex flex-column align-items-center justify-content-center w-100'>";
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($id, $observacio, $data, $qui);
				while ($stmt->fetch()) {
					$mostrar .= "<div class='d-flex flex-column flex-sm-row align-items-center justify-content-center w-100 mb-2'>";

					$year=substr($data,0,4);
					$month=substr($data,5,2);
					$day=substr($data,8,2);
					$dataFormat=$day."/".$month."/".$year;

					$mostrar .= "<div class='datacol text-center p-2'>".$dataFormat."</div>";
					$mostrar .= "<div class='quicol text-center p-2'>".$qui."</div>";
					$mostrar .= "<div class='obscol text-center p-2'>".$observacio."</div>";
					$mostrar .= "<div class='ocultcol text-center p-2'><i id='amagar-".$id."' class='fas fa-eye amagar-observacio' aria-hidden='true'></i></div>";

					$mostrar .= "</div>";
				}
			}
			else {
				$mostrar .= "No n'hi ha cap.";
			}
			$mostrar .= "</div>";
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('', 4006);
		}
		$conWeb->desconectarBD();

		return $mostrar;
	}

