   * @return  Mostra les observacions generals corresponent a la ultima inscripció del dni $dni
   */
	public function afegirObservacioGeneral_resultatCerca($obs, $dni, $qui) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["insertObsGeneral"] ) ) {
			$stmt->bind_param("sss", $dni, $obs, $qui);
			$stmt->execute();
			$idInserit = $conWeb->lastInsertId();
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('', 4007);
		}
		$conWeb->desconectarBD();
	}

