	/**
   * @brief Mostra el contingut de la informació d'una inscripció em el modal d'inscripcio
   * @return Mostra el contingut de la informació d'una inscripció em el modal d'inscripcio
   */
	public function modalConsultaInformacio_resultatCerca($idInsc) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();
		$idmoodle = '';
		$iduser = '';
		/*
			Es busca la informació de la inscripció amb id $idInsc.
			Si no existeix la informació, es llança l'error 4001
		*/
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarInfoMostraInfo"] ) ) {
			$stmt->bind_param("d", $idInsc);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($any, $mes, $curs, $aula, $nom, $cognoms, $dni, $correu,
				$telefon, $adreca, $cp, $poblacio, $perfil, $titulacio, $datainsc,
				$inscrit, $tipusInsc, $inscao, $inscmail, $certificat, $obscertificat, $generat, $obs,
				$comentaris, $databaixa, $motiubaixa, $quibaixa, $apagar, $pag, $datapag,
				$idpag, $pagObs, $comHaPagat, $entitat, $fraccio, $comFraccio, $factura, $datarec, $reclamat, $usuari);
				$stmt->fetch();
			}
			else {
				throw new Exception('',4001);
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4015);
		}

		$codicurs = $any.$curs.$mes.$aula;

		/*
			Es busca la informació del curs amb id_curs $any.$curs.$mes i AULA $aula
			Si no existeix la informació, es llança l'error 4002
		*/
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarInfoCursHono"] ) ) {
			$stmt->bind_param("ss", $idCurs, $aula);
			$idCurs = $any.$curs.$mes;
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($titol, $hores, $datai, $dataf, $diesI, $diesF, $gtaf, $cursEscolar, $nomTutor, $cogTutor, $dniTutor);
				$stmt->fetch();
				$conWeb->closeStmt();
			}
			else {
				$conWeb->closeStmt();
				if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarInfoJorHono"] ) ) {
					$stmt->bind_param("dss", $any, $mes, $curs);
					$stmt->execute();
					$stmt->store_result();
					if ($stmt->num_rows() > 0) {
						$stmt->bind_result($titol, $hores, $datai, $dataf, $diesI, $diesF, $gtaf, $cursEscolar);
						$stmt->fetch();
					}
					else {
						throw new Exception('',4002);
					}
					$conWeb->closeStmt();
				}
				else {
					throw new Exception('',4154);
				}
			}
		}
		else {
			throw new Exception('',4016);
		}

		$perfilprofessional = "";

		/*
			Es busca la informació del perfil corresponent al codi $curs,
			curs escolar $cursEscolar i amb codi gtaf $gtaf
			Si existeix la informació, es guarda els perfils separats amb un | a
			la variable $perfilprofessional.
			Altrament, la variable $perfilprofessional esta buida
		*/
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarNomPerfil"] ) ) {
			$stmt->bind_param("sss", $curs, $cursEscolar, $gtaf);
			$stmt->execute();
			$stmt->store_result();
			$i = 0;
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($perf);
				while ($stmt->fetch()) {
					if ($i > 0) $perfilprofessional .= "<span class='mx-2'>|</span>";
					$perfilprofessional .= $perf;
				}
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4017);
		}
		/*
			Es busca el número d'inscrits del curs $curs de l'any $any, del mes $mes
			i de l'aula $aula
		*/
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarNInscrits"] ) ) {
			$stmt->bind_param("dsss", $any, $mes, $curs, $aula);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($inscripcions);
				$stmt->fetch();
			}
			else {
				$inscripcions = 0;
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4018);
		}

		$conWeb->desconectarBD();

		$tutor = $nomTutor." ".$cogTutor;

		/* S'indica a la variable $temps quan falta per començar el curs,
			quan falta per acabar-lo o quan fa que ha acabat */

		if ( $diesI == 0 )  //avui comença el curs
			$temps = "El curs comença avui.";
		else if ( $diesF == 0 )  //avui acaba el curs
			$temps = "El curs acaba avui.";
		else if ( $diesI < 0 )  //si falten dies per començar el curs, "Falta X dies per començar el curs."
		{
			if ( abs($diesI) == 1 )
				$temps = "Falta ".abs($diesI)." dia";
			else
				$temps = "Falten ".abs($diesI)." dies";

			$temps .= " per començar el curs.";

		}
		else if ( $diesI > 0 && $diesF < 0 )  //si el curs ha començat però falten dies per acabar el curs, "Han passat X dies des de que ha començat el curs."
		{
			if ( abs($diesI) == 1 )
				$temps = "Ha passat ".abs($diesI)." dia";
			else
				$temps = "Han passat ".abs($diesI)." dies";

			$temps .= " des de que ha començat el curs.";
		}
		else //si ha acabat el curs, "Ha passat 1 mes i 2 dies des de que ha acabat el curs" (quan fa que ha acabat el curs)
		{
			$firstDate  = new DateTime($dataf);
			$secondDate = new DateTime("now");
			$intvl = $firstDate->diff($secondDate);

			$temps = "Ha passat ";
			$tempsAnys = $tempsMesos = $tempsDies = '';
			if ( $intvl->y > 0 ) {
				$tempsAnys = $intvl->y;
				if ( $intvl->y == 1 )
					$tempsAnys .= " any";
				else
					$tempsAnys .= " anys";
			}
			if ( $intvl->m > 0 ) {
				$tempsMesos = $intvl->m;
				if ( $intvl->m == 1 )
					$tempsMesos .= " mes";
				else
					$tempsMesos .= " mesos";
			}
			if ( $intvl->d > 0 ) {
				$tempsDies = $intvl->d;
				if ( $intvl->d == 1 )
					$tempsDies .= " dia";
				else
					$tempsDies .= " dies";
			}

			if ( $tempsAnys != '' ) {
				$temps .= $tempsAnys;
				if ( $tempsMesos != '' ) {
					if ( $tempsDies != '' ) {
						$temps .= ", ".$tempsMesos." i ".$tempsDies;
					}
					else {
						$temps .= " i ".$tempsMesos;
					}
				}
				else {
					if ( $tempsDies != '' ) {
						$temps .= " i ".$tempsDies;
					}
				}
			}
			else {
				if ( $tempsMesos != '' ) {
					$temps .= $tempsMesos;
					if ( $tempsDies != '' ) {
						$temps .= " i ".$tempsDies;
					}
				}
				else {
					$temps .= $tempsDies;
				}
			}
			$temps .= " des de que ha acabat el curs";
		}

		$textMoodle = ""; //Variable que ens servirà per saber si estem treballant amb el moodle nou o amb l'antic

		$connexioModdle1 = new ConnexioMoodle();
		$connexioModdle1->connectarBD();

		/*
			Es busca la id del curs de la bd del moodle.
			Com que treballem amb dos moodles, caldrà veure si està disponible
			en el moodle nou. Si no està, llavors haurem d'anar mirar al
			moodle antic.
			Per tant, primer busquem la id del curs en el nou moodle.
			Si existeix,
				$textMoodle = 'moodle' (ens indicarà que treballem amb el nou moodle)
				$existeixCursMoodle = true; (ens indicarà que el curs existeix en un moodle)
				Es busca la id de l'usuari $usuari de la bd del nou moodle.
				Si no existeix, llança una excepció 4003
			Si no existeix,
				Es busca la id del curs de la bd del moodle antic.
				Si existeix,
					$textMoodle = 'moodleAntic' (ens indicarà que treballem amb el moodle antic)
					$existeixCursMoodle = true; (ens indicarà que el curs existeix en un moodle)
					Es busca la id de l'usuari $usuari de la bd del nou moodle.
					Si no existeix, $existeixCursMoodle = false;
				Si no existeix,
					$existeixCursMoodle = false;
			Si $existeixCursMoodle és false, no es mostraràn els botons per accedir als diferents enllaços del curs
		*/

		if ( $stmt=$connexioModdle1->prepare( $this->consultesBD_Moodle["buscarIdCurs"] ) ) {
			$stmt->bind_param("s", $shortname);
			$shortname = $any.$curs.$mes.$aula;
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($idmoodle);
				$stmt->fetch();
				$connexioModdle1->closeStmt();

				$existeixCursMoodle = true;
				$textMoodle = 'moodle';

				if ( $stmt=$connexioModdle1->prepare( $this->consultesBD_Moodle["buscarIdUsuari"] ) ) {
					$stmt->bind_param("d", $usuari);
					$stmt->execute();
					$stmt->store_result();
					if ($stmt->num_rows() > 0) {
						$stmt->bind_result($iduser);
						$stmt->fetch();
						$connexioModdle1->closeStmt();
					}
					else {
						$connexioModdle1->closeStmt();
						$existeixCursMoodle = false;
					}
				}
				else {
					throw new Exception('',4020);
				}
			}
			else {
				$connexioModdle1->closeStmt();

				$connexioModdle2 = new ConnexioMoodleAntic();
				$connexioModdle2->connectarBD();

				if ( $stmt=$connexioModdle2->prepare( $this->consultesBD_MoodleAntic["buscarIdCurs"] ) ) {
					$stmt->bind_param("s", $shortname);
					$shortname = $any.$curs.$mes.$aula;
					$stmt->execute();
					$stmt->store_result();
					if ($stmt->num_rows() > 0) {
