	/**
   * @brief Substitueix els camp NOM per $nom, COGNOMS per $cognoms, CORREU per
	* 			$email, DNI per $dni, TELEFON per $telefon, ADRECA per $adreca,
	*			Codi_Postal per $cp, Poblacio per $poblacio, PERFIL per $perfil,
	* 			Titulacio per $titulacio, DATA_INSC per $dataInsc, INSC CURS per
	*			$inscritCurs, PERENNE per $inscritAO, INSC_MAILING per $inscritMailing,
	*			CERTIFICAT per $cert, OBS CERT per $obsCert, GENERAT per $generat,
	*			OBSERVACIONS per $obs, COMENTARIS per $coment, DATA_BAIXA per
	*			$dataBaixa, MOTIU_BAIXA per $motiuBaixa, QUI_BAIXA per $quiBaixa
	*			on la id d'inscripció és $idInsc
   * @return Substitueix els camp NOM per $nom, COGNOMS per $cognoms, CORREU per
	* 			$email, DNI per $dni, TELEFON per $telefon, ADRECA per $adreca,
	*			Codi_Postal per $cp, Poblacio per $poblacio, PERFIL per $perfil,
	* 			Titulacio per $titulacio, DATA_INSC per $dataInsc, INSC CURS per
	*			$inscritCurs, PERENNE per $inscritAO, INSC_MAILING per $inscritMailing,
	*			CERTIFICAT per $cert, OBS CERT per $obsCert, GENERAT per $generat,
	*			OBSERVACIONS per $obs, COMENTARIS per $coment, DATA_BAIXA per
	*			$dataBaixa, MOTIU_BAIXA per $motiuBaixa, QUI_BAIXA per $quiBaixa
	*			on la id d'inscripció és $idInsc
   */
	public function guardarDadesPersonals_modalsresultatCerca($idInsc, $nom,
	$cognoms, $email, $dni, $telefon, $adreca, $cp, $poblacio, $perfil,
	$titulacio, $dataInsc, $inscritCurs, $inscritAO, $inscritMailing,
	$cert, $obsCert, $generat, $obs, $coment, $dataBaixa, $motiuBaixa, $quiBaixa) {

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		if ( $dataInsc != '' ) {
			$objDateInsc = new Date( $dataInsc );
			$dataInsc = $objDateInsc->getDataFomatYYYYMMDD_HHMMSS();
		}
		else
			$dataInsc = null;

		if ( $dataBaixa != '' ) {
			$objDateBaixa = new Date( $dataBaixa );
			$dataBaixa = $objDateBaixa->getDataFomatYYYYMMDD_HHMMSS();
		}
		else
			$dataBaixa = null;

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["updInscDadesPersInfo"] ) ) {
			$stmt->bind_param("ssssdsssssssssssdsssssd", $nom, $cognoms, $email,
			$dni, $telefon, $adreca, $cp, $poblacio, $perfil, $titulacio,
			$dataInsc, $inscritCurs, $inscritAO, $inscritMailing, $cert, $obsCert,
			$generat, $obs, $coment, $dataBaixa, $motiuBaixa, $quiBaixa, $idInsc);
			$stmt->execute();
			$conWeb->closeStmt();

			$mostrar = "OK";
		}
		else {
			throw new Exception('', 4005);
		}
		$conWeb->desconectarBD();

		return $mostrar;
	}

	/**
   * @brief Substitueix els camp A_PAGAR per $apagar, DATA PAG per $datapag,
	* 			IDPAG per $idpag, pag_observacions per $pagobs, forma_pagament per $comhapagat,
	* 			ENTITAT per $entitat, FRACCIONAT per $fraccio, FRACCIO per $comfraccio,
	*			FACTURA_RELACIONADA per $factura, data_reclamacio per $datarec,
	*			reclamat per $rec on la id d'inscripció és $idInsc
   * @return Substitueix els camp A_PAGAR per $apagar, DATA PAG per $datapag,
	* 			IDPAG per $idpag, pag_observacions per $pagobs, forma_pagament per $comhapagat,
	* 			ENTITAT per $entitat, FRACCIONAT per $fraccio, FRACCIO per $comfraccio,
	*			FACTURA_RELACIONADA per $factura, data_reclamacio per $datarec,
	*			reclamat per $rec on la id d'inscripció és $idInsc
   */
	public function guardarDadesPagament_modalsresultatCerca($idInsc, $apagar, $pagament,
	$datapag, $idpag, $pagobs, $fraccio, $comfraccio,
	$factura, $datarec, $rec) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		if ( $datapag != '' ) {
			$objDatePag = new Date( $datapag );
			$datapag = $objDatePag->getDataFomatYYYYMMDD_HHMMSS();
		}
		else {
			$datapag = null;
		}
		if ( $datarec != '' ) {
			$objDateRec = new Date( $datarec );
			$datarec = $objDateRec->getDataFomatYYYYMMDD_HHMMSS();
		}
		else {
			$datarec = null;
		}
		if ( $factura == '' ) {
			$factura = null;
		}

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["updInscDadesPagInfo"] ) ) {
			$stmt->bind_param("ddsdsdsdssd", $apagar, $pagament, $datapag, $idpag,
			$pagobs, $fraccio, $comfraccio, $factura, $datarec,
			$rec, $idInsc);
			$stmt->execute();
			$conWeb->closeStmt();

			$mostrar = "OK";
		}
		else {
			throw new Exception('', 4023);
		}
		$conWeb->desconectarBD();

		return $mostrar;
	}

	/**
	 * @brief Envia una notificació a l'alumne indicant el mètode que ens ha
	 * 				indicat per fraccionar el pagament
	 * @return Envia una notificació a l'alumne indicant el mètode que ens ha
	 * 				indicat per fraccionar el pagament
	 */
	 public function enviarNotificacioObsPagament_modalsresultatCerca($idInsc, $apagar, $pagament,
 	 $pagobs, $recPag) {

		$pagobs = str_replace(chr(13),"<br />", $pagobs);	// substituïm la tecla intro pel tag <br> perquè quedi correcte en el mail

		$pendent = $apagar - $pagament;

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarParam"] ) ) {
			$stmt->bind_param("s", $tipus);

			$tipus = 'autentificacioSecretaria';
			$stmt->execute();
			$stmt->bind_result($valor);
			$stmt->fetch();

			$autentificacioSecretaria = explode('|',$valor);
			$usernameSecre = $autentificacioSecretaria[0];
			$passwordSecre = $autentificacioSecretaria[1];
			$nameUserSecre = $autentificacioSecretaria[2];
			$conWeb->closeStmt();
		}
		else
			throw new Exception('',4334);

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarInfoInscCurs"] ) ) {
			$stmt->bind_param("d", $idInsc);
			$stmt->execute();
			$stmt->bind_result($anyInsc, $mesInsc, $codiCursInsc, $aulaInsc, $dataInscripcioInsc,
			$nomInsc, $cogInsc, $emailInsc, $dniInsc, $adrecaInsc, $cpInsc, $poblacio,
			$telefonInsc, $obsInsc, $perfilInsc, $titolInsc, $inscritInsc, $tipusInsc,
			$inscMailingInsc, $apagarInsc, $pagamentInsc, $dataPagInsc, $idpagInsc, $factRelInsc,
			$fraccionatInsc, $comHaPagatInsc, $comentarisInsc, $obsPagInsc, $conegutInsc,
			$motiuBaixaInsc, $usuariInsc, $perenneInsc, $horesInsc, $idPreuInsc,
			$nomCursInsc, $dataiInsc, $datafInsc, $dniTutorInsc);

			$stmt->fetch();

			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4335);
		}

		$conWeb->desconectarBD();

		$dateNow = new DateTime("now");
		$dataAct = $dateNow->format('d/m/Y');
		$dataHoraAct = $dateNow->format('d/m/Y H:i');

		// $subject = "Pagament fraccionat. ".$_POST['icurs']." ".$_POST['idni']; // perquè no apareguin junts els correus
		$subject = "Pagament fraccionat del curs ".$nomCursInsc." | ".$dataAct;
		$subjectCopiaResguard = "Pagament fraccionat. ".$codiCursInsc." ".$dniInsc." ".$dataHoraAct;

		$recordatori = "";
		if ( $recPag == "1" )
			$recordatori = "<p>Et recordem que cal efectuar un primer pagament abans de l'inici del curs i que despr&eacute;s de la finalitzaci&oacute; d'aquest encara disposar&agrave;s d'uns dies per acabar de pagar els <strong>".$pendent." euros</strong>.</p>";

		$missatge = "<p>Benvolgut/da ".$nomInsc.",</p>
		<p align=justify>Et confirmem que hem anotat en la teva inscripci&oacute; al curs <strong style='color: ".$this->colors_destacats["msgDestacatCorreu1"]."'>".$nomCursInsc."</strong> la forma de fraccionar el pagament que ens has comentat:</p>
		<ul style='list-style: square; margin-bottom: 20px; margin-left: 30px; padding: 0;'>
			&laquo;".$pagobs."&raquo;
		</ul>
		<p>Quan rebem cada pagament t'enviarem un missatge de confirmaci&oacute; al teu correu electr&ograve;nic <a
		href='mailto:".$emilInsc."' style='font-weight: bold; text-decoration: none;
		color: ".$this->colors_destacats["msgDestacatCorreu1"]."'>".$emailInsc."</a>.</p>

		".$recordatori."

		<p>Atentament,</p>";

		$qui = $this->usuari->getNom()->get()." ".$this->usuari->getCognom()->get();
		$depart = $this->usuari->getDepart()->get();

		// Enviem un correu de confirmació
		require_once "MailSMTPComvive.php";

		$nomFromHead = $nameUserSecre;
		$correuFromHead = $usernameSecre;
		$nomReplyHead = $nomInsc." ".$cogInsc;
		$correuReplyHead = $emailInsc;

		$nomTo = "PrisMa Secretaria";
		$correuTo = "resguard.secretaria@prisma.cat";

		$mailTut = new MailSMTPComvive($usernameSecre, $passwordSecre, $nomFromHead, $correuFromHead,
										$nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
										$subjectCopiaResguard, $missatge, $qui, $depart);

		$nomTo = $nomInsc." ".$cogInsc;
		$correuTo = $emailInsc;
		$nomReplyHead = $nameUserSecre;
		$correuReplyHead = $usernameSecre;

		$mailTut = new MailSMTPComvive($usernameSecre, $passwordSecre, $nomFromHead, $correuFromHead,
										$nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
										$subject, $missatge, $qui, $depart);

		$mostrar = "OK";
		return $mostrar;
	}

