	/**
   * @brief Mostra el contingut del canvi d'edició d'una inscripció em el modal d'inscripcio
   * @return Mostra el contingut del canvi d'edició d'una inscripció em el modal d'inscripcio
   */
	public function modalCanviCurs_resultatCerca($idInsc) {
		$motiuCanvi = 'Canvi de curs';

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		/* Busquem la informació del canvi de curs de la inscripció  */
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarInfoCanviCurs"] ) ) {
			$stmt->bind_param("d", $idInsc);
			$stmt->execute();
			$stmt->bind_result($any, $curs, $mes, $obsinsc, $datainsc, $apagat, $pagat, $dies,
			$diesBaixa, $motiuBaixa, $dni, $factRel, $cert, $idpag, $tipusDesc, $validDesc);
			$stmt->fetch();
			$conWeb->closeStmt();
		}
		else {
			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarInfoCanviJor"] ) ) {
				$stmt->bind_param("d", $idInsc);
				$stmt->execute();
				$stmt->bind_result($any, $curs, $mes, $obsinsc, $datainsc, $apagat,
				$pagat, $dies, $diesBaixa, $motiuBaixa, $dni, $factRel, $cert, $idpag);
				$stmt->fetch();
				$conWeb->closeStmt();
			}
			else {
				throw new Exception('',4029);
			}
		}

		if ( $obsinsc != '' ) {
			$ObjObs = new Text($obsinsc);
			$ObjObs->replace('/n', '<br />');
			$ObjObs->replace('/r', '<br />');
			$obsinsc = $ObjObs->get();
		}

		/* Si ha pagat, s'ha de marcar amb la classe text-danger */
		$dangerHaPagat = '';
		if ( $pagat > 0 ) $dangerHaPagat = 'text-danger';

		/* Calculem els dies que han passat des de la data d'inici del curs a la
		data de baixa si n'hi ha. Si no hi ha data baixa, doncs els dies que
		han passat des de la data d'inici a l'actual. */
		$diesHanPassat = 0;
		if ( $diesBaixa != null )
			$diesHanPassat = $diesBaixa;
		else {
			if ( $dies > 0 )
				$diesHanPassat = $dies;
		}

		/* Si exiteix un motiu de baixa, cal que es mostri */
		$textMotiuBaixa = "";
		if ( $motiuBaixa != null )
			$textMotiuBaixa = $this->__mostrarInput(1,"","MOTIU BAIXA", "active", "moitu-baixa-canvi-curs-actual", "no-edit", $motiuBaixa);

		/* Si el cerfiticat s'ha pujat, s'ha d'avisar*/
		$alertaCertificat = "";
		if ( $cert != null && $cert != '' ) {
			$alertaCertificat = "<div class='alert alert-warning alert-with-icon w-100 py-3 mb-4'>";
			$alertaCertificat .= "<i class='material-icons' data-notify='icon'>notifications</i>";
			$alertaCertificat .= "<button type='button' data-dismiss='alert' aria-label='Close' ";
			$alertaCertificat .= "class='close'><i class='material-icons'>close</i></button>";
			$alertaCertificat .= "<span>".$cert."!</span></div>";
		}

		/* Es busca tots els canvis que ha fet la persona amb la mateixa factura que no sigui l'actual curs*/
		$tableCanvis = "";
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarCanvisUser"] ) ) {
			$stmt->bind_param("ssdd", $dni, $curs, $idInsc, $factRel);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($anyC, $mesC, $datainscC, $pagatc, $obsinscC,
			 	$datapagC, $motiuBaixaC, $dataIniciC, $diesBaixaInscC, $diesBaixaIniciC);
				$tableCanvis = "<table class='table table-striped table-hover text-center mt-2'>
				<thead><tr>
					<th>ANY</th>
					<th>MES</th>
					<th>DATA INSC</th>
					<th>DIES</th>
					<th>PAGAT</th>
					<th>OBSERVACIONS</th>
					<th>MOTIU CANVI / BAIXA</th>
				</tr></thead>
				<tbody>";
				while ( $stmt->fetch() ) {
					$tableCanvis .= "<tr>";
					$tableCanvis .= "<td>".$anyC."</td>";
					$tableCanvis .= "<td>".$mesC."</td>";

					$dateInscC = new Date($datainscC);
					$tableCanvis .= "<td>".$dateInscC->getDataFomatDDMMYYYY_HHMMSS()."</td>";

					if ( $datainscC > $dataIniciC ) $diesC = $diesBaixaInscC;
					else if ( $diesBaixaIniciC < 0 ) $diesC = 0;
					else $diesC = $diesBaixaIniciC;
					$tableCanvis .= "<td>".$diesC."</td>";

					$datapagamentC = '-';
					if ( $datapagC != null && $datapagC != "0000-00-00 00:00:00" ) {
						$datePagC = new DateTime($datapagC);
						$datapagamentC = $datePagC->format('d/m/Y H:i:s');
					}
					$tableCanvis .= "<td>".$datapagamentC."</td>";

					$tableCanvis .= "<td>".$obsinscC."</td>";
					$tableCanvis .= "<td>".$motiuBaixaC."</td>";

					$tableCanvis .= "</tr>";
				}
			}
			$conWeb->closeStmt();
			$tableCanvis .= "</tbody></table>";
		}
		else {
			throw new Exception('',4030);
		}
		$conWeb->desconectarBD();

		$anyActual = date('Y');

		/* Busquem els anys disponibles pel curs $curs */
		$vectAnys = explode('|', $this->buscarAnys_modalCanviCurs($curs));
		/* Busquem els mesos disponibles pel curs $curs i per l'any $any*/
		$vectMesos = explode('|', $this->buscarMesos_modalCanviCurs($anyActual, $curs));
		/* Busquem els cursos disponibles pel mes $mes i per l'any $any */
		$vectCursos = explode('|', $this->buscarCursosTotal_modalCanviCurs($anyActual));
		$vectCanvi = [];
		$opcionsCanvi = "<li class='border-bottom m-0' id='dades-canvi-numero-0'><a href='#'>No compta</a></li>
		<li class='border-bottom m-0' id='dades-canvi-numero-2'><a href='#'>Canvi</a></li>
		<li class='border-bottom m-0' id='dades-canvi-numero-3'><a href='#'>Extra</a></li>
		<li class='border-bottom m-0' id='dades-canvi-numero-4'><a href='#'>Despes de gestió</a></li>";

		$apagarNou = $this->buscarPreuAPagar_modalCanviCurs($idInsc, $anyActual, $mes, $curs, $apagat, $tipusDesc, $validDesc);
		$despeses = 0;

		$objDataInsc = new Date($datainsc);
		$dataInscTr = $objDataInsc->getDataFomatDDMMYYYY_HHMMSS();

		$classPreuAPagar = 'active';
		if ( $apagarNou != $apagat ) $classPreuAPagar .= ' text-danger font-weight-bold';

		$exMoros = $this->comprovaAlumnaEsMoros($dni);
		$alertaMoros = '';
		if ( $exMoros ) {
			$alertaMoros = "<div id='moros' class='d-flex flex-column justify-content-center
			align-items-center badge text-center bg-danger mb-3 py-3 fs-5'>DEUTOR!</div>";
			$alertaMoros .= "<p class='text-center'>Ha de pagar per realitzar qualsevol canvi!</p>";
		}

		$mostrar = $alertaMoros."<div id='dades-curs-canvi' class='destacat-blau d-flex flex-column
		justify-content-center align-items-center my-2 py-2'>
			<p class='titol-apartat'>Dades curs</p>
			<div class='apartat d-flex flex-column flex-md-row align-items-center justify-content-center w-100 my-2'>
				<div class='d-flex flex-column align-items-center justify-content-center w-100'>
					".$this->__mostrarInput(1,"hide","ID", "active", "id-canvi-curs-actual", "no-edit", $idInsc)."
					".$this->__mostrarInput(1,"hide","TIPUSDESC", "", "tipusDesc-registre", "no-edit", $tipusDesc)."
					".$this->__mostrarInput(1,"hide","VALIDESC", "", "validDesc-registre", "no-edit", $validDesc)."
					".$this->__mostrarInput(1,"","ANY", "active", "any-canvi-curs-actual", "no-edit", $any)."
					".$this->__mostrarInput(1,"","CURS", "active", "curs-canvi-curs-actual", "no-edit", $curs)."
					".$this->__mostrarInput(1,"","MES", "active", "mes-canvi-curs-actual", "no-edit", $mes)."
					".$this->__mostrarInput(1,"","OBSERVACIONS", "active", "obs-canvi-curs-actual", "no-edit", $obsinsc)."
					".$textMotiuBaixa."
				</div>
				<div class='d-flex flex-column align-items-center justify-content-center w-100'>
					".$this->__mostrarInput(1,"","DATA INSC", "active", "datainsc-canvi-curs-actual", "no-edit", $dataInscTr)."
					".$this->__mostrarInput(1,"","A PAGAR", $classPreuAPagar, "apagar-canvi-curs-actual", "no-edit", $apagat." €")."
					".$this->__mostrarInput(1,"","PAGAT", "active", "pagat-canvi-curs-actual", "no-edit", $pagat." €")."
					".$this->__mostrarInput(1,"","DIES", "active", "dies-canvi-curs-actual", "no-edit", $diesHanPassat)."
				</div>
			</div>
			".$tableCanvis."
		</div>
		<div id='dades-canvi' class='d-flex flex-column
			justify-content-center align-items-center mt-3'>
			<p class='titol-apartat'>Dades canvi</p>
			<div class='loading-wrapper hide'><div class='loading-content'></div></div>
			<div class='result-success hide'></div>
			<div class='apartat d-flex flex-column flex-md-row align-items-center justify-content-center w-100 mt-2'>
				<div class='d-flex flex-column align-items-center justify-content-center w-100'>
					".$this->mostrarSelect('', 'ANY', 'active', 'dades-canvi-any', '', $anyActual, '', $vectAnys)."
					".$this->mostrarSelect('', 'MES', 'active', 'dades-canvi-mes', '', "Triar", '', $vectMesos)."
				</div>
				<div class='d-flex flex-column align-items-center justify-content-center w-100'>
					".$this->mostrarSelect('', 'CURS', 'active', 'dades-canvi-curs', '', $curs, '', $vectCursos)."
					".$this->mostrarSelect('', 'CANVI', 'active', 'dades-canvi-numero', '', '', $opcionsCanvi, $vectCanvi)."
				</div>
			</div>
		</div>
		<div id='dades-nou-registre' class='d-flex flex-column
			justify-content-center align-items-center mb-2'>
			<div class='loading-wrapper hide'><div class='loading-content'></div></div>
			<div class='result-success hide'></div>
			<div class='apartat d-flex flex-column flex-md-row align-items-center justify-content-center w-100 mb-2'>
				<div class='d-flex flex-column align-items-center justify-content-center w-100'>
				".$this->__mostrarInput(2,"","A_PAGAR", $classPreuAPagar, "apagar-nou-registre", "edit", $apagarNou)."
				".$this->__mostrarInput(2,"","DESPESES", "active", "despeses-registre", "edit", $despeses)."
				".$this->__mostrarTextarea('', 'OBSERVACIONS PER AL NOU CURS', 'active', 'obs-canvi', 'edit', '', 'text')."
				</div>
				<div class='d-flex flex-column align-items-center justify-content-center w-100'>
				".$this->__mostrarInput(2,"","PAGAT", "active", "pagat-nou-registre", "edit", $pagat)."
				".$this->__mostrarInput(2,"","PENDENT", "active", "pendent-nou-registre", "edit", (floatval($apagarNou) - floatval($pagat)))."
				".$this->__mostrarTextarea('', 'MOTIU CANVI', 'active', 'motiu-canvi', 'edit', $motiuCanvi, 'text')."
