	/**
   * @brief Mostra un text dels anys disponibles a partir de l'any actual on cada any esta separat del següent amb un |
   * @return Mostra un text dels anys disponibles a partir de l'any actual on cada any esta separat del següent amb un |
   */
	public function buscarAnys_modalCanviCurs($curs) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		$anysCURS = [];
		$anysJOR = [];
		$anys = "";

		$objData = new Date("now");
		$anyActual = $objData->getAny();
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarAnysDispoCurs"] ) ) {
			$stmt->bind_param("d", $anyActual);
			$stmt->execute();
			$stmt->bind_result($any);
			while ($stmt->fetch()) {
				$anysCURS[] = $any;
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4026);
		}

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarAnysDispoJor"] ) ) {
			$stmt->bind_param("d", $anyActual);
			$stmt->execute();
			$stmt->bind_result($any);
			while ($stmt->fetch()) {
				$anysJOR[] = $any;
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4158);
		}

		$conWeb->desconectarBD();

		$i=0; $j=0; $trobat=false;
		while ( $i<count($anysCURS) || $j<count($anysJOR) ) {
			if ( $i<count($anysCURS) && $j<count($anysJOR) ) {
				if ( $anysCURS[$i] < $anysJOR[$j] ) {
					if ( $anys!='' ) $anys .= "|";
					$anys .= $anysCURS[$i];
					$i++;
				}
				else if ( $anysCURS[$i] == $anysJOR[$j] ) {
					if ( $anys!='' ) $anys .= "|";
					$anys .= $anysCURS[$i];
					$i++;
					$j++;
				}
				else {
					if ( $anys!='' ) $anys .= "|";
					$anys .= $anysJOR[$j];
					$j++;
				}
			}
			else if ( $i<count($anysCURS) ) {
				if ( $anys!='' ) $anys .= "|";
				$anys .= $anysCURS[$i];
				$i++;
			}
			else if ( $j<count($anysJOR) ) {
				if ( $anys!='' ) $anys .= "|";
				$anys .= $anysJOR[$j];
				$j++;
			}
		}

		return $anys;
	}

