	/**
   * @brief Busca el preu a pagar del curs de l'any $any i del mes $mes de la inscripcio $idInsc
   * @return Busca el preu a pagar del curs de l'any $any, del mes $mes, del curs $curs.
	* Per trobar el preu, es busca l'id_preu de la taula curs corresponent
	* a l'any $any, del mes $mes, del curs $curs. Si la persona de la inscripció
	* amb id $idInsc ha tingut alguna inscripció que estigui pagada abans de la
	* data d'inscripció corresponent a la $idInsc, retornarem el preu amb descompte.
	* Altrament, retornarem el preu sense cap descompte
   */
	public function buscarPreuAPagar_modalCanviCurs($idInsc, $any, $mes, $curs, $apagat, $tipusDesc, $validDesc) {
		$teCarnetJove = false;
		$esExalumne = false;
		$nouAlumne = true;

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		/* Busquem si la inscripció està marcada com a Carnet Jove */
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarIdSegonsObsID"] ) ) {
			$stmt->bind_param("sd", $observacio, $idInsc);
			$observacio = '%Carnet Jove%';
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$teCarnetJove = true;
				$nouAlumne = false;
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4034);
		}

		if ( !$teCarnetJove ) {
			/* Busquem si la persona és exalumne */

			/* Buscar la data inscripcio de la inscripcio $idInsc */
			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarDataInscDNISegID"] ) ) {
				$stmt->bind_param("d", $idInsc);
				$stmt->execute();
				$stmt->bind_result($dataInsc, $dni);
				$stmt->fetch();
				$conWeb->closeStmt();
			}
			else {
				throw new Exception('',4035);
			}

			/* Buscar si existeix com a minim un registre que hagi fet un curs
			que estigui pagat o que sigui un regal que no sigui un registrat
			duplicat que no sigui la inscripció $idinsc i que la data de la
			inscripció sigui anterior a $dataInsc */
			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["inscrEsAlumneCanvi"] ) ) {
				$stmt->bind_param("sds", $dni, $idInsc, $dataInsc);
				$stmt->execute();
				$stmt->store_result();
				if ($stmt->num_rows() > 0) {
					$esExalumne = true;
					$nouAlumne = false;
				}
				$conWeb->closeStmt();
			}
			else {
				throw new Exception('',4036);
			}
		}
		else {
			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarDataInscDNISegID"] ) ) {
				$stmt->bind_param("d", $idInsc);
				$stmt->execute();
				$stmt->bind_result($dataInsc, $dni);
				$stmt->fetch();
				$conWeb->closeStmt();
			}
			else {
				throw new Exception('',4035);
			}

		}

		/* Busquem el id preu de l'edició corresponent */
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarCursSegEd"] ) ) {
			$stmt->bind_param("dss", $any, $mes, $curs);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($nomCurs, $datai, $dataf, $hores, $idPreu);
				$stmt->fetch();
				$conWeb->closeStmt();
			}
			else {
				$conWeb->closeStmt();
				if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarJorSegEd"] ) ) {
					$stmt->bind_param("dss", $any, $mes, $curs);
					$stmt->execute();
					$stmt->store_result();
					if ($stmt->num_rows() > 0) {
						$stmt->bind_result($titol, $datai, $dataf, $hores, $idPreu);
						$stmt->fetch();
						$conWeb->closeStmt();
					}
					else {
						$conWeb->closeStmt();
					}
				}
				else {
					throw new Exception('',4163);
				}
			}
		}
		else {
			throw new Exception('',4037);
		}

		/* Mirem si l'alumne té descompte */
		$teDescompte = 0;
		if ( $stmt=$conWeb->prepare( "SELECT ID FROM descomptes where tipus >= 10 and curs = ? and mes = ? and datai <= ? and ( ? <= dataf or dataf is null) and preu = ?" ) ) {
			$stmt->bind_param("ssssd", $curs, $mes, $dataInsc, $dataInsc, $apagat);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$teDescompte = 1;
				$preu = $apagat;
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',xxx);
		}

		if ( !$teDescompte ) {
			if ( $validDesc == 1 && ( $tipusDesc == 4 || $tipusDesc == 5 || $tipusDesc == 6 || $tipusDesc == 7 || $tipusDesc == 8 ) ) {
				if ( $stmt=$conWeb->prepare( "SELECT PREU FROM descomptes
					WHERE tipus = ? AND ID_PREU = ? AND (curs = ? OR curs = 'TOTS') AND
					(mes = ? OR mes = 'TOTS') AND datai <= ? AND ( ? <= dataf or dataf is null)" ) ) {
					$stmt->bind_param("ddssss", $tipusDesc, $idPreu, $curs, $mes, $dataInsc, $dataInsc);
					$stmt->execute();
					$stmt->store_result();
					$stmt->bind_result($preuDescompte);
					$stmt->fetch();
					if ($stmt->num_rows() > 0) {
						$teDescompte = 1;
						$preu = $preuDescompte;
					}
					$conWeb->closeStmt();
				}
				else {
					throw new Exception('',xxx);
				}
			}
		}

		if ( !$teDescompte ) {
			/* Calculem el preu amb descompte Carnet Jove */
			if ( $teCarnetJove ) {
				if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarPreuDescompte"] ) ) {
					$stmt->bind_param("dd", $idPreu, $tipus);
					$tipus = 2;
					$stmt->execute();
					$stmt->bind_result($preu);
					$stmt->fetch();
					$conWeb->closeStmt();
				}
				else {
					throw new Exception('',4038);
				}		}

			/* Calculem el preu amb descompte Exalumne */
			if ( $esExalumne ) {
				if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarPreuDescompte"] ) ) {
					$stmt->bind_param("dd", $idPreu, $tipus);
					$tipus = 1;
					$stmt->execute();
					$stmt->bind_result($preu);
					$stmt->fetch();
					$conWeb->closeStmt();
				}
				else {
					throw new Exception('',4039);
				}
			}

			/* Calculem el preu car */
			if ( $nouAlumne ) {
				if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarPreuCar"] ) ) {
					$stmt->bind_param("d", $idPreu);
					$stmt->execute();
					$stmt->bind_result($preu);
					$stmt->fetch();
					$conWeb->closeStmt();
				}
				else {
					throw new Exception('',4040);
				}
			}
		}
		$conWeb->desconectarBD();
		echo $preu."<br />";

		return $preu;
	}

	/**
   * @brief Busca les despeses de gestió corresponent a l'edició del curs $curs
	* de l'any $any i del mes $mes
   * @return Busca les despeses de gestió corresponent a l'edició del curs $curs
	* de l'any $any i del mes $mes
   */
	public function calcularDespesesGestio_modalCanviCurs($any, $mes, $curs) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		// echo $any.$mes.$curs;

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarCursSegEd"] ) ) {
			$stmt->bind_param("dss", $any, $mes, $curs);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($nomcurs, $datai, $dataf, $hores, $idPreu);
				$stmt->fetch();
				$conWeb->closeStmt();
			}
			else {
				$conWeb->closeStmt();
				if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarJorSegEd"] ) ) {
					$stmt->bind_param("dss", $any, $mes, $curs);
					$stmt->execute();
					$stmt->store_result();
					if ($stmt->num_rows() > 0) {
						$stmt->bind_result($titol, $datai, $dataf, $hores, $idPreu);
						$stmt->fetch();
						$conWeb->closeStmt();
					}
					else {
						$conWeb->closeStmt();
					}
				}
				else {
					throw new Exception('',4161);
				}
			}
		}
		else
			throw new Exception('',4031);

		$conWeb->desconectarBD();

		// echo $hores;

		$conIntra = new ConnexioIntranet();
		$conIntra->connectarBD();

		/* ##### Busquem les despeses corresponents a les hores del curs ##### */
		/* Les despeses de gestió es calculen segons el nombre d'hores del curs anterior
		ja que representa que és el que li has pagat el tutor/a */
		if ( $stmt=$conIntra->prepare( $this->consultesBD_Intra["buscarParam"] ) ) {
			$stmt->bind_param("ss", $param, $tipus);
			$param = "despeses-gestio";
			$tipus = $hores;
			$stmt->execute();
			$stmt->bind_result($despeses);
			$stmt->fetch();
			$conIntra->closeStmt();
		}
		else
			throw new Exception('',4032);

		$conIntra->desconectarBD();

		return $despeses;
	}

	/**
   * @brief Realitza el canvi de curs de la inscripcio $idInsc per l'any $anyC,
	* el mes $mesC, el curs $cursC amb el numero de canvi $numeroCanvi, amb les
	* observacions $obsCanvi i el motii de canvi $motiuCanvi. S'avisarà a l'alumne
	* si  $checkNoEnviarCoreu és true
   * @return Realitza el canvi de curs de la inscripcio $idInsc per l'any $anyC,
	* el mes $mesC, el curs $cursC amb el numero de canvi $numeroCanvi, amb les
	* observacions $obsCanvi i el motii de canvi $motiuCanvi. S'avisarà a l'alumne
	* si  $checkNoEnviarCoreu és true
   */
	public function realitzarCanviCurs_modalCanviCurs($idInsc, $anyC, $mesC,
	$cursC, $numeroCanvi, $apagarC, $pagatC, $pendentC, $despesesC, $obsCanvi,
	$motiuCanvi, $noEnviarCoreu, $tipusDesc, $validDesc) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();
		$conIntra = new ConnexioIntranet();
		$conIntra->connectarBD();

		$sendCoreu = 0;
		if ( $noEnviarCoreu == "false" ) $sendCoreu = 1;

		echo $this->consultesBD_Web["buscarInfoInscCurs"]."<br />";
		echo $idInsc."<br />";
		/* ############## Busquem la informacio de la inscripcio ############## */
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarInfoInscCurs"] ) ) {
			$stmt->bind_param("d", $idInsc);
			$stmt->execute();
			$stmt->bind_result($any, $mes, $curs, $aula, $dataInscripcio, $nom, $cognoms,
			$correu, $dni, $adreca, $cp, $poblacio, $telefon, $obs, $perfil, $titol, $inscrit, $tipusInsc,
			$inscMailing, $apagar, $pagament, $dataPag, $idpag, $factRel, $fraccionat,
			$comHaPagat, $comentaris, $obsPag, $conegut, $motiuBaixa, $usuari,
			$perenne, $hores, $idPreu, $nomCurs, $datai, $dataf, $dniTutor);
			$stmt->fetch();

			echo $any."<br />".$mes."<br />".$curs."<br />".$aula."<br />".$dataInscripcio."<br />
			".$nom."<br />".$cognoms."<br />".$correu."<br />".$dni."<br />".$adreca."<br />
			".$cp."<br />".$poblacio."<br />".$telefon."<br />".$obs."<br />".$perfil."<br />
			".$titol."<br />".$inscrit."<br />".$tipusInsc."<br />".$inscMailing."<br />
			".$apagar."<br />".$pagament."<br />".$dataPag."<br />".$idpag."<br />
			".$factRel."<br />".$fraccionat."<br />".$comHaPagat."<br />".$comentaris."<br />
			".$obsPag."<br />".$conegut."<br />".$motiuBaixa."<br />".$usuari."<br />
			".$perenne."<br />".$hores."<br />".$idPreu."<br />".$nomCurs."<br />
			".$datai."<br />".$dataf."<br />".$dniTutor."<br />";

			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4041);
		}

		echo $any." ".$mes."<br />";
		if ( $mes == '07' && $any == '2023' ) {
			echo " possible k te promo<br />";
			$codiDecompte = "PROMOJUL#%";
			//busquem si té alguin codi de descompte dispo amb PROMOJUL#
			echo $this->consultesBD_Web["cnsSiTePromocioDispo"];
			echo $codiDecompte;
			echo $dni;
			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["cnsSiTePromocioDispo"] ) ) {
				$stmt->bind_param("ss", $codiDecompte, $dni);
				$stmt->execute();
				$stmt->store_result();
				if ( $stmt->num_rows() > 0 ) {
					echo " k te promo<br />";
					$conWeb->closeStmt();
					if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["updDataFPromocio"] ) ) {
						echo " upd promo<br />";
						$stmt->bind_param("ss", $codiDecompte, $dni);
						$stmt->execute();
					}
				}
				$conWeb->closeStmt();
			}
		}

		if ( $factRel == '' OR $factRel == null ) {
			$factRel = null;
		}

		$textCanviAlumne = "";
		$textCanviTutor = "";

		/* ###### Calculem el text del canvi segons el número de canvi ###### */
		if ( $numeroCanvi == 0 )
			$objCanvi = new Text("No compta com a canvi");
		else if ( $numeroCanvi == 1 ) {
			$objCanvi = new Text("Primer canvi");
			if ( $pagament > 0 || $apagar == 0 )
				$textCanviAlumne = "T'informem que aquest canvi es pot fer una vegada sense que hi hagi cap recàrrec.";
		}
		else if ( $numeroCanvi == 2 ) {
			$objCanvi = new Text("Darrer canvi");
			if ( $pagament > 0 || $apagar == 0 ) {
				$textCanviAlumne = "T'informem que aquest és l'últim canvi que pots fer sense cap recàrrec.";
			}
		}
		else if ( $numeroCanvi == 3 ) {
			$objCanvi = new Text("Canvi extraordinari");
			if ( $pagament > 0 || $apagar == 0 ) {
				$textCanviAlumne = "T'informem que aquest és l'últim canvi que pots fer sense cap recàrrec.";
			}
		}
		else if ( $numeroCanvi == 4 ) {
			$objCanvi = new Text("Despeses gestió");
			if ( $pagament > 0 || $apagar == 0 ) {
				$textCanviAlumne = "Et recordem que aquest canvi té un cost afegit de ".$despesesC." euros en concepte de despeses de gestió.";
			}
		}

		$objCanvi->setMaj();
		$textCanviBD = $objCanvi->get();
		if ( $textCanviAlumne != '' )
			$textCanviAlumne = "<p>".$textCanviAlumne."</p>";
		if ( $textCanviTutor != '' )
			$textCanviTutor = "<p>".$textCanviTutor."</p>";

		/* ###### Calculem el camp d'observacions per la nova inscripció ###### */
		/* ###### (observacions de l'edició antiga + el número de canvi) ###### */
		require_once 'Date.php';
		$objDataInscNoHour = new Date($dataInscripcio);
		$dataInscNoHour = $objDataInscNoHour->getDataFomatDDMMYYYY();
		if ( $obs == '' or $obs == null )
			$obs .= '';
		else
			$obs .= "/n ";
		$textObsBD = $obs."(Ve de ".$any.$curs.$mes.$aula." ".$dataInscNoHour."). ".$textCanviBD." ".$obsCanvi." ".$motiuCanvi;

		/* #### Calculem el camp del motiu de baixa per la inscripció antiga #### */
		/* #### (motiu de canvi de l'edició antiga +  el número de canvi) #### */
		if ( $motiuBaixa == '' or $motiuBaixa == null )
			$motiuBaixa = '';
		else
			$motiuBaixa .= " // ";
		$textMotiuBaixaBD = $motiuBaixa.$motiuCanvi." (Passa a ".$anyC.$cursC.$mesC."A) ".$textCanviBD;

		/* ######################## Generem el nou IDPAG ######################## */
		if ( $idpag == 0 ) {
			// Busquem l'últim id pag
			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarIdPagInsc"] ) ) {
				$stmt->execute();
				$stmt->bind_result($lastIdPag);
				$stmt->fetch();
				$conWeb->closeStmt();
			}
			else
				throw new Exception('',4042);

			$idPagBD = $lastIdPag+1;
		}
		else {
			$idPagBD = $idpag;
		}

		echo "<strong style='color: #e91e63'>###### Generem el nou IDPAG ######</strong>".$idPagBD."<br />";

		//consulta per buscar la key d'encriptacio de prisma
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarParam"] ) ) {
			$stmt->bind_param("s", $tipus);

			$tipus = 'keyEncriptar';
			$stmt->execute();
			$stmt->bind_result($keyEncr);
			$stmt->fetch();

			$tipus = 'autentificacioConsultes';
			$stmt->execute();
			$stmt->bind_result($valor);
			$stmt->fetch();

			$autentificacioConsultes = explode('|',$valor);
			$usernameCons = $autentificacioConsultes[0];
			$passwordCons = $autentificacioConsultes[1];
			$nameUserCons = $autentificacioConsultes[2];

			$tipus = 'autentificacioSecretaria';
			$stmt->execute();
			$stmt->bind_result($valor);
			$stmt->fetch();

			$autentificacioSecretaria = explode('|',$valor);
			$usernameSecre = $autentificacioSecretaria[0];
			$passwordSecre = $autentificacioSecretaria[1];
			$nameUserSecre = $autentificacioSecretaria[2];
			$conWeb->closeStmt();
		}
		else
			throw new Exception('',4036);

		$cipher = "AES-128-CBC";

		/* ############## Calculem la url de pagament del $idPagBD ############## */
		$ivlen = openssl_cipher_iv_length($cipher);
		$iv = openssl_random_pseudo_bytes($ivlen);
		$ciphertext_raw = openssl_encrypt($idPagBD, $cipher, $keyEncr, $options=OPENSSL_RAW_DATA, $iv);
		$hmac = hash_hmac('sha256', $ciphertext_raw, $keyEncr, $as_binary=true);
		$hashIdPag = base64_encode( $iv.$hmac.$ciphertext_raw );

		$urlIdPag = "https://www.prisma.cat/";

		if ( $tipusInsc == 'I' )
			$urlIdPag .= "pagament/";
		else if ( $tipusInsc == 'G' OR $tipusInsc == 'P' )
			$urlIdPag .= "pagaments/";

		$urlIdPag .= $hashIdPag;

		/* ############## Creem el text de l'opcions de pagament ############## */
		require_once 'Template.php';
		$templates = new Template();
		$msg = $templates->getTemplate_Inscripcions_Pagaments_MissatgeTextManeresPagar();
		$names_template = array("[URL_PAGAMENT]", "[TITOL]", "[CODI_CURS]", "[MES]");
		$names_function   = array($urlIdPag, $nomCurs, $cursC, $mesC);
		$textManeresPagar = str_replace($names_template, $names_function, $msg);

		// $textManeresPagar ="
		// <ul style='list-style: square; margin-bottom: 20px; margin-left: 30px; padding: 0;'>
		// 	<li style='margin-top: 8px; line-height: 24px;'>
		// 		TARGETA: clica a l'enllaç següent (cal que tinguis activat el codi
		// 		de compra segura facilitat per la teva entitat bancària):
		// 		<a href='".$urlIdPag."' title='Pagament del curs ".$nomCurs."' target='_blank'>".$urlIdPag."</a>.
		// 	</li>
		// 	<li style='margin-top: 8px; line-height: 24px;'>
		// 		TRANSFERÈNCIA o INGRÉS BANCARI: indica clarament el concepte
		// 		<strong>«".$cursC."-".$mesC."+ el número
		// 		del teu NIF/NIE/Passaport»</strong>, en qualsevol dels comptes següents:
		// 		<ul style='list-style: circle; margin-left: 30px; padding: 0;'>
		// 			<li style='margin-top: 8px; line-height: 24px;'>La Caixa: ES30 2100 4279 21 2200080678 </li>
		// 			<li style='margin-top: 8px; line-height: 24px;'>BBVA: ES04 0182 5117 00 0201534816</li>
		// 		</ul>
		// 	</li>
		// </ul>
		// <p>Un cop hagis realitzat el pagament és important que conservis el
		// justificant bancari fins que t'arribi un correu electrònic que confirmi
		// que hem rebut correctament el teu pagament.</p>";

		$textFaltaPagar = '';
		/* ########## Creem part del missatge a enviar a l'alumne ########## */
		/* ##########  Creem la part del què fa falta per pagar   ########## */
		if ( $apagarC + $despesesC > $pagatC ) { //El preu el curs varia
			if ( $pagatC == 0 ) {
				$textFaltaPagar = "<p>Actualment no hi ha cap pagament realitzat.</p>";
				$textFaltaPagar .= "<p>Et recordem que per tal de formalitzar la matrícula del nou curs, pots realitzar el pagament dels <strong>".( floatval($apagarC) + $despesesC )." euros</strong> escollint una de les opcions següents:</p>";
				$textFaltaPagar .= $textManeresPagar;
				$faccionatBD = 0;
			}
			else {
				$textFaltaPagar = "<p>Actualment hi ha pagats <strong>".$pagatC." euros</strong> del total dels <strong>".($apagarC + $despesesC)." euros</strong> corresponents a la inscripció del nou curs.</p>";
				$textFaltaPagar .= "<p>Et recordem que, per poder efectuar la resta del pagament, pots realitzar el pagament dels <strong>".( floatval($apagarC) - floatval($pagatC) + $despesesC )." euros</strong> escollint una de les opcions següents:</p>";
				$textFaltaPagar .= $textManeresPagar;
				$faccionatBD = 1;
			}
		}
		else { //El preu del curs no varia
			if ( $apagarC + $despesesC < $pagatC ) {
				$textFaltaPagar = "<p>Actualment hi ha pagats <strong>".$pagatC." euros</strong> del total dels <strong>".($apagarC + $despesesC)." euros</strong> corresponents a la inscripció del nou curs.</p>";
				$textFaltaPagar .= "<p>Et recordem que et reservem la diferència del imports per a un altre curs.</p>";
			}
			$faccionatBD = 0;
		}

		$dataInsc = date('Y')."-".date('m')."-".date('d')." ".date('H').":".date('i').":".date('s');
		$inscritNouReg = '0';

		echo $this->consultesBD_Web["insertRegInscCanvi"]."<br />";
		echo  $anyC."<br>".$mesC."<br>".$cursC."<br>".$dataInsc."<br>".$nom."<br>
		".$cognoms."<br>".$correu."<br>".$dni."<br>".$adreca."<br>".$cp."<br>".$poblacio."<br>
		".$perfil."<br>".$titol."<br>".$telefon."<br>".($apagarC+$despesesC)."<br>".$comHaPagat."<br>
		".$pagatC."<br>".$dataPag."<br>".$factRel."<br>".$inscritNouReg."<br>".$textObsBD."<br>
		".$comentaris."<br>".$obsPag."<br>".$faccionatBD."<br>".$usuari."<br>".$inscMailing."<br>
		".$conegut."<br>".$idPagBD."<br />".$tipusDesc."<br>".$validDesc."<br />";
		$conWeb2 = new ConnexioWeb();
		$conWeb2->connectarBD();
		/* ######## Inserim el nou registre a la taula d'inscrpcions ######## */
		if ( $stmt2=$conWeb2->prepare( $this->consultesBD_Web["insertRegInscCanvi"] ) ) {
			$stmt2->bind_param("dssssssssssssddsdsdsssssddssddd", $anyC, $mesC, $cursC,
			$dataInsc, $nom, $cognoms, $correu, $dni, $adreca, $cp, $poblacio,
			$perfil, $titol, $telefon, $apagarC2, $comHaPagat, $pagatC, $dataPag,
			$factRel, $inscritNouReg, $tipusInsc, $textObsBD, $comentaris, $obsPag, $faccionatBD,
			$usuari, $inscMailing, $conegut, $idPagBD, $tipusDesc, $validDesc);
			$apagarC2 = $apagarC + $despesesC;
			$stmt2->execute();
			$idInserit = $conWeb2->lastInsertId();
			$conWeb2->closeStmt();
		}
		else
			throw new Exception('',4043);
		$conWeb2->desconectarBD();

		echo "<strong style='color: #e91e63'>###### Inserim el nou registre a la taula d'inscrpcions ######</strong><br />";
		echo $idInserit;
		echo "<br />";

		$ivlen = openssl_cipher_iv_length($cipher);
		$iv = openssl_random_pseudo_bytes($ivlen);
		$ciphertext_raw = openssl_encrypt($idInserit, $cipher, $keyEncr, $options=OPENSSL_RAW_DATA, $iv);
		$hmac = hash_hmac('sha256', $ciphertext_raw, $keyEncr, $as_binary=true);
		$hashIdInserit = base64_encode( $iv.$hmac.$ciphertext_raw );

		$objInsc = new Text($inscrit);
		$objInsc->setMaj();
		$inscrit = $objInsc->get();
		echo "<strong style='color: #e91e63'>######  inscrit".$inscrit." ######</strong><br />";
		/* ######## Actualitzem el registre a la taula d'inscrpcions ######## */
		if ( $inscrit == 'X' or $inscrit == 'C' or $inscrit == '0' ) {
			//ja ha estat donat de baixa del curs o no s'ha arribat a insciur-re

			echo "<strong style='color: #e91e63'>######  Donem de baixa la inscripció de la nostre BD ######</strong><br />";
			/* ######## Donem de baixa la inscripció de la nostre BD ######## */
			$conWeb = new ConnexioWeb();
			$conWeb->connectarBD();

			$dateNow = new DateTime("now");
			$dataBaixa = $dateNow->format('Y-m-d H:i:s');

			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["updInscCanviCurs"] ) ) {
				$stmt->bind_param("sssd", $dataBaixa, $quiBaixa, $textMotiuBaixaBD, $idInsc);
				// $dataBaixa = CURRENT_TIME;
				$motiuBaixa = "Canvi de curs";
				$quiBaixa = $this->usuari->getNom()->get()." ".$this->usuari->getCognom()->get();
				$stmt->execute();
				$conWeb->closeStmt();
			}
			else
				throw new Exception('',4046);



			if ( $inscrit == 'X' or $inscrit == 'C' ) {
				/* Cal mirar si estava donat d'alta a l'aula oberta.
				Si està a l'aula oberta, cal donar-lo de baixa del Campus */
				if ( $perenne == '1' ) {
					/* Mirem si la persona està inscrita a l'aula oberta del nou moodle.
					Si ho està, la donem de baixa.
					Si no està, mirem si la persona està inscrita a l'aula oberta del moodle antic.
					Si ho està, la donem de baixa.
					Si no està, s'envia un missatge d'excepció. No pot ser que hi
					hagi un perenne == 1 i no estigui inscrit ni a l'aula oberta
					del moodle nou ni a l'aula oberta del moodle antic.*/
					echo "<strong style='color: #e91e63'>######  Donem de baixa de l'aula oberta ######</strong><br />";

					if ( !$this->__donarBaixaMoodleNou($curs, $usuari) ) {
						if ( !$this->__donarBaixaMoodleAntic($curs, $usuari) ) {
							throw new Exception('',4050);
						}
					}
				}
			}
		}
		else if ( $inscrit == 'M' or $inscrit == '1' ) {
			$dateNow = new DateTime("now");
			$dataBaixa = $dateNow->format('Y-m-d H:i:s');

			echo "<strong style='color: #e91e63'>######  Donem de baixa la inscripció de la nostre BD ######</strong><br />";
			/* ######## Donem de baixa la inscripció de la nostre BD ######## */
			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["updInscCanviCurs"] ) ) {
				$stmt->bind_param("sssd", $dataBaixa, $quiBaixa, $motiuBaixa, $idInsc);
				// $dataBaixa = CURRENT_TIME;
				$motiuBaixa = "Canvi de curs";
				$quiBaixa = $this->usuari->getNom()->get()." ".$this->usuari->getCognom()->get();
				$stmt->execute();
				$conWeb->closeStmt();
			}
			else
				throw new Exception('',4054);

			/* ######## Donem de baixa la inscripció del curs en el moodle ######## */

			/* Mirem si la persona està inscrita a l'edició del curs del nou moodle.
			Si ho està, la donem de baixa.
			Si no està, mirem si la persona està inscrita a l'edició del curs moodle antic.
			Si ho està, la donem de baixa.
			Si no està, s'envia un missatge d'excepció. No pot ser que hi
			hagi un perenne == 1 i no estigui inscrit ni a l'aula oberta
			del moodle nou ni a l'aula oberta del moodle antic.*/

			$shortname = $any.$curs.$mes.$aula;
			if ( !$this->__donarBaixaMoodleNou($shortname, $usuari) ) {
				if ( !$this->__donarBaixaMoodleAntic($shortname, $usuari) ) {
					// throw new Exception('',4061);
				}
			}

			if ( $perenne == '1' ) {
				/* ### Donem de baixa la inscripció de l'aula oberta del moodle ### */
				/* Mirem si la persona està inscrita a l'aula oberta del nou moodle.
				Si ho està, la donem de baixa.
				Si no està, mirem si la persona està inscrita a l'aula oberta del moodle antic.
				Si ho està, la donem de baixa.
				Si no està, s'envia un missatge d'excepció. No pot ser que hi
				hagi un perenne == 1 i no estigui inscrit ni a l'aula oberta
				del moodle nou ni a l'aula oberta del moodle antic.*/

				echo "<strong style='color: #e91e63'>######  Donem de baixa de l'aula oberta ######</strong><br />";

				if ( !$this->__donarBaixaMoodleNou($curs, $usuari) ) {
					if ( !$this->__donarBaixaMoodleAntic($curs, $usuari) ) {
						throw new Exception('',4069);
					}
				}
			}

			/* ########### Enviem missatge al tutor de confirmació ########### */
			/* Si el curs ha acabat i no han passat els 15 dies,
			enviem missatge al tutor de confirmació */
			echo "<strong style='color: #e91e63'>######  Enviem missatge al tutor de confirmació ######</strong><br />";

			$date1 = new DateTime("now");
			$date2 = new DateTime($dataf);
			$diff = $date1->diff($date2);

			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarPersonal"] ) ) {
				$stmt->bind_param("s", $dniTutor);
				$stmt->execute();
				$stmt->store_result();
