			$objDataF = new Date($dataf);
			$dataFLlarga = $objDataF->getDataLlarga();
			$objDataCanviI = new Date($dataiCanvi);
			$dataICanviLlarga = $objDataCanviI->getDataLlarga();
			$objDataCanviF = new Date($datafCanvi);
			$dataFCanviLlarga = $objDataCanviF->getDataLlarga();

			$datesIniciFi = "<strong>".$this->__mostrarDatesIniciFi($datai, $dataf)."</strong>";
			$datesIniciFiCanvi = "<strong style='color: ".$this->colors_destacats["msgDestacatCorreu1"]."'>".$this->__mostrarDatesIniciFi($dataiCanvi, $datafCanvi)."</strong>";

