	/* ---------------------------- Donar de baixa ----------------------------- */

	/**
   * @brief Mostra un modal amb l'estructura per representar el donar de baixa d'una inscripció
   * @return Mostra un modal amb l'estructura per representar el donar de baixa d'una inscripció
   */
	private function __modalDonarBaixa_resultatCerca() {
		$mostrar = "
		<div class='modal fade in' id='modalDonarBaixa' tabindex='-1' role='dialog'
		aria-labelledby='modalDonarBaixaTitle' style='display: none;' aria-hidden='true'>
			<div class='modal-dialog modal-dialog-centered modal-notify modal-scroll modal-info' role='document'>
				<div class='modal-content w-100 p-4 mh-100 ps2'>
					<div class='modal-header border-0 d-flex justify-content-center align-items-center position-relative p-0'>
						<p class='modal-title font-weight-bold text-center'></p>
						<button type='button' class='close' data-bs-dismiss='modal'>×</button>
					</div>
					<div class='modal-body p-0 text-center'></div>
					<div class='modal-footer border-0 d-flex align-items-center justify-content-center p-0'>
						<a role='button' class='btn btn-info confirma-baixa' aria-label='Confirma la baixa'>Confirma la baixa</a>
					</div>
				</div>
			</div>
		</div>";
		return $mostrar;
	}

	/**
   * @brief Mostra el contingut de donar de baixa d'una inscripció em el modal d'inscripcio
   * @return Mostra el contingut de donar de baixa d'una inscripció em el modal d'inscripcio
   */
	public function modalDonarBaixa_resultatCerca( $idInsc) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		/* ############## Busquem la informacio de la inscripcio ############## */
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarDadesBaixaInsc"] ) ) {
			$stmt->bind_param("d", $idInsc);
			$stmt->execute();
			$stmt->bind_result($any, $mes, $curs, $aula, $apagar, $pagament, $usuari,
			$inscrit, $perenne, $nom, $correu);
			echo $any;
			$stmt->fetch();
