	/**
   * @brief Dona de baixa el registre $idInsc
   * @return Dona de baixa el registre $idInsc amb el motiu de baixa $motiu de
	* baixa i envia un correu a l'alumne si $noEnviarCoreu=="false"
   */
	public function confirmaBaixa_modalDonarBaixa( $idInsc, $motiuBaixa, $noEnviarCoreu ) {
		$mostrar = "confirma baixa";
		$motiuBaixa2 = '';

		$sendCoreu = 0;
		if ( $noEnviarCoreu == "false" ) $sendCoreu = 1;

		$conWeb = new ConnexioWeb();
