		/* ############## Busquem la informacio de la inscripcio ############## */
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarDadesBaixaInsc"] ) ) {
			$stmt->bind_param("d", $idInsc);
			$stmt->execute();
			$stmt->bind_result($any, $mes, $curs, $aula, $apagar, $pagament, $usuari,
			$inscrit, $perenne, $nom, $correu);
			$stmt->fetch();
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4117);
		}

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarParam"] ) ) {
			$stmt->bind_param("s", $tipus);

			$tipus = 'autentificacioConsultes';
			$stmt->execute();
			$stmt->bind_result($valor);
			$stmt->fetch();

			$autentificacioConsultes = explode('|',$valor);
			$usernameCons = $autentificacioConsultes[0];
			$passwordCons = $autentificacioConsultes[1];
			$nameUserCons = $autentificacioConsultes[2];

			$tipus = 'autentificacioSecretaria';
			$stmt->execute();
			$stmt->bind_result($valor);
			$stmt->fetch();

			$autentificacioSecretaria = explode('|',$valor);
			$usernameSecre = $autentificacioSecretaria[0];
			$passwordSecre = $autentificacioSecretaria[1];
			$nameUserSecre = $autentificacioSecretaria[2];

			$conWeb->closeStmt();
		}
		else
			throw new Exception('',4329);

		if ( $inscrit == '1' )  {
			$shortname = $any.$curs.$mes.$aula;
			if ( !$this->__donarBaixaMoodleNou($shortname, $usuari) ) {
				if ( !$this->__donarBaixaMoodleAntic($shortname, $usuari) ) {
					// throw new Exception('',4118);
				}
			}
			if ( $perenne == '1' ) {
				if ( !$this->__donarBaixaMoodleNou($curs, $usuari) ) {
					if ( !$this->__donarBaixaMoodleAntic($curs, $usuari) ) {
						throw new Exception('',4119);
					}
				}
			}

			/* ########### Enviem missatge al tutor de confirmació ########### */
			/* Si el curs ha acabat i no han passat els 15 dies,
			enviem missatge al tutor de confirmació */
			echo "<strong style='color: #e91e63'>######  Enviem missatge al tutor de confirmació ######</strong><br />";
			echo $this->consultesBD_Web["buscarInfoInscCurs"]." ".$idInsc."<br />";

			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarInfoInscCurs"] ) ) {
				$stmt->bind_param("d", $idInsc);
				$stmt->execute();
				$stmt->store_result();
				if ($stmt->num_rows() > 0) {
					$stmt->bind_result($any, $mes, $curs, $aula, $dataInscripcio, $nom, $cognoms,
					$correu, $dni, $adreca, $cp, $poblacio, $telefon, $obs, $perfil, $titol, $inscrit, $tipusInsc,
					$inscMailing, $apagar, $pagament, $dataPag, $idpag, $factRel, $fraccionat,
					$comHaPagat, $comentaris, $obsPag, $conegut, $motiuBaixa2, $usuari,
					$perenne, $hores, $idPreu, $nomCurs, $datai, $dataf, $dniTutor);
					$stmt->fetch();
				}
				else
					throw new Exception('',4155);
				$conWeb->closeStmt();
			}
			else
				throw new Exception('',4156);

			$date1 = new DateTime("now");
			$date2 = new DateTime($dataf);
			$diff = $date1->diff($date2);

			echo "enviem un missatge al tutor1<br />";

			if ( $mes == '07' && $any == '2023' ) {
				$codiDecompte = "PROMOJUL#?";
				//busquem si té alguin codi de descompte dispo amb PROMOJUL#
				if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["cnsSiTePromocioDispo"] ) ) {
					$stmt->bind_param("ss", $codiDecompte, $dni);
					$stmt->execute();
					$stmt->store_result();
					if ( $stmt->num_rows() > 0 ) {
						$conWeb->closeStmt();
						if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["updDataFPromocio"] ) ) {
							$stmt->bind_param("ss", $codiDecompte, $dni);
							$stmt->execute();
						}
					}
					$conWeb->closeStmt();
				}
			}

			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarPersonal"] ) ) {
				$stmt->bind_param("s", $dniTutor);
				$stmt->execute();
				$stmt->store_result();
				if ($stmt->num_rows() > 0) {
					$stmt->bind_result($nomTutor, $cognomsTutor, $mailPrsimaTutor, $mailTutor);
					$stmt->fetch();

					echo $diff->invert == 0;
					echo ($diff->invert==1 && $diff->days <= 15 );

					if ( $diff->invert == 0 || ($diff->invert==1 && $diff->days <= 15 ) ) {
						$to = $mailPrsimaTutor;

						echo "enviem un missatge al tutor2<br />";
						echo $to;

						$subject = "Baixa d'un alumne/a: ".$nom." ".$cognoms;

						$objDataI = new Date($datai);
						$dataLlargaInici = $objDataI->getDataLlarga();

						$missatge = "<p>Hola ".$nomTutor.",</p>
						<p>T'informem que l'alumne/a <strong>".$nom." ".$cognoms."</strong>
						s'ha donat de baixa del curs <strong style='color: ".$this->colors_destacats["msgDestacatCorreu1"]."'>".$nomCurs." - Aula ".$aula."</strong>
						que comença ".$objDataI->getPronomEl()."<strong>".$objDataI->getDataLlarga()."</strong>.</p>";
						$missatge .= "<p>Salutacions,</p>";

						$qui = $this->usuari->getNom()->get()." ".$this->usuari->getCognom()->get();
						$depart = $this->usuari->getDepart()->get();

						require_once "MailSMTPComvive.php";

						$nomFromHead = $nameUserCons;
						$correuFromHead = $usernameCons;
						$nomReplyHead = $nameUserCons;
						$correuReplyHead = $usernameCons;

						$nomTo = "PrisMa Secretaria";
						$correuTo = "resguard.secretaria@prisma.cat";

						//enviar un email  de confirmacio a la persona que ha fet la compra
						$mailAlumne = new MailSMTPComvive($usernameCons, $passwordCons, $nomFromHead, $correuFromHead,
															$nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
															$subject, $missatge, $qui, $depart);

						$nomTo = $nomTutor;
						$correuTo = $to;
						// $correuTo = "merimari051094@gmail.com";

						//enviar un email  de confirmacio a la persona que ha fet la compra
						$mailAlumne = new MailSMTPComvive($usernameCons, $passwordCons, $nomFromHead, $correuFromHead,
															$nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
															$subject, $missatge, $qui, $depart);
					}

				}
				else //no existeix el tutor/a a la taula personal
					throw new Exception('',4071);
				$conWeb->closeStmt();
			}
			else
				throw new Exception('',4070);

		}

		$this->__donarBaixaRegistreInscripcions($idInsc, $motiuBaixa2." ".$motiuBaixa);

		if ( $sendCoreu ) {
			/* ############## Busquem les dades de l'edició ############## */
			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarCursSegEd"] ) ) {
				$stmt->bind_param("dss", $any, $mes, $curs);
				$stmt->execute();
				$stmt->store_result();
				if ($stmt->num_rows() > 0) {
					$stmt->bind_result($titol, $datai, $dataf, $hores, $idPreu);
					$stmt->fetch();
					$conWeb->closeStmt();
				}
				else {
					$conWeb->closeStmt();
					if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarJorSegEd"] ) ) {
						$stmt->bind_param("dss", $any, $mes, $curs);
						$stmt->execute();
						$stmt->store_result();
						if ($stmt->num_rows() > 0) {
							$stmt->bind_result($titol, $datai, $dataf, $hores, $idPreu);
							$stmt->fetch();
							$conWeb->closeStmt();
						}
						else {
							$conWeb->closeStmt();
						}
					}
					else {
						throw new Exception('',4157);
					}
				}
			}
			else {
				throw new Exception('',4120);
			}

			$objDataI = new Date($datai);
			$dataILlarga = $objDataI->getDataLlarga();

			$dateNow = new DateTime("now");
			$dataAct = $dateNow->format('d-m-Y H:i');

			$subject = "Confirmació de baixa de curs";
			$subjectCopiaResguard = "Confirmació de baixa de curs ".$dataAct;

			if ( $pagament > 0 ) {
				$textPag = "<p>Si el vols fer més endavant, pots enviar-nos un correu a
				<strong style='color: ".$this->colors_destacats["msgDestacatCorreu1"]."; text-decoration: none'>
				secretaria@prisma.cat</strong> a través del teu correu electrònic
				<strong style='color: ".$this->colors_destacats["msgDestacatCorreu1"]."; text-decoration: none'>
				".$correu."</strong> per traspassar l'import de
				<strong style='color: ".$this->colors_destacats["msgDestacatCorreu1"]."'>
				".$pagament." euros</strong> a una nova edició.</p>";
			}
			else {
				$textPag = "<p>Si el vols fer més endavant, pots enviar-nos un correu a
				<strong style='color: ".$this->colors_destacats["msgDestacatCorreu1"]."; text-decoration: none'>
				secretaria@prisma.cat</strong> a través del teu correu electrònic
				<strong style='color: ".$this->colors_destacats["msgDestacatCorreu1"]."; text-decoration: none'>
				".$correu."</strong> o bé realitzar un altre cop la inscripció.</p>";
			}

			$retrobar = "";
			/* ############## Busquem si la persona està fent algun curs ##############
				##############    més amb nosaltres que acabi més tard    ############## */
			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarSiTeCursFutur"] ) ) {
				$stmt->bind_param("d", $usuari);
				$stmt->execute();
				$stmt->store_result();
				if ($stmt->num_rows() > 0)
					$retrobar = " i esperem retrobar-te aviat";
				$conWeb->closeStmt();
			}
			else {
				throw new Exception('',4121);
			}

			$missatge = "<p>Benvolgut/da ".$nom.",</p>
			<p>Et confirmem que t'hem donat de baixa del curs
			<strong style='color: ".$this->colors_destacats["msgDestacatCorreu1"]."'>
			".$titol."</strong> amb data d'inici ".$objDataI->getPronomEl()."<strong>".$objDataI->getDataLlarga()."</strong>.</p>
			".$textPag."
			<p>Aprofitem per saludar-te ben cordialment".$retrobar.",</p>";

			$qui = $this->usuari->getNom()->get()." ".$this->usuari->getCognom()->get();
			$depart = $this->usuari->getDepart()->get();

			$nomFromHead = $nameUserSecre;
			$correuFromHead = $usernameSecre;
			$nomReplyHead = $nameUserSecre;
			$correuReplyHead = $usernameSecre;

			require_once "MailSMTPComvive.php";

			$nomTo = "PrisMa Secretaria";
			$correuTo = "resguard.secretaria@prisma.cat";

			//enviar un email de confirmacio a gestio@prisma.cat
			$mailCopiaResguard = new MailSMTPComvive($usernameSecre, $passwordSecre, $nomFromHead, $correuFromHead,
												$nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
												$subjectCopiaResguard, $missatge, $qui, $depart);

			$nomTo = $nameUserSecre;
			$correuTo = 'inscripcions@prisma.cat';

			//enviar un email de confirmacio a gestio@prisma.cat
			$mailInscripcions = new MailSMTPComvive($usernameSecre, $passwordSecre, $nomFromHead, $correuFromHead,
												$nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
