	/**
   * @brief Donem de baixa la inscripció idInsc de la nostre BD
   * @return Donem de baixa la inscripció idInsc de la nostre BD
   */
	private function __donarBaixaRegistreInscripcions( $idInsc, $motiuBaixa ) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		$dateNow = new DateTime("now");
		$dataBaixa = $dateNow->format('Y-m-d H:i:s');

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["updInscBaixaCurs"] ) ) {
			$stmt->bind_param("sssd", $dataBaixa, $quiBaixa, $motiuBaixa, $idInsc);
			// $dataBaixa = CURRENT_TIME;
			$quiBaixa = $this->usuari->getNom()->get()." ".$this->usuari->getCognom()->get();
			$stmt->execute();
			$conWeb->closeStmt();
		}
		else
			throw new Exception('',4046);

		$conWeb->desconectarBD();
	}

	/**
   * @brief Donem de baixa la inscripció del moodle nou
   * @return Donem de baixa la inscripció del moodle nou
   */
	private function __donarBaixaMoodleNou( $curs, $usuari ) {
		$conMoodle = new ConnexioMoodle();
		$conMoodle->connectarBD();

		$existeix = false;
		if ( $stmt=$conMoodle->prepare( $this->consultesBD_Moodle["buscarUsuariMoodle"] ) ) {
			$stmt->bind_param("ss", $curs, $usuari);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($idUserEnrolments);
				$stmt->fetch();
				$conMoodle->closeStmt();
				echo "<strong style='color: #e91e63'>###### Existeix l'usuari del curs ".$curs." al moodle nou ######</strong><br />";

				if ( $stmt=$conMoodle->prepare( $this->consultesBD_Moodle["deleteMdlUserEnrol"] ) ) {
					$stmt->bind_param("s", $idUserEnrolments);
					$stmt->execute();
					$stmt->store_result();
					echo "<strong style='color: #e91e63'>######  Donem de baixa del user enrolments la id ".$idUserEnrolments." ######</strong><br />";
					$conMoodle->closeStmt();
				}
				else
					throw new Exception('',4048);

				if ( $stmt=$conMoodle->prepare( $this->consultesBD_Moodle["deleteMdlRoleAssig"] ) ) {
					$stmt->bind_param("ss", $curs, $usuari);
					$stmt->execute();
					echo "<strong style='color: #e91e63'>######  Donem de baixa del role assigments la id ".$idUserEnrolments." ######</strong><br />";
					$conMoodle->closeStmt();
				}
				else
					throw new Exception('',4049);

				$existeix = true;
			}
			else {
				$conMoodle->closeStmt();
			}
		}
		else
			throw new Exception('',4047);

		$conMoodle->desconectarBD();

		return $existeix;
	}

	/**
   * @brief Donem de baixa la inscripció del moodle antic
   * @return Donem de baixa la inscripció del moodle antic
   */
	private function __donarBaixaMoodleAntic( $curs, $usuari ) {
		$conMoodleAntic = new ConnexioMoodleAntic();
		$conMoodleAntic->connectarBD();

		$existeix = false;
		if ( $stmt=$conMoodleAntic->prepare( $this->consultesBD_MoodleAntic["buscarUsuariMoodle"] ) ) {
			$stmt->bind_param("ss", $curs, $usuari);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($idUserEnrolments);
				$stmt->fetch();
				$conMoodleAntic->closeStmt();

				echo "<strong style='color: #e91e63'>###### Existeix l'usuari del curs ".$curs." al moodle antic ######</strong><br />";

				if ( $stmt=$conMoodleAntic->prepare( $this->consultesBD_MoodleAntic["deleteMdlUserEnrol"] ) ) {
					$stmt->bind_param("s", $idUserEnrolments);
					$stmt->execute();
					$stmt->store_result();
					echo "<strong style='color: #e91e63'>######  Donem de baixa del user enrolments la id ".$idUserEnrolments." ######</strong><br />";
					$conMoodleAntic->closeStmt();
				}
				else
					throw new Exception('',4051);

				if ( $stmt=$conMoodleAntic->prepare( $this->consultesBD_MoodleAntic["deleteMdlRoleAssig"] ) ) {
					$stmt->bind_param("ss", $curs, $usuari);
					$stmt->execute();
					echo "<strong style='color: #e91e63'>######  Donem de baixa del role assigments la id ".$idUserEnrolments." ######</strong><br />";
					$conMoodleAntic->closeStmt();
				}
				else
					throw new Exception('',4052);

				$existeix = true;
			}
			else {
				// throw new Exception('',4053);
			}
		}

		$conMoodleAntic->desconectarBD();
		return $existeix;
	}

