	/**
   * @brief Mostra el contingut de consulta una factura d'una inscripció em el modal d'inscripcio
   * @return Mostra el contingut de consulta una factura d'una inscripció em el modal d'inscripcio
   */
	public function modalConsultaFactura_resultatCerca($idInsc) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarFactura"] ) ) {
			$stmt->bind_param("d", $idInsc);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($factura);
				$stmt->fetch();
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('', 4125);
		}

		$mostrar = $this->generaFactura($factura, false);
		$mostrar .= $this->__mostrarInput(1,"hide","ID", "active", "factura-relacionada-fact", "no-edit", $factura);

		$conWeb->desconectarBD();

		return $mostrar;
	}

	/**
	* @brief Retorna l'HTML de la factura $factura
	* @return Retorna l'HTML de la factura $factura segons si s'ha de visualitzar per
	* pantalla o s'ha de descarregar. Si $descarrega = true, significa que s'ha de descarregar
	*/
	public function generaFactura($factura, $descarrega) {
		if ( $descarrega ) {
			$widthPantalla = "width: 700px; margin: 0 auto;";
			$mostrar = "<html><head>
				<style>
					html {
						margin: 0;
					}
					body {
						margin: 20mm 8mm 2mm 8mm;
					}
				</style>
			</head><body>";
		}
		else {
			$widthPantalla = "width: 100%;";
		}

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		$mostrar = "";

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarInfoFactura"] ) ) {
			$stmt->bind_param("d", $factura);
			$stmt->execute();
			$stmt->store_result();
			$i = 0;
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($id, $any, $ordre, $num, $data, $dataPagament,
				$generada, $rao, $cif, $adreca, $cp, $poblacio, $concepte1, $concepte2,
				$import, $entitat, $curs, $hores, $observacions);
				while ( $stmt->fetch() ) {
					/* Construim les dades de la factura de Prisma */
					$dadesFacturaPrisma = "";
					if ( $generada != null && $generada != '' ) {
						$dadesFacturaPrisma .= "<div style='vertical-align:bottom !important;
						color: #597bb8; font-weight:bold;'>ÉS CÒPIA</div>";
					}
					$dadesFacturaPrisma .= "Número factura: ".$num."<br />";

					$dataForm = date_create($data);
					$dataForm = date_format($dataForm, 'd/m/Y');
					$dadesFacturaPrisma .= "Data d'emissió: ".$dataForm."<br />";

					/* Construim les dades del pagador */
					$dadesFacturaPagador = "";

					if ( $rao!= '' ) {
						$objRao = new Text($rao);
						$objRao->setMaj();
						$dadesFacturaPagador .= "<strong>".$objRao->get()."</strong><br />";
					}
					if ( $cif!= '' ) {
						$objCif = new Text($cif);
						$objCif->setMaj();
						$dadesFacturaPagador .= $objCif->get()."<br />";
					}
					if ( $adreca!= '' ) {
						$objAdreca = new Text($adreca);
						$objAdreca->setMaj();
						$dadesFacturaPagador .= $objAdreca->get()."<br />";
					}
					if ( $cp!= '' or $poblacio!='' ) {
						$cpPobl = $cp." ".$poblacio;
						$objPobl = new Text($cp." ".$poblacio);
						$objPobl->setMaj();
						$dadesFacturaPagador .= $objPobl->get()."<br />";
					}

					$visible = "";
					/* Si no és la primera pàgina i no s'ha de descarregar, no s'ha de veure la factura */
					if ( !$descarrega && $i>0 )
						$visible = 'display: none;';

					$mostrar .= "<div style='".$widthPantalla." font-family:Calibri,
					Arial, Helvetica, sans-serif; text-align: justify; ".$visible."' id='pagina-factura".($i+1)."'>
						<table style='border: none; width: 100%'>
							<tr>
								<td style='width: 40%'>
									<img src='https://intranet.prisma.cat/img/logo_factura.png' border='0' />
								</td>
								<td style='width:60%'>&nbsp;</td>
							</tr>
							<tr>
								<td colspan='2' style='height:20px'>&nbsp;</td>
							</tr>
							<tr>
								<td style='vertical-align:bottom !important; width:40%;'>".$dadesFacturaPrisma."</td>
								<td style='border:1px solid #597bb8;
								vertical-align:top !important; width:60%; padding:10px;'>".$dadesFacturaPagador."</td>
							</tr>
						</table>
						<table style='border: none; width: 100%; margin-top: 20px; border-collapse: collapse;'>
							<thead>
								<tr>
									<th style='width:80%; border:1px solid #597bb8; padding:10px; text-align:center;'>
										CONCEPTE
									</th>
									<th style='width:20%; border:1px solid #597bb8; padding:10px; text-align:center;'>
										IMPORT
									</th>
								</tr>
							</thead>
							<tbody>
								<tr>
									<td style='width:80%; height:300px; vertical-align:top !important;
									border-left:1px solid #597bb8; border-right:1px solid #597bb8;
									border-bottom:1px solid #597bb8; padding:50px 10px;'>
										<p>".$concepte1."</p>

										<p style='padding-top:50px;'>".$concepte2."</p>

									</td>
									<td style='width:20%; vertical-align:top !important; padding:50px 10px;
									border-right:1px solid #597bb8; border-bottom:1px solid #597bb8; text-align:center;'>
										<p>".$import." €</p>
									</td>
								</tr>
								<tr>
									<td colspan='2' style='height:50px'>&nbsp;</td>
								</tr>
								<tr>
									<td style='border-top:1px solid #597bb8; border-left:1px solid #597bb8; width:80%;'>&nbsp;</td>
									<td style='width:20%; border:1px solid #597bb8; padding:10px; text-align:center;'>
										TOTAL
									</td>
								</tr>
								<tr>
									<td style='width:80%; border:1px solid #597bb8; padding:10px;'>
										<p style='font-size:10px;'>Factura exempta d'IVA d'acord amb l'article 20.1.9 de la Llei 37/1992, de 28 de desembre, de l'Impost sobre el Valor Afegit (formació i reciclatge professionals realitzats per entitats privades autoritzades per a l'exercici de les activitats).</p>
									</td>
									<td style='width:20%; padding:10px; border-right:1px solid #597bb8;
									border-bottom:1px solid #597bb8; text-align:center;'>
										".$import." €
									</td>
								</tr>
								<tr>
		                  	<td colspan='2'>
		                      	<p style='text-align:center; color:#597bb8; margin-top:40px; font-size:12px'>
		                             Associació per al Desenvolupament Infantil i Familiar PrisMa<br />
		                             G17881988 &middot; C. Sant Hipòlit, 16, bxs. 2a - 17003 GIRONA &middot; 972 21 75 65 &middot; www.prisma.cat
		                         </p>
		                      </td>
		                  </tr>
							</tbody>
						</table>
					</div>
					<hr style='page-break-after: always; border: 0; margin: 0; padding: 0;'>";
					$i++;
				}
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('', 4126);
		}

		if ( $descarrega ) {
			$mostrar .= "</body></html>";

			$fecha = new DateTime();
			$tmp = $fecha->getTimestamp();

			if ( $generada == null || $generada == '' ) {
				/* Actualitzar GENERAT a la taula factures */
				if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["updGeneratFactura"] ) ) {
					$stmt->bind_param("ss", $dataGenerada, $num);
					$date = new DateTime( "now" );
					$dataGenerada = date_format($date, 'Y-m-d');
					$stmt->execute();
					$conWeb->closeStmt();
				}
				else
					throw new Exception('',4127);
			}

			//generar PDF
			$options = new \Dompdf\Options();
			$options->set('isRemoteEnabled', true);
			$dompdf = new \Dompdf\Dompdf($options);
			$dompdf->set_paper("A4", "portrait");
			$dompdf->load_html($mostrar);
			$dompdf->render();
			$pdf = $dompdf->output();
			$filename = "A".$any."-".$ordre."-".$tmp.".pdf";
			file_put_contents($filename, $pdf);

			$mostrar = $filename;
		}
		else {
			if ( $i>1 ) {
				$mostrar .= "<div class='d-flex mt-2 justify-content-center align-items-center'>
					<div class='d-flex justify-content-center align-items-center'>
						<i class='material-icons ml-1 fletxa-left pointer'>arrow_left</i>
						<div class='d-flex justify-content-center align-items-center'>
							Pàgina <strong id='factura-pagina-actual' class='ml-1'>1</strong>/<strong id='factura-num-pagines'>".$i."</strong>
						</div>
						<i class='material-icons ml-1 fletxa-right pointer'>arrow_right</i>
					</div>
				</div>";
			}
		}
		$conWeb->desconectarBD();

		return $mostrar;
	}

	/* -------------------------- Consultar certificat  -------------------------- */

	/**
   * @brief Mostra un modal amb l'estructura per representar el certificat d'una inscripció
   * @return Mostra un modal amb l'estructura per representar el certificat d'una inscripció
   */
	private function __modalConsultaCertificat_resultatCerca() {
		$mostrar = "
		<div class='modal fade in' id='modalConsultaCertificat' tabindex='-1' role='dialog'
		aria-labelledby='modalConsultaCertificatTitle' style='display: none;' aria-hidden='true'>
			<div class='modal-dialog modal-dialog-centered modal-notify modal-scroll modal-info' role='document'>
				<div class='modal-content w-100 p-4 mh-100 ps2'>
					<div class='modal-header border-0 d-flex justify-content-center align-items-center position-relative p-0'>
						<p class='modal-title font-weight-bold text-center'></p>
						<button type='button' class='close' data-bs-dismiss='modal'>×</button>
					</div>
					<div class='modal-body p-0 text-center'></div>
					<div class='modal-footer border-0 d-flex align-items-center justify-content-center p-0'>
						<a role='button' class='btn btn-info download-certificat' aria-label='Descarrega certificat'>Descarrega</a>
					</div>
				</div>
			</div>
