	/**
   * @brief Mostra el contingut de consulta d'un certificat d'una inscripció em el modal d'inscripcio
   * @return Mostra el contingut de consulta d'un certificat d'una inscripció em el modal d'inscripcio
   */
	public function modalConsultaCertificat_resultatCerca($idInsc, $tipus) {
		// $tipus = "DIGITAL";

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarInfoCert"] ) ) {
			$stmt->bind_param("d", $idInsc);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($nomCurs, $any, $curs, $mes, $aula, $hores, $gtaf, $fiss,
				$cursEscolar, $datai, $dataf, $dataRes, $certificat, $nom, $cognoms, $dni, $obsCert);
				$stmt->fetch();
				$pdfCertificat = $this->generaCertificat($idInsc, $tipus, false);
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('', 4131);
		}

		if ( $tipus == "INSCRIT" ) {
			$botons = "<button id='prev-inscrit' class='boto-certificat marcat'>Cursant el curs</button>";
		}
		else {
			$botons = "<button id='prev-digital' class='boto-certificat marcat mr-2'>Digital</button>
			<button id='prev-paper' class='boto-certificat mr-2'>Paper</button>
			<button id='prev-sobre' class='boto-certificat mr-2'>Sobre</button>";
		}

		$mostrar = "<div id='dades-certificat' class='d-flex flex-column justify-content-center align-items-center'>
			<div class='loading-wrapper hide'><div class='loading-content'></div></div>
			<div class='destacat-blau d-flex flex-column justify-content-center
				align-items-center mt-3 mb-2 py-3 w-100'>
				".$this->__mostrarInput(1,"hide","ID", "active", "id-insc-certificat", "no-edit", $idInsc)."
				<div class='apartat d-flex flex-column flex-md-row align-items-center
				justify-content-center w-100 my-2'>
					<div class='mr-3'>Certificat:</div>
					".$botons."
				</div>
			</div>
			<div id='print-certificat' class='w-100'>".$pdfCertificat."</div>
		</div>";

		$conWeb->desconectarBD();

		return $mostrar;
	}

	/**
	* @brief Retorna l'HTML del certificat de la inscripció $idInsc segons si
	* s'ha de visualitzar per pantalla o s'ha de descarregar i el tipus.
	* @return Retorna l'HTML del certificat indicant que l'alumne $nom $cognoms
	* amb DNI $dni ha superat el curs $nomCurs de $hores hores que s'ha realitzat
	* des de la data d'inici $datai fins la data de fi $dataf.
	* Si GTAF != null i GTAF != '', indiquem que el curs té el codi GTAF
	* $gtaf / $cursEscolar amb data de resolució $dataRes.
	* Si FISS != null i FISS != '', indiquem que el curs té el codi FISS $fiss.
	* Si $tipus = DIGITAL, significa que el certificat ha d'estar firmat per l'Adam
	* Si $tipus = PAPER, significa que el certificat ha d'estar firmat per en Pablo
	* Si $tipus = SOBRE, retorna un sobre amb les dades de l'alumne
	* Si $descarrega = true, significa que s'ha de descarregar
	*/
	public function generaCertificat($idInsc, $tipus, $descarrega) {
		$mostrar = "";
		$objTipus = new Text($tipus);
		$objTipus->setMaj();
		$tipus = $objTipus->get();

		if ( $tipus == 'DIGITAL' || $tipus == 'PAPER' || $tipus == 'APROFITAMENT' || $tipus == 'INSCRIT' ) {
			if ( $descarrega ) {
				$widthPantalla = "width: 550px; max-width: 700px; margin: 0 auto; font-size: 14px;";
				$mostrar = "<html><head>
					<style>
						html {
							margin: 0;
						}
						body
						{
							margin: 0 7mm;
						}
					</style>
				</head><body>";
			}
			else {
				$widthPantalla = "width: 100%; max-width: 760px; font-size: 0.96rem; ";
			}
		}
		else if ( $tipus == 'SOBRE' ) {
			if ( $descarrega ) {
				$widthPantalla = "width: 638px; margin: 0 auto; font-size: 14px; text-align: justify;";
				$mostrar = "<html><head>
					<style>
						html {
							margin: 0;
						}
						body
						{
							margin: 60mm 8mm 0mm 120mm;
						}
					</style>
				</head><body>";
			}
			else {
				$widthPantalla = "width: 100%; max-width: 638px;
				margin: 30mm 8mm 20mm 0; font-size: 0.96rem; text-align: right;";
			}
		}

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();
		$conWeb2 = new ConnexioWeb();
		$conWeb2->connectarBD();

		if (  $tipus == 'DIGITAL' || $tipus == 'PAPER' || $tipus == 'APROFITAMENT' || $tipus == 'INSCRIT' ) {

			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarInfoCert"] ) ) {
				$stmt->bind_param("d", $idInsc);
				$stmt->execute();
				$stmt->store_result();
				if ($stmt->num_rows() > 0) {
					$stmt->bind_result($nomCurs, $any, $curs, $mes, $aula, $hores, $gtaf, $fiss, $cursEscolar,
					$datai, $dataf, $dataRes, $certificat, $nom, $cognoms, $dni, $obsCert);
					$stmt->fetch();

					$tipusCurs = 'X';

					//busquem el tipus del curs
					if ( $stmt2=$conWeb2->prepare( $this->consultesBD_Web["cnsTipusCursnfo"] ) ) {
						$stmt2->bind_param("s", $curs);
						$stmt2->execute();
						$stmt2->store_result();
						if ($stmt2->num_rows() > 0) {
							$stmt2->bind_result($tipusCurs);
							$stmt2->fetch();
						}
						$conWeb2->closeStmt();
					}
					else {
						throw new Exception('', 4131);
					}
					// si el curs és subvencionat.
					if ( $tipusCurs == 'S' ) {
						//busquem el curs gtaf d'aquest curs
						if ( $stmt2=$conWeb2->prepare( $this->consultesBD_Web["cnsGtafsSubv"] ) ) {
							$stmt2->bind_param("dsss", $any, $mes, $curs, $aula);
							$stmt2->execute();
							$stmt2->store_result();
							if ($stmt2->num_rows() > 0) {
								$stmt2->bind_result($gtaf);
								$stmt2->fetch();
							}
							$conWeb2->closeStmt();
						}
						else {
							throw new Exception('', 4131);
						}
					}
					else {
						if ( $stmt2=$conWeb2->prepare( $this->consultesBD_Web["buscarCodiGtaf"] ) ) {
					      $stmt2->bind_param("dsss", $any, $mes, $curs, $aula);
					      $stmt2->execute();
					      $stmt2->store_result();
					      if ($stmt2->num_rows() > 0) {
					         $stmt2->bind_result($gtaf, $dataRes, $dataValGtaf);
					         $stmt2->fetch();
					      }
					      $conWeb2->closeStmt();
					   }
					   else {
					      throw new Exception('', 4131);
					   }
					}

					/* Construim les dates llargues */
					$objDataI = new Date($datai);
					$dataLlargaInici = $objDataI->getDataLlarga();
					$objDataF = new Date($dataf);
					$dataLlargaFi = $objDataF->getDataLlarga();
					$objDataRes = new Date($dataRes);
					$dataLlargaRes = $objDataRes->getDataLlarga();

					/* Construim nom del curs en majúscules */
					$objNomCurs = new Text($nomCurs);
					$objNomCurs->setMaj();

					/* Construim el dia, el mes i l'any actual */
					$objData = new Date("now");
					$anyActual = $objData->getAny();
					$nomMesActual = $objData->getNomMes();
					$diaActual = $objData->getDia();

					/* Construim el text de la firma */
					$classBackground = "";
					if ( $tipus == 'DIGITAL' || $tipus == 'APROFITAMENT' || $tipus == 'INSCRIT' ) {
						$textFirma = "<p style='margin-top: 20px'>Adam Carmona Carrasco com a
						President de l'Associació per al Desenvolupament Infantil i
						Familiar PrisMa.</p>";
						$classBackground = "background-repeat: no-repeat; background-image:
						url('https://intranet.prisma.cat/img/fons_certificat_prisma_sense_adreca.jpg')";
					}
					else if ( $tipus == 'PAPER' ) {
						$textFirma = "<p style='margin-top: 20px'>Pablo Martori Delupi com a
						Secretari Pedagògic de l'Associació per al Desenvolupament
						Infantil i Familiar PrisMa.</p>";
					}

					$textFirma .= "<p id='firma' style='margin-top: 20px'></p>
					<p style='margin-top: 15px'>CERTIFICO,</p>";

					/* Construim el text de ha superat el curs */
					if ( $tipus == 'DIGITAL' || $tipus == 'PAPER' || $tipus == 'APROFITAMENT' ) {
						$superat = "ha superat el";
						$haRealitzat = "s'ha realitzat";
						$apte = " amb la qualificació APTE";
					}
					else if ( $tipus == 'INSCRIT' ) {
						$superat = "està inscrit al";
						$date1 = new DateTime("now");
						$date2 = new DateTime($datai);
						$diff = $date1->diff($date2);
						if ( $diff->invert == 1 ) {
							$haRealitzat = "s'està realitzant";
						}
						else {
							$haRealitzat = "realitzarà";
						}
						$apte = "";
					}

					$textDatesIniciFi = $this->__mostrarDatesIniciFi($datai, $dataf);

					// $textSuperat = "<p style='margin-top: 15px;'>Que en/na <strong>
					// ".$nom." ".$cognoms."</strong>, amb DNI <strong>".$dni."</strong>,
					// ".$superat." curs <strong>".$nomCurs."</strong> de
					// <strong>".$hores." hores</strong> de durada".$apte.",
					// organitzat per l'<strong>Associació per al Desenvolupament Infantil i
					// Familiar PrisMa</strong>, que ".$haRealitzat." virtualment, del
					// dia ".$dataLlargaInici." al dia ".$dataLlargaFi.".</p>";
					$textSuperat = "<p style='margin-top: 15px;'>Que en/na <strong>
					".$nom." ".$cognoms."</strong>, amb DNI <strong>".$dni."</strong>,
					".$superat." curs <strong>".$nomCurs."</strong> de
					<strong>".$hores." hores</strong> de durada".$apte.",
					organitzat per l'<strong>Associació per al Desenvolupament Infantil i
					Familiar PrisMa</strong>, que ".$haRealitzat." virtualment, ".$textDatesIniciFi.".</p>";

					/* Construim el text del certificat */
					$textCertificat = "";
					$comprovacio = ( $certificat != null && mb_strtoupper($certificat, 'UTF-8') != mb_strtoupper('ESTUDIANT', 'UTF-8') &&
					mb_strtoupper($certificat, 'UTF-8') != mb_strtoupper('ESTUDIANT UdG', 'UTF-8') ) OR $certificat == null;

					$textCertFISS = "";
					if ( $fiss != null && $fiss != '' ) {
						$textCertFISS = "<p style='font-weight:bold; margin-top: 15px'>
						Aquesta activitat ha rebut el reconeixement de formació d'interès
						en serveis socials (codi FISS / ".$fiss.") que concedeix el
						Departament de Drets Socials i Inclusió de la Generalitat de Catalunya.</p>";
					}
					$textCertificat = $textCertFISS;

					echo $textCertFISS."<br />";

					if ( $comprovacio ) {
						$textCertGTAF = "";

						if ( $gtaf != null && $gtaf != '' ) {
							$vectCursEscolar = explode('/', $cursEscolar);
							$cursEsc = $vectCursEscolar[0]."-".$vectCursEscolar[1];

							$textCertGTAF = "<p style='font-weight:bold; margin-top: 15px'>
							Aquesta activitat de formació (codi GTAF ".$gtaf." / ".$cursEsc.")
							ha estat reconeguda com a Formació Permanent del Professorat per
							la resolució de ".$dataLlargaRes." del director general de
							l'Educació Bàsica i el Batxillerat del Departament d'Educació
							de la Generalitat de Catalunya.</p>";
						}

						$textCertificat = $textCertGTAF.$textCertFISS;
					}
					if ( $tipus == 'APROFITAMENT' ) {
						$textCertificat = "".$textCertFISS;
					}

					/* Construim el titol de certificat d'aprofitament */
					$segonTitolCertificat = "<p style=\"text-align: center;
					margin: 20px 0; font-size: 1rem; font-weight: bold; color: #496BAA;\">
					CERTIFICAT D'ASSISTÈNCIA I APROFITAMENT</p>";

					/* Construim el titol de certificat d'inscripcio */
					if ( $tipus == 'INSCRIT' ) {
						$segonTitolCertificat = "<p style=\"text-align: center;
						margin: 20px 0; font-size: 1rem; font-weight: bold; color: #496BAA;\">
						CERTIFICAT D'INSCRIPCIÓ</p>";
					}

					$textFirma2 = "<p style='margin-top: 130px'>";
					$textFirma2 .= "Girona, ".intval($diaActual)." ".$nomMesActual." de ".$anyActual."</p>";

					/* Construim el text a mostrar */
					$mostrar .= "<div style=\"".$widthPantalla." font-family:Calibri,
					Arial, Helvetica, sans-serif; text-align: justify; height: 1090px;
					padding: 0 75px 0 130px; line-height: 2;
					".$classBackground."\">
						<p style='text-align: center; height: 150px;'></p>
						".$segonTitolCertificat."
						<hr style='border-color: #505050'>
						<p style='text-align: center; margin: 15px 0; font-size: 1.3rem;
						font-weight: bold; line-height:1.5 !important'>".$objNomCurs->get()."</p>
						<hr style='border-color: #505050'>
						".$textFirma."
						".$textSuperat."
						".$textCertificat."
						<p style='margin-top: 15px'>I perquè així consti, signo
						el present certificat.</p>
						".$textFirma2."
					</div>";

				}
				$conWeb->closeStmt();
			}
			else {
				throw new Exception('', 4126);
			}

			if ( $descarrega ) {
				$mostrar .= "</body></html>";

				$fecha = new DateTime();
				$tmp = $fecha->getTimestamp();

				/* Actualitzem el registre d'inscripció amb la data de la generació del certificat */
				if ( $obsCert != null && $obsCert != '' ) {
					$obsCertNou = $obsCert." - ";
				}
				else {
					$obsCertNou = "";
				}

				$objData = new Date("now");
				$obsCertNou .= $objData->getDataFomatDDMMYYYY();
				$obsCertNou .= " ";

				if ( $tipus == 'DIGITAL') {
					$obsCertNou .= "(D)";
				}
				else if ( $tipus == 'PAPER' ) {
					$obsCertNou .= "(P)";
				}
				else if ( $tipus == 'APROFITAMENT' ) {
					$obsCertNou .= "(A)";
				}
				else if ( $tipus == 'INSCRIT' ) {
					$obsCertNou .= "(I)";
				}

				if ( $stmt2=$conWeb2->prepare( $this->consultesBD_Web["updGeneratCertificat"] ) ) {
					$stmt2->bind_param("sd", $obsCertNou, $idInsc);
					$stmt2->execute();
					$conWeb2->closeStmt();
				}
				else
					throw new Exception('',4132);

				$options = new \Dompdf\Options();
				$options->set('isRemoteEnabled', true);
				$dompdf = new \Dompdf\Dompdf($options);
				$dompdf->set_paper("A4", "portrait");
				$dompdf->load_html($mostrar);
				$dompdf->render();

				$pdf = $dompdf->output();
				$filename = $dni."_". $any.$curs.$mes."_Certificat_digital_".$tmp;
				file_put_contents($filename, $pdf);

				$mostrar = $filename;
			}

		}
		else if ( $tipus == 'SOBRE' ) {
			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarInfoCertAlumne"] ) ) {
				$stmt->bind_param("d", $idInsc);
				$stmt->execute();
				$stmt->store_result();
				if ($stmt->num_rows() > 0) {
					$stmt->bind_result($any, $curs, $mes, $dni, $nom, $cognoms, $adreca, $cp, $poble);
					$stmt->fetch();

					$objNom = new Text($nom." ".$cognoms);
					$objNom->setMaj();
					$nomCognoms = $objNom->get();

					$objAdreca = new Text($adreca);
					$objAdreca->setMaj();
					$adreca = $objAdreca->get();

					$objPoble = new Text($poble);
					$objPoble->setMaj();
					$poblacio = $objPoble->get();

					$mostrar .= "<div style=\"".$widthPantalla." font-family:Calibri,
					Arial, Helvetica, sans-serif; \">
						<p style='margin: 0'><strong>".$nomCognoms."</strong><br/>
						".$adreca."<br/>
						".$cp." ".$poblacio."</p>
					</div>";

				}
				$conWeb->closeStmt();
			}
			else {
				throw new Exception('', 4133);
			}

			if ( $descarrega ) {
				$mostrar .= "</body></html>";

				$fecha = new DateTime();
				$tmp = $fecha->getTimestamp();

				//generar PDF 491pt width 251pt height
				$options = new \Dompdf\Options();
				$options->set('isRemoteEnabled', true);
				$dompdf = new \Dompdf\Dompdf($options);
				$dompdf->set_paper(array(0, 0, 311.75, 623.51), "landscape");
				$dompdf->load_html($mostrar);
				$dompdf->render();
				$pdf = $dompdf->output();
				$filename = $dni."_". $any.$curs.$mes."_Certificat_sobre_".$tmp;
				file_put_contents($filename, $pdf);

				$mostrar = $filename;
			}
		}
		$conWeb->desconectarBD();

		return $mostrar;
	}

	/* ########################   INTRANET D'ALUMNES  ######################### */
