	/**
   * @brief Mostra l'estructura de la pàgina '/intranet/alumnes/pagaments/'.
   * @return Mostra l'estructura de la pàgina '/intranet/alumnes/pagaments/'.
   */
	private function __mostrarPage_Alumnes_Pagaments() {
		$dataAnalitzarFitxer = "";

		$csv_file = "analisis-fitxer.txt";
		$path_file = "../fitxers/".$csv_file;

		if ( file_exists($path_file) ) {
			if (!$handle = fopen($path_file, "r")) {
				 echo "Cannot open file analisis fitxer";
				 exit;
			}
			else {
				$content = fread($handle, filesize($path_file));
				$dates = explode('_', $content);
				$ldates = count($dates);
				$dataAnalitzarFitxer = $dates[$ldates-2];
			}

			fclose($handle);
		}

		$mostrar = "
		<div id='analisis-tpv' class='card card-blau'>
			<form id='formTPV' action='https://intranet.prisma.cat/ajax/alumnes/analitzarFitxerTPV.php'method='POST' enctype='multipart/form-data'>
				<div class='d-flex flex-column justify-content-center align-items-center w-100 text-center border-bottom card-header'>
					<p class='title font-weight-bold text-center py-3 mb-0 align-items-center justify-content-center d-flex'>
						ANALITZA FITXER
						<i class='material-icons ml-1'>search</i>
					</p>
				</div>
				<div class='card-body px-0'>
					<div class='d-flex flex-column flex-md-row justify-content-center align-items-center'>
						<div class='d-flex flex-column flex-sm-row justify-content-center align-items-center w-100'>
							".$this->__mostrarInput(4, '', '', '', 'fitxer-tpv', '', '')."
						</div>
					</div>
				</div>
				<div class='card-footer d-flex justify-content-center align-items-center pt-0'>
					<input id='analitza-fitxer-pay-tpv' type='submit' role='button' class='boto-blau px-4 d-flex'
						value=\"Analitza el fitxer\">
					<span class='ml-0 ml-md-2 lastVersion'>Últim anàlisi: ".$dataAnalitzarFitxer."</span>
				</div>
			</form>
		</div>
		<div id='pagaments-tpv' class='card card-blau mt-0' style='display: none;'></div>
		<div id='pagaments' class='card card-blau mb-2'>
			<div class='d-flex flex-column justify-content-center align-items-center w-100 text-center border-bottom card-header'>
				<p class='title font-weight-bold text-center py-3 mb-0 align-items-center justify-content-center d-flex'>
					CERCA
					<i class='material-icons ml-1'>search</i>
				</p>
			</div>
			<div class='card-body px-0'>
				<div class='d-flex flex-column flex-md-row justify-content-center align-items-center'>
					<div class='d-flex flex-column flex-sm-row justify-content-center align-items-center w-100'>
						".$this->__mostrarInput(2, '', 'NIF/NIE', '', 'dni', '', '')."
						".$this->__mostrarInput(2, '', 'CODI REGAL', '', 'codi-regal', '', '')."
						".$this->__mostrarInput(2, '', 'NÚM FACTURA', '', 'num-fact', '', '')."
					</div>
				</div>
				<div class='d-flex flex-column flex-md-row justify-content-center align-items-center'>
					<div class='d-flex flex-column flex-sm-row justify-content-center align-items-center w-100 pt-1'>
						<label class='position-relative mr-sm-2 pr-sm-3' style='flex-shrink: 0'>TIPUS D'INSCRIPCIÓ</label>
						<button id='tipus-individual' role='button' class='boto-blau px-4 d-flex w-50 mr-sm-1 tipusInsc marcat'>
							<i class='material-icons mr-1'>face</i>
							Alumne
						</button>
						<button id='tipus-grup' role='button' class='boto-blau px-4 d-flex w-50 ml-sm-1 tipusInsc'>
							<i class='material-icons mr-1'>people</i>
							Grup
						</button>
					</div>
				</div>
			</div>
			<div class='card-footer d-flex justify-content-center align-items-center pt-0'>
				<button id='cercar-pagament' role='button' class='boto-blau px-4 d-flex'>
					Cerca
					<i class='material-icons ml-1'>search</i>
				</button>
			</div>
		</div>
		<div id='resultats-cerca' class='card card-blau mt-0 pt-0' style='display: none; min-height: 420px'></div>";

		return $mostrar;
	}

	/**
   * @brief Mostra els pagaments relacionats amb el dni $dni segons el tipus $tipusInsc
   * @return Mostra totes les inscripcions que falti pagar alguna part de al inscripció
	* on el dni és $dni i el tipus d'incripció és $tipusInsc
   */
	public function mostrarPagaments($dni, $codiRegal, $numeroFact, $tipusInsc) {

		$pagaments = []; $nPag = 0;

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();
		$conWeb2 = new ConnexioWeb();
		$conWeb2->connectarBD();
		$conWeb3 = new ConnexioIntranet();
		$conWeb3->connectarBD();
		if ( $dni != '' ) {
			if ( $tipusInsc == "I") {
				/* Busco pagaments individuals per dni */
				if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarPagaments"] ) ) {
					$stmt->bind_param("ss", $dniLike, $tipusInsc);
					$dniLike = $dni."%";
					$stmt->execute();
					$stmt->store_result();
					if ($stmt->num_rows() > 0) {
						$stmt->bind_result($tipus, $idInsc, $any, $mes, $curs, $nom, $cognoms, $correu, $dniProv,
						$apagar, $pagament, $factura, $fraccionat, $fraccio, $pagObs, $idPag);

						while( $stmt->fetch() ) {
							$efact = 0; $numFact = '';

							if ( $factura != null or $factura != '' ) {
								if ( $stmt2=$conWeb2->prepare( $this->consultesBD_Web["buscarInfoFacturaByFact"] ) ) {
									$stmt2->bind_param("d", $factura);
									$stmt2->execute();
									$stmt2->store_result();
									if ($stmt2->num_rows() > 0) {
										$stmt2->bind_result($idFact, $factRelFact, $anyFact, $ordreFact,
	   							  $numFact, $dataFact, $dataPagFact, $generadaFact, $raoFact, $cifFact,
	   							  $adrecaFact, $cpFact, $pobleFact, $c1Fact, $c2Fact, $importFact,
	   							  $entitatFat, $formaPagamentFact, $cursFact, $horesFact, $obsFact, $efact);

										$stmt2->fetch();

									}
									$conWeb2->closeStmt();
								}
							}

							$pagaments[$nPag] = [
								$tipus, $idInsc, $any, $mes, $curs, $nom, $cognoms, $correu, $dniProv,
								$apagar, $pagament, $factura, $fraccionat, $fraccio, $pagObs, $idPag, $efact, $numFact
							];
							$nPag++;
						}
					}
					$conWeb->closeStmt();
				}
				else {
					throw new Exception('',4226);
				}

				$tipusI = 'P';
				/* Busco pagaments per pack per dni */
				if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarPagamentsPack"] ) ) {
					$stmt->bind_param("ss", $dniLike, $tipusI);
					if ( $stmt2=$conWeb2->prepare( $this->consultesBD_Web["buscarInfoPack"] ) ) {
						$stmt2->bind_param("d", $idPack);

						$stmt->execute();
						$stmt->store_result();
						if ($stmt->num_rows() > 0) {
							$stmt->bind_result($tipus, $idInsc, $nom, $cognoms, $correu, $dniProv,
							$apagar, $pagament, $factura, $fraccionat, $fraccio, $pagObs, $obs, $idPag);

							while( $stmt->fetch() ) {
								//A partir d'observacions, busco el idpag
			               $arrObs = explode(' ',$obs);
			               $i = 0; $trobat = 0;
			               while ( $i < count($arrObs) && !$trobat ) {
			                  if ( explode('|', $arrObs[$i])[0] == 'PACK' ) {
			                     $idPack = explode('|', $arrObs[$i])[1];
			                     $trobat = 1;
			                  }
			                  $i++;
			               }

								$stmt2->execute();
								$stmt2->store_result();

								if ($stmt2->num_rows() > 0) {
									$stmt2->bind_result($codiPack);
									$stmt2->fetch();
									if ( $apagar > 0 && $apagar > $pagament ) {
										$pagaments[$nPag] = [
											$tipus, $idInsc, "-", "-", $codiPack, $nom, $cognoms, $correu, $dniProv,
											$apagar, $pagament, $factura, $fraccionat, $fraccio, $pagObs, $idPag, "0", "0"
										];
										$nPag++;
									}
								}
							}
						}
						$conWeb2->closeStmt();
					}
					else {
						throw new Exception('',0000);
					}
					$conWeb->closeStmt();
				}
				else {
					throw new Exception('',0000);
				}

				/* Busco regals per dni */
				if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarRegNoPayByDni"] ) ) {
					$stmt->bind_param("s", $dniLike);
					$dniLike = $dni."%";
					$stmt->execute();
					$stmt->bind_result($id, $dniProv, $nom, $correu, $curs, $nomCurs,
					$apagar, $factura, $obs);

					$tipus = 'R';
					$buit = '-';
					$zero = 0;

					while( $stmt->fetch() ) {
						$pagaments[$nPag] = [
							$tipus, $id, $buit, $buit, $curs, $nom, $buit, $correu, $dniProv,
							$apagar, $zero, $factura, $buit, $buit, $obs, $zero, "0", "0"
						];
						$nPag++;
					}
					$conWeb->closeStmt();
				}
				else {
					throw new Exception('',4227);
				}
			}

			if ( $tipusInsc == "G") {

				echo $this->consultesBD_Web["buscarPersRespGrup2"]."<br />";
				echo $dni."<br />";

				if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarPersRespGrup2"] ) ) {
					$stmt->bind_param("ss", $dni, $dni);
					$dniLike = $dni."%";
					$stmt->execute();
					$stmt->store_result();
					if ($stmt->num_rows() > 0) {
						$stmt->bind_result($idPag2, $dniGrup);

						while( $stmt->fetch() ) {
							echo $this->consultesBD_Web["buscarPagamentsGrup"]."<br />";
							echo $idPag2." ".$tipusInsc."<br />";

							if ( $stmt2=$conWeb2->prepare( $this->consultesBD_Web["buscarPagamentsGrup"] ) ) {
								$stmt2->bind_param("ds", $idPag2, $tipusInsc);
								$stmt2->execute();
								$stmt2->store_result();
								if ($stmt2->num_rows() > 0) {
									$stmt2->bind_result($tipus, $idInsc, $any, $mes, $curs, $nom, $cognoms, $correu, $dniProv,
									$apagar, $pagament, $factura, $fraccionat, $fraccio, $pagObs, $idPag);

									while( $stmt2->fetch() ) {
										if ( $apagar > 0 && $apagar > $pagament ) {
											$pagaments[$nPag] = [
												$tipus, $idInsc, $any, $mes, $curs, $nom, $cognoms, $correu, $dniGrup,
												$apagar, $pagament, $factura, $fraccionat, $fraccio, $pagObs, $idPag, "0", "0"
											];
											$nPag++;
										}
									}
								}
								$conWeb2->closeStmt();
							}
							else {
								throw new Exception('',4229);
							}
						}
					}
					$conWeb->closeStmt();
				}
				else {
					throw new Exception('',5229);
				}

			}

			$textRes = "RESULTATS DE LA CERCA PER DNI «".$dni."»";
		}
		else if ( $codiRegal != '' ) {
			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarRegNoPayByCodi"] ) ) {
				$stmt->bind_param("s", $codiRegal);
				$stmt->execute();
				$stmt->bind_result($id, $dniProv, $nom, $correu, $curs, $nomCurs,
				$apagar, $factura, $obs);

				$tipus = 'R';
				$buit = '-';
				$zero = 0;

				while( $stmt->fetch() ) {
					$pagaments[$nPag] = [
						$tipus, $id, $buit, $buit, $curs, $nom, $buit, $correu, $dniProv,
						$apagar, $zero, $factura, $buit, $buit, $obs, $zero, "0", "0"
					];
					$nPag++;
				}
				$conWeb->closeStmt();
			}
			else {
				throw new Exception('',4228);
			}
			$textRes = "RESULTATS DE LA CERCA PER CODI REGAL «".$codiRegal."»";
		}
		else if ( $numeroFact != '' ) {
			/* Busquem la info dels pagament amb el numero de factura $numFact */
			// echo $this->consultesBD_Web["buscarPagamentsByFact"]."<br />".$numeroFact."<br />".$tipusInsc."<br />";
			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarPagamentsByFact"] ) ) {
				$stmt->bind_param("s", $numeroFact);
				$stmt->execute();
				$stmt->store_result();
				if ($stmt->num_rows() > 0) {
					$stmt->bind_result($tipus, $idInsc, $any, $mes, $curs, $apagar, $pagament,
					$factura, $fraccionat, $fraccio, $pagObs, $idPag, $obs, $dniProv, $efact);
					while( $stmt->fetch() ) {
						// echo $tipus."<br>".$idInsc."<br>".$any."<br>".$mes."<br>".$curs."<br>".$apagar."<br>".$pagament."<br>".$factura."<br>".$fraccionat."<br>".$fraccio."<br>".$pagObs."<br>".$idPag."<br>".$dniProv."<br>".$efact."<br />";
						//Per cada registre, marco si és un efact i busco les dades de la persona que fa el pagament (si EFACT = 1, les busco a inscripcions, altrament a entitats)
						if ( $efact == 1 ) {
							// echo $this->consultesBD_Intra["buscarRespEntitatByCIF"]."<br />".$dniProv."<br />";

							if ( $stmt3=$conWeb3->prepare( $this->consultesBD_Intra["buscarRespEntitatByCIF"] ) ) {
								$stmt3->bind_param("s", $dniProv);
								$stmt3->execute();
								$stmt3->store_result();
								if ($stmt3->num_rows() > 0) {
									$stmt3->bind_result($entitat, $nom, $cognoms, $correu);
									$stmt3->fetch();
								}
								$conWeb3->closeStmt();
							}
							else {
								throw new Exception('',4285);
							}
						}
						else {
							// echo $this->consultesBD_Web["buscarNomResPagamentsByFact"]."<br />".$factura."<br />";

							if ( $stmt2=$conWeb2->prepare( $this->consultesBD_Web["buscarNomResPagamentsByFact"] ) ) {
								$stmt2->bind_param("d", $factura);
								$stmt2->execute();
								$stmt2->store_result();
								if ($stmt2->num_rows() > 0) {
									$stmt2->bind_result($nom, $cognoms, $correu);
									$stmt2->fetch();
								}
								$conWeb2->closeStmt();
							}
							else {
								throw new Exception('',4284);
							}
						}

						$pagaments[$nPag] = [
							$tipus, $idInsc, $any, $mes, $curs, $nom, $cognoms, $correu, $dniProv,
							$apagar, $pagament, $factura, $fraccionat, $fraccio, $pagObs, $idPag, $efact, $numeroFact
						];
						$nPag++;
					}
				}
				$conWeb->closeStmt();
			}
			else {
				throw new Exception('',4226);
			}

		}

		$conWeb3->desconectarBD();
		$conWeb2->desconectarBD();
		$conWeb->desconectarBD();

		if ( $nPag > 0 ) {

			$tipusBancs[0] = "Caixa";
			$tipusBancs[1] = "tpv";
			$tipusBancs[2] = "BBVA";

			$mostrar = "<div class='d-flex flex-column justify-content-center align-items-center w-100 text-center border-bottom card-header'>
				<p class='title font-weight-bold text-center py-3 mb-0 align-items-center justify-content-center d-flex'>
					Resultats de la cerca
				</p>
			</div>
