				else if ( $tipusI == 'R' ) {
					$idCercat = $id;
					$pagamentTD = "<td id='pagament-".$idCercat."'>".$apagar."</td>";
					$classTipus = "lightGreen";
					$iconTipus = "<i class='fas fa-gift' aria-hidden='true'></i>";
				}
				else if ( $tipusI == 'P' ) {
					$idCercat = $idPag;

					if ( $numeroFact != '' ) {
						$pagamentTD = "<td id='pagament-".$idCercat."'>".$apagar."</td>";
					}
					else {
						$pagamentTD = "<td id='pagament-".$idCercat."'>".$this->__mostrarInput(2, '', '', '', '', 'text-center pagament', '')."</td>";
					}
					$classTipus = "lightPurple";
					$iconTipus = "<i class='fas fa-cubes' aria-hidden='true'></i>";
				}
				else if ( $tipusI == 'G' ) {
					$idCercat = $idPag;

					if ( $numeroFact != '' ) {
						$pagamentTD = "<td id='pagament-".$idCercat."'>".$apagar."</td>";
					}
					else {
						$pagamentTD = "<td id='pagament-".$idCercat."'>".$this->__mostrarInput(2, '', '', '', '', 'text-center pagament', '')."</td>";
					}
					$classTipus = "lightOrange";
					$iconTipus = "<i class='material-icons aria-hidden='true''>group</i>";
				}

				$labelTipus = "<label id='labelType-".$idCercat."' class='label tipus ".$classTipus." d-flex
				justify-content-center align-items-center position-relative
				font-weight-bold px-2 py-2 pointer'>".$iconTipus."</label>";

				$banc = $this->mostrarSelect('', '', '', 'banc-'.$idCercat, 'banc', 'Triar', '', $tipusBancs);

				$mostrar .= "<tr>
					<td>".$labelTipus."</td>
					<td>".$any."</td>
					<td>".$mes."</td>
					<td>".$curs."</td>
					<td>".$dni."</td>
					<td id='apagar-".$idCercat."'>".$apagar." €</td>
					<td id='pagat-".$idCercat."'>".$pagament." €</td>
					".$pagamentTD."
					<td>".$this->__mostrarInput(3, '', '', '', 'dataPag-'.$idCercat, 'text-center dataPag', '')."</td>
					<td>".$banc."</td>
					<td id='pagObs-".$idCercat."'>".$obs."</td>
					<td id='fraccio-".$idCercat."'>".$textFrac."</td>
