			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarDadesCursAllByIdPag"] ) ) {
				$stmt->bind_param("d", $id);
				$stmt->execute();
				$stmt->store_result();
				if ($stmt->num_rows() > 0) {
					$stmt->bind_result($any, $mes, $codiCurs, $nom, $cognoms, $dni, $email,
					$adreca, $cp, $poble, $factRel, $apagar, $inscrit, $importPagat, $fraccio, $frac, $pagObs, $entitat);
					$stmt->fetch();
