				throw new Exception('',4269);
			}
			$mostrar = "<div class='d-flex flex-column justify-content-center align-items-center mt-3'>
				<p class='titol-apartat'>Dades del regal</p>
				<div class='apartat d-flex flex-column align-items-center justify-content-center w-100 mt-2'>
					<div class='d-flex flex-column align-items-center justify-content-center w-100 mb-2'>
						".$this->__mostrarInput(1,"","ORIGEN", "active", "", "no-edit", $origen)."
					</div>
					<div class='d-flex flex-column align-items-center justify-content-center w-100 mb-2'>
						".$this->__mostrarInput(1,"","DESTÍ", "active", "", "no-edit", $desti)."
					</div>
					<div class='d-flex flex-column align-items-center justify-content-center w-100 mb-2'>
						".$this->__mostrarInput(1,"","CODI REGAL", "active", "", "no-edit", $codiRegal)."
					</div>
					<div class='d-flex flex-column align-items-center justify-content-center w-100 mb-0'>
						".$this->__mostrarInput(1,"","CURS REGAL", "active", "", "no-edit", $nomCurs)."
					</div>
				</div>
			</div>";

		}
		else if ( $tipus == 'G' ) {
			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarPersRespGrup"] ) ) {
				$stmt->bind_param("d", $id);
				$stmt->execute();
				$stmt->store_result();
				if ($stmt->num_rows() > 0) {
