									<th style='width: 15%'>MES</th>
									<th style='width: 15%'>CURS</th>
									<th style='width: 40%'>MOM CURS</th>
									<th style='width: 15%'>HORES</th>
								</tr>
							</thead>
							<tbody>";

					$stmt->fetch();

					$tableCursos .= "<tr>
						<td>".$anyEdicio."</td>
						<td>".$mesEdicio."</td>
						<td>".$codiCurs."</td>
						<td>".$titol."</td>
						<td>".$horesEd."</td>
					</tr>";

					$tableCursos .= "</tbody></table></div>";
				}
				$conWeb->closeStmt();
			}
			else {
				throw new Exception('',4273);
			}

			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarPersGrup"] ) ) {
				$stmt->bind_param("d", $id);
				$stmt->execute();
				$stmt->store_result();
				if ($stmt->num_rows() > 0) {
					$stmt->bind_result($nomAlumne, $cognomsAlumne, $dniAlumne, $correuAlumne);

					$tableAlumnes = "<div class='d-flex flex-column flex-sm-row align-items-center justify-content-center w-100'>
					<table class='table table-hover table-striped table-hover text-center'>
						<thead>
							<tr>
								<th style='width: 25%'>NOM</th>
								<th style='width: 25%'>COGNOMS</th>
								<th style='width: 25%'>DNI</th>
								<th style='width: 25%'>CORREU</th>
							</tr>
						</thead>
						<tbody>";

					while ( $stmt->fetch() ) {
						$tableAlumnes .= "<tr>
							<td>".$nomAlumne."</td>
							<td>".$cognomsAlumne."</td>
							<td>".$dniAlumne."</td>
							<td>".$correuAlumne."</td>
						</tr>";
					}

					$tableAlumnes .= "</tbody></table></div>";

				}
				$conWeb->closeStmt();
			}
			else {
				throw new Exception('',4274);
			}

			$mostrar = "<div class='d-flex flex-column justify-content-center align-items-center mt-3'>
				<p class='titol-apartat'>Dades de la persona responsable</p>".$tableResp."
				<p class='titol-apartat'>Dades del curs</p>".$tableCursos."
				<p class='titol-apartat'>Alumnes del grup</p>".$tableAlumnes."
			</div>";
		}
		else if ( $tipus == 'P' ) {
			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["cnsInscsPack"] ) ) {
				$stmt->bind_param("d", $id);
				$stmt->execute();
				$stmt->bind_result($nom, $cognoms, $dni, $email, $adreca, $cp,
				$poble, $factRel, $apagar, $inscrit, $importPagat, $fraccio, $fracc, $observacions, $pagObs);
				$stmt->fetch();
				$conWeb->closeStmt();
			}
			else {
				throw new Exception('',4270);
			}

			$arrObs = explode(' ',$observacions);
