					}
					$tablePacks .= "</tbody></table></div>";
				}
				$conWeb->closeStmt();
			}
			else {
				throw new Exception('',4271);
			}

			$mostrar = "<div class='d-flex flex-column justify-content-center align-items-center mt-3'>
				<p class='titol-apartat'>Dades de l'alumne</p>
				<div class='apartat d-flex flex-column align-items-center justify-content-center w-100 mt-2'>
					<div class='d-flex flex-column align-items-center justify-content-center w-100 mb-2'>
						".$this->__mostrarInput(1,"","NOM", "active", "", "no-edit", $nom)."
					</div>
					<div class='d-flex flex-column align-items-center justify-content-center w-100 mb-2'>
						".$this->__mostrarInput(1,"","COGNOMS", "active", "", "no-edit", $cognoms)."
					</div>
					<div class='d-flex flex-column align-items-center justify-content-center w-100 mb-3'>
						".$this->__mostrarTextarea('', 'OBSERVACIONS DE PAGAMENT', 'active', '', 'no-edit', $pagObs, 'text')."
					</div>
				</div>
				<p class='titol-apartat'>Cursos relacionats amb el pack</p>".$tablePacks."
				<div class='apartat d-flex flex-column align-items-center justify-content-center w-100 mt-2'>
					<button id='cons-dades-".$dni."' role='button' class='cnsDadesAlumne boto-blau px-4 d-flex'>
						Consulta altres dades de l'alumne
