	public function mostrarModalConfPag($numFact) {
		$qui = $this->usuari->getNom()->get();

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		//s'h de buscar el cif de la factura
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarInfoFacturaByNum"] ) ) {
			$stmt->bind_param("s", $numFact);
			$stmt->execute();
			$stmt->store_result();
			$stmt->bind_result($idFact, $any, $ordre, $num, $data, $dataPagament,
			$generada, $rao, $cif, $adreca, $cp, $poblacio, $concepte1, $concepte2,
			$import, $entitat, $curs, $hores, $observacions);
			$stmt->fetch();
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('', 4287);
		}

		$conWeb->desconectarBD();

		$conIntra = new ConnexioIntranet();
		$conIntra->connectarBD();

		//es busca l'entitat i la persona responsable
		if ( $stmt=$conIntra->prepare( $this->consultesBD_Intra["buscarRespEntitatByCIF"] ) ) {
			$stmt->bind_param("s", $cif);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($nomEnt, $nomRespEnt, $cogRespEnt, $correuRespEnt);
				$stmt->fetch();
				$existeixEntitat = 1;
			}
			else {
				$existeixEntitat = 0;
			}
			$conIntra->closeStmt();
		}
		else {
			throw new Exception('',4288);
		}

		$conIntra->desconectarBD();

		if ( !$existeixEntitat ) $textCorreu = "NO s'enviarà un missatge a l'entitat
		ja que no s'ha trobat l'entitat. Si us plau, ves a l'apartat «Genera entitat» per crear l'entitat.";
		else {
			if ( $nomRespEnt == '' || $correuRespEnt == '' ) {
				$textCorreu = "NO s'enviarà un missatge a l'entitat ja falten dades de la persona que gestiona l'entitat.";
			}
			else {

				$respEnt = $nomRespEnt." ".$cogRespEnt;

				$textCorreu = "s'<strong>enviarà un missatge</strong> a l'entitat
				<strong class='text-marcat'>".$nomEnt."</strong> que té com a
				persona responsable <strong class='text-marcat'>".$respEnt."</strong>
				amb un correu <strong class='text-marcat'>".$correuRespEnt."</strong>";
			}

		}

		$mostrar = "<p>Hola <strong>".$qui."</strong>,</p>
		<p>estàs intentant passar un pagament que té una factura generada.</p>
		<p>Si continues, s'<strong>actualitzarà la factura</strong> núum <strong class='text-marcat'>".$numFact."</strong>
		i ".$textCorreu.".</p>
		<div class='modal-footer border-0 d-flex align-items-center justify-content-center p-0 mt-1'>
			<a id='torna-pagament' role='button' class='btn btn-disable mr-1'>Torna enrere</a>
			<a id='confirmar-pagament' role='button' class='btn btn-success'>Confirma</a>
		</div>";

		return $mostrar;
	}

	public function efectuarPagament($idTipus, $tipus, $pagament,
	$dataPag, $banc, $obs, $numFact, $efact) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		$dataPagament = $dataPag;

		$objDatePag = new Date($dataPagament);
		$dataPagamentDDMMYY = $objDatePag->getDataFomatDDMMYYYY_HHMMSS();

		$dataPagament = $dataPag;

		// Busquem l'import de pagament
		$importPag = $pagament;

		// Busquem la forma de pagament
		$formaPagament = $banc;
		if ( $efact == 0 ) {
			/* ########### Calculem les variables per efectuar el pagament ###########
			   ###########   sense tenir en compte el tipus d'inscripció   ########### */

			// Calculem l'any fiscal
			$anyFiscal = date('Y');

			// Calculem el tipus de factura
			if ( $pagament > 0 ) $tipusFact = 'A';
			else if ( $pagament < 0 ) $tipusFact = 'R';

			// Calculem l'ordre de la factura
			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarLastOrdreFact"] ) ) {
				$stmt->bind_param("ds", $anyFiscal, $tipusFact);
				$stmt->execute();
				$stmt->bind_result($lastOrdreFact);
				$stmt->store_result();
				if ( $stmt->num_rows() > 0 ) {
					$stmt->fetch();
					$ordreFact = intval($lastOrdreFact)+1;
				}
				else {
					$ordreFact = 1;
				}
				$conWeb->closeStmt();
			}
			else {
				throw new Exception('',4230);
			}

			// Calculem el número  de la factura
			$numFact = "A".$anyFiscal."/".$ordreFact;

			// Buscquem la data actual de la factura
			$dataActual = date('Y')."-".date('m')."-".date('d')." ".date('H').":".date('i').":".date('s');

			// Calculem el valor de l'entitat i la forma de pagament de la factura
			$entitat = "Asso";

			/* ########### Efectuar el pagament amb les variables generals ###########
			   ###########     tenint en compte el tipus d'inscripció      ########### */

			if ( $tipus == 'R' ) {
				$idRegal = $idTipus;
				$this->efectuarPagamentRegal($idRegal, $anyFiscal, $tipusFact, $ordreFact,
				$numFact, $dataActual, $dataPagament, $importPag, $entitat, $formaPagament);
			}
			else if ( $tipus == 'G' ) {
				$idPag = $idTipus;
				$this->efectuarPagamentGrupal($idPag, $obs,
				$anyFiscal, $tipusFact, $ordreFact, $numFact, $dataActual, $dataPagament, $importPag, $entitat, $formaPagament);
			}
			else if ( $tipus == 'P' ) {
				$idPag = $idTipus;

				$this->efectuarPagamentPack($idPag, $obs,
				$anyFiscal, $tipusFact, $ordreFact, $numFact, $dataActual, $dataPagament, $importPag, $entitat, $formaPagament);
			}
			else if ( $tipus == 'I' ) {
				$idPag = $idTipus;

				$this->efectuarPagamentInscripcio($idPag, $obs,
				$anyFiscal, $tipusFact, $ordreFact, $numFact, $dataActual, $dataPagament, $importPag, $entitat, $formaPagament);
			}
		}
		else {
			$this->efectuarPagamentFacturaGenerada($numFact, $tipus, $obs,
			$dataPagament, $importPag, $formaPagament);
		}

		$conWeb->desconectarBD();

	}

	private function efectuarPagamentRegal($idRegal, $anyFiscal, $tipusFact, $ordreFact,
	$numFact, $dataActual, $dataPagament, $importPag, $entitat, $formaPagament) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		// Busquem les dades de la inscripció del regal a partir del codi del regal
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarRegalById"] ) ) {
			$stmt->bind_param("d", $idRegal);
			$stmt->execute();
			$stmt->bind_result($nomCurs, $codiCurs, $nomC, $nifC,
				$mailC, $adrecaC, $pobleC, $cpC, $codiRegal, $factRel, $origen, $desti);
			$stmt->fetch();
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4231);
		}

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarLastFact"] ) ) {
			$stmt->execute();
			$stmt->bind_result($lastFactRel);
			$stmt->store_result();
			if ( $stmt->num_rows() > 0 ) {
				$stmt->fetch();
				$factura = intval($lastFactRel)+1;
			}
			else {
				$factura = 1;
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4232);
		}

		// Calculem la rao de la factura
		$rao = $nomC;
		$cif = $nifC;

		// Calculem el concepte 1 i el concepte 2 de la factura
		$concepte1 = "Curs regal ".$nomCurs;
		$concepte2 = "Codi ".$codiRegal;

		if (intval($codiCurs)==0) {
			//Buscar les hores del codi curs $codiCurs
			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarHoresCursGen"] ) ) {
				$stmt->bind_param("s", $codiCurs);
				$stmt->execute();
				$stmt->store_result();
				if ( $stmt->num_rows() > 0 ) {
					$stmt->bind_result($hores);
					$stmt->fetch();
				}
				else {
					$conWeb->closeStmt();
					if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarHoresLastEd"] ) ) {
						$stmt->bind_param("s", $codiCurs);
						$stmt->execute();
						$stmt->bind_result($hores);
						$stmt->fetch();
						$conWeb->closeStmt();
					}
					else {
						throw new Exception('',4235);
					}
					if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarParamOrder"] ) ) {
						$stmt->bind_param("ss", $tipus, $orderBy);
						$tipus='dies-inscriu-cursos';
						$orderBy='VALOR';
						$stmt->execute();
						$stmt->bind_result($valor);
						$diesObets=0;
						while ( $stmt->fetch() ) {
							$valors = explode('|',$valor);
							if (count($valors) != 2)
								$diesObets=0;
							else if (intval($valors[0])>0 && $valors[0]==$hores) //si el valor és un numero i les hores son iguals al curs
								$diesObets = $valors[1];
							else if (intval($valors[0])<=0 && $valors[0]==$codiCurs) //si el valor no és un numero i el codi és igual al curs
								$diesObets = $valors[1];
						}
						$conWeb->closeStmt();
					}
					else {
						throw new Exception('',4236);
					}
					if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarHoresCurs"] ) ) {
						$stmt->bind_param("ds", $diesObets, $codiCurs);
						$stmt->execute();
						$stmt->store_result;
						if ( $stmt->num_rows() > 0 ) {
							$stmt->bind_result($hores);
							$stmt->fetch();
						}
					}
					else {
						throw new Exception('',4237);
					}


				}
				$conWeb->closeStmt();
			}
			else {
				throw new Exception('',4234);
			}
		}
		else {
			$hores = intval($codiCurs);
		}

		$numComanda = NULL;
		$observacions = NULL;
		$efact = 0;

		if ( $factRel == 0 ) { //No ha pagat
			/* ##########     Afegir la factua a la taula FACTURES     ########## */
			if ( $stmtInsert=$conWeb->prepare( $this->consultesBD_Web["insertFacturaAut"] ) ) {
				$stmtInsert->bind_param("dsddsssdsssssssdsssdsd",
					$factura, $tipusFact, $anyFiscal, $ordreFact, $numFact, $dataActual, $dataPagament,
					$numComanda, $rao, $cif, $adrecaC, $cpC, $pobleC, $concepte1, $concepte2,
					$importPag, $entitat, $formaPagament, $codiCurs, $hores, $observacions, $efact);
				$stmtInsert->execute();
				$conWeb->closeStmt();

				$mostrar .= "<p>S'ha generat la factura relacionada <strong id='factura-creada'>".$factura."</strong></p>";
			}
			else {
				throw new Exception('',4233);
			}

			/* ########## Actualitzar el registre del regal amb la factura utilitzada ########## */
			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["updFactRegal"] ) ) {
				$stmt->bind_param("dd", $factura, $idRegal);
				$stmt->execute();
				$conWeb->closeStmt();
			}
			else {
				throw new Exception('',4238);
			}

			/* ########## Buscar el username i el password d'autentificació de prisma ########## */
			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarParam"] ) ) {
				$stmt->bind_param("s", $tipusParam);
				$tipusParam = 'autentificacioPagament';
				$stmt->execute();
				$stmt->bind_result($valor);
				$stmt->fetch();

				$autentificacioInscripcio = explode('|',$valor);
				$username = $autentificacioInscripcio[0];
				$password = $autentificacioInscripcio[1];
				$nameUser = $autentificacioInscripcio[2];

				$conWeb->closeStmt();
			}
			else {
				throw new Exception('',4239);
			}

			/* ########## Missatge de confirmació de pagament ########## */
			$subject = "Confirmació de pagament del val regal ".$codiRegal;

			$missatge = "<p>Benvolgut/da ".$nomC.",</p>
			<p>
				Hem rebut correctament el teu pagament per al val regal
				amb el codi <strong>".$codiRegal."</strong>.
			</p>
			<p>
				En <a title='Targeta regal. Versió digital'
					 href=\"https://www.prisma.cat/targetes-regal/".$codiRegal."_targeta_regal_versio_digital.pdf\">
					 aquest enllaç</a> trobaràs la targeta regal en format PDF.
			</p>
			<p>Et recordem que el codi té una validesa d’un any des
			de la compra de la targeta regal.</p>
			<p>Gràcies per haver escollit regalar un dels nostres cursos!</p>";

			$qui = $this->usuari->getNom()->get()." ".$this->usuari->getCognom()->get();
			$depart = $this->usuari->getDepart()->get();

			$nomFromHead = $nameUser;
			$correuFromHead = $username;
			$nomReplyHead = $nameUser;
			$correuReplyHead = $username;

			$nomTo = $nameUser;
			$correuTo = 'resguard.gestio@prisma.cat';

			require_once "MailSMTPComvive.php";

			//enviar un email de confirmacio a gestio@prisma.cat
			$mailAlumne = new MailSMTPComvive($username, $password, $nomFromHead, $correuFromHead,
												$nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
												$subject, $missatge, $qui, $depart);

			$nomTo = $nomC;
			$correuTo = $mailC;

			//enviar un email  de confirmacio a la persona que ha fet la compra
			$mailAlumne = new MailSMTPComvive($username, $password, $nomFromHead, $correuFromHead,
												$nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
												$subject, $missatge, $qui, $depart);
		}

		$conWeb->desconectarBD();

	}

	private function efectuarPagamentGrupal($idPag, $obs,
	$anyFiscal, $tipusFact, $ordreFact, $numFact, $dataActual, $dataPagament, $importPag, $entitat, $formaPagament) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		$objDatePag = new Date($dataPagament);
		$dataPagamentDDMMYY = $objDatePag->getDataFomatDDMMYYYY_HHMMSS();

		/* ##################    Consultem les dades de   ##################
			##################    la persona responsable   ################## */

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarPersRespGrup"] ) ) {
			$stmt->bind_param("d", $idPag);
			$stmt->execute();
			$stmt->bind_result($nomResp, $cognomsResp, $dniResp, $emailResp,
				$adrecaResp, $cpResp, $pobleResp, $factRel, $fracc, $fraccio, $apagar, $importPagat);
			$stmt->fetch();
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4240);
		}

		$pendentPagar = $apagar - $importPagat - $importPag;
		if ( $pendentPagar > 0 )
			$fracc = 1;

		/* ##################    Consultem les dades de    ##################
			##################       l'edició del curs      ################## */

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarInfoEdGrup"] ) ) {
			$stmt->bind_param("d", $idPag);
			$stmt->execute();
			$stmt->bind_result($anyEdicio, $mesEdicio, $codiCurs, $titol, $horesEd,
				$datai, $dataf);
			$stmt->fetch();
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4241);
		}

		require_once 'Date.php';

		/* Obtinc la data d'inici i la data de fi en lletres */
		$objDataI = new Date($datai);
		$dataIniciLlarga = $objDataI->getDataLlarga();
		$objDataF = new Date($dataf);
		$dataFiLlarga = $objDataF->getDataLlarga();

		/* ##################     Generem la factura     #################### */

		/* Obtinc el mes en lletres */
		$objMes = new Date("01-".$mesEdicio."-2021");
		$mesEdicioEscrit = $objMes->getNomMes();

		/* ********* Calculem el número de la factura relacionada ********* */
		if ( $factRel == null or $factRel == '' ) { //l'alumne no ha pagat res
			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarLastFact"] ) ) {
				$stmt->execute();
				$stmt->bind_result($lastFactRel);
				$stmt->store_result();
				if ( $stmt->num_rows() > 0 ) {
					$stmt->fetch();
					$factura = intval($lastFactRel)+1;
				}
				else {
					$factura = 1;
				}
				$conWeb->closeStmt();
			}
			else {
				throw new Exception('',4242);
			}
		}
		else { //l'alumne havia pagat alguna cosa
			$factura = $factRel;
		}

		/* ********* Calculem la rao de la factura ********* */
		$rao = $nomResp." ".$cognomsResp;
		$cif = $dniResp;

		/* ********* Calculem el concepte 1 i el concepte 2 de la factura ********* */
		$concepte1 = "Curs ".$titol;
		$concepte2 = "Convocatòria ".$mesEdicioEscrit." ".$anyEdicio;

		$cp = $cpResp;
		$adreca = $adrecaResp;
		$poble = $pobleResp;
		$hores = $horesEd;
		$numComanda = NULL;
		$observacions = NULL;
		$efact = 0;

		/* ##########     Afegir la factua a la taula FACTURES     ########## */
		if ( $stmtInsert=$conWeb->prepare( $this->consultesBD_Web["insertFacturaAut"] ) ) {
			$stmtInsert->bind_param("dsddsssdsssssssdsssdsd",
				$factura, $tipusFact, $anyFiscal, $ordreFact, $numFact, $dataActual, $dataPagament,
				$numComanda, $rao, $cif, $adreca, $cp, $poble, $concepte1, $concepte2,
				$importPag, $entitat, $formaPagament, $codiCurs, $hores, $observacions, $efact);
			$stmtInsert->execute();
			$conWeb->closeStmt();

			$mostrar .= "<p>S'ha generat la factura relacionada <strong id='factura-creada'>".$factura."</strong></p>";
		}
		else {
			throw new Exception('',4243);
		}

		/* ##################  Actualitzem inscripcions  #################### */

		/* Busco tots els registres que tenen IDPAG $idpag i estiguin inscrits.
		Mentre hi hagi registre i $auxPag > 0,
				si auxPag >= apagar-pagat d'aquest registre,
					fer un update del registre i posar que pagat APAGAR i la factura relacionada $factura i la DATA PAGAMENT actual
					AUXPAG -= (apagar-pagat)
				else
					fer un update del registre i posar que pagat PAGAT+AUXPAG i la factura relacionada $factura
					auxPag -= (auxpag)
		*/
		$conWeb2 = new ConnexioWeb();
		$conWeb2->connectarBD();

		$auxPagat = floatval($importPag);

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["searchMembresGrup"] ) ) {
			$stmt->bind_param("sd", $tipusInsc, $idPag);
			$tipusInsc = 'G';
			$stmt->execute();
			$stmt->bind_result($id, $aPagarMembre, $pagamentMembre, $factMembre); $i=0;
			while ( $stmt->fetch() && $auxPagat > 0 ) {
				if ( $auxPagat < ($aPagarMembre - $pagamentMembre) ) {
					$pagat = floatval($auxPagat);
					$auxPagat -= floatval($auxPagat);
				}
				else {
					$pagat = floatval($aPagarMembre);
					$auxPagat -= floatval($aPagarMembre - $pagamentMembre);
				}
				if ( $stmtUpd=$conWeb2->prepare( $this->consultesBD_Web["updPayInscr"] ) ) {
					$stmtUpd->bind_param("ddd", $pagat, $factura, $id);
					$stmtUpd->execute();
					$conWeb2->closeStmt();
				}
				else {
					throw new Exception('',4245);
				}

				$pagat2 = number_format($pagat,2);
				$aPagarMembre2 = number_format($aPagarMembre,2);

				if ( floatval($pagat2) >= floatval($aPagarMembre2) ) {
					if ( $stmtUpd=$conWeb2->prepare( $this->consultesBD_Web["updDateInscr"] ) ) {
						$stmtUpd->bind_param("sd", $dataPagament, $id);
						$stmtUpd->execute();
						$conWeb2->closeStmt();

					}
					else {
						throw new Exception('',4246);
					}
				}
				$i++;
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception ('', 4244);
		}
		$conWeb2->desconectarBD();

		if ( $fracc == 1 ) {
			if ( $fraccio!=null && $fraccio!='' )
				$fraccio.="\n";

			$fraccio .= "(".$importPag." € ".$dataPagamentDDMMYY.")";

			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["updFraccBD"] ) ) {
				$stmt->bind_param("sd", $fraccio, $idPag);
				$stmt->execute();
				$conWeb->closeStmt();
			}
			else {
				throw new Exception('',4256);
			}
		}

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarParam"] ) ) {
			$stmt->bind_param("s", $tipusParam);

			/* ########## Buscar el username i el password d'autentificació de prisma ########## */
			$tipusParam = 'autentificacioPagament';
			$stmt->execute();
			$stmt->bind_result($valor);
			$stmt->fetch();

			$autentificacioInscripcio = explode('|',$valor);
			$username = $autentificacioInscripcio[0];
			$password = $autentificacioInscripcio[1];
			$nameUser = $autentificacioInscripcio[2];

			/* ##########           Calculem la url de pagament           ########## */
			$tipusParam = 'keyEncriptar';
			$stmt->execute();
			$stmt->bind_result($keyEncr);
			$stmt->fetch();

			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4247);
		}

		$cipher = "AES-128-CBC";

		$ivlen = openssl_cipher_iv_length($cipher);
		$iv = openssl_random_pseudo_bytes($ivlen);
		$ciphertext_raw = openssl_encrypt($idPag, $cipher, $keyEncr, $options=OPENSSL_RAW_DATA, $iv);
		$hmac = hash_hmac('sha256', $ciphertext_raw, $keyEncr, $as_binary=true);
		$hashIdPag = base64_encode( $iv.$hmac.$ciphertext_raw );

		$urlPagament = "https://www.prisma.cat/pagaments/".$hashIdPag;

		$conWeb->desconectarBD();

		/* ##################  Missatge de confirmació de pagament ################## */
		$subject = "Confirmació matrícula ".$titol." | ".$dataPagamentDDMMYY;

		$textPagamentFraccionat="";

		if ( $fraccionat == 1 )  {
			$pagats = $importPag + $importPagat;
			if ( $pendentPagar > 0 ) {
				$textPagamentFraccionat = "<p>A data d'avui estan pagats <strong>".$pagats." €</strong> del total que són <strong>".$apagar." €</strong>.</p>";
				$textPendentPagar1 = "<p><strong>Pendent de pagar:</strong> ".$pendentPagar." € de ".$apagar."€</p>";
				$textPendentPagar2 = "<p>Et recordem l'enllaç per fer els pagaments posteriors: <a href='$urlPagament' title='Pagament del grup ".$titol."'>".$urlPagament."</a></p>";
			}
			else {
				$textPagamentFraccionat = "<p>A data d'avui el <em>pack</em> està pagat en la seva totalitat.</p>";
			}
		}

		$missatge = "<p>Benvolgut/da ".$nomResp.",</p>

		<p>Hem rebut correctament el pagament de la matrícula del curs <strong style='color: #496baa'>".$titol."</strong> que es
		realitza <strong>".$this->__mostrarDatesIniciFi($datai, $dataf)."</strong> ".$textPagamentFraccionat."</p>

		<div style='background-color: #e8ecf5; border: 1px solid #D7DEEE; border-radius: 2px; padding: 5px 25px; margin-bottom: 20px'>
			<p><strong>Concepte:</strong> ".$dniResp." | ".$titol."</p>
			<p><strong>Correu electrònic: </strong> ".$emailResp."</p>
			<p><strong>Import:</strong> ".$importPag." €</p>
			<p><strong>Resultat:</strong> Acceptat</p>
			<p><strong>Data:</strong> ".$dataPagamentDDMMYY."</p>
			".$textPendentPagar1."
		</div>
		".$textPendentPagar2."

		<p>Per a qualsevol consulta, no dubtis a posar-te en contacte amb nosaltres.</p>

		<p>Salutacions ben cordials,</p>";

		require_once "MailSMTPComvive.php";

		$qui = $this->usuari->getNom()->get()." ".$this->usuari->getCognom()->get();
		$depart = $this->usuari->getDepart()->get();

		$nomFromHead = $nameUser;
		$correuFromHead = $username;
		$nomReplyHead = $nameUser;
		$correuReplyHead = $username;

		$nomTo = $nameUser;
		$correuTo = 'resguard.gestio@prisma.cat';

		$mailCopia = new MailSMTPComvive($username, $password, $nomFromHead, $correuFromHead,
											$nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
											$subject, $missatge, $qui, $depart);

		/* ################## Enviar confirmació a l'alumne ################## */
		$nomTo = $nomResp;
		$correuTo = $emailResp;

		//enviar un email a la persona que ha fet la compra
		$mailAlumne = new MailSMTPComvive($username, $password, $nomFromHead, $correuFromHead,
											$nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
											$subject, $missatge, $qui, $depart);
	}

	private function efectuarPagamentPack($idPag, $obs,
	$anyFiscal, $tipusFact, $ordreFact, $numFact, $dataActual, $dataPagament, $importPag, $entitat, $formaPagament) {

		/* ##################    Consultem les dades de   ##################
			##################    la inscripicó del pack   ################## */

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		$objDatePag = new Date($dataPagament);
		$dataPagamentDDMMYY = $objDatePag->getDataFomatDDMMYYYY_HHMMSS();

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["cnsInscsPack"] ) ) {
			$stmt->bind_param("d", $idPag);
			$stmt->execute();
			$stmt->bind_result($nom, $cognoms, $dni, $email, $adreca, $cp,
			$poble, $factRel, $apagar, $inscrit, $importPagat, $fraccio, $fracc,
			$observacions, $pagOBs);
			$stmt->fetch();
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4248);
		}

		$pendentPagar = $apagar - $importPagat - $importPag;
		if ( $pendentPagar > 0 ) $fracc = 1;

		$arrObs = explode(' ',$observacions);
		$i = 0; $trobat = 0;
		while ( $i < count($arrObs) && !$trobat ) {
			if ( explode('|', $arrObs[$i])[0] == 'PACK' ) {
				$idPack = explode('|', $arrObs[$i])[1];
				$trobat = 1;
			}
			$i++;
		}

		$codiPack = "P".$idPack;

		/* ################## Consultem les edicions del pack ################## */
		$textEdicions = "";

		$conWeb2 = new ConnexioWeb();
		$conWeb2->connectarBD();

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["cnsDadesCursPack"] ) ) {
			$stmt->bind_param("d", $idPack);
			$stmt->execute();
			$stmt->store_result();
			if ( $stmt->num_rows() > 0 ) {
				$cnt = 0;

				$stmt->bind_result($dataiEd, $datafEd, $cursEscEd, $fissEd, $gtafEd,
					$dataResEd, $anyEd, $mesEd, $cursEd, $horesEd, $idInfoEd, $idUrlCurs, $titolCurs, $estatEd, $titolPack);
				$datesRealitzacioCursos = "<ul style='list-style: square; margin-bottom: 20px; margin-left: 30px; padding: 0;'>";
				while ( $stmt->fetch() ) {

					if ( $stmt2=$conWeb2->prepare( $this->consultesBD_Web["buscarDadesUrlAmig"] ) ) {
						$stmt2->bind_param("d", $idUrlCurs);
						$stmt2->execute();
						$stmt2->bind_result($name, $title, $target, $url);
						$stmt2->fetch();
						$conWeb2->closeStmt();
					}
					else {
						throw new Exception('',4259);
					}

					$linkCurs="https://www.prisma.cat".$url;

					$dataI = new Date($dataiEd);
			      $dataIL = $dataI->getDataLlarga();

					$objDataF = new Date($datafEd);
					$dataFL = $objDataF->getDataLlarga();
					$diaDataF = $objDataF->getDia();
			      if ( $diaDataF == "1" or $diaDataF == "11" ) $dataFPref = " a l'".$dataFL;
			      else $dataFPref = " al ".$dataFL;

					$liCurs = "<a style='color: #496BAA; text-decoration: none; font-weight: bold;'
					href='".$linkCurs."' target='_blank'>
			      ".$titolCurs."</a> de ".$horesEd." hores de durada que es realitza ".$this->__mostrarDatesIniciFi($dataiEd, $datafEd).".";

					$datesRealitzacioCursos .= "<li style='margin-top: 8px; line-height: 24px;'>".$liCurs."</li>";

					// if ($textEdicions != "" ) {
					// 	$textEdicions .= "<br />";
					// 	$datai = $dataiEd;
					// }
					if ($textEdicions != "" ) {
						$textEdicions .= "<br />";
					}
					else {
						$datai = $dataiEd;
					}
					$textEdicions .= $titolCurs." (".$mesEd."/".$anyEd.")";

					$cnt++;
				}
				$datesRealitzacioCursos .= "</ul>";
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4249);
		}
		$conWeb2->desconectarBD();


		/* Busco la data d'inici de la pimera edició i la data de fi de l'última edició */
		$dataf = $datafEd;

		$dateDataF = new DateTime($dataf);
		$diaDataF=$dateDataF->format('j');
		$dataFPref = $dataFL;
		if ( $diaDataF == "1" or $diaDataF == "11" ) $dataFPref = "l'".$dataFL;
		else $dataFPref = "el ".$dataFL;

		$titol = $titolPack;

		/* ##################     Generem la factura     #################### */

		/* ********* Calculem el número de la factura relacionada ********* */
		if ( $factRel == null or $factRel == '' ) { //l'alumne no ha pagat res
			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarLastFact"] ) ) {
				$stmt->execute();
				$stmt->bind_result($lastFactRel);
				$stmt->store_result();
				if ( $stmt->num_rows() > 0 ) {
					$stmt->fetch();
					$factura = intval($lastFactRel)+1;
				}
				else {
					$factura = 1;
				}
				$conWeb->closeStmt();
			}
			else {
				throw new Exception('',4250);
			}
		}
		else { //l'alumne havia pagat alguna cosa
			$factura = $factRel;
		}

		/* ********* Calculem la rao de la factura ********* */
		$rao = $nom." ".$cognoms;
		$cif = $dni;

		$textFactura = "";
		if ( $fracc == 1 ) {
			$textFactura=". Pagament fraccionat";
		}

		/* ********* Calculem el concepte 1 i el concepte 2 de la factura ********* */
		$concepte1 = "Pack ".$titol;
		$concepte2 = $textEdicions;

		$hores = 0;
		$numComanda = NULL;
		$observacions = NULL;
		$efact = 0;

		/* ##########     Afegir la factua a la taula FACTURES     ########## */
		if ( $stmtInsert=$conWeb->prepare( $this->consultesBD_Web["insertFacturaAut"] ) ) {
			$stmtInsert->bind_param("dsddsssdsssssssdsssdsd",
				$factura, $tipusFact, $anyFiscal, $ordreFact, $numFact, $dataActual, $dataPagament,
				$numComanda, $rao, $cif, $adreca, $cp, $poble, $concepte1, $concepte2,
				$importPag, $entitat, $formaPagament, $codiPack, $hores, $observacions, $efact);
			$stmtInsert->execute();
			$conWeb->closeStmt();

			$mostrar .= "<p>S'ha generat la factura relacionada <strong id='factura-creada'>".$factura."</strong></p>";
		}
		else {
			throw new Exception('',4251);
		}

		/* ##################  Actualitzem inscripcions  #################### */
		$conWeb2 = new ConnexioWeb();
		$conWeb2->connectarBD();

		$auxPagat = floatval($importPag);

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["searchMembresGrup"] ) ) {
			$stmt->bind_param("sd", $tipusInsc, $idPag);
			$tipusInsc = 'P';
			$stmt->execute();
			$stmt->bind_result($id, $aPagarMembre, $pagamentMembre, $factMembre); $i=0;
			while ( $stmt->fetch() && $auxPagat > 0 ) {
				if ( $auxPagat < ($aPagarMembre - $pagamentMembre) ) {
					$pagat = floatval($auxPagat);
					$auxPagat -= floatval($auxPagat);
				}
				else {
					$pagat = floatval($aPagarMembre);
					$auxPagat -= floatval($aPagarMembre - $pagamentMembre);
				}

				if ( $factMembre != null && $factMembre!='') {
					if ( $stmtUpd=$conWeb2->prepare( $this->consultesBD_Web["updPayInscr2"] ) ) {
						$stmtUpd->bind_param("dd", $pagat, $id);
						$stmtUpd->execute();
						$conWeb2->closeStmt();
					}
					else {
						throw new Exception('',4254);
					}
				}
				else {
					if ( $stmtUpd=$conWeb2->prepare( $this->consultesBD_Web["updPayInscr2"] ) ) {
						$stmtUpd->bind_param("dd", $pagat, $id);
						$stmtUpd->execute();
						$conWeb2->closeStmt();
					}
					else {
						throw new Exception('',4253);
					}
					if ( $stmtUpd=$conWeb2->prepare( $this->consultesBD_Web["updFactInscr"] ) ) {
						$stmtUpd->bind_param("dd", $factura, $idPag);
						$stmtUpd->execute();
						$conWeb2->closeStmt();
					}
					else {
						throw new Exception('',4253);
					}
				}

				$pagat2 = number_format($pagat,2);
				$aPagarMembre2 = number_format($aPagarMembre,2);

				if ( floatval($pagat2) >= floatval($aPagarMembre2) ) {
					if ( $stmtUpd=$conWeb2->prepare( $this->consultesBD_Web["updDateInscr"] ) ) {
						$stmtUpd->bind_param("sd", $dataPagament, $id);
						$stmtUpd->execute();
						$conWeb2->closeStmt();
					}
					else {
						throw new Exception('',4255);
					}
				}
				$i++;
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception ('', 4252);
		}
		$conWeb2->desconectarBD();

		if ( $fracc == 1 ) {
			if ( $fraccio!=null && $fraccio!='' )
				$fraccio.="\n";

			$fraccio .= "(".$importPag." € ".$dataPagamentDDMMYY.")";

			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["updFraccBD"] ) ) {
				$stmt->bind_param("sd", $fraccio, $idPag);
				$stmt->execute();
				$conWeb->closeStmt();
			}
			else {
				throw new Exception('',4256);
			}
		}

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarParam"] ) ) {
			$stmt->bind_param("s", $tipusParam);

			/* ########## Buscar el username i el password d'autentificació de prisma ########## */
			$tipusParam = 'autentificacioPagament';
			$stmt->execute();
			$stmt->bind_result($valor);
			$stmt->fetch();

			$autentificacioInscripcio = explode('|',$valor);
			$username = $autentificacioInscripcio[0];
			$password = $autentificacioInscripcio[1];
			$nameUser = $autentificacioInscripcio[2];

			/* ##########           Calculem la url de pagament           ########## */
			$tipusParam = 'keyEncriptar';
			$stmt->execute();
			$stmt->bind_result($keyEncr);
			$stmt->fetch();

			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4257);
		}

		$cipher = "AES-128-CBC";

		$ivlen = openssl_cipher_iv_length($cipher);
		$iv = openssl_random_pseudo_bytes($ivlen);
		$ciphertext_raw = openssl_encrypt($idPag, $cipher, $keyEncr, $options=OPENSSL_RAW_DATA, $iv);
		$hmac = hash_hmac('sha256', $ciphertext_raw, $keyEncr, $as_binary=true);
		$hashIdPag = base64_encode( $iv.$hmac.$ciphertext_raw );

		$urlPagament = "https://www.prisma.cat/pagaments/".$hashIdPag;

		/* ##################  Missatge de confirmació de pagament ################## */

		/* Calculem la diferència en dies entre la data d'avui i la data d'inici.
		Si la diferència es positiva vol dir que la data d'inici  és posterior a l'actual */
		$date1 = new DateTime("now");
		$date2 = new DateTime($datai);
		$diffInici = intval($date1->diff($date2)->days);
		$signe = $date1->diff($date2)->format('%R');
		if ($signe == "-") $diffInici = 0 - $diffInici;

		if ( $diffInici > 0 ) $cursHaComencat = 0;
		else $cursHaComencat = 1;

		/* Calculem la diferència en dies entre la data d'avui i la data de fi.
		Si la diferència es positiva vol dir que la data de fi és posterior a l'actual */
		$date1 = new DateTime("now");
		$date2 = new DateTime($dataf);
		$diffFi = intval($date1->diff($date2)->days);
		$signe = $date1->diff($date2)->format('%R');
		if ($signe == "-") $diffFi = 0 - $diffFi;

		if ( $diffFi >= 0 ) $cursHaAcabat = 0;
		else $cursHaAcabat = 1;

		$inscripcioOberta = false;

		/* Obtinc la data d'inici i la data de fi en lletres */
		$objDataI = new Date($datai);
		$dataIniciLlarga = $objDataI->getDataLlarga();
		$objDataF = new Date($dataf);
		$dataFiLlarga = $objDataF->getDataLlarga();

		if ( !$cursHaAcabat ) {
			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarParam"] ) ) {
				$stmt->bind_param("ss", $tipusParam, $valorParam);
				$tipusParam='dies-inscriu-cursos';
				$valorParam=$hores.'%';
				$stmt->execute();
				$stmt->bind_result($valor);
				$stmt->fetch();
				$conWeb->closeStmt();

				$diesOberts = explode('|',$valor)[1];

				if ( !$cursHaComencat || ( $cursHaComencat && $diffInici > 0-intval($diesOberts) && $diffInici <=0 ) )
					$inscripcioOberta = true;
			}
			else {
				throw new Exception('',4258);
			}
		}

		$conWeb->desconectarBD();

		/* Calculem els texts del correu que enviarem a l'alumne */
		$textPendentPagar1="";
		$textPendentPagar2="";
		$textPagamentFraccionat="";
		$textDadesAccesCampus="";
		$textCursNoHaComencat="";

		if ( $fracc == 1 )  {
			$pagats = $importPag + $importPagat;
			if ( $pendentPagar > 0 ) {
				$textPagamentFraccionat = "<p>A data d'avui estan pagats <strong>".$pagats." €</strong> del total del <em>pack</em> que són <strong>".$apagar." €</strong>.</p>";
				$textPendentPagar1 = "<p><strong>Pendent de pagar:</strong> ".$pendentPagar." € de ".$apagar."€</p>";
				$textPendentPagar2 = "<p>Et recordem l'enllaç per fer els pagaments posteriors: <a href='$urlPagament' title='Pagament del pack ".$titol."'>".$urlPagament."</a></p>";
			}
			else {
				$textPagamentFraccionat = "<p>A data d'avui el <em>pack</em> està pagat en la seva totalitat.</p>";
			}
		}

		if ( $cursHaComencat && $inscrit == '0' ) {
			$textCursNoHaComencat = "<p>En menys de 24 hores laborables podeu accedir al primer curs.</p>";
		}

		if ( !$cursHaComencat || ($cursHaComencat && $inscripcioOberta) ) {
			if (!$cursHaComencat)
				$textRebut = "rebreu";
			else
				$textRebut = "heu rebut";

			$textDadesAccesCampus = "<p>Els alumnes que:</p>
				<ul style='list-style: square; margin-bottom: 20px; margin-left: 30px; padding: 0;'>
					<li style='margin-top: 8px; line-height: 24px;'><strong>Feu per primera vegada
					un curs amb nosaltres</strong>, ".$textRebut." un correu electrònic amb el vostre
					nom d'usuari i contrasenya per accedir al campus virtual.</li>
					<li style='margin-top: 8px; line-height: 24px;'><strong>Ja havíeu fet algun
					curs amb nosaltres</strong>, heu d'utilitzar el nom i la contrasenya que
					ja teniu. En cas que no els recordeu, podeu clicar <a target='_blank'
					href='http://www.prisma.cat/campus/login/forgot_password.php'
					itle='Has oblidat la contrasenya?'>aquí</a> per	demanar-nos-els.</li>
				</ul>
				<p>Quan entris al campus amb el teu <strong>usuari</strong> i
				<strong>contrasenya</strong>, trobaràs
				el primer curs del <em>pack</em> al bloc «Els meus cursos».</p>";
		}

		if ( !$cursHaComencat ) {
			$textDadesAccesCampus .= "<p>Et recordem que aquest espai no estarà
			plenament actiu fins a la data d'inici marcada en el calendari del primer curs,
			que serà ".$objDataI->getPronomEl()."<strong>".$objDataI->getDataLlarga()."</strong>.</p>
			<p>Uns dies abans de l'inici de cada curs ja podràs entrar a l'aula per
			visualitzar el material de lectura.</p>";
		}

		$missatge = "<p>Benvolgut/da ".$nom.",</p>

		<p>Hem rebut correctament el pagament de la matrícula del <em>pack</em> <strong style='color: #496baa'>".$titol."</strong> que que consta dels cursos següents:</p>
		".$datesRealitzacioCursos."
		".$textPagamentFraccionat."

		<div style='background-color: #e8ecf5; border: 1px solid #D7DEEE; border-radius: 2px; padding: 5px 25px; margin-bottom: 20px'>
		<p><strong>Concepte:</strong> ".$dni." | ".$titol."</p>
		<p><strong>Correu electrònic: </strong> ".$email."</p>
		<p><strong>Import:</strong> ".$importPag." €</p>
		<p><strong>Resultat:</strong> Acceptat</p>
		<p><strong>Data:</strong> ".$dataPagamentDDMMYY."</p>
		".$textPendentPagar1."
		</div>
		".$textPendentPagar2."

		".$textCursNoHaComencat.$textDadesAccesCampus."

		<p>Per a qualsevol consulta, no dubtis a posar-te en contacte amb nosaltres.</p>

		<p>Salutacions ben cordials,</p>";

		$subject = "Confirmació matrícula ".$titol." | ".$dataPagamentDDMMYY;

		require_once "MailSMTPComvive.php";

		$qui = $this->usuari->getNom()->get()." ".$this->usuari->getCognom()->get();
		$depart = $this->usuari->getDepart()->get();

		/* ################## Enviar confirmació a PrisMa ################## */
		$nomFromHead = $nameUser;
		$correuFromHead = $username;
		$nomReplyHead = $nameUser;
		$correuReplyHead = $username;

		$nomTo = $nameUser;
		$correuTo = 'resguard.gestio@prisma.cat';
		// $correuTo = 'merimari051094@gmail.com';

		$mailAlumne = new MailSMTPComvive($username, $password, $nomFromHead, $correuFromHead,
											$nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
											$subject, $missatge, $qui, $depart);

		/* ################## Enviar confirmació a l'alumne ################## */
		$nomTo = $nom;
		$correuTo = $email;
		// $correuTo = 'meriem.music.051094@gmail.com';

		//enviar un email a la persona que ha fet la compra i a gestio@prisma.cat
		$mailAlumne = new MailSMTPComvive($username, $password, $nomFromHead, $correuFromHead,
											$nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
											$subject, $missatge, $qui, $depart);

	}

	private function efectuarPagamentInscripcio($idPag, $obs,
	$anyFiscal, $tipusFact, $ordreFact, $numFact, $dataActual, $dataPagament, $importPag, $entitat, $formaPagament) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		$objDatePag = new Date($dataPagament);
		$dataPagamentDDMMYY = $objDatePag->getDataFomatDDMMYYYY_HHMMSS();

		/* ##################    Consultem les dades de   ##################
		   ##################         la inscripció        ################## */

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarDadesCursAlByIdPag"] ) ) {
			$stmt->bind_param("d", $idPag);
			$stmt->execute();
			$stmt->bind_result($any, $mes, $codiCurs, $nom, $cognoms, $dni, $email,
			$adreca, $cp, $poble, $factRel, $apagar, $inscrit, $importPagat, $fraccio, $frac);
			$stmt->fetch();
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4260);
		}

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarCursSegEd"] ) ) {
			$stmt->bind_param("dss", $any, $mes, $codiCurs);
			$stmt->execute();
			$stmt->bind_result($titol, $datai, $dataf, $hores, $idPreu);
			$stmt->fetch();
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4261);
		}

		$fracc = intval($frac);

		$pendentPagar = 0;
		$pagats = floatval($importPagat)+floatval($importPag);

		if ( floatval($apagar) > $pagats ) {
			$pendentPagar = floatval($apagar) - $pagats;
		}
		if ( floatval($apagar) > floatval($importPag) ) {
			$fracc = 1;
		}

		/* ######################## Generem la factura ######################## */

		require_once 'Date.php';

		/* Obtinc la data d'inici i la data de fi en lletres */
		$objDataI = new Date($datai);
		$dataIniciLlarga = $objDataI->getDataLlarga();
		$objDataF = new Date($dataf);
		$dataFiLlarga = $objDataF->getDataLlarga();

		/* ********* Calculem el número de la factura relacionada ********* */
		if ( $factRel == null or $factRel == '' ) { //l'alumne no ha pagat res
			if ( $stmtFactRel=$conWeb->prepare( $this->consultesBD_Web["buscarLastFact"] ) ) {
				$stmtFactRel->execute();
				$stmtFactRel->bind_result($lastFactRel);
				$stmtFactRel->store_result();
				if ( $stmtFactRel->num_rows() > 0 ) {
					$stmtFactRel->fetch();
					$factura = intval($lastFactRel)+1;
				}
				else {
					$factura = 1;
				}
				$conWeb->closeStmt();
			}
			else {
				throw new Exception('',4262);
			}
		}
		else { //l'alumne havia pagat alguna cosa
			$factura = $factRel;
		}

		/* ********* Calculem la rao de la factura ********* */
		$rao = $nom." ".$cognoms;
		$cif = $dni;

		/* ********* Calculem el concepte 1 i el concepte 2 de la factura ********* */
		/* Obtinc el mes en lletres */
		$objMes = new Date("01-".$mes."-2021");
		$mesEdicioEscrit = $objMes->getNomMes();

		$textFactura = "";
		if ( $fracc == 1 ) {
			$textFactura=". Pagament fraccionat";
		}

		if ( ctype_alpha($codiCurs) ) { //Si el codi curs no té numeros es tracta d'un curs
			$concepte1 = "Curs ".$titol;
			$concepte2 = "Convocatòria ".$mesEdicioEscrit." ".$any.$textFactura;
		}
		else { //Si el codi curs té numeros es tracta d'una jornada
			$concepte1 = $titol;
			$concepte2 = "Convocatòria ".$dataIniciLlarga;
		}

		$numComanda = NULL;
		$observacions = NULL;
		$efact = 0;

		/* ##########     Afegir la factua a la taula FACTURES     ########## */
		if ( $stmtInsert=$conWeb->prepare( $this->consultesBD_Web["insertFacturaAut"] ) ) {
			$stmtInsert->bind_param("dsddsssdsssssssdsssdsd",
				$factura, $tipusFact, $anyFiscal, $ordreFact, $numFact, $dataActual, $dataPagament,
				$numComanda, $rao, $cif, $adreca, $cp, $poble, $concepte1, $concepte2,
				$importPag, $entitat, $formaPagament, $codiCurs, $hores, $observacions, $efact);
			$stmtInsert->execute();
			$conWeb->closeStmt();

			$mostrar = "<p>S'ha generat la factura relacionada <strong id='factura-creada'>".$factura."</strong></p>";
		}
		else {
			throw new Exception('',4262);
		}

		/* ##################  Actualitzem inscripcions  #################### */

		if ($factRel==null or $factRel=='') //No ha pagat
		{
			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["updPayInscrByIdPag"] ) ) {
				$stmt->bind_param("dds", $pagats, $factura, $idPag);
				$stmt->execute();
				$conWeb->closeStmt();
			}
			else {
				throw new Exception('',4263);
			}
		}
		else { // ja havia fet un pagament anterior
			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["updPayInscrByIdPag2"] ) ) {
				$stmt->bind_param("dd", $pagats, $idPag);
				$stmt->execute();
				$conWeb->closeStmt();
			}
			else {
				throw new Exception('',4264);
			}
		}

		$pagats2 = number_format($pagats,2);
		$apagar2 = number_format($apagar,2);

		if ( floatval($pagats2) >= floatval($apagar2) ) {
			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["updDateInscrByIdPag"] ) ) {
				$stmt->bind_param("sd", $dataPagament, $idPag);
				$stmt->execute();
				$conWeb->closeStmt();
			}
			else {
				throw new Exception('',4265);
			}
		}

		/* Actualitzem */
		if ( $fracc==1 ) {
			if ( $fraccio != null && $fraccio != '' )
				$fraccio.="\n";

			$fraccio .= "(".$importPag." € ".$dataPagamentDDMMYY.")";

			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["updFraccBD"] ) ) {
				$stmt->bind_param("sd", $fraccio, $idPag);
				$stmt->execute();
				$conWeb->closeStmt();
			}
			else {
				throw new Exception('',4266);
			}
		}

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarParam"] ) ) {
			$stmt->bind_param("s", $tipusParam);

			/* ########## Buscar el username i el password d'autentificació de prisma ########## */
			$tipusParam = 'autentificacioPagament';
			$stmt->execute();
			$stmt->bind_result($valor);
			$stmt->fetch();

			$autentificacioInscripcio = explode('|',$valor);
			$username = $autentificacioInscripcio[0];
			$password = $autentificacioInscripcio[1];
			$nameUser = $autentificacioInscripcio[2];

			/* ##########           Calculem la url de pagament           ########## */
			$tipusParam = 'keyEncriptar';
			$stmt->execute();
			$stmt->bind_result($keyEncr);
			$stmt->fetch();

			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4267);
		}

		$cipher = "AES-128-CBC";

		$ivlen = openssl_cipher_iv_length($cipher);
		$iv = openssl_random_pseudo_bytes($ivlen);
		$ciphertext_raw = openssl_encrypt($idPag, $cipher, $keyEncr, $options=OPENSSL_RAW_DATA, $iv);
		$hmac = hash_hmac('sha256', $ciphertext_raw, $keyEncr, $as_binary=true);
		$hashIdPag = base64_encode( $iv.$hmac.$ciphertext_raw );

		$urlPagament = "https://www.prisma.cat/pagament/".$hashIdPag;

		/* ##################### Missatge de confirmació de pagament #################### */

		/* Calculem la diferència en dies entre la data d'avui i la data d'inici.
		Si la diferència es positiva vol dir que la data d'inici  és posterior a l'actual */
		$date1 = new DateTime("now");
		$date2 = new DateTime($datai);
		$diffInici = intval($date1->diff($date2)->days);
		$signe = $date1->diff($date2)->format('%R');
		if ($signe == "-") $diffInici = 0 - $diffInici;

		if ( $diffInici > 0 ) $cursHaComencat = 0;
		else $cursHaComencat = 1;

		/* Calculem la diferència en dies entre la data d'avui i la data de fi.
		Si la diferència es positiva vol dir que la data de fi és posterior a l'actual */
		$date1 = new DateTime("now");
		$date2 = new DateTime($dataf);
		$diffFi = intval($date1->diff($date2)->days);
		$signe = $date1->diff($date2)->format('%R');
		if ($signe == "-") $diffFi = 0 - $diffFi;

		if ( $diffFi >= 0 ) $cursHaAcabat = 0;
		else $cursHaAcabat = 1;

		$inscripcioOberta = 0;

		/* Obtinc la data d'inici i la data de fi en lletres */
		$objDataI = new Date($datai);
		$dataIniciLlarga = $objDataI->getDataLlarga();
		$objDataF = new Date($dataf);
		$dataFiLlarga = $objDataF->getDataLlarga();

		if ( !$cursHaAcabat ) {
			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarParamValorOrder"] ) ) {
				$stmt->bind_param("sss", $tipusParam, $valorParam, $orderByPram);
				$tipusParam='dies-inscriu-cursos';
				$valorParam=$hores.'%';
				$orderByPram='VALOR';
				$stmt->execute();
				$stmt->bind_result($valor);
				$stmt->fetch();
				$conWeb->closeStmt();

				$diesOberts = explode('|',$valor)[1];

				if ( !$cursHaComencat || ( $cursHaComencat && $diffInici > 0-intval($diesOberts) && $diffInici <=0 ) )
					$inscripcioOberta = true;
			}
			else {
				throw new Exception('',4268);
			}
		}

		$conWeb->desconectarBD();

		/* Calculem els texts del correu que enviarem a l'alumne */
		$textPendentPagar1="";
		$textPendentPagar2="";
		$textPagamentFraccionat="";
		$textDadesAccesCampus="";
		$textCursNoHaComencat="";

		if ( $fracc == 1 )  {
			$pagats = $importPag + $importPagat;
			if ( $pendentPagar > 0 ) {
				$textPagamentFraccionat = "A data d'avui estan pagats <strong>".$pagats." €</strong> del total del curs que són <strong>".$apagar." €</strong>.";
				$textPendentPagar1 = "<p><strong>Pendent de pagar:</strong> ".$pendentPagar." € de ".$apagar."€</p>";
				$textPendentPagar2 = "<p>Et recordem l'enllaç per fer els pagaments posteriors: <a href='$urlPagament' title='Pagament del curs ".$titol."'>".$urlPagament."</a></p>";
			}
			else {
				$textPagamentFraccionat = "A data d'avui el curs està pagat en la seva totalitat.";
			}
		}

		if ( $cursHaComencat && $inscrit == '0' ) {
			$textCursNoHaComencat = "<p>En menys de 24 hores laborables podeu accedir al curs.</p>";
		}

		if ( !$cursHaComencat || ($cursHaComencat && $inscripcioOberta) ) {
			if (!$cursHaComencat)
				$textRebut = "rebreu";
			else
				$textRebut = "heu rebut";

			$textDadesAccesCampus = "<p>Els alumnes que:</p>
				<ul style='list-style: square; margin-bottom: 20px; margin-left: 30px; padding: 0;'>
					<li style='margin-top: 8px; line-height: 24px;'><strong>Feu per primera vegada
					un curs amb nosaltres</strong>, ".$textRebut." un correu electrònic amb el vostre
					nom d'usuari i contrasenya per accedir al campus virtual.</li>
					<li style='margin-top: 8px; line-height: 24px;'><strong>Ja havíeu fet algun
					curs amb nosaltres</strong>, heu d'utilitzar el nom i la contrasenya que
					ja teniu. En cas que no els recordeu, podeu clicar <a target='_blank'
					href='http://www.prisma.cat/campus/login/forgot_password.php'
					itle='Has oblidat la contrasenya?'>aquí</a> per	demanar-nos-els.</li>
				</ul>
				<p>Quan entris al campus amb el teu <strong>usuari</strong> i
				<strong>contrasenya</strong>, trobaràs
				el curs al bloc «Els meus cursos».</p>";
		}

		if ( !$cursHaComencat ) {
			$textDadesAccesCampus .= "<p>Et recordem que aquest espai no estarà
			plenament actiu fins a la data d'inici marcada en el calendari del curs,
			que serà ".$objDataI->getPronomEl()."<strong>".$objDataI->getDataLlarga()."</strong>.</p>
			<p>Uns dies abans de l'inici del curs ja podràs entrar a l'aula per
			visualitzar el material de lectura.</p>";
		}
		$missatge = "<p>Benvolgut/da ".$nom.",</p>

		<p>Hem rebut correctament el pagament de la matrícula del curs <strong style='color: #496baa'>".$titol."</strong> que es
		realitza ".$this->__mostrarDatesIniciFi($datai, $dataf).". ".$textPagamentFraccionat."</p>

		<div style='background-color: #e8ecf5; border: 1px solid #D7DEEE; border-radius: 2px; padding: 5px 25px; margin-bottom: 20px'>
		<p><strong>Concepte:</strong> ".$dni." | ".$titol."</p>
		<p><strong>Correu electrònic: </strong> ".$email."</p>
		<p><strong>Import:</strong> ".$importPag." €</p>
		<p><strong>Resultat:</strong> Acceptat</p>
		<p><strong>Data:</strong> ".$dataPagamentDDMMYY."</p>
		".$textPendentPagar1."
		</div>
		".$textPendentPagar2."

		".$textCursNoHaComencat.$textDadesAccesCampus."

		<p>Per a qualsevol consulta, no dubtis a posar-te en contacte amb nosaltres.</p>

		<p>Salutacions ben cordials,</p>";

		$subject = "Confirmació matrícula ".$titol." | ".$dataPagamentDDMMYY;

		require_once "MailSMTPComvive.php";

		$qui = $this->usuari->getNom()->get()." ".$this->usuari->getCognom()->get();
		$depart = $this->usuari->getDepart()->get();

		/* ################## Enviar confirmació a PrisMa ################## */
		$nomFromHead = $nameUser;
		$correuFromHead = $username;
		$nomReplyHead = $nameUser;
		$correuReplyHead = $username;
		$nomTo = $nameUser;
		$correuTo = 'resguard.gestio@prisma.cat';

		$mailAlumne = new MailSMTPComvive($username, $password, $nomFromHead, $correuFromHead,
											$nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
											$subject, $missatge, $qui, $depart);

		/* ################## Enviar confirmació a l'alumne ################## */
		$nomTo = $nom;
		$correuTo = $email;

		//enviar un email a la persona que ha fet la compra i a gestio@prisma.cat
		$mailAlumne = new MailSMTPComvive($username, $password, $nomFromHead, $correuFromHead,
											$nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
											$subject, $missatge, $qui, $depart);

		echo $mostrar;
	}

	private function efectuarPagamentFacturaGenerada($numFact, $tipusFact, $obs,
	$dataPagament, $importPag, $formaPagament) {
		echo $numFact."<br>".$tipusFact."<br>".$obs."<br>".$dataPagament."<br>".$importPag."<br>".$formaPagament."<br />";
		echo "---------------------------------------------------------------------------------------------<br />";
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		$conIntra = new ConnexioIntranet();
		$conIntra->connectarBD();

		$objDatePag = new Date($dataPagament);
		$dataPagamentDDMMYY = $objDatePag->getDataFomatDDMMYYYY_HHMMSS();

		/* ##################    Consultem les dades de   ##################
			##################    la persona que gestiona l'entitat   ################## */

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarPagamentsByFact"] ) ) {
			$stmt->bind_param("s", $numFact);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($tipus, $idInsc, $any, $mes, $curs, $apagar, $importPagat,
				$factura, $fraccionat, $fraccio, $pagObs, $idPag, $observacions, $dniProv, $efact);
				$stmt->fetch();
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4290);
		}

		echo $this->consultesBD_Web["buscarPagamentsByFact"]."<br />";
		echo $numFact."<br>".$tipusFact."<br>";
		echo $tipus."<br>".$idInsc."<br>".$any."<br>".$mes."<br>".$curs."<br>".$apagar."<br>".$importPagat."<br>".$factura."<br>".$fraccionat."<br>".$fraccio."<br>".$pagObs."<br>".$idPag."<br>".$dniProv."<br>".$efact."<br />";
		echo "---------------------------------------------------------------------------------------------<br />";

		if ( $stmt=$conIntra->prepare( $this->consultesBD_Intra["buscarRespEntitatByCIF"] ) ) {
			$stmt->bind_param("s", $dniProv);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($nomEnt, $nomResp, $cognomsResp, $emailResp);
				$stmt->fetch();
				$existeixEntitat = 1;
			}
			else {
				$existeixEntitat = 0;
			}
			$conIntra->closeStmt();
		}
		else {
			throw new Exception('',4289);
		}

		echo $this->consultesBD_Intra["buscarRespEntitatByCIF"]."<br />";
		echo $dniProv."<br>";
		echo $nomEnt."<br>".$nomResp."<br>".$cognomsResp."<br>".$emailResp."<br />";
		echo "---------------------------------------------------------------------------------------------<br />";

		/* Consolto el apagar i el pagat de les persones del pagament */
		$pendentPagar = $apagar - $importPagat - $importPag;
		if ( $pendentPagar > 0 )
			$fracc = 1;

		if ( $tipus == 'P' ) {
			$arrObs = explode(' ',$observacions);
			$i = 0; $trobat = 0;
			while ( $i < count($arrObs) && !$trobat ) {
				if ( explode('|', $arrObs[$i])[0] == 'PACK' ) {
					$idPack = explode('|', $arrObs[$i])[1];
					$trobat = 1;
				}
				$i++;
			}

			$codiPack = "P".$idPack;

			/* ################## Consultem les edicions del pack ################## */
			$textEdicions = "";

			$conWeb2 = new ConnexioWeb();
			$conWeb2->connectarBD();

			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["cnsDadesCursPack"] ) ) {
				$stmt->bind_param("d", $idPack);
				$stmt->execute();
				$stmt->store_result();
				if ( $stmt->num_rows() > 0 ) {
					$cnt = 0;

					$stmt->bind_result($dataiEd, $datafEd, $cursEscEd, $fissEd, $gtafEd,
						$dataResEd, $anyEd, $mesEd, $cursEd, $horesEd, $idInfoEd, $idUrlCurs, $titolCurs, $estatEd, $titolPack);
					$datesRealitzacioCursos = "<ul style='list-style: square; margin-bottom: 20px; margin-left: 30px; padding: 0;'>";
					while ( $stmt->fetch() ) {

						if ( $stmt2=$conWeb2->prepare( $this->consultesBD_Web["buscarDadesUrlAmig"] ) ) {
							$stmt2->bind_param("d", $idUrlCurs);
							$stmt2->execute();
							$stmt2->bind_result($name, $title, $target, $url);
							$stmt2->fetch();
							$conWeb2->closeStmt();
						}
						else {
							throw new Exception('',4300);
						}

						$linkCurs="https://www.prisma.cat".$url;

						$dataI = new Date($dataiEd);
				      $dataIL = $dataI->getDataLlarga();

						$objDataF = new Date($datafEd);
						$dataFL = $objDataF->getDataLlarga();
						$diaDataF = $objDataF->getDia();
				      if ( $diaDataF == "1" or $diaDataF == "11" ) $dataFPref = " a l'".$dataFL;
				      else $dataFPref = " al ".$dataFL;

						$datesRealitzacioCursos .= "<li style='margin-top: 8px; line-height: 24px;'>".$liCurs."</li>";

						if ($textEdicions != "" ) {
							$textEdicions .= "<br />";
							$datai = $dataiEd;
						}
						$textEdicions .= $titolCurs." (".$mesEd."/".$anyEd.")";

						$cnt++;
					}
					$datesRealitzacioCursos .= "</ul>";
				}
				$conWeb->closeStmt();
			}
			else {
				throw new Exception('',4299);
			}
			$conWeb2->desconectarBD();

			/* Busco la data d'inici de la pimera edició i la data de fi de l'última edició */
			$dataf = $datafEd;

			$dateDataF = new DateTime($dataf);
			$diaDataF=$dateDataF->format('j');
			$dataFPref = $dataFL;
			if ( $diaDataF == "1" or $diaDataF == "11" ) $dataFPref = "l'".$dataFL;
			else $dataFPref = "el ".$dataFL;

			$titol = $titolPack;
		}
		else {
			/* ##################    Consultem les dades de    ##################
				##################       l'edició del curs      ################## */

			echo $this->consultesBD_Web["buscarInfoEdGrupByFact"]."<br />";
			echo $factura."<br />";

			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarInfoEdGrupByFact"] ) ) {
				$stmt->bind_param("d", $factura);
				$stmt->execute();
				$stmt->bind_result($anyEdicio, $mesEdicio, $codiCurs, $titol, $horesEd,
					$datai, $dataf);
				$stmt->fetch();
				$conWeb->closeStmt();
			}
			else {
				throw new Exception('',4297);
			}
			echo $anyEdicio."<br>".$mesEdicio."<br>".$codiCurs."<br>".$titol."<br>".$horesEd."<br>".$datai."<br>".$dataf."<br />";
			echo "---------------------------------------------------------------------------------------------<br />";

			require_once 'Date.php';

			/* Obtinc la data d'inici i la data de fi en lletres */
			$objDataI = new Date($datai);
			$dataIniciLlarga = $objDataI->getDataLlarga();
			$objDataF = new Date($dataf);
			$dataFiLlarga = $objDataF->getDataLlarga();
		}


		/* ##################     Actualitzem la factura     #################### */

		echo $this->consultesBD_Web["updFactGenerada"]."<br />";
		echo $dataPagament."<br>".$importPag."<br />".$formaPagament."<br />".$numFact."<br />";
		echo "---------------------------------------------------------------------------------------------<br />";

		if ( $stmtInsert=$conWeb->prepare( $this->consultesBD_Web["updFactGenerada"] ) ) {
			$stmtInsert->bind_param("sdss", $dataPagament, $importPag, $formaPagament, $numFact);
			$stmtInsert->execute();
			$conWeb->closeStmt();

			$mostrar .= "<p>S'ha actualitzat la factura núm <strong id='factura-creada'>".$factura."</strong></p>";
		}
		else {
			throw new Exception('',4291);
		}

		/* ##################  Actualitzem inscripcions  #################### */

		/* Busco tots els registres que tenen IDPAG $idpag i estiguin inscrits.
		Mentre hi hagi registre i $auxPag > 0,
				si auxPag >= apagar-pagat d'aquest registre,
					fer un update del registre i posar que pagat APAGAR i la factura relacionada $factura i la DATA PAGAMENT actual
					AUXPAG -= (apagar-pagat)
				else
					fer un update del registre i posar que pagat PAGAT+AUXPAG i la factura relacionada $factura
					auxPag -= (auxpag)
		*/
		$conWeb2 = new ConnexioWeb();
		$conWeb2->connectarBD();

		$auxPagat = floatval($importPag);

		echo $this->consultesBD_Web["searchMembresFactRel"]."<br />";
		echo $factura."<br>";
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["searchMembresFactRel"] ) ) {
			$stmt->bind_param("d", $factura);
			$stmt->execute();
			$stmt->bind_result($id, $aPagarMembre, $pagamentMembre, $factMembre); $i=0;
			while ( $stmt->fetch() && $auxPagat > 0 ) {
				if ( $auxPagat < ($aPagarMembre - $pagamentMembre) ) {
					$pagat = floatval($auxPagat);
					$auxPagat -= floatval($auxPagat);
				}
				else {
					$pagat = floatval($aPagarMembre);
					$auxPagat -= floatval($aPagarMembre - $pagamentMembre);
				}
				if ( $stmtUpd=$conWeb2->prepare( $this->consultesBD_Web["updPayInscr"] ) ) {
					$stmtUpd->bind_param("ddd", $pagat, $factura, $id);
					$stmtUpd->execute();
					$conWeb2->closeStmt();
				}
				else {
					throw new Exception('',4292);
				}
				echo $this->consultesBD_Web["updPayInscr"]."<br />";
				echo $pagat."<br>".$factura."<br>".$id."<br>";

				$pagat2 = number_format($pagat,2);
				$aPagarMembre2 = number_format($aPagarMembre,2);

				if ( floatval($pagat2) >= floatval($aPagarMembre2) ) {
					if ( $stmtUpd=$conWeb2->prepare( $this->consultesBD_Web["updDateInscr"] ) ) {
						$stmtUpd->bind_param("sd", $dataPagament, $id);
						$stmtUpd->execute();
						$conWeb2->closeStmt();
					}
					else {
						throw new Exception('',4293);
					}
					echo $this->consultesBD_Web["updDateInscr"]."<br />";
					echo $dataPagament."<br>".$id."<br>";
				}
				$i++;
			}
			$conWeb->closeStmt();
		}
		else {
