	/**
	* @brief Genera una factura electronica amb les dades de la empresa $empresa
	* el concepte1 $concepte1, el concepte2 $concepte2, l'import $preu, amb el
	* cursos que trobarem en el primer element de cada element de l'array $cursos,
	* de les edicions corresponents a $edicions. Substitueix la factura electronica
	* de les inscripcions que estan a l'array $inscripcions per la factura electronica
	* creada i posa a observacions de pagament i al reclamat de cada inscripció
	* "Paga l'empresa $empresa"
	* @return Genera una factura electronica amb les dades de la empresa $empresa
	* el concepte1 $concepte1, el concepte2 $concepte2, l'import $preu, amb el
	* cursos que trobarem en el primer element de cada element de l'array $cursos,
	* de les edicions corresponents a $edicions. Substitueix la factura electronica
	* de les inscripcions que estan a l'array $inscripcions per la factura electronica
	* creada i posa a observacions de pagament i al reclamat de cada inscripció
	* "Paga l'empresa $empresa"
	*/
	public function generarFacturaElectronica_Alumnes($empresa, $concepte1,
	$concepte2, $preu, $cursos, $edicions, $inscripcions, $observacions) {
		$conIntra = new ConnexioIntranet();
		$conIntra->connectarBD();
		if ( $stmt=$conIntra->prepare( $this->consultesBD_Intra["buscarEntitat"] ) ) {
			$stmt->bind_param("s", $empresa);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($cif, $rao, $adreca, $cp,	$poble);
				$stmt->fetch();
			}
			$conIntra->closeStmt();
		}
		else {
			throw new Exception('',4136);
		}
		$conIntra->desconectarBD();

		$arrCursos = json_decode($cursos); $codiCurs = ''; $hores = '';
		for ($i=0; $i<count($arrCursos); $i++) {
			if ($i>0) {
				$codiCurs.="|";
				$hores.="|";
			}
			$codiCurs .= $arrCursos[$i][0];
			$hores .= $arrCursos[$i][3];
		}

		$anyFiscal = date('Y');
		$import = floatval($preu);
		$entitat = "Asso";
		$formaPagament = '';
		$dataActual = date('Y')."-".date('m')."-".date('d')." ".date('H').":".date('i').":".date('s');
		$efact = 1;

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		$tipusOrdre = 'A';

		if ( $stmtOrdre=$conWeb->prepare( $this->consultesBD_Web["buscarLastOrdreFact"] ) ) {
			$stmtOrdre->bind_param("ds", $anyFiscal, $tipusOrdre);
			$stmtOrdre->execute();
			$stmtOrdre->bind_result($lastOrdreFact);
			$stmtOrdre->store_result();
			if ( $stmtOrdre->num_rows() > 0 ) {
				$stmtOrdre->fetch();
				$ordreFact = intval($lastOrdreFact)+1;
			}
			else {
				$ordreFact = 1;
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4137);
		}
		$numFact = "A".$anyFiscal."/".$ordreFact;

		if ( $stmtFactRel=$conWeb->prepare( $this->consultesBD_Web["buscarLastFact"] ) ) {
			$stmtFactRel->execute();
			$stmtFactRel->bind_result($lastFactRel);
			$stmtFactRel->store_result();
			if ( $stmtFactRel->num_rows() > 0 ) {
				$stmtFactRel->fetch();
				$factura = intval($lastFactRel)+1;
			}
			else {
				$factura = 1;
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4138);
		}

		$null = NULL;

		/* afegir la factura a FACTURES */
		if ( $stmtInsert=$conWeb->prepare( $this->consultesBD_Web["insertFactura"] ) ) {
			$stmtInsert->bind_param("dddssssssssssdsssdsd",
				$factura, $anyFiscal, $ordreFact, $numFact, $dataActual, $null,
				$rao, $cif, $adreca, $cp, $poble, $concepte1, $concepte2,
				$import, $entitat, $formaPagament, $codiCurs, $hores, $observacions, $efact);
			$stmtInsert->execute();
			$conWeb->closeStmt();
			$mostrar = "<p>S'ha generat la factura relacionada <strong id='factura-creada'>".$factura."</strong></p>";
		}
		else {
			throw new Exception('',4139);
		}

		$paga = "Paga ".$empresa;

		/* actualitzar el registre d'inscripcions */
		$arrInsc = json_decode($inscripcions);
		if ( $stmtUpdate=$conWeb->prepare( $this->consultesBD_Web["updInscFacturaPrePag"] ) ) {
			$stmtUpdate->bind_param("dsssd", $factura, $paga, $paga, $cif, $id);
			for ($i=0; $i<count($arrInsc); $i++) {
				$id = intval($arrInsc[$i]);
				$stmtUpdate->execute();
				$mostrar .= "<p>S'ha actualitzat la inscripció <strong>".$id."</strong></p>";
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4140);
		}

		// for ($i=0; $i<count($arrInsc); $i++) {
		// 	$id = intval($arrInsc[$i]);
		// 	echo "UPDATE inscripcions SET FACTURA_RELACIONADA=".$factura.",
		// 	reclamat=".$paga.", pag_observacions=".$paga." WHERE ID=".$id."<br />";
		// }
		$conWeb->desconectarBD();

		return $mostrar;
	}

	/**
   * @brief Mostra les dades de la factura relacionada $factura
   * @return Mostra les dades NUM, ANY, ORDRE, DATA, RAO, CIF, CP, POBLACIÓ,
	* ADREÇA, CONCEPTE1, CONCEPTE2, IMPORT, CURS i HORES de la factura
   */
	public function mostraDadesFacturaElectronica_Alumnes($factura) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarInfoFactura"] ) ) {
