	/**
   * @brief Mostra les dades de les inscripcions amb la factura relacionada $factura
   * @return Mostra les dades ANY, MES, CURS, INSCRIT, NOM, COGNOMS, DNI, APAGAR,
	* PAGAMENT, IDPAG de les inscripcions amb la factura relacionada $factura
   */
	public function mostraInscripcionsFacturaElectronica_Alumnes($factura) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarInscFactRel"] ) ) {
			$stmt->bind_param("d", $factura);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($idInsc, $any, $mes, $curs, $grup, $inscrit, $nom, $cognoms,
				$dni, $apagar, $pagat, $idPag);

				$mostrar = "<div class='d-flex flex-column flex-sm-row align-items-center justify-content-center w-100'>
				<table class='table table-hover table-striped table-hover text-center'>
					<thead>
						<tr>
						<th style='width: 6%'>ANY</th>
						<th style='width: 5%'>MES</th>
						<th style='width: 7%'>CURS</th>
						<th style='width: 9%'>INCRIT</th>
						<th style='width: 15%'>NOM</th>
						<th style='width: 20%'>COGNOMS</th>
						<th style='width: 9%'>DNI</th>
						<th style='width: 21%'>A PAGAR</th>
						<th style='width: 6%'>PAGAT</th>
						<th style='width: 6%'>IDPAG</th>
						</tr>
					</thead>
					<tbody>";

				while ( $stmt->fetch() ) {
					if ( $inscrit == "1" )
						$textInscrit = "<span class='text-success'>INSCRIT</span>";
					else if ( $inscrit == "X" )
						$textInscrit = "<span class='text-alert'>BAIXA</span>";
					else if ( $inscrit == "C" )
						$textInscrit = "<span class='text-alert'>CANVI</span>";
					else if ( $inscrit == "0" )
						$textInscrit = "<span class='text-alert'>NO INSCRIT</span>";
					else if ( $inscrit == "M" )
						$textInscrit = "<span class='text-alert'>MORÒS</span>";
					else
						$textInscrit = "<span class='text-alert'>".$inscrit."</span>";

					$mostrar .= "<tr>
						<td>".$any."</td>
						<td>".$mes."</td>
						<td>".$curs."</td>
						<td>".$textInscrit."</td>
						<td>".$nom."</td>
						<td>".$cognoms."</td>
						<td>".$dni."</td>
						<td>".$apagar."</td>
						<td>".$pagat."</td>
						<td>".$idPag."</td>
					</tr>";
				}
				$mostrar .= "</tbody></table></div>";
			}
			$conWeb->closeStmt();
		}

		$conWeb->desconectarBD();
		return $mostrar;
	}

	/**
