					if ( $cog == '' ) $textCog = "<strong class='text-danger'>BUIT</strong>";
					if ( $correu == '' ) $textCorreu = "<strong class='text-danger'>BUIT</strong>";

					$tableEntitats .= "<tr>
						<td>".$id."</td>
						<td>".$cif."</td>
						<td>".$rao."</td>
						<td>".$adreca."</td>
