					<div class='d-flex flex-column justify-content-center align-items-center w-100 una-fila'>
						".$this->__mostrarInput(2,"","CIF", "active", "cif-insert", "edit", '')."
					</div>
					<div class='d-flex flex-column justify-content-center align-items-center w-100 una-fila'>
						".$this->__mostrarInput(2,"","Raó", "active", "rao-insert", "edit", '')."
					</div>
					<div class='d-flex flex-column justify-content-center align-items-center w-100 una-fila'>
