	/**
	* @brief Creem una empresa amb el nom $rao, el cif $cif, l'adreca $adreca,
	* el codi postal $cp i la població $poble i la persona responsable
	* @return Creem una empresa amb el nom $rao, el cif $cif, l'adreca $adreca,
	* el codi postal $cp i la població $poble. Creem una persona responsable
	* amb les dades nom: $nomResp, cognoms: $cogResp i correu: $correu amb un nou
	* ID_RESP i l'assignem a l'entitat
	*/
	public function creaEmpresa_Alumnes($rao, $cif, $adreca, $cp, $poble, $nomResp, $cogResp, $correu) {
		$conIntra = new ConnexioIntranet();
		$conIntra->connectarBD();
		if ( $stmt=$conIntra->prepare( $this->consultesBD_Intra["cnsLastIdResp"] ) ) {
			$stmt->execute();
			$stmt->bind_result($idResp);
			$stmt->fetch();
			$conIntra->closeStmt();
		}
		else {
			throw new Exception('',4279);
		}

		$idResp = $idResp + 1;

		if ( $stmt=$conIntra->prepare( $this->consultesBD_Intra["insertPersRespEntitat"] ) ) {
			$stmt->bind_param("dsss", $idResp, $nomResp, $cogResp, $correu);
			$stmt->execute();
			$conIntra->closeStmt();
		}
		else {
			throw new Exception('',4280);
		}

		if ( $stmt=$conIntra->prepare( $this->consultesBD_Intra["insertEntitat"] ) ) {
			$stmt->bind_param("sssssd", $rao, $cif, $adreca, $cp, $poble, $idResp);
			$stmt->execute();
			$conIntra->closeStmt();
		}
		else {
			throw new Exception('',4142);
		}
		$conIntra->desconectarBD();
	}

