	/**
   * @brief Actualitza les dades CIF, RAO, ADRECA, CP, POBLACIO de l'entitat amb id $id
   * @return Actualitza les dades CIF, RAO, ADRECA, CP, POBLACIO de l'entitat amb id $id
   */
	public function actualitzaEditaEntitat_Alumnes($idEntitat, $rao, $cif, $adreca, $cp, $poblacio, $nomResp, $cogResp, $correu) {
		$conIntra = new ConnexioIntranet();
		$conIntra->connectarBD();

		//busquem les dades de l'entitat
		if ( $stmt=$conIntra->prepare( $this->consultesBD_Intra["buscarEntitatById"] ) ) {
			$stmt->bind_param("d", $idEntitat);
			$stmt->execute();
			$stmt->bind_result($cifE, $raoE, $adrecaE, $cpE, $poblacioE, $idResp);
			$stmt->fetch();
			$conIntra->closeStmt();
		}
		else {
			throw new Exception('',4281);
		}

		//actualitzem les dades de l'entitat
		if ( $stmt=$conIntra->prepare( $this->consultesBD_Intra["updEntitat"] ) ) {
			$stmt->bind_param("sssssd", $rao, $cif, $adreca, $cp, $poblacio, $idEntitat);
			$stmt->execute();
			$conIntra->closeStmt();
		}
		else {
			throw new Exception('',4144);
		}

		//actualitzo el regisrtre actiu de la persona responsable (posem la data inici a data d'avui)
		if ( $stmt=$conIntra->prepare( $this->consultesBD_Intra["updEntitatResp"] ) ) {
			$stmt->bind_param("d", $idResp);
			$stmt->execute();
			$conIntra->closeStmt();
		}
		else {
			throw new Exception('',4282);
		}

		//insereixo un nou regisrtre de persona responsable
		if ( $stmt=$conIntra->prepare( $this->consultesBD_Intra["insertPersRespEntitat"] ) ) {
			$stmt->bind_param("dsss", $idResp, $nomResp, $cogResp, $correu);
			$stmt->execute();
			$conIntra->closeStmt();
		}
		else {
			throw new Exception('',4283);
		}

		$conIntra->desconectarBD();
	}

