	/**
   * @brief Busca les factures de la taula factures on el registre d'inscripcions
	* 			corresponent a la factura relacionada on el DNI del registre conté el
	* 			$dni o el CORREU del registre conté $email o FACTURA RELACIONADA del
	*			registre conté $factRel o el NUM FACT del registre conté $numFact
   * @return Retorna els id's de la taula de factures on el DNI del registre d'inscripcions
	*			corresponent a la factura relacionada conté el $dni o el CORREU del registre
	*			conté $email o FACTURA RELACIONADA del registre conté $factRel o el
	*			NUM FACT del registre conté $numFact en format d'una cadena, concatenant
	*			els diferents registres amb un | .
   */
	public function buscarUsuaris_Factures( $dni, $email, $factRel, $factNum ) {
		$i = 0;
		$dniUsuaris = "";
		$vectDniProvsional = "";

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		$likeDni = "%".$dni."%";
		$likeEmail = "%".$email."%";
		$likeFactRel = "%".$factRel."%";
		$likeNumFact = "%".$factNum."%";

		$dnisProvisionals = [];
		$dniDefinitius = [];

		/* Busco totes les inscripcions on el dni correspont a $dni */
		if ( $dni != '' ) {
			$facturesRelacionades = [];

			/* busquem totes les factures relacionades amb  amb el filtre de dni == dni */
			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscaFactRelInsc"] ) ) {
				$stmt->bind_param("s", $likeDni);
				$stmt->execute();
				$stmt->bind_result($factRel);
				while ($stmt->fetch()) {
					if ($factRel)
						$facturesRelacionades[] = $factRel;
				}
				$conWeb->closeStmt();
			}
			else {
				throw new Exception('', 4180);
			}

			/* busquem totes les ids possibles amb el filtre de factura relacionada == factRel
			i els posem a dniDefinitius; */
			if ( count($facturesRelacionades) > 0 ) {
				if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarIdFact"] ) ) {
					for ($i=0; $i<count($facturesRelacionades); $i++) {
						$stmt->bind_param("d", $facturesRelacionades[$i]);
						$stmt->execute();
						$stmt->bind_result($id);
						while ($stmt->fetch()) {
							$dniDefinitius[] = $id;
						}
					}
					$conWeb->closeStmt();
				}
				else {
					throw new Exception('', 4182);
				}
			}

			if ( count($facturesRelacionades) == 0 ) {
				if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscaIdFactCif"] ) ) {
					$stmt->bind_param("s", $likeDni);
					$stmt->execute();
					$stmt->bind_result($id);
					while ($stmt->fetch()) {
						if ($id)
							$dniDefinitius[] = $id;
					}
					$conWeb->closeStmt();
				}
				else {
					throw new Exception('', 4181);
				}
			}

			$existeixCerca = true;
		}
		/* Busco totes les inscripcions on el correu correspont a $email */
		/* Si $dniDefinitius no esta buit, vol dir que hem filtrat per un altre camp
		   anteriorment, llavors hem de partir d'aquest llistat de dnis per buscar
			les inscripcions corresponents on el correu és $email . */
		if ( $email != '' ) {
			/* Necessitem buscar les inscripcions que tinguin els filtres aplicats
			anteriorment i que el correu sigui $email, per fer-ho considerem
			que els dnis amb els filtres passen a ser els provisionals i els
			dnis definitus comencen buits */
			$dnisProvisionals = $dniDefinitius;
			$dniDefinitius = [];

			if ( count($dnisProvisionals) > 0 ) {
				/* es busca si existeix alguna persona amb el dni i el email */
				if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscaIdFactCorreuID"] ) ) {
					$stmt->bind_param("ss", $likeDniProv, $likeEmail);

					for ( $i = 0; $i < count($dnisProvisionals); $i++ ) {
						$likeDniProv = $dnisProvisionals[$i];
						$stmt->execute();
						$stmt->store_result();
						$stmt->bind_result($idRes);
						$stmt->fetch();
						if ($stmt->num_rows() > 0)
							$dniDefinitius[] = $idRes;
					}
					$conWeb->closeStmt();
				}
				else {
					throw new Exception('', 4168);
				}
			}
			else if ( count($dnisProvisionals) <= 0 && !$existeixCerca) {
				/* busquem totes les ids possibles amb el filtre de correu = $correu
				i els posem a dniDefinitius; */
				if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscaIdFactCorreu"] ) ) {
					$stmt->bind_param("s", $likeEmail);
					$stmt->execute();
					$stmt->bind_result($idRes);
					while ($stmt->fetch())
						$dniDefinitius[] = $idRes;
					$conWeb->closeStmt();
				}
				else {
					throw new Exception('', 4169);
				}
			}
			$existeixCerca = true;
		}

		/* Busco totes les inscripcions on el correu correspont a $factRel */
		/* Si $dniDefinitius no esta buit, vol dir que hem filtrat per un altre camp
		   anteriorment, llavors hem de partir d'aquest llistat de dnis per buscar
			les inscripcions corresponents on la factura relacionada és $factRel . */
		if ( $factRel != '' ) {
			/* Necessitem buscar les inscripcions que tinguin els filtres aplicats
			anteriorment i que el correu sigui $email, per fer-ho considerem
			que els dnis amb els filtres passen a ser els provisionals i els
			dnis definitus comencen buits */
			$dnisProvisionals = $dniDefinitius;
			$dniDefinitius = [];

			if ( count($dnisProvisionals) > 0 ) {
				/* es busca si existeix alguna persona amb el dni i el email */
				if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscaIdFactRelID"] ) ) {
					$stmt->bind_param("ss", $likeDniProv, $likeFactRel);

					for ( $i = 0; $i < count($dnisProvisionals); $i++ ) {
						$likeDniProv = $dnisProvisionals[$i];
						$stmt->execute();
						$stmt->store_result();
						$stmt->bind_result($idRes);
						$stmt->fetch();
						if ($stmt->num_rows() > 0)
							$dniDefinitius[] = $idRes;
					}
					$conWeb->closeStmt();
				}
				else {
					throw new Exception('', 4170);
				}
			}
			else if ( count($dnisProvisionals) <= 0 && !$existeixCerca) {
				/* busquem totes les ids possibles amb el filtre de correu = $correu
				i els posem a dniDefinitius; */
				if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscaIdFactRel"] ) ) {
					$stmt->bind_param("s", $likeFactRel);
					$stmt->execute();
					$stmt->bind_result($idRes);
					while ($stmt->fetch())
						$dniDefinitius[] = $idRes;
					$conWeb->closeStmt();
				}
				else {
					throw new Exception('', 4171);
				}
			}
			$existeixCerca = true;
		}

		/* Busco totes les inscripcions on el correu correspont a $factNum */
		/* Si $dniDefinitius no esta buit, vol dir que hem filtrat per un altre camp
		   anteriorment, llavors hem de partir d'aquest llistat de dnis per buscar
			les inscripcions corresponents on el numero de factura és $factNum . */
		if ( $factNum != '' ) {
			/* Necessitem buscar les inscripcions que tinguin els filtres aplicats
			anteriorment i que el correu sigui $email, per fer-ho considerem
			que els dnis amb els filtres passen a ser els provisionals i els
			dnis definitus comencen buits */
			$dnisProvisionals = $dniDefinitius;
			$dniDefinitius = [];

			if ( count($dnisProvisionals) > 0 ) {
				/* es busca si existeix alguna persona amb el dni i el email */
				if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscaIdFactNumID"] ) ) {
					$stmt->bind_param("ss", $likeDniProv, $factNum);

					for ( $i = 0; $i < count($dnisProvisionals); $i++ ) {
						$likeDniProv = $dnisProvisionals[$i];
						$stmt->execute();
						$stmt->store_result();
						$stmt->bind_result($idRes);
						$stmt->fetch();
						if ($stmt->num_rows() > 0)
							$dniDefinitius[] = $idRes;
					}
					$conWeb->closeStmt();
				}
				else {
					throw new Exception('', 4172);
				}
			}
			else if ( count($dnisProvisionals) <= 0 && !$existeixCerca) {
				/* busquem totes les ids possibles amb el filtre de correu = $correu
				i els posem a dniDefinitius; */
				if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscaIdFactNum"] ) ) {
					$stmt->bind_param("s", $factNum);
					$stmt->execute();
					$stmt->bind_result($idRes);
					while ($stmt->fetch())
						$dniDefinitius[] = $idRes;
					$conWeb->closeStmt();
				}
				else {
					throw new Exception('', 4173);
				}
			}
			$existeixCerca = true;
		}

		/* A partir de les id's d'inscripcions, obtinc els dnis unics de les inscripcions corresponents*/
		$dnisProvisionals = $dniDefinitius;
		$dniDefinitius = [];
		if ( count($dnisProvisionals) > 0 ) {
			$dniUsuaris = "#";
			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscaDniIdFact"] ) ) {
				$stmt->bind_param("s", $likeID);
				for ( $i = 0; $i < count($dnisProvisionals); $i++ ) {
					$likeID = $dnisProvisionals[$i];
					$stmt->execute();
					$stmt->store_result();
					$stmt->bind_result($dniRes);
					$stmt->fetch();
					if ($stmt->num_rows() > 0) {
						$j = 0;
						$trobat = false;
						while ( $j<count($dniDefinitius) && !$trobat) {
							$objDniDef = new Text($dniDefinitius[$j]);
							$objDniRes = new Text($dniRes);

							$objDniRes->setMaj();
							$objDniDef->setMaj();

							if ( $objDniRes->get() == $objDniDef->get() ) $trobat=true;
							$j++;
						}
						if ( !$trobat ) {
							$dniDefinitius[] = $dniRes;
							if ( $i > 0 ) $dniUsuaris .= "|";
							$dniUsuaris .= $dniRes;
						}

					}
				}
				$conWeb->closeStmt();
			}
			else {
				throw new Exception('', 4174);
			}
		}
		else {
			$dniUsuaris = "No s'han trobat resultats";
		}

		$conWeb->desconectarBD();

		return $dniUsuaris;
	}

	/**
   * @brief Mostra la informació de totes les factures corresponent al dni $dni
   * @return Mostra totes les factures corresponents al cif. El header de la cerca
	*			és $cercaPer.
   */
	public function mostrarTotesFacturesUsuari_Factures( $dni, $cercaPer ) {
		$tableFactures = "";

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		$facturesRelacionades = [];
		$idsFactRel = [];

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscaFactRelInsc"] ) ) {
			$stmt->bind_param("s", $dni);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($factRel);
				while ( $stmt->fetch() ) {
					if ( $factRel ) {
						$facturesRelacionades[] = $factRel;
					}
				}
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('', 4178);
		}

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscaFactRelFact"] ) ) {
			$stmt->bind_param("s", $dni);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($factRel);
				while ( $stmt->fetch() ) {
					if ( $factRel ) {
						$i = 0; $trobat = 0;
						while ( $i < count($facturesRelacionades) && !$trobat ) {
							if ( $facturesRelacionades[$i] == $factRel )
								$trobat = 1;
							$i++;
						}
						if ( !$trobat )
							$facturesRelacionades[] = $factRel;
					}
				}
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('', 4178);
		}

		if ( count($facturesRelacionades) > 0 ) {
			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarIdFact"] ) ) {
				for ($i=0; $i<count($facturesRelacionades); $i++) {
					$stmt->bind_param("d", $facturesRelacionades[$i]);
					$stmt->execute();
					$stmt->store_result();
					if ($stmt->num_rows() > 0) {
						$stmt->bind_result($id);
						while ( $stmt->fetch() ) {
							$idsFactRel[] = $id;
						}
					}
				}
				$conWeb->closeStmt();
			}
			else {
				throw new Exception('', 4183);
			}
		}

		if ( count($facturesRelacionades) == 0 ) {
			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscaIdFactCif"] ) ) {
				$stmt->bind_param("s", $dni);
				$stmt->execute();
				$stmt->store_result();
				if ($stmt->num_rows() > 0) {
					$stmt->bind_result($id);
					while ( $stmt->fetch() ) {
						$idsFactRel[] = $id;
					}
				}
				$conWeb->closeStmt();
			}
			else {
				throw new Exception('', 4179);
			}
		}

		$resultats = [];

		if ( count($idsFactRel) > 0 ) {
			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarTotesFactId"] ) ) {
				$j=0;
				for ($i=0; $i<count($idsFactRel); $i++) {
					$stmt->bind_param("d", $idsFactRel[$i]);
					$stmt->execute();
					$stmt->store_result();
					if ($stmt->num_rows() > 0) {
						$stmt->bind_result($id, $factRel, $any, $factNum, $rao, $cif, $import, $curs, $obs, $generat, $inscrit);
						while ( $stmt->fetch() ) {
							$resultats[$j][0] = $id;
							$resultats[$j][1] = $factRel;
							$resultats[$j][2] = $any;
							$resultats[$j][3] = $factNum;
							$resultats[$j][4] = $rao;
							$resultats[$j][5] = $cif;
							$resultats[$j][6] = $curs;
							$resultats[$j][7] = $obs;
							$resultats[$j][8] = $generat;
							$resultats[$j][9] = $inscrit;
							$resultats[$j][10] = $import;
							$j++;
						}

					}
				}
				$conWeb->closeStmt();
			}
			else {
				throw new Exception('', 4184);
			}
		}

		$conWeb->desconectarBD();

		function cmpNumFact($a, $b) {
		    if ($a[3] == $b[3]) {
		        return 0;
		    }
		    return ($a[3] > $b[3]) ? -1 : 1;
		}

		usort($resultats, "cmpNumFact");

		if ( count($resultats) > 0 ) {
			$tableFactures = "<p class='titol-apartat'>Totes les factures</p>";
			$tableFactures .= "<div class='d-flex flex-column flex-sm-row align-items-center justify-content-center w-100'>
			<table class='table table-hover table-striped table-hover text-center'>
			<thead>
			<tr>
			<th style='width: 20%'>FACTURA REL.</th>
			<th style='width: 10%'>ANY</th>
			<th style='width: 15%'>N. FACT</th>
			<th style='width: 20%'>RAO</th>
			<th style='width: 10%'>CIF</th>
			<th style='width: 10%'>CURS</th>
			<th style='width: 25%'>ACCIONS</th>
			</tr>
			</thead>
			<tbody>";
			for ($i=0; $i<count($resultats); $i++) {
				$classAnulaFactura = 'anula-factura';
				$titleAnulaFactura ='Anul·la la factura';
				$condRetornada = false;
				if ( $resultats[$i][7] != null )
				   $condRetornada = strripos($resultats[$i][7],'Retornada') !== false;
				if ( $resultats[$i][10] <= 0 || $condRetornada || $resultats[$i][8]!=0 || $resultats[$i][9]=='C' || $resultats[$i][9]=='D' ) {
					$classAnulaFactura .= '-hide no-disponible';
					if ( $resultats[$i][10] <= 0 )
						$titleAnulaFactura = "L'import pagat és menor o igual a 0";
					else if ( $condRetornada )
						$titleAnulaFactura = 'Ja està retornada';
					else if ( $resultats[$i][8]!=0 )
						$titleAnulaFactura = 'Està pujada al GTAF';
					else if ( $resultats[$i][9]=='C' )
						$titleAnulaFactura = "Es tracta d'un canvi de curs";
					else
						$titleAnulaFactura = "Es tracta d'un curs duplicat";
				}

				$tableFactures .= "<tr>
				<td>".$resultats[$i][1]."</td>
				<td>".$resultats[$i][2]."</td>
				<td>".$resultats[$i][3]."</td>
				<td>".$resultats[$i][4]."</td>
				<td>".$resultats[$i][5]."</td>
				<td>".$resultats[$i][6]."</td>
				<td>
					<div class='d-flex flex-column flex-sm-row justify-content-center align-items-center w-100'>
						<i id='info-".$resultats[$i][0]."' class='material-icons cns-informacio' title='Consulta la informació'>info</i>
						<i id='anula-".$resultats[$i][0]."' class='material-icons ml-2 ".$classAnulaFactura."' title=\"".$titleAnulaFactura."\">cancel</i>
						<i id='factura-".$resultats[$i][0]."' class='fas fa-file-pdf ml-2 prev-factura' title='Previsualitza la factura'></i>
					</div>
				</td>
				</tr>";
			}
			$tableFactures .= "</tbody></table></div>";
		}

		$mostrar = "
			<div class='d-flex flex-column justify-content-center align-items-center
				w-100 text-center border-bottom card-header '>
				<p class='title font-weight-bold text-center py-3 mb-0 align-items-center
				justify-content-center d-flex'>".$cercaPer."</p>
			</div>
			<div class='card-body px-0'>
				<div id='totes-factures' class='regCursos flex-column
				justify-content-center align-items-center my-2'>
				".$tableFactures."
				</div>
				".$this->__modalConsultaInformacio_Factures()."
				".$this->__modalAnularFactura_Factures()."
				".$this->__modalPrevisualitzaFactura_Factures()."
			</div>
		";

		return $mostrar;
	}

