	/**
	* @brief Substitueix els camp factura_relacionada per $factura, rao per $rao,
	* 			cif per $cif, cp per $cp, poblacio per $poblacio, adreca per $adreca,
	* 			concepte1 per $concepte1, concepte2 per $concepte2, observacions per
	*			$obs on la id de factures és $id
	* @return Substitueix els camp factura_relacionada per $factura, rao per $rao,
	* 			cif per $cif, cp per $cp, poblacio per $poblacio, adreca per $adreca,
	* 			concepte1 per $concepte1, concepte2 per $concepte2, observacions per
	*			$obs on la id de factures és $id
	*/
	public function guardarDadesFactura_Factures(
	$id, $factura, $rao, $cif, $cp, $poblacio, $adreca,
	$concepte1, $concepte2, $obs) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["updDadesFact"] ) ) {
			$stmt->bind_param("dssssssssd", $factura, $rao, $cif, $adreca,$cp, $poblacio,
			$concepte1, $concepte2, $obs, $id);
			$stmt->execute();
			$stmt->fetch();
			$conWeb->closeStmt();

			$mostrar = "OK";
		}
		else {
			throw new Exception('', 4176);
		}
		$conWeb->desconectarBD();

		return $mostrar;
	}

