	/**
	* @brief Anula la factura $id. Crea una factura negativa amb les mateixes dades
	* fiscals i del curs que la factura $id pero amb l'import en negatiu de $tornar, la data de
	* pagament $dataDevol i com a observacio.
	* @return Es crea una factura negativa amb les mateixes dades fiscals i del curs
	* que la factura $id pero amb l'import $tornar, la data de pagament $dataDevol
	*  i com a observacio. S'actualitza les observacions de la factura amb id $id
	* afegint-li "Retornada". S'actualitza el pagament de la inscripció corresponent
	* a la factura $id restant-li l'import $tornar
	*/
	public function anularFactura( $idFact, $tornar, $dataDevol, $obsDev ) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		$totOK = true;

		// Es busca les dades de la factura amb un id $id
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarInfoFacturaId"] ) ) {
			$stmt->bind_param("d", $idFact);
			$stmt->execute();
			$stmt->bind_result($id, $factRel, $any, $ordre, $num, $data, $dataPagament,
			$generada, $rao, $cif, $adreca, $cp, $poblacio, $concepte1, $concepte2,
			$import, $entitat, $formaPag, $codiCurs, $hores, $obs, $efact);
			$stmt->fetch();
			$conWeb->closeStmt();
		}
		else {
			$totOK = false;
			throw new Exception('', 4188);
		}

		if ( $totOK && $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarInfoFactInsc2"] ) ) {
			$stmt->bind_param("d", $idFact);
			$stmt->execute();
			$stmt->store_result();
			$numInscripcionsRelacionades = $stmt->num_rows();
			$stmt->bind_result($dniInsc, $tipusInsc, $fracInsc, $comPagaraInsc,
			$apagarInsc, $pagamentInsc, $idPag, $pagObs);
			$stmt->fetch();
			$conWeb->closeStmt();
		}
		else {
			$totOK = false;
			throw new Exception('', 4193);
		}

		// echo "tipus".$tipusInsc."<br />";

		$anyFiscal = date('Y');

		$importDev = floatval( 0 - floatval($tornar) );

		// transformem la data de devolució
		$dataDev = null;
		if ( $dataDevol ) {
			$objDataDev = new Date($dataDevol);
			$dataDev = $objDataDev->getDataFomatYYYYMMDD_HHMMSS();
		}

		$dataActual = date('Y')."-".date('m')."-".date('d')." ".date('H').":".date('i').":".date('s');

		$tipusOrdre = 'R';
		//es busca el nou ordre de la factura
		if ( $totOK && $stmtOrdre=$conWeb->prepare( $this->consultesBD_Web["buscarLastOrdreFact"] ) ) {
			$stmtOrdre->bind_param("ds", $anyFiscal, $tipusOrdre);
			$stmtOrdre->execute();
			$stmtOrdre->bind_result($lastOrdreFact);
			$stmtOrdre->store_result();
			if ( $stmtOrdre->num_rows() > 0 ) {
				$stmtOrdre->fetch();
				$nouOrdre = intval($lastOrdreFact)+1;
			}
			else {
				$nouOrdre = 1;
			}
			$conWeb->closeStmt();
		}
		else {
			$totOK = false;
			throw new Exception('',4189);
		}

		$numFact = $tipusOrdre.$anyFiscal."/".$nouOrdre;
		$numComanda = NULL;

		// afegir factura anul·lada
		if ( $totOK && $stmtInsert=$conWeb->prepare( $this->consultesBD_Web["insertFacturaAut"] ) ) {
			$stmtInsert->bind_param("dsddsssssssssssdsssdsd",
				$factRel, $tipusOrdre, $anyFiscal, $nouOrdre, $numFact, $dataActual, $dataDev,
				$numComanda, $rao, $cif, $adreca, $cp, $poblacio, $concepte1, $concepte2,
				$importDev, $entitat, $formaPag, $codiCurs, $hores, $obsDev, $efact);
			$stmtInsert->execute();
			// echo "-----------------------------------------------------------------<br />";
			// echo $this->consultesBD_Web["insertFacturaAut"]."<br />";
			// echo $factRel."<br />".$tipusOrdre."<br />".$anyFiscal."<br />".$nouOrdre."<br />".$numFact."<br />".$dataActual."<br />".$dataDev."<br />".
			// $rao."<br />".$cif."<br />".$adreca."<br />".$cp."<br />".$poblacio."<br />".$concepte1."<br />".$concepte2."<br />".
			// $importDev."<br />".$entitat."<br />".$formaPag."<br />".$codiCurs."<br />".$hores."<br />".$obsDev."<br />".$efact."<br />";
			$conWeb->closeStmt();
		}
		else {
			$totOK = false;
			throw new Exception('',4190);
		}

		if ( $numInscripcionsRelacionades == 1 ) {
			$pagObs .= "Retornem ".$importDev." € (".$dataActual.")";

			if ( $tipusInsc == 'I' or $tipusInsc == 'R' ) {
				$retorn = $pagamentInsc - $tornar;

				/* Actualitzo l'import de pagament */
				if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["updPayInscrByIdPag2"] ) ) {
					$stmt->bind_param("dd", $retorn, $idPag);
					$stmt->execute();
					// echo "S'ha actualitzat ".$conWeb->affectedRows()." registre";
					// echo "-----------------------------------------------------------------<br />";
					// echo $this->consultesBD_Web["updPayInscrByIdPag2"]."<br />";
					// echo $retorn."<br />".$idPag."<br />";
					$conWeb->closeStmt();
				}
				else {
					$totOK = false;
					throw new Exception('',4191);
				}

				/* Actualitzo les observacions de pagament */
				if ( $stmtUpd=$conWeb->prepare( $this->consultesBD_Web["updPagObsByIdPag"] ) ) {
					$stmtUpd->bind_param("sd", $pagObs, $idPag);
					$stmtUpd->execute();
					// echo "-----------------------------------------------------------------<br />";
					// echo $this->consultesBD_Web["updPagObsByIdPag"]."<br />";
					// echo $pagObs."<br />".$idPag."<br />";
					$conWeb->closeStmt();
				}
				else {
					throw new Exception('',4275);
				}

				if ( $apagarInsc > floatval( floatval($pagamentInsc) - floatval($tornar) ) ) {
					/* Actualitzo la data de pagament */
					if ( $totOK &&  $stmt=$conWeb->prepare( $this->consultesBD_Web["updInscDataPagAnulFact"] ) ) {
						$stmt->bind_param("d", $factRel);
						$stmt->execute();
						// echo "-----------------------------------------------------------------<br />";
						// echo $this->consultesBD_Web["updInscDataPagAnulFact"]."<br />";
						// echo $factRel."<br />";
						$conWeb->closeStmt();
					}
					else {
						$totOK = false;
						throw new Exception('', 4276);
					}
				}

			}
			else if ( $tipusInsc == 'P'  or $tipusInsc == 'G' ) {
				$conWeb2 = new ConnexioWeb();
				$conWeb2->connectarBD();

				$auxRetorn = floatval($tornar);

				if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["searchMembresGrup2"] ) ) {
					$stmt->bind_param("sd", $tipusInsc, $idPag);
					$stmt->execute();
					$stmt->bind_result($id, $aPagarMembre, $pagamentMembre, $factMembre); $i=0;
					while ( $stmt->fetch() && $auxRetorn > 0 ) {
						if ( $auxRetorn > $pagamentMembre ) {
							$retorn = 0;
							$auxRetorn -= $pagamentMembre;
						}
						else {
							$retorn = $pagamentMembre - $auxRetorn;
							$auxRetorn = 0;
						}

						if ( $stmtUpd=$conWeb2->prepare( $this->consultesBD_Web["updPayInscr2"] ) ) {
							$stmtUpd->bind_param("dd", $retorn, $id);
							$stmtUpd->execute();
							// echo "-----------------------------------------------------------------<br />";
							// echo $this->consultesBD_Web["updPayInscr2"]."<br />";
							// echo $retorn."<br />".$factRel."<br />".$id."<br />";
							$conWeb2->closeStmt();
						}
						else {
							throw new Exception('',4268);
						}

						$pagat2 = number_format($pagat,2);
						$aPagarMembre2 = number_format($aPagarMembre,2);

						$dataPagament = NULL;

						if ( $stmtUpd=$conWeb2->prepare( $this->consultesBD_Web["updDateInscr"] ) ) {
							$stmtUpd->bind_param("sd", $dataPagament, $id);
							$stmtUpd->execute();
							// echo "-----------------------------------------------------------------<br />";
							// echo $this->consultesBD_Web["updDateInscr"]."<br />";
							// echo $dataPagament."<br />".$id."<br />";
							$conWeb2->closeStmt();
						}
						else {
							throw new Exception('',4269);
						}
					}
					$conWeb->closeStmt();
				}
				else {
					throw new Exception ('', 4270);
				}
				$conWeb2->desconectarBD();

				if ( $stmtUpd=$conWeb->prepare( $this->consultesBD_Web["updPagObsByIdPag"] ) ) {
					$stmtUpd->bind_param("sd", $pagObs, $idPag);
					$stmtUpd->execute();
					// echo "-----------------------------------------------------------------<br />";
					// echo $this->consultesBD_Web["updPagObsByIdPag"]."<br />";
					// echo $pagObs."<br />".$idPag."<br />";
					$conWeb->closeStmt();
				}
				else {
					throw new Exception('',4271);
				}
				$i++;
			}

			if ( $apagarInsc > floatval( floatval($pagamentInsc) - floatval($tornar) ) ) {
				// actualitzem la inscripció amb fraccionat == 1
				if ( floatval( floatval($pagamentInsc) - floatval($tornar) ) > 0 ) {
					if ( $totOK &&
					$stmt=$conWeb->prepare( $this->consultesBD_Web["updInscFraccAnulFact"] ) ) {
						$stmt->bind_param("d", $factRel);
						$stmt->execute();
						// echo "-----------------------------------------------------------------<br />";
						// echo $this->consultesBD_Web["updInscFraccAnulFact"]."<br />";
						// echo $factRel."<br />";
						$conWeb->closeStmt();
					}
					else {
						$totOK = false;
						throw new Exception('', 4195);
					}
				}
			}
		}

		if ( $obs == '' )
			$obs = "Retornada";
		else
			$obs = $obs." Retornada";

		//actualitzem les observacions de la factura original
		if ( $totOK && $stmt=$conWeb->prepare( $this->consultesBD_Web["updObsFact"] ) ) {
			$stmt->bind_param("sd", $obs, $idFact);
			$stmt->execute();
			// echo "-----------------------------------------------------------------<br />";
			// echo $this->consultesBD_Web["updObsFact"]."<br />";
			// echo $obs."<br />".$idFact."<br />";
			$conWeb->closeStmt();
		}
		else {
			$totOK = false;
			throw new Exception('', 4192);
		}

		if ( $totOK )
			$mostrar = "La factura <strong>".$num."</strong> ha estat anul·lada correctament.";
		else
			$mostrar = "Hi ha hagut algun error a l'hora d'anular la factura";

		$conWeb->desconectarBD();

		return $mostrar;
	}

	/**
   * @brief Mostra el contingut de la previsualització d'una factura en el modal
   * @return Mostra el contingut de la previsualització d'una factura en el modal
   */
	public function modalPrevisualitzaFactura_Factures($id) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarInfoFacturaId"] ) ) {
			$stmt->bind_param("d", $id);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($id, $factRel, $any, $ordre, $num, $data, $dataPagament,
				$generada, $rao, $cif, $adreca, $cp, $poblacio, $concepte1, $concepte2,
				$import, $entitat, $formaPag, $curs, $hores, $obs, $efact);
				$stmt->fetch();
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4187);
		}
		$conWeb->desconectarBD();

		$mostrar = $this->generaFactura($factRel, false);
		$mostrar .= $this->__mostrarInput(1,"hide","ID", "active", "factura-relacionada-fact", "no-edit", $factRel);
		return $mostrar;
	}

