	private function __mostrarPage_Inici_ValidarDescomptes($idFuncio, $idApartatFuncio) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();



		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["cnsAlumnDescNoValidat"] ) ) {
			$stmt->execute();
			$stmt->store_result();
			if ( $stmt->num_rows() > 0 ) {
					$button = "<p>Hi han inscripcions que necessiten que els hi validis els descomptes.</p>
					<button id='valid-desc-".$idApartatFuncio."' class='valid-desc boto-blau mt-2 px-4 d-flex'>Valida els descomptes</button>";
					$conWeb->closeStmt();
			}
			else {
				$conWeb->closeStmt();

				if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["cnsAlumnProfNovellNoValidat"] ) ) {
					$stmt->execute();
					$stmt->store_result();
					if ( $stmt->num_rows() > 0 ) {
							$button = "<p>Hi han inscripcions que necessiten que els hi validis si és recent titulat.</p>
							<button id='valid-desc-".$idApartatFuncio."' class='valid-desc boto-blau mt-2 px-4 d-flex'>Valida els descomptes</button>";
					}
					else {
						$button = "<p class='text-center'>No hi ha resultats.</p>";
					}
					$conWeb->closeStmt();
				}
				else {
					throw new Exception('', xxx);
				}
			}
		}
		else {
			throw new Exception('', xxx);
		}

		return $button;
	}

