	public function sendMsgValidatCurosProfessorNovell($idInsc, $verificat) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		// modificar el registre de la bd per verificat.
		//update verificat = verificat from recent_titulat where id_insc = $idInsc
		// enviar missatge si el descompte es 0 1 2
		//
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarInfoInscripcions"] ) ) {
