	/**
	* @brief Busco tots els ids cursos que continguin com a idCurs $codiCurs, un any $any, un mes $mes i un curs $curs.
	* @return Busco tots els ids cursos que continguin com a idCurs $codiCurs, un any $any, un mes $mes i un curs $curs.
	*/
	public function buscarIdsCursos($idCurs, $any, $mes, $curs) {
		$i = 0;

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		if ( $any != '' )
			$likeAny = $any;
		else
			$likeAny = "%".$any."%";
		if ( $mes != '' )
			$likeMes = $mes;
		else
			$likeMes = "%".$mes."%";
		if ( $curs != '' )
			$likeCurs = $curs;
		else
			$likeCurs = "%".$curs."%";

		$likeIdCurs = "%".$idCurs."%";

		echo $this->consultesBD_Web["buscaIdsCursosAntic"]."<br />";
		echo $likeIdCurs."<br /> ".$likeAny."<br /> ".$likeMes."<br /> ".$likeCurs."<br />";

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscaIdsCursosAntic"] ) ) {
			$stmt->bind_param("ssss", $likeIdCurs, $likeAny, $likeMes, $likeCurs);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$ids = "#";
				$stmt->bind_result($idCursRes);
				while ($stmt->fetch()) {
					$idCursSenseAula = substr($idCursRes, 0, strlen($idCursRes) - 1);

					if ( $i > 0 ) $ids .= "|";
					$ids .= $idCursSenseAula;
					$i++;
				}
			}
			else {
				$ids = "No s'han trobat resultats";
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('', 4301);
		}
		$conWeb->desconectarBD();

		return $ids;
	}

	/**
   * @brief Mostra els usuaris corresponents a les ids de cursos $ids ordents per $oderby
   * @return Retorna una taula mostrant la informació dels cursos (any, mes, curs)
	*			 dels cursos $ids ordenats per any si $orderby == 'any',
	*			 per mes si $order by == mes o per curs si $orderby == curs, per idcurs si $orderby == 'id'
	* 			 Si $asc == 1, s'ordena ascendentment.
	* 			 Si $asc == 0, s'ordena ascendentment.
	* 			 Per defecte s'ordenarà per idcurs ascendents
   */
	public function mostrarTaulaCursos_Cursos($ids, $orderby, $asc) {
		if ($orderby != 'any' && $orderby!='mes' && $orderby!='curs' && $orderby!='id')
			$orderby = 'id';
		if ($asc!=1 and $asc!=0)
			$asc = 1;

		$vectIds = explode('|', $ids);

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();
		$conWeb2 = new ConnexioWeb();
		$conWeb2->connectarBD();


		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscaDadesCursByIdOrdAntic"] ) ) {
			$stmt->bind_param("s", $idCursAmbAula);

			if ( $stmt2=$conWeb2->prepare( $this->consultesBD_Web["buscaDadesCursByIdOrd"] ) ) {
				$stmt2->bind_param("s", $idCurs);

				for ($i = 0; $i<count($vectIds); $i++) {
					$idCurs = $vectIds[$i];

					// $idCursSenseAula = substr($idCurs, 0, strlen($idCurs) - 1);
					$idCursAmbAula = $idCurs."A";

					$stmt->execute();
					$stmt->bind_result($idCursAnt, $anyAnt, $mesAnt, $cursAnt, $codiUdgAnt, $dataIAnt, $dataFAnt);
					$stmt->fetch();

					$stmt2->execute();
					$stmt2->bind_result($idCurs2, $any, $mes, $curs, $estat, $dataI, $dataF);
					$stmt2->fetch();

					// echo $idCurs."<br>".$any."<br>".$mes."<br>".$curs."<br>".$estat."<br>".$dataI."<br>".$dataF."<br />------------------------------------------<br />";

					$resultats[$i][0] = $idCurs;
					$resultats[$i][1] = $anyAnt;
					$resultats[$i][2] = $mesAnt;
					$resultats[$i][3] = $cursAnt;
					$resultats[$i][4] = $dataIAnt;
					$resultats[$i][5] = $dataFAnt;
					$resultats[$i][6] = $estat;
					$resultats[$i][7] = $codiUdgAnt;
				}
				$conWeb2->closeStmt();
				$conWeb->closeStmt();
			}
			else {
				throw new Exception('', 4324);
			}

		}
		else {
			throw new Exception('', 4302);
		}

		function cmpIdCurs($a, $b) {
		    if ($a[0] == $b[0]) {
		        return 0;
		    }
		    return ($a[0] < $b[0]) ? -1 : 1;
		}

		function cmpAny($a, $b) {
		    if ($a[1] == $b[1]) {
		        return 0;
		    }
		    return ($a[1] < $b[1]) ? -1 : 1;
		}

		function cmpMes($a, $b) {
		    if ($a[2] == $b[2]) {
		        return 0;
		    }
		    return ($a[2] < $b[2]) ? -1 : 1;
		}

		function cmpCurs($a, $b) {
		    if ($a[3] == $b[3]) {
		        return 0;
		    }
		    return ($a[3] < $b[3]) ? -1 : 1;
		}

		if ($orderby == 'id') usort($resultats, "cmpIdCurs");
		else if ($orderby == 'any') usort($resultats, "cmpAny");
		else if ($orderby == 'mes') usort($resultats, "cmpMes");
		else if ($orderby == 'curs') usort($resultats, "cmpCurs");

		$conWeb2->desconectarBD();
		$conWeb->desconectarBD();

		$classId = '';
		$classAny = '';
		$classMes = '';
		$classCurs = '';

		if ($asc == 1) { //s'ordena ascendentment
			if ($orderby == 'id') $classId = ' asc';
			else if ($orderby == 'any') $classAny = ' asc';
			else if ($orderby == 'mes') $classMes = ' asc';
			else if ($orderby == 'curs') $classCurs = ' asc';
		}
		else { //s'ordena desscendentment
			if ($orderby == 'id') $classId = ' desc';
			else if ($orderby == 'any') $classAny = ' desc';
			else if ($orderby == 'mes') $classMes = ' desc';
			else if ($orderby == 'curs') $classCurs = ' desc';
		}

		//Mostra usuaris en format d'una taula ordenats per dni;
		$mostrar = "<table class='table table-striped table-hover table-order text-center'>
		<thead>
			<tr>
				<th id='th-id' class='sorting".$classId."'>ID_CURS</th>
				<th id='th-any' class='sorting".$classAny."'>ANY</th>
				<th id='th-mes' class='sorting".$classMes."'>MES</th>
				<th id='th-curs' class='sorting".$classCurs."'>CURS</th>
				<th id='th-estat'>ESTAT</th>
				<th></th>
			</tr>
		</thead>
		<tbody>";



		if ($asc == 1) {
			$inici = 0;
			$fi = count($resultats);
			for ($i = $inici; $i<$fi; $i++) {
				$estat = $resultats[$i][6];
				$codiUdg = $resultats[$i][7];

				$labelEstat = 'NO EXISTEIX EL REGISTRE A CURS';
				if ( $estat != '' )
					$labelEstat = $this->obtenirLabelEstatEdicio($estat, $codiUdg, $resultats[$i][4], $resultats[$i][5]);

				$mostrar .= "<tr>";
				$mostrar .= "<td>".$resultats[$i][0]."</td>";
				$mostrar .= "<td>".$resultats[$i][1]."</td>";
				$mostrar .= "<td>".$resultats[$i][2]."</td>";
				$mostrar .= "<td>".$resultats[$i][3]."</td>";
				$mostrar .= "<td>".$labelEstat."</td>";
				$mostrar .= "<td><button class='boto-blau seleccionar' id='".$resultats[$i][0]."'>Selecciona</button></td>";
				$mostrar .= "</tr>";
			}
		}
		else {
			$inici = count($resultats);
			$fi = 0;
			for ($i = $inici-1; $i>=$fi; $i--) {
				$estat = $resultats[$i][6];
				$codiUdg = $resultats[$i][7];

				$labelEstat = 'NO EXISTEIX EL REGISTRE A CURS';
				if ( $estat != '' )
					$labelEstat = $this->obtenirLabelEstatEdicio($estat, $codiUdg, $resultats[$i][4], $resultats[$i][5]);

				$mostrar .= "<tr>";
				$mostrar .= "<td>".$resultats[$i][0]."</td>";
				$mostrar .= "<td>".$resultats[$i][1]."</td>";
				$mostrar .= "<td>".$resultats[$i][2]."</td>";
				$mostrar .= "<td>".$resultats[$i][3]."</td>";
				$mostrar .= "<td>".$labelEstat."</td>";
				$mostrar .= "<td><button class='boto-blau seleccionar' id='".$resultats[$i][0]."'>Selecciona</button></td>";
				$mostrar .= "</tr>";
			}
		}

		$mostrar .= "</tbody></table>";

		return $mostrar;
	}

