	/**
   * @brief Mostra l'estat de la inscripció del curs $idCurs
   * @return ostra l'estat de la inscripció del curs $idCurs. Si el curs està tancat,
	* visible i no ha acabat, s'informa que aquesta edició està completa.
	* Si  el curs encara està visible a la web, s'indicarà i es mostrara un enllaç cap a la info de la web.
   */
	private function __mostrarDadesEstatInscrEdicioCurs_resultatCerca($idCursSenseAula) {
		$header = "<div class='d-flex align-items-center justify-content-center w-100
		position-relative pt-2'>
			<p class='titol-apartat d-flex p-0 m-0'>Dades de l'estat de la inscripció
		</div>";

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		/* Buscar ESTAT, PUBLIC, CODI_CURS, NOM_CURS, DATAI, DATAF, HORES, CODI_GTAF,
		CODI_FISS, DATA_RESOL, DATA_QUAL, VALORACIO_GTAF, VALORACIO_FISS, CURS_ESCOLAR, ID_AULA a CURS */
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarDadesEdCursByIdAntic"] ) ) {
			$stmt->bind_param("s", $idCurs);
			$idCurs = $idCursSenseAula."%";
			$stmt->execute();
			$stmt->bind_result($anyAnt, $mesAnt, $cursAnt, $nomCursAnt, $dataiAnt,
			$datafAnt, $horesAnt, $cursEscAnt, $gtafAnt, $fissAnt, $dataResolAnt,
			$dataQualAnt, $dataBloqAnt, $valGtafAnt, $valFissAnt, $dniTutor, $codiUdg, $obsAnt);
			$stmt->fetch();
		}
		else {
			throw new Exception('', 4303);
		}
		$conWeb->closeStmt();

		/* Buscar CODI UDG, NOM_CURS, DATAI, DATAF, HORES, CODI_GTAF, CODI_FISS,
		DATA_RESOL, DATA_QUAL, VALORACIO_GTAF, VALORACIO_FISS, CURS_ESCOLAR a CURSOS */
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarDadesEdCursById"] ) ) {
			$stmt->bind_param("s", $idCursSenseAula);
			$stmt->execute();
			$stmt->bind_result($any, $mes, $curs, $nomCurs, $datai, $dataf, $hores,
			$cursEsc, $gtaf, $fiss, $dataResol, $dataQual, $dataBloq, $valGtaf, $valFiss, $idAula, $estat, $public, $obs);
			$stmt->fetch();

		}
		else {
			throw new Exception('', 4304);
		}
		$conWeb->closeStmt();

		$existUrl = 0;
		$idUrlInfo = "";

		/* Buscar la ID_URL a info corresponent al curs i relacionar-le amb amigable*/
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarCursUrlRel"] ) ) {
			$stmt->bind_param("s", $curs);
			$stmt->execute();
			$stmt->store_result();
			if ( $stmt->num_rows() > 0 ) {
				$existUrl = 1;
				$stmt->bind_result($urlWeb);
				$stmt->fetch();
				$idUrlInfo = 'labelLinkInfo-'.$curs;
			}
		}
		else {
			throw new Exception('', 4305);
		}
		$conWeb->closeStmt();

		$conWeb->desconectarBD();

		$msgErrors = '';

		if ( $codiUdg == 'P' && $estat != 'P' ) {
			$msgErrors .= "<span>El curs està pendent de començar a la taula cursos, però no a la taula curs </span>";
		}
		if ( $codiUdg == 'T' && $estat != '0' ) {
			$msgErrors .= "<span>El curs està tancat a la taula cursos, però no a la taula curs </span>";
		}

		$alertError = "";
		if ( $msgErrors != '' ) {
			$alertError = "<div class='alert alert-danger alert-with-icon w-100 mb-2'>
			<i class='material-icons' data-notify='icon'>notifications</i>
			<button type='button' data-dismiss='alert' aria-label='Close' class='close'>
			<i class='material-icons'>close</i></button>".$msgErrors."</div>";
		}

		$inscripcioOberta = 0;
		if ( $public ) {
			//Consultar si la inscripció del cus $idCurs està oberta a la web
			$inscripcioOberta = $this->inscripcionOberta($any, $mes, $curs, $hores);
			if ( $inscripcioOberta )
				$inscripcioOberta = $this->inscripcioVisible($any, $mes, $curs, $hores);
		}

		$dateNow = new DateTime("now");
		$dateLastDay = new DateTime($dataf);
		$diffFi = $dateLastDay->diff($dateNow);
		$signe = $diffFi->format('%R');

		$labelEstat = '';
		/* Si el curs està tancat, visible i no ha finalitzat, mostrar que l'edició està completa */
		if ( ( $codiUdg == 'T' ||  $estat == 'T' || $estat == '0' ) && $inscripcioOberta && ( $signe == '-' || $diffFi->days==0 ) )
			$labelEstat = $this->obtenirLabelEstatInscr($estat, $codiUdg);

		$labelPublic = $this->obtenirLabelPublic($inscripcioOberta);
		$labelUrlInfo = $this->obtenirLabelUrl($idUrlInfo, $curs, $existUrl, "INFO");

		$botonsInfo = "<div class='d-flex flex-column flex-md-row align-items-center
		justify-content-center w-100 my-2'>
			<div class='d-flex flex-column flex-sm-row align-items-center justify-content-center my-2 ml-3'>
				".$labelEstat.$labelPublic.$labelUrlInfo."
			</div>
		</div>";

		$mostrar = $header.$botonsInfo.$alertError;
		return $mostrar;
	}

	/**
   * @brief Mostra les dades de l'edició d'un curs amb l'identificador $idCurs
   * @return Mostra les dades de l'edició d'un curs amb l'identificador $idCurs
   */
	private function __mostrarDadesEdicioCurs_resultatCerca($idCursSenseAula) {
		$header = "<div class='d-flex align-items-center justify-content-center w-100
		position-relative pt-2'>
			<p class='titol-apartat d-flex p-0 m-0'>Dades de l'edició
			<i class='material-icons ml-2 editar-apartat pointer'>edit</i></p>
		</div>";

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		/* Buscar ESTAT, PUBLIC, CODI_CURS, NOM_CURS, DATAI, DATAF, HORES, CODI_GTAF,
		CODI_FISS, DATA_RESOL, DATA_QUAL, VALORACIO_GTAF, VALORACIO_FISS, CURS_ESCOLAR, ID_AULA a CURS */
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarDadesEdCursByIdAntic"] ) ) {
			$stmt->bind_param("s", $idCurs);
			$idCurs = $idCursSenseAula."%";
			$stmt->execute();
			$stmt->bind_result($anyAnt, $mesAnt, $cursAnt, $nomCursAnt, $dataiAnt,
			$datafAnt, $horesAnt, $cursEscAnt, $gtafAnt, $fissAnt, $dataResolAnt,
			$dataQualAnt, $dataBloqAnt, $valGtafAnt, $valFissAnt, $dniTutor, $codiUdg, $obsAnt);
			$stmt->fetch();
		}
		else {
			throw new Exception('', 4303);
		}
		$conWeb->closeStmt();

		// $idCursSenseAula = substr($idCurs, 0, strlen($idCurs) - 1);

		/* Buscar CODI UDG, NOM_CURS, DATAI, DATAF, HORES, CODI_GTAF, CODI_FISS,
		DATA_RESOL, DATA_QUAL, VALORACIO_GTAF, VALORACIO_FISS, CURS_ESCOLAR a CURSOS */
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarDadesEdCursById"] ) ) {
			$stmt->bind_param("s", $idCursSenseAula);
			$stmt->execute();
			$stmt->bind_result($any, $mes, $curs, $nomCurs, $datai, $dataf, $hores,
			$cursEsc, $gtaf, $fiss, $dataResol, $dataQual, $dataBloq, $valGtaf, $valFiss, $idAula, $estat, $public, $obs);
			$stmt->fetch();
		}
		else {
			throw new Exception('', 4304);
		}
		$conWeb->closeStmt();

		$existUrl = 0;
		$idUrlInfo = "";

		/* Buscar la ID_URL a info corresponent al curs i relacionar-le amb amigable*/
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarCursUrlRel"] ) ) {
			$stmt->bind_param("s", $curs);
			$stmt->execute();
			$stmt->store_result();
			if ( $stmt->num_rows() > 0 ) {
				$existUrl = 1;
				$stmt->bind_result($urlWeb);
				$stmt->fetch();
				$idUrlInfo = 'labelLinkInfo-'.$curs;
			}
		}
		else {
			throw new Exception('', 4305);
		}
		$conWeb->closeStmt();

		/* Buscar NÚM AULES a CURSOS */
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarNumAulesByIdAntic"] ) ) {
			$stmt->bind_param("dss", $anyAnt, $mesAnt, $cursAnt);
			$stmt->execute();
			$stmt->store_result();
			$numAulesAnt = $stmt->num_rows();
		}
		else {
			throw new Exception('', 4306);
		}
		$conWeb->closeStmt();

		/* Buscar NÚM AULES a AULA  */
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarNumAulesById"] ) ) {
			$stmt->bind_param("s", $idAula);
			$stmt->execute();
			$stmt->store_result();
			$numAules = $stmt->num_rows();
		}
		else {
			throw new Exception('', 4307);
		}
		$conWeb->closeStmt();

		$conWeb->desconectarBD();

		$msgErrors = '';
