	/**
   * @brief Retorna el contenidor d'un label amb l'estat del curs
   * @return Retorna el contenidor d'un label amb l'estat del curs
   */
	private function obtenirLabelEstatInscr($estat, $codiUdg) {
		/* Definir l'estat a la taula curs */
		$objText = new Text($estat);
		$objText->setMaj();
		$estat = $objText->get();

		$nomEstat = '';
		if ( $estat == '0' ) {
			$colorLabel = 'lightGray';
			$nomEstat = 'Inscripció Tancada ( Curs anul·lat)';
		}
		else if ( $estat == 'T' ) {
			$colorLabel = 'lightGreen';
			$nomEstat = 'Inscripció Tancada (Edició completa)';
		}
		else if ( $estat == '1' ) {
			$colorLabel = 'lightGreen';
			$nomEstat = 'Inscripció Oberta';
		}
		else if ( $estat == 'P' ) {
			$colorLabel = 'lightOrange';
			$nomEstat = 'Inscripció Oberta';
		}

		/* Definir l'estat de la taula cursos */
		if ( $codiUdg == '#' ) {
			$colorLabel = 'lightOrange';
			$nomEstat = 'Inscripció Oberta';
		}
		else if ( $codiUdg == 'T' ) {
			$colorLabel = 'lightGreen';
			$nomEstat = 'Inscripció Tancada (Edició completa)';
		}

		$label = $this->obtenirLabel('', $colorLabel, $nomEstat);

		return $label;
	}

	/**
   * @brief Retorna el contenidor d'un label amb l'estat del curs
   * @return Retorna el contenidor d'un label amb l'estat del curs
   */
	private function obtenirLabelEstatEdicio($estat, $codiUdg, $datai, $dataf) {
		/* Definir l'estat a la taula curs */
		$objText = new Text($estat);
		$objText->setMaj();
		$estat = $objText->get();

		$nomEstat = '';
		if ( $estat == '0' ) {
			$colorLabel = 'lightGray';
			$nomEstat = 'Anul·lat';
		}
		else if ( $estat == '1' or $estat == 'T' or $codiUdg == 'T') {
			$colorLabel = 'lightGreen';

			$dateNow = new DateTime("now");
			$dateLastDay = new DateTime($dataf);
			$dateStartDay = new DateTime($datai);

			$diffFi = $dateLastDay->diff($dateNow);
			$signeFi = $diffFi->format('%R');

			$diffIn = $dateStartDay->diff($dateNow);
			$signeIn = $diffIn->format('%R');

			if ( $signeIn == '-' ) { //Encara no ha començat
				$nomEstat = 'Per començar';
			}
			else if ( $signeFi == '+' ) { //Curs ha acabat
				$nomEstat = 'Acabat';
			}
			else {
				if ( $estat == 'T' or $codiUdg == 'T' ) {
					$nomEstat = 'Actiu (Edició completa)';
				}
				else if ( $estat == '1' ) {
					$nomEstat = 'Actiu';
				}
			}
		}
		else if ( $estat == 'P' or $codiUdg == '#' ) {
			$colorLabel = 'lightOrange';
			$nomEstat = 'Pendent';
		}

		$label = $this->obtenirLabel('', $colorLabel, $nomEstat);

		return $label;
	}

