	/*
   * @brief Obtens true si les inscripcions de l'any $any i del mes $edicio estan
   obertes. Altrament, retorna false
   * @return Obtens true si les inscripcions de l'any $any i del mes $edicio estan
   obertes. Altrament, retorna false
   */
   public function inscripcionOberta($any, $mes, $curs, $hores) {
		$inscOberta = 1;

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarParamValorOrder"] ) ) {
			$stmt->bind_param("sss", $tipus, $valor, $orderBy);

			$tipus='dies-inscriu-cursos';
			$valor=$hores."%";
	      $orderBy='VALOR';

			$stmt->execute();
			$stmt->bind_result($valor);

			$diesOberts=[];
	      $pos=0;

			while ( $stmt->fetch() ) {
				$valors = explode('|',$valor);
	         if (count($valors) != 2)
	            throw new Exception('',4319);
	         else {
	            $cnt = 0;
	            while ( $cnt < count($diesOberts) && $diesOberts[$cnt]!=$valors[1])
	               $cnt++;
	            if ($cnt==count($diesOberts)) {
	               $diesOberts[$pos] = $valors[1];
	               $pos++;
	            }
	         }
			}
		}
		else {
			throw new Exception('', 4318);
		}
		$conWeb->closeStmt();

		$dateDifss="";
    for ($i=0; $i<count($diesOberts); $i++) {
       if ($i>0) $dateDifss.=" OR ";
       $dateDifss.="DATEDIFF(DATAI + ".$diesOberts[$i].",CURRENT_DATE)>0";
    }

		$cnsEd = "SELECT MES, ANY FROM curs AS c INNER JOIN aula AS a ON
         c.ID_AULA=a.ID_AULA INNER JOIN rel_cuho AS r ON r.ID_CUHO=a.ID_CUHO
         INNER JOIN honoraris AS h ON r.ID_HONO=h.ID WHERE PUBLIC=1 AND
         c.CURS!='PROVA' AND c.CURS NOT LIKE '%0%' AND c.ESTAT!='0' AND r.ACTIU=1
         AND (".$dateDifss.") AND c.CURS NOT LIKE '%JOR%' AND c.PUBLIC = 1 AND
         (a.ID_CUHO=17 OR a.ID_CUHO=13 OR (a.ID_CUHO!=17 AND h.DNI_TUTOR='GENERIC')
         OR (a.ID_CUHO!=17 AND  h.DNI_TUTOR!='GENERIC' AND AULA='A' AND perfil='tutor'
         )) AND ANY=? AND MES=? AND c.CURS=? GROUP BY ANY, MES";

		if ( $stmt=$conWeb->prepare( $cnsEd) ) {
			$stmt->bind_param("dss", $any, $mes, $curs);
			$stmt->execute();
			$stmt->store_result();
			$inscOberta = $stmt->num_rows() > 0;
		}
		else {
			throw new Exception('', 4320);
		}
		$conWeb->closeStmt();

		$conWeb->desconectarBD();

      return $inscOberta;
   }


	/*
   * @brief Obtens true si les inscripcions de l'any $any i del mes $edicio estan
   obertes. Altrament, retorna false
   * @return Obtens true si les inscripcions de l'any $any i del mes $edicio estan
   obertes. Altrament, retorna false
   */
   public function inscripcioVisible($any, $mes, $curs, $hores) {
		$inscVisible = 0;

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarParamOrder"] ) ) {
			$stmt->bind_param("ss", $tipus, $orderBy);

			$tipus='limit-editions';
			$orderBy='DATAI';

			$stmt->execute();
			$stmt->bind_result($limitEd);
			$stmt->fetch();

			$tipus='dies-inscriu-cursos';
			$orderBy='VALOR';

			$stmt->execute();
			$stmt->bind_result($valor);
			$diesOberts=0;
			while ( $stmt->fetch() ) {
				$valors = explode('|',$valor);
				if (count($valors) != 2)
					throw new Exception('',4322);
				else if (intval($valors[0])>0 && $valors[0]== $hores) //si el valor és un numero i les hores son iguals al curs
					$diesOberts = $valors[1];
				else if (intval($valors[0])<=0 && $valors[0]== $curs) //si el valor no és un numero i el codi és igual al curs
					$diesOberts = $valors[1];
			}
		}
		else {
			throw new Exception('', 4321);
		}
		$conWeb->closeStmt();

		if ($diesOberts==0)
			throw new Exception('',4323);

		/*Es busca les X proximes edicions obertes del curs */
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarProxEdObertInsc"] ) ) {
			$stmt->bind_param("sds", $curs, $diesOberts, $limitEd);
			$stmt->execute();
			$stmt->bind_result($anyEd, $mesEd);
			while ( $stmt->fetch() && !$inscVisible ) {
				$inscVisible = $anyEd == $any && $mesEd == $mes;
			}
		}
		else {
			throw new Exception('', 4324);

		}
		$conWeb->desconectarBD();

      return $inscVisible;
   }

	/**
   * @brief Mostra la informació de les aules del curs amb id $id
   * @return Mostra les dades següents de les aules dels curs amb id $id:
	* L'estat de l'aula en el moodle (visible o no), l'enllaç a l'aula del moodle,
	* un botó per accedir al modal dels alumnes, el tutor i el dni del tutor de l'aula,
	* la data de revisió, la data d'informe, les observacions de l'aula i la data de bloqueig
   */
	private function __mostrarDadesAulaEdicioCurs_resultatCerca($idCursSenseAula) {
		$numAules = [];
		$cntAulesAnt = 0;
		$cntAulesNou = 0;

		// $idCursSenseAula = substr($idCurs, 0, strlen($idCurs) - 1);
		// $likeIdCursSenseAula = substr($idCurs, 0, strlen($idCurs) - 1)."%";
		$likeIdCursSenseAula = $idCursSenseAula."%";

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarDadesAulaByIdCursAntic"] ) ) {
			$stmt->bind_param("s", $likeIdCursSenseAula);
			$stmt->execute();
			$stmt->bind_result($aulaAnt, $anyAnt, $mesAnt, $cursAnt, $codiGtafAnt, $dataResAnt, $dataBloqAnt, $dataValAnt, $dataRevisioAnt, $dataInfAnt, $obsAnt, $dniTutor);
			while ( $stmt->fetch() ) {
				$numAules[$cntAulesAnt][0] = [$idCursSenseAula, $aulaAnt, $anyAnt, $mesAnt, $cursAnt, $dataRevisioAnt, $dataInfAnt, $obsAnt, $dniTutor, '', '', 0, $codiGtafAnt, $dataResAnt, $dataValAnt, $dataBloqAnt];
				$cntAulesAnt++;
			}
		}
		else {
			throw new Exception('', 4308);
		}
		$conWeb->closeStmt();

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarDadesAulaById"] ) ) {
			$stmt->bind_param("s", $idCursSenseAula);
			$stmt->execute();
			$stmt->bind_result($aula, $any, $mes, $curs, $codiGtaf, $dataRes, $dataBloq, $dataVal, $dataRevisio, $dataInf, $obs, $dniTutor, $nomTut, $cogTut, $idAula);
			while ( $stmt->fetch() ) {
				$numAules[$cntAulesNou][1] = [$idCursSenseAula, $aula, $any, $mes, $curs, $dataRevisio, $dataInf, $obs, $dniTutor, $nomTut, $cogTut, $idAula, $codiGtaf, $dataRes, $dataVal, $dataBloq];
				$cntAulesNou++;
			}
		}
		else {
			throw new Exception('', 4309);
		}
		$conWeb->closeStmt();

		if ( $cntAulesNou > $cntAulesAnt ) {
			for ( $i = $cntAulesAnt; $i < $cntAulesNou; $i++ ) {
				$numAules[$i][0] = [];
			}
		}
		if ( $cntAulesAnt > $cntAulesNou ) {
			for ( $i = $cntAulesNou; $i < $cntAulesAnt; $i++ ) {
				$numAules[$i][1] = [];
			}
		}

		$conWeb->desconectarBD();

		$mostrar = '';

		for ( $i = 0; $i < count($numAules); $i++ ) {

			/* Dades de l'aula de cursos : $numAules[$i][0]
				Dades de l'aula de curs: $numAules[$i][1] */

				$idCursSenseAula = $numAules[$i][1][0];
				$aula = $numAules[$i][1][1];
				$any = $numAules[$i][1][2];
				$mes = $numAules[$i][1][3];
				$curs = $numAules[$i][1][4];
				$dataRevisio = $numAules[$i][1][5];
				if ( $dataRevisio == '' ) $dataRevisio = $numAules[$i][0][5];
				$dataInf = $numAules[$i][1][6];
				if ( $dataInf == '' ) $dataInf = $numAules[$i][0][6];
				$obs = $numAules[$i][1][7];
				$dniTutor = $numAules[$i][1][8];
				$nomTut = $numAules[$i][1][9];
				$cogTut = $numAules[$i][1][10];
				$codiGtaf = $numAules[$i][1][12];
				$dataResol = $numAules[$i][1][13];
				if ( $dataResol == '' ) $dataResol = $numAules[$i][0][13];
				$dataValGtaf = $numAules[$i][1][14];
				if ( $dataValGtaf == '' ) $dataValGtaf = $numAules[$i][0][14];
				$dataBloq = $numAules[$i][1][15];
				if ( $dataBloq == '' ) $dataBloq = $numAules[$i][0][15];

			if ( count($numAules[$i][1]) < 0 ) {
				$idCursSenseAula = $numAules[$i][0][0];
				$aula = $numAules[$i][0][1];
				$any = $numAules[$i][0][2];
				$mes = $numAules[$i][0][3];
				$curs = $numAules[$i][0][4];
				$dataRevisio = $numAules[$i][0][5];
				$dataInf = $numAules[$i][0][6];
				$obs = $numAules[$i][0][7];
				$dniTutor = $numAules[$i][0][8];
				$nomTut = $numAules[$i][0][9];
				$cogTut = $numAules[$i][0][10];
				$codiGtaf = $numAules[$i][0][12];
				$dataResol = $numAules[$i][0][13];
				$dataValGtaf = $numAules[$i][0][14];
				$dataBloq = $numAules[$i][0][15];
			}
			$idAula = $numAules[$i][1][11];

			$msgErrors = '';
			if ( count($numAules[$i][0]) > 0 && !count($numAules[$i][0]) > 0 ) {
				$msgErrors .= "<span>No existeix l'aula ".$aula." a la taula aula.</span>";
			}
			else if ( !count($numAules[$i][0]) > 0 && count($numAules[$i][1]) > 0 ) {
				$msgErrors .= "<span>No existeix l'aula ".$aula." a la taula cursos.</span>";
			}
			else {
				if ( $numAules[$i][0][1] != $numAules[$i][1][1] ) {
					$msgErrors .= "<span>L'aula de l'edició de la taula cursos i de curs no coincideixen.</span>";
				}
				if ( $numAules[$i][0][2] != $numAules[$i][1][2] ) {
					$msgErrors .= "<span>L'any de l'edició de la taula cursos i de curs no coincideixen.</span>";
				}
				if ( $numAules[$i][0][3] != $numAules[$i][1][3] ) {
					$msgErrors .= "<span>El mes de l'edició de la taula cursos i de curs no coincideixen.</span>";
				}
				if ( $numAules[$i][0][4] != $numAules[$i][1][4] ) {
					$msgErrors .= "<span>El curs de l'edició de la taula cursos i de curs no coincideixen.</span>";
				}
				if ( $numAules[$i][0][5] != $numAules[$i][1][5] ) {
					$msgErrors .= "<span>La data de revisió de l'edició de la taula cursos i de aula no coincideixen.</span>";
				}
				if ( $numAules[$i][0][6] != $numAules[$i][1][6] ) {
					$msgErrors .= "<span>La data de l'informe de l'edició de la taula cursos i de aula no coincideixen.</span>";
				}
				if ( $numAules[$i][0][7] != $numAules[$i][1][7] ) {
					$msgErrors .= "<span>Les observacions de l'edició de la taula cursos i de aula no coincideixen.</span>";
				}
				if ( $numAules[$i][0][8] != $numAules[$i][1][8] ) {
					$msgErrors .= "<span>El dni del tutor de l'edició de la taula cursos i de aula no coincideixen.</span>";
				}
				if ( $numAules[$i][0][12] != $numAules[$i][1][12] ) {
					$msgErrors .= "<span>El codi GTAF de l'edició de la taula cursos i de curs no coincideixen.</span>";
				}
				if ( $numAules[$i][0][13] != $numAules[$i][1][13] ) {
					$msgErrors .= "<span>La data de resolució de l'edició de la taula cursos i de curs no coincideixen.</span>";
				}
				if ( $numAules[$i][0][14] != $numAules[$i][1][14] ) {
					$msgErrors .= "<span>La data de valoració per al GTAF de l'edició de la taula cursos i de curs no coincideixen.</span>";
				}
				if ( $numAules[$i][0][15] != $numAules[$i][1][15] ) {
					$msgErrors .= "<span>La data de bloqueig de l'edició de la taula cursos i de curs no coincideixen.</span>";
				}
			}

			$alertError = "";
			if ( $msgErrors != '' ) {
				$alertError = "<div class='alert alert-danger alert-with-icon w-100 mb-2'>
				<i class='material-icons' data-notify='icon'>notifications</i>
				<button type='button' data-dismiss='alert' aria-label='Close' class='close'>
				<i class='material-icons'>close</i></button>".$msgErrors."</div>";
			}

			$existCursMoodle = 0;
			$visibleCursMoodle = 0;

			/*
			Busco si existeix el idCurs en el moodle nou (això em confirma si està restaurat o no).
			Si no existeix en el moodle nou.
				Miro si existeix en el moodle vell.
					Si existeix,
						existsCursMoodle = 1
						consulto si el curs és visible i el id del curs del moodle
						Si ho és, $visibleCursMoodle = 1
			Si existeix en el moodle nou.
				existsCursMoodle = 1
				consulto si el curs és visible i el id del curs del moodle
				Si ho és, $visibleCursMoodle = 1
			*/

			$idMoodle = '';
			$visibleCursMoodle = 0;
			$existCursMoodle = 0;

			require_once 'ConnexioMoodle.php';
			$connexioModdle1 = new ConnexioMoodle();
			$connexioModdle1->connectarBD();

			$idCursAula = $idCursSenseAula.$aula;

			//Busco si existeix el idCurs en el moodle nou.
			if ( $stmt=$connexioModdle1->prepare( $this->consultesBD_Moodle["buscarCursVisble"] ) ) {
				$stmt->bind_param("s", $idCursAula);
				$stmt->execute();
				$stmt->store_result();
				if ( $stmt->num_rows() > 0 ) { //num_Rows
					$existCursMoodle = 1;
					$stmt->bind_result($idCursMoodle, $visible);
					$stmt->fetch();

					//Busco el camp visible i el id del curs del moodle nou del curs $idCurs
					if ( $visible == 1 ) {
						$visibleCursMoodle = 1;
					}
					$idMoodle = 'linkAulaCurs-nou-'.$idCursMoodle;
				}
				else {
					require_once 'ConnexioMoodleAntic.php';

					$connexioModdle2 = new ConnexioMoodleAntic();
					$connexioModdle2->connectarBD();

					//Busco si existeix el idCurs en el moodle antic.
					if ( $stmt2=$connexioModdle2->prepare( $this->consultesBD_MoodleAntic["buscarCursVisble"] ) ) {
						$stmt2->bind_param("s", $idCursAula);
						$stmt2->execute();
						$stmt2->store_result();
						if ( $stmt2->num_rows() > 0 ) { //num_Rows
							$existCursMoodle = 1;
							$stmt2->bind_result($idCursMoodle, $visible);
							$stmt2->fetch();
							//Busco el camp visible i el id del curs del moodle antic del curs $idCurs
							if ( $visible == 1 ) {
								$visibleCursMoodle = 1;
							}
							$idMoodle = 'linkAulaCurs-antic-'.$idCursMoodle;
						}
					}
					else {
						throw new Exception('', 4310);
					}
				}
			}
			else {
				throw new Exception('', 4311);
			}

			$titol = "<div class='d-flex align-items-center justify-content-center w-100
			position-relative pt-2 pb-3'>
				<p class='titol-apartat d-flex p-0 m-0'>Dades de l'aula «<strong>".$aula."</strong>»
				<i id='editar-apartat-aula-".$aula."' class='material-icons ml-2 editar-apartat pointer'>edit</i></p>
			</div>";

			$estatMoodle = $this->obtenirLabelVisibleMoodle($visibleCursMoodle, $existCursMoodle);

			$urlMoodle = $this->obtenirLabelUrl($idMoodle, $curs, $existCursMoodle, "MOODLE");

			$botoAlumnes = "<button id='mesInfoAlumnes-".$any."-".$curs."-".$mes."-".$aula."' role='button' class='boto-blau px-4 d-flex alumnes'>
				<i class='material-icons mr-3'>groups</i>ALUMNES
			</button>";

			$botonsEstat = "<div class='d-flex flex-column flex-md-row align-items-center
			justify-content-center w-100 my-2'>
				<div class='d-flex flex-column flex-sm-row align-items-center justify-content-center my-2 ml-3'>
					".$estatMoodle.$urlMoodle.$botoAlumnes."
				</div>
			</div>";

			$dataInfFormat = '';
			if ( $dataInf != '' ) {
				$date = new Date($dataInf);
				$dataInfFormat = $date->getDataFomatDDMMYYYY_HHMMSS();
			}
			$dataRevisioFormat = '';
			if ( $dataRevisio != '' ) {
				$date = new Date($dataRevisio);
				$dataRevisioFormat = $date->getDataFomatDDMMYYYY_HHMMSS();
			}

			$dadesResolFormat = '';
			if ( $dataResol != '' ) {
				$date = new Date($dataResol);
				$dadesResolFormat = $date->getDataFomatDDMMYYYY_HHMMSS();
			}
			$dataValGtafFormat = '';
			if ( $dataValGtaf != '' ) {
				$date = new Date($dataValGtaf);
				$dataValGtafFormat = $date->getDataFomatDDMMYYYY_HHMMSS();
			}
			$dataBloqFormat = '';
			if ( $dataBloq != '' ) {
				$date = new Date($dataBloq);
				$dataBloqFormat = $date->getDataFomatDDMMYYYY_HHMMSS();
			}

			$dades = "<div class='apartat d-flex flex-column flex-md-row
				align-items-center justify-content-center w-100'>
				<div class='d-flex flex-column align-items-center justify-content-center w-100'>
					".$this->__mostrarInput(1,"hide","ID", "active", "idCursAula-".$aula."-cercat", "no-edit", $idCursSenseAula)."
					".$this->__mostrarInput(1,"hide","ID", "active", "idAula-".$aula."-cercat", "no-edit", $idAula)."
					".$this->__mostrarInput(1,"","CODI GTAF", "active", "codiGtaf-cercat", "no-edit", $codiGtaf)."
					".$this->__mostrarInput(1,"","DATA BLOQUEIG", "active", "dataBloq-cercat", "no-edit", $dataBloqFormat)."
					".$this->__mostrarInput(1,"","REVISIÓ", "active", "dataRevisio-".$aula."-cercat", "no-edit", $dataRevisioFormat)."
					".$this->__mostrarInput(1,"","NOM TUTOR", "active", "nomTutor-cercat", "no-edit", $nomTut." ".$cogTut)."

				</div>
				<div class='d-flex flex-column align-items-center justify-content-center w-100'>
					".$this->__mostrarInput(1,"","DATA RESOLUCIÓ", "active", "dataRes-cercat", "no-edit", $dadesResolFormat)."
					".$this->__mostrarInput(1,"","VALORACIÓ GTAF", "active", "valGtaf-cercat", "no-edit", $dataValGtafFormat)."
					".$this->__mostrarInput(1,"","INFORME", "active", "dataInforme-".$aula."-cercat", "no-edit", $dataInfFormat)."
					".$this->__mostrarInput(1,"","OBS", "active", "obs-".$aula."-cercat", "no-edit", $obs)."
				</div>
			</div>";

			$mostrar .= "<div id='dades-aula-".$aula."' class='d-flex flex-column
			justify-content-center align-items-center my-2 w-100 dades-aula'>".$titol.$botonsEstat.$dades.$alertError."</div>";
		}

		return $mostrar;
	}

	private function __modalConsultaAlumnes_resultatCerca() {
		$mostrar = $this->__mostrarModalConsulta("modalConsultaAlumnes", 0, 0, '', '');
		return $mostrar;
	}

	/**
   * @brief Mostra els alumnes que s'han matriculat al curs $curs durant l'any $any i el $mes  l'aula $aula
   * @return Mostra els alumnes que s'han matriculat al curs $curs durant l'any $any i el $mes  l'aula $aula
   */
	public function modalConsultaAlumnes_resultatCerca($any, $curs, $mes, $aula) {

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarInscrCursGrup"] ) ) {
			$stmt->bind_param("dsss", $any, $mes, $curs, $aula);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($nom, $cognoms, $dni, $correu, $certificat, $apagar, $pagament, $inscrit);

				$table = "<table class='table table-striped table-hover text-center mt-2'>
				<thead><tr>
					<th>NOM</th>
					<th>COGNOMS</th>
					<th>DNI</th>
					<th>CORREU</th>
					<th>CERTIFICAT</th>
					<th>FALTA PAGAR</th>
					<th>INSCRIT</th>
					<th>+INFO</th>
				</tr></thead>
				<tbody>";

				while ( $stmt->fetch() ) {
					if ( $inscrit == 'X' || $inscrit == 'C' ) {
						$faltaPagar = "-";
					}
					else {
						if ( $apagar - $pagament > 0 ) {
							$faltaPagar = "<strong class='text-danger'>".( floatval($apagar - $pagament) )."</strong>";
						}
						else {
							$faltaPagar = "0";
						}
					}

					$labelInscrit = $this->obtenirLabel('', 'lightGray', $inscrit);
					if ( $inscrit == "0" ) $labelInscrit = $this->obtenirLabel('', 'lightOrange', 'NO INSCRIT');
					else if ( $inscrit == "1" ) $labelInscrit = $this->obtenirLabel('', 'lightGreen', 'INSCRIT');
					else if ( $inscrit == "C" ) $labelInscrit = $this->obtenirLabel('', 'lightGray', 'CANVI');
					else if ( $inscrit == "X" ) $labelInscrit = $this->obtenirLabel('', 'lightGray', 'BAIXA');
					else if ( $inscrit == "M" ) $labelInscrit = $this->obtenirLabel('', 'lightGray', 'MORÒS');

					$botoConsAlumne = "<button id='cons-dades-".$dni."' role='button' class='boto-blau px-4 d-flex cnsDadesAlumne'><i class='material-icons text-white ml-1'>search</i></button>";

					$table .= "<tr>";
					$table .= "<td>".$nom."</td>";
					$table .= "<td>".$cognoms."</td>";
					$table .= "<td>".$dni."</td>";
					$table .= "<td>".$correu."</td>";
					$table .= "<td>".$certificat."</td>";
					$table .= "<td>".$faltaPagar."</td>";
					$table .= "<td>".$labelInscrit."</td>";
					$table .= "<td>".$botoConsAlumne."</td>";
					$table .= "</tr>";
				}

				$table .= "</tbody></table>";
			}
			else {
				$table = "<p>No hi han alumnes matriculats en aquesta edició.</p>";
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4312);
		}

		$conWeb->desconectarBD();

		return $table;
	}

	public function buscarUrlPaginaWeb($codiCurs) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		/* Buscar la ID_URL a info corresponent al curs i relacionar-le amb amigable*/
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarCursUrlRel"] ) ) {
			$stmt->bind_param("s", $codiCurs);
			$stmt->execute();
			$stmt->store_result();
			if ( $stmt->num_rows() > 0 ) {
				$stmt->bind_result($urlWeb);
				$stmt->fetch();
			}
		}
		else {
			throw new Exception('', 4312);
		}
		$conWeb->closeStmt();

		return $urlWeb;
	}

	/**
	* @brief Substitueix els camp NOM CURS per $nomCurs, DATA INICI per $dataI,
	* 			DATA FI per $dataF, HORES per $hores, CURS ESCOLAR per $cursEsc,
	* 			CODI GTAF per $codiGtaf, CODI FISS per $codiFiss, DATA RESOL per $dataRes,
	* 			DATA QUALIFICACIÓ per $dataQual, VALORACIÓ GTAF per $valGtaf,
	*			VALORACIÓ FISS per $valFiss on la id Curs és $idCurs
	* @return Substitueix els camp NOM CURS per $nomCurs, DATA INICI per $dataI,
	* 			DATA FI per $dataF, HORES per $hores, CURS ESCOLAR per $cursEsc,
	* 			CODI GTAF per $codiGtaf, CODI FISS per $codiFiss, DATA RESOL per $dataRes,
	* 			DATA QUALIFICACIÓ per $dataQual, VALORACIÓ GTAF per $valGtaf,
	*			VALORACIÓ FISS per $valFiss on la id Curs és $idCurs a la taula cursos
	*			i a curs juntament amb aula
	*/
	public function desarCanvisDadesEdicio($idCurs, $nomCurs, $dataI, $dataF,
	$hores, $cursEsc, $codiGtaf, $codiFiss, $dataRes, $dataQual, $dataBloq, $valGtaf, $valFiss, $obs) {
		require_once 'Date.php';
		if ( $dataI != '' ) {
			$objDate = new Date( $dataI );
			$dataI = $objDate->getDataFomatYYYYMMDD_HHMMSS();
		}
		else
			$dataI = null;

		if ( $dataF != '' ) {
			$objDate = new Date( $dataF );
			$dataF = $objDate->getDataFomatYYYYMMDD_HHMMSS();
		}
		else
			$dataF = null;

		if ( $dataRes != '' ) {
			$objDate = new Date( $dataRes );
			$dataRes = $objDate->getDataFomatYYYYMMDD_HHMMSS();
		}
		else
			$dataRes = null;

		if ( $dataQual != '' ) {
			$objDate = new Date( $dataQual );
			$dataQual = $objDate->getDataFomatYYYYMMDD_HHMMSS();
		}
		else
			$dataQual = null;

		if ( $dataBloq != '' ) {
			$objDate = new Date( $dataBloq );
			$dataBloq = $objDate->getDataFomatYYYYMMDD_HHMMSS();
		}
		else
			$dataBloq = null;

		if ( $valGtaf != '' ) {
			$objDate = new Date( $valGtaf );
			$valGtaf = $objDate->getDataFomatYYYYMMDD_HHMMSS();
		}
		else
			$valGtaf = null;

		if ( $valFiss != '' ) {
			$objDate = new Date( $valFiss );
			$valFiss = $objDate->getDataFomatYYYYMMDD_HHMMSS();
		}
		else
			$valFiss = null;

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();
		$likeIdCurs = $idCurs."%";

		echo $this->consultesBD_Web["updEdicioCursosAntic"]."\n";
		echo $nomCurs."\n".$dataI."\n".$dataF."\n".$hores."\n".$cursEsc."\n".$codiGtaf."\n".$codiFiss."\n".$dataRes."\n".$dataQual."\n".$valGtaf."\n".$valFiss."\n".$obs."\n".$likeIdCurs."\n\n";
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["updEdicioCursosAntic"] ) ) {
			$stmt->bind_param("sssdssssssssss", $nomCurs, $dataI, $dataF, $hores, $cursEsc,
			$codiGtaf, $codiFiss, $dataRes, $dataQual, $dataBloq, $valGtaf, $valFiss, $obs, $likeIdCurs);
			$likeIdCurs = $idCurs."%";
			$stmt->execute();
			$conWeb->closeStmt();

			$mostrar = "OK";
		}
		else {
			throw new Exception('', 4313);
		}

		echo $this->consultesBD_Web["updEdicioCursos"]."\n";
		echo $nomCurs."\n".$dataI."\n".$dataF."\n".$hores."\n".$cursEsc."\n".$codiGtaf."\n".$codiFiss."\n".$dataRes."\n".$dataQual."\n".$valGtaf."\n".$valFiss."\n".$obs."\n".$idCurs."\n\n";
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["updEdicioCursos"] ) ) {
			$stmt->bind_param("sssdssssssssss", $nomCurs, $dataI, $dataF, $hores, $cursEsc,
			$codiGtaf, $codiFiss, $dataRes, $dataQual, $dataBloq, $valGtaf, $valFiss, $obs, $idCurs);
			$stmt->execute();
			$conWeb->closeStmt();
			$mostrar = "OK";
		}
		else {
			throw new Exception('', 4314);
		}
		$conWeb->desconectarBD();

		return $mostrar;
	}

	/**
	* @brief Substitueix els camp DATA REVISIÓ per $nomCurs, DATA INICI per $dataI,
	* 			DATA INFORME per $dataF, DATA BLOQUEIG per $hores, OBSERVACIONS per $cursEsc
	*			on la id Curs és $idCurs i l'aula és $aula
	* @return Substitueix els camp DATA REVISIÓ per $nomCurs, DATA INICI per $dataI,
	* 			DATA INFORME per $dataF, DATA BLOQUEIG per $hores, OBSERVACIONS per $cursEsc
	*			on la id Curs és $idCurs i l'aula és $aula
	*/
	public function desarCanvisDadesAulaEdicio($idCurs, $aula, $dataRevisio,
	$dataInforme, $obs, $idAula) {
		require_once 'Date.php';
		if ( $dataRevisio != '' ) {
			$objDate = new Date( $dataRevisio );
			$dataRevisio = $objDate->getDataFomatYYYYMMDD_HHMMSS();
		}
		else
			$dataRevisio = null;

		if ( $dataInforme != '' ) {
			$objDate = new Date( $dataInforme );
			$dataInforme = $objDate->getDataFomatYYYYMMDD_HHMMSS();
		}
		else
			$dataInforme = null;

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		$likeIdCurs = $idCurs.$aula;
		echo $this->consultesBD_Web["updEdicioAulaCursosAntic"]."\n";
		echo $dataRevisio."\n".$dataInforme."\n".$dataBloq."\n".$likeIdCurs."\n\n";
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["updEdicioAulaCursosAntic"] ) ) {
			$stmt->bind_param("ssss", $dataRevisio, $dataInforme, $obs, $likeIdCurs);
			$likeIdCurs = $idCurs.$aula;
			$stmt->execute();
			$conWeb->closeStmt();

			$mostrar = "OK";
		}
		else {
			throw new Exception('', 4315);
		}

		if ( $idAula == "0" ) {
			throw new Exception('', 4317);
		}

		echo $this->consultesBD_Web["updEdicioAulaCursos"]."\n";
		echo $dataRevisio."\n".$dataInforme."\n".$dataBloq."\n".$idAula."\n".$aula."\n\n";
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["updEdicioAulaCursos"] ) ) {
			$stmt->bind_param("sssds", $dataRevisio, $dataInforme, $obs, $idAula, $aula);
			$stmt->execute();
			$conWeb->closeStmt();
			$mostrar = "OK";
		}
		else {
			throw new Exception('', 4316);
		}
		$conWeb->desconectarBD();
	}

