	/**
	* @brief Mostra els cursos que comencen en una edició ordenats
	* @return Mostra els cursos disponibles a l'edició del mes $mes i de l'any $any ordenats per $oderby i en ascendent segons $asc
	*/
	public function mostrarCursos_CursosOberts($any, $mes, $orderby, $asc) {
		//$mostrar = "hello".$any." ".$mes." ".$orderby." ".$asc;

		if ($orderby != 'codi' && $orderby!='titol' && $orderby!='existeix' && $orderby!='visible' && $orderby!='hores' && $orderby!='estat')
			$orderby = 'codi';
		if ($asc!=1 and $asc!=0)
			$asc = 1;

		function cmpCodi($a, $b) {
		    if ($a[0] == $b[0]) {
		        return 0;
		    }
		    return ($a[0] < $b[0]) ? -1 : 1;
		}

		function cmpTitol($a, $b) {
		    if ($a[1] == $b[1]) {
		        return 0;
		    }
		    return ($a[1] < $b[1]) ? -1 : 1;
		}

		function cmpHores($a, $b) {
		    if ($a[2] == $b[2]) {
		        return 0;
		    }
		    return ($a[2] < $b[2]) ? -1 : 1;
		}

		function cmpEstatMdl($a, $b) {
		    if ($a[8] == $b[8]) {
		        return 0;
		    }
		    return ($a[8] < $b[8]) ? -1 : 1;
		}

		function cmpUrlMdl($a, $b) {
		    if ($a[7] == $b[7]) {
		        return 0;
		    }
		    return ($a[7] < $b[7]) ? -1 : 1;
		}

		function cmpCursVisble($a, $b) {
		    if ($a[6] == $b[6]) {
		        return 0;
		    }
		    return ($a[6] < $b[6]) ? -1 : 1;
		}

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();
		$conWeb2 = new ConnexioWeb();
		$conWeb2->connectarBD();

		require_once 'ConnexioMoodle.php';
		$connexioModdle1 = new ConnexioMoodle();
		$connexioModdle1->connectarBD();

		$i = 0;

		/* Buscar tots els cursos de l'any $any i del mes $mes.*/
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["cnsCursosOberts"] ) ) {
			$stmt->bind_param("ds", $any, $mes);
			$stmt->execute();
			$stmt->bind_result($titolCurs, $codiCurs, $hores, $aula, $estat);
			while ( $stmt->fetch() ) {
				$resultats[$i][0] = $codiCurs;
				$resultats[$i][1] = $titolCurs;
				$resultats[$i][2] = $hores;
				$resultats[$i][3] = $aula;

				/* buscar el nº inscrits i el nº de pagats */
				if ( $stmt2=$conWeb2->prepare( $this->consultesBD_Web["cnsNumInscAula"] ) ) {
					$stmt2->bind_param("dsss", $any, $mes, $codiCurs, $aula);
					$stmt2->execute();
					$stmt2->bind_result($nInsc);
					$stmt2->fetch();
					$conWeb2->closeStmt();
				}
				else {
					throw new Exception('', 4337);
				}

				$resultats[$i][4] = $nInsc;

				$idEstat = 'estat-'.$any."-".$mes.'-'.$codiCurs;
				if ( $estat == 'P' ) $labelEstat = $this->obtenirLabel($idEstat, 'lightOrange', 'PENDENT');
				if ( $estat == '0' ) $labelEstat = $this->obtenirLabel($idEstat, 'lightRed', 'ANUL·LAT');
				if ( $estat == '1' || $estat == 'T' ) $labelEstat = $this->obtenirLabel($idEstat, 'lightGreen', 'ACTIU');

				$resultats[$i][5] = $labelEstat;
				$resultats[$i][8] = $estat;

				$idMoodle = '';
				$visibleCursMoodle = 0;
				$existCursMoodle = 0;
				$idCursAula = $any.$codiCurs.$mes.$aula;

				//Busco si existeix el idCurs en el moodle nou.
				if ( $stmt3=$connexioModdle1->prepare( $this->consultesBD_Moodle["buscarCursVisble"] ) ) {
					$stmt3->bind_param("s", $idCursAula);
					$stmt3->execute();
					$stmt3->store_result();
					if ( $stmt3->num_rows() > 0 ) { //num_Rows
						$existCursMoodle = 1;
						$stmt3->bind_result($idCursMoodle, $visible);
						$stmt3->fetch();

						//Busco el camp visible i el id del curs del moodle nou del curs $idCurs
						if ( $visible == 1 ) {
							$visibleCursMoodle = 1;
						}
						$idMoodle = 'linkAulaCurs-nou-'.$idCursMoodle;
					}
					/*else {
						require_once 'ConnexioMoodleAntic.php';

						$connexioModdle2 = new ConnexioMoodleAntic();
						$connexioModdle2->connectarBD();

						//Busco si existeix el idCurs en el moodle antic.
						if ( $stmt4=$connexioModdle2->prepare( $this->consultesBD_MoodleAntic["buscarCursVisble"] ) ) {
							$stmt4->bind_param("s", $idCursAula);
							$stmt4->execute();
							$stmt4->store_result();
							if ( $stmt4->num_rows() > 0 ) { //num_Rows
								$existCursMoodle = 1;
								$stmt4->bind_result($idCursMoodle, $visible);
								$stmt4->fetch();
								//Busco el camp visible i el id del curs del moodle antic del curs $idCurs
								if ( $visible == 1 ) {
									$visibleCursMoodle = 1;
								}
								$idMoodle = 'linkAulaCurs-antic-'.$idCursMoodle;
							}
						}
						else {
							throw new Exception('', 4310);
						}
					}*/
				}
				else {
					throw new Exception('', 4311);
				}

				$visibleMoodle = $this->obtenirLabelVisibleMoodle($visibleCursMoodle, $existCursMoodle);
				$urlMoodle = $this->obtenirLabelUrl($idMoodle, '', $existCursMoodle, "MOODLE");

				$resultats[$i][6] = $visibleMoodle;
				$resultats[$i][7] = $urlMoodle;

				$i++;

			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('', 4336);
		}

		$connexioModdle1->desconectarBD();
		$conWeb2->desconectarBD();
		$conWeb->desconectarBD();


		if ($orderby == 'codi') usort($resultats, "cmpCodi");
		else if ($orderby == 'titol') usort($resultats, "cmpTitol");
		else if ($orderby == 'hores') usort($resultats, "cmpHores");
		else if ($orderby == 'estat') usort($resultats, "cmpEstatMdl");
		else if ($orderby == 'existeix') usort($resultats, "cmpUrlMdl");
		else if ($orderby == 'visible') usort($resultats, "cmpCursVisble");

		$classCurs = '';
		$classTitol = '';
		$classHores = '';
		$classEstat = '';
		$classExisteix = '';
		$classVisible = '';

		if ($asc == 1) { //s'ordena ascendentment
			if ($orderby == 'codi') $classCurs = ' asc';
			else if ($orderby == 'titol') $classTitol = ' asc';
			else if ($orderby == 'estat') $classEstat = ' asc';
			else if ($orderby == 'existeix') $classExisteix = ' asc';
			else if ($orderby == 'visible') $classVisible = ' asc';
		}
		else { //s'ordena desscendentment
			if ($orderby == 'codi') $classCurs = ' desc';
			else if ($orderby == 'titol') $classTitol = ' desc';
			else if ($orderby == 'estat') $classEstat = ' desc';
			else if ($orderby == 'existeix') $classExisteix = ' desc';
			else if ($orderby == 'visible') $classVisible = ' desc';
		}

		//Mostra usuaris en format d'una taula ordenats per dni;
		$table = "<table class='table table-striped table-hover table-order text-center'>
		<thead>
			<tr>
				<th id='th-codi' class='sorting".$classCurs."'>CURS</th>
				<th id='th-titol' class='sorting".$classTitol."'>TÍTOL</th>
				<th id='th-hores' class='sorting".$classHores."'>HORES</th>
				<th>AULA</th>
				<th>INSCRITS</th>
				<th id='th-estat' class='sorting".$classEstat."'>ESTAT</th>
				<th id='th-existeix' class='sorting".$classExisteix."'>MOODLE</th>
				<th id='th-visible' class='sorting".$classVisible."'>VISIBLE</th>
				</tr>
		</thead>
		<tbody>";

		if ($asc == 1) {
			$inici = 0;
			$fi = count($resultats);
			for ($i = $inici; $i<$fi; $i++) {
				$table .= "
				<td>".$resultats[$i][0]."</td>
				<td>".$resultats[$i][1]."</td>
				<td>".$resultats[$i][2]."</td>
				<td>".$resultats[$i][3]."</td>
				<td>".$resultats[$i][4]."</td>
				<td>".$resultats[$i][5]."</td>
				<td>".$resultats[$i][7]."</td>
				<td>".$resultats[$i][6]."</td>
				</tr>";
			}
		}
		else {
			$inici = count($resultats);
			$fi = 0;
			for ($i = $inici-1; $i>=$fi; $i--) {
				$table .= "
				<td>".$resultats[$i][0]."</td>
				<td>".$resultats[$i][1]."</td>
				<td>".$resultats[$i][2]."</td>
				<td>".$resultats[$i][3]."</td>
				<td>".$resultats[$i][4]."</td>
				<td>".$resultats[$i][5]."</td>
				<td>".$resultats[$i][7]."</td>
				<td>".$resultats[$i][6]."</td>
				</tr>";
			}
		}

		$table .= "</tbody></table>";

		$mostrar = "<div class='d-flex flex-column justify-content-center align-items-center
				w-100 text-center border-bottom card-header'>
				<p class='title font-weight-bold text-center py-3 mb-0 align-items-center
				justify-content-center d-flex'>RESULTATS DE LA CERCA ".$mes."/".$any."</p>
			</div>
		<div class='card-body px-0'>
			".$table."
		</div>";

		return $mostrar;
	}

