	/**
	* @brief Creo un curs a la tual curs i cursos de la base de dades de gstió.
	* @return Afegeix a la taula de cursos i de curs un curs amb idCurs $idCurs i any $any,
	* mes $mes, un codi curs $codiCurs, amb nom del curs $nomCurs amb dates d'inici i de fix
	* $datai $dataf, amb aula $aula, id aula $idAula, id preu $idPreu i public 1.
	*/
	public function insertCurs($idCurs, $any, $mes, $codiCurs, $cursEscolar,
	$codiGtaf, $nomCurs, $dataI, $dataF, $aula, $idAula, $idPreu, $public, $hores, $dataRes) {

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["insertCurs"] ) ) {
			$stmt->bind_param("sdssdsssddsssd", $idCurs, $any, $mes, $codiCurs, $idAula, $nomCurs,
			$dataI, $dataF, $hores, $idPreu, $cursEscolar, $codiGtaf, $dataRes, $public );
			$stmt->execute();
			$idInserit = $conWeb->lastInsertId();
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('', 4325);
		}
		echo $this->consultesBD_Web["insertCurs"]."<br />".$idCurs."<br />".$any."<br />".$mes."<br />".$codiCurs."<br />".$idAula."<br />".$nomCurs."<br />".$dataI."<br />".$dataF."<br />".$hores."<br />".$idPreu."<br />".$cursEscolar."<br />".$codiGtaf."<br />".$public."<br />".$dataRes."<br /><br />";
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["insertAula"] ) ) {
			$stmt->bind_param("ds", $idAula, $aula );
			$stmt->execute();
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('', 4327);
		}
		echo $this->consultesBD_Web["insertAula"];

		$objDataI = new Date($dataI);
		$dataLlargaI = $objDataI->getDataLlarga();
		$objDataF = new Date($dataF);
		$dataLLargaF = $objDataF->getDataLlarga();
		$objDataRes = new Date($dataRes);
		$dataLLargaResol = $objDataRes->getDataLlarga();

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["insertCursos"] ) ) {
			$stmt->bind_param("sdssssssssddssss", $idCursAmbAula, $any, $mes, $codiCurs, $aula, $nomCurs,
			$dataI, $dataLlargaI, $dataF, $dataLLargaF, $hores, $idPreu, $cursEscolar, $codiGtaf, $dataRes, $dataLLargaResol);
			$idCursAmbAula = $idCurs.$aula;
			$stmt->execute();
			$stmt->fetch();
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('', 4326);
		}
		echo $this->consultesBD_Web["insertCursos"]."<br />".$idCurs."<br />".$any."<br />".$mes."<br />".$codiCurs."<br />".$aula."<br />".$nomCurs."<br />".$dataI."<br />".$dataLlargaI."<br />".$dataF."<br />".$dataLLargaF."<br />".$hores."<br />".$idPreu."<br />".$cursEscolar."<br />".$codiGtaf."<br />".$dataRes."<br />".$dataLLargaResol."<br />";
		$conWeb->desconectarBD();
	}

	/**
	* @brief Creo un curs a la tual curs i cursos de la base de dades de gstió.
	* @return Afegeix a la taula de cursos i de curs un curs amb idCurs $idCurs i any $any,
	* mes $mes, un codi curs $codiCurs, amb nom del curs $nomCurs amb dates d'inici i de fix
	* $datai $dataf, amb aula $aula, id aula $idAula, id preu $idPreu i public 1.
	*/
	public function inserirNumTramit($dataRes, $numTramit) {

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["insertNumTramit"] ) ) {
			$stmt->bind_param("ssd", $dataRes, $numTramit, $estat );
			$estat = 1;
			$stmt->execute();
			$idInserit = $conWeb->lastInsertId();
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('', 4328);
		}
		// echo $this->consultesBD_Web["insertNumTramit"]."<br />".$dataRes."<br />".$numTramit."<br />".$estat."<br />";
		$conWeb->desconectarBD();
	}

