 	/**
	* @brief Mostra els cursos que comencen en una edició ordenats
	* @return Mostra els cursos disponibles a l'edició del mes $mes i de l'any $any ordenats per $oderby i en ascendent segons $asc
	*/
	public function mostrarCursos_PreviIniciCursos($any, $mes, $orderby, $asc) {
		$mostrar = "hello".$any." ".$mes." ".$orderby." ".$asc;

		if ($orderby != 'codi' && $orderby!='titol' && $orderby!='estat')
			$orderby = 'codi';
		if ($asc!=1 and $asc!=0)
			$asc = 1;

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();
		$conWeb2 = new ConnexioWeb();
		$conWeb2->connectarBD();

		$i=0;

		/* Buscar tots els cursos de l'any $any i del mes $mes.*/
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["cnsCursos"] ) ) {
			$stmt->bind_param("ds", $any, $mes);
			$stmt->execute();
			$stmt->bind_result($codiCurs, $titolCurs, $estat);
			while ( $stmt->fetch() ) {
				$resultats[$i][0] = $codiCurs;
				$resultats[$i][1] = $titolCurs;

				/* buscar el nº inscrits i el nº de pagats */
				if ( $stmt2=$conWeb2->prepare( $this->consultesBD_Web["cnsNumInsc"] ) ) {
					$stmt2->bind_param("dss", $any, $mes, $codiCurs);
					$stmt2->execute();
					$stmt2->bind_result($nInsc);
					$stmt2->fetch();
					$conWeb2->closeStmt();
				}
				else {
					throw new Exception('', 4337);
				}
				if ( $stmt2=$conWeb2->prepare( $this->consultesBD_Web["cnsNumPag"] ) ) {
					$stmt2->bind_param("dss", $any, $mes, $codiCurs);
					$stmt2->execute();
					$stmt2->bind_result($nPag);
					$stmt2->fetch();
					$conWeb2->closeStmt();
				}
				else {
					throw new Exception('', 4338);
				}

				$resultats[$i][2] = $nInsc;
				$resultats[$i][3] = $nPag;

				$idEstat = 'estat-'.$any."-".$mes.'-'.$codiCurs;
				if ( $estat == 'P' ) $labelEstat = $this->obtenirLabel($idEstat, 'lightOrange', 'PENDENT');
				if ( $estat == '0' ) $labelEstat = $this->obtenirLabel($idEstat, 'lightRed', 'ANUL·LAT');
				if ( $estat == '1' ) $labelEstat = $this->obtenirLabel($idEstat, 'lightGreen', 'ACTIU');
				if ( $estat == 'T' ) $labelEstat = $this->obtenirLabel($idEstat, 'lightPurple', 'TANCAT');

				$nRegals = 0;
				$nEntitats = 0;

				$resultats[$i][4] = $labelEstat;

				if ( $stmt2=$conWeb2->prepare( $this->consultesBD_Web["buscarNumEdicio"] ) ) {
					$stmt2->bind_param("ssdss", $likeObs, $tipusInsc, $any, $mes, $codiCurs);
					$likeObs = '%CURS REGAL%';
					$tipusInsc = 'R';
					$stmt2->execute();
					$stmt2->bind_result($nRegals);
					$stmt2->fetch();
					$conWeb2->closeStmt();
				}
				else {
					throw new Exception('', 4370);
				}
				if ( $stmt2=$conWeb2->prepare( $this->consultesBD_Web["buscarNumInscEntitats"] ) ) {
					$stmt2->bind_param("dss", $any, $mes, $codiCurs);
					$stmt2->execute();
					$stmt2->bind_result($nEntitats);
					$stmt2->fetch();
					$conWeb2->closeStmt();
				}
				else {
					throw new Exception('', 4371);
				}

				$resultats[$i][5] = $nRegals;
				$resultats[$i][6] = $nEntitats;

				$i++;

			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('', 4336);
		}

		function cmpCodi($a, $b) {
		    if ($a[0] == $b[0]) {
		        return 0;
		    }
		    return ($a[0] < $b[0]) ? -1 : 1;
		}

		function cmpTitol($a, $b) {
		    if ($a[1] == $b[1]) {
		        return 0;
		    }
		    return ($a[1] < $b[1]) ? -1 : 1;
		}

		function cmpEstat($a, $b) {
		    if ($a[3] == $b[3]) {
		        return 0;
		    }
		    return ($a[3] < $b[3]) ? -1 : 1;
		}

		if ($orderby == 'codi') usort($resultats, "cmpCodi");
		else if ($orderby == 'titol') usort($resultats, "cmpTitol");
		else if ($orderby == 'estat') usort($resultats, "cmpEstat");

		$conWeb2->desconectarBD();
		$conWeb->desconectarBD();

		$classCurs = '';
		$classTitol = '';
		$classEstat = '';

		if ($asc == 1) { //s'ordena ascendentment
			if ($orderby == 'codi') $classCurs = ' asc';
			else if ($orderby == 'titol') $classTitol = ' asc';
			else if ($orderby == 'estat') $classEstat = ' asc';
		}
		else { //s'ordena desscendentment
			if ($orderby == 'codi') $classCurs = ' desc';
			else if ($orderby == 'titol') $classTitol = ' desc';
			else if ($orderby == 'estat') $classEstat = ' desc';
		}

		//Mostra usuaris en format d'una taula ordenats per dni;
		$table = "<table class='table table-striped table-hover table-order text-center'>
		<thead>
			<tr>
				<th id='th-codi' class='sorting".$classCurs."'>CURS</th>
				<th id='th-titol' class='sorting".$classTitol."'>TÍTOL</th>
				<th>INSCRITS</th>
				<th>PAGATS</th>
				<th>ALTRES</th>
				<th id='th-estat' class='sorting".$classEstat."'>ESTAT</th>
				<th>ACCIO</th>
				</tr>
		</thead>
		<tbody>";

		if ($asc == 1) {
			$inici = 0;
			$fi = count($resultats);
			for ($i = $inici; $i<$fi; $i++) {
				if ( $resultats[$i][3] < 10 && $resultats[$i][3] < 5 )
					$table .= "<tr class='text-danger'>";
				else
					$table .= "<tr>";

				$textRegals = "";
				$textAltres = "0";

				if ( $resultats[$i][5] > 0 ) {
					$textRegals = " (+ ".$resultats[$i][5]." REGAL";
					if ( $resultats[$i][6] > 1 )
						$textRegals .= "S";
					$textRegals .= ")";
				}
				if ( $resultats[$i][6] > 0 ) {
					$textAltres = $resultats[$i][6]." D'ENTITAT";
					if ( $resultats[$i][6] > 1 ) $textAltres .= "S";
				}
				$table .= "
				<td>".$resultats[$i][0]."</td>
				<td>".$resultats[$i][1]."</td>
				<td>".$resultats[$i][2]."</td>
				<td>".$resultats[$i][3].$textRegals."</td>
				<td>".$textAltres."</td>
				<td>".$resultats[$i][4]."</td>
				<td><i id='cns-info-".$resultats[$i][0]."' class='infoCurs material-icons'>info</i></td>
				</tr>";
			}
		}
		else {
			$inici = count($resultats);
			$fi = 0;
			for ($i = $inici-1; $i>=$fi; $i--) {
				if ( $resultats[$i][3] < 10 && $resultats[$i][3] < 5 )
					$table .= "<tr class='text-danger'>";
				else
					$table .= "<tr>";

				$textRegals = "";
				$textAltres = "0";

				if ( $resultats[$i][5] > 0 ) {
					$textRegals = " (+ ".$resultats[$i][5]." REGAL";
					if ( $resultats[$i][6] > 1 )
						$textRegals .= "S";
					$textRegals .= ")";
				}
				if ( $resultats[$i][6] > 0 ) {
					$textAltres = $resultats[$i][6]." D'ENTITAT";
					if ( $resultats[$i][6] > 1 ) $textAltres .= "S";
				}
				$table .= "
				<td>".$resultats[$i][0]."</td>
				<td>".$resultats[$i][1]."</td>
				<td>".$resultats[$i][2]."</td>
				<td>".$resultats[$i][3].$textRegals."</td>
				<td>".$textAltres."</td>
				<td>".$resultats[$i][4]."</td>
				<td><i id='cns-info-".$resultats[$i][0]."' class='material-icons'>info</i></td>
				</tr>";
			}
		}

		$table .= "</tbody></table>";

		$mostrar = "<div class='d-flex flex-column justify-content-center align-items-center
				w-100 text-center border-bottom card-header'>
				<p class='title font-weight-bold text-center py-3 mb-0 align-items-center
				justify-content-center d-flex'>RESULTATS DE LA CERCA ".$mes."/".$any."</p>
			</div>
		<div class='card-body px-0'>
			".$table."
			<div class='card-footer d-flex justify-content-center align-items-center'>
				<button id='guardar-canvis-envia' role='button' class='boto-blau px-4 d-flex'>
					Desa canvis i envia
					<i class='material-icons ml-1'>save</i>
				</button>
			</div>
		</div>";

		return $mostrar;
	}

	/**
	* @brief Desa el canvi d'estat a la taula curs i cursos i envia un missatge a qui pertoqui
	* @return Desa els canvis a curs ( es posarà una P a estat a la taula curs si $estat == 'PENDENT'
	* es posarà un 0 a estat, un 13 a ID_CUHO si $estat == ANUL·LAT i es posarà un 1 a estat
	* si $estat == ACTIU).
	* Desa els canvis a cursos ( es posarà una # a codi_udg si $estat == 'PENDENT'
	* es posarà un 0 a DNI_TUTOR, un 13 a ID_CUHO i NULL a codi_udg si $estat == ANUL·LAT
	* i es posarà un NULL a codi_udg si $estat == ACTIU).
	* S'enviarà un missatge al tutor/a pertinent en cada cas.
	* S'enviarà un missatge a l'alumne en cas que estat == ANUL·LAT o en cas que estat == ACTIU.
	*/
	public function desarCanvisEstatEnviarMsg_PreviIniciCursos($any, $mes, $curs, $estatAnt, $estat) {
		// $mostrar = "hello:<br>
		// <strong>ANY:</strong> ".$any." <br>
		// <strong>MES:</strong> ".$mes." <br>
		// <strong>CURS:</strong> ".$curs." <br>
		// <strong>ESTAT ANTERIOR:</strong> ".$estatAnt." <br>
		// <strong>ESTAT ACTUAL:</strong> ".$estat."<br><hr><br>";

		$qui = $this->usuari->getNom()->get()." ".$this->usuari->getCognom()->get();
		$depart = $this->usuari->getDepart()->get();

		/* ########################          SMTP          ######################## */
		$authSecre = $this->getAuthSMTP_Secretaria();
		$userSecre = $authSecre[0];
		$passSecre = $authSecre[1];
		$nameUserSecre = $authSecre[2];

		$nomFromHead = $nameUserSecre;
		$correuFromHead = $userSecre;

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();
		$conWeb2 = new ConnexioWeb();
		$conWeb2->connectarBD();

		/* ########################       ANULAR CURSOS       ######################## */
		if ( $estat == 'ANUL·LAR' || $estat == 'ANUL·LAT' ) {
			echo "ANULAT<BR>";
			if ( $estatAnt != 'ANUL·LAR' && $estatAnt != 'ANUL·LAT' ) {
				require_once 'Date.php';

				// Consultar dades del curs actual
				// echo "<strong style='color: #e91e63'>Buscar dades del curs</strong><br>";
				if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarCursSegEd"] ) ) {
					$stmt->bind_param("dss", $any, $mes, $curs);
					$stmt->execute();
					$stmt->bind_result($nomCurs, $dataI, $dataF, $hores, $idPreu);
					$stmt->fetch();

					$objDataI = new Date($dataI);

					echo "<strong style='color: #597bb8'>".$this->consultesBD_Web["buscarCursSegEd"]."</strong><br>
					<span style='color: #597bb8'>".$any."</span><br>
					<span style='color: #597bb8'>".$mes."</span><br>
					<span style='color: #597bb8'>".$curs."</span><br>
					".$nomCurs."<br>".$dataI."<br>".$dataF."<br>".$hores."<br>".$idPreu."<br><hr>";
				}
				else {
					throw new Exception('', 4351);
				}
				$conWeb->closeStmt();

				/* ##############           Avís MSG al tutor           ############## */
				echo "<strong style='color: #e91e63'>MSG del tutor</strong><br>";

				// Consultar dades del tutor del curs actual
				if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarDadesPersonalByCurs"] ) ) {
					$stmt->bind_param("dssssd", $any, $mes, $curs, $aula, $perfil, $estatPersonal);
					$aula = 'A';
					$perfil = 'tutor';
					$estatPersonal = 1;
					$stmt->execute();
					$stmt->bind_result($dniTutor, $nomTutor, $cogTutor, $correuTutorPrisma, $correuTutorPers);

					echo "<strong style='color: #597bb8'>".$this->consultesBD_Web["buscarDadesPersonalByCurs"]."</strong><br>
					<span style='color: #597bb8'>".$any."</span><br>
					<span style='color: #597bb8'>".$mes."</span><br>
					<span style='color: #597bb8'>".$curs."</span><br>
					<span style='color: #597bb8'>".$aula."</span><br>
					<span style='color: #597bb8'>".$perfil."</span><br>
					<span style='color: #597bb8'>".$estatPersonal."</span><br>";
					require_once "MailSMTPComvive.php";
					while ( $stmt->fetch() ) {
						// echo "".$dniTutor."<br>".$nomTutor."<br>".$cogTutor."<br>".$correuTutorPrisma."<br>".$correuTutorPers."<br><hr>";

						if ( $nomTutor != 'PENDENT' ) {
							$subject = "Anul·lació del curs ".$nomCurs." (".$mes."/".$any.")";

							/* Obtinc el mes en lletres */
							$objMes = new Date("01-".$mes."-2021");
							$mesEdicioEscrit = $objMes->getNomMesArticle();

							$message = "<p>Hola, ".$nomTutor.",</p>
							<p>T'informem que hem anul·lat l'edició del mes ".$mesEdicioEscrit." del curs <strong style='color: #496baa'>".$nomCurs."</strong>.</p>
							<p>Ja hem avisat els alumnes.</p>
							<p>Atentament,</p>";

							$nomTo = $nameUserSecre;
							$correuTo = "resguard.secretaria@prisma.cat";
							$correuTo = "meriem.prisma.cat@gmail.com";
							$nomReplyHead = $nomTutor." ".$cogTutor;
							$correuReplyHead = $correuTutorPrisma;

							$mailSecre = new MailSMTPComvive($userSecre, $passSecre, $nomFromHead, $correuFromHead,
												 $nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
												 $subject, $message, $qui, $depart);

							$nomTo = "Suport PrisMa";
							$correuTo = "suport@prisma.cat";

							$mailSuport = new MailSMTPComvive($userSecre, $passSecre, $nomFromHead, $correuFromHead,
												 $nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
												 $subject, $message, $qui, $depart);

							$nomTo = "Suport Informàtic PrisMa";
							$correuTo = "suport.informatic@prisma.cat";

							$mailSuportInfo = new MailSMTPComvive($userSecre, $passSecre, $nomFromHead, $correuFromHead,
								$nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
								$subject, $message, $qui, $depart);

							$nomTo = $nomTutor." ".$cogTutor;
							$correuTo = $correuTutorPrisma;
							$nomReplyHead = $nameUserSecre;
							$correuReplyHead = $userSecre;
							$correuTo = "meriem.prisma.cat@gmail.com";

							$mailTutor1 = new MailSMTPComvive($userSecre, $passSecre, $nomFromHead, $correuFromHead,
												 $nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
												 $subject, $message, $qui, $depart);

							$nomTo = $nomTutor." ".$cogTutor;
							$correuTo = $correuTutorPers;
							$correuTo = "mrkt.prisma.cat@gmail.com";

							$mailTutor2 = new MailSMTPComvive($userSecre, $passSecre, $nomFromHead, $correuFromHead,
								$nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
								$subject, $message, $qui, $depart);

							$mostrar .= "<p>S'ha enviat un missatge d'avís al tutor <strong>".$nomTo."</strong> sobre l'anul·lació del curs <strong>".$nomCurs."</strong>.</p>";

							echo $subject."<br>".$message."<br><hr>";
						}
					}
				}
				else {
					throw new Exception('', 4351);
				}
				$conWeb->closeStmt();

				/* ##############     Donar de baixa el curs a curs     ############## */
				// echo "<strong style='color: #e91e63'>Donar de baixa el curs a curs</strong><br>";
				if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["updEstatCurs"] ) ) {
					$stmt->bind_param("sdss", $estatCurs, $any, $mes, $curs);
					$estatCurs = '0';
					$stmt->execute();
					echo "<strong style='colo: #597bb8'>".$this->consultesBD_Web["updEstatCurs"]."</strong><br>
					<span style='color: #597bb8'>".$estatCurs."</span><br>
					<span style='color: #597bb8'>".$any."</span><br>
					<span style='color: #597bb8'>".$mes."</span><br>
					<span style='color: #597bb8'>".$curs."</span><br><hr>";
				}
				else {
					throw new Exception('', 4339);
				}
				$conWeb->closeStmt();

				if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarDadesEdCursById"] ) ) {
					$stmt->bind_param("s", $idCurs);
					$idCurs = $any.$curs.$mes;
					$stmt->execute();
					$stmt->bind_result($any2, $mes2, $curs2, $nomCurs2, $datai2, $dataf2,
					$hores2, $cursEsc2, $gtaf2, $fiss2, $dataResol2, $dataQual2,
					$dataBloq2, $valGtaf2, $valFiss2, $idAula, $estat2, $public2, $obs2);
					$stmt->fetch();
					echo "<strong style='color: #597bb8'>".$this->consultesBD_Web["buscarDadesEdCursById"]."</strong><br>
					<span style='color: #597bb8'>".$idCurs."</span><br>
					".$any2."<br>".$mes2."<br>".$curs2."<br>".$nomCurs2."<br>".$datai2."<br>".$dataf2."<br>".$hores2."<br>".$cursEsc2."<br>".$gtaf2."<br>".$fiss2."<br>".$dataResol2."<br>".$dataQual2."<br>".$dataBloq2."<br>".$valGtaf2."<br>
					".$valFiss2."<br>".$idAula."<br>".$estat2."<br>".$public2."<br>".$obs2."<br><hr>";
				}
				else {
					throw new Exception('', 4342);
				}
				$conWeb->closeStmt();

				if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["updIdCuhoAula"] ) ) {
					$stmt->bind_param("dds", $idCuho, $idAula, $aula);
					$idCuho = 13;
					$aula = 'A';
					$stmt->execute();
					echo "<strong style='color: #597bb8'>".$this->consultesBD_Web["updIdCuhoAula"]."</strong><br>
					<span style='color: #597bb8'>".$idCuho."</span><br>
					<span style='color: #597bb8'>".$idAula."</span><br>
					<span style='color: #597bb8'>".$aula."</span><br><hr>";
				}
				else {
					throw new Exception('', 4343);
				}
				$conWeb->closeStmt();

				/* ##############    Donar de baixa el curs a cursos    ############## */
				echo "<strong style='color: #e91e63'>Donar de baixa el curs a cursos</strong><br>";

				if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["updEstatCursByAntic"] ) ) {
					$stmt->bind_param("sdsdsss", $dniTutor, $idCuho, $codiUdg, $any, $mes, $curs, $aula);
					$dniTutor = '0';
					$idCuho = 13;
					$aula = 'A';
					$codiUdg = '';
					$stmt->execute();
					echo "<strong style='color: #597bb8'>".$this->consultesBD_Web["updEstatCursByAntic"]."</strong><br>
					<span style='color: #597bb8'>".$dniTutor."</span><br>
					<span style='color: #597bb8'>".$idCuho."</span><br>
					<span style='color: #597bb8'>".$codiUdg."</span><br>
					<span style='color: #597bb8'>".$any."</span><br>
					<span style='color: #597bb8'>".$mes."</span><br>
					<span style='color: #597bb8'>".$curs."</span><br><hr>";
				}
				else {
					throw new Exception('', 4344);
				}
				$conWeb->closeStmt();

				$mostrar .= "<p>El curs <strong>".$nomCurs."</strong> de l'edició <strong>".$mes."/".$any."</strong> s'ha anul·lat correctament</p>";

				/* ############## Buscar les pròximes edicions del curs ############## */
				echo "<strong style='color: #e91e63'>Buscar les pròximes edicions del curs</strong><br>";
				if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarParamOrder"] ) ) {
					$stmt->bind_param("ss", $tipus, $orderBy);

					$tipus='limit-editions';
					$orderBy='DATAI';

					$stmt->execute();
					$stmt->bind_result($limitEd);
					$stmt->fetch();

					echo "<strong style='color: #597bb8'>".$this->consultesBD_Web["buscarParamOrder"]."</strong><br>
					<span style='color: #597bb8'>".$tipus."</span><br>
					<span style='color: #597bb8'>".$orderBy."</span><br>
					".$limitEd."<br><hr>";

					$tipus='dies-inscriu-cursos';
					$orderBy='VALOR';

					$stmt->execute();
					$stmt->bind_result($valor);
					$diesOberts=0;
					while ( $stmt->fetch() ) {
						$valors = explode('|',$valor);
						if (count($valors) != 2)
						throw new Exception('',4346);
						else if (intval($valors[0])>0 && $valors[0]== $hores) //si el valor és un numero i les hores son iguals al curs
						$diesOberts = $valors[1];
						else if (intval($valors[0])<=0 && $valors[0]== $curs) //si el valor no és un numero i el codi és igual al curs
						$diesOberts = $valors[1];
					}

					// echo "<strong style='color: #597bb8'>".$this->consultesBD_Web["buscarParamOrder"]."</strong><br>
					// <span style='color: #597bb8'>".$tipus."</span><br>
					// <span style='color: #597bb8'>".$orderBy."</span><br>
					// ".$valor."<br>
					// ".$diesOberts."<br><hr>";
				}
				else {
					throw new Exception('', 4345);
				}
				$conWeb->closeStmt();

				if ($diesOberts==0)
					throw new Exception('',4347);

				$cnt = 0; $dates = [];
				if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarProxEdObertInsc"] ) ) {
					$stmt->bind_param("sds", $curs, $diesOberts, $limitEd);
					$stmt->execute();
					$stmt->bind_result($anyEd, $mesEd);
					while ( $stmt->fetch() ) {
						//Consultar les dates d'inici i de fi
						if ( $stmt2=$conWeb2->prepare( $this->consultesBD_Web["buscarCursSegEd"] ) ) {
							$stmt2->bind_param("dss", $anyEd, $mesEd, $curs);
							$stmt2->execute();
							$stmt2->bind_result($nomCursEd, $dataIEd, $dataFEd, $horesEd, $idPreuEd);
							$stmt2->fetch();

							$dates[$cnt] = $this->__mostrarDatesIniciFi( $dataIEd, $dataFEd );
							$cnt++;

							echo "<strong style='color: #597bb8'>".$this->consultesBD_Web["buscarProxEdObertInsc"]."</strong><br>
							<span style='color: #597bb8'>".$curs."</span><br>
							<span style='color: #597bb8'>".$diesOberts."</span><br>
							<span style='color: #597bb8'>".$limitEd."</span><br>
							".$anyEd."<br>".$mesEd."<br><hr>";

							echo "<strong style='color: #597bb8'>".$this->consultesBD_Web["buscarCursSegEd"]."</strong><br>
							<span style='color: #597bb8'>".$anyEd."</span><br>
							<span style='color: #597bb8'>".$mesEd."</span><br>
							<span style='color: #597bb8'>".$curs."</span><br>
							".$nomCursEd."<br>".$dataIEd."<br>".$dataFEd."<br>".$horesEd."<br>".$idPreuEd."<br><hr>";
						}
						else {
							throw new Exception('', 4349);
						}
						$conWeb2->closeStmt();
					}
				}
				else {
					throw new Exception('', 4348);
				}
				$conWeb->closeStmt();

				/* ############## Avís MSG als alumnes ############## */
				require_once "MailSMTPComvive.php";
				echo "<strong style='color: #e91e63'>MSG dels alumnes</strong><br>";

				// Consultar alumnes del curs actual
				if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarInscrCursByCursInsc"] ) ) {
					$stmt->bind_param("dsss", $any, $mes, $curs, $inscCurs);
					$inscCurs = '0';
					$stmt->execute();
					$stmt->bind_result($idInsc, $nom, $cognoms, $dni, $correu, $telefon,
					$certificat, $aPagar, $pagament, $factRel, $inscrit, $obs);
					while ( $stmt->fetch() ) {
						echo "<strong style='color: #597bb8'>".$this->consultesBD_Web["buscarInscrCursByCursInsc"]."</strong><br>
						<span style='color: #597bb8'>".$any."</span><br>
						<span style='color: #597bb8'>".$mes."</span><br>
						<span style='color: #597bb8'>".$curs."</span><br>
						<span style='color: #597bb8'>".$inscCurs."</span><br>
						".$idInsc."<br>".$nom."<br>".$cognoms."<br>".$dni."<br>".$correu."<br>
						".$telefon."<br>".$certificat."<br>".$aPagar."<br>".$pagament."<br>".$factRel."<br>
						".$inscrit."<br>".$obs."<br><hr>";

						/* ############## Donar de baixa als alumnes a les inscripcions ############## */

						$dateNow = new DateTime("now");
						$dataBaixa = $dateNow->format('Y-m-d H:i:s');

						if ( $stmt2=$conWeb2->prepare( $this->consultesBD_Web["updInscBaixaCurs"] ) ) {
							$stmt2->bind_param("sssd", $dataBaixa, $quiBaixa, $motiuBaixa, $idInsc);
							$quiBaixa = $this->usuari->getNom()->get()." ".$this->usuari->getCognom()->get();
							$motiuBaixa = 'CURS ANUL·LAT';
							$stmt2->execute();
							echo "<strong style='color: #597bb8'>".$this->consultesBD_Web["updInscBaixaCurs"]."</strong><br>
							<span style='color: #597bb8'>".$dataBaixa."</span><br>
							<span style='color: #597bb8'>".$quiBaixa."</span><br>
							<span style='color: #597bb8'>".$motiuBaixa."</span><br>
							<span style='color: #597bb8'>".$idInsc."</span><br><hr>";
						}
						else
							throw new Exception('',4353);
						$conWeb2->closeStmt();

						// Avís MSG als alumnes */
						$nomFromHead = $nameUserSecre;
						$correuFromHead = $userSecre;

						$subject = "Anul·lació del curs ".$nomCurs." (".$mes."/".$any.")";
						$subjectCopiaResguard = "Anul·lació del curs ".$nomCurs." (".$mes."/".$any.") - ".$dni;

						$metodePagament="";

						if ( $stmt2=$conWeb2->prepare( $this->consultesBD_Web["buscarInfoFacturaByFact"] ) ) {
							$stmt2->bind_param("d", $factRel);
							$stmt2->execute();
							$stmt2->bind_result($idFact, $factRelFact, $anyFact, $ordreFact,
							$numFact, $dataFact, $dataPagFact, $generadaFact, $raoFact, $cifFact,
							$adrecaFact, $cpFact, $pobleFact, $c1Fact, $c2Fact, $importFact,
							$entitatFat, $formaPagamentFact, $cursFact, $horesFact, $obsFact, $efact);
							$stmt2->fetch();
						}
						else {
							throw new Exception('', 4354);
						}
						$conWeb2->closeStmt();

						$objMes = new Date("01-".$mes."-2021");
						$mesEdicioEscrit = $objMes->getNomMesArticle();

						if ( $pagament > 0 ) {
							$metodePagament = " (";
							$textFormaPag = new Text($formaPagamentFact);
							$textFormaPag->setMaj();
							if ( $textFormaPag->get() == 'TPV' ) {
								$metodePagament .= "targeta de dèbit o crèdit";
							}
							else {
								$metodePagament .= "transferència bancària";
							}
							$metodePagament .= ")";
						}

						$dataIPronom = $objDataI->getPronomEl()."<strong>".$objDataI->getDataLlarga()."</strong>";

						require_once 'Template.php';
					   $templates = new Template();
					   $msg = $templates->getTemplate_Secretaria_AnularCurs_Alumne($dates, $pagament);

						$names_template = array("[NOM_ALUMNE]", "[COG_ALUMNE]", "[DNI_ALUMNE]",
							"[CORREU_ALUMNE]", "[TEL_ALUMNE]", "[PAY_ALUMNE]", "[METHOD_PAY]", "[DATAI]",
						 	"[TITOL]", "[EDICIO_MES]", "[MES]", "[ANY]");
						$names_function   = array($nom, $cognoms, $dni, $correu, $telefon,
							$pagament, $metodePagament, $dataIPronom, $nomCurs,
							$mesEdicioEscrit, $mes, $any);
						$message = str_replace($names_template, $names_function, $msg);

						$nomTo = $nameUserSecre;
						$correuTo = "resguard.secretaria@prisma.cat";
						$correuTo = "meriem.prisma.cat@gmail.com";

						$nomReplyHead = $nameUserSecre;
						$correuReplyHead = $userSecre;

						$mailSecre = new MailSMTPComvive($userSecre, $passSecre, $nomFromHead, $correuFromHead,
												 $nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
												 $subjectCopiaResguard, $message, $qui, $depart);

						$nomTo = $nom." ".$cognoms;
						$correuTo = $correu;
						$correuTo = "meriem.prisma.cat@gmail.com";
						$nomReplyHead = $nameUserSecre;
						$correuReplyHead = $userSecre;

						$mailAlumne = new MailSMTPComvive($userSecre, $passSecre, $nomFromHead, $correuFromHead,
												 $nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
												 $subject, $message, $qui, $depart);

						$mostrar .= "<p>S'ha enviat un missatge d'avís a l'alumne <strong>".$nomTo."</strong> sobre l'anul·lació del curs <strong>".$nomCurs."</strong>.</p>";
					}
				}
