 	/**
 	* @brief Mostra l'estructura de la pàgina '/intranet/cursos/previ-inici-cursos/avisar-inici-cursos-pendents/'.
 	* @return Mostra l'estructura de la pàgina '/intranet/cursos/previ-inici-cursos/avisar-inici-cursos-pendents/'.
 	*/
   private function __mostrarPage_Cursos_PreviInici_MostrarAvisCursosPendents() {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();
		$conWeb2 = new ConnexioWeb();
		$conWeb2->connectarBD();

		$cursos = [];
		$alumnes = [];
		$cntCursos = 0;

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["cnsCursosPendents"] ) ) {
			$stmt->bind_param("s",  $estat);
			$estat = 'P';
			$stmt->execute();
			$stmt->store_result();
			if ( $stmt->num_rows() > 0 ) {
				//Si existeixen cursos pendents:
				$stmt->bind_result($codiCurs, $nomCurs, $any, $mes, $datai);

				while ( $stmt->fetch() ) {
					$cursos[$cntCursos]["codi"] = $codiCurs;
					$cursos[$cntCursos]["nom"] = $nomCurs;
					$cursos[$cntCursos]["any"] = $any;
					$cursos[$cntCursos]["mes"] = $mes;
					$cursos[$cntCursos]["datai"] = $datai;
					//Busquem els alumnes amb cursos pendents
					if ( $stmt2=$conWeb2->prepare( $this->consultesBD_Web["cnsAlumnesAmbCursosPendents"] ) ) {
						$stmt2->bind_param("dss",  $any, $mes, $codiCurs);
						$stmt2->execute();
						$stmt2->store_result();
						if ( $stmt2->num_rows() > 0 ) {
							$cursos[$cntCursos]["nAlumnes"] = $stmt2->num_rows();
							$cnt = 0;
							//Si existeixen alumnes amb cursos pendents:
							$stmt2->bind_result($id, $nom, $cognoms, $correu, $dataInsc, $obs, $aPagar, $pagament, $pendentInici, $entitat, $tipusInsc);
							while ( $stmt2->fetch() ) {
								$alumnes[$codiCurs][$cnt] = [$id, $nom, $cognoms, $correu, $dataInsc, $obs, $aPagar, $pagament, $pendentInici, $entitat, $tipusInsc];
								$cnt++;
							}
						}
						else {
							//No existeixen cursos pendents:
						}
						$conWeb2->closeStmt();
					}
					else {
						throw new Exception('', 4371);
					}

					$cntCursos++;
				}
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('', 4370);
		}

		$conWeb2->desconectarBD();
		$conWeb->desconectarBD();

		$apartats = '';

		$nCursos = count( $cursos );
		if ( $nCursos > 0 ) {

			for ( $i = 0; $i < $nCursos; $i++ ) {
				$codiCursActual = $cursos[$i]["codi"];
				$nomCursActual = $cursos[$i]["nom"];
				$anyCurs = $cursos[$i]["any"];
				$mesCurs = $cursos[$i]["mes"];
				$nAlumnes = count( $alumnes[$codiCursActual] );
				$nAlumnes = $cursos[$i]["nAlumnes"];

				if ( $nAlumnes > 0 ) {
					$tableAlumnes = "<table class='table table-striped table-hover table-order text-center'>
						<thead>
							<tr>
								<th style='width: 10%'>NOM</th>
								<th style='width: 10%'>COGNOMS</th>
								<th style='width: 10%'>E-MAIL</th>
								<th style='width: 15%'>DATA INSCRIPCIÓ</th>
								<th style='width: 45%'>OBSERVACIONS</th>
								<th style='width: 10%'>PAGAMENT</th>
								<th style='width: 10%'>AVISAR</th>
							</tr>
						</thead>
					<tbody>";
					for ( $j = 0; $j < $nAlumnes; $j++ ) {
						$id = $alumnes[$codiCursActual][$j][0];
						$nom = $alumnes[$codiCursActual][$j][1];
						$cognoms = $alumnes[$codiCursActual][$j][2];
						$dataInsc = $alumnes[$codiCursActual][$j][4];
						$obs = $alumnes[$codiCursActual][$j][5];
						$aPagar = $alumnes[$codiCursActual][$j][6];
						$pagament = $alumnes[$codiCursActual][$j][7];
						$pendentInici = $alumnes[$codiCursActual][$j][8];
						$entitat = $alumnes[$codiCursActual][$j][9];
						$tipusInsc = $alumnes[$codiCursActual][$j][10];

						$correu = $alumnes[$codiCursActual][$j][3];

						if ( $dataInsc == '' or $dataInsc == null)
							$dataInscFormat = '';
						else {
							$dateInsc = new Date($dataInsc);
							$dataInscFormat = $dateInsc->getDataFomatDDMMYYYY_HHMMSS();
						}
						$csv_file = "observacions-cursos-pendents-".$any."-".$mes."-".$codiCursActual.".txt";
						$path_file = "../fitxers/".$csv_file;
						$obsCSV = '';

						if ( file_exists($path_file) ) {
							if (!$handle = fopen($path_file, "r")) {
								echo "Cannot open file observacions cursos pendents $any $mes $codiCursActual";
								 exit;
							}
							else {
								$content = fread($handle, filesize($path_file));
								$observacionsArr = explode('_||_', $content);
								$cntObsArr = count($observacionsArr)-1; $trobat=0;
								while ( $cntObsArr >= 0 && !$trobat ) {
									$trobat = explode('_###_', $observacionsArr[$cntObsArr])[0] == $id;
									if ( !$trobat ) $cntObsArr--;
								}
								if ( $trobat ) $obsCSV = explode('_###_', $observacionsArr[$cntObsArr])[1];
								else $obsCSV = '';
							}
							fclose($handle);
						}

						$inputObs = "<div class='d-flex flex-row align-items-center'>
							".$this->__mostrarTextarea('', 'OBSERVACIONS', 'hide', 'obs-'.$codiCursActual."-".$id, 'obs', $obsCSV, 'text')."
							<span class='material-icons saveObs' id='saveObs-".$codiCursActual."-".$id."' aria-hidden='true'>save</span>
						</div>";

						if ( $pendentInici == 1 ) {
							$textLabelAvis = 'AVISAT/DA';
							$classLabelAvis = "avisar-alumne lightGray";
						}
						else {
							if ( $entitat == null or $entitat == ''  or $tipusInsc == 'R' ) {
								if ( $aPagar > 0 && $pagament > 0 ) {
									$textLabelAvis = "NO";
									$classLabelAvis = "avisar-alumne lightRed";
								}
								else {
									$textLabelAvis = "SÍ";
									$classLabelAvis = "avisar-alumne lightGreen";
								}
							}
							else {
								$textLabelAvis = "NO";
								$classLabelAvis = "avisar-alumne lightRed";
							}
						}

						$labelAvis = "<label id='avis-".$id."' class='label d-flex justify-content-center
						align-items-center position-relative font-weight-bold px-2 py-2 ".$classLabelAvis."'>
						".$textLabelAvis."
						</label>";

						$classPag = "";
						if ( $aPagar - $pagament > 0 && ( $entitat == null || $entitat == '' ) ) {
							$classPag = 'text-danger font-weight-bold';
						}

						$tableAlumnes .= "<tr>
							<td>".$nom."</td>
							<td>".$cognoms."</td>
							<td>".$correu."</td>
							<td>".$dataInscFormat."</td>
							<td>".$obs.$inputObs."</td>
							<td class='".$classPag."'>".$pagament."</td>
							<td>".$labelAvis."</td>
						</tr>";
					}
					$tableAlumnes .= "</tbody></table>";
				}
				else {
					$tableAlumnes = "<p class='text-center'>No existeix cap alumne per avisar.</p>";
				}

				$apartats .= "<div class='d-flex flex-column my-3'>
					<p class='font-weight-bold titolCurs text-center'>".$codiCursActual." - ".$nomCursActual."</p>
					<div id='cntCurs-".$codiCursActual."-".$anyCurs."-".$mesCurs."' class='d-flex flex-column align-items-center justify-content-center w-100'>
						".$tableAlumnes."
						<p class='font-weight-bold'>Nombre d'alumnes: ".$nAlumnes."</p>
						<div class='d-flex justify-content-center align-items-center'>
							<button id='sendAvis-".$codiCursActual."-".$anyCurs."-".$mesCurs."' class='sendAvis boto-blau px-4 d-flex'>ENVIAR CORREUS</button>
						</div>
					</div>
				</div>";
			}
		}
		else {
			$apartats = "<p class='text-center'>No existeix cap curs pendent.</p>";
		}

		$mostrar = "<div id='cursos' class='card card-blau'>
			<div class='d-flex flex-column justify-content-center align-items-center
					w-100 text-center border-bottom card-header'>
					<p class='title font-weight-bold text-center py-3 mb-0 align-items-center
					justify-content-center d-flex'>CURSOS PENDENTS</p>
				</div>
			<div class='card-body px-0'>
				".$apartats."
			</div>
		</div>";

		return $mostrar;
  }

  /**
  * @brief Substitueix $observacio per les observacions de les inscripcion on la id de la inscripció és $idInsc
  * @return Substitueix $observacio per les observacions de les inscripcion on la id de la inscripció és $idInsc
  */
  public function saveObservacionsInscripcio( $idInsc, $observacio ) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarInfoMostraInfo"] ) ) {
			$stmt->bind_param("d", $idInsc);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($any, $mes, $curs, $aula, $nom, $cognoms, $dni, $correu,
				$telefon, $adreca, $cp, $poblacio, $perfil, $titulacio, $datainsc,
				$inscrit, $tipusInsc, $inscao, $inscmail, $certificat, $obscertificat, $generat, $obs,
				$comentaris, $databaixa, $motiubaixa, $quibaixa, $apagar, $pag, $datapag,
				$idpag, $pagObs, $comHaPagat, $entitat, $fraccio, $comFraccio, $factura, $datarec, $reclamat, $usuari);
				$stmt->fetch();
			}
			else {
				throw new Exception('',4376);
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4372);
		}

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarCursSegEd"] ) ) {
			$stmt->bind_param("dss", $any, $mes, $curs);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($nomCurs, $datai, $dataf, $hores, $idPreu);
				$stmt->fetch();
				$conWeb->closeStmt();
			}
			else {
				throw new Exception('',4377);
			}
		}
		else {
			throw new Exception('',4373);
		}

		// if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["saveObsInsc"] ) ) {
		// 	$stmt->bind_param("sd", $observacio, $idInsc);
		// 	$stmt->execute();
		// 	$conWeb->closeStmt();
		// }
		// else {
		// 	throw new Exception('', 4374);
		// }

		/* Generar fitxer observacions */

		$csvFitxer = $idInsc."_###_".$observacio."_||_";

		$csv_file = "observacions-cursos-pendents-".$any."-".$mes."-".$curs.".txt";
		$path_file = "../../fitxers/".$csv_file;

		//Si el fitxer no existeix, generem el fitxer
		if (!$handle = fopen($path_file, "a+")) {
		    echo "Cannot open file observacions cursos pendents (generar)";
		    exit;
		}

		//Omplim el fitxer
		if (fwrite($handle, $csvFitxer) === FALSE) {
		    echo "Cannot write to file";
		    exit;
		}
		fclose($handle);

		/* Fi de Generar fitxer observacions */

		$conWeb->desconectarBD();

		$authSecre = $this->getAuthSMTP_Secretaria();
		$userSecre = $authSecre[0];
		$passSecre = $authSecre[1];
		$nameUserSecre = $authSecre[2];

		$objDateOpen = new Date( $this->getDataObertura( $datai ) );
		$dataObertura = $objDateOpen->getDataFomatDDMMYYYY_HHMMSS();
		$nameDateOpen = $objDateOpen->getDiaSetmana();
		$textDateOpen = new Text($nameDateOpen);
		$textDateOpen->setMin();
		$nameDateOpen = $textDateOpen->get();

		$textPagament = "";
		if ( $apagar - $pag > 0 )
			$textPagament = "<p>Pots esperar a la confirmació per fer l'ingrés.</p>";

		$subject = "Resposta enregistrada | Curs pendent de començar (".$nomCurs.")";

		$message = "<p>Benvolgut/da ".$nom.",</p>
			<p>T'informem que hem rebut la teva resposta conforme estàs interessat/da en fer el curs <strong style='color: #496baa'>".$nomCurs."</strong>.</p>
			<p>Entre avui i ".$nameDateOpen." ens posarem en contacte amb tu a través del correu electrònic
			<a
			href='mailto:".$correu."' style='font-weight: bold; text-decoration: none;
			color: ".$this->colors_destacats["msgDestacatCorreu1"]."'>".$correu."</strong></a> per confirmar-te si el curs tira endavant o no.</p>
			".$textPagament."
			<p>Salutacions ben cordials,</p>";

		require_once 'MailSMTPComvive.php';

		$qui = $this->usuari->getNom()->get()." ".$this->usuari->getCognom()->get();
		$depart = $this->usuari->getDepart()->get();

		$nomFromHead = $nameUserSecre;
		$correuFromHead = $userSecre;

		$nomTo = $nameUserSecre;
		$correuTo = "resguard.secretaria@prisma.cat";
		$nomReplyHead = $nom." ".$cognoms;
		$correuReplyHead = $correu;

		$mailSecre = new MailSMTPComvive($userSecre, $passSecre, $nomFromHead, $correuFromHead,
							$nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
							$subject, $message, $qui, $depart);

		$nomTo = $nom." ".$cognoms;
		$correuTo = $correu;
		$nomReplyHead = $nameUserSecre;
		$correuReplyHead = $userSecre;

		$mailAlumne = new MailSMTPComvive($userSecre, $passSecre, $nomFromHead, $correuFromHead,
							$nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
							$subject, $message, $qui, $depart);

		$mostrar = "<p>S'ha enviat un missatge d'avís a l'alumne <strong>".$nom." ".$cognoms."</strong>.</p>";
		return $mostrar;
  }

  /**
  * @brief S'envia un misatge d'avís que el curs està pendent a la persona que té com a id d'inscripció $id
  * @return S'envia un misatge d'avís informant que el curs està pendent a la persona que té com a id d'inscripció $id
