				$inscrit, $tipusInsc, $inscao, $inscmail, $certificat, $obscertificat, $generat, $obs,
				$comentaris, $databaixa, $motiubaixa, $quibaixa, $apagar, $pag, $datapag,
				$idpag, $pagObs, $comHaPagat, $entitat, $fraccio, $comFraccio, $factura, $datarec, $reclamat, $usuari);
