			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4378);
		}

		// Cal obtenir la data d'inici $datai, nomCurs del curs de la inscripció $idInsc
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarCursSegEd"] ) ) {
			$stmt->bind_param("dss", $any, $mes, $curs);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
