	public function mostrarTable_Alumnes_CorreuDiferentBDCampus($any, $mes, $orderBy, $asc) {
		if ($orderBy != 'dni' && $orderBy!='nom' && $orderBy!='cog')
			$orderBy = 'dni';
		if ($asc!=1 and $asc!=0)
			$asc = 1;

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();
		require_once 'ConnexioMoodle.php';
		$connexioMdlUser = new ConnexioMoodle();
		$connexioMdlUser->connectarBD();
		$apartats = '';

		$i=0;

		/* Buscar tots els alumnes matriculats en l'any $any i del mes $mes.*/
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["cnsCursosAlumnesMatrNoEnvCorreuConf"] ) ) {
			$stmt->bind_param("ds", $any, $mes);
			$stmt->execute();
			$stmt->store_result();
			if ( $stmt->num_rows() > 0 ) {
				$i = 0;
				$stmt->bind_result($id, $dni, $nom, $cognoms, $email_bd, $usuari);
				while ( $stmt->fetch() ) {
					if ( $stmt2=$connexioMdlUser->prepare( $this->consultesBD_Moodle["buscarEmailUsuari"] ) ) {
						$stmt2->bind_param("d",  $usuari);
						$stmt2->execute();
						$stmt2->store_result();
						if ( $stmt2->num_rows() == 0 )
							$email_mdl = '';

						$stmt2->bind_result($email_mdl);
						$stmt2->fetch();
						$connexioMdlUser->closeStmt();

						if ( $email_mdl != '' && $email_mdl != $email_bd ) {
							$resultats[$i][0] = $dni;
							$resultats[$i][1] = $nom;
							$resultats[$i][2] = $cognoms;
							$resultats[$i][3] = $email_bd;
							$resultats[$i][4] = $email_mdl;
							$resultats[$i][5] = $usuari;
							$resultats[$i][6] = $id;
							$i++;
						}
					}
					else {
						throw new Exception('', 4449);
					}

				}
			}
			else {
				$resultats = [];
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('', 4448);
		}

		$connexioMdlUser->desconectarBD();
		$conWeb->desconectarBD();

		if ( count($resultats) > 0 ) {
			function cmpDni($a, $b) {
			    if ($a[0] == $b[0]) {
						 return 0;
			    }
			    return ($a[0] < $b[0]) ? -1 : 1;
			}
			function cmpNom($a, $b) {
			    if ($a[1] == $b[1]) {
					 if ($a[2] == $b[2]) {
						 return 0;
				   }
				   return ($a[2] < $b[2]) ? -1 : 1;
			    }
			    return ($a[1] < $b[1]) ? -1 : 1;
			}
			function cmpCognom($a, $b) {
			    if ($a[2] == $b[2]) {
					 if ($a[1] == $b[1]) {
						 return 0;
				   }
				   return ($a[1] < $b[1]) ? -1 : 1;
			    }
			    return ($a[2] < $b[2]) ? -1 : 1;
			}

			if ($orderBy == 'dni') usort($resultats, "cmpDni");
			else if ($orderBy == 'nom') usort($resultats, "cmpNom");
			else if ($orderBy == 'cog') usort($resultats, "cmpCognom");

			$classDNI = '';
			$classNom = '';
			$classCog = '';

			if ($asc == 1) { //s'ordena ascendentment
				$inici = 0;
				$fi = count($resultats);
				$i = $inici;
				$condicio = $i < $fi;

				if ($orderBy == 'dni') $classDNI = ' asc';
				else if ($orderBy == 'nom') $classNom = ' asc';
				else if ($orderBy == 'cog') $classCog = ' asc';
			}
			else { //s'ordena dsscendentment
				$inici = count($resultats);
				$fi = 0;
				$i = $inici-1;
				$condicio = $i >= $fi;

				if ($orderBy == 'dni') $classDNI = ' desc';
				else if ($orderBy == 'nom') $classNom = ' desc';
				else if ($orderBy == 'cog') $classCog = ' desc';
			}

			$table = "<table class='table table-striped table-hover table-order text-center'>
			<thead>
				<tr>
					<th id='th-dni' class='sorting".$classDNI."'>DNI</th>
					<th id='th-nom' class='sorting".$classNom."'>NOM</th>
					<th id='th-cog' class='sorting".$classCog."'>COGNOMS</th>
					<th>CORREU BD</th>
	            <th>CORREU <em>MOODLE</em></th>
					<th>SELECCIONAR</th>
				</tr>
			</thead>
			<tbody>";

			while ( $condicio ) {
				$dni = $resultats[$i][0];
				$nom = $resultats[$i][1];
				$cognoms = $resultats[$i][2];
				$email_bd = $resultats[$i][3];
				$email_mdl = $resultats[$i][4];
				$usuari = $resultats[$i][5];
				$id = $resultats[$i][6];

				$labelConfirmacio = $this->obtenirLabel('enivarMsg-'.$id, 'avisar-alumne lightGreen pointer', 'ENVIAR');

				$table .= "<tr>
					<td>".$dni."</td>
					<td>".$nom."</td>
					<td>".$cognoms."</td>
					<td>".$email_bd."</td>
					<td>".$email_mdl."</td>
					<td>".$labelConfirmacio."</td>
				</tr>";

				if ( $asc == 1 ) {
					$i++;
					$condicio = $i < $fi;
				}
				else {
					$i--;
					$condicio = $i >= $fi;
				}
			}

			$table .= "</tbody></table>";

			$apartats .= $table."
			<div class='d-flex flex-column justify-content-center align-items-center my-2'>
				<button id='enviarCorreusAlumnesBDMdlDiff' class='sendAvis boto-blau mt-2 px-4 d-flex'>Enviar correus</button>
			</div>";
		}
		else {
			$table = "<p class='text-center'>No hi ha cap alumne amb el correu de la inscripció diferent que el del seu perfil del campus virtual.</p>";
		}

		$mostrar = "<div class='d-flex flex-column justify-content-center align-items-center
				w-100 text-center border-bottom card-header'>
				<p class='title font-weight-bold text-center py-3 mb-0 align-items-center
				justify-content-center d-flex'>Alumnes amb correus diferents en el Campus i a la BD</p>
			</div>
			<div class='card-body px-0'>
			<p>Resultats de la cerca del <strong> ".$mes."/".$any."</strong>:</p>
			".$apartats."
		</div>";

		return $mostrar;
	}

	public function sendMsgAvisCorreuDiferentBDCampus( $idInsc ) {
		$mostrar = "";

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		// Cal obtenir el nom, cognoms, any, mes, curs, correu
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarInfoMostraInfo"] ) ) {
			$stmt->bind_param("d", $idInsc);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($any, $mes, $curs, $aula, $nom, $cognoms, $dni, $email_bd,
				$telefon, $adreca, $cp, $poblacio, $perfil, $titulacio, $datainsc,
				$inscrit, $tipusInsc, $inscao, $inscmail, $certificat, $obscertificat, $generat, $obs,
				$comentaris, $databaixa, $motiubaixa, $quibaixa, $apagar, $pag, $datapag,
				$idpag, $pagObs, $comHaPagat, $entitat, $fraccio, $comFraccio, $factura, $datarec, $reclamat, $usuari);
				$stmt->fetch();
			}
			else {
				throw new Exception('',4451);
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4450);
		}


		$connexioMdlUser = new ConnexioMoodle();
		$connexioMdlUser->connectarBD();
		if ( $stmt2=$connexioMdlUser->prepare( $this->consultesBD_Moodle["buscarEmailUsuari"] ) ) {
			$stmt2->bind_param("d",  $usuari);
			$stmt2->execute();
			$stmt2->store_result();
			if ( $stmt2->num_rows() == 0 )
				$email_mdl = '';

			$stmt2->bind_result($email_mdl);
			$stmt2->fetch();
			$connexioMdlUser->closeStmt();
		}
		else {
			throw new Exception('', 4452);
		}
		if ( $stmt2=$connexioMdlUser->prepare( $this->consultesBD_Moodle["buscarIdUsuari"] ) ) {
			$stmt2->bind_param("d",  $usuari);
			$stmt2->execute();
			$stmt2->store_result();
			if ( $stmt2->num_rows() == 0 )
				$idUserMdl = '';
			$stmt2->bind_result($idUserMdl);
			$stmt2->fetch();
			$connexioMdlUser->closeStmt();
		}
		else {
			throw new Exception('', 4453);
		}
		$connexioMdlUser->desconectarBD();

		$subject = "E-mail de contacte en el Campus Virtual PrisMa";
		$subjectCopiaResguard = "E-mail de contacte en el Campus Virtual PrisMa ".date('d')."-".date('m')."-".date('Y')." ".date('H').":".date('i');

		$message = "<p align=justify>Hola, ".$nom.",</p>

		<p align=justify>T'informem que el correu associat al teu perfil del Campus Virtual de PrisMa és diferent del correu que ens vas facilitar en el moment d'enviar l'última sol·licitud d'inscripció.</p>

		<p align=justify>Per tant, els missatges del Campus t'arribaran a
		<a href='mailto:".$email_mdl."' style='font-weight: bold; text-decoration: none; color: ".$this->colors_destacats["msgDestacatCorreu1"]."'>".$email_mdl."</a>
		i els de Secretaria a
		<a href='mailto:".$email_bd."' style='font-weight: bold; text-decoration: none; color: ".$this->colors_destacats["msgDestacatCorreu1"]."'>".$email_bd."</a>.</p>

		<p align=justify>Si vols rebre tota la informació en un mateix correu electrònic, escriu-nos a <a href='mailto:secretaria@prisma.cat' style='font-weight: bold; text-decoration: none; color: ".$this->colors_destacats["msgDestacatCorreu1"]."'>secretaria@prisma.cat</a> especificant quin dels dos vols utilitzar.</p>

		<p align=justify>Salutacions ben cordials,</p>";

		//Enviem el msg a resguard.secretaria@prisma.cat i a l'allumne
		// cal buscar usuari i contrassenya del correu smtp
		$authSecre = $this->getAuthSMTP_Secretaria();
		$userSecre = $authSecre[0];
		$passSecre = $authSecre[1];
		$nameUserSecre = $authSecre[2];

		require_once 'MailSMTPComvive.php';

		$qui = $this->usuari->getNom()->get()." ".$this->usuari->getCognom()->get();
		$depart = $this->usuari->getDepart()->get();

		$nomFromHead = $nameUserSecre;
		$correuFromHead = $userSecre;

		$nomTo = $nameUserSecre;
		$correuTo = "resguard.secretaria@prisma.cat";
		$correuTo = "meriem.prisma.cat@gmail.com";
		$nomReplyHead = $nom." ".$cognoms;
		$correuReplyHead = $email_bd;

		$mailSecre = new MailSMTPComvive($userSecre, $passSecre, $nomFromHead, $correuFromHead,
							$nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
							$subjectCopiaResguard, $message, $qui, $depart);

		$nomTo = $nom." ".$cognoms;
		$correuTo = $email_bd;
		$correuTo = "meriem.prisma.cat@gmail.com";
		$nomReplyHead = $nameUserSecre;
		$correuReplyHead = $userSecre;

		$mailAlumne = new MailSMTPComvive($userSecre, $passSecre, $nomFromHead, $correuFromHead,
							$nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
							$subject, $message, $qui, $depart);

		$mostrar .= "<p>S'ha enviat un missatge d'avís a l'alumne <strong>".$nom." ".$cognoms."</strong>.</p>";

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["updCorreuInfoCorreuConf"] ) ) {
			$stmt->bind_param("dd", $avis, $idInsc);
			$avis = 1;
			$stmt->execute();
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('', 4454);
		}

		$conWeb->desconectarBD();

		return $mostrar;
	}

