					}
					else {
						throw new Exception('', xxx);
					}
					if ( $stmt2=$connexioMdlUser->prepare( $this->consultesBD_Moodle["cnsContextIdUserMdlUser"] ) ) {
						$stmt2->bind_param("d", $picture);
