		}
		else {
			throw new Exception('', xxx);
		}

		$connexioMdlUser->desconectarBD();
		$conWeb->desconectarBD();

		if ( count($resultats) > 0 ) {
			function cmpDni($a, $b) {
			    if ($a[0] == $b[0]) {
						 return 0;
			    }
			    return ($a[0] < $b[0]) ? -1 : 1;
			}
			function cmpNom($a, $b) {
			    if ($a[1] == $b[1]) {
					 if ($a[2] == $b[2]) {
						 return 0;
				   }
				   return ($a[2] < $b[2]) ? -1 : 1;
			    }
			    return ($a[1] < $b[1]) ? -1 : 1;
			}
			function cmpCognom($a, $b) {
			    if ($a[2] == $b[2]) {
					 if ($a[1] == $b[1]) {
						 return 0;
				   }
				   return ($a[1] < $b[1]) ? -1 : 1;
			    }
			    return ($a[2] < $b[2]) ? -1 : 1;
			}
			function classCorreu($a, $b) {
			    if ($a[3] == $b[3]) {
					return 0;
			    }
			    return ($a[3] < $b[3]) ? -1 : 1;
			}
			function classCurs($a, $b) {
			    if ($a[6] == $b[6]) {
					return 0;
			    }
			    return ($a[6] < $b[6]) ? -1 : 1;
			}

