							$classPag = 'text-danger font-weight-bold';
						}

						$tableAlumnes .= "<tr>
							<td>".$nom."</td>
							<td>".$cognoms."</td>
							<td>".$correu."</td>
							<td>".$dataInscFormat."</td>
							<td>".$labelAvis."</td>
						</tr>";
					}

					//Buscar el tutor i afegir una fila només pel tutor

					$conWeb = new ConnexioWeb();
					$conWeb->connectarBD();

					// Consultar dades del tutor del curs actual
					if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarDadesPersonalByCurs"] ) ) {
						$stmt->bind_param("dssssd", $anyCurs, $mesCurs, $codiCursActual, $aula, $perfil, $estatPersonal);
						$aula = 'A';
						$perfil = 'tutor';
						$estatPersonal = 1;
						$stmt->execute();
						$stmt->bind_result($dniTutor, $nomTutor, $cogTutor, $correuTutorPrisma, $correuTutorPers);
						while ( $stmt->fetch() ) {
							// echo "".$dniTutor."<br>".$nomTutor."<br>".$cogTutor."<br>".$correuTutorPrisma."<br>".$correuTutorPers."<br><hr>";

							$labelAvis = "<label id='avistutor-".$dniTutor."-".$anyCurs."-".$mesCurs."-".$codiCursActual."' class='label d-flex justify-content-center
							align-items-center position-relative font-weight-bold px-2 py-2 avisar-tutor lightGreen'>SÍ</label>";

							$tableAlumnes .= "<tr class='tutor'>
								<td>".$nomTutor."</td>
								<td>".$cogTutor."</td>
								<td>".$correuTutorPrisma."</td>
								<td>-</td>
								<td>".$labelAvis."</td>
							</tr>";
						}
					}
					else {
						throw new Exception('', 4630);
					}
					$conWeb->closeStmt();
					$conWeb->desconectarBD();

					$tableAlumnes .= "</tbody></table>";
				}
				else {
					$tableAlumnes = "<p class='text-center'>No existeix cap alumne per avisar.</p>";
				}

				$apartats .= "<div class='d-flex flex-column my-3'>
					<p class='font-weight-bold titolCurs text-center'>".$codiCursActual." - ".$nomCursActual."</p>
					<div id='cntCurs-".$codiCursActual."-".$anyCurs."-".$mesCurs."' class='d-flex flex-column align-items-center justify-content-center w-100'>
						".$tableAlumnes."
