  /**
  * @brief S'envia un misatge d'avís que el curs està pendent al tutor que té com a dni $dniTutor
  * @return S'envia un misatge d'avís informant que el curs està pendent al tutor que té com a dni $dniTutor
  */
	public function sendMsgTutorAvisCursosPendentsTots( $dniTutor, $any, $mes, $curs, $dataMaxim, $hourDataMaxim ) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		// Cal obtenir nomTutor cogTutor correuTutorPrisma del tutor
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarPersonal"] ) ) {
			$stmt->bind_param("s", $dniTutor);
			$stmt->execute();
			$stmt->bind_result($nomTutor, $cogTutor, $correuTutorPrisma, $correuTutorPers);
			$stmt->fetch();
		}
		else {
			throw new Exception('', 4633);
		}
		$conWeb->closeStmt();

		// Cal obtenir la data d'inici $datai, nomCurs del curs de la inscripció $idInsc
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarCursSegEd"] ) ) {
			$stmt->bind_param("dss", $any, $mes, $curs);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($nomCurs, $datai, $dataf, $hores, $idPreu);
				$stmt->fetch();
				$conWeb->closeStmt();
			}
			else {
				throw new Exception('',4631);
			}
		}
		else {
			throw new Exception('',4632);
		}

		$objDateOpen = new Date( $this->getDataObertura( $datai ) );
		$dataObertura = $objDateOpen->getDataFomatDDMMYYYY_HHMMSS();
		$nameDateOpen = $objDateOpen->getDiaSetmana();
		$textDateOpen = new Text($nameDateOpen);
		$textDateOpen->setMin();
		$nameDateOpen = $textDateOpen->get();

		$objDataI = new Date($datai);
		$dataLlargaInici = $objDataI->getDataLlarga();
		$nameDateI = $objDataI->getDiaSetmana();


		$diaMaxim = '';
		//DiaMaxim = si la data d'inici es un dilluns, es posarà el mateix dilluns entre les 8 i les 9. Altrament, el dia anterior a les 18h
		//el dia XXX a les XXX
		if ( $nameDateI == "dilluns" ) {
			$objDataMaxim = new Date($datai);
			$horesDataMaxim = "9h";
		}
		else {
			$dataMenosDataI = date("d-m-Y",strtotime($datai."- 1 days"));
			$objDataMaxim = new Date($dataMenosDataI);
			$horesDataMaxim = "18h";
		}
		$diaMaxim = $objDataMaxim->getPronomAl()."<strong>".$objDataMaxim->getDataLlarga()."</strong> a les ".$horesDataMaxim;

		$objDataMaxim = new Date($dataMaxim);
		$horesDataMaxim = $hourDataMaxim;
		$diaMaxim = $objDataMaxim->getPronomAl()."<strong>".$objDataMaxim->getDataLlarga()."</strong> a les ".$horesDataMaxim;

		$objMes = new Date("01-".$mes."-2021");
		$nomTextMes = $objMes->getNomMesArticle();

		$subject = "Curs ".$nomCurs." pendent de començar (".$mes."/".$any.")";

		$message = "<p>Hola ".$nomTutor.",</p>
		<p>Avui teníem previst obrir l'apartat general de l'edició ".$nomTextMes."
		del curs <strong style='color: ".$this->colors_destacats["msgDestacatCorreu1"]."'>".$nomCurs."</strong>,
		però estem a l'espera de més inscripcions i que les persones que encara no
		han fet el pagament ens confirmin si realitzaran el curs. A partir de llavors
		valorarem si tira endavant o hem d’anul·lar l’edició.
		<p>Esperem com a màxim fins ".$diaMaxim." per decidir si comencem el curs</p>
		<p>Moltes gràcies per endavant, i estem en contacte.</p>";

		// cal buscar usuari i contrassenya del correu smtp
		$authSecre = $this->getAuthSMTP_Secretaria();
		$userSecre = $authSecre[0];
		$passSecre = $authSecre[1];
		$nameUserSecre = $authSecre[2];

		//Enviem el msg a resguard.secretaria@prisma.cat i a l'allumne

		require_once 'MailSMTPComvive.php';

		$qui = $this->usuari->getNom()->get()." ".$this->usuari->getCognom()->get();
		$depart = $this->usuari->getDepart()->get();

		$nomFromHead = $nameUserSecre;
		$correuFromHead = $userSecre;

		$nomTo = $nameUserSecre;
		$correuTo = "resguard.secretaria@prisma.cat";
		$nomReplyHead = $nomTutor." ".$cogTutor;
		$correuReplyHead = $correuTutorPrisma;
		$correuTo = "meriem.prisma.cat@gmail.com";

		$mailSecre = new MailSMTPComvive($userSecre, $passSecre, $nomFromHead, $correuFromHead,
							$nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
							$subject, $message, $qui, $depart);

		$nomTo = $nomTutor." ".$cogTutor;
		$correuTo = $correuTutorPrisma;
		$nomReplyHead = $nameUserSecre;
		$correuReplyHead = $userSecre;
		$correuTo = "meriem.prisma.cat@gmail.com";

		$mailAlumne = new MailSMTPComvive($userSecre, $passSecre, $nomFromHead, $correuFromHead,
							$nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
							$subject, $message, $qui, $depart);

		$mostrar = "<p>S'ha enviat un missatge d'avís al tutor <strong>".$nomTutor." ".$cogTutor."</strong>.</p>";

