	/**
	* @brief Mostra els cursos que comencen en una edició ordenats
	* @return Mostra els cursos disponibles a l'edició del mes $mes i de l'any $any ordenats per $oderby i en ascendent segons $asc
	*/
	public function mostrarCursos_PreviIniciCursos_AssignarTutors($any, $mes, $orderby, $asc) {
		$mostrar = "mostrarCursos_PreviIniciCursos_AssignarTutors <br />
		".$any." ".$mes." ".$orderby." ".$asc;

		if ($orderby != 'codi' && $orderby!='titol')
			$orderby = 'codi';
		if ($asc!=1 and $asc!=0)
			$asc = 1;

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();
		$conWeb2 = new ConnexioWeb();
		$conWeb2->connectarBD();

		$i=0;

		/* Buscar tots els cursos que estan pendents d'assignar un tutor de l'any $any i del mes $mes.*/
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["cnsCursPendentAssig"] ) ) {
			$stmt->bind_param("dsdd", $any, $mes, $confirmat, $idCuho);
			$confirmat = 0;
			$idCuho = 17;
			$stmt->execute();
			$stmt->store_result();
			if ( $stmt->num_rows() > 0 ) {
				$stmt->bind_result($titolCurs, $idCurs, $codiCurs, $idAula, $aula, $idCuho, $nomTutor, $cogTutor);
				while ( $stmt->fetch() ) {
					$resultats[$i][0] = $titolCurs;
					$resultats[$i][1] = $codiCurs;
					$resultats[$i][2] = $aula;
					$resultats[$i][3] = $idCurs;
					$resultats[$i][4] = $idAula;
					$resultats[$i][5] = $idCuho;
					$resultats[$i][6] = $nomTutor;
					$resultats[$i][7] = $cogTutor;

					$i++;
				}
			}
			else {
				$resultats = [];
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('', 4385);
		}

		$conWeb2->desconectarBD();
		$conWeb->desconectarBD();

		if ( count($resultats) > 0 ) {
			function cmpCodi($a, $b) {
			    if ($a[1] == $b[1]) {
			        return 0;
			    }
			    return ($a[1] < $b[1]) ? -1 : 1;
			}

			function cmpTitol($a, $b) {
			    if ($a[0] == $b[0]) {
			        return 0;
			    }
			    return ($a[0] < $b[0]) ? -1 : 1;
			}

			if ($orderby == 'codi') usort($resultats, "cmpCodi");
			else if ($orderby == 'titol') usort($resultats, "cmpTitol");


			$classCurs = '';
			$classTitol = '';

			if ($asc == 1) { //s'ordena ascendentment
				$inici = 0;
				$fi = count($resultats);
				$i = $inici;
				$condicio = $i < $fi;

				if ($orderby == 'codi') $classCurs = ' asc';
				else if ($orderby == 'titol') $classTitol = ' asc';
			}
			else { //s'ordena dsscendentment
				$inici = count($resultats);
				$fi = 0;
				$i = $inici-1;
				$condicio = $i >= $fi;

				if ($orderby == 'codi') $classCurs = ' desc';
				else if ($orderby == 'titol') $classTitol = ' desc';
			}

			//Mostra usuaris en format d'una taula ordenats per dni;
			$table = "<table class='table table-striped table-hover table-order text-center'>
			<thead>
				<tr>
					<th id='th-titol' class='sorting".$classTitol."'>TÍTOL</th>
					<th id='th-codi' class='sorting".$classCurs."'>CURS</th>
					<th>AULA</th>
					<th>TUTOR/A ASSIGNAT</th>
					<th>ASSIGNAR TUTOR/A</th>
				</tr>
			</thead>
			<tbody>";

			while ( $condicio ) {
				$titolCurs = $resultats[$i][0];
				$codiCurs = $resultats[$i][1];
				$aula = $resultats[$i][2];
				$idCurs = $resultats[$i][3];
				$idAula = $resultats[$i][4];
				$idCuho = $resultats[$i][5];
				$nomTutor = $resultats[$i][6];
				$cogTutor = $resultats[$i][7];

				$botoAfegirTutor = "<div class='d-flex flex-column justify-content-center align-items-center my-2'>
				<button id='add-tutor-".$idCurs."-".$aula."' role='button' class='add-tutor boto-blau px-4 d-flex'>
					Tria
				</button></div>";

				$botoSetTutor = "<div class='d-flex flex-column justify-content-center align-items-center my-2'>
				<button id='set-tutor-".$idCurs."-".$aula."' role='button' class='set-tutor boto-blau px-4 d-flex'>
					Assigna
				</button></div>";

				$table .= "<tr>";

				$table .= "
				<td>".$titolCurs."</td>
				<td id='codiCurs-".$idCurs."-".$aula."'>".$codiCurs."</td>
				<td>".$aula."</td>
				<td id='tutor-".$idCurs."-".$aula."'>".$nomTutor." ".$cogTutor."</td>
				<td id='idCuho-".$idCurs."-".$aula."' class='d-none'>".$idCuho."</td>
				<td>".$botoAfegirTutor."</td>
				<td id='idAula-".$idCurs."-".$aula."' class='d-none'>".$idAula."</td>
				</tr>";

				if ( $asc == 1 ) {
					$i++;
					$condicio = $i < $fi;
				}
				else {
					$i--;
					$condicio = $i >= $fi;
				}
			}

			$table .= "</tbody></table>";

			$mostrar = "<div class='d-flex flex-column justify-content-center align-items-center
					w-100 text-center border-bottom card-header'>
					<p class='title font-weight-bold text-center py-3 mb-0 align-items-center
					justify-content-center d-flex'>ASSIGNAR TUTORS</p>
				</div>
				<div class='card-body px-0'>
					<p>Resultats de la cerca del <strong> ".$mes."/".$any."</strong>:</p>
					".$table."
				</div>";
		}
		else {
			$mostrar = "";
		}

		return $mostrar;
	}

	/**
	* @brief Mostra els tutors disponibles del curs amb id $idCurs
	* @return Mostra els tutors disponibles del curs amb id $idCurs
	*/
	public function mostrarModal_PreviIniciCursos_AssignarTutors($codiCurs, $idCurs, $aula, $idCuho, $any, $mes) {
		// busquem els tutors relacionats a cada curs

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();
		$conWeb2 = new ConnexioWeb();
		$conWeb2->connectarBD();

		$i=0;

