	/**
	* @brief Actualitza la base de dades amb el el id cuho $idCuho del curs amb id $idCurs de l'aula $aula
	* @return Actualitza la base de dades de curs i cursos amb el el id cuho $idCuho
	* i el dni tutor del curs amb id $idCurs de l'aula $aula.
	*/
	public function updCursos_PreviIniciCursos_AssignarTutors($codiCurs, $idCurs, $aula, $idCuho, $any, $mes) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		/* Busco el dni tutor relacionat amb el id_cuho i el codicurs */
		// echo $this->consultesBD_Web["cnsInfoByIdCuhoCurs"]."<br />";
		// echo $codiCurs."<br />";
		// echo $idCuho."<br /><br />";
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["cnsInfoByIdCuhoCurs"] ) ) {
			$stmt->bind_param("sd", $codiCurs, $idCuho);
			$stmt->execute();
			$stmt->store_result();
			$stmt->bind_result($dniTutor);
			$stmt->fetch();
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('', 4388);
		}

		/* Actualitzo el dni tutor i el id cuho de cursos */
		$idCursLike = $idCurs."%";

		// echo $this->consultesBD_Web["updCursosIdCuho"]."<br />";
		// echo $dniTutor."<br />";
		// echo $idCuho."<br />";
		// echo $idCursLike."<br />";
		// echo $aula."<br /><br />";
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["updCursosIdCuho"] ) ) {
			$stmt->bind_param("sdss", $dniTutor, $idCuho, $idCursLike, $aula);
			$stmt->execute();
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('', 4389);
		}

		/* Actualitzo el id cuho de curs */
		// echo $this->consultesBD_Web["cnsIdAula"]."<br />";
		// echo $idCurs."<br /><br />";
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["cnsIdAula"] ) ) {
			$stmt->bind_param("s", $idCurs);
			$stmt->execute();
			$stmt->store_result();
			$stmt->bind_result($idAula);
			$stmt->fetch();
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('', 4390);
		}
		// echo $this->consultesBD_Web["updAulaIdCuho"]."<br />";
		// echo $idCuho."<br />";
		// echo $idAula."<br />";
		// echo $aula."<br /><br />";
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["updAulaIdCuho"] ) ) {
			$stmt->bind_param("sds", $idCuho, $idAula, $aula);
			$stmt->execute();
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('', 4391);
		}

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["cnsInfoTutor"] ) ) {
			$stmt->bind_param("s", $dniTutor);
			$stmt->execute();
			$stmt->bind_result($nomTutor, $cogTutor, $mailPrsima, $mailPersonal, $curriculum, $titulacio, $idImgLarge, $idImgSmall, $idUrl);
			$stmt->fetch();
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('', 4392);
		}

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarCursSegEd"] ) ) {
			$stmt->bind_param("dss", $any, $mes, $codiCurs);
			$stmt->execute();
			$stmt->bind_result($nomCurs, $dataI, $dataF, $hores, $idPreu);
			$stmt->fetch();
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('', 4393);
		}

		$conWeb->desconectarBD();

		$mostrar = "S'ha assignat el tutor <strong>".$nomTutor." ".$cogTutor."</strong> en el curs <strong>".$nomCurs."</strong> correctament!";

		return $mostrar;

	}

	/**
	* @brief Mostra els cursos que comencen en una edició ordenats
	* @return Mostra els cursos disponibles a l'edició del mes $mes i de l'any $any ordenats per $oderby i en ascendent segons $asc
	*/
	public function mostrarCursos_PreviIniciCursos_PropostaTutoritzacio($any, $mes, $orderby, $asc) {
		$mostrar = "mostrarCursos_PreviIniciCursos_PropostaTutoritzacio <br />
		".$any." ".$mes." ".$orderby." ".$asc;

		if ($orderby != 'codi' && $orderby!='titol')
			$orderby = 'codi';
		if ($asc!=1 and $asc!=0)
			$asc = 1;

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();
		$conWeb2 = new ConnexioWeb();
		$conWeb2->connectarBD();

		$i=0;

		/* Buscar tots els cursos que estan pendents de confirmar un tutor de l'any $any i del mes $mes.*/
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["cnsCursPendConfTutor"] ) ) {
			$stmt->bind_param("ds", $any, $mes);
			$stmt->execute();
			$stmt->store_result();
			$stmt->bind_result($titolCurs, $idCurs, $codiCurs, $dataI, $dataF,
			$idAula, $aula, $idCuho, $nomTutor, $cogTutor, $mailPrismaTutor, $mailPersTutor);
			if ( $stmt->num_rows() > 0 ) {
				while ( $stmt->fetch() ) {
					$resultats[$i][0] = $titolCurs;
					$resultats[$i][1] = $codiCurs;
					$resultats[$i][2] = $aula;
					$resultats[$i][3] = $idCurs;
					$resultats[$i][4] = $idAula;
					$resultats[$i][5] = $idCuho;
					$resultats[$i][6] = $nomTutor;
					$resultats[$i][7] = $cogTutor;
					$resultats[$i][8] = $mailPrismaTutor;
					$resultats[$i][9] = $mailPersTutor;

					/* buscar el nº inscrits */
					if ( $stmt2=$conWeb2->prepare( $this->consultesBD_Web["cnsNumInscGrup"] ) ) {
						$stmt2->bind_param("dsss", $any, $mes, $codiCurs, $aula);
						$stmt2->execute();
						$stmt2->bind_result($nInsc);
						$stmt2->fetch();
						$conWeb2->closeStmt();
					}
					else {
						throw new Exception('', 4384);
					}
					$resultats[$i][10] = $nInsc;

					$i++;
				}
			}
			else {
				$resultats = [];
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('', 4383);
		}

		$conWeb2->desconectarBD();
		$conWeb->desconectarBD();

		if ( count($resultats) > 0 ) {
			function cmpCodi($a, $b) {
			    if ($a[1] == $b[1]) {
			        return 0;
			    }
			    return ($a[1] < $b[1]) ? -1 : 1;
			}

			function cmpTitol($a, $b) {
			    if ($a[0] == $b[0]) {
			        return 0;
			    }
			    return ($a[0] < $b[0]) ? -1 : 1;
			}

			if ($orderby == 'codi') usort($resultats, "cmpCodi");
			else if ($orderby == 'titol') usort($resultats, "cmpTitol");

			$classCurs = '';
			$classTitol = '';

			if ($asc == 1) { //s'ordena ascendentment
				$inici = 0;
				$fi = count($resultats);
				$i = $inici;
				$condicio = $i < $fi;

				if ($orderby == 'codi') $classCurs = ' asc';
				else if ($orderby == 'titol') $classTitol = ' asc';
			}
			else { //s'ordena dsscendentment
				$inici = count($resultats);
				$fi = 0;
				$i = $inici-1;
				$condicio = $i >= $fi;

				if ($orderby == 'codi') $classCurs = ' desc';
				else if ($orderby == 'titol') $classTitol = ' desc';
			}

			//Mostra usuaris en format d'una taula ordenats per dni;
			$table = "<table class='table table-striped table-hover table-order text-center'>
			<thead>
				<tr>
					<th id='th-codi' class='sorting".$classCurs."'>CURS</th>
					<th>AULA</th>
					<th colspan='2'>TUTOR/A</th>
					<th>CORREU PERSONAL/PRISMA</th>
					<th>ALUMNES</th>
					<th>SELECCIONAR</th>
					</tr>
			</thead>
			<tbody>";

			while ( $condicio ) {
				$titolCurs = $resultats[$i][0];
				$codiCurs = $resultats[$i][1];
				$aula = $resultats[$i][2];
				$idCurs = $resultats[$i][3];
				$idAula = $resultats[$i][4];
				$idCuho = $resultats[$i][5];
				$nomTutor = $resultats[$i][6];
				$cogTutor = $resultats[$i][7];
				$mailPersTutor = $resultats[$i][8];
				$mailPrisTutor = $resultats[$i][9];
				$nInsc = $resultats[$i][10];

				$botoCanviTutor = "<div class='d-flex flex-row justify-content-center align-items-center my-2'>
					<i id='canvi-tutor-".$idCurs."-".$aula."' class='canvi-tutor material-icons ml-1'>change_circle</i>
				</div>";

				if ( $idCuho == 17 ) {
					$labelAvis = "<label id='avisar-tutor-".$idCurs."-".$aula."' class='avisar-tutor label d-flex justify-content-center
					align-items-center position-relative font-weight-bold px-2 py-2 lightRed'>NO</label>";

					$table .= "<tr class='text-danger'>";
				}
				else {
					$labelAvis = "<label id='avisar-tutor-".$idCurs."-".$aula."' class='avisar-tutor label d-flex justify-content-center
					align-items-center position-relative font-weight-bold px-2 py-2 lightGreen'>SÍ</label>";

					$table .= "<tr>";
				}

				$table .= "
				<td id='codiCurs-".$idCurs."-".$aula."'>".$codiCurs."</td>
				<td>".$aula."</td>
				<td id='idCuho-".$idCurs."-".$aula."' class='d-none'>".$idCuho."</td>
				<td id='tutor-".$idCurs."-".$aula."'>".$nomTutor." ".$cogTutor."</td>
				<td>".$botoCanviTutor."</td>
				<td id='mailTut-".$idCurs."-".$aula."'>".$mailPersTutor." - ".$mailPrisTutor."</td>
				<td>".$nInsc."</td>
				<td id='idAula-".$idCurs."-".$aula."' class='d-none'>".$idAula."</td>
				<td>".$labelAvis."</td>
				</tr>";

				if ( $asc == 1 ) {
					$i++;
					$condicio = $i < $fi;
				}
				else {
					$i--;
					$condicio = $i >= $fi;
				}
			}

			$table .= "</tbody></table>";
			$table .= "<div class='card-footer d-flex justify-content-center align-items-center'>
				<button id='guardar-canvis-envia' role='button' class='boto-blau px-4 d-flex'>
					Envia correus
					<i class='material-icons ml-1'>send</i>
				</button>
			</div>";
		}
		else {
			$table = "<p class='text-center'>No hi ha resultats.</p>";
		}

		$footerModalConsulta = "<div class='modal-footer border-0 d-flex align-items-center justify-content-center p-0'>
			<a role='button' id='selecciona-tutor' class='btn btn-info selecciona-tutor' aria-label='Close' data-dismiss='modal'>SELECCIONA TUTOR/A</a>
		</div>";

		$mostrar = "<div class='d-flex flex-column justify-content-center align-items-center
				w-100 text-center border-bottom card-header'>
				<p class='title font-weight-bold text-center py-3 mb-0 align-items-center
				justify-content-center d-flex'>PROPOSTA DE TUTORITZACIÓ</p>
			</div>
		<div class='card-body px-0'>
			<p>Resultats de la cerca del <strong> ".$mes."/".$any."</strong>:</p>
			".$table."
			".$this->__mostrarModalConsulta("modalEscollirTutor", 1, 1, '', '')."
		</div>";

		return $mostrar;
	}

