	/**
	* @brief Enviar proposta de tutorització al tutor que correspon al $idCuho
	* del curs $codiCurs i de l'any $any i del mes $mes de l'aula $aula
	* @return Enviar proposta de tutorització al tutor que correspon al $idCuho
	* del curs $codiCurs i de l'any $any i del mes $mes de l'aula $aula
	*/
	public function enviarCorreus_PreviIniciCursos_PropostaTutoritzacio($codiCurs, $idCurs, $aula, $idCuho, $any, $mes) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		$qui = $this->usuari->getNom()->get()." ".$this->usuari->getCognom()->get();
		$depart = $this->usuari->getDepart()->get();

		/* Buscar el nombre d'inscirts a partir de l'any, el mes i el codi curs i l'aula */
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["nInscritsEdicio"] ) ) {
			$stmt->bind_param("dsss", $any, $mes, $codiCurs, $aula);
			$stmt->execute();
			$stmt->store_result();
			$numInscrits = $stmt->num_rows();
		}
		else {
			throw new Exception('', 4396	);
		}
		$conWeb->closeStmt();

		/* Calcular el missatge de la solicitud a partir del nombre d'inscrits */
		if ( $numInscrits == 0 ) {
			$solicitud = "no hi ha cap sol·licitud";
		}
		else {
			$solicitud = "hi ha ".$numInscrits." sol·licitud";
			if ( $numInscrits > 1 ) {
				$solicitud .= "s";
			}
		}

		/* Buscar el nom del curs, la data d'inici i la data de fi a partir de l'any, el mes i el codi curs */
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarCursSegEd"] ) ) {
			$stmt->bind_param("dss", $any, $mes, $codiCurs);
			$stmt->execute();
			$stmt->bind_result($nomCurs, $dataI, $dataF, $hores, $idPreu);
			$stmt->fetch();
		}
		else {
			throw new Exception('', 4397	);
		}
		$conWeb->closeStmt();

		require_once "Date.php";

		/* Buscar la data d'obertura */
		$objDateOpen = new Date( $this->getDataObertura( $dataI ) );
		$dataObertura = $objDateOpen->getDataFomatDDMMYYYY_HHMMSS();
		$dataLlargaObertura = $objDateOpen->getDataLlarga();

		$pronomDataObertura = $objDateOpen->getPronomEl()."<strong>".$dataLlargaObertura."</strong>";

		/* Busca la data d'inici */
		$objDataI = new Date($dataI);
		$dataLlargaInici = $objDataI->getDataLlarga();
		$objDataF = new Date($dataF);
		$dataLlargaFi = $objDataF->getDataLlarga();

		$pronomDataInici = $objDataI->getPronomEl()."<strong>".$dataLlargaInici."</strong>";
		$pronomDataFi = $objDataF->getPronomEl()."<strong>".$dataLlargaFi."</strong>";

		/* Buscar els dies de diferencia que hi ha entre avui i la data d'inici */
		$date1 = new DateTime("now");
		$date2 = new DateTime($dataI);
		$diff = $date1->diff($date2);

		$diesQueFaltenIniciCurs = $diff->days;

		/* Buscar el dni del tutor a partir del id cuho i el codi curs */
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["cnsInfoByIdCuhoCurs"] ) ) {
			$stmt->bind_param("sd", $codiCurs, $idCuho);
			$stmt->execute();
			$stmt->bind_result($dniTutor);
			$stmt->fetch();
		}
		else {
			throw new Exception('', 4398	);
		}
		$conWeb->closeStmt();

		/* Buscar info del tutor a partir del dni del tutor */
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["cnsInfoTutor"] ) ) {
			$stmt->bind_param("s", $dniTutor);
			$stmt->execute();
			$stmt->bind_result($nomTutor, $cogTutor, $mailPrismaTutor, $mailPersonalTutor, $curriculum, $titulacio, $idImgLarge, $idImgSmall, $idUrl);
			$stmt->fetch();
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('', 4399);
		}

		/* Eliminar frase proposta de tutorització: 20/04/2026 */
		// $msgProvisional = "";

		// if ( $numInscrits < 5 ) {
		// 	$msgProvisional = "<p>Et recordem que perquè el curs tiri endavant,
		// 	el proper ".$pronomDataObertura." ha d'haver-hi 5 inscrits com a mínim.
		// 	En el cas de no arribar a aquesta quantitat avisarem que el curs encara està pendent de començar i
		// 	que haurem d'esperar uns dies per saber si es realitza aquesta convocatòria.</p>";
		// }

		$conWeb->desconectarBD();

		require_once "MailSMTPComviveBBCC.php";

		$subject = "Propera edició del curs ".$nomCurs;

		/* Eliminar frase proposta de tutorització: 20/04/2026 */
		// $message = "<p>Benvolgut/da ".$nomTutor.",</p>
		// 	<p>En ".$diesQueFaltenIniciCurs." dies aproximadament comença una nova edició del curs <strong style='color: ".$this->colors_destacats["msgDestacatCorreu1"]."'>".$nomCurs."</strong>.
		// 	Volem saber si t'interessaria tutoritzar-lo, tenint en compte que comença ".$pronomDataInici." i acaba ".$pronomDataFi.".</p>
		// 	<p>T'informem que de moment ".$solicitud." d'inscripció, però com que encara falten alguns dies per començar, esperem que en siguin més. </p>
		// 	".$msgProvisional."
		// 	<p>Esperem la teva confirmació.</p>
		// 	<p>Salutacions,</p>";

		$message = "<p>Benvolgut/da ".$nomTutor.",</p>
			<p>En ".$diesQueFaltenIniciCurs." dies aproximadament comença una nova edició del curs <strong style='color: ".$this->colors_destacats["msgDestacatCorreu1"]."'>".$nomCurs."</strong>.
			Volem saber si t'interessaria tutoritzar-lo, tenint en compte que comença ".$pronomDataInici." i acaba ".$pronomDataFi.".</p>
			<p>T'informem que de moment ".$solicitud." d'inscripció, però com que encara falten alguns dies per començar, esperem que en siguin més. </p>
			".$msgProvisional."
			<p>Esperem la teva confirmació.</p>
			<p>Salutacions,</p>";

		/* ########################          SMTP          ######################## */
		$authCoord = $this->getAuthSMTP_Secretaria();
		$userCoord = $authCoord[0];
		$passCoord = $authCoord[1];
		$nameUserCoord = $authCoord[2];

		$nomFromHead = $nameUserCoord;
		$correuFromHead = $userCoord;

		$nomTo = $nomTutor." ".$cogTutor;
		$correuTo = $mailPrismaTutor;
		$nomReplyHead = $nameUserCoord;
		$correuReplyHead = $userCoord;

		$mailCoord = new MailSMTPComviveBBCC($userCoord, $passCoord, $nomFromHead, $correuFromHead,
							 $nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
							 $subject, $message, $qui, $depart);

		$mailCoord->addBCC($mailPersonalTutor, $nomTutor." ".$cogTutor);
		$mailCoord->addBCC($userCoord, $nameUserCoord);
		$mailCoord->send();

		$mostrar = "<p>S'ha enviat un missatge al tutor/a <strong>".$nomTutor." ".$cogTutor."</strong> sobre el curs <strong>".$nomCurs."</strong></p>";

		return $mostrar;
	}

