	/**
   * @brief Mostra l'estructura de la pàgina '/intranet/cursos/fi-cursos/correu-comunicat-certificat/'.
   * @return Mostra l'estructura de la pàgina '/intranet/cursos/fi-cursos/correu-comunicat-certificat/'.
   */
	private function __mostrarPage_Cursos_Certificat() {
		/* Busquem els anys disponibles i formem un llistat a partir del resultat */
		$anysDispo = explode('|', $this->buscarAnysDisponibles());
		/* Busquem els mesos disponibles i formem un llistat a partir del resultat */
		$mesosDispo = explode('|', $this->buscarMesosDisponibles());
		/* Busquem les hores disponibles i formem un llistat a partir del resultat */
		$horesDispo = explode('|', $this->buscarHoresDisponibles());

		/* Busquem la pròxima edició */
		$anyMesProxEd = explode('|', $this->__buscarAnyMesEdicioNoHaFinalitzat() );
		$anyProxEd = $anyMesProxEd[0];
		$mesProxEd = $anyMesProxEd[1];
		$horesProxEd = $anyMesProxEd[2];

		$mostrar = "<div id='cursos' class='card card-blau mt-0'>
		 <div class='d-flex flex-column justify-content-center align-items-center w-100 text-center border-bottom card-header hide'>
			 <p class='title font-weight-bold text-center py-3 mb-0 align-items-center justify-content-center d-flex'>
				 CERCA
				 <i class='material-icons ml-1'>search</i>
			 </p>
		 </div>
		 <div class='card-body px-0'>
			 <div class='d-flex flex-column flex-md-row justify-content-center align-items-center'>
				 ".$this->mostrarSelect('', 'Any', 'active', 'anys-dispo', 'mb-2', $anyProxEd, '', $anysDispo)."
				 ".$this->mostrarSelect('', 'Mes', 'active', 'mesos-dispo', 'mb-2', $mesProxEd, '', $mesosDispo)."
				 ".$this->mostrarSelect('', 'Hores', 'active', 'hores-dispo', 'mb-2', $horesProxEd, '', $horesDispo)."
			 </div>
		 </div>
		 <div class='card-footer d-flex justify-content-center align-items-center'>
			 <button id='cercar-cursos' role='button' class='boto-blau px-4 d-flex'>
				 Cerca
				 <i class='material-icons ml-1'>search</i>
			 </button>
		 </div>
		</div>
		<div id='resultats-cerca' class='card card-blau mt-5' style='display: none'></div>";
		return $mostrar;
	}

	/**
	* @brief Mostra una taula amb la informació dels alumnes que s'han d'enviar els
	* certificats dels cursos de l'any $any, el mes $mes i amb el nombre d'hores $hores
	* ordenats per $orderBy i ascendentment si $asc és 1, altrament descendentment
	* @return Mostra una taula amb la informació dels alumnes que s'han d'enviar els
	* certificats dels cursos de l'any $any, el mes $mes i amb el nombre d'hores $hores
	* ordenats per $orderBy i ascendentment si $asc és 1, altrament descendentment
	*/
	public function mostrarTable_Alumnes_EnviarCertficat($any, $mes, $hores) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();
		$conWeb2 = new ConnexioWeb();
		$conWeb2->connectarBD();
		$apartats = '';
		$existeixenCursos = false;

		/* Buscar tots els cursos de l'any $any i del mes $mes.*/
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["cnsCursosAlumnesCert"] ) ) {
			$stmt->bind_param("dsd", $any, $mes, $hores);
			$stmt->execute();
			$stmt->store_result();
			if ( $stmt->num_rows() > 0 ) {
				$i = 0;
				$stmt->bind_result($codiCurs, $titolCurs, $dataf);
				while ( $stmt->fetch() ) {
					if ( $stmt2=$conWeb2->prepare( $this->consultesBD_Web["cnsInfoAlumnesCertif"] ) ) {
						$stmt2->bind_param("dss",  $any, $mes, $codiCurs);
						$stmt2->execute();
						$stmt2->store_result();
						if ( $stmt2->num_rows() > 0 ) {
							$tableAlumnes = "<table class='table table-striped table-hover table-order text-center'>
								<thead>
									<tr>
										<th>CERTIFICAT</th>
										<th>OBS</th>
										<th>NOM</th>
										<th>COGNOMS</th>
										<th>CORREU</th>
										<th>ENVIAR</th>
									</tr>
								</thead>
							<tbody>";
							$stmt2->bind_result($id, $grup, $obsCert, $certificat, $nom,
							$cognoms, $correu, $adreca, $cp, $poblacio, $aPagar, $pagament, $entitat);
							while ( $stmt2->fetch() ) {
								$classAlumnes = '';
								if ( $aPagar - $pagament > 0 && $entitat == '' ) {
									$labelConfirmacio = $this->obtenirLabel('aprovat-'.$id, 'avisar-alumne lightRed pointer', 'NO ENVIAR');
									$classAlumnes = 'text-danger';
								}
								else {
									$labelConfirmacio = $this->obtenirLabel('aprovat-'.$id, 'avisar-alumne lightGreen pointer', 'ENVIAR');
								}

								$tableAlumnes .= "<tr class='".$classAlumnes."'>
									<td>".$certificat."</td>
									<td>".$obsCert."</td>
									<td>".$nom."</td>
									<td>".$cognoms."</td>
									<td>".$correu."</td>
									<td>".$labelConfirmacio."</td>
								</tr>";
							}
							$tableAlumnes .= "</tbody></table>";
						}
						else {
							//No existeixen cursos pendents:
							$tableAlumnes = "<p class='text-center'>No existeix cap alumne per avisar.</p>";
						}
						$conWeb2->closeStmt();
					}
					else {
						throw new Exception('', 4419);
					}

					$apartats .= "<div class='d-flex flex-column
					justify-content-center align-items-center my-2'>
						<p class='titol-curs text-blue text-center'><strong>".$titolCurs."</strong> - <strong>".$codiCurs."</strong></p>
						<div class='apartat d-flex flex-column flex-md-row align-items-center justify-content-center w-100 my-2'>
							".$tableAlumnes."
						</div>
					</div>";

					$i++;

				}
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('', 4418);
		}

		$conWeb2->desconectarBD();
		$conWeb->desconectarBD();

		if ( $existeixenCursos ) {
			$apartats .= "
			<div class='d-flex flex-column justify-content-center align-items-center my-2'>
				<button id='enviarCorreusCertificat' class='sendAvis boto-blau mt-2 px-4 d-flex'>Enviar correus</button>
			</div>";
		}
		else {
			$apartats .= "<p class='text-center'>No existeixen certificats a enviar.</p>";
		}

		$mostrar = "<div class='d-flex flex-column justify-content-center align-items-center
				w-100 text-center border-bottom card-header'>
				<p class='title font-weight-bold text-center py-3 mb-0 align-items-center
				justify-content-center d-flex'>CERTIFICATS PENDENTS A ENVIAR</p>
			</div>
			<div class='card-body px-0'>
			".$apartats."
		</div>";

		return $mostrar;

	}

	public function mostrarTable_Alumnes_EnviarCertficat_Curs($any, $mes, $curs) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();
		$conWeb2 = new ConnexioWeb();
		$conWeb2->connectarBD();
		$apartats = '';
		$existeixenCursos = false;

		/* Buscar tots els cursos de l'any $any i del mes $mes.*/
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["cnsCursosAlumnesCertCurs"] ) ) {
			$stmt->bind_param("dss", $any, $mes, $curs);
			$stmt->execute();
			$stmt->store_result();
			if ( $stmt->num_rows() > 0 ) {
				$i = 0;
				$stmt->bind_result($codiCurs, $titolCurs, $dataf);
				while ( $stmt->fetch() ) {
					if ( $stmt2=$conWeb2->prepare( $this->consultesBD_Web["cnsInfoAlumnesCertif"] ) ) {
						$stmt2->bind_param("dss",  $any, $mes, $codiCurs);
						$stmt2->execute();
						$stmt2->store_result();
						$existeixenCursos = $stmt2->num_rows() > 0;
						if ( $stmt2->num_rows() > 0 ) {
							$tableAlumnes = "<table class='table table-striped table-hover table-order text-center'>
								<thead>
									<tr>
										<th>CERTIFICAT</th>
										<th>OBS</th>
										<th>NOM</th>
										<th>COGNOMS</th>
										<th>CORREU</th>
										<th>ENVIAR</th>
									</tr>
								</thead>
							<tbody>";
							$stmt2->bind_result($id, $grup, $obsCert, $certificat, $nom,
							$cognoms, $correu, $adreca, $cp, $poblacio, $aPagar, $pagament, $entitat);
							while ( $stmt2->fetch() ) {
								$classAlumnes = '';
								if ( $aPagar - $pagament > 0 && $entitat == '' ) {
									$labelConfirmacio = $this->obtenirLabel('aprovat-'.$id, 'avisar-alumne lightRed pointer', 'NO ENVIAR');
									$classAlumnes = 'text-danger';
								}
								else {
									$labelConfirmacio = $this->obtenirLabel('aprovat-'.$id, 'avisar-alumne lightGreen pointer', 'ENVIAR');
								}

								$tableAlumnes .= "<tr class='".$classAlumnes."'>
									<td>".$certificat."</td>
									<td>".$obsCert."</td>
									<td>".$nom."</td>
									<td>".$cognoms."</td>
									<td>".$correu."</td>
									<td>".$labelConfirmacio."</td>
								</tr>";
							}
							$tableAlumnes .= "</tbody></table>";
						}
						else {
							//No existeixen cursos pendents:
							$tableAlumnes = "<p class='text-center'>No existeix cap alumne per avisar.</p>";
						}
						$conWeb2->closeStmt();
					}
					else {
						throw new Exception('', 4419);
					}

					$apartats .= "<div class='d-flex flex-column
					justify-content-center align-items-center my-2'>
						<p class='titol-curs text-blue text-center'><strong>".$titolCurs."</strong> - <strong>".$codiCurs."</strong></p>
						<div class='apartat d-flex flex-column flex-md-row align-items-center justify-content-center w-100 my-2'>
							".$tableAlumnes."
						</div>
					</div>";

					$i++;

				}
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('', 4418);
		}

		$conWeb2->desconectarBD();
		$conWeb->desconectarBD();

		if ( $existeixenCursos ) {
			$apartats .= "
			<div class='d-flex flex-column justify-content-center align-items-center my-2'>
				<button id='enviarCorreusCertificat' class='sendAvis boto-blau mt-2 px-4 d-flex'>Enviar correus</button>
			</div>";
		}
		else {
			$apartats .= "<p class='text-center'>No existeixen certificats a enviar.</p>";
		}

		$mostrar = "<div class='d-flex flex-column justify-content-center align-items-center
				w-100 text-center border-bottom card-header'>
				<p class='title font-weight-bold text-center py-3 mb-0 align-items-center
				justify-content-center d-flex'>CERTIFICATS PENDENTS A ENVIAR</p>
			</div>
			<div class='card-body px-0'>
			".$apartats."
		</div>";

		return $mostrar;

	}

	public function sendMsgAvisCursosCertificat( $idInsc ) {
		$mostrar = "";

		$conWeb = new ConnexioWeb();

		$conWeb->connectarBD();

		// Cal obtenir el nom, cognoms, any, mes, curs, correu
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarInfoMostraInfo"] ) ) {
			$stmt->bind_param("d", $idInsc);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($any, $mes, $curs, $aula, $nom, $cognoms, $dni, $correu,
				$telefon, $adreca, $cp, $poblacio, $perfil, $titulacio, $datainsc,
				$inscrit, $tipusInsc, $inscao, $inscmail, $certificat, $obscertificat, $generat, $obs,
				$comentaris, $databaixa, $motiubaixa, $quibaixa, $apagar, $pag, $datapag,
				$idpag, $pagObs, $comHaPagat, $entitat, $fraccio, $comFraccio, $factura, $datarec, $reclamat, $usuari);
				$stmt->fetch();
			}
			else {
				throw new Exception('',4421);
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4422);
		}

		// Cal obtenir la data d'inici $datai, nomCurs del curs de la inscripció $idInsc
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarCursSegEd"] ) ) {
			$stmt->bind_param("dss", $any, $mes, $curs);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($nomCurs, $datai, $dataf, $hores, $idPreu);
				$stmt->fetch();
				$conWeb->closeStmt();
			}
			else {
				throw new Exception('',4423);
			}
		}
		else {
			throw new Exception('',4424);
		}

		$objDataF = new Date($dataf);
		$dataLlargaFi = $objDataF->getDataLlarga();

		$subject = "PrisMa | Certificat curs ".$nomCurs." (".$mes."/".$any.")";
		$subjectCopiaResguard = "PrisMa | Certificat curs ".$nomCurs." (".$mes."/".$any.") ".date('d')."-".date('m')."-".date('Y')." ".date('H').":".date('i');

		$message = "<p>Benvolgut/da ".$nom.",</p>
		<p align=justify>Us comuniquem que ja podeu consultar el vostre certificat de formació
		permanent del curs <strong style='color: ".$this->colors_destacats["msgDestacatCorreu1"]."'>".$nomCurs."</strong> que va acabar
		".$objDataF->getPronomEl()."<strong>".$dataLlargaFi."</strong> a la pàgina de la XTEC clicant damunt la imatge següent:</p>
		<p><a target=\"_blank\" href=\"https://aplicacions.ensenyament.gencat.cat/pls/e13_cert_pub/certificacio_formacio.menu_opcions\">
			<img src=\"http://www.prisma.cat/img_cursos/secretaria/consulta-certificat.jpg\"
			style='width: 100%; min-width: 400px; max-width: 584px;'/>
		</a></p>
		<p>Si no teniu un compte d'usuari XTEC o no recordeu les claus,
		podeu completar <a href=\"https://campus.prisma.cat/alumnes/contacte/codi-verificacio\" target=\"_blank\"><strong>aquest formulari</strong></a>
		i us enviarem un codi de verificació al correu electrònic <strong>".$correu."</strong>
		per descarregar el certificat.</p>
		<p>Salutacions,</p>";

		//Enviem el msg a resguard.secretaria@prisma.cat i a l'allumne
		// cal buscar usuari i contrassenya del correu smtp
		$authSecre = $this->getAuthSMTP_Secretaria();
		$userSecre = $authSecre[0];
		$passSecre = $authSecre[1];
		$nameUserSecre = $authSecre[2];

		require_once 'MailSMTPComvive.php';

		$qui = $this->usuari->getNom()->get()." ".$this->usuari->getCognom()->get();
		$depart = $this->usuari->getDepart()->get();

		$nomFromHead = $nameUserSecre;
		$correuFromHead = $userSecre;

		$nomTo = $nameUserSecre;
		$correuTo = "resguard.secretaria@prisma.cat";
		$correuTo = "meriem.prisma.cat@gmail.com";
		$nomReplyHead = $nom." ".$cog;
		$correuReplyHead = $correu;

		$mailSecre = new MailSMTPComvive($userSecre, $passSecre, $nomFromHead, $correuFromHead,
							$nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
							$subjectCopiaResguard, $message, $qui, $depart);

		$nomTo = $nom." ".$cognoms;
		$correuTo = $correu;
		$correuTo = "meriem.prisma.cat@gmail.com";
		$nomReplyHead = $nameUserSecre;
		$correuReplyHead = $userSecre;

		$mailAlumne = new MailSMTPComvive($userSecre, $passSecre, $nomFromHead, $correuFromHead,
							$nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
							$subject, $message, $qui, $depart);

		$mostrar .= "<p>S'ha enviat un missatge d'informació del certificat
		a l'alumne <strong>".$nom." ".$cognoms."</strong> sobre el curs
		<strong>".$nomCurs."</strong> (".$mes."/".$any.").</p>";

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["updCorreuInfoCertificat"] ) ) {
			$stmt->bind_param("dd", $avis, $idInsc);
			$avis = 1;
			$stmt->execute();
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('', 4425);
		}

		$conWeb->desconectarBD();

		return $mostrar;
	}

