	private function __mostrarPage_Inici_Canviar_Forums_Debat_Simple($idFuncio, $idApartatFuncio) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();
		require_once 'ConnexioMoodle.php';
		$conMdl = new ConnexioMoodle();
		$conMdl->connectarBD();

		$anyProgramat = 2024; $trobat = 0;

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["cnsCursosAmbForumsPreguntesRespostes"] ) ) {
			$stmt->bind_param("d",  $anyProgramat);
			$stmt->execute();
			$stmt->store_result();
			$existeixenCursos = $stmt->num_rows() > 0;
			if ( $existeixenCursos ) {
				$stmt->bind_result($idCurs, $any, $mes, $codiCurs, $aula, $hores, $titolCurs);
				while ( $stmt->fetch() && !$trobat) {
					if ( $stmt2=$conMdl->prepare( $this->consultesBD_Moodle["buscarActivitatsPregRes"] ) ) {
						$stmt2->bind_param("s", $shortname);
						$shortname = $any.$codiCurs.$mes.$aula;
						$stmt2->execute();
						$stmt2->store_result();
						if ($stmt2->num_rows() > 0) {
							$trobat = 1;
						}
					}
					else {
						throw new Exception('',xxxx);
					}
				}
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('', xxxx);
		}
		$conMdl->desconectarBD();

		if ($trobat) {
			$button = "<p>Hi han fòrums que s'han de canviar de p/r a debat simple.</p>
			<button id='canvi-pregresp-".$idApartatFuncio."' class='canvi-pregresp boto-blau mt-2 px-4 d-flex'>Modifica els fòrums!</button>";
		}
		else
			$button = "<p class='text-center'>No hi ha resultats.</p>";

		return $button;
	}

