	/**
   * @brief Mostra una taula amb els les activitats que són forum de preguntes i respostes del curs amb id $idCurs
   * @return Mostra una taula amb els les activitats que són forum de preguntes i respostes del curs amb id $idCurs.
	*			Per cada activitat, es mostrarà un registre a la taula amb els ítems de l'any, el mes, el codicurs,
	*			l'aula, les hores, el nom de l'activitat y un label per marcar sí s'ha de canviar o no l'activitat.
   */
	private function mostrarTable_Cursos_CanviarForumPreguntesRespostes($idCurs, $any, $mes, $codiCurs, $aula, $hores) {
		$tableCursos = '';

		require_once 'ConnexioMoodle.php';
		$conMdl = new ConnexioMoodle();
		$conMdl->connectarBD();
		$conMdl2 = new ConnexioMoodle();
		$conMdl2->connectarBD();

		//Busquem les activitats que siguin pregutnes i respostes del idcurs $idcurs
		if ( $stmt=$conMdl->prepare( $this->consultesBD_Moodle["buscarActivitatsPregRes"] ) ) {
			$stmt->bind_param("s", $shortname);
			$shortname = $any.$codiCurs.$mes.$aula;
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($idForum, $nameForum);

				//Mostra capçalera de la taula
				$titolsInscr[0] = "ANY";
				$titolsInscr[1] = "MES";
				$titolsInscr[2] = "CURS";
				$titolsInscr[3] = "AULA";
				$titolsInscr[4] = "HORES";
				$titolsInscr[5] = "ACTIVITAT";
				$titolsInscr[6] = "BOTÓ";
				$titolsInscr[7] = "CANVIAR";

				$tableCursos .= "<table class='table table-striped table-hover table-lg-responsive text-center mt-2 mb-4'>
				<thead><tr>
					<th>".$titolsInscr[0]."</th>
					<th>".$titolsInscr[1]."</th>
					<th>".$titolsInscr[2]."</th>
					<th>".$titolsInscr[3]."</th>
					<th>".$titolsInscr[4]."</th>
					<th>".$titolsInscr[5]."</th>
					<th>".$titolsInscr[6]."</th>
					<th>".$titolsInscr[7]."</th>
				</tr></thead>
				<tbody>";
				//Per cada activitat:
				while ( $stmt->fetch() ) {
					//cns de si l'activitt té més d'una pregunta associada.
					if ( $stmt2=$conMdl2->prepare( $this->consultesBD_Moodle["buscarForums"] ) ) {
						// echo $this->consultesBD_Moodle["buscarForums"]."<br />";
						// echo $idForum."<br />";
						$stmt2->bind_param("d", $idForum);
						$stmt2->execute();
						$stmt2->store_result();
						$mesUnaPreg = $stmt2->num_rows() > 1;
						$stmt2->bind_result($idForumPost);
						$stmt2->fetch();
					}
					else
						throw new Exception('',4475);
					//Obtinc el botó per accedir en el forum de l'activitat
					$nomButtonAct = $this->obtenirIconaFontAw('', '', 'fas fa-link-simple text-white', 'Activitat');
					$nomButtonAct = $this->obtenirIconaFontAw('', '', 'fas fa-square-up-right text-white', 'Activitat');
					$nomButtonAct = $this->obtenirIconaFontAw('', '', 'fas fa-square-arrow-up-right text-white', 'Activitat');
					$nomButtonAct = $this->obtenirIconaFontAw('', '', 'fas fa-up-right-from-square text-white', 'Activitat');
					$btnAct = $this->obtenirBotoTooltip('moodle_act_'.$idForumPost, 'btn-action activitat w-100', $nomButtonAct, 'bottom', 'Activitat en el moodle');

					//Labl per marcar si s'ha de fer el canvi
					if ( $mesUnaPreg ) {
						$labelChange = $this->obtenirLabel('changeAct-'.$idForum.'-'.$idCurs, 'changeAct lightPurple pointer', '+1 PREGUNTA');
					}
					else {
						$labelChange = $this->obtenirLabel('changeAct-'.$idForum.'-'.$idCurs, 'changeAct lightGreen pointer', 'CANVIAR');
					}

					$cntBtn = "<div class='d-flex flex-column flex-sm-row align-items-center justify-content-center w-100'>
					".$btnAct."
					</div>";

					$cntLabel = "<div class='d-flex flex-column flex-xl-row align-items-center justify-content-center w-100'>
					".$labelChange."
					</div>";

					$tableCursos .= "<tr>
						".$this->mostrarFilaTaulaResponsive($titolsInscr[0], $any)."
						".$this->mostrarFilaTaulaResponsive($titolsInscr[1], $mes)."
						".$this->mostrarFilaTaulaResponsive($titolsInscr[2], $codiCurs)."
						".$this->mostrarFilaTaulaResponsive($titolsInscr[3], $aula)."
						".$this->mostrarFilaTaulaResponsive($titolsInscr[4], $hores)."
						".$this->mostrarFilaTaulaResponsive($titolsInscr[5], $nameForum)."
						".$this->mostrarFilaTaulaResponsive($titolsInscr[6], $cntBtn)."
						".$this->mostrarFilaTaulaResponsive($titolsInscr[7], $cntLabel)."
					</tr>";

				}
				$tableCursos .= "</tbody></table>";
			}
		}
		else {
			throw new Exception('',4474);
		}
		$conMdl2->desconectarBD();
		$conMdl->desconectarBD();


		return $tableCursos;
	}

	public function updateCanvisForumsPreguntesRespostes($idCurs, $idForum) {
		//canvio el tipus forum idforum per el tipus debat simple

		require_once 'ConnexioMoodle.php';
		$conMdl = new ConnexioMoodle();
		$conMdl->connectarBD();

		if ( $stmtUpd=$conMdl->prepare( $this->consultesBD_Moodle["updForumSingle"] ) ) {
			$stmtUpd->bind_param("d", $idForum);
			$stmtUpd->execute();
			$conMdl->closeStmt();
		}
		else {
			throw new Exception('',4476);
		}

		$conMdl->desconectarBD();

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		//actualitzo la data del canvi de forum de la taula de cursos
		if ( $stmtUpd=$conWeb->prepare( $this->consultesBD_Web["updCursosDataCanvi"] ) ) {
			$stmtUpd->bind_param("d", $idCurs);
			$stmtUpd->execute();
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4477);
		}

		//busquem el idAula del curs $idCurs
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["cnsIdAula"] ) ) {
			$stmt->bind_param("s", $idCurs);
			$stmt->execute();
			$stmt->store_result();
			$stmt->bind_result($idAula);
			$stmt->fetch();
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('', 4478);
		}

		//actualitzo la data del canvi de forum de la taula de curs
		if ( $stmtUpd=$conWeb->prepare( $this->consultesBD_Web["updCursDataCanvi"] ) ) {
			$stmtUpd->bind_param("d", $idAula);
			$stmtUpd->execute();
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4479);
		}
		$conWeb->desconectarBD();

		$msgMostrar = "<p>S'ha canviat el tipus de fòrum de l'activitat
		<strong class='text-primary'>".$nomActivitat."</strong> del curs
		<strong class='text-secondary'>".$idCurs."</strong> de preguntes i respostes a debat simple.</p>";
		return $msgMostrar;
	}

	/* #########################      INTRANET CURSOS       ######################### */
	/* *************************         FI CURSOS          ************************** */
	/* -------------------------        CURS SUPERAT         -------------------------- */
	/**
   * @brief Mostra l'estructura de la pàgina '/intranet/cursos/fi-cursos/curs-superat-no-superat/'.
   * @return Mostra l'estructura de la pàgina '/intranet/cursos/fi-cursos/curs-superat-no-superat/'.
   */
	private function __mostrarPage_Cursos_Fi_Cursos_Curs_Superat() {
		/* Busquem els anys disponibles i formem un llistat a partir del resultat */
		$anysDispo = explode('|', $this->buscarAnysDisponibles());
		/* Busquem els mesos disponibles i formem un llistat a partir del resultat */
		$mesosDispo = explode('|', $this->buscarMesosDisponibles());
		/* Busquem les hores disponibles i formem un llistat a partir del resultat */
		$horesDispo = explode('|', $this->buscarHoresDisponibles());

		/* Busquem la pròxima edició */
		$anyMesProxEd = explode('|', $this->__buscarAnyMesEdicioNoHaFinalitzat() );
		$anyProxEd = $anyMesProxEd[0];
		$mesProxEd = $anyMesProxEd[1];
		$horesProxEd = $anyMesProxEd[2];

