	public function mostrarTable_Alumnes_Curs_EnviarMsgCursSuperat($any, $mes, $codiCurs) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		/*
		Busco totes les inscripcions que hi han de l'any, el mes i les hores cercades,
		el curs actual, que estiguin inscrits, on CERTIFICAT es NUULL i
		correu_curs_superat = 0
		*/
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["cnsInfoAlumnesCursSuperat"] ) ) {
			$stmt->bind_param("dss",  $any, $mes, $codiCurs);
			$stmt->execute();
			$stmt->store_result();
			if ( $stmt->num_rows() > 0 ) {
				$tableAlumnes = "<table class='table table-striped table-hover table-order text-center cnt-curs-superat'>
					<thead>
						<tr>
							<th></th>
							<th>GRUP</th>
							<th>NOM TUTOR/A</th>
							<th>NOM ALUMNE</th>
							<th style='width: 15%'>OBS</th>
							<th>FALTA</th>
							<th>NO SUPERAT</th>
							<th>OBS CERT</th>
							<th>BOTONS</th>
							<th>ENVIAR</th>
						</tr>
					</thead>
				<tbody>";
				$stmt->bind_result($id, $grup, $obs, $obsCert, $certificat, $nom,
				$cognoms, $correu, $adreca, $cp, $poblacio, $usuari, $tipusI,
				$aPagar, $pagament, $idPag, $entitat);
				while ( $stmt->fetch() ) {

					//Busquem el ID del curs i de l'usuari del moodle
					$userIdMdl = "";
					$courseIdMdl = "";

					require_once 'ConnexioMoodle.php';
					require_once 'ConnexioMoodleAntic.php';

					$conMdl1 = new ConnexioMoodle();
					$conMdl1->connectarBD();
					if ( $stmt1=$conMdl1->prepare( $this->consultesBD_Moodle["buscarIdCurs"] ) ) {
						$stmt1->bind_param("s", $shortname);
						$shortname = $any.$codiCurs.$mes.$grup;
						$stmt1->execute();
						$stmt1->store_result();
						if ($stmt1->num_rows() > 0) {
							$stmt1->bind_result($courseIdMdl);
							$stmt1->fetch();
							$existCursMdl = true;
							$textMoodle = 'moodle';

							$conMdl12 = new ConnexioMoodle();
							$conMdl12->connectarBD();

							if ( $stmt2=$conMdl12->prepare( $this->consultesBD_Moodle["buscarIdUsuari"] ) ) {
								$stmt2->bind_param("d", $usuari);
								$stmt2->execute();
								$stmt2->store_result();
								if ($stmt2->num_rows() > 0) {
									$stmt2->bind_result($userIdMdl);
									$stmt2->fetch();
									$conMdl12->closeStmt();
								}
								else {
									$conMdl12->closeStmt();
									$existCursMdl = false;
								}
							}
							else {
								throw new Exception('',4428);
							}
							$conMdl12->desconectarBD();
						}
						else {

							$conMdl2 = new ConnexioMoodleAntic();
							$conMdl2->connectarBD();
							if ( $stmt12=$conMdl2->prepare( $this->consultesBD_MoodleAntic["buscarIdCurs"] ) ) {
								$stmt12->bind_param("s", $shortname);
								$shortname = $any.$codiCurs.$mes.$grup;
								$stmt12->execute();
								$stmt12->store_result();
								if ($stmt12->num_rows() > 0) {
									$stmt12->bind_result($courseIdMdl);
									$stmt12->fetch();
									$conMdl2->closeStmt();

									$existCursMdl = true;
									$textMoodle = 'moodleAntic';

									$conMdl122 = new ConnexioMoodleAntic();
									$conMdl122->connectarBD();

									if ( $stmt122=$conMdl122->prepare( $this->consultesBD_MoodleAntic["buscarIdUsuari"] ) ) {
										$stmt122->bind_param("d", $usuari);
										$stmt122->execute();
										$stmt122->store_result();
										if ($stmt122->num_rows() > 0) {
											$stmt122->bind_result($userIdMdl);
											$stmt122->fetch();
										}
										else {
											$existCursMdl = false;
										}
									}
									else {
										throw new Exception('',xxxx);
									}
									$conMdl122->desconectarBD();

								}
								else {
									$existCursMdl = false;
								}
							}
							else {
								throw new Exception('', xxxx);
							}
							$conMdl2->closeStmt();
							$conMdl2->desconectarBD();
						}
						$conMdl1->closeStmt();
					}
					else {
						throw new Exception('',4427);
					}
					$conMdl1->desconectarBD();

					if ($existCursMdl) {
						$classMdlDispo = "btn-action";
						$textBotoMoodleDispo = "";
					}
					else {
						$classMdlDispo = "btn-action-disable";
						$textBotoMoodleDispo = " no disponible";
					}

					//Obtinc el botó per accedir a les qualificacions
					$nomButtonQual = $this->obtenirIconaFontAw('', '', 'fas fa-user-graduate text-white', 'Qualificador'.$textBotoMoodleDispo);
					$btnQual = $this->obtenirBotoTooltip($textMoodle.'_qual_'.$courseIdMdl.'_'.$userIdMdl, $classMdlDispo.' qualificador w-100', $nomButtonQual, 'bottom', 'Qualificacions en el moodle');
					//Obtinc el botó per accedir a les participacions
					$nomButtonPart = $this->obtenirIconaFontAw('', '', 'fas fa-comments text-white', 'Participacions'.$textBotoMoodleDispo);
					$btnPart = $this->obtenirBotoTooltip($textMoodle.'_part_'.$userIdMdl.'_'.$courseIdMdl, $classMdlDispo.' participacions w-100 ml-md-2', $nomButtonPart, 'bottom', 'Participacions en el moodle');

					$classAlumnes = '';
					if ( $aPagar - $pagament > 0 && $entitat == '' ) {
						$labelAvisAlumne = $this->obtenirLabel('aprovat-alumne-'.$id, 'avisar-alumne lightRed pointer', 'NO ENVIAR ALUMNE/A');
						$labelAvisTutor= $this->obtenirLabel('aprovat-tutor-'.$id, 'avisar-tutor lightRed pointer', 'NO ENVIAR TUTOR/A');
						$classAlumnes = 'text-danger';
						$faltaPagar = $aPagar - $pagament;
					}
					else {
						$faltaPagar = 0;
					}

					//Busco la qualificació que ha de tenir aquest curs per aprovar
					$puntuacioApprove = 66;

					$conIntra = new ConnexioIntranet();
					$conIntra->connectarBD();

					/* ##### Busquem les despeses corresponents a les hores del curs ##### */
					/* Les despeses de gestió es calculen segons el nombre d'hores del curs anterior
					ja que representa que és el que li has pagat el tutor/a */
					if ( $stmtI=$conIntra->prepare( $this->consultesBD_Intra["buscarParam"] ) ) {
						$stmtI->bind_param("ss", $param, $tipus);
						$param = "puntuacio-aprovar-campus";
						$tipus = $codiCurs;
						// echo $id;
						// echo $this->consultesBD_Intra["buscarParam"];
						// echo $param;
						// echo $tipus;
						$stmtI->execute();
						$stmtI->store_result();
						if ( $stmtI->num_rows() > 0 ) {
							$stmtI->bind_result($puntuacioApprove);
							$stmtI->fetch();
						}
						else {
							$param = "puntuacio-aprovar-campus";
							$tipus = 'tots';
							$stmtI->execute();
							// echo $id;
							// echo $this->consultesBD_Intra["buscarParam"];
							// echo $param;
							// echo $tipus;
							if ( $stmtI->num_rows() > 0 ) {
								$stmtI->bind_result($puntuacioApprove);
								$stmtI->fetch();
							}
						}
						$conIntra->closeStmt();
					}
					else
						throw new Exception('',4429);

					$conIntra->desconectarBD();

					$notAprove = 0;

					//Busco la puntuació de la inscripció en el curs de la inscripció té aprovades les qualificacions
					if ( $textMoodle == 'moodle' ) {
						//Busco la puntuació de la inscripció en el curs de la inscripció té aprovades les qualificacions
						//en el moodle nou
						$conMdl1 = new ConnexioMoodle();
						$conMdl1->connectarBD();
						// echo $this->consultesBD_Moodle["cnsUserApprove"]."<br>";
						// echo $any.$codiCurs.$mes.$grup." ".$any.$codiCurs.$mes.$grup." ".$puntuacioApprove." ".$usuari."<br>";
						if ( $stmt1=$conMdl1->prepare( $this->consultesBD_Moodle["cnsUserApprove"] ) ) {
							$stmt1->bind_param("ssds", $shortname, $shortname, $puntuacioApprove, $usuari);
							$shortname = $any.$codiCurs.$mes.$grup;
							$stmt1->execute();
							$stmt1->store_result();
							if ( $stmt1->num_rows() > 0 ) {
								$stmt1->bind_result($userMdl11);
								$stmt1->fetch();
								$notAprove = 1;
							}
							$conMdl1->closeStmt();
						}
						else
							throw new Exception('',4430);
						// $puntuacioUser = 0;

						if ( $notAprove ) {
							$labelAvisAlumne = $this->obtenirLabel('aprovat-alumne-'.$id, 'avisar-alumne lightGreen pointer', 'ENVIA ALUMNE/A');
							$labelAvisTutor= $this->obtenirLabel('aprovat-tutor-'.$id, 'avisar-tutor lightRed pointer', 'NO ENVIAR TUTOR/A');
						}
						else {
							$labelAvisAlumne = $this->obtenirLabel('aprovat-alumne-'.$id, 'avisar-alumne lightRed pointer', 'NO ENVIAR ALUMNE/A');
							$labelAvisTutor= $this->obtenirLabel('aprovat-tutor-'.$id, 'avisar-tutor lightRed pointer', 'NO ENVIAR TUTOR/A');
						}

						$conMdl1->desconectarBD();
					}
					if ( $textMoodle == 'moodleAntic' ) {
						//Busco la puntuació de la inscripció en el curs de la inscripció té aprovades les qualificacions
						//en el moodle antic
						$conMdl2 = new ConnexioMoodleAntic();
						$conMdl2->connectarBD();
						if ( $stmt1=$conMdl2->prepare( $this->consultesBD_MoodleAntic["cnsUserApprove"] ) ) {
							$stmt1->bind_param("sssd", $shortname, $shortname, $usuari, $puntuacioApprove);
							$shortname = $any.$codiCurs.$mes.$grup;
							$stmt1->execute();
							if ( $stmt1->num_rows() > 0 ) {
								$stmt1->bind_result($userMdl12);
								$stmt1->fetch();
								$notAprove = 1;
							}
							$conMdl2->closeStmt();
						}
						else
							throw new Exception('',4431);
						// $puntuacioUser = 0;
						if ( $notAprove ) {
							$labelAvisAlumne = $this->obtenirLabel('aprovat-alumne-'.$id, 'avisar-alumne lightGreen pointer', 'ENVIA ALUMNE/A');
							$labelAvisTutor= $this->obtenirLabel('aprovat-tutor-'.$id, 'avisar-tutor lightRed pointer', 'NO ENVIAR TUTOR/A');
						}
						else {
							$labelAvisAlumne = $this->obtenirLabel('aprovat-alumne-'.$id, 'avisar-alumne lightRed pointer', 'NO ENVIAR ALUMNE/A');
							$labelAvisTutor= $this->obtenirLabel('aprovat-tutor-'.$id, 'avisar-tutor lightRed pointer', 'NO ENVIAR TUTOR/A');
						}
						$conMdl2->desconectarBD();
					}

					if ( !$notAprove ) {
						$nomButtonDontApprove = "NO SUPERAT";
						$btnNotAprove = $this->obtenirBoto('btn_not_aprove_'.$id, 'not-aprove w-100 ml-md-2', $nomButtonDontApprove);
					}
					else {
						$btnNotAprove = '';
					}

					//Marcar el tipus d'inscripció i si es tracta d'una entitat
					if ( $tipusI == 'I' ) {
						$idCercat = $idPag;
						$classTipus = "lightBlue";
						$iconTipus = $this->obtenirIconaMaterials('', '', 'person', 'Inscripció normal');
					}
					else if ( $tipusI == 'R' ) {
						$idCercat = $id;
						$classTipus = "lightGreen";
						$iconTipus = $this->obtenirIconaFontAw('', 'fas', 'fa-gift', '');
					}
					else if ( $tipusI == 'P' ) {
						$idCercat = $idPag;
						$classTipus = "lightPurple";
						$iconTipus = $this->obtenirIconaFontAw('', 'fas', 'fa-cubes', '');
					}
					else if ( $tipusI == 'G' ) {
						$idCercat = $idPag;
						$classTipus = "lightOrange";
						$iconTipus = $this->obtenirIconaMaterials('', '', 'group', 'Inscripció grupal');
					}

					$labelTipusInscr = $this->obtenirLabel('labelType-'.$idCercat, $classTipus, $iconTipus);

					$nomCompletTutor = "";
					//Buscar el tutor d'aquest curs i mostrar el nom i el cognom
					if ( $stmtT=$conWeb->prepare( $this->consultesBD_Web["buscarDadesPersonalByCurs"] ) ) {
						$stmtT->bind_param("dssssd", $any, $mes, $codiCurs, $grup, $perfil, $estatPersonal);
						$perfil = 'tutor';
						$estatPersonal = 1;
						$stmtT->execute();
						$stmtT->store_result();
						if ($stmtT->num_rows() > 0) {
							$stmtT->bind_result($dniTutor, $nomTutor, $cogTutor, $correuTutorPrisma, $correuTutorPers);
							while ( $stmtT->fetch() ) {
								if ( $nomTutor != 'PENDENT' ) {
									if ( $nomCompletTutor != '' ) $nomCompletTutor .= " / ";
									$nomCompletTutor .= $nomTutor." ".$cogTutor;
								}
							}
						}
						else //no existeix el tutor/a a la taula personal
							throw new Exception('',4433);
						$conWeb->closeStmt();
					}
					else
						throw new Exception('',4432);

					$nomCompletAlumne = $nom." ".$cognoms;
					$faltaPagar = floatval($faltaPagar);

					$tableAlumnes .= "<tr class='".$classAlumnes."'>
						<td>".$labelTipusInscr."</td>
						<td>".$grup."</td>
						<td>".$nomCompletTutor."</td>
						<td>".$nomCompletAlumne."</td>
						<td>".$obs."</td>
						<td>".$faltaPagar." €</td>
						<td>".$btnNotAprove."</td>
						<td>".$obsCert."</td>
						<td>
							<div class='d-flex flex-column flex-sm-row align-items-center justify-content-center w-100'>
							".$btnQual.$btnPart."
							</div>
						</td>
						<td>
							<div class='d-flex flex-column flex-xl-row align-items-center justify-content-center w-100'>
							".$labelAvisTutor.$labelAvisAlumne."
							</div>
						</td>
					</tr>";

				}
				$tableAlumnes .= "</tbody></table>";
			}
			else {
				//No existeixen cursos pendents:
				$tableAlumnes = "<p class='text-center'>No existeix cap alumne per avisar.</p>";
			}
		}
		else {
			throw new Exception('', xxx);
		}
		$conWeb->desconectarBD();

		return $tableAlumnes;
	}

