			$fomulari = "<div class='d-flex flex-row justify-content-center align-items-center my-2'>
				<p class='mb-0'>Introdueix la data en la qual estarà disponible el certificat:</p>
				".$this->__mostrarInput(3, 'w-auto', '', '', '', 'text-center dataDispo', '')."
			</div>";
			$contingut = $fomulari;

			//Mostro la taula de les inscripcions
			// $inscripCurs = '';
			$contingut .= $inscripCurs;

			//Mostro el botó d'enviar missatges
			$nomButtonSend = "Enviar correus".$this->obtenirIconaMaterials('', 'ml-2', 'send', 'Envia correus');

			$contingut .= "
			<div class='d-flex flex-column justify-content-center align-items-center my-2'>
				".$this->obtenirBoto('enviarCorreusCursSuperat', 'sendAvis mt-2', $nomButtonSend)."
			</div>";
		}

		$mostrar = "
		<div class='d-flex flex-column justify-content-center align-items-center
			w-100 text-center border-bottom card-header'>
			<p class='title font-weight-bold text-center py-3 mb-0 align-items-center
			justify-content-center d-flex'>CORREUS PENDENTS A ENVIAR</p>
		</div>
		<div class='card-body px-0'>
		".$contingut."
		</div>";

		return $mostrar;
	}

