	}

	public function sendMsgAvisAlumneCursSuperat($idInsc, $dispo) {
		$mostrar = "";

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		// Cal obtenir el nom, cognoms, any, mes, curs, correu
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarInfoMostraInfo"] ) ) {
			$stmt->bind_param("d", $idInsc);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($any, $mes, $curs, $aula, $nomActual, $cognomsActual,
				$dniActual, $correuActual,	$telefonActual, $adrecaActual, $cpActual,
				$poblacioActual, $perfilActual, $titulacioActual, $datainsc, $inscrit, $tipusInsc,
				$inscao, $inscmail, $certificat, $obscertificat, $generat, $obs,
				$comentaris, $databaixa, $motiubaixa, $quibaixa, $aPagar, $pagament, $datapag,
				$idpag, $pagObs, $comHaPagat, $entitat, $fraccio, $comFraccio, $factura,
				$datarec, $reclamat, $usuari);
				$stmt->fetch();
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',xxxx);
		}

		// Cal obtenir la data d'inici $datai, nomCurs del curs de la inscripció $idInsc
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarCursSegEd"] ) ) {
			$stmt->bind_param("dss", $any, $mes, $curs);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($titol, $datai, $dataF, $hores, $idPreu);
				$stmt->fetch();
				$conWeb->closeStmt();
			}
			else {
				throw new Exception('',xxxx);
			}
		}
		else {
			throw new Exception('',xxxxx);
		}

		//si l'import pendent és positiu i no es tracta d'una entitat.
		if ( $aPagar - $pagament > 0 && ( $entitat == null || $entitat == '' ) ) {
			/* ############## Calculem la url de pagament del $idPagBD ############## */
			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarParam"] ) ) {
				$stmt->bind_param("s", $tipus);

				$tipus = 'keyEncriptar';
				$stmt->execute();
				$stmt->bind_result($keyEncr);
				$stmt->fetch();
				$conWeb->closeStmt();
			}
			else
				throw new Exception('',4036);

			$cipher = "AES-128-CBC";
			$ivlen = openssl_cipher_iv_length($cipher);
			$iv = openssl_random_pseudo_bytes($ivlen);
			$ciphertext_raw = openssl_encrypt($idpag, $cipher, $keyEncr, $options=OPENSSL_RAW_DATA, $iv);
			$hmac = hash_hmac('sha256', $ciphertext_raw, $keyEncr, $as_binary=true);
			$hashIdPag = base64_encode( $iv.$hmac.$ciphertext_raw );

			$urlIdPag = "https://www.prisma.cat/";

			if ( $tipusInsc == 'I' or $tipusInsc == 'R' )
				$urlIdPag .= "pagament/";
			else if ( $tipusInsc == 'G' OR $tipusInsc == 'P' )
				$urlIdPag .= "pagaments/";

			$urlIdPag .= $hashIdPag;

			$pendent = $aPagar - $pagament;

			require_once 'Template.php';
			$templates = new Template();
			$msg = $templates->getTemplate_Inscripcions_Pagaments_MissatgeTextManeresPagar();
			$names_template = array("[URL_PAGAMENT]", "[TITOL]", "[CODI_CURS]", "[MES]");
			$names_function   = array($urlIdPag, $titol, $curs, $mes);
			$textManeresPagar = str_replace($names_template, $names_function, $msg);

			$textNoPagat = "<p>IMPORTANT: Per tal de poder gestionar el certificat hauries d’acabar de fer el pagament dels ".$pendent." euros que falten escollint una de les opcions següents:</p>
			".$textManeresPagar."
			<p>Per a qualsevol dubte en referència al pagament pots consultar-ho amb gestio@prisma.cat.</p>";

			if ( $tipusInsc == 'G') {
				//buscar $dniResp, $nomCompletResp, $correuResp de la persona resonsable
				//cns titol, dataFi del curs $any.$curs.$mes
				if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarInfoPersRespGrup"] ) ) {
					$stmt->bind_param("d", $idpag);
					$stmt->execute();
					$stmt->store_result();
					if ($stmt->num_rows() > 0) {
						$stmt->bind_result($nomResp, $cognomsResp, $dniResp, $correuResp);
						$stmt->fetch();
						$nomCompletResp = $nomResp." ".$cognomsResp;
					}
					else //no existeix el tutor/a a la taula personal
						throw new Exception('',4437);
				}
				else
					throw new Exception('',4436);

				$conWeb->closeStmt();
				// No és la persona responsable
				if ( $dniActual != $dniResp && ( $entitat == null || $entitat == '' ) ) {
					$textNoPagat = "<p>IMPORTANT: Per tal de poder gestionar el certificat hauries d’acabar de fer el pagament grupal dels ".$pendent." euros.</p>
					<p>Posa't en contacte amb <strong>".$nomCompletResp."</strong> al correu electrònic <strong>".$correuResp."</strong> per acabar de fer el pagament.</p>
