						$conMdl1->desconectarBD();
					}
					if ( $textMoodle == 'moodleAntic' ) {
						//Busco la puntuació de la inscripció en el curs de la inscripció té aprovades les qualificacions
						//en el moodle antic
						$conMdl2 = new ConnexioMoodleAntic();
						$conMdl2->connectarBD();
						if ( $stmt1=$conMdl2->prepare( $this->consultesBD_MoodleAntic["cnsUserApprove"] ) ) {
							$stmt1->bind_param("sssd", $shortname, $shortname, $usuari, $puntuacioApprove);
							$shortname = $any.$codiCurs.$mes.$grup;
							$stmt1->execute();
							if ( $stmt1->num_rows() > 0 ) {
								$stmt1->bind_result($userMdl12);
								$stmt1->fetch();
								$notAprove = 1;
							}
							$conMdl2->closeStmt();
						}
						else
							throw new Exception('',4431);
						// $puntuacioUser = 0;
						if ( $notAprove ) {
							$labelAvisTutor= $this->obtenirLabel('aprovat-tutor-'.$id, 'avisar-tutor lightGreen pointer', 'ENVIAR TUTOR/A');
						}
						else {
							$labelAvisTutor= $this->obtenirLabel('aprovat-tutor-'.$id, 'avisar-tutor lightGreen pointer', 'ENVIAR TUTOR/A');
						}
						$conMdl2->desconectarBD();
					}

					if ( $notAprove ) {
						$nomButtonApprove = "SUPERAT";
						$btnNotAprove = $this->obtenirBoto('btn_aprove_'.$id, 'aprove w-100 ml-md-2', $nomButtonApprove);
						$campus = 'Aprovat/da';
					}
					else {
						$btnNotAprove = '';
						$campus = '';
					}

					//Marcar el tipus d'inscripció i si es tracta d'una entitat
					if ( $tipusI == 'I' ) {
						$idCercat = $idPag;
						$classTipus = "lightBlue";
						$iconTipus = $this->obtenirIconaMaterials('', '', 'person', 'Inscripció normal');
					}
					else if ( $tipusI == 'R' ) {
						$idCercat = $id;
						$classTipus = "lightGreen";
						$iconTipus = $this->obtenirIconaFontAw('', 'fas', 'fa-gift', '');
					}
					else if ( $tipusI == 'P' ) {
						$idCercat = $idPag;
						$classTipus = "lightPurple";
						$iconTipus = $this->obtenirIconaFontAw('', 'fas', 'fa-cubes', '');
					}
					else if ( $tipusI == 'G' ) {
						$idCercat = $idPag;
						$classTipus = "lightOrange";
						$iconTipus = $this->obtenirIconaMaterials('', '', 'group', 'Inscripció grupal');
					}

					$labelTipusInscr = $this->obtenirLabel('labelType-'.$idCercat, $classTipus, $iconTipus);

					$nomCompletTutor = "";
					//Buscar el tutor d'aquest curs i mostrar el nom i el cognom
					if ( $stmtT=$conWeb->prepare( $this->consultesBD_Web["buscarDadesPersonalByCurs"] ) ) {
						$stmtT->bind_param("dssssd", $any, $mes, $codiCurs, $grup, $perfil, $estatPersonal);
						$perfil = 'tutor';
						$estatPersonal = 1;
						$stmtT->execute();
						$stmtT->store_result();
						if ($stmtT->num_rows() > 0) {
							$stmtT->bind_result($dniTutor, $nomTutor, $cogTutor, $correuTutorPrisma, $correuTutorPers);
							while ( $stmtT->fetch() ) {
								if ( $nomTutor != 'PENDENT' ) {
									if ( $nomCompletTutor != '' ) $nomCompletTutor .= " / ";
									$nomCompletTutor .= $nomTutor." ".$cogTutor;
								}
							}
						}
						else //no existeix el tutor/a a la taula personal
							throw new Exception('',4433);
						$conWeb->closeStmt();
					}
					else
						throw new Exception('',4432);

					$nomCompletAlumne = $nom." ".$cognoms;
					$faltaPagar = floatval($faltaPagar);

					// busquem el seguiment dels alumnes suspesos

					//Buscar el tutor d'aquest curs i mostrar el nom i el cognom
					if ( $stmtT=$conWeb->prepare( $this->consultesBD_Web["cnsSeguimentNoAprove"] ) ) {
						$stmtT->bind_param("ds", $usuari, $shortname);
						$shortname = $any.$codiCurs.$mes.$grup;
						$stmtT->execute();
						$stmtT->bind_result($seguiment);
						$stmtT->fetch();
						$conWeb->closeStmt();
					}
					else
						throw new Exception('',xxx);
					// $result_s = mysqli_query ($connexio, "SELECT seguiment FROM cursos INNER JOIN suspesos ON cursos.id_Curs = suspesos.codicurs WHERE usuari='".$row['usuari']."' AND id_Curs='".$codicurs."'");

					$tableAlumnes .= "<tr class='".$classAlumnes."'>
						<td>".$labelTipusInscr."</td>
						<td>".$grup."</td>
						<td>".$nomCompletTutor."</td>
						<td>".$nomCompletAlumne."</td>
						<td>".$faltaPagar." €</td>
						<td>".$btnNotAprove."</td>
						<td>".$obsCert."</td>
						<td>
							<div class='d-flex flex-column flex-sm-row align-items-center justify-content-center w-100'>
							".$btnQual.$btnPart."
							</div>
						</td>
							<td>".$seguiment."</td>
							<td>".$campus."</td>
						<td>
							<div class='d-flex flex-column flex-xl-row align-items-center justify-content-center w-100'>
							".$labelAvisTutor."
							</div>
						</td>
					</tr>";

				}
				$tableAlumnes .= "</tbody></table>";
			}
			else {
				//No existeixen cursos pendents:
				$tableAlumnes = "<p class='text-center'>No existeix cap alumne per avisar.</p>";
			}
		}
		else {
			throw new Exception('', xxx);
		}
		$conWeb->desconectarBD();

		return $tableAlumnes;
	}

	public function marcarInscripcioCursSuperat($idInsc) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["updCertificat"] ) ) {
			$stmt->bind_param("sd", $certificat, $idInsc);
			$certificat = '';
			$stmt->execute();
			$conWeb->closeStmt();
		}
		else
			throw new Exception('',4446);

		$conWeb->desconectarBD();
	}

	public function sendMsgAvisTutorCursNoSuperat($idInsc, $dispo) {
			$conWeb = new ConnexioWeb();
			$conWeb->connectarBD();

			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarInfoMostraInfo"] ) ) {
				$stmt->bind_param("d", $idInsc);
				$stmt->execute();
				$stmt->store_result();
				if ($stmt->num_rows() > 0) {
					$stmt->bind_result($any, $mes, $curs, $aula, $nomActual, $cognomsActual,
					$dniActual, $correuActual,	$telefonActual, $adrecaActual, $cpActual,
					$poblacioActual, $perfilActual, $titulacioActual, $datainsc, $inscrit, $tipusInsc,
					$inscao, $inscmail, $certificat, $obscertificat, $generat, $obs,
					$comentaris, $databaixa, $motiubaixa, $quibaixa, $aPagar, $pagament, $datapag,
					$idpag, $pagObs, $comHaPagat, $entitat, $fraccio, $comFraccio, $factura,
					$datarec, $reclamat, $usuari);
					$stmt->fetch();
				}
				else //no existeix el tutor/a a la taula personal
					throw new Exception('',4439);
			}
			else
				throw new Exception('',4438);

			$conWeb->closeStmt();

			//cns titol, dataFi del curs $any.$curs.$mes
			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarCursSegEd"] ) ) {
				$stmt->bind_param("dss", $any, $mes, $curs);
				$stmt->execute();
				$stmt->store_result();
				if ($stmt->num_rows() > 0) {
					$stmt->bind_result($titol, $datai, $dataf, $hores, $idPreu);
					$stmt->fetch();
				}
				else //no existeix el tutor/a a la taula personal
					throw new Exception('',4441);
			}
			else
				throw new Exception('',4440);

			$conWeb->closeStmt();

			$dateNow = new DateTime("now");
			$dataAct = $dateNow->format('d/m/Y');

			require_once 'Date.php';

			$subject = "Curs pendent de superar. ".$nomActual." ".$cognomsActual.". ".$curs."-".$aula." (".$mes."/".$any.")";
			$subjectPrisMa = "Curs pendent de superar. ".$nomActual." ".$cognomsActual.". ".$curs."-".$aula." (".$mes."/".$any.") ".$dataAct;

			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarDadesPersonalByCurs"] ) ) {
				$stmt->bind_param("dssssd", $any, $mes, $curs, $aula, $perfil, $estatPersonal);
				$perfil = 'tutor';
				$estatPersonal = 1;
				$stmt->execute();
				$stmt->store_result();
				if ($stmt->num_rows() > 0) {
					$stmt->bind_result($dniTutor, $nomTutor, $cogTutor, $correuTutorPrisma, $correuTutorPers);
					require_once "MailSMTPComvive.php";
					while( $stmt->fetch() ) {
						$objDataDispo = new Date($dispo);
						$dataLlargaDispo = $objDataDispo->getDataLlarga();
						$pronomDataLlargaDispo = $objDataDispo->getPronomEl()."<strong>".$dataLlargaDispo."</strong>";

						$mgMail = "<p>Hola ".$nomTutor.",</p>

						<p>Et comuniquem que l'alumne/a <strong>".$nomActual." ".$cognomsActual."</strong>
						no ha superat el curs <strong style='color: ".$this->colors_destacats["msgDestacatCorreu1"]."'>".$titol." - ".$aula."</strong> (".$mes."/".$any.").</p>

						<p>Si encara no ho has fet, hauries de posar-te en contacte amb en/la ".$nomActual." per comunicar-li que:</p>

						<ul style='list-style: square; margin-bottom: 20px; margin-left: 30px; padding: 0;'>
							<li style='margin-top: 8px; line-height: 24px;'>té fins ".$pronomDataLlargaDispo." per acabar-lo. En aquest cas li has de recordar el que li falta per superar el curs.</li>
							<li style='margin-top: 8px; line-height: 24px;'>si li falta molt per acabar el curs, s’hauria de <strong>canviar a una propera edició</strong>.</li>
						</ul>

						<p>Recorda que s’ha de deixar constància a l’<strong>informe</strong> el que li falta per superar el curs i quina és la <span style=\"text-decoration: underline\">teva proposta</span>, i quan et contesti quina és la seva resposta.</p>

						<p>Després caldrà que li facis un seguiment i ens avisis al correu de consultes@prisma.cat quan l'hagi superat. Si ".$pronomDataLlargaDispo." encara consta com a pendent, comunica'ns-ho i ja farem nosaltres el seguiment.</p>

						<p>Moltes gràcies,</p>";

						$authSecre = $this->getAuthSMTP_Consultes();
						$userSecre = $authSecre[0];
						$passSecre = $authSecre[1];
						$nameUserSecre = $authSecre[2];

						require_once 'MailSMTPComvive.php';

						$qui = $this->usuari->getNom()->get()." ".$this->usuari->getCognom()->get();
						$depart = $this->usuari->getDepart()->get();

						$nomFromHead = $nameUserSecre;
						$correuFromHead = $userSecre;

						$nomTo = $nameUserSecre;
						$correuTo = "resguard.secretaria@prisma.cat";
						$nomReplyHead = $nomTutor." ".$cogTutor;
						$correuReplyHead = $correuTutorPrisma;

						$mailSecre = new MailSMTPComvive($userSecre, $passSecre, $nomFromHead, $correuFromHead,
											$nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
											$subjectPrisMa, $mgMail, $qui, $depart);

						$nomTo = $nomTutor." ".$cogTutor;
						$correuTo = $correuTutorPrisma;
						// $correuTo = "meriem.prisma.cat@gmail.com";
						$nomReplyHead = $nameUserSecre;
						$correuReplyHead = $userSecre;

						$mailAlumne = new MailSMTPComvive($userSecre, $passSecre, $nomFromHead, $correuFromHead,
											$nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
											$subject, $mgMail, $qui, $depart);
					}
				}
				else //no existeix el tutor/a a la taula personal
					throw new Exception('',4443);
				$conWeb->closeStmt();
			}
			else
				throw new Exception('',4442);

			$conWeb->desconectarBD();
	}

