	   $llistatHores = "<li class='border-bottom'><a href='#'>Tots</a></li>";

	   $button = "<button id='cercar-cursos' role='button' class='boto-blau px-4 d-flex'>
	      Cerca <i class='material-icons ml-1'>search</i>
	   </button>";

	   $mostrar = "<div id='comunicats' class='card card-blau mt-0'>
