	               ".$this->mostrarSelect('', 'Mes', '', 'mesos-dispo', '', '', '', $mesosDispo)."
	               ".$this->mostrarSelect('', 'Hores', '', 'hores-dispo', '', '', $llistatHores, $horesDispo)."
