	/**
	* @brief Comprova si s'ha enviat el comunicat amb el nom $nameComunicate al curs $idCourseMdl
	* @return Boolean Comprova si s'ha enviat el comunicat amb el nom $nameComunicate al curs $idCourseMdl
	*/
	public function hasBeenSentComunicate($idCourseMdl, $nameComunicate ) {
	   $hasBeen = 0;

	   // Comprova si s'ha enviat el comunicat amb el nom $nameComunicate al curs $idCourseMdl
	   require_once 'ConnexioMoodle.php';
	   $connMdl = new ConnexioMoodle();
	   $connMdl->connectarBD();
	   $connMdl2 = new ConnexioMoodle();
	   $connMdl2->connectarBD();
	   $connMdl3 = new ConnexioMoodle();
	   $connMdl3->connectarBD();

	   //Busco si existeix el idCurs en el moodle nou.
	   if ( $stmt=$connMdl->prepare( $this->consultesBD_Moodle["cnsForum"] ) ) {
	      $stmt->bind_param("ds", $idCourseMdl, $nameComunicate);
	      if ( $stmt2=$connMdl2->prepare( $this->consultesBD_Moodle["cnsForumPost"] ) ) {
	         $stmt2->bind_param("d", $idDiscussions);
	         $stmt->execute();
	         $stmt->store_result();
	         if ( $stmt->num_rows() > 0 ) { //num_Rows
	            $stmt->bind_result($idDiscus);
	            $stmt->fetch();

	            $idDiscussions = $idDiscus;
	            $stmt2->execute();
	            $stmt2->store_result();
	            if ( $stmt2->num_rows() > 0 ) { //num_Rows
	               $stmt2->bind_result($idDiscus);
	               $stmt2->fetch();
	               $hasBeen = 1;
	            }
	            else {
	               // eliminar missatge comunicat
	               if ( $stmt3=$connMdl3->prepare( $this->consultesBD_Moodle["deleteMdlForum"] ) ) {
	                  $stmt3->bind_param("d", $idDiscus);
	                  $stmt3->execute();
	               }
	               else {
	                  throw new Exception('', 4535);
	               }
	            }
	         }
	      }
	      else {
	         throw new Exception('', 4536);
	      }
	   }
	   else {
	      throw new Exception('', 4537);
	   }

	   $connMdl3->desconectarBD();
	   $connMdl2->desconectarBD();
	   $connMdl->desconectarBD();

	   return $hasBeen;
	}

