	/**
	* @brief vista template del comunicat d'obertura d'aules
	* @return String vista template del comunicat d'obertura d'aules
	*/
	public function viewTemplateComunicate_OberturaAules() {
	   // modal per visualitzar el comunicat (plantilla + dades d'aquell curs)
	   require_once 'Template.php';
	   $templates = new Template();
	   $msg = $templates->getTemplate_Comunicat_OberturaAules(0,0);

	   // color class
	   $classLabelCourse = 'labelCourse';

	   // BADGES DE CURSOS
	   $badgeTitol = $this->getBadge($classLabelCourse, "TITOL");
	   $badgeDataI = $this->getBadge($classLabelCourse, "DATA INICI");
	   $badgeEdicioMes = $this->getBadge($classLabelCourse, "EDICIO");
	   $badgeDataSessio1 = $this->getBadge($classLabelCourse, "DATA SESSIO1");
	   $badgeHoraSessio1 = $this->getBadge($classLabelCourse, "HORA SESSIO1");

	   // ACTUALITZAR TOTS ELS CAMPS AMB [] PER UN BADGE
	   $names_template = array("[TITOL]", "[EDICIO_MES]", "[DATAI]",
	   "[DATA_SESSIO1]", "[HORA_SESSIO1]");
	   $names_function   = array($badgeTitol, $badgeEdicioMes, $badgeDataI, $badgeDataSessio1, $badgeHoraSessio1);
	   $missatge = str_replace($names_template, $names_function, $msg);

		$missatge = "<div class='border rounded bg-light p-4 mb-3'>
			".$missatge."
		</div>";

	   return $missatge;
	}

