	/**
   * @brief Mostra els cursos que són de l'any $year, del mes $month i de les hores $hours o tots
   * @return string Mostra els cursos que són de l'any $year, del mes $month i de les hores $hours o tots
   */
   public function viewCourses_Comunicate_OberturaAules($year, $month, $hours, $orderBy, $asc) {
      $table = "";
      $infoTable = "";
      $button = "";
      $resultats = []; $i = 0;

      $titolsInscr[0] = "Any";
      $titolsInscr[1] = "Mes";
      $titolsInscr[2] = "Curs";
      $titolsInscr[3] = "Aula";
      $titolsInscr[4] = "Hores";
      $titolsInscr[5] = "Nom curs";
      $titolsInscr[6] = "Estat";
      $titolsInscr[7] = "Seleccionar";
      $titolsInscr[8] = "Moodle";
      $titolsInscr[9] = "Comunicat";

      $conWeb = new ConnexioWeb();
      $conWeb->connectarBD();

      if ( $hours == 'Tots' ) $cns = "cnsCoursesByYearMonth";
      else $cns = "cnsCoursesByYearMonthHours";

      // consultar tots els cursos de l'any $any, del mes $mes i de les hores $hours o tots
      if ( $stmt=$conWeb->prepare( $this->consultesBD_Web[$cns] ) ) {
			if ( $hours == 'Tots' ) $stmt->bind_param("ds", $year, $month);
	      else $stmt->bind_param("dsd", $year, $month, $hours);

			$stmt->execute();
	      $stmt->bind_result($idCourse, $yearCourse, $monthCourse, $course, $aulaCourse,
	      $title, $hoursCourse, $estat);
         while ( $stmt->fetch() ) {
            $resultats[$i][0] = $idCourse;
            $resultats[$i][1] = $yearCourse;
            $resultats[$i][2] = $monthCourse;
            $resultats[$i][3] = $course;
            $resultats[$i][4] = $aulaCourse;
            $resultats[$i][5] = $title;
            $resultats[$i][6] = $hoursCourse;
            $resultats[$i][7] = $estat;

            $shortname = $idCourse.$aulaCourse;

            $variablesMdl = $this->__getVariablesMdl($shortname);
	         if ( $variablesMdl[0] != null ) {
					$idCourseMdl = explode('-', $variablesMdl[0])[2];
	         	$espaiMdl = explode('-', $variablesMdl[0])[1];
				}
				else {
					$idCourseMdl = 0;
					$espaiMdl = 0;
				}
            $existCourseMdl = $variablesMdl[1];
            $visibleCourseMdl = $variablesMdl[2];

            // BUSCAR LA ID DEL CURS MOODLE CORRESPONENT AL SHORTNAME
            $resultats[$i][8] = $idCourseMdl;
            // Busco si existeix el idCurs en el moodle.
            $resultats[$i][9] = $existCourseMdl;
            // Busco el camp visible i el id del curs del moodle del curs $idCurs
            $resultats[$i][10] = $visibleCourseMdl;

            $resultats[$i][11] = $espaiMdl;

            // SI ESTÀ PENDENT DE COMENÇAR ES MARCA EN VERMELL
            $classAccess = $this->__getColorTrCont_Comunicate($estat);

            // Label d'estat. ACTIU o PENDENT
            $labelEstat = '';
            if ( $estat == 'P' ) $labelEstat = $this->getLabel('', 'lightOrange', 'PENDENT');
            if ( $estat == '0' ) $labelEstat = $this->getLabel('', 'lightRed', 'ANUL·LAT');
            if ( $estat == '1' ) $labelEstat = $this->getLabel('', 'lightGreen', 'ACTIU');
            if ( $estat == 'T' ) $labelEstat = $this->getLabel('', 'lightPurple', 'TANCAT');
            $labelEstatMoodle = $this->obtenirLabelVisibleMoodle($visibleCourseMdl, $existCourseMdl);

            // Label marcar per enviar
            $labelMarcat = $this->__getLabelSendComunicate_OberturaAules($idCourseMdl, $idCourse, $aulaCourse, $estat);

            // Botó per enllaçar el comunicat
				if ( $existCourseMdl == 1 ) {
					$classLabelMDL = "urlCurs w-100";
					$nomLabelMDL = "<span class='material-icons me-1'>link</span>MOODLE";
					$urlMoodle = $this->obtenirBoto('urlCurs-'.$espaiMdl.'-'.$idCourseMdl, $classLabelMDL, $nomLabelMDL);
				}
				else {
					$classLabelMDL = "lightRed";
					$nomLabelMDL = "<span class='material-icons me-1'>link_off</span>MOODLE";
					$urlMoodle = $this->getLabel('urlCurs-'.$espaiMdl.'-'.$idCourseMdl, $classLabelMDL, $nomLabelMDL);
				}

            // Botó per previsualitzar el comunicat
				$buttonPrev = $this->obtenirBoto('prev-'.$idCourse."-".$aulaCourse, 'view-comunicate', "<i class='material-icons text-white me-1'>preview</i> Comunicat");

            // mostrar dades
            $infoTable .= "<tr ".$classAccess.">
               ".$this->mostrarFilaTaulaResponsive($titolsInscr[0], $yearCourse)."
               ".$this->mostrarFilaTaulaResponsive($titolsInscr[1], $monthCourse)."
               ".$this->mostrarFilaTaulaResponsive($titolsInscr[2], $course)."
               ".$this->mostrarFilaTaulaResponsive($titolsInscr[3], $aulaCourse)."
               ".$this->mostrarFilaTaulaResponsive($titolsInscr[4], $hoursCourse)."
               ".$this->mostrarFilaTaulaResponsive($titolsInscr[5], $title)."
               ".$this->mostrarFilaTaulaResponsive($titolsInscr[6], $labelEstat)."
               ".$this->mostrarFilaTaulaResponsive($titolsInscr[7], $labelMarcat)."
               ".$this->mostrarFilaTaulaResponsive($titolsInscr[8], $urlMoodle)."
               ".$this->mostrarFilaTaulaResponsive($titolsInscr[9], $buttonPrev)."
            </tr>";
            $i++;
         }
      }
      else {
         throw new Exception('', 4539);
      }
      $conWeb->desconectarBD();

      $classes = ['', '', ''];

      if ( $orderBy != '' ) {
         if ($orderBy == 'codi') $cntOrderBy = 0;
         else if ($orderBy == 'hores') $cntOrderBy = 1;
         else if ($orderBy == 'title') $cntOrderBy = 2;

         if ($asc == 1) { //s'ordena ascendentment
            $inici = 0;
            $fi = count($resultats);
            $i = $inici;
            $condicio = $i < $fi;

            $classes[$cntOrderBy] = ' asc';
         }
         else { //s'ordena dsscendentment
            $inici = count($resultats);
            $fi = 0;
            $i = $inici-1;
            $condicio = $i >= $fi;

            $classes[$cntOrderBy] = ' desc';
         }
      }

      if ( count($resultats) > 0 ) {
         $table .= "<p class='text-center'>S'han trobat <strong class='badge bg-pris fs-6 mx-1'>".$i."</strong> resultats.</p>";

         $table .= "<table class='table table-striped table-hover table-order table-xl-responsive text-center mt-2 mb-0'>
         <thead><tr>
            <th>".$titolsInscr[0]."</th>
            <th>".$titolsInscr[1]."</th>
            <th id='th-codi' class='sorting".$classes[0]."'>".$titolsInscr[2]."</th>
            <th>".$titolsInscr[3]."</th>
            <th id='th-hores' class='sorting".$classes[1]."'>".$titolsInscr[4]."</th>
            <th id='th-title' class='sorting".$classes[2]."'>".$titolsInscr[5]."</th>
            <th>".$titolsInscr[6]."</th>
            <th>".$titolsInscr[7]."</th>
            <th>".$titolsInscr[8]."</th>
            <th>".$titolsInscr[9]."</th>
         </tr></thead>
         <tbody>";
         if ( $orderBy != '' )
            $infoTable = $this->viewCourses_Comunicate_OberturaAulesOrderBy($titolsInscr, $resultats, $orderBy, $asc);
         $table .= $infoTable;
         $table .= "</tbody></table>";
      }
      else {
         $table = "";
      }
      return $table;

   }

	/**
   * @brief Cream label per enviar el comunicat
   * @return String Cream label per enviar el comunicat.
   * 			 si $estat == 'P', retorna label amb NO
   *			 altrament, consultar si ja està enviat el comunicat.
   * 			 Si està enviat, label enviat i si no, label amb un SI
   */
   public function __getLabelSendComunicate_OberturaAules($idCourseMdl, $idCourse, $aulaCourse, $estat)
	{
		$labelMarcat = '';
		if ( $idCourseMdl != null ) {
		   if ( $estat == 'P') {
		      $nomMarcat = "NO ".$this->obtenirIconaMaterials('', '', 'sentiment_very_dissatisfied', 'No enviar'); // No enviar el comunicat
		      $classMarcat = "lightRed";
		   }
		   else {
		      $nomMarcat = "SÍ ".$this->obtenirIconaMaterials('', '', 'sentiment_very_satisfied', 'Enviar'); // No enviar el comunicat
		      $classMarcat = "marcat lightGreen pointer";
		      // consultar si ja està enviat el comunicat. Sí es així, es marca com a enviat. Si no, es marca per enviar
		      if ( $this->hasBeenSentComunicate($idCourseMdl, "OBERTURA D'AULES") ) {
		         $nomMarcat = 'ENVIAT';
		         $classMarcat = "lightOrange";
		      }
		   }
		}
		else {
			$nomMarcat = 'NO ES POT';
			$classMarcat = "lightRed";
		}
	   $labelMarcat = $this->getLabel('send-'.$idCourse."-".$aulaCourse, $classMarcat.' w-100', $nomMarcat);

	   return $labelMarcat;
   }

	/**
   * @brief Veure els cursos del comunicat d'obertura d'aules
   * @return String Veure els cursos del comunicat d'obertura d'aules amb els titols
   * $titolsInscr, amb els resultats $resultats ordenats per $orderby i en
   * ascendent o descendentment depenedent de $asc
   */
   public function viewCourses_Comunicate_OberturaAulesOrderBy($titolsInscr, $resultats, $orderBy, $asc) {
      function cmpCodi($a, $b) {
          if ($a[3] == $b[3]) {
            if ($a[4] == $b[4]) {
                return 0;
            }
            return ($a[4] < $b[4]) ? -1 : 1;
          }
          return ($a[3] < $b[3]) ? -1 : 1;
      }

      function cmpHores($a, $b) {
          if ($a[6] == $b[6]) {
             if ($a[3] == $b[3]) {
               if ($a[4] == $b[4]) {
                  if ($a[7] == $b[7]) {
                      return 0;
                  }
                  return ($a[7] < $b[7]) ? -1 : 1;
              }
              return ($a[4] < $b[4]) ? -1 : 1;
            }
            return ($a[3] < $b[3]) ? -1 : 1;
          }
          return ($a[6] < $b[6]) ? -1 : 1;
      }

      function cmpTitle($a, $b) {
          if ($a[5] == $b[5]) {
            if ($a[4] == $b[4]) {
               return 0;
            }
            return ($a[4] < $b[4]) ? -1 : 1;
          }
          return ($a[5] < $b[5]) ? -1 : 1;
      }

      $cntOrderBy = 0;
      if ($orderBy == 'codi') { usort($resultats, "cmpCodi"); $cntOrderBy = 0; }
      else if ($orderBy == 'hores') { usort($resultats, "cmpHores"); $cntOrderBy = 1; }
      else if ($orderBy == 'title') { usort($resultats, "cmpTitle"); $cntOrderBy = 2; }

      $classes = ['', '', ''];

      if ( $orderBy != '' ) {

         if ($asc == 1) { //s'ordena ascendentment
            $inici = 0;
            $fi = count($resultats);
            $i = $inici;
            $condicio = $i < $fi;

            $classes[$cntOrderBy] = 'asc';
         }
         else { //s'ordena dsscendentment
            $inici = count($resultats);
            $fi = 0;
            $i = $inici-1;
            $condicio = $i >= $fi;

            $classes[$cntOrderBy] = 'desc';
         }
      }

      $table = '';

      while ( $condicio ) {

         $idCourse = $resultats[$i][0];
         $yearCourse = $resultats[$i][1];
         $monthCourse = $resultats[$i][2];
         $course = $resultats[$i][3];
         $aulaCourse = $resultats[$i][4];
         $title = $resultats[$i][5];
         $hoursCourse = $resultats[$i][6];
         $estat = $resultats[$i][7];

         $shortname = $idCourse.$aulaCourse;

         // BUSCAR LA ID DEL CURS MOODLE CORRESPONENT AL SHORTNAME
         $idCourseMdl = $resultats[$i][8];
         // Busco si existeix el idCurs en el moodle.
         $existCourseMdl = $resultats[$i][9];
         // Busco el camp visible i el id del curs del moodle del curs $idCurs
         $visibleCourseMdl = $resultats[$i][10];

         $espaiMdl = $resultats[$i][11];

         // SI ESTÀ PENDENT DE COMENÇAR ES MARCA EN VERMELL
         $classAccess = $this->__getColorTrCont_Comunicate($estat);

         // Label d'estat. ACTIU o PENDENT
         $labelEstat = '';
         if ( $estat == 'P' ) $labelEstat = $this->obtenirLabel('', 'lightOrange', 'PENDENT');
         if ( $estat == '0' ) $labelEstat = $this->obtenirLabel('', 'lightRed', 'ANUL·LAT');
         if ( $estat == '1' ) $labelEstat = $this->obtenirLabel('', 'lightGreen', 'ACTIU');
         if ( $estat == 'T' ) $labelEstat = $this->obtenirLabel('', 'lightPurple', 'TANCAT');
         $labelEstatMoodle = $this->obtenirLabelVisibleMoodle($visibleCourseMdl, $existCourseMdl);

         // Label marcar per enviar
         $labelMarcat = $this->__getLabelSendComunicate_OberturaAules($idCourseMdl, $idCourse, $aulaCourse, $estat);

         // Botó per enllaçar el comunicat
			if ( $existCourseMdl == 1 ) {
				$classLabelMDL = "urlCurs w-100";
				$nomLabelMDL = "<span class='material-icons me-1'>link</span>MOODLE";
				$urlMoodle = $this->obtenirBoto('urlCurs-'.$espaiMdl.'-'.$idCourseMdl, $classLabelMDL, $nomLabelMDL);
			}
			else {
				$classLabelMDL = "lightRed";
				$nomLabelMDL = "<span class='material-icons me-1'>link_off</span>MOODLE";
				$urlMoodle = $this->obtenirLabel('urlCurs-'.$espaiMdl.'-'.$idCourseMdl, $classLabelMDL, $nomLabelMDL);
			}


         // Botó per previsualitzar el comunicat
			$buttonPrev = $this->obtenirBoto('prev-'.$idCourse."-".$aulaCourse, 'view-comunicate', "<i class='material-icons text-white me-1'>preview</i> Comunicat");


         $table .= "<tr ".$classAccess.">
            ".$this->mostrarFilaTaulaResponsive($titolsInscr[0], $yearCourse)."
            ".$this->mostrarFilaTaulaResponsive($titolsInscr[1], $monthCourse)."
            ".$this->mostrarFilaTaulaResponsive($titolsInscr[2], $course)."
            ".$this->mostrarFilaTaulaResponsive($titolsInscr[3], $aulaCourse)."
            ".$this->mostrarFilaTaulaResponsive($titolsInscr[4], $hoursCourse)."
            ".$this->mostrarFilaTaulaResponsive($titolsInscr[5], $title)."
            ".$this->mostrarFilaTaulaResponsive($titolsInscr[6], $labelEstat)."
            ".$this->mostrarFilaTaulaResponsive($titolsInscr[7], $labelMarcat)."
            ".$this->mostrarFilaTaulaResponsive($titolsInscr[8], $urlMoodle)."
            ".$this->mostrarFilaTaulaResponsive($titolsInscr[9], $buttonPrev)."
         </tr>";

         if ( $asc == 1 ) {
            $i++;
            $condicio = $i < $fi;
         }
         else {
            $i--;
            $condicio = $i >= $fi;
         }
      }
      return $table;
   }

	/**
   * @brief vista del comunicat de a punt de començar del curs
   * @return String vista del comunicat de a punt de començar que té per any $any, mes $mes, curs $curs, aula $aula
   */
	public function getTemplate_Comunicat_OberturaAules($any, $mes, $curs, $aula) {
		// modal per visualitzar el comunicat (plantilla + dades d'aquell curs)
      require_once 'Template.php';
      $templates = new Template();
		$cas1 = 0;
      $cas2 = 0;
		if ( $curs == 'SDA' || $curs == 'SUI' ) $cas1 = 1;
      if ( $curs == 'SDA' || $curs == 'SUI' || $curs == 'GED' ) $cas2 = 1;
		if ( $curs == 'ALBUM' || $curs == 'GUST' ) $cas2 = 2;

		$msg = $templates->getTemplate_Comunicat_OberturaAules( $cas1, $cas2 );

		require_once 'Text.php';
		$objCodiCursMin = new Text($curs);
		$codiCursMin = $objCodiCursMin->setMin();

		// OBTENIR DATAI D'INICI, TITOL
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarInfoCursHono"] ) ) {
			$stmt->bind_param("ss", $idCurs, $aula);
			$idCurs = $any.$curs.$mes;
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($titol, $hores, $datai, $dataf, $diesI, $diesF,
				$gtaf, $cursEscolar, $nomTutor, $cogTutor, $dniTutor);
				$stmt->fetch();
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4579);
		}

		require_once 'Date.php';
		$dataSessio1 = $horaSessio1 = '';
		if ( $cas1 == 1 ) {
			$numSessio = 1;
			/* Cerquem la data de la sessió i la hora de la sessió */
			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["cnsDataSessioMixt"] ) ) {
				$stmt->bind_param("dssd", $any, $mes, $curs, $numSessio);
				$stmt->execute();
				$stmt->store_result();
				if ($stmt->num_rows() > 0) {
					$stmt->bind_result($dataSessio);
					$stmt->fetch();

					$objDataSessio = new Date($dataSessio);
					$dataSessio1 = $objDataSessio->getPronomEl()."<strong>".$objDataSessio->getDataLlarga()."</strong>";
				}
				else {
					$horaSessio1="<strong>17:30 h</strong>";
				}
				$conWeb->closeStmt();
			}
			else {
				throw new Exception('',4580);
			}

			/* Cerquem la data de la sessió i la hora de la sessió */
			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarParamValorOrder"] ) ) {
				$stmt->bind_param("sss", $tipusParam, $valorParam, $orderByPram);
				$tipusParam="horari-sessions-sincrones";
				$valorParam=$any."|".$mes."|".$curs."|"."%";
				$orderByPram='VALOR';
				$stmt->execute();
				$stmt->store_result();
				if ($stmt->num_rows() > 0) {
					$stmt->bind_result($text_horari);
					$stmt->fetch();
					$text_horari=str_replace($any."|".$mes."|".$curs."|",' ',$text_horari);
					$text_horari=str_replace("de <span class='font-weight-bold'>",'',$text_horari);
					$text_horari=str_replace("</span>",'',$text_horari);
					$text_horari=trim($text_horari);
					$text_horari= explode(' ', $text_horari)[0];
					$horaSessio1="<strong>".$text_horari." h</strong>";
				}
				else {
					$horaSessio1="<strong>17:30 h</strong>";
				}
				$conWeb->closeStmt();
			}
			else {
				throw new Exception('',4581);
			}
		}
		$conWeb->desconectarBD();

		$objDataI = new Date($datai);
		$dataI = $objDataI->getPronomEl()."<strong>".$objDataI->getDataLlarga()."</strong>";
		$textMes = $objDataI->getNomMesArticle();

      // ACTUALITZAR TOTS ELS CAMPS AMB [] PER LES DADES DE L'ANY $any, $mes, $curs, $aula
		$names_template = array("[TITOL]", "[EDICIO_MES]", "[DATAI]",
      "[DATA_SESSIO1]", "[HORA_SESSIO1]");
      $names_function   = array($titol, $textMes, $dataI, $dataSessio1, $horaSessio1);
      $missatge = str_replace($names_template, $names_function, $msg);

		return $missatge;
	}

   /**
   * @brief vista del comunicat d'obertura d'aules
   * @return String vista del comunicat d'obertura d'aules
   */
   public function viewComunicate_OberturaAules($idCurs, $aula)
	{
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarDadesEdCursById"] ) ) {
			$stmt->bind_param("s", $idCurs);
			$stmt->execute();
			$stmt->bind_result($any, $mes, $curs, $nomCurs, $datai, $dataf, $hores,
			$cursEsc, $gtaf, $fiss, $dataResol, $dataQual, $dataBloq, $valGtaf,
			$valFiss, $idAula, $estat, $public, $obs);
			$stmt->fetch();
		}
		else {
			throw new Exception('', 4558);
		}
		$conWeb->closeStmt();

      // modal per visualitzar el comunicat (plantilla + dades d'aquell curs)
		$missatge = $this->getTemplate_Comunicat_OberturaAules($any, $mes, $curs, $aula);

		return $missatge;
   }

	/**
	* @brief vista del comunicat d'obertura d'aules
	* @return String vista del comunicat d'obertura d'aules
	*/
	public function insertComunicate_OberturaAules($idCurs, $aula) {
		$message = $this->viewComunicate_OberturaAules($idCurs, $aula);

		$message = str_replace('"', '\"', $message);
		$message = mb_convert_encoding($message, "UTF-8");

		$shortname = $idCurs.$aula;

		$time = time();
		$userId = 1006;
		$subject = "OBERTURA D'AULES";
		$namePost = "COMUNICATS D'AULA";

		require_once 'ConnexioMoodle.php';
      $conMdl = new ConnexioMoodle();
      $conMdl->connectarBD();

		// Busquem el nom i la id del curs del moodle
		if ( $stmt=$conMdl->prepare( $this->consultesBD_Moodle["buscarIdCurs"] ) ) {
			$stmt->bind_param("s", $shortname);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($idCourseMdl);
				$stmt->fetch();
				$conMdl->closeStmt();
				echo " ########################### ID_COURSE: ".$idCourseMdl." ########################### </br>";

				// Busquem el forum de comunicats d'aula del curs del moodle
				if ( $stmt=$conMdl->prepare( $this->consultesBD_Moodle["cnsForumName"] ) ) {
					$stmt->bind_param("ds", $idCourseMdl, $namePost);
					$stmt->execute();
					$stmt->store_result();
					if ($stmt->num_rows() > 0) {
						$stmt->bind_result($idForum);
						$stmt->fetch();
					}
					$conMdl->closeStmt();
				}
				else {
					throw new Exception('', 4567);
				}
				echo " ########################### ID_FORUM: ".$idForum." ########################### </br>";
			}
		}
		else {
			throw new Exception('', 4568);
		}


		// Busquem la id de l'ultim forum_discussion
		if ( $stmt=$conMdl->prepare( $this->consultesBD_Moodle["cnsLastForumDiscus"] ) ) {
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($idDiscussion);
				$stmt->fetch();
				$idDiscussion = intval($idDiscussion)+1;
			}
			else {
				throw new Exception('', 4562);
			}
			$conMdl->closeStmt();
		}
		else {
			throw new Exception('', 4566);
		}
		echo " ########################### ID_DISCUSSIONS: ".$idDiscussion." ########################### </br>";

		// Busquem la id de l'ultim post
		if ( $stmt=$conMdl->prepare( $this->consultesBD_Moodle["cnsLastForumPost"] ) ) {
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($idPost);
				$stmt->fetch();
				$idPost = intval($idPost)+1;
			}
			else {
				throw new Exception('', 4561);
			}
			$conMdl->closeStmt();
		}
		else {
			throw new Exception('', 4565);
		}

		$conMdl2 = new ConnexioMoodle();
		$conMdl2->connectarBD();

		if ( $stmt2=$conMdl2->prepare( $this->consultesBD_Moodle["insertForumPost"] ) ) {
			$stmt2->bind_param("dddddddssdddd", $idPost, $idDiscussion, $parent, $userId, $dateCreate,
				$dateModified, $mailed, $subject, $message, $messageformat, $messagetrust,
				$totalscore, $mailnow);
			$parent = $mailed = $totalscore = $mailnow = 0;
			$messageformat = $messagetrust = 1;
			$dateCreate = $dateModified = $time;

			$stmt2->execute();
			$conMdl2->closeStmt();
		}
		else {
			throw new Exception('', 4564);
		}
		if ( $stmt=$conMdl->prepare( $this->consultesBD_Moodle["insertForumDiscussion"] ) ) {
			$stmt->bind_param("dddsdddddddd", $idDiscussion, $idCourseMdl, $idForum,
			$subject, $idPost, $userId, $groupId, $assessed, $timeModified,
			$userModified, $timeStart, $timeEnd);
			$groupId = $assessed = 1;
			$timeStart = $timeEnd = 0;
			$timeModified = $time;
			$userModified = $userId;
			$stmt->execute();
		}
		else {
			throw new Exception('', 4563);
		}
		$conMdl->closeStmt();
	}

