	/**
	* @brief Mostra els cursos que comencen en una edició ordenats que tinguin un tutor assignat i que no estigui anul·lat
	* @return Mostra els cursos disponibles que comencen en una edició ordenats que
	* 			tinguin un tutor assignat i que no estigui anul·lat a l'edició del mes $mes i de l'any $any ordenats per $oderby i en ascendent segons $asc
	*/
	public function mostrarCursos_Tutors_ConfirmacioTutoritzacio( $any, $mes, $orderBy, $asc ) {
		$mostrar = "mostrarCursos_Tutors_ConfirmacioTutoritzacio <br />
		".$any." ".$mes." ".$orderBy." ".$asc;

		if ($orderBy != 'codi' && $orderBy!='titol')
			$orderBy = 'codi';
		if ($asc!=1 and $asc!=0)
			$asc = 1;

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();
		$conWeb2 = new ConnexioWeb();
		$conWeb2->connectarBD();

		$i=0;

		/* Buscar tots els cursos que estan pendents d'assignar un tutor de l'any $any i del mes $mes.*/
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["cnsCursosConfTut"] ) ) {
			$stmt->bind_param("dsd", $any, $mes, $idCuhoSearch);
			$idCuhoSearch = 17;
			$stmt->execute();
			$stmt->store_result();
			if ( $stmt->num_rows() > 0 ) {
				$stmt->bind_result($titolCurs, $idCurs, $codiCurs, $idAula, $aula, $idCuho, $confirmat, $nomTutor, $cogTutor, $idImg);
				while ( $stmt->fetch() ) {
					$resultats[$i][0] = $titolCurs;
					$resultats[$i][1] = $codiCurs;
					$resultats[$i][2] = $aula;
					$resultats[$i][3] = $idCurs;
					$resultats[$i][4] = $idAula;
					$resultats[$i][5] = $idCuho;
					$resultats[$i][6] = $confirmat;
					$resultats[$i][7] = $nomTutor;
					$resultats[$i][8] = $cogTutor;
					$resultats[$i][9] = $idImg;
					$i++;
				}
			}
			else {
				$resultats = [];
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('', 4406);
		}

		$conWeb2->desconectarBD();

		if ( count($resultats) > 0 ) {
			function cmpCodi($a, $b) {
			    if ($a[1] == $b[1]) {
					 if ($a[2] == $b[2]) {
						 return 0;
				   }
				   return ($a[2] < $b[2]) ? -1 : 1;
			    }
			    return ($a[1] < $b[1]) ? -1 : 1;
			}

			function cmpTitol($a, $b) {
			    if ($a[0] == $b[0]) {
					 if ($a[2] == $b[2]) {
						 return 0;
				   }
				   return ($a[2] < $b[2]) ? -1 : 1;
			    }
			    return ($a[0] < $b[0]) ? -1 : 1;
			}

			function cmpTutor($a, $b) {
			    if ($a[7] == $b[7]) {
					 if ($a[8] == $b[8]) {
						 if ($a[0] == $b[0]) {
							 return 0;
					   }
					   return ($a[0] < $b[0]) ? -1 : 1;
				    }
				    return ($a[8] < $b[8]) ? -1 : 1;
			    }
			    return ($a[7] < $b[7]) ? -1 : 1;
			}

			if ($orderBy == 'codi') usort($resultats, "cmpCodi");
			else if ($orderBy == 'titol') usort($resultats, "cmpTitol");
			else if ($orderBy == 'tutor') usort($resultats, "cmpTutor");

			$classCurs = '';
			$classTitol = '';
			$classTutor = '';

			if ($asc == 1) { //s'ordena ascendentment
				$inici = 0;
				$fi = count($resultats);
				$i = $inici;
				$condicio = $i < $fi;

				if ($orderBy == 'codi') $classCurs = ' asc';
				else if ($orderBy == 'titol') $classTitol = ' asc';
				else if ($orderBy == 'tutor') $classTutor = ' asc';
			}
			else { //s'ordena dsscendentment
				$inici = count($resultats);
				$fi = 0;
				$i = $inici-1;
				$condicio = $i >= $fi;

				if ($orderBy == 'codi') $classCurs = ' desc';
				else if ($orderBy == 'titol') $classTitol = ' desc';
				else if ($orderBy == 'tutor') $classTutor = ' desc';
			}

			//Mostra usuaris en format d'una taula ordenats per dni;
			$table = "<table class='table table-striped table-hover table-order text-center'>
			<thead>
				<tr>
					<th id='th-titol' class='sorting".$classTitol."'>TÍTOL</th>
					<th id='th-codi' class='sorting".$classCurs."'>CURS</th>
					<th>AULA</th>
					<th id='th-tutor' class='sorting".$classTutor."'>TUTOR/A ASSIGNAT</th>
					<th>CONFIRMACIÓ</th>
				</tr>
			</thead>
			<tbody>";

			while ( $condicio ) {
				$titolCurs = $resultats[$i][0];
				$codiCurs = $resultats[$i][1];
				$aula = $resultats[$i][2];
				$idCurs = $resultats[$i][3];
				$idAula = $resultats[$i][4];
				$idCuho = $resultats[$i][5];
				$confirmat = $resultats[$i][6];
				$nomTutor = $resultats[$i][7];
				$cogTutor = $resultats[$i][8];
				$nomCogTutor = $nomTutor." ".$cogTutor;
				$idImg = $resultats[$i][9];

				if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["cnsImatgeWebVersById"] ) ) {
					$stmt->bind_param("d", $idImg);
					$stmt->execute();
					$stmt->store_result();
					if ( $stmt->num_rows() > 0 ) {
						$stmt->bind_result($altImg, $linkImg, $versio);
						$stmt->fetch();
					}
					$conWeb->closeStmt();
				}
				else {
					throw new Exception('', 4407);
				}

				$urlImg = "https://www.prisma.cat".$linkImg."?ver=".$versio;

				$divImgTutor = "<div class='tutor-overlay mt-0'>
					<img role='img' class='w-100' src='".$urlImg."' alt='".$nomCogTutor."'>
				</div>";
				$divNameTutor = "<div class='ml-lg-3 text-tutor mt-0'>".$nomCogTutor."</div>";

				$divTutorAssignat = "<div class='d-flex flex-column flex-lg-row justify-content-center align-items-center px-2'>".$divImgTutor.$divNameTutor."</div>";

				$botoConfirmarTutor = "<div class='d-flex flex-column justify-content-center align-items-center my-2'>
				<button id='confirma-".$idCurs."-".$aula."' role='button' class='confirma-tutor boto-blau px-4 d-flex'>
					Confirma
				</button></div>";

				$labelConfirmarTutor = "<div class='d-flex flex-column justify-content-center align-items-center my-2'>
				".$this->obtenirLabel('', 'lightGreen', 'Confirmat')."</div>";

				if ( $confirmat == 1 ) {
					$confirmacio = $labelConfirmarTutor;
				}
				else {
					$confirmacio = $botoConfirmarTutor;
				}

				$table .= "<tr>";

				$table .= "
					<td>".$titolCurs."</td>
					<td id='codiCurs-".$idCurs."-".$aula."'>".$codiCurs."</td>
					<td>".$aula."</td>
					<td>".$divTutorAssignat."</td>
					<td>".$confirmacio."</td>
					<td id='idAula-".$idCurs."-".$aula."' class='d-none'>".$idAula."</td>
				</tr>";

				if ( $asc == 1 ) {
					$i++;
					$condicio = $i < $fi;
				}
				else {
					$i--;
					$condicio = $i >= $fi;
				}
			}

			$conWeb->desconectarBD();
			$table .= "</tbody></table>";
		}
		else {
			$table = "<p class='text-center'>No hi ha resultats.</p>";
		}

		$mostrar = "<div class='d-flex flex-column justify-content-center align-items-center
				w-100 text-center border-bottom card-header'>
				<p class='title font-weight-bold text-center py-3 mb-0 align-items-center
				justify-content-center d-flex'>CONFIRMA ELS TUTORS QUE PORTARAN EL CURS</p>
			</div>
			<div class='card-body px-0'>
				<p>Resultats de la cerca del <strong> ".$mes."/".$any."</strong>:</p>
				".$table."
			</div>";

		return $mostrar;
	}

	/**
	* @brief Actualitza la confirmació del tutor a 1
	* @return Actualitza la confirmació del tutor a 1 del curs amb codi cursc$codiCurs a l'edició del mes $mes i de l'any $any ordenats per $oderby i en ascendent segons $asc
	*/
	public function updCursos_Tutors_ConfirmacioTutoritzacio( $any, $mes, $codiCurs, $aula ) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["updCursosSetConf"] ) ) {
			$stmt->bind_param("ds", $confirmat, $idCurs);
			$confirmat = 1;
			$idCurs = $any.$codiCurs.$mes.$aula;
			$stmt->execute();
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('', 4408);
		}
		echo $this->consultesBD_Web["updCursosSetConf"]."<br />";
		echo $confirmat."<br />";
		echo $idCurs."<br />";

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["cnsIdAula"] ) ) {
			$stmt->bind_param("s", $idCursSenseAula);
			$idCursSenseAula = $any.$codiCurs.$mes;
			$stmt->execute();
			$stmt->bind_result($idAula);
			$stmt->fetch();
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('', 4409);
		}
		echo $this->consultesBD_Web["cnsIdAula"]."<br />";
		echo $idCursSenseAula."<br />";
		echo $idAula."<br />";

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["updAulaSetConf"] ) ) {
			$stmt->bind_param("dds",  $confirmat, $idAula, $aula);
			$stmt->execute();
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('', 4410);
		}
		echo $this->consultesBD_Web["updAulaSetConf"]."<br />";
		echo $confirmat."<br />";
		echo $idAula."<br />";
		echo $aula."<br />";

		$conWeb->desconectarBD();

		$mostrar = "";

		echo $mostrar;
	}

