	/**
	* @brief Mostra la info del perfil
	* @return Mostra la info del perfil
	*/
	public function __mostrarPage_Perfil_MostrarPerfil() {

		// /* Buscar dades IMG_PERFIL de l'usuari */
		$usuariPerfil = $this->usuari->getUsuari()->get();

		$conIntra = new ConnexioIntranet();
		$conIntra->connectarBD();

		/* ##### Busquem les despeses corresponents a les hores del curs ##### */
		/* Les despeses de gestió es calculen segons el nombre d'hores del curs anterior
		ja que representa que és el que li has pagat el tutor/a */
		if ( $stmt=$conIntra->prepare( $this->consultesBD_Intra["cnsInfoUsuari"] ) ) {
			$stmt->bind_param("s", $usuariPerfil);
			$stmt->execute();
			$stmt->bind_result($rolsPerfil, $nomPerfil, $cogPerfil, $imgPerfil, $deptPerfil);
			$stmt->fetch();
			$conIntra->closeStmt();
		}
		else
			throw new Exception('',4401);

		$conIntra->desconectarBD();

		/* Buscar la url de la imatge del perfil amb usuari $usuariPerfil*/

		$cntImgPerfil = "<div class='d-flex flex-column justify-content-center align-items-center w-100 mb-2'>
			<img src='".$imgPerfil."' class='w-100 img-profile'>
			<button id='change-password-".$usuariPerfil."' role='button' class='change-pass boto-blau px-4 d-flex mt-2'>
				Canvi de contrassenya<i class='material-icons ml-2'>vpn_key</i>
	 		</button>
		</div>";

		/* Preparar el label dels rols */
		$labelRolsPerfil = "";

		$conIntra = new ConnexioIntranet();
		$conIntra->connectarBD();

		$arrRolsPerfil = explode('|', $rolsPerfil);
		if ( $stmt=$conIntra->prepare( $this->consultesBD_Intra["cnsNomRol"] ) ) {
			$stmt->bind_param("d", $idRol);
			for ( $i=0; $i < count($arrRolsPerfil); $i++ ) {
				$idRol = $arrRolsPerfil[$i];
				$stmt->execute();
				$stmt->bind_result($nomRol);
				$stmt->fetch();

				$labelRolsPerfil .= $this->obtenirLabel('', 'rols rol-'.$idRol, $nomRol);
			}
		}
		else
			throw new Exception('',4399);

		$conIntra->closeStmt();
		$conIntra->desconectarBD();

		$cntDadesPerfil = "<div class='d-flex flex-column justify-content-center align-items-center w-100 mb-2'>
			<div class='apartat d-flex flex-column flex-md-row align-items-center justify-content-center w-100 my-2'>
				<div class='d-flex flex-column align-items-center justify-content-center w-100'>
					<p class='titol-apartat d-flex font-weight-bold mt-3'>DADES DE L'USUARI</p>
