	/**
	* @brief Retorna error si $passAct no coincideix amb la contrassenya actual de l'usuari
	* 			o si la contrassenya nova no té 8 dígits, una majúscula, una míniscula
	*			i un caràcter especial
	* @return Retorna l'error "La contraseenyaa introduïda no coincideix amb la contrassenya de l'usuari"
	*			si $passAct no coincideix amb la contrassenya actual de l'usuari.
	*			Retorn l'error "La contrassenya nova ha de tenir com a mínim 8 dígits!"
	* 			si la contrassenya nova $passNew no té 8 dígits
	*			Retorn l'error "La contrassenya nova ha de tenir com a mínim un majúcula!"
	* 			si la contrassenya nova $passNew no té una majúscula
	*			Retorn l'error "La contrassenya nova ha de tenir com a mínim un míniscula!"
	* 			si la contrassenya nova $passNew no té una míniscula
	*			Retorn l'error "La contrassenya nova ha de tenir com a mínim un caràcter especial!"
	* 			si la contrassenya nova $passNew no té un caràcter especial
	*			Retorn l'error "La contrassenya nova no coincideix amb la confirmació de la contrassenya nova "
	* 			si la contrassenya nova $passNew i la confirmació $passConfNew no son iguals
	*/
	public function comprovarContrassenyes_Perfil_MostrarPerfil($passAct, $passNew, $passConfNew)  {
		/* Recupero passHashUser de l'usuari */
		$passHashUser = $this->usuari->getHashPass()->get();

		/* Recupero clau per encriptar */
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarParam"] ) ) {
			$stmt->bind_param("s", $tipus);
			$tipus = "keyEncriptar";
			$stmt->execute();
			$stmt->bind_result($keyEncr);
			$stmt->fetch();
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4025);
		}

		$conWeb->desconectarBD();

		$c = base64_decode($passHashUser);
		$cipher="AES-128-CBC";
		$ivlen = openssl_cipher_iv_length($cipher);
		$iv = substr($c, 0, $ivlen);
		$hmac = substr($c, $ivlen, $sha2len=32);
		$ciphertext_raw = substr($c, $ivlen+$sha2len);
		$originalPass = openssl_decrypt($ciphertext_raw, $cipher, $keyEncr, $options=OPENSSL_RAW_DATA, $iv);

		if ( $originalPass != $passAct ) {
			$msgErrors .= "<span>La contrassenya introduïda no coincideix amb la contrassenya de l'usuari!</span>";
		}

		//l'error "La contrassenya nova ha de tenir com a mínim un míniscula!"
		if ( preg_match('/[a-z]/', $passNew) != 1 ) {
			$msgErrors .= "<span>La contrassenya nova ha de tenir com a mínim un míniscula!</span>";
		}

		//l'error "La contrassenya nova ha de tenir com a mínim un majúcula!"
		if ( preg_match('/[A-Z]/', $passNew) != 1 ) {
			$msgErrors .= "<span>La contrassenya nova ha de tenir com a mínim una majúcula!</span>";
		}

		//l'error "La contrassenya nova ha de tenir com a mínim un nombre!"
		if ( preg_match('/\d/', $passNew) != 1 ) {
			$msgErrors .= "<span>La contrassenya nova ha de tenir com a mínim un nombre!</span>";
		}

		//l'error "La contrassenya nova ha de tenir com a mínim un caràcter especial!"
		if ( preg_match('/[^a-zA-Z\d]/', $passNew) != 1 ) {
			$msgErrors .= "<span>La contrassenya nova ha de tenir com a mínim un caràcter especial!</span>";
		}

		//l'error "La contrassenya nova ha de tenir com a mínim 8 dígits!"
		if ( strlen($passNew) < 8 ) {
			$msgErrors .= "<span>La contrassenya nova ha de tenir com a mínim 8 dígits!</span>";
		}

		//l'error "La contrassenya nova no coincideix amb la confirmació de la contrassenya nova"
		if ( $passNew != $passConfNew ) {
			$msgErrors .= "<span>La contrassenya nova no coincideix amb la confirmació de la contrassenya nova!</span>";
		}

		$alertes = '';
		if ( $msgErrors != '' ) {
			$alertes = "<div class='alert alert-danger alert-with-icon w-100 mb-2'>
				<i class='material-icons' data-notify='icon'>notifications</i>
				<button type='button' data-dismiss='alert' aria-label='Close' class='close'>
				<i class='material-icons'>close</i></button>".$msgErrors."
			</div>";
		}

		return $alertes;
	}

	/**
	* @brief Actualitza la contrassenya de l'usuari
	* @return Actualitza la contrassenya de l'usuari
	*/
	public function actualitzaContrassenya_Perfil_MostrarPerfil($passNew)  {
		/* Recupero clau per encriptar */
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarParam"] ) ) {
			$stmt->bind_param("s", $tipus);
			$tipus = "keyEncriptar";
			$stmt->execute();
			$stmt->bind_result($keyEncr);
			$stmt->fetch();
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4025);
		}

		$conWeb->desconectarBD();

		$cipher = "AES-128-CBC";
		$ivlen = openssl_cipher_iv_length($cipher);
		$iv = openssl_random_pseudo_bytes($ivlen);
		$ciphertext_raw = openssl_encrypt($passNew, $cipher, $keyEncr, $options=OPENSSL_RAW_DATA, $iv);
		$hmac = hash_hmac('sha256', $ciphertext_raw, $keyEncr, $as_binary=true);
		$hashPassNew = base64_encode( $iv.$hmac.$ciphertext_raw);

		$usuariPerfil = $this->usuari->getUsuari()->get();

		/* upd rols haspassnew */
		$conIntra = new ConnexioIntranet();
		$conIntra->connectarBD();

		if ( $stmt=$conIntra->prepare( $this->consultesBD_Intra["updHashPass"] ) ) {
			$stmt->bind_param("ss", $hashPassNew, $usuariPerfil);
			$stmt->execute();
			$conIntra->closeStmt();
		}
		else
			throw new Exception('',4400);

		$conIntra->desconectarBD();

		return "ok";
	}


