		$conWeb2 = new ConnexioWeb();
		$conWeb2->connectarBD();

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["obtLastDateTrobada"] ) ) {
			$stmt->execute();
			$stmt->bind_result($dataInici);
			$stmt->fetch();

			$dataI = new DateTime($dataInici);
			$lastYear = $dataI->format('Y');
		}
		$conWeb->closeStmt();

		/* Preparo una taula tableTrobadesAnyActual amb totes les trobades de l'any XXX */
		$tableTrobadesAnyActual = "";
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["obtTrobadesAnyActual"] ) ) {
			$stmt->bind_param("s", $year);
			$year = "%".$lastYear."%";
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($id, $titol, $dataI, $enviat);

				$i = 0;

				$tableTrobadesAnyActual = "<div class='d-flex flex-column flex-sm-row align-items-center justify-content-center w-100'>
				<table class='table table-hover table-striped table-hover text-center'>
					<thead>
						<tr>
						<th style='width: 5%'>ID</th>
						<th style='width: 60%'>TÍTOL</th>
						<th style='width: 20%'>DATA</th>
						<th style='width: 10%'>NÚM. INSCRITS</th>
						<th style='width: 5%'>ACCIÓ</th>
						</tr>
					</thead>
					<tbody>";

				while ( $stmt->fetch() ) {
					// $dataInici = date_format($dataI, 'd/m/Y H:i:s');
					$date = new Date($dataI);
					$dataInici = $date->getDataFomatDDMMYYYY_HHMMSS();
					// $dataInici = $dataI;

					$inscrits = 0;

					//Busco el nombre d'inscrits al mailing de trobades de la trobada id
					if ( $stmt2=$conWeb2->prepare( $this->consultesBD_Web["obtInscTrob"] ) ) {
						$stmt2->bind_param("d", $id);
						$stmt2->execute();
						$stmt2->store_result();
						$inscrits = $stmt2->num_rows();
					}
					$conWeb2->closeStmt();

					if ( $enviat == 0 && $inscrits > 0 ) {
						$accio = "<i id='avis-trobada-".$id."' class='material-icons avis-trobada p-2'
							title=\"Envia l'avís a tots els inscrits de la trobada \">send</i>";
					}
					else if ( $enviat == 0 && $inscrits == 0 ) {
						$accio = "Cap";
					}
					else {
						$accio = "Enviat";
					}

					$tableTrobadesAnyActual .= "<tr>
						<td>".$id."</td>
						<td>".$titol."</td>
						<td>".$dataInici."</td>
						<td>".$inscrits."</td>
						<td>".$accio."</td>
					</tr>";
				}
				$tableTrobadesAnyActual .= "</tbody></table></div>";
			}
		}
		$conWeb->closeStmt();


		/* Preparo una taula tableTrobadesAnysAnt amb totes les trobades anteriors a l'any XXX */
		$tableTrobadesAnysAnt = "";

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["obtTrobadesAnysAnt"] ) ) {
			$stmt->bind_param("s", $year);
			$year = "%".$lastYear."%";
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($id, $titol, $enviat);

				$i = 0;

				$tableTrobadesAnysAnt = "<div class='d-flex flex-column flex-sm-row align-items-center justify-content-center w-100'>
				<table class='table table-hover table-striped table-hover text-center'>
					<thead>
						<tr>
						<th style='width: 5%'>ID</th>
						<th style='width: 70%'>TÍTOL</th>
						<th style='width: 10%'>NÚM. INSCRITS</th>
						<th style='width: 15%'>ACCIÓ</th>
						</tr>
					</thead>
					<tbody>";

				while ( $stmt->fetch() ) {
					$inscrits = 0;

					//Busco el nombre d'inscrits al mailing de trobades de la trobada id
					if ( $stmt2=$conWeb2->prepare( $this->consultesBD_Web["obtInscTrob"] ) ) {
						$stmt2->bind_param("d", $id);
						$stmt2->execute();
						$stmt2->store_result();
						$inscrits = $stmt2->num_rows();
					}
					$conWeb2->closeStmt();

					if ( $enviat == 0 && $inscrits > 0 ) {
						$accio = "No enviat";
					}
					else if ( $enviat == 0 && $inscrits == 0 ) {
						$accio = "Cap";
					}
					else {
						$accio = "Enviat";
					}

					$tableTrobadesAnysAnt .= "<tr>
						<td>".$id."</td>
						<td>".$titol."</td>
						<td>".$inscrits."</td>
						<td>".$accio."</td>
					</tr>";
				}
				$tableTrobadesAnysAnt .= "</tbody></table></div>";
			}
		}
		$conWeb->closeStmt();

		$conWeb->desconectarBD();
		$conWeb2->desconectarBD();

		$mostrar = "<div id='trobades-linia' class='card card-blau'>
