				$stmt2->bind_param("s", $codi);
				if ( $stmt3=$conWeb3->prepare( $this->consultesBD_Web["cnsImatgeWebById"] ) ) {
					$stmt3->bind_param("d", $idImg);

					$stmt->execute();
					$stmt->bind_result($codiCurs, $idImgLarge, $idImgSmall, $idImgPerfil);
					while ( $stmt->fetch() && !$existeix ) {
						$codi = $codiCurs;
						$stmt2->execute();
						$stmt2->bind_result($dataiPrimeraEdicio);
						$stmt2->fetch();
						if ( $dataiPrimeraEdicio!= null ) {
							$date1 = new DateTime("now");
							$date2 = new DateTime($dataiPrimeraEdicio);
							$diff = $date1->diff($date2);

							if ( $diff->invert == 0) {
								$existeix = 1;
							}
						}
					}
				}
				else {
					throw new Exception('',4331);
				}
				$conWeb3->closeStmt();

			}
			else {
				throw new Exception('',4332);
			}
			$conWeb2->closeStmt();
		}
		else {
			throw new Exception('',4333);
		}
		$conWeb->closeStmt();

		$conWeb3->desconectarBD();
		$conWeb2->desconectarBD();
		$conWeb->desconectarBD();

		$button = $existeix == 1 ? $button = "<p>Hi han imatges que no existeixen.</p>
		<button id='cns-imatges-".$idApartatFuncio."'
		class='cns-imatges-cursos-nous boto-blau mt-2 px-4 d-flex'>Consulta imatges</button>" : "<p class='text-center'>Totes les imatges existeixen.</p>";

		return $button;
	}

