						$connexioMdlUser->closeStmt();

					}

					if ( $cursCns == 'TUT' ) {
						echo "---------------<br>";
						print_r($usuarisBD);
						echo "---------------<br>";
						print_r($usuarisMdl);
						$resultDiffArray = array_diff( $usuarisMdl, $usuarisBD );
						print_r($resultDiffArray);
					}

					// Trobem el nombre d'alumnes màxim
					if ( $numUsuarisBD < $numUsuarisMdl )
						$numUsuarisMax = $numUsuarisMdl;
					else
						$numUsuarisMax = $numUsuarisBD;

					$resultDiffArray = array_diff( $usuarisMdl, $usuarisBD );
					if ( count($resultDiffArray) > 0 ) {
						echo $cursCns."<br>";
						print_r($resultDiffArray);
						echo "---------------<br>";
					}

					foreach ($resultDiffArray as $clau => $valor) {
						if ( $valor == $usuarisMdl[$clau] ) {
							$errorsCampusAO[$i] = [$cursCns, 1, $usuarisMdl[$clau], $usuarisCorreuMdl[$usuarisMdl[$clau]]];
						}
						if ( $valor == $usuarisBD[$clau] ) {
							$errorsCampusAO[$i] = [$cursCns, 0, $usuarisBD[$clau], $usuarisCorreuBD[$usuarisBD[$clau]]];
						}
						$i++;
					}
				}

				$conWebUser->desconectarBD();
				$connexioMdlUser->desconectarBD();

				$conWeb->closeStmt();

		}
		else {
			throw new Exception('', xxx);
		}

		$conWeb->desconectarBD();

		/* ######### PREPAREM LA REPRESENTACIÓ DE LES DADES DEL CAMPUS ######### */

		$tableAlumnes = ''; $contingutCns = '';
		$shortnameAnt = '';
		for ( $cnt = 0; $cnt < count($errorsCampus); $cnt++ ) {

			$anyError = $errorsCampus[$cnt][0];
			$mesError = $errorsCampus[$cnt][1];
			$cursError = $errorsCampus[$cnt][2];
			$aulaError = $errorsCampus[$cnt][3];
			$typeError = $errorsCampus[$cnt][4];
			$usuariError = $errorsCampus[$cnt][5];
			$correuError = $errorsCampus[$cnt][6];

			$shortname = $anyError.$cursError.$mesError.$aulaError;
			if ( $cnt == 0 || $shortname != $shortnameAnt ) {
				if ( $tableAlumnes != '' ) {
					$tableAlumnes .= "</tbody></table>";
				}
				$tableAlumnes .= "
	 				<p class='titol-curs text-blue text-center'><strong>".$shortname."</strong></p>
					<table class='table table-striped table-hover table-order text-center cnt-curs-superat'>
					<thead>
						<tr>
							<th>CURS</th>
							<th>MES</th>
							<th>AULA</th>
							<th>USUARI</th>
							<th>CORREU CAMPUS</th>
							<th>CORREU BD</th>
						</tr>
					</thead>
				<tbody>";
			}

			$correuCampus = $correuBD = '';
			if ( $typeError == 0 ) $correuBD = $correuError;
			if ( $typeError == 1 ) $correuCampus = $correuError;

			$btnCnsInfoAlumne = '';

			$tableAlumnes .= "<tr>
				<td>".$cursError."</td>
				<td>".$mesError."</td>
				<td>".$aulaError."</td>
				<td>".$usuariError."</td>
				<td>".$correuCampus."</td>
				<td>".$correuBD."</td>
			</tr>";

			if ( $cnt == count($errorsCampus) - 1  ) {
				$tableAlumnes .= "</tbody></table>";
			}

			$shortnameAnt = $shortname;
		}

		/* ######### PREPAREM LA REPRESENTACIÓ DE LES DADES DEL AO  ######### */
		$tableAlumnesAO = '';
		$shortnameAntAO = '';
		for ( $cnt = 0; $cnt < count($errorsCampusAO); $cnt++ ) {

			$cursError = $errorsCampusAO[$cnt][0];
			$typeError = $errorsCampusAO[$cnt][1];
			$usuariError = $errorsCampusAO[$cnt][2];
			$correuError = $errorsCampusAO[$cnt][3];

			$shortname = $cursError;
			if ( $cnt == 0 || $shortname != $shortnameAntAO ) {
				if ( $tableAlumnesAO != '' ) {
					$tableAlumnesAO .= "</tbody></table>";
				}
				$tableAlumnesAO .= "
	 				<p class='titol-curs text-blue text-center'><strong>".$shortname."</strong></p>
					<table class='table table-striped table-hover table-order text-center cnt-curs-superat'>
					<thead>
						<tr>
							<th>CURS</th>
							<th>USUARI</th>
							<th>CORREU CAMPUS</th>
							<th>CORREU BD</th>
						</tr>
					</thead>
				<tbody>";
			}

			$correuCampus = $correuBD = '';
			if ( $typeError == 0 ) $correuBD = $correuError;
			if ( $typeError == 1 ) $correuCampus = $correuError;

			$btnCnsInfoAlumne = '';

			$tableAlumnesAO .= "<tr>
				<td>".$cursError."</td>
				<td>".$usuariError."</td>
				<td>".$correuCampus."</td>
				<td>".$correuBD."</td>
			</tr>";

			if ( $cnt == count($errorsCampusAO) - 1 ) {
				$tableAlumnesAO .= "</tbody></table>";
			}

			$shortnameAntAO = $shortname;
		}

		/* ############# ALUMNES CURSOS CAMPUS ############# */
		if ( count($errorsCampus) > 0 ) {
			$contingutCns .= $tableAlumnes;
		}
		else {
			$contingutCns .= "<p class='text-center'>
				No hi ha cap alumne/a a la BD que no estigui en el Campus.
			</p>";
		}

		/* ############# ALUMNES AO CAMPUS ############# */
		if ( count($errorsCampusAO) > 0 ) {
			$contingutAO = $tableAlumnesAO;
		}
		else {
			$contingutAO = "<p class='text-center'>
				No hi ha cap alumne/a a la BD que no estigui en el Campus.
			</p>";
		}

		$contingut .= "</div>";

		$mostrar = "
		<div class='d-flex flex-column justify-content-center align-items-center
			w-100 text-center border-bottom card-header'>
			<p class='title font-weight-bold text-center py-3 mb-0 align-items-center
			justify-content-center d-flex'>COMPROVACIÓ DELS ALUMNES ENTRE EL CAMPUS I LA BD</p>
		</div>
		<div class='card-body px-0'>
			<p class='titol-campus text-blue text-center'>
				<strong>Comprovació als cursos</strong>
			</p>
			<div  class='d-flex flex-column justify-content-center align-items-center w-100 text-center'>
				".$contingutCns."
			</div>

			<p class='titol-campus text-blue text-center'>
				<strong>Comprovació a les aules obertes</strong>
			</p>
			<div  class='d-flex flex-column justify-content-center align-items-center w-100 text-center'>
				".$contingutAO."
			</div>
		</div>";

		return $mostrar;

		// <div  class='d-flex flex-column justify-content-center align-items-center w-100 text-center'>
		// <p class='titol-campus text-blue text-center'>
		// 	<strong>Comprovació a les aules obertes</strong>
		// </p>
		// <div  class='d-flex flex-column justify-content-center align-items-center w-100 text-center'>
		// 	".$contingutAO."
		// </div>
		// </div>
	}

	private function mostrarTable_Dades_ComprovacioNombreAlumnes($any, $mes, $codiCurs) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		/*
		Busco totes les inscripcions que hi han de l'any, el mes i les hores cercades,
		el curs actual, que estiguin inscrits, on CERTIFICAT es NUULL i
		correu_curs_superat = 0
		*/
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["cnsInfoDifAlumnesCampusBD"] ) ) {
			$stmt->bind_param("dss",  $any, $mes, $codiCurs);
			$stmt->execute();
			$stmt->store_result();
			if ( $stmt->num_rows() > 0 ) {
				$tableAlumnes = "<table class='table table-striped table-hover table-order text-center cnt-curs-superat'>
					<thead>
						<tr>
							<th>GRUP</th>
							<th>MES</th>
							<th>USUARI/th>
							<th>CORREU CAMPUS</th>
							<th>CORREU BD</th>
							<th>BOTONS</th>
						</tr>
					</thead>
				<tbody>";
				// $stmt->bind_result($id, $grup, $obs, $obsCert, $certificat, $nom,
				// $cognoms, $correu, $adreca, $cp, $poblacio, $usuari, $tipusI,
				// $aPagar, $pagament, $idPag, $entitat);
				while ( $stmt->fetch() ) {
					$tableAlumnes .= "<tr>
						<td>".$grup."</td>
						<td>".$mes."</td>
						<td>".$usuari."</td>
						<td>".$correuCampus."</td>
						<td>".$correuBD." €</td>
						<td>".$btnCnsInfoAlumne."</td>
					</tr>";
				}
				$tableAlumnes .= "</tbody></table>";
			}
			else {
				//No existeixen cursos pendents:
				$tableAlumnes = "<p class='text-center'>No existeix cap alumne que estigui a la BD i no en el Campus.</p>";
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('', xxx);
		}
		$conWeb->desconectarBD();

		return $tableAlumnes;
	}

