	private function __mostrarPage_Inici_Facturacio_Comprovar_Duplicats_IdPags($idFuncio, $idApartatFuncio) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["cnsDuplicateIdPag"] ) ) {
			$stmt->execute();
			$stmt->store_result();
			if ( $stmt->num_rows() > 0 ) {
				$button = "<p>Hi han IDPAGs duplicats.</p>
				<button id='duplicate-idpag-".$idApartatFuncio."' class='duplicats-idpag boto-blau mt-2 px-4 d-flex'>Consulta els IDPAGs duplicats</button>";
			}
