		}
		else {
			throw new Exception('', 4411);
		}
		return $button;
	}

	/**
   * @brief Mostra una taula amb tota la informació necessària per la consulta diària «Comprovar duplicats»
   * @return Mostra una taula amb tota la informació necessària per la consulta diària «Comprovar duplicats»
   */
	private function __mostrarPage_Facturacio_Comprovar_Duplicats_IdPags($nomFuncio, $descFuncio) {

		$table = "";
		$button = "";

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();
		$conWeb2 = new ConnexioWeb();
		$conWeb2->connectarBD();

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["cnsDuplicateIdPag"] ) ) {
			if ( $stmt2=$conWeb2->prepare( $this->consultesBD_Web["cnsInfoInscByIdPag"] ) ) {
				$stmt2->bind_param("d", $idPagSearch);

				$stmt->execute();
				$stmt->store_result();
				if ( $stmt->num_rows() > 0 ) {
					$stmt->bind_result($numDuplicats, $idPag);

					while ( $stmt->fetch() ) {
						$classTr = "";

						$table .= "<table class='table table-hover table-striped table-hover text-center mb-4'>
						<thead>
						<tr>
							<th>Any</th>
							<th>Mes</th>
							<th>Curs</th>
							<th>DNI</th>
							<th>Nom</th>
							<th>Cognoms</th>
							<th><em>E-mail</em></th>
							<th>Inscrit</th>
							<th>A Pagar</th>
							<th>Pagament</th>
							<th>Falta pagar</th>
							<th>Factura</th>
							<th>Accions</th>
						</tr>
						</thead>
						<tbody>";

						$table .= "<p class='text-center'>El IDPAG <strong>".$idPag."</strong> està duplicat <strong>".$numDuplicats."</strong> vegades.</p>";

						$idPagSearch = $idPag;

						$stmt2->execute();

						$stmt2->bind_result($any, $mes, $curs, $dniAlumne, $nomAlumne,
						$cognomsAlumne, $emailAlumne, $inscrit, $aPagar, $pagament, $factRel);

						while ( $stmt2->fetch() ) {
							$faltaPagar = $aPagar - $pagament;
							$classTr = '';
							if ( $faltaPagar > 0 ) $classTr = 'text-danger';

							$labelInscrit = $this->obtenirLabel('', 'lightGray', $inscrit);
							if ( $inscrit == "0" ) $labelInscrit = $this->obtenirLabel('', 'lightOrange', 'NO INSCRIT');
							else if ( $inscrit == "1" ) $labelInscrit = $this->obtenirLabel('', 'lightGreen', 'INSCRIT');
							else if ( $inscrit == "C" ) $labelInscrit = $this->obtenirLabel('', 'lightGray', 'CANVI');
							else if ( $inscrit == "X" ) $labelInscrit = $this->obtenirLabel('', 'lightGray', 'BAIXA');
							else if ( $inscrit == "M" ) $labelInscrit = $this->obtenirLabel('', 'lightRed', 'MORÒS');

							$classFactura='';
							$titleFactura='Consulta la factura de la inscripció';
							if ( $factRel == '' or $factRel == null ) {
								$labelFactRel = $this->obtenirLabel('', 'lightGray', "NO N'HI HA");
								$classFactura = "-hide no-disponible";
								$titleFactura = "La factura de la inscripció no està disponible";
							}
							else {
								$labelFactRel = $this->obtenirLabel('', 'lightOrange', $factRel);
								$classFactura = " generada";
								$titleFactura = "La factura de la inscripció està generada";
							}

							$table .= "<tr class='".$classTr."'>
								<td>".$any."</td>
								<td>".$curs."</td>
								<td>".$mes."</td>
								<td>".$dniAlumne."</td>
								<td>".$nomAlumne."</td>
								<td>".$cognomsAlumne."</td>
								<td>".$emailAlumne."</td>
								<td>".$labelInscrit."</td>
								<td>".$aPagar."</td>
								<td>".$pagament."</td>
								<td>".$faltaPagar." €</td>
								<td>".$labelFactRel."</td>
								<td>
									<div class='d-flex flex-column flex-md-row justify-content-center align-items-center w-100'>
										<i id='cnsAlumne-".$dniAlumne."' class='material-icons cns-alumne' title='Consulta la informació'>info</i>
										<i id='cnsFact-".$dniAlumne."' class='fa-solid fa-file-invoice-dollar ml-2 cns-factura".$classFactura."' title='".$titleFactura."'></i>
									</div>
								</td>
							</tr>";
						}

						$table .= "</tbody></table>";
					}

				}
				else {
					$table = "<p class='text-center'>No hi ha resultats.</p>";
				}
			}
			else {
				throw new Exception('', 4413);
			}
		}
		else {
			throw new Exception('', 4412);
		}

		$conWeb2->desconectarBD();
		$conWeb->desconectarBD();

		if ( $descFuncio != '' ) $descFuncio = "<p class='desc-apartat'>".$descFuncio."</p>";

		$mostrar = "<div id='cursos' class='card card-blau mt-5 d-flex flex-column justify-content-center align-items-center'>
			<div class='d-flex flex-column justify-content-center align-items-center w-100 text-center border-bottom card-header'>
				<p class='title font-weight-bold text-center py-3 mb-0 align-items-center
				justify-content-center d-flex'>".$nomFuncio."</p>
			</div>
			<div class='card-body px-0 w-100 ps2' style='max-height: 500px'>
				<div class='d-flex flex-column justify-content-center my-2'>
					".$table."
				</div>
			</div>
			".$button."
		</div>";

		return $mostrar;
	}

