	   $trobat = 0;
	   if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["cnsReclamacions"] ) ) {
	      $stmt->execute();
	      $stmt->store_result();
	      if ( $stmt->num_rows() > 0 ) {
	         $stmt->bind_result($idInsc, $any, $mes, $curs, $dni, $nom, $cognoms,
				$correu, $obsPagament, $tipusInsc, $entitat, $idpag);
	         while ( $stmt->fetch() && !$trobat) {
	            $button = "<p>Hi han persones per donar-los de baixa.</p>
	            <button id='reclamar-".$idApartatFuncio."' class='reclamar boto-blau mt-2 px-4 d-flex'>Recorda pagament (fi de curs)</button>";
	            $trobat = 1;
	         }
	      }
	      else {
	         $button = "<p class='text-center'>No hi ha resultats.</p>";
