	public function __mostrarPage_Facturacio_Primera_Reclamacio_contingut($orderBy, $asc) {
		$table = "";
		$infoTable = "";
		$button = "";
		$resultats = []; $i = 0;

		$titolsInscr[0] = "Tipus";
		$titolsInscr[1] = "Any";
		$titolsInscr[2] = "Mes";
		$titolsInscr[3] = "Curs";
		$titolsInscr[4] = "DNI";
		$titolsInscr[5] = "Nom";
		$titolsInscr[6] = "Cognoms";
		$titolsInscr[7] = "<em>E-mail</em>";
		$titolsInscr[8] = "Observacions";
		$titolsInscr[9] = "Reclamar";

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["cnsReclamacions"] ) ) {
			$stmt->execute();
			$stmt->store_result();
			if ( $stmt->num_rows() > 0 ) {

				$stmt->bind_result($idInsc, $any, $mes, $curs, $dni, $nom, $cognoms,
				$correu, $obsPagament, $tipusInsc, $entitat, $idpag);
				while ( $stmt->fetch() ) {
					$exMoros = $this->comprovaAlumnaEsMoros($dni);
					$alertaMoros = '';
					if ( $exMoros ) $alertaMoros = "<label class='estat bg-danger text-white position-relative font-weight-bold px-2 py-1'>DEUTOR!</label>";

					$resultats[$i][0] = $idInsc;
					$resultats[$i][1] = $any;
					$resultats[$i][2] = $mes;
					$resultats[$i][3] = $curs;
					$resultats[$i][4] = $dni;
					$resultats[$i][5] = $nom;
					$resultats[$i][6] = $cognoms;
					$resultats[$i][7] = $correu;
					$resultats[$i][8] = $obsPagament;
					$resultats[$i][9] = $alertaMoros;
					$resultats[$i][10] = $tipusInsc;
					$resultats[$i][11] = $entitat;
					$resultats[$i][12] = $idpag;

					$buttonValidar = 	$this->obtenirLabel('reclamar-'.$idInsc, 'lightGreen marcat pointer w-100', 'SÍ'.$this->obtenirIconaMaterials('', '', 'sentiment_satisfied_alt', 'reclama'));
					if ( $entitat != '' )
						$buttonValidar = 	$this->obtenirLabel('reclamar-'.$idInsc, 'lightRed no_marcat pointer w-100', 'NO'.$this->obtenirIconaMaterials('', '', 'sentiment_very_dissatisfied', 'reclama'));

					$labelTipus = $this->__getLabelTypeInsc($idpag, $tipusInsc, $entitat);
					$labels = "<div class='d-flex flex-row justify-content-center align-items-center'>
						".$labelTipus."
					</div>";

					// Marquem de color en els casos que s'han de tenir controlats (entitas i grups)
					$classAccess = $this->__getColorTrCont_Recordatori_Pagament($tipusInsc, $entitat);

					$infoTable .= "<tr ".$classAccess.">
						".$this->mostrarFilaTaulaResponsive('', $alertaMoros)."
						".$this->mostrarFilaTaulaResponsive($titolsInscr[0], $labels)."
						".$this->mostrarFilaTaulaResponsive($titolsInscr[1], $any)."
						".$this->mostrarFilaTaulaResponsive($titolsInscr[2], $mes)."
						".$this->mostrarFilaTaulaResponsive($titolsInscr[3], $curs)."
						".$this->mostrarFilaTaulaResponsive($titolsInscr[4], $dni)."
						".$this->mostrarFilaTaulaResponsive($titolsInscr[5], $nom)."
						".$this->mostrarFilaTaulaResponsive($titolsInscr[6], $cognoms)."
						".$this->mostrarFilaTaulaResponsive($titolsInscr[7], $correu)."
						".$this->mostrarFilaTaulaResponsive($titolsInscr[8], $obsPagament)."
						".$this->mostrarFilaTaulaResponsive($titolsInscr[9], $buttonValidar)."
					</tr>";

					$i++;
				}


			}
			else {
				$table = "";
			}
		}
		else {
			throw new Exception('', 4486);
		}

		$conWeb->desconectarBD();

		$classes = ['', '', '', ''];

		if ( $orderBy != '' ) {

			if ($orderBy == 'codi') $cntOrderBy = 0;
			else if ($orderBy == 'nom') $cntOrderBy = 1;
			else if ($orderBy == 'dni') $cntOrderBy = 2;
			else if ($orderBy == 'cog') $cntOrderBy = 3;

			if ($asc == 1) { //s'ordena ascendentment
				$inici = 0;
				$fi = count($resultats);
				$i = $inici;
				$condicio = $i < $fi;

				$classes[$cntOrderBy] = ' asc';
			}
			else { //s'ordena dsscendentment
				$inici = count($resultats);
				$fi = 0;
				$i = $inici-1;
				$condicio = $i >= $fi;

				$classes[$cntOrderBy] = ' desc';
			}
		}

		if ( count($resultats) > 0 ) {

			$table .= "<table class='table table-striped table-hover table-order table-lg-responsive text-center mt-2 mb-0'>
			<thead><tr>
				<th></th>
				<th>".$titolsInscr[0]."</th>
				<th>".$titolsInscr[1]."</th>
				<th>".$titolsInscr[2]."</th>
				<th id='th-codi' class='sorting".$classes[0]."'>".$titolsInscr[3]."</th>
				<th id='th-dni' class='sorting".$classes[2]."'>".$titolsInscr[4]."</th>
				<th id='th-nom' class='sorting".$classes[1]."'>".$titolsInscr[5]."</th>
				<th id='th-cog' class='sorting".$classes[3]."'>".$titolsInscr[6]."</th>
				<th>".$titolsInscr[7]."</th>
				<th>".$titolsInscr[8]."</th>
				<th>".$titolsInscr[9]."</th>
			</tr></thead>
			<tbody>";
			if ( $orderBy != '' )
				$infoTable = $this->__mostrarResultatsReclamacionsOrdenatsPerUnCamp($titolsInscr, $resultats, $orderBy, $asc);
			$table .= $infoTable;
			$table .= "</tbody></table>";
		}
		else {
			$table = "";
		}
		return $table;
	}

	public function __mostrarResultatsReclamacionsOrdenatsPerUnCamp($titolsInscr, $resultats, $orderBy, $asc) {
		function cmpCodi($a, $b) {
		    if ($a[3] == $b[3]) {
				if ($a[1] == $b[1]) {
					if ($a[2] == $b[2]) {
						if ($a[6] == $b[6]) {
							 return 0;
					   }
					   return ($a[6] < $b[6]) ? -1 : 1;
				  }
				  return ($a[2] < $b[2]) ? -1 : 1;
			   }
			   return ($a[1] < $b[1]) ? -1 : 1;
		    }
		    return ($a[3] < $b[3]) ? -1 : 1;
		}

		function cmpNom($a, $b) {
		    if ($a[5] == $b[5]) {
				if ($a[6] == $b[6]) {
					if ($a[1] == $b[1]) {
					  if ($a[2] == $b[2]) {
								return 0;
					 }
					 return ($a[2] < $b[2]) ? -1 : 1;
				  }
				  return ($a[1] < $b[1]) ? -1 : 1;
			   }
			   return ($a[6] < $b[6]) ? -1 : 1;
		    }
		    return ($a[5] < $b[5]) ? -1 : 1;
		}

		function cmpDni($a, $b) {
		    if ($a[4] == $b[4]) {
				 if ($a[1] == $b[1]) {
 					if ($a[2] == $b[2]) {
 						if ($a[3] == $b[3]) {
 							 return 0;
 					   }
 					   return ($a[3] < $b[3]) ? -1 : 1;
 				  }
 				  return ($a[2] < $b[2]) ? -1 : 1;
 			   }
 			   return ($a[1] < $b[1]) ? -1 : 1;
		    }
		    return ($a[4] < $b[4]) ? -1 : 1;
		}

		function cmpCognoms($a, $b) {
		    if ($a[6] == $b[6]) {
				 if ($a[1] == $b[1]) {
 					if ($a[2] == $b[2]) {
 						if ($a[3] == $b[3]) {
 							 return 0;
 					   }
 					   return ($a[3] < $b[3]) ? -1 : 1;
 				  }
 				  return ($a[2] < $b[2]) ? -1 : 1;
 			   }
 			   return ($a[1] < $b[1]) ? -1 : 1;
		    }
		    return ($a[6] < $b[6]) ? -1 : 1;
		}

		$cntOrderBy = 0;
		if ($orderBy == 'codi') { usort($resultats, "cmpCodi"); $cntOrderBy = 0; }
		else if ($orderBy == 'nom') { usort($resultats, "cmpNom"); $cntOrderBy = 1; }
		else if ($orderBy == 'dni') { usort($resultats, "cmpDni"); $cntOrderBy = 2; }
		else if ($orderBy == 'cog') { usort($resultats, "cmpCognoms"); $cntOrderBy = 3; }

		$classes = ['', '', '', ''];

		if ( $orderBy != '' ) {

			if ($asc == 1) { //s'ordena ascendentment
				$inici = 0;
				$fi = count($resultats);
				$i = $inici;
				$condicio = $i < $fi;

				$classes[$cntOrderBy] = 'asc';
			}
			else { //s'ordena dsscendentment
				$inici = count($resultats);
				$fi = 0;
				$i = $inici-1;
				$condicio = $i >= $fi;

				$classes[$cntOrderBy] = 'desc';
			}
		}


		$table = '';
		while ( $condicio ) {
			$idInsc = $resultats[$i][0];
			$any = $resultats[$i][1];
			$mes = $resultats[$i][2];
			$curs = $resultats[$i][3];
			$dni = $resultats[$i][4];
			$nom = $resultats[$i][5];
			$cognoms = $resultats[$i][6];
			$correu = $resultats[$i][7];
			$obsPagament = $resultats[$i][8];
			$alerta = $resultats[$i][9];
			$tipusInsc = $resultats[$i][10];
			$entitat = $resultats[$i][11];
			$idpag = $resultats[$i][12];

			$buttonValidar = 	$this->obtenirLabel('reclamar-'.$idInsc, 'lightGreen marcat pointer w-100', 'SÍ'.$this->obtenirIconaMaterials('', '', 'sentiment_satisfied_alt', 'reclama'));
			if ( $entitat != '' )
				$buttonValidar = 	$this->obtenirLabel('reclamar-'.$idInsc, 'lightRed no_marcat pointer w-100', 'NO'.$this->obtenirIconaMaterials('', '', 'sentiment_very_dissatisfied', 'reclama'));

			$labelTipus = $this->__getLabelTypeInsc($idpag, $tipusInsc, $entitat);
			$labels = "<div class='d-flex flex-row justify-content-center align-items-center'>
				".$labelTipus."
			</div>";

			$classAccess = $this->__getColorTrCont_Recordatori_Pagament($tipusInsc, $entitat);
			$infoTable .= "<tr ".$classAccess.">
				".$this->mostrarFilaTaulaResponsive('', $alerta)."
				".$this->mostrarFilaTaulaResponsive($titolsInscr[0], $labels)."
				".$this->mostrarFilaTaulaResponsive($titolsInscr[1], $any)."
				".$this->mostrarFilaTaulaResponsive($titolsInscr[2], $mes)."
				".$this->mostrarFilaTaulaResponsive($titolsInscr[3], $curs)."
				".$this->mostrarFilaTaulaResponsive($titolsInscr[4], $dni)."
				".$this->mostrarFilaTaulaResponsive($titolsInscr[5], $nom)."
				".$this->mostrarFilaTaulaResponsive($titolsInscr[6], $cognoms)."
				".$this->mostrarFilaTaulaResponsive($titolsInscr[7], $correu)."
				".$this->mostrarFilaTaulaResponsive($titolsInscr[8], $obsPagament)."
				".$this->mostrarFilaTaulaResponsive($titolsInscr[9], $buttonValidar)."
			</tr>";

			if ( $asc == 1 ) {
				$i++;
				$condicio = $i < $fi;
			}
			else {
				$i--;
				$condicio = $i >= $fi;
			}
		}
		return $table;
	}

	/**
	* @brief ENVIAMENT DE CORREUS I ACTUALITZACIONS DE REGISTRES
	* @return ACTUALITZEM EL REGISTRE $idInsc INDICANT QUE S’HA RECLAMAT
	* (ACTUALITZEM LA INSCRIPCIÓ AMB reclamat= '1a reclamació correu' i data_reclamacio = DATA ACTUAL)
	* ENVIEM CORREU DE RECLAMACIÓ a l'alumne i amb copia a resguard.gestio@prisma.cat
	*/
	public function __updateSendMsg_Facturacio_Primera_Reclamacio($idInsc) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		/* ###################   CERCO DADES DE L'USUARI   ################### */

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarInfoInscripcions"] ) ) {
			$stmt->bind_param("d", $idInsc);
			$stmt->execute();
			$stmt->bind_result($any, $mes, $curs, $aula, $nom, $cognoms, $dni, $email,
			$telefon, $adreca, $cp, $poblacio, $perfil, $titulacio,
			$dataInsc, $inscrit, $tipusInsc, $tipusDesc, $validDesc,
			$inscao, $inscmail, $certificat, $obscertificat, $generat, $obs,
			$comentaris, $databaixa, $motiubaixa, $quibaixa, $apagar, $pag, $datapag,
			$idPag, $pagObs, $comHaPagat, $entitat, $fraccio, $comFraccio, $factura,
			$datarec, $reclamat, $usuari);
			$stmt->fetch();
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4487);
		}

		/* ###################      CERCO DADES CURS       ################### */
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarCursSegEd"] ) ) {
			$stmt->bind_param("dss", $any, $mes, $curs);
			$stmt->execute();
			$stmt->bind_result($titol, $datai, $dataf, $hores, $idPreu);
			$stmt->fetch();
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4488);
		}

		require_once 'Date.php';
		$objDataI = new Date($datai);
		$dataLlargaInici = $objDataI->getDataLlarga();

		/* ################### CALCULO L'ENLLAÇ DE PAGAMENT ################### */

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarParam"] ) ) {
			$stmt->bind_param("s", $tipusParam);
			$tipusParam = 'keyEncriptar';
			$stmt->execute();
			$stmt->bind_result($keyEncr);
			$stmt->fetch();

			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4489);
		}

		$cipher = "AES-128-CBC";

		$ivlen = openssl_cipher_iv_length($cipher);
		$iv = openssl_random_pseudo_bytes($ivlen);
		$ciphertext_raw = openssl_encrypt($idPag, $cipher, $keyEncr, $options=OPENSSL_RAW_DATA, $iv);
		$hmac = hash_hmac('sha256', $ciphertext_raw, $keyEncr, $as_binary=true);
		$hashIdPag = base64_encode( $iv.$hmac.$ciphertext_raw );

		$urlPagament = "https://www.prisma.cat/";

		if ( $tipusInsc == 'I' or $tipusInsc == 'R' )
			$urlPagament .= "pagament/";
		else if ( $tipusInsc == 'G' OR $tipusInsc == 'P' )
			$urlPagament .= "pagaments/";

		$urlPagament .= $hashIdPag;

		/* ###################    CONSTRUIM EL MISSATGE    ################### */
		$dateNow = new DateTime("now");
		$dataAct = $dateNow->format('d/m/Y');
		$dataHoraAct = $dateNow->format('d/m/Y H:i');

		$subject = "Recordatori de pagament de la inscripció del curs ".$titol;
		$subjectCopy = "Recordatori de pagament de la inscripció del curs ".$titol." | ".$dataHoraAct;

		$message = "<p>Benvolgut/da ".$nom.",</p>

		<p>Revisant els pagaments, hem detectat que encara no hem rebut l'import corresponent a
		la teva inscripció al curs <strong style='color: ".$this->colors_destacats["msgDestacatCorreu1"]."'>".$titol."</strong>
		que va començar ".$objDataI->getPronomEl()."<strong>".$dataLlargaInici."</strong>.</p>

		<p>Si ja has fet el pagament mitjançant transferència bancària,
		pot ser que no hàgim pogut identificar-lo correctament.
		En aquest cas, et demanem que ens n'enviïs el justificant o ens indiquis
		la data d'ingrés i a quin banc es va fer (La Caixa o BBVA) a
		<a href='mailto:gestio@prisma.cat' style='font-weight: bold; text-decoration: none;
		color: ".$this->colors_destacats["msgDestacatCorreu1"]."'>gestio@prisma.cat</a>
		per poder validar-lo a través del correu electrònic <a
		href='mailto:".$email."' style='font-weight: bold; text-decoration: none;
		color: ".$this->colors_destacats["msgDestacatCorreu1"]."'>".$email."</a>.</p>

		<p>Si encara no has realitzat el pagament, t'agrairíem que el completessis
		com més aviat millor per seguir assegurant la teva plaça al curs.</p>

		<p>Et recordem l'enllaç per fer el pagament: <a href='".$urlPagament."'
		title='Pagament del curs ".$titol."'>".$urlPagament."</a></p>

		<p>En cas que no rebem el pagament en un termini de 3 dies naturals, et donarem de baixa del curs automàticament.</p>

		<p>Per a qualsevol dubte, no dubtis a contactar amb nosaltres.</p>

		<p>Moltes gràcies per la teva atenció.</p>

		<p>Atentament,</p>";

		/* ########################   UPDATE INSCRIPCIO   ######################## */

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["updPrimeraReclamacio"] ) ) {
			$stmt->bind_param("d", $idInsc);
			$stmt->execute();
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4490);
		}

		/* ########################          SMTP          ######################## */
		$authGest = $this->getAuthSMTP_Gestio();
		// $authGest = $this->getAuthSMTP_Secretaria();
		$userGest = $authGest[0];
		$passGest = $authGest[1];
		$nameUserGest = $authGest[2];

		$qui = $this->usuari->getNom()->get()." ".$this->usuari->getCognom()->get();
		$depart = $this->usuari->getDepart()->get();

		require_once 'MailSMTPComvive.php';

		$nomFromHead = $nameUserGest;
		$correuFromHead = $userGest;
		$nomReplyHead = $nom." ".$cognoms;
		$correuReplyHead = $email;

		$nomTo = "PrisMa Gestió";
		$correuTo = "resguard.gestio@prisma.cat";
		// $correuTo = "meriem.prisma.cat@gmail.com";

		$mailCopy = new MailSMTPComvive($userGest, $passGest, $nomFromHead, $correuFromHead,
							$nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
							$subjectCopy, $message, $qui, $depart);

		$nomTo = $nom." ".$cognoms;
		$correuTo = $email;
		// $correuTo = "meriem.prisma.cat@gmail.com";
		$nomReplyHead = $nameUserGest;
		$correuReplyHead = $userGest;

		$mailAlumne = new MailSMTPComvive($userGest, $passGest, $nomFromHead, $correuFromHead,
							$nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
							$subject, $message, $qui, $depart);

		echo "OK";
	}

