	public function __mostrarPage_Facturacio_Baixes_Segona_Setmana_contingut($orderBy, $asc) {
		$table = "";
		$infoTable = "";
		$button = "";
		$resultats = []; $i = 0;

		$titolsInscr[0] = "Tipus";
		$titolsInscr[1] = "Any";
		$titolsInscr[2] = "Mes";
		$titolsInscr[3] = "Curs";
		$titolsInscr[4] = "DNI";
		$titolsInscr[5] = "Nom";
		$titolsInscr[6] = "Cognoms";
		$titolsInscr[7] = "<em>E-mail</em>";
		$titolsInscr[8] = "Telèfon";
		$titolsInscr[9] = "Reclamat";
		$titolsInscr[10] = "Obs. pagament";
		$titolsInscr[11] = "";
		$titolsInscr[12] = "Motiu";
		$titolsInscr[13] = "Baixa";

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["cnsRegBaixesSegonaSetnaba"] ) ) {
			$stmt->execute();
			$stmt->store_result();
			if ( $stmt->num_rows() > 0 ) {

				$stmt->bind_result($idInsc, $any, $mes, $curs, $aula, $tel, $dni, $nom,
				$cognoms, $correu, $reclamat, $obsPagament, $perenne, $usuari, $tipusInsc, $entitat, $idpag);
				while ( $stmt->fetch() ) {
					$resultats[$i][0] = $idInsc;
					$resultats[$i][1] = $any;
					$resultats[$i][2] = $mes;
					$resultats[$i][3] = $curs;
					$resultats[$i][4] = $dni;
					$resultats[$i][5] = $nom;
					$resultats[$i][6] = $cognoms;
					$resultats[$i][7] = $correu;
					$resultats[$i][8] = $tel;
					$resultats[$i][9] = $reclamat;
					$resultats[$i][10] = $obsPagament;
					$resultats[$i][11] = $perenne;

					//CONSULTEM LES DADES DEL MOODLE
					$shortname = $any.$curs.$mes.$aula;
					$campsMdl = $this->__getInfoMdl($shortname, $usuari);

					$resultats[$i][12] = $campsMdl['exist'];
					$resultats[$i][13] = $campsMdl['userId'];
					$resultats[$i][14] = $campsMdl['courseId'];
					$resultats[$i][15] = $campsMdl['access'];
					$resultats[$i][16] = $campsMdl['textMoodle'];
					$resultats[$i][17] = $campsMdl['motiuBaixa'];
					$resultats[$i][18] = $campsMdl['colorTr'];

					$resultats[$i][19] = $tipusInsc;
					$resultats[$i][20] = $entitat;
					$resultats[$i][21] = $idpag;

					$motiu = $campsMdl['motiuBaixa'];

					// label tipus
					$labelTipus = $this->__getLabelTypeInsc($idpag, $tipusInsc, $entitat);
					$labels = "<div class='d-flex flex-row justify-content-center align-items-center'>
						".$labelTipus."
					</div>";

					//Preparar el camp Motiu
					$campReclamat = $this->__obtenirCampReclamacio_DonarBaixa($reclamat, $idInsc);
					//Preparar el botó de qualificacions
					$buttonQual = $this->__getButtonQual_DonarBaixa($campsMdl['textMoodle'], $campsMdl['exist'], $campsMdl['userId'], $campsMdl['courseId']);
					//Obtinc el botó per accedir a les participacions
					$buttonPart = $this->__getButtonPart_DonarBaixa($campsMdl['textMoodle'], $campsMdl['exist'], $campsMdl['userId'], $campsMdl['courseId']);
					//Preparar el camp Motiu
					$campMotiu = $this->__obtenirCampMotiu_DonarBaixa($motiu, $idInsc);
					//Preparar el botó per validar la Baixa
					$buttonValidar = 	$this->obtenirLabel('baixa-'.$idInsc, 'lightGreen marcat pointer w-100', 'SÍ'.$this->obtenirIconaMaterials('', '', 'sentiment_satisfied_alt', 'dona de baixa'));

					$cntButtons = "<div class='d-flex flex-column
					flex-sm-row align-items-center justify-content-center w-100'>
					".$buttonQual.$buttonPart."
					</div>";

					$classAccess = '';
					if ( $campsMdl['colorTr'] != '' ) $classAccess = " class='".$campsMdl['colorTr']."'";

					$infoTable .= "<tr".$classAccess.">
						".$this->mostrarFilaTaulaResponsive($titolsInscr[0], $labels)."
						".$this->mostrarFilaTaulaResponsive($titolsInscr[1], $any)."
						".$this->mostrarFilaTaulaResponsive($titolsInscr[2], $mes)."
						".$this->mostrarFilaTaulaResponsive($titolsInscr[3], $curs)."
						".$this->mostrarFilaTaulaResponsive($titolsInscr[4], $dni)."
						".$this->mostrarFilaTaulaResponsive($titolsInscr[5], $nom)."
						".$this->mostrarFilaTaulaResponsive($titolsInscr[6], $cognoms)."
						".$this->mostrarFilaTaulaResponsive($titolsInscr[7], $correu)."
						".$this->mostrarFilaTaulaResponsive($titolsInscr[8], $tel)."
						".$this->mostrarFilaTaulaResponsive($titolsInscr[9], $campReclamat)."
						".$this->mostrarFilaTaulaResponsive($titolsInscr[10], $obsPagament)."
						".$this->mostrarFilaTaulaResponsive($titolsInscr[11], $cntButtons)."
						".$this->mostrarFilaTaulaResponsive($titolsInscr[12], $campMotiu)."
						".$this->mostrarFilaTaulaResponsive($titolsInscr[13], $buttonValidar)."
					</tr>";

					$i++;
				}
			}
			else {
				$table = "";
			}
		}
		else {
			throw new Exception('', 4491);
		}

		$conWeb->desconectarBD();

		$classes = ['', '', '', ''];

		if ( $orderBy != '' ) {

			if ($orderBy == 'codi') $cntOrderBy = 0;
			else if ($orderBy == 'nom') $cntOrderBy = 1;
			else if ($orderBy == 'dni') $cntOrderBy = 2;
			else if ($orderBy == 'cog') $cntOrderBy = 3;

			if ($asc == 1) { //s'ordena ascendentment
				$inici = 0;
				$fi = count($resultats);
				$i = $inici;
				$condicio = $i < $fi;

				$classes[$cntOrderBy] = ' asc';
			}
			else { //s'ordena dsscendentment
				$inici = count($resultats);
				$fi = 0;
				$i = $inici-1;
				$condicio = $i >= $fi;

				$classes[$cntOrderBy] = ' desc';
			}
		}

		if ( count($resultats) > 0 ) {

			$table .= "<table class='table table-striped table-hover table-order table-xl-responsive text-center mt-2 mb-0'>
			<thead><tr>
				<th>".$titolsInscr[0]."</th>
				<th>".$titolsInscr[1]."</th>
				<th>".$titolsInscr[2]."</th>
				<th id='th-codi' class='sorting".$classes[0]."'>".$titolsInscr[3]."</th>
				<th id='th-dni' class='sorting".$classes[2]."'>".$titolsInscr[4]."</th>
				<th id='th-nom' class='sorting".$classes[1]."'>".$titolsInscr[5]."</th>
				<th id='th-cog' class='sorting".$classes[3]."'>".$titolsInscr[6]."</th>
				<th>".$titolsInscr[7]."</th>
				<th>".$titolsInscr[8]."</th>
				<th>".$titolsInscr[9]."</th>
				<th>".$titolsInscr[10]."</th>
				<th>".$titolsInscr[11]."</th>
				<th>".$titolsInscr[12]."</th>
				<th>".$titolsInscr[13]."</th>
			</tr></thead>
			<tbody>";
			if ( $orderBy != '' )
				$infoTable = $this->__mostrarResultatsDonarBaixaOrdenatsPerUnCamp($titolsInscr, $resultats, $orderBy, $asc);
			$table .= $infoTable;
			$table .= "</tbody></table>";
		}
		else {
			$table = "";
		}
		return $table;
	}

	public function __mostrarResultatsDonarBaixaOrdenatsPerUnCamp($titolsInscr, $resultats, $orderBy, $asc) {
		function cmpCodi($a, $b) {
		    if ($a[3] == $b[3]) {
				if ($a[1] == $b[1]) {
					if ($a[2] == $b[2]) {
						if ($a[6] == $b[6]) {
							 return 0;
					   }
					   return ($a[6] < $b[6]) ? -1 : 1;
				  }
				  return ($a[2] < $b[2]) ? -1 : 1;
			   }
			   return ($a[1] < $b[1]) ? -1 : 1;
		    }
		    return ($a[3] < $b[3]) ? -1 : 1;
		}

		function cmpNom($a, $b) {
		    if ($a[5] == $b[5]) {
				if ($a[6] == $b[6]) {
					if ($a[1] == $b[1]) {
					  if ($a[2] == $b[2]) {
								return 0;
					 }
					 return ($a[2] < $b[2]) ? -1 : 1;
				  }
				  return ($a[1] < $b[1]) ? -1 : 1;
			   }
			   return ($a[6] < $b[6]) ? -1 : 1;
		    }
		    return ($a[5] < $b[5]) ? -1 : 1;
		}

		function cmpDni($a, $b) {
		    if ($a[4] == $b[4]) {
				 if ($a[1] == $b[1]) {
 					if ($a[2] == $b[2]) {
 						if ($a[3] == $b[3]) {
 							 return 0;
 					   }
 					   return ($a[3] < $b[3]) ? -1 : 1;
 				  }
 				  return ($a[2] < $b[2]) ? -1 : 1;
 			   }
 			   return ($a[1] < $b[1]) ? -1 : 1;
		    }
		    return ($a[4] < $b[4]) ? -1 : 1;
		}

		function cmpCognoms($a, $b) {
		    if ($a[6] == $b[6]) {
				 if ($a[1] == $b[1]) {
 					if ($a[2] == $b[2]) {
 						if ($a[3] == $b[3]) {
 							 return 0;
 					   }
 					   return ($a[3] < $b[3]) ? -1 : 1;
 				  }
 				  return ($a[2] < $b[2]) ? -1 : 1;
 			   }
 			   return ($a[1] < $b[1]) ? -1 : 1;
		    }
		    return ($a[6] < $b[6]) ? -1 : 1;
		}

		$cntOrderBy = 0;
		if ($orderBy == 'codi') { usort($resultats, "cmpCodi"); $cntOrderBy = 0; }
		else if ($orderBy == 'nom') { usort($resultats, "cmpNom"); $cntOrderBy = 1; }
		else if ($orderBy == 'dni') { usort($resultats, "cmpDni"); $cntOrderBy = 2; }
		else if ($orderBy == 'cog') { usort($resultats, "cmpCognoms"); $cntOrderBy = 3; }

		$classes = ['', '', '', ''];

		if ( $orderBy != '' ) {

			if ($asc == 1) { //s'ordena ascendentment
				$inici = 0;
				$fi = count($resultats);
				$i = $inici;
				$condicio = $i < $fi;

				$classes[$cntOrderBy] = 'asc';
			}
			else { //s'ordena dsscendentment
				$inici = count($resultats);
				$fi = 0;
				$i = $inici-1;
				$condicio = $i >= $fi;

				$classes[$cntOrderBy] = 'desc';
			}
		}


		$table = '';
		while ( $condicio ) {
			$idInsc = $resultats[$i][0];
			$any = $resultats[$i][1];
			$mes = $resultats[$i][2];
			$curs = $resultats[$i][3];
			$dni = $resultats[$i][4];
			$nom = $resultats[$i][5];
			$cognoms = $resultats[$i][6];
			$correu = $resultats[$i][7];
			$tel = $resultats[$i][8];
			$reclamat = $resultats[$i][9];
			$obsPagament = $resultats[$i][10];
			$perenne = $resultats[$i][11];

			$exist = $resultats[$i][12];
			$userId = $resultats[$i][13];
			$courseId = $resultats[$i][14];
			$accessMdl = $resultats[$i][15];
			$textMoodle = $resultats[$i][16];
			$motiu = $resultats[$i][17];
			$colorTr = $resultats[$i][18];

			$tipusInsc = $resultats[$i][19];
			$entitat = $resultats[$i][20];
			$idpag = $resultats[$i][21];

			$labelTipus = $this->__getLabelTypeInsc($idpag, $tipusInsc, $entitat);
			$labels = "<div class='d-flex flex-row justify-content-center align-items-center'>
				".$labelTipus."
			</div>";

			//Preparar el camp Motiu
			$campReclamat = $this->__obtenirCampReclamacio_DonarBaixa($reclamat, $idInsc);
			//Preparar el botó de qualificacions
			$buttonQual = $this->__getButtonQual_DonarBaixa($textMoodle, $exist, $userId, $courseId);
			//Obtinc el botó per accedir a les participacions
			$buttonPart = $this->__getButtonPart_DonarBaixa($textMoodle, $exist, $userId, $courseId);

			//Preparar el camp Motiu
			$campMotiu = $this->__obtenirCampMotiu_DonarBaixa($motiu,$idInsc);
			//Preparar el botó per validar la Baixa
			$buttonValidar = 	$this->obtenirLabel('baixa-'.$idInsc, 'lightGreen marcat pointer w-100', 'SÍ'.$this->obtenirIconaMaterials('', '', 'sentiment_satisfied_alt', 'dona de baixa'));

			$cntButtons = "<div class='d-flex flex-column
			flex-sm-row align-items-center justify-content-center w-100'>
			".$buttonQual.$buttonPart."
			</div>";

			$classAccess = '';
			if ( $colorTr != '' ) $classAccess = " class='".$colorTr."'";

			$table .= "<tr".$classAccess.">
				".$this->mostrarFilaTaulaResponsive($titolsInscr[0], $labels)."
				".$this->mostrarFilaTaulaResponsive($titolsInscr[1], $any)."
				".$this->mostrarFilaTaulaResponsive($titolsInscr[2], $mes)."
				".$this->mostrarFilaTaulaResponsive($titolsInscr[3], $curs)."
				".$this->mostrarFilaTaulaResponsive($titolsInscr[4], $dni)."
				".$this->mostrarFilaTaulaResponsive($titolsInscr[5], $nom)."
				".$this->mostrarFilaTaulaResponsive($titolsInscr[6], $cognoms)."
				".$this->mostrarFilaTaulaResponsive($titolsInscr[7], $correu)."
				".$this->mostrarFilaTaulaResponsive($titolsInscr[8], $tel)."
				".$this->mostrarFilaTaulaResponsive($titolsInscr[9], $campReclamat)."
				".$this->mostrarFilaTaulaResponsive($titolsInscr[10], $obsPagament)."
				".$this->mostrarFilaTaulaResponsive($titolsInscr[11], $cntButtons)."
				".$this->mostrarFilaTaulaResponsive($titolsInscr[12], $campMotiu)."
				".$this->mostrarFilaTaulaResponsive($titolsInscr[13], $buttonValidar)."
			</tr>";

			if ( $asc == 1 ) {
				$i++;
				$condicio = $i < $fi;
			}
			else {
				$i--;
				$condicio = $i >= $fi;
			}
		}
		return $table;
	}

	/**
   * @brief Obtens un vector amb la informació del moodle (existeix, userId, courseId, participacio)
	* @param shortname El codi del curs a cercar
	* @param usuari El codi del curs a cercar
   * @return campsMdl Obtens un array amb
	*	clau => exist i valor => confirma si el $usuari existeix en el curs
	*  clau => userId i valor => id de l'usuari del moodle
	*  clau => courseId i valor => id del curs $shortname del moodle
	*  clau => access i valor => la data de l'últim access de l'usuari $usuari al curs $shortname. En el seu defecte, "Mai"
	*
   */
	private function __getInfoMdl($shortname, $usuari) {
		// echo "################################<br />";
		// echo "short 	".$shortname."<br />";
		$campsMdl['exist'] = false;
		$campsMdl['userId'] = 0;
		$campsMdl['courseId'] = '';
		$campsMdl['access'] = 'Mai';
		$campsMdl['textMoodle'] = '';
		$campsMdl['motiuBaixa'] = "No ha pagat";
		$campsMdl['colorTr'] = "";

		//Busquem el ID del curs i de l'usuari del moodle

		require_once 'ConnexioMoodle.php';
		require_once 'ConnexioMoodleAntic.php';

		$conMdl1 = new ConnexioMoodle();
		$conMdl1->connectarBD();

		//Busquem el ID del curs
		if ( $stmt1=$conMdl1->prepare( $this->consultesBD_Moodle["buscarIdCurs"] ) ) {
			$stmt1->bind_param("s", $shortname);
			$stmt1->execute();
			$stmt1->store_result();
			$campsMdl['exist'] = ($stmt1->num_rows() > 0);
			if ( $campsMdl['exist'] ) {
				// echo "exist: ".$campsMdl['exist']."<br />";
				$stmt1->bind_result($campsMdl['courseId']);
				$stmt1->fetch();
				$conMdl1->closeStmt();
				$campsMdl['textMoodle'] = 'moodle';
				// echo "courseId: ".$campsMdl['courseId']."<br />";

				//Busquem el ID de l'usuari del moodle
				if ( $stmt2=$conMdl1->prepare( $this->consultesBD_Moodle["buscarIdUsuari"] ) ) {
					$stmt2->bind_param("d", $usuari);
					$stmt2->execute();
					$stmt2->store_result();
					if ($stmt2->num_rows() > 0) {
						$stmt2->bind_result($campsMdl['userId']);
						$stmt2->fetch();
						$conMdl1->closeStmt();
						// echo "userId: ".$campsMdl['userId']."<br />";
					}
				}
				else {
					throw new Exception('',xxxx);
				}

				//Busquem el log de l'usuari en el curs del moodle
				if ( $stmt3=$conMdl1->prepare( $this->consultesBD_Moodle["cnsLogUserCourse"] ) ) {
					// echo $this->consultesBD_Moodle["cnsLogUserCourse"]."<br />";
					$stmt3->bind_param("dd", $campsMdl['userId'], $campsMdl['courseId']);
					$stmt3->execute();
					$stmt3->store_result();
					if ($stmt3->num_rows() > 0) {
						$stmt3->bind_result($action, $target, $time);
						$stmt3->fetch();
						$conMdl1->closeStmt();
						if ( $action != 'created' || ( $action == 'created' && $target != 'post' && $target != 'submission' && $target != 'discussion') ) {
							$campsMdl['motiuBaixa'] = "No ha pagat i no ha participat";
							$campsMdl['colorTr'] = 'text-turquesa';
						}
						// echo "time".$time."<br />";

						$date = date_create();
						date_timestamp_set($date, $time);
						$campsMdl['access'] = date_format($date,"d-m-Y H:i:s");
					}
					else {
						$campsMdl['motiuBaixa'] = "No ha pagat i no ha accedit";
						$campsMdl['colorTr'] = 'text-danger';
					}
					// echo "motiu de baixa ".$campsMdl['motiuBaixa']."<br />";
				}
				else {
					throw new Exception('',xxxx);
				}
			}
			$conMdl1->desconectarBD();
		}
		else {
			throw new Exception('',xxxx);
		}
		// echo $campsMdl['access']."<br />";

		return $campsMdl;
	}

	/**
