		$textarea = $this->__mostrarTextarea($classForm, $nameLabel, $labelClass,
		$idInput, $classInput, $valorInput, $tipusInput);

		$nomButton = $this->obtenirIconaFontAw('', '', 'fas fa-floppy-disk text-white', 'Guardar');
		$button = $this->obtenirBotoTooltip('btnReclamar-'.$id, 'py-3 mx-1 rounded-circle btn-reclamar', $nomButton, 'bottom',
		'Guardar la reclamació');

		$camp = "<div class='d-flex flex-column flex-sm-row align-items-center justify-content-center w-100'>
