		$nomButton = $this->obtenirIconaFontAw('', '', 'fas fa-user-graduate text-white', 'Qualificador'.$textBotoDispo);
		$button = $this->obtenirBotoTooltip($textMoodle.'-qual-'.$courseId.'-'.$userId,
		$classDispo.' qualificador py-3 mx-1 rounded-circle w-100', $nomButton, 'bottom', 'Qualificacions en el moodle');

		return $button;
