	/**
   * @brief Actualitza el registre reclamat amb el que posa a $claim del registre $id
   * @return Actualitza el reclamat
   */
	public function saveMoneyClaim_DonarBaixa($claim, $id) {
		$mostrar = '';

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["updClaimDonarBaixa"] ) ) {
			$stmt->bind_param("sd", $claim, $id);
			echo "actualitzar reclamat ".$id." ".$claim."<br />";
			$stmt->execute();
			$conWeb->closeStmt();
			$mostrar = 'OK';
		}
		else {
			throw new Exception('',4497);
		}
		$conWeb->desconectarBD();
		return $mostrar;
	}

	/**
   * @brief Dona de baixa del campus i de la inscripció i enviem un missatge al tutori i a l'alumne
   * @return Dona de baixa el registre $idInsc amb el motiu de baixa $motiu de
	* baixa i envia un correu a l'alumne
	* 				$id es la id de la inscripció. (id del registre)
	* 				$motiuBaixa es el motiu de la baixa d'inscripció. (camp motiu baixa del registre)
   */
	public function updateSendMsg_Facturacio_Baixes_Segona_Setmana($id, $motiuBaixa) {
		echo $id."<br />";
		echo $motiuBaixa."<br />";

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		/* ##############  Busquem la informacio de la inscripcio  ############## */

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarInfoInscCurs"] ) ) {
			$stmt->bind_param("d", $id);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($any, $mes, $curs, $aula, $dataInscripcio, $nom, $cognoms,
				$correu, $dni, $adreca, $cp, $poblacio, $telefon, $obs, $perfil, $titol, $inscrit, $tipusInsc,
				$inscMailing, $apagar, $pagament, $dataPag, $idpag, $factRel, $fraccionat,
				$comHaPagat, $comentaris, $obsPag, $conegut, $motiuBaixa2, $usuari,
				$perenne, $hores, $idPreu, $nomCurs, $datai, $dataf, $dniTutor);
				$stmt->fetch();
			}
			else
				throw new Exception('',4498);
			$conWeb->closeStmt();
		}
		else
			throw new Exception('',4492);

		$motiuBaixa = $motiuBaixa2." ".$motiuBaixa;

		/* ##############      Busquem la informacio del curs      ############## */
		if ( $tipusInsc == 'T' ) {
			// Buscar la informació a la taula info_taller
			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarInfoTaller"] ) ) {
				$stmt->bind_param("dss", $any, $mes, $curs);
				$stmt->execute();
				$stmt->store_result();
				if ($stmt->num_rows() > 0) {
					$stmt->bind_result($datai, $hores, $idPreu);
					$stmt->fetch();
					$conWeb->closeStmt();
				}
				else {
					$conWeb->closeStmt();
				}
			}
			else {
				throw new Exception('',4493);
			}
		}
		else {
			// Buscar la informació a la taula curs
			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarCursSegEd"] ) ) {
				$stmt->bind_param("dss", $any, $mes, $curs);
				$stmt->execute();
				$stmt->store_result();
				if ($stmt->num_rows() > 0) {
					$stmt->bind_result($titol, $datai, $dataf, $hores, $idPreu);
					$stmt->fetch();
					$conWeb->closeStmt();
				}
				else {
					$conWeb->closeStmt();
				}
			}
			else {
				throw new Exception('',4494);
			}
		}

		/* ##############    Donem de baixa del curs del campus    ##############  */
		if ( $inscrit == '1' )  {
			$shortname = $any.$curs.$mes.$aula;
			// Si la persona està en el moodle nou
			if ( !$this->__donarBaixaMoodleNou($shortname, $usuari) ) {
				// Si la persona està en el moodle antic
				if ( !$this->__donarBaixaMoodleAntic($shortname, $usuari) ) {
					// throw new Exception('',xxx);
				}
			}
			// Si PERENNE = '1' Donem de baixa l'alumne de l'aula oberta del campus
			if ( $perenne == '1' ) {
				// Si la persona està en el moodle nou
				if ( !$this->__donarBaixaMoodleNou($curs, $usuari) ) {
					// Si la persona està en el moodle antic
					if ( !$this->__donarBaixaMoodleAntic($curs, $usuari) ) {
						// throw new Exception('',xxx);
					}
				}
			}
		}

		/* ##############      Busquem dades internes de SMTP      ##############  */
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarParam"] ) ) {
			$stmt->bind_param("s", $tipus);

			$tipus = 'autentificacioConsultes';
			$stmt->execute();
			$stmt->bind_result($valor);
			$stmt->fetch();

			$autentificacioConsultes = explode('|',$valor);
			$usernameCons = $autentificacioConsultes[0];
			$passwordCons = $autentificacioConsultes[1];
			$nameUserCons = $autentificacioConsultes[2];

			$tipus = 'autentificacioSecretaria';
			$stmt->execute();
			$stmt->bind_result($valor);
			$stmt->fetch();

			$autentificacioSecretaria = explode('|',$valor);
			$usernameSecre = $autentificacioSecretaria[0];
			$passwordSecre = $autentificacioSecretaria[1];
			$nameUserSecre = $autentificacioSecretaria[2];

			$conWeb->closeStmt();
		}
		else
			throw new Exception('',4496);

		/* ##############         Enviem missatge al tutor         ##############  */
		/* Si el curs ha acabat i no han passat els 7 dies,
		enviem missatge al tutor de confirmació */
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarPersonal"] ) ) {
			$stmt->bind_param("s", $dniTutor);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($nomTutor, $cognomsTutor, $mailPrsimaTutor, $mailTutor);
				$stmt->fetch();
				echo "<strong style='color: #e91e63'>######  Enviem missatge al tutor de confirmació ######</strong><br />";

				$date1 = new DateTime("now");
				$date2 = new DateTime($dataf);
				$diff = $date1->diff($date2);
				echo $diff->invert == 0;
				echo ($diff->invert==1 && $diff->days <= 7 );

				if ( $diff->invert == 0 || ($diff->invert==1 && $diff->days <= 7 ) ) {
					$to = $mailPrsimaTutor;

					echo "enviem un missatge al tutor2<br />";
					echo $to;

					$subject = "Baixa d'un alumne/a: ".$nom." ".$cognoms;
					require_once 'Date.php';
					$objDataI = new Date($datai);
					$dataLlargaInici = $objDataI->getDataLlarga();

					$missatge = "<p>Hola ".$nomTutor.",</p>
					<p>T'informem que l'alumne/a <strong>".$nom." ".$cognoms."</strong>
					s'ha donat de baixa del curs <strong style='color: ".$this->colors_destacats["msgDestacatCorreu1"]."'>".$nomCurs." - Aula ".$aula."</strong>
					que comença ".$objDataI->getPronomEl()."<strong>".$objDataI->getDataLlarga()."</strong>.</p>";
					$missatge .= "<p>Salutacions,</p>";
					echo $missatge;

					$qui = $this->usuari->getNom()->get()." ".$this->usuari->getCognom()->get();
					$depart = $this->usuari->getDepart()->get();

					require_once "MailSMTPComvive.php";

					$nomFromHead = $nameUserCons;
					$correuFromHead = $usernameCons;
					$nomReplyHead = $nameUserCons;
					$correuReplyHead = $usernameCons;

					$nomTo = "PrisMa Secretaria";
					$correuTo = "resguard.secretaria@prisma.cat";
					$correuTo = "meriem.prisma.cat@gmail.com";

					//enviar un email  de confirmacio a la persona que ha fet la compra
					$mailAlumne = new MailSMTPComvive($usernameCons, $passwordCons, $nomFromHead, $correuFromHead,
														$nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
														$subject, $missatge, $qui, $depart);

					$nomTo = $nomTutor;
					$correuTo = $to;
					$correuTo = "meriem.prisma.cat@gmail.com";

					//enviar un email  de confirmacio a la persona que ha fet la compra
					$mailAlumne = new MailSMTPComvive($usernameCons, $passwordCons, $nomFromHead, $correuFromHead,
														$nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
														$subject, $missatge, $qui, $depart);
				}
			}
			else //no existeix el tutor/a a la taula personal
				throw new Exception('',4499);
			$conWeb->closeStmt();
		}
		else
			throw new Exception('',4495);

		/* ############## Donem de baixa del registre d'inscripció ##############  */
		$this->__donarBaixaRegistreInscripcions( $id, $motiuBaixa );

		$conWeb->desconectarBD();

		/* ##############           Construïm missatges           ##############  */
		$dateNow = new DateTime("now");
		$dataAct = $dateNow->format('d-m-Y H:i');

		$subject = "Confirmació de baixa de curs";
		$subjectCopiaResguard = "Confirmació de baixa de curs ".$dataAct;

		require_once 'Date.php';

		$objDataI = new Date($datai);
		$dataILlarga = $objDataI->getDataLlarga();

		$missatge = "​<p>Benvolgut/da ".$nom.",</p>
		<p>Fa uns dies ens vam posar en contacte amb tu perquè no havíem rebut el pagament corresponent a la teva inscripció en el curs ​
		<strong style='color: ".$this->colors_destacats["msgDestacatCorreu1"]."'>".$titol."</strong>,
		que va començar ".$objDataI->getPronomEl()."<strong>".$objDataI->getDataLlarga()."</strong>.
		En no haver rebut ni cap resposta ni el pagament dins el termini establert, hem hagut de donar-te de baixa del curs.</p>
		<p>Si decideixes reprendre’l, estarem encantats de comptar amb tu.
		Contacta amb nosaltres a <a href='mailto:gestio@prisma.cat' style='font-weight: bold; text-decoration: none;
		color: ".$this->colors_destacats["msgDestacatCorreu1"]."'>gestio@prisma.cat</a>
		des del correu electrònic <a
		href='mailto:".$correu."' style='font-weight: bold; text-decoration: none;
		color: ".$this->colors_destacats["msgDestacatCorreu1"]."'>".$correu."</a>
		per formalitzar el pagament i que t’hi tornem a donar accés, o també et pots inscriure en una propera edició.</p>
		<p>Per a qualsevol dubte, escriu-nos i t’ajudarem en el que necessitis.</p>
		<p>Gràcies, i esperem veure’t aviat!</p>
		​<p>Atentament,</p>";

		echo $missatge;

		/* ##############            Enviem missatges            ##############  */
		$qui = $this->usuari->getNom()->get()." ".$this->usuari->getCognom()->get();
		$depart = $this->usuari->getDepart()->get();

		$nomFromHead = $nameUserSecre;
		$correuFromHead = $usernameSecre;
		$nomReplyHead = $nameUserSecre;
		$correuReplyHead = $usernameSecre;

		require_once "MailSMTPComvive.php";

		$nomTo = "PrisMa Secretaria";
		$correuTo = "resguard.secretaria@prisma.cat";
		$correuTo = "meriem.prisma.cat@gmail.com";

		//enviar un email de confirmacio a gestio@prisma.cat
		$mailCopiaResguard = new MailSMTPComvive($usernameSecre, $passwordSecre, $nomFromHead, $correuFromHead,
											$nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
											$subjectCopiaResguard, $missatge, $qui, $depart);

		$nomTo = $nameUserSecre;
		$correuTo = 'inscripcions@prisma.cat';
		$correuTo = "meriem.prisma.cat@gmail.com";

		//enviar un email de confirmacio a gestio@prisma.cat
		$mailInscripcions = new MailSMTPComvive($usernameSecre, $passwordSecre, $nomFromHead, $correuFromHead,
											$nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
											$subject, $missatge, $qui, $depart);

		$nomTo = $nom;
		$correuTo = $correu;
		$correuTo = "meriem.prisma.cat@gmail.com";

		//enviar un email  de confirmacio a la persona que ha fet la compra
		$mailAlumne = new MailSMTPComvive($usernameSecre, $passwordSecre, $nomFromHead, $correuFromHead,
											$nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
											$subject, $missatge, $qui, $depart);

		$mostrar = 'OK';

		return $mostrar;
	}

	/* ############################## ULTIM REC.  ############################## */

	public function __mostrarPage_Inici_Facturacio_Recordatori_Pagament($idFuncio, $idApartatFuncio) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();
		$conWeb2 = new ConnexioWeb();
		$conWeb2->connectarBD();

		$trobat = 0;
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["cnsCursosRecordarPag"] ) ) {
			if ( $stmt2=$conWeb2->prepare( $this->consultesBD_Web["cnsAlumnesRecordarPag"] ) ) {
				$stmt2->bind_param("dss", $anyCons, $mesCons, $cursCons);
				$stmt->execute();
				$stmt->store_result();
				if ( $stmt->num_rows() > 0 ) {
					$stmt->bind_result($any, $mes, $curs);
					while ( $stmt->fetch() && !$trobat) {
						$anyCons = $any;
						$mesCons = $mes;
						$cursCons = $curs;
						$stmt2->execute();
						$stmt2->store_result();
						if ( $stmt2->num_rows() > 0 ) {
							$button = "<p>Hi han persones per recordar-lis el pagament.</p>
							<button id='recordatori-pagament-".$idApartatFuncio."' class='rec-pag boto-blau mt-2 px-4 d-flex'>Recorda pagament (fi de curs)</button>";
							$trobat = 1;
						}
						else {
							$button = "<p class='text-center'>No hi ha resultats.</p>";
						}
					}
					$conWeb2->closeStmt();
					$conWeb->closeStmt();
				}
				else {
					$button = "<p class='text-center'>No hi ha resultats.</p>";
				}
			}
			else {
				throw new Exception('', 4509);
			}
		}
		else {
			throw new Exception('', 4510);
		}

		$conWeb2->desconectarBD();
		$conWeb->desconectarBD();

		return $button;
	}

	/**
	* @brief Mostra una taula amb tota la informació necessària per la consulta «Recordatori de pagament»
	* @return Mostra una taula amb tota la informació necessària per la consulta «Recordatori de pagament»
	*/
	public function __mostrarPage_Facturacio_Recordatori_Pagament($nomFuncio, $descFuncio, $orderBy, $asc) {
		$button = "<button id='confirma-reclamacio' role='button' class='boto-blau mt-3 mb-2 px-4 d-flex'>
			Envia reclamacions <i class='material-icons ms-1'>send</i>
		</button>";
		$llegenda = "<div class='my-3 p-3 bg-body rounded shadow-sm'>
		 <h5 class='border-bottom pb-2 mb-0 text-uppercase text-center fw-bold'>Llegenda de colors</h5>
		 <div clas='d-flex flex-column flex-md-row flex-wrap'>
			 <div class='d-flex border-bottom text-body-secondary pt-3 pb-2'>
				".$this->__getLabelTypeInsc('', 'I', '')."
				<p class='mb-0 lh-sm align-items-center'><strong class='d-block text-gray-dark'>Inscripció normal</strong>Paga la persona</p>
			 </div>
			 <div class='d-flex border-bottom text-body-secondary pt-3 pb-2'>
				".$this->__getLabelTypeInsc('', '', 'x')."
				<p class='mb-0 lh-sm align-items-center'><strong class='d-block text-gray-dark'>Entitat</strong>Paga l'entitat (el camp entitat esta omplert)</p>
			 </div>
			 <div class='d-flex border-bottom text-body-secondary pt-3 pb-2'>
				".$this->__getLabelTypeInsc('', 'P', '')."
				<p class='mb-0 lh-sm align-items-center'><strong class='d-block text-gray-dark'>Pack</strong>Paga la persona</p>
			 </div>
			 <div class='d-flex border-bottom text-body-secondary pt-3 pb-2'>
				".$this->__getLabelTypeInsc('', 'G', '')."
				<p class='mb-0 lh-sm align-items-center'><strong class='d-block text-gray-dark'>Grup</strong>Paga el responsable de grup</p>
			 </div>
			 <div class='d-flex border-bottom text-body-secondary pt-3 pb-2'>
				".$this->__getLabelTypeInsc('', 'R', '')."
				<p class='mb-0 lh-sm align-items-center'><strong class='d-block text-gray-dark'>Regal</strong>Paga la persona</p>
			 </div>
		 </div>
	 </div>";
		$table = $this->__mostrarPage_Facturacio_Recordatori_Pagament_contingut($orderBy, $asc);
		if ( $table == '' ) {
			$table = "<p class='text-center'>No hi ha resultats.</p>";
			$button = '';
			$llegenda = '';
		}

		$mostrar = "<div id='recordatori' class='card card-blau mt-5 d-flex flex-column justify-content-center align-items-center pb-5'>
			<div class='d-flex flex-column justify-content-center align-items-center w-100 text-center border-bottom card-header'>
				<p class='title fw-bold text-center py-3 mb-0 align-items-center
				justify-content-center d-flex'>".$nomFuncio."</p>
			</div>
			<div class='card-body px-0 pb-0 w-100 ps2'>
				<div class='d-flex flex-column justify-content-center my-2'>
					".$table."
				</div>
			</div>
			".$button."
			".$llegenda."
		</div>";

		return $mostrar;
	}

	/**
	* @brief Mostra una taula amb tota la informació necessària per la consulta «Recordatori de pagament»
	* @return Mostra una taula amb l'any, el mes, el curs, el nom, els cognoms,
	*			 els diners pendents, el camp reclamació, la data de Reclamació
	*			 les observacions de pagament i un label MARCAT de totes les persones
	*			 que no han pagat i el curs ha finaltzat fa 3 dies i menys d'una setmana
	*/
	public function __mostrarPage_Facturacio_Recordatori_Pagament_contingut($orderBy, $asc) {
		$table = "";
		$infoTable = "";
		$button = "";
		$resultats = []; $i = 0;

		$titolsInscr[0] = "Tipus";
		$titolsInscr[1] = "Any";
		$titolsInscr[2] = "Mes";
		$titolsInscr[3] = "Curs";
		$titolsInscr[4] = "Nom";
		$titolsInscr[5] = "Cognoms";
		$titolsInscr[6] = "Pendent";
		$titolsInscr[7] = "Reclamat";
		$titolsInscr[8] = "Data reclamat";
		$titolsInscr[9] = "Obs. pagament";
		$titolsInscr[10] = "Reclamar";

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();
		$conWeb2 = new ConnexioWeb();
		$conWeb2->connectarBD();
		//
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["cnsCursosRecordarPag"] ) ) {
			if ( $stmt2=$conWeb2->prepare( $this->consultesBD_Web["cnsAlumnesRecordarPag"] ) ) {
				$stmt2->bind_param("dss", $anyCons, $mesCons, $cursCons);
				$stmt->execute();
				$stmt->store_result();
				if ( $stmt->num_rows() > 0 ) {
					$stmt->bind_result($any, $mes, $curs);
					while ( $stmt->fetch() ) {
						$anyCons = $any;
						$mesCons = $mes;
						$cursCons = $curs;
						$stmt2->execute();
						$stmt2->store_result();
						if ( $stmt2->num_rows() > 0 ) {
							$stmt2->bind_result($idInsc, $dni, $nom, $cognoms, $correu, $apagar, $pagament,
							$pendent, $tipusInsc, $entitat, $dataReclamat, $reclamat, $obsPagament);
							while ( $stmt2->fetch() ) {
								$resultats[$i][0] = $idInsc;
								$resultats[$i][1] = $any;
								$resultats[$i][2] = $mes;
								$resultats[$i][3] = $curs;
								$resultats[$i][4] = $nom;
								$resultats[$i][5] = $cognoms;
								$resultats[$i][6] = $pendent;
								$resultats[$i][7] = $reclamat;
								$resultats[$i][8] = $dataReclamat;
								$resultats[$i][9] = $obsPagament;
								$resultats[$i][10] = $tipusInsc;
								$resultats[$i][11] = $entitat;

								//Crem lablels segons el tipus inscripció i entitat
								$labelTipus = $this->__getLabelTypeInsc($idInsc, $tipusInsc, $entitat);
								// Marquem de color en els casos que s'han de tenir controlats (entitas i grups)
								$classAccess = $this->__getColorTrCont_Recordatori_Pagament($tipusInsc, $entitat);
								// creem un label amb els diners pendents
								$labelPendent = $this->obtenirLabel('', 'red fw-bold', $pendent." €");

								if ( $dataReclamat != null) {
									require_once 'Date.php';
									$objData = new Date($dataReclamat);
									$dateReclamat = $objData->getDataFomatDDMMYYYY();
								}
								else $dateReclamat = '';

								$buttonValidar = 	$this->obtenirLabel('reclamar-'.$idInsc, 'lightGreen marcat pointer w-100', 'SÍ'.$this->obtenirIconaMaterials('', '', 'sentiment_satisfied_alt', 'dona de baixa'));

								$infoTable .= "<tr ".$classAccess.">
									".$this->mostrarFilaTaulaResponsive($titolsInscr[0], $labelTipus)."
									".$this->mostrarFilaTaulaResponsive($titolsInscr[1], $any)."
									".$this->mostrarFilaTaulaResponsive($titolsInscr[2], $mes)."
									".$this->mostrarFilaTaulaResponsive($titolsInscr[3], $curs)."
									".$this->mostrarFilaTaulaResponsive($titolsInscr[4], $nom)."
									".$this->mostrarFilaTaulaResponsive($titolsInscr[5], $cognoms)."
									".$this->mostrarFilaTaulaResponsive($titolsInscr[6], $labelPendent)."
									".$this->mostrarFilaTaulaResponsive($titolsInscr[7], $reclamat)."
									".$this->mostrarFilaTaulaResponsive($titolsInscr[8], $dateReclamat)."
									".$this->mostrarFilaTaulaResponsive($titolsInscr[9], $obsPagament)."
									".$this->mostrarFilaTaulaResponsive($titolsInscr[10], $buttonValidar)."
								</tr>";

								$i++;
							}
						}
						else {
							$table = "";
						}
					}
					$conWeb2->closeStmt();
					$conWeb->closeStmt();
				}
				else {
					$table = "";
				}
			}
			else {
				throw new Exception('', 4508);
			}
		}
		else {
			throw new Exception('', 4507);
		}

		$conWeb2->desconectarBD();
		$conWeb->desconectarBD();

		$classes = ['', '', '', ''];

		if ( $orderBy != '' ) {

			if ($orderBy == 'codi') $cntOrderBy = 0;
			else if ($orderBy == 'nom') $cntOrderBy = 1;
			else if ($orderBy == 'cog') $cntOrderBy = 2;

			if ($asc == 1) { //s'ordena ascendentment
				$inici = 0;
				$fi = count($resultats);
				$i = $inici;
				$condicio = $i < $fi;

				$classes[$cntOrderBy] = ' asc';
			}
			else { //s'ordena dsscendentment
				$inici = count($resultats);
				$fi = 0;
				$i = $inici-1;
				$condicio = $i >= $fi;

				$classes[$cntOrderBy] = ' desc';
			}
		}

		if ( count($resultats) > 0 ) {

			$table .= "<table class='table table-striped table-hover table-order table-xl-responsive text-center mt-2 mb-0'>
			<thead><tr>
				<th>".$titolsInscr[0]."</th>
				<th>".$titolsInscr[1]."</th>
				<th>".$titolsInscr[2]."</th>
				<th id='th-codi' class='sorting".$classes[0]."'>".$titolsInscr[3]."</th>
				<th id='th-nom' class='sorting".$classes[1]."'>".$titolsInscr[4]."</th>
				<th id='th-cog' class='sorting".$classes[2]."'>".$titolsInscr[5]."</th>
				<th>".$titolsInscr[6]."</th>
				<th>".$titolsInscr[7]."</th>
				<th>".$titolsInscr[8]."</th>
				<th>".$titolsInscr[9]."</th>
				<th>".$titolsInscr[10]."</th>
			</tr></thead>
			<tbody>";
			if ( $orderBy != '' )
				$infoTable = $this->__mostrarResultatsrRecordatoriPagamentOrdenatsPerUnCamp($titolsInscr, $resultats, $orderBy, $asc);
			$table .= $infoTable;
			$table .= "</tbody></table>";
		}
		else {
			$table = "";
		}
		return $table;
	}

	/**
	* @brief Mostra una taula amb tota la informació necessària per la consulta «Recordatori de pagament»
	* @return Mostra una taula amb l'any, el mes, el curs, el nom, els cognoms,
	*			 els diners pendents, el camp reclamació, la data de Reclamació
	*			 les observacions de pagament i un label MARCAT de l'array resultats
	*			 amb la ordenació que dictamini $order i si $asc = 1, la ordenació és ascendent.
	*
	*/
	public function __mostrarResultatsrRecordatoriPagamentOrdenatsPerUnCamp($titolsInscr, $resultats, $orderBy, $asc) {
		function cmpCodi($a, $b) {
			 if ($a[3] == $b[3]) {
				if ($a[1] == $b[1]) {
					if ($a[2] == $b[2]) {
						if ($a[5] == $b[5]) {
							 return 0;
						}
						return ($a[5] < $b[5]) ? -1 : 1;
				  }
				  return ($a[2] < $b[2]) ? -1 : 1;
				}
				return ($a[1] < $b[1]) ? -1 : 1;
			 }
			 return ($a[3] < $b[3]) ? -1 : 1;
		}

		function cmpNom($a, $b) {
			 if ($a[4] == $b[4]) {
				if ($a[5] == $b[5]) {
					if ($a[1] == $b[1]) {
					  if ($a[2] == $b[2]) {
								return 0;
					 }
					 return ($a[2] < $b[2]) ? -1 : 1;
				  }
				  return ($a[1] < $b[1]) ? -1 : 1;
				}
				return ($a[5] < $b[5]) ? -1 : 1;
			 }
			 return ($a[4] < $b[4]) ? -1 : 1;
		}

		function cmpCognoms($a, $b) {
			 if ($a[5] == $b[5]) {
				 if ($a[1] == $b[1]) {
					if ($a[2] == $b[2]) {
						if ($a[3] == $b[3]) {
							 return 0;
						}
						return ($a[3] < $b[3]) ? -1 : 1;
				  }
				  return ($a[2] < $b[2]) ? -1 : 1;
				}
				return ($a[1] < $b[1]) ? -1 : 1;
			 }
			 return ($a[5] < $b[5]) ? -1 : 1;
		}

		$cntOrderBy = 0;
		if ($orderBy == 'codi') { usort($resultats, "cmpCodi"); $cntOrderBy = 0; }
		else if ($orderBy == 'nom') { usort($resultats, "cmpNom"); $cntOrderBy = 1; }
		else if ($orderBy == 'cog') { usort($resultats, "cmpCognoms"); $cntOrderBy = 2; }

		$classes = ['', '', '', ''];

		if ( $orderBy != '' ) {

			if ($asc == 1) { //s'ordena ascendentment
				$inici = 0;
				$fi = count($resultats);
				$i = $inici;
				$condicio = $i < $fi;

				$classes[$cntOrderBy] = 'asc';
			}
			else { //s'ordena dsscendentment
				$inici = count($resultats);
				$fi = 0;
				$i = $inici-1;
				$condicio = $i >= $fi;

				$classes[$cntOrderBy] = 'desc';
			}
		}

		$table = '';
		while ( $condicio ) {
			$idInsc = $resultats[$i][0];
			$any = $resultats[$i][1];
			$mes = $resultats[$i][2];
			$curs = $resultats[$i][3];
			$nom = $resultats[$i][4];
			$cognoms = $resultats[$i][5];
			$pendent = $resultats[$i][6];
			$reclamat = $resultats[$i][7];
			$dataReclamat = $resultats[$i][8];
			$obsPagament = $resultats[$i][9];
			$tipusInsc = $resultats[$i][10];
			$entitat = $resultats[$i][11];

			//Crem lablels segons el tipus inscripció i entitat
			$labelTipus = $this->__getLabelTypeInsc($idInsc, $tipusInsc, $entitat);
			// Marquem de color en els casos que s'han de tenir controlats (entitas i grups)
			$classAccess = $this->__getColorTrCont_Recordatori_Pagament($tipusInsc, $entitat);
			// creem un label amb els diners pendents
			$labelPendent = $this->obtenirLabel('', 'red fw-bold', $pendent." €");

			if ( $dataReclamat != null) {
				$objData = new Date($dataReclamat);
				$dateReclamat = $objData->getDataFomatDDMMYYYY();
			}
			else $dateReclamat = '';

			$buttonValidar = 	$this->obtenirLabel('reclamar-'.$idInsc, 'lightGreen marcat pointer w-100', 'SÍ'.$this->obtenirIconaMaterials('', '', 'sentiment_satisfied_alt', 'dona de baixa'));

			$table .= "<tr ".$classAccess.">
				".$this->mostrarFilaTaulaResponsive($titolsInscr[0], $labelTipus)."
				".$this->mostrarFilaTaulaResponsive($titolsInscr[1], $any)."
				".$this->mostrarFilaTaulaResponsive($titolsInscr[2], $mes)."
				".$this->mostrarFilaTaulaResponsive($titolsInscr[3], $curs)."
				".$this->mostrarFilaTaulaResponsive($titolsInscr[4], $nom)."
				".$this->mostrarFilaTaulaResponsive($titolsInscr[5], $cognoms)."
				".$this->mostrarFilaTaulaResponsive($titolsInscr[6], $labelPendent)."
				".$this->mostrarFilaTaulaResponsive($titolsInscr[7], $reclamat)."
				".$this->mostrarFilaTaulaResponsive($titolsInscr[8], $dateReclamat)."
				".$this->mostrarFilaTaulaResponsive($titolsInscr[9], $obsPagament)."
				".$this->mostrarFilaTaulaResponsive($titolsInscr[10], $buttonValidar)."
			</tr>";

			if ( $asc == 1 ) {
				$i++;
				$condicio = $i < $fi;
			}
			else {
				$i--;
				$condicio = $i >= $fi;
			}
		}
		return $table;
	}

	/**
	* @brief Crem lablels segons el tipus inscripció i entitat
	* @return
	*/
	private function __getLabelTypeInsc($idInsc, $tipusInsc, $entitat) {
		$label = '';

		if ( $entitat != null || $entitat != '' ) {
			// és una entitat
			$classTipus = "lightRose";
			if ( $idInsc != '' ) $idInsc = 'label-insc-'.$idInsc.'-'.$tipusInsc;
			$iconTipus = $this->obtenirIconaMaterials($idInsc, '', 'corporate_fare', 'Entitat');
		}
		else {
			if ( $tipusInsc == 'I' ) {
				// és una inscripció
				$classTipus = "lightBlue"; $idInsc = '';
				$iconTipus = $this->obtenirIconaMaterials('', '', 'person', 'Inscripció normal');
			}
			else if ( $tipusInsc == 'P' ) {
				// és un pack
				$classTipus = "lightPurple"; $idInsc = '';
				$iconTipus = $this->obtenirIconaFontAw('', 'fas', 'fa-cubes', '');
			}
			else if ( $tipusInsc == 'G' ) {
				// és un grup
				$classTipus = "lightOrange";
				if ( $idInsc != '' ) $idInsc = 'label-insc-'.$idInsc.'-'.$tipusInsc;
				$iconTipus = $this->obtenirIconaMaterials($idInsc, '', 'group', 'Inscripció grupal');
			}
			else if ( $tipusInsc == 'R' ) {
				// és un grup
				$classTipus = "lightGreen"; $idInsc = '';
				$iconTipus = $this->obtenirIconaFontAw('', 'fas', 'fa-gift', '');
			}
		}

		$label = $this->obtenirLabel($idInsc, $classTipus." mx-2", $iconTipus);

		return $label;
	}

	/**
	* @brief Marquem de color en els casos que s'han de tenir controlats (entitas i grups)
	* @return classe Una variable que preten definir un color. Si TipusInsc == 'G' o $entitat != null, retornara 'control'
	*/
	public function __getColorTrCont_Recordatori_Pagament($tipusInsc, $entitat) {
		if ( ( $entitat != null || $entitat != '' ) || $tipusInsc == 'G' ) {
			$classe = "class='text-danger'";
		}
		else $classe = '';
		return $classe;
	}

	/**
	* @brief Enviem recordatori de pagament a la persona amb id inscripcio $id
	* @return Enviem recordatori de pagamen a la persona amb id inscripció.
	*			 Si el tipus d'inscripció és G o la entitat no esta buida, s'envia a la persona de contacte
	*/
	public function updateSendMsg_Facturacio_Recordatori_Pagament($id) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		/* ##############  Busquem la informacio de la inscripcio  ############## */

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarInfoMostraInfo"] ) ) {
			$stmt->bind_param("d", $id);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($any, $mes, $curs, $aula, $nom, $cognoms, $dni, $correu,
				$telefon, $adreca, $cp, $poblacio, $perfil, $titulacio, $datainsc,
				$inscrit, $tipusInsc, $inscao, $inscmail, $certificat, $obscertificat,
				$generat, $obs, $comentaris, $databaixa, $motiubaixa, $quibaixa, $apagar,
				$pagament, $datapag, $idpag, $pagObs, $comHaPagat, $entitat, $fraccio,
				$comFraccio, $factura, $datarec, $reclamat, $usuari);
				$stmt->fetch();
			}
			else
				throw new Exception('',4506);
			$conWeb->closeStmt();
		}
		else
			throw new Exception('',4505);

		/* ##############      Busquem la informacio del curs      ############## */
		if ( $tipusInsc == 'T' ) {
			// Buscar la informació a la taula info_taller
			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarInfoTaller"] ) ) {
				$stmt->bind_param("dss", $any, $mes, $curs);
				$stmt->execute();
				$stmt->store_result();
				if ($stmt->num_rows() > 0) {
					$stmt->bind_result($datai, $hores, $idPreu);
					$stmt->fetch();
					$conWeb->closeStmt();
				}
				else {
					$conWeb->closeStmt();
				}
			}
			else {
				throw new Exception('',4504);
			}
		}
		else {
			// Buscar la informació a la taula curs
			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarCursSegEd"] ) ) {
				$stmt->bind_param("dss", $any, $mes, $curs);
				$stmt->execute();
				$stmt->store_result();
				if ($stmt->num_rows() > 0) {
					$stmt->bind_result($titol, $datai, $dataf, $hores, $idPreu);
					$stmt->fetch();
					$conWeb->closeStmt();
				}
				else {
					$conWeb->closeStmt();
				}
			}
			else {
				throw new Exception('',4503);
			}
		}

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarParam"] ) ) {
			$stmt->bind_param("s", $parametre);
			$parametre = "keyEncriptar";
			$stmt->execute();
			$stmt->store_result();
			if ( $stmt->num_rows() > 0 ) {
				$stmt->bind_result($keyEncr);
				$stmt->fetch();
			}
			else {
				throw new Exception('', 4502);
			}
		}
		else {
			throw new Exception('', 4501);
		}
		$conWeb->closeStmt();

		/* ##############     Update data_reclamació, pag_obs     ##############  */
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["updClaimRecPag"] ) ) {
			$stmt->bind_param("ssd", $pagObsM, $reclamatM, $id);
			$pagObsM = $pagObs;
			if ( $pagObs != '' ) $pagObsM .= ". ";
			$pagObsM .= "Reclamat fi de curs";
			$reclamatM = $reclamat;
			if ( $reclamatM != '' ) $reclamatM .= ". ";
			$reclamatM .= "Reclamat fi de curs";
			echo "actualitzar reclamat ".$pagObsM." ".$reclamatM." ".$id."<br />";
			$stmt->execute();
			$conWeb->closeStmt();
			$mostrar = 'OK';
		}
		else
			throw new Exception('',4500);

		/* ##############      Busquem dades internes de SMTP      ##############  */
		$authGest = $this->getAuthSMTP_Gestio();
		$userGest = $authGest[0];
		$passGest = $authGest[1];
		$nameUserGest = $authGest[2];
		echo "0<br />";

		/* ##############           Construïm missatges           ##############  */
		$dateNow = new DateTime("now");
		$dataAct = $dateNow->format('d-m-Y H:i');

		$subject = "Recordatori pagament pendent. ".$titol;
		$subjectCopiaResguard = "Recordatori pagament pendent.  ".$titol." ".$dataAct;

		require_once 'Date.php';

		$objDataF = new Date($dataf);
		$dataFLlarga = $objDataF->getDataLlarga();

		echo "1<br />";

		$cipher = "AES-128-CBC";
		$ivlen = openssl_cipher_iv_length($cipher);
		$iv = openssl_random_pseudo_bytes($ivlen);
		$ciphertext_raw = openssl_encrypt($idpag, $cipher, $keyEncr, $options=OPENSSL_RAW_DATA, $iv);
		$hmac = hash_hmac('sha256', $ciphertext_raw, $keyEncr, $as_binary=true);
		$hashIdPag = base64_encode( $iv.$hmac.$ciphertext_raw );
		echo "2<br />";

		if ( $tipusInsc == 'G' || $tipusInsc == 'P' ) $urlIdPag = "https://www.prisma.cat/pagaments/";
		else $urlIdPag = "https://www.prisma.cat/pagament/";

		$urlIdPag .= $hashIdPag;

		$objDataPag = new Date($dataf);
		$objDataPag->addDays(3);
		echo "3<br />";

		$pendent = $apagar - $pagament;

		require_once 'Template.php';
		$templates = new Template();
		$msg = $templates->getTemplate_Inscripcions_Pagaments_MissatgeTextManeresPagar();
		$names_template = array("[URL_PAGAMENT]", "[TITOL]", "[CODI_CURS]", "[MES]");
		$names_function   = array($urlIdPag, $titol, $curs, $mes);
		$textManeresPagar = str_replace($names_template, $names_function, $msg);

		// $textManeresPagar ="
		// <ul style='list-style: square; margin-bottom: 20px; margin-left: 30px; padding: 0;'>
		// 	<li style='margin-top: 8px; line-height: 24px;'>
		// 		TARGETA: clica a l'enllaç següent (cal que tinguis activat el codi
		// 		de compra segura facilitat per la teva entitat bancària):
		// 		<a href='$urlIdPag' title='Pagament del curs ".$titol."'>".$urlIdPag."</a>.
		// 	</li>
		// 	<li style='margin-top: 8px; line-height: 24px;'>
		// 		TRANSFERÈNCIA o INGRÉS BANCARI: indica clarament el concepte
		// 		<strong>«".$curs."-".$mes."+ el número
		// 		del teu NIF/NIE/passaport»</strong>, en qualsevol dels comptes següents:
		// 		<ul style='list-style: circle; margin-left: 30px; padding: 0;'>
		// 			<li style='margin-top: 8px; line-height: 24px;'>La Caixa: ES30 2100 4279 21 2200080678 </li>
		// 			<li style='margin-top: 8px; line-height: 24px;'>BBVA: ES04 0182 5117 00 0201534816</li>
		// 		</ul>
		// 	</li>
		// </ul>
		// <p>Un cop hagis realitzat el pagament és important que conservis el
		// justificant bancari fins que t'arribi un correu electrònic que confirmi
		// que l'hem rebut correctament.</p>";
		echo "4<br />";

		if ( ( $entitat != null && $entitat != '' ) || $tipusInsc == 'G' ) {
			if ( $entitat != null && $entitat != '' ) {
				//Busco el responsable de l'entitat
				$conIntra = new ConnexioIntranet();
				$conIntra->connectarBD();

				if ( $stmt=$conIntra->prepare( $this->consultesBD_Intra["buscarRespEntitatByCIF"] ) ) {
					$stmt->bind_param("s", $entitat);
					$stmt->execute();
					$stmt->store_result();
					if ( $stmt->num_rows() > 0 ) {
						$stmt->bind_result($nomEnt, $nomRespEnt, $cogRespEnt, $correuRespEnt);
						$stmt->fetch();
					}
					$conIntra->closeStmt();
				}

				//Buscar el nom, cognoms del responsable
				$nomEnviar = $nomRespEnt;
				$cogEnviar = $cogRespEnt;
				$correuEnviar = $correuRespEnt;
			}
			else {
				//Busco el responsable de l'entitat
				if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarPersRespGrup"] ) ) {
					$stmt->bind_param("d", $idpag);
					$stmt->execute();
					$stmt->store_result();
					if ($stmt->num_rows() > 0) {
						$stmt->bind_result($nomResp, $cognomsResp, $dniResp, $emailResp,
							$adrecaResp, $cpResp, $pobleResp, $factRel, $fracc, $fraccio, $apagarTotal, $importPagatTotal);
						$stmt->fetch();
					}
					$conWeb->closeStmt();
				}
				//Buscar el nom, cognoms del responsable
				$nomEnviar = $nomResp;
				$cogEnviar = $cognomsResp;
				$correuEnviar = $emailResp;
			}
			$msgInfo = "<p>Et recordem que el proper <strong>".$objDataF->getDataLlarga()."</strong>
			finalitza el curs <strong style='color: ".$this->colors_destacats["msgDestacatCorreu1"]."'>".$titol."</strong> i continuem sense haver rebut el
			pagament de l'alumne <strong>".$nom." ".$cognoms."</strong>.
			T’agrairiem que et poses <strong>en contacte amb nosaltres</strong> com més aviat millor.</p>";

			$textPagament = "	<p>Pots fer el pagament que falta a través de l'enllaç següent:</p>
			".$urlIdPag." ";
		}
		else {
			$nomEnviar = $nom;
			$cogEnviar = $cognoms;
			$correuEnviar = $correu;

			$msgInfo = "<p>Et recordem que el proper <strong>".$objDataF->getDataLlarga()."</strong>
			finalitza el curs <strong style='color: ".$this->colors_destacats["msgDestacatCorreu1"]."'>".$titol."</strong>.
			Si passats tres dies d'aquesta data (".$objDataPag->getPronomEl()."<strong>".$objDataPag->getDataLlarga()."</strong>) continuem sense haver rebut els
			<strong>".$pendent." euros</strong> que hi falten per fer-ne efectiu el pagament complet, deixaràs de tenir accés al curs i no podrem tramitar-te'n el certificat.</p>";

			$textPagament = "	<p>Pots fer el pagament que falten escollint una de les opcions següents:</p>
			".$textManeresPagar;
		}
		$missatge = "​<p>Benvolgut/da ".$nomEnviar.",</p>
		".$msgInfo."
		".$textPagament."
		<p>Per a qualsevol consulta, posa't en contacte amb el Departament de Gestió,
		ja sigui per telèfon al 972 21 75 65 o bé per correu electrònic a
		<a href='mailto:gestio@prisma.cat' style='font-weight: bold; text-decoration: none;
		color: ".$this->colors_destacats["msgDestacatCorreu1"]."'>gestio@prisma.cat</a> a través del correu electrònic <a
		href='mailto:".$correuEnviar."' style='font-weight: bold; text-decoration: none;
		color: ".$this->colors_destacats["msgDestacatCorreu1"]."'>".$correuEnviar."</a>.</p>
		<p>Salutacions ben cordials,</p>";

		echo $missatge;

		/* ##############            Enviem missatges            ##############  */
		$qui = $this->usuari->getNom()->get()." ".$this->usuari->getCognom()->get();
		$depart = $this->usuari->getDepart()->get();

		$nomFromHead = $nameUserGest;
		$correuFromHead = $userGest;
		$nomReplyHead = $nomEnviar." ".$cogEnviar;
		$correuReplyHead = $correuEnviar;

		require_once "MailSMTPComvive.php";

		$nomTo = "PrisMa Gestió";
		$correuTo = "resguard.gestio@prisma.cat";

		//enviar un email de confirmacio a gestio@prisma.cat
		$mailCopiaResguard = new MailSMTPComvive($userGest, $passGest, $nomFromHead, $correuFromHead,
											$nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
											$subjectCopiaResguard, $missatge, $qui, $depart);

		$nomTo = $nomEnviar." ".$cogEnviar;
		$correuTo = $correuEnviar;
		$correuTo = "meriem.prisma.cat@gmail.com";

		//enviar un email  de confirmacio a la persona que ha fet la compra
		$mailAlumne = new MailSMTPComvive($userGest, $passGest, $nomFromHead, $correuFromHead,
											$nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
											$subject, $missatge, $qui, $depart);

		$mostrar = 'OK';

		return $mostrar;
	}

	/* ############################## RECLAMACIÓ FINAL  ############################## */

	public function __mostrarPage_Inici_Facturacio_BaixaMorosos($idFuncio, $idApartatFuncio) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();
		$conWeb2 = new ConnexioWeb();
		$conWeb2->connectarBD();

		$trobat = 0;
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["cnsCursosClaimBaixes"] ) ) {
			if ( $stmt2=$conWeb2->prepare( $this->consultesBD_Web["cnsAlumnClaimPag"] ) ) {
				$stmt2->bind_param("dss", $anyCons, $mesCons, $cursCons);
				$stmt->execute();
				$stmt->store_result();
				if ( $stmt->num_rows() > 0 ) {
					$stmt->bind_result($any, $mes, $curs);
					while ( $stmt->fetch() && !$trobat) {
						$anyCons = $any;
						$mesCons = $mes;
						$cursCons = $curs;
						$stmt2->execute();
						$stmt2->store_result();
						if ( $stmt2->num_rows() > 0 ) {
							$button = "<p>Hi han persones per reclamar-lis el pagament i donar-los de baixa.</p>
							<button id='final-claim-".$idApartatFuncio."' class='claim-pag boto-blau mt-2 px-4 d-flex'>Recorda pagament (fi de curs)</button>";
							$trobat = 1;
						}
						else {
							$button = "<p class='text-center'>No hi ha resultats.</p>";
						}
					}
					$conWeb2->closeStmt();
					$conWeb->closeStmt();
				}
				else {
					$button = "<p class='text-center'>No hi ha resultats.</p>";
				}
			}
			else {
				throw new Exception('', 4512);
			}
		}
		else {
			throw new Exception('', 4514);
		}

		$conWeb2->desconectarBD();
		$conWeb->desconectarBD();

		return $button;
	}

