	public function __mostrarPage_Facturacio_BaixaMorosos_contingut($orderBy, $asc) {
		$table = "";
		$infoTable = "";
		$button = "";
		$resultats = []; $i = 0;

		$titolsInscr[0] = "Tipus";
		$titolsInscr[1] = "Any";
		$titolsInscr[2] = "Mes";
		$titolsInscr[3] = "Curs";
		$titolsInscr[4] = "Nom";
		$titolsInscr[5] = "Cognoms";
		$titolsInscr[6] = "Pendent";
		$titolsInscr[7] = "Reclamat";
		$titolsInscr[8] = "Data reclamat";
		$titolsInscr[9] = "Obs. pagament";
		$titolsInscr[10] = "Reclamar";

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();
		$conWeb2 = new ConnexioWeb();
		$conWeb2->connectarBD();
		//
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["cnsCursosClaimBaixes"] ) ) {
			if ( $stmt2=$conWeb2->prepare( $this->consultesBD_Web["cnsAlumnClaimPag"] ) ) {
				$stmt2->bind_param("dss", $anyCons, $mesCons, $cursCons);
				$stmt->execute();
				$stmt->store_result();
				if ( $stmt->num_rows() > 0 ) {
					$stmt->bind_result($any, $mes, $curs);
					while ( $stmt->fetch() ) {
						$anyCons = $any;
						$mesCons = $mes;
						$cursCons = $curs;
						$stmt2->execute();
						$stmt2->store_result();
						if ( $stmt2->num_rows() > 0 ) {
							$stmt2->bind_result($idInsc, $dni, $nom, $cognoms, $correu, $apagar, $pagament,
							$pendent, $tipusInsc, $entitat, $dataReclamat, $reclamat, $obsPagament, $certificat, $idpag);
							while ( $stmt2->fetch() ) {
								$resultats[$i][0] = $idInsc;
								$resultats[$i][1] = $any;
								$resultats[$i][2] = $mes;
								$resultats[$i][3] = $curs;
								$resultats[$i][4] = $nom;
								$resultats[$i][5] = $cognoms;
								$resultats[$i][6] = $pendent;
								$resultats[$i][7] = $reclamat;
								$resultats[$i][8] = $dataReclamat;
								$resultats[$i][9] = $obsPagament;
								$resultats[$i][10] = $tipusInsc;
								$resultats[$i][11] = $entitat;
								$resultats[$i][12] = $certificat;
								$resultats[$i][13] = $idpag;

								//Crem lablels segons el tipus inscripció i entitat
								if ( $tipusInsc != 'R' )
									$labelTipus = $this->__getLabelTypeInsc($idpag, $tipusInsc, $entitat);
								else
									$labelTipus = $this->__getLabelTypeInsc($idInsc, $tipusInsc, $entitat);

								if ( $certificat == 'no aprovat' ) {
									$labelAprovat = $this->obtenirLabel('', 'no_aprovat fw-bold my-1', "NO APROVAT");
								}
								else {
									$labelAprovat = $this->obtenirLabel('', 'aprovat fw-bold my-1', "APROVAT");
								}

								$labels = "<div class='d-flex flex-row justify-content-center align-items-center'>
									".$labelTipus.$labelAprovat."
								</div>";
								// Marquem de color en els casos que s'han de tenir controlats (entitas i grups)
								$classAccess = $this->__getColorTrCont_Recordatori_Pagament($tipusInsc, $entitat);
								// creem un label amb els diners pendents
								$labelPendent = $this->obtenirLabel('', 'red fw-bold', $pendent." €");

								if ( $dataReclamat != null) {
									require_once 'Date.php';
									$objData = new Date($dataReclamat);
									$dateReclamat = $objData->getDataFomatDDMMYYYY();
								}
								else $dateReclamat = '';

								$buttonValidar = 	$this->obtenirLabel('reclamar-'.$idInsc, 'lightGreen marcat pointer w-100', 'SÍ'.$this->obtenirIconaMaterials('', '', 'sentiment_satisfied_alt', 'dona de baixa'));

									$infoTable .= "<tr ".$classAccess.">
										".$this->mostrarFilaTaulaResponsive($titolsInscr[0], $labels)."
										".$this->mostrarFilaTaulaResponsive($titolsInscr[1], $any)."
										".$this->mostrarFilaTaulaResponsive($titolsInscr[2], $mes)."
										".$this->mostrarFilaTaulaResponsive($titolsInscr[3], $curs)."
										".$this->mostrarFilaTaulaResponsive($titolsInscr[4], $nom)."
										".$this->mostrarFilaTaulaResponsive($titolsInscr[5], $cognoms)."
										".$this->mostrarFilaTaulaResponsive($titolsInscr[6], $labelPendent)."
										".$this->mostrarFilaTaulaResponsive($titolsInscr[7], $reclamat)."
										".$this->mostrarFilaTaulaResponsive($titolsInscr[8], $dateReclamat)."
										".$this->mostrarFilaTaulaResponsive($titolsInscr[9], $obsPagament)."
										".$this->mostrarFilaTaulaResponsive($titolsInscr[10], $buttonValidar)."
									</tr>";
								$i++;
							}
						}
						else {
							$table = "";
						}
					}
					$conWeb2->closeStmt();
					$conWeb->closeStmt();
				}
				else {
					$table = "";
				}
			}
			else {
				throw new Exception('', 4511);
			}
		}
		else {
			throw new Exception('', 4513);
		}

		$conWeb2->desconectarBD();
		$conWeb->desconectarBD();

		$classes = ['', '', '', ''];

		if ( $orderBy != '' ) {

			if ($orderBy == 'codi') $cntOrderBy = 0;
			else if ($orderBy == 'nom') $cntOrderBy = 1;
			else if ($orderBy == 'cog') $cntOrderBy = 2;

			if ($asc == 1) { //s'ordena ascendentment
				$inici = 0;
				$fi = count($resultats);
				$i = $inici;
				$condicio = $i < $fi;

				$classes[$cntOrderBy] = ' asc';
			}
			else { //s'ordena dsscendentment
				$inici = count($resultats);
				$fi = 0;
				$i = $inici-1;
				$condicio = $i >= $fi;

				$classes[$cntOrderBy] = ' desc';
			}
		}

		if ( count($resultats) > 0 ) {
			$table .= "<p class='text-center'>S'han trobat <strong class='badge bg-pris fs-6 mx-1'>".$i."</strong> resultats.</p>";

			$table .= "<table class='table table-striped table-hover table-order table-xl-responsive text-center mt-2 mb-0'>
			<thead><tr>
				<th>".$titolsInscr[0]."</th>
				<th>".$titolsInscr[1]."</th>
				<th>".$titolsInscr[2]."</th>
				<th id='th-codi' class='sorting".$classes[0]."'>".$titolsInscr[3]."</th>
				<th id='th-nom' class='sorting".$classes[1]."'>".$titolsInscr[4]."</th>
				<th id='th-cog' class='sorting".$classes[2]."'>".$titolsInscr[5]."</th>
				<th>".$titolsInscr[6]."</th>
				<th>".$titolsInscr[7]."</th>
				<th>".$titolsInscr[8]."</th>
				<th>".$titolsInscr[9]."</th>
				<th>".$titolsInscr[10]."</th>
			</tr></thead>
			<tbody>";
			if ( $orderBy != '' )
				$infoTable = $this->__resultsLastClaimOrderBy($titolsInscr, $resultats, $orderBy, $asc);
			$table .= $infoTable;
			$table .= "</tbody></table>";
		}
		else {
			$table = "";
		}
		return $table;
	}

	/**
	* @brief Mostra una taula amb tota la informació necessària per la consulta «Reclamació i baixes»
	* @return Mostra una taula amb l'any, el mes, el curs, el nom, els cognoms,
	*			 els diners pendents, el camp reclamació, la data de Reclamació
	*			 les observacions de pagament i un label MARCAT de l'array resultats
	*			 amb la ordenació que dictamini $order i si $asc = 1, la ordenació és ascendent.
	*
	*/
	public function __resultsLastClaimOrderBy($titolsInscr, $resultats, $orderBy, $asc) {
		function cmpCodi($a, $b) {
			 if ($a[3] == $b[3]) {
				if ($a[1] == $b[1]) {
					if ($a[2] == $b[2]) {
						if ($a[5] == $b[5]) {
							 return 0;
						}
						return ($a[5] < $b[5]) ? -1 : 1;
				  }
				  return ($a[2] < $b[2]) ? -1 : 1;
				}
				return ($a[1] < $b[1]) ? -1 : 1;
			 }
			 return ($a[3] < $b[3]) ? -1 : 1;
		}

		function cmpNom($a, $b) {
			 if ($a[4] == $b[4]) {
				if ($a[5] == $b[5]) {
					if ($a[1] == $b[1]) {
					  if ($a[2] == $b[2]) {
								return 0;
					 }
					 return ($a[2] < $b[2]) ? -1 : 1;
				  }
				  return ($a[1] < $b[1]) ? -1 : 1;
				}
				return ($a[5] < $b[5]) ? -1 : 1;
			 }
			 return ($a[4] < $b[4]) ? -1 : 1;
		}

		function cmpCognoms($a, $b) {
			 if ($a[5] == $b[5]) {
				 if ($a[1] == $b[1]) {
					if ($a[2] == $b[2]) {
						if ($a[3] == $b[3]) {
							 return 0;
						}
						return ($a[3] < $b[3]) ? -1 : 1;
				  }
				  return ($a[2] < $b[2]) ? -1 : 1;
				}
				return ($a[1] < $b[1]) ? -1 : 1;
			 }
			 return ($a[5] < $b[5]) ? -1 : 1;
		}

		$cntOrderBy = 0;
		if ($orderBy == 'codi') { usort($resultats, "cmpCodi"); $cntOrderBy = 0; }
		else if ($orderBy == 'nom') { usort($resultats, "cmpNom"); $cntOrderBy = 1; }
		else if ($orderBy == 'cog') { usort($resultats, "cmpCognoms"); $cntOrderBy = 2; }

		$classes = ['', '', '', ''];

		if ( $orderBy != '' ) {

			if ($asc == 1) { //s'ordena ascendentment
				$inici = 0;
				$fi = count($resultats);
				$i = $inici;
				$condicio = $i < $fi;

				$classes[$cntOrderBy] = 'asc';
			}
			else { //s'ordena dsscendentment
				$inici = count($resultats);
				$fi = 0;
				$i = $inici-1;
				$condicio = $i >= $fi;

				$classes[$cntOrderBy] = 'desc';
			}
		}

		$table = '';
		while ( $condicio ) {
			$idInsc = $resultats[$i][0];
			$any = $resultats[$i][1];
			$mes = $resultats[$i][2];
			$curs = $resultats[$i][3];
			$nom = $resultats[$i][4];
			$cognoms = $resultats[$i][5];
			$pendent = $resultats[$i][6];
			$reclamat = $resultats[$i][7];
			$dataReclamat = $resultats[$i][8];
			$obsPagament = $resultats[$i][9];
			$tipusInsc = $resultats[$i][10];
			$entitat = $resultats[$i][11];
			$certificat = $resultats[$i][12];

			//Crem lablels segons el tipus inscripció i entitat
			$labelTipus = $this->__getLabelTypeInsc($idInsc, $tipusInsc, $entitat);
			if ( $certificat == 'no aprovat' ) {
				$labelAprovat = $this->obtenirLabel('', 'no_aprovat fw-bold my-1', "NO APROVAT");
			}
			else {
				$labelAprovat = $this->obtenirLabel('', 'aprovat fw-bold my-1', "APROVAT");
			}

			$labels = "<div class='d-flex flex-row justify-content-center align-items-center'>
				".$labelTipus.$labelAprovat."
			</div>";
			// Marquem de color en els casos que s'han de tenir controlats (entitas i grups)
			$classAccess = $this->__getColorTrCont_Recordatori_Pagament($tipusInsc, $entitat);
			// creem un label amb els diners pendents
			$labelPendent = $this->obtenirLabel('', 'red fw-bold', $pendent." €");

			if ( $dataReclamat != null) {
				$objData = new Date($dataReclamat);
				$dateReclamat = $objData->getDataFomatDDMMYYYY();
			}
			else $dateReclamat = '';

			$buttonValidar = 	$this->obtenirLabel('reclamar-'.$idInsc, 'lightGreen marcat pointer w-100', 'SÍ'.$this->obtenirIconaMaterials('', '', 'sentiment_satisfied_alt', 'dona de baixa'));
			$table .= "<tr ".$classAccess.">
				".$this->mostrarFilaTaulaResponsive($titolsInscr[0], $labels)."
				".$this->mostrarFilaTaulaResponsive($titolsInscr[1], $any)."
				".$this->mostrarFilaTaulaResponsive($titolsInscr[2], $mes)."
				".$this->mostrarFilaTaulaResponsive($titolsInscr[3], $curs)."
				".$this->mostrarFilaTaulaResponsive($titolsInscr[4], $nom)."
				".$this->mostrarFilaTaulaResponsive($titolsInscr[5], $cognoms)."
				".$this->mostrarFilaTaulaResponsive($titolsInscr[6], $labelPendent)."
				".$this->mostrarFilaTaulaResponsive($titolsInscr[7], $reclamat)."
				".$this->mostrarFilaTaulaResponsive($titolsInscr[8], $dateReclamat)."
				".$this->mostrarFilaTaulaResponsive($titolsInscr[9], $obsPagament)."
				".$this->mostrarFilaTaulaResponsive($titolsInscr[10], $buttonValidar)."
			</tr>";
			if ( $asc == 1 ) {
				$i++;
				$condicio = $i < $fi;
			}
			else {
				$i--;
				$condicio = $i >= $fi;
			}
		}
		return $table;
	}

	/**
	* @brief Enviem recordatori de pagament a la persona amb id inscripcio $id
	* @return Enviem recordatori de pagamen a la persona amb id inscripció.
	*			 Si el tipus d'inscripció és G o la entitat no esta buida, s'envia a la persona de contacte
	*/
	public function updateSendMsg_LastClaimPay($id) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		echo "<p style='font-weight: bold' >#################### Actualitzem i enviem missatge de reclamació de pagament final ####################</p>";

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarInfoMostraInfo"] ) ) {
			$stmt->bind_param("d", $id);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($any, $mes, $curs, $aula, $nom, $cognoms, $dni, $correu,
				$telefon, $adreca, $cp, $poblacio, $perfil, $titulacio, $datainsc,
				$inscrit, $tipusInsc, $inscao, $inscmail, $certificat, $obscertificat,
				$generat, $obs, $comentaris, $databaixa, $motiubaixa, $quibaixa, $apagar,
				$pagament, $datapag, $idpag, $pagObs, $comHaPagat, $entitat, $fraccio,
				$comFraccio, $factura, $datarec, $reclamat, $usuari);
				$stmt->fetch();
			}
			else
				throw new Exception('',4519);
			$conWeb->closeStmt();
		}
		else
			throw new Exception('',4518);

		$conWeb->desconectarBD();

		if ( $certificat == 'no aprovat' ) {
			echo "<p style='color: #e91e63; font-weight: bold' >####################
			Actualitzem i enviem missatge de NO APROVAT ####################</p>";
			$this->updateSendMsg_LastClaimPay_noApprove($id);

		}
		else {
			echo "<p style='color: #e91e63; font-weight: bold' >####################
			Actualitzem i enviem missatge de APROVAT ####################</p>";
			$this->updateSendMsg_LastClaimPay_approve($id);
		}
		$mostrar = 'OK';
		return $mostrar;
	}

