	/**
	* @brief Actualitzem i enviem missatge no approvat
	* @return Actualitzem i enviem missatge no approvatid inscripció.
	*/
	public function updateSendMsg_LastClaimPay_noApprove($id) {
		$msgMoros = "Baixa no aprovat i no pagat";

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		echo "<p style='color: #28a79f; font-weight: bold' >#################### Busquem la informacio de la inscripcio ####################</p>";
		/* ##############  Busquem la informacio de la inscripcio  ############## */
