			$stmt->bind_param("d", $id);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($any, $mes, $curs, $aula, $nom, $cognoms, $dni, $correu,
				$telefon, $adreca, $cp, $poblacio, $perfil, $titulacio, $datainsc,
				$inscrit, $tipusInsc, $inscao, $inscmail, $certificat, $obscertificat,
				$generat, $obs, $comentaris, $databaixa, $motiubaixa, $quibaixa, $apagar,
				$pagament, $datapag, $idpag, $pagObs, $comHaPagat, $entitat, $fraccio,
				$comFraccio, $factura, $datarec, $reclamat, $usuari);
				$stmt->fetch();
			}
			else
				throw new Exception('',4519);
			$conWeb->closeStmt();
		}
		else
			throw new Exception('',4518);

		echo "<p style='color: #28a79f; font-weight: bold' >#################### Busquem la informacio del curs ####################</p>";
		/* ##############  Busquem la informacio del curs  ############## */

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarInfoCursHono"] ) ) {
			$stmt->bind_param("ss", $idCurs, $aula);
			$idCurs = $any.$curs.$mes;
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($titol, $hores, $datai, $dataf, $diesI, $diesF,
				$gtaf, $cursEscolar, $nomTutor, $cogTutor, $dniTutor);
				$stmt->fetch();
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4522);
		}

		if ( $pagObs == '' ) $obsPag = $pagObs.$msgMoros;
		else $obsPag = $pagObs.". ".$msgMoros;

		if ( $motiubaixa == '' ) $motiuBaixa = $motiubaixa.$msgMoros;
		else $motiuBaixa = $motiubaixa.". ".$msgMoros;

		if ( $tipusInsc != 'G' && $entitat == null) {
			/* ##############   Donem de baixa del curs del campus   ##############  */
			echo "<p style='color: #28a79f; font-weight: bold' >####################
			Donem de baixa del curs del campus ####################</p>";
			$shortname = $any.$curs.$mes.$aula;
			// Si la persona està en el moodle nou
			if ( !$this->__donarBaixaMoodleNou($shortname, $usuari) ) {
				// Si la persona està en el moodle antic
				if ( !$this->__donarBaixaMoodleAntic($shortname, $usuari) ) {
					// throw new Exception('',xxx);
				}
			}

			/* ##############          Donem de baixa en la BD       ############## */
			echo "<p style='color: #28a79f; font-weight: bold' >####################
			Donem de baixa en la BD ####################</p>";
			$this->updCampInscripcioBaixaMorosBD($id, 'X', $motiuBaixa, $obsPag);

			/* ##############    Construïm i enviem missatge tutor   ##############  */
			echo "<p style='color: #28a79f; font-weight: bold' >####################
			MSG TUTOR ####################</p>";
			$this->__sendMsgTutor_LastClaimPay_NoApprove($dataf, $titol, $aula, $dniTutor, $nom, $cognoms);

			/* ##############   Construïm i enviem missatge alumne   ##############  */
			echo "<p style='color: #28a79f; font-weight: bold' >####################
			MSG ALUMNE ####################</p>";
			$this->__sendMsgAlumnn_LastClaimPay_NoApprove($dataf, $titol, $hores, $nom, $cognoms, $correu, $idpag, $pagament);
		}
		else {
			$this->updCampInscripcioBaixaMorosBD($id, 'X', $motiuBaixa, $obsPag);
			$this->__sendMsgRespGrup_LastClaimPay($tipusInsc, $entitat, $dataf, $titol, $hores, $nom, $cognoms, $correu, $idpag, $pagament);
		}
		$mostrar = 'OK';
	}

	/**
	* @brief Enviem missatge  del tutor no approvat
	* @return Enviem missatge  del tutor no approvat id inscripció.
	*/
	public function __sendMsgTutor_LastClaimPay_NoApprove($dataf, $titol, $aula, $dniTutor, $nom, $cog) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		/* ##############         Enviem missatge al tutor         ##############  */

		/* Si el curs ha acabat i no han passat els 7 dies,
		enviem missatge al tutor de confirmació */
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarPersonal"] ) ) {
			$stmt->bind_param("s", $dniTutor);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($nomTutor, $cognomsTutor, $mailPrsimaTutor, $mailTutor);
				$stmt->fetch();

				$date1 = new DateTime("now");
				$date2 = new DateTime($dataf);
				$diff = $date1->diff($date2);

				if ( $diff->invert == 0 || ($diff->invert==1 && $diff->days <= 15 ) ) {
					$to = $mailPrsimaTutor;

					require_once 'Date.php';
					$objDataF = new Date($dataf);
					$dataf = $objDataF->getPronomEl()."<strong>".$objDataF->getDataLlarga()."</strong>";

					$dateNow = new DateTime("now");
					$dataHoraAct = $dateNow->format('d/m/Y H:i');

					require_once 'Template.php';
					$templates = new Template();
					$msg = $templates->getTemplate_LastClaimPayNoApproveTut();

					$names_template = array("[DATAF]", "[TITOL]", "[AULA]", "[NOM_TUTOR]", "[NOM_ALUMNE]", "[COG_ALUMNE]");
					$names_function   = array($dataf, $titol, $aula, $nomTutor, $nom, $cog);

					$subject = "Baixa de l'alumne: ".$nom." ".$cog." al curs ".$titol;
					$subjectCopiaResguard = "Baixa de l'alumne: ".$nom." ".$cog." al curs ".$titol." ".$dataHoraAct;
					$missatge = str_replace($names_template, $names_function, $msg);

					echo $missatge."<br />";

					$qui = $this->usuari->getNom()->get()." ".$this->usuari->getCognom()->get();
					$depart = $this->usuari->getDepart()->get();

					require_once "MailSMTPComvive.php";

					/* ##############      Busquem dades internes de SMTP      ##############  */
					$authGest = $this->getAuthSMTP_Gestio();
					$userGest = $authGest[0];
					$passGest = $authGest[1];
					$nameUserGest = $authGest[2];

					$nomFromHead = $nameUserGest;
					$correuFromHead = $userGest;
					$nomReplyHead = $nomTutor." ".$cognomsTutor;
					$correuReplyHead = $mailPrsimaTutor;

					$nomTo = "PrisMa Gestió";
					$correuTo = "resguard.gestio@prisma.cat";
					$correuTo = "meriem.prisma.cat@gmail.com";

					//enviar un email  de confirmacio a la persona que ha fet la compra
					$mailAlumne = new MailSMTPComvive($userGest, $passGest, $nomFromHead, $correuFromHead,
														$nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
														$subjectCopiaResguard, $missatge, $qui, $depart);

					$nomTo = $nomTutor." ".$cognomsTutor;
					$correuTo = $mailPrsimaTutor;
					$correuTo = "meriem.abjil.94@gmail.com";

					//enviar un email  de confirmacio a la persona que ha fet la compra
					$mailAlumne = new MailSMTPComvive($userGest, $passGest, $nomFromHead, $correuFromHead,
														$nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
														$subject, $missatge, $qui, $depart);
				}
			}
			else //no existeix el tutor/a a la taula personal
				throw new Exception('',4525);
			$conWeb->closeStmt();
		}
		else
			throw new Exception('',4524);

		$conWeb->desconectarBD();
	}

	/**
	* @brief Enviem missatge  del alumne no approvat
	* @return Enviem missatge  del alumne no approvat id inscripció.
	*/
	public function __sendMsgAlumnn_LastClaimPay_NoApprove($dataf, $titol, $hores, $nom, $cognoms, $correu, $idpag, $pagament) {
		$keyEncr = $this->getAuthKey();
		$despesesGestio = $this->__getParamsBD('despeses-gestio', $hores);

		require_once 'Template.php';
		$templates = new Template();

