				$comFraccio, $factura, $datarec, $reclamat, $usuari);
				$stmt->fetch();
			}
			else
				throw new Exception('',4517);
			$conWeb->closeStmt();
		}
		else
			throw new Exception('',4516);

		/* ##############  Busquem la informacio del curs  ############## */
		echo "<p style='color: #28a79f; font-weight: bold' >####################
		Busquem la informacio del curs ####################</p>";

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarInfoCursHono"] ) ) {
			$stmt->bind_param("ss", $idCurs, $aula);
			$idCurs = $any.$curs.$mes;
			echo $idCurs." ".$aula."<br />";
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($titol, $hores, $datai, $dataf, $diesI, $diesF,
				$gtaf, $cursEscolar, $nomTutor, $cogTutor, $dniTutor);
				$stmt->fetch();
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4523);
