			echo "<p style='color: #28a79f; font-weight: bold' >#################### MSG TUTOR ####################</p>";
			$this->__sendMsgTutor_LastClaimPay_Approve($dataf, $titol, $aula, $dniTutor, $nom, $cognoms);

			/* ##############    Construïm i enviem missatge alumne    ##############  */
			echo "<p style='color: #28a79f; font-weight: bold' >#################### MSG ALUMNE ####################</p>";
			$this->__sendMsgAlumnn_LastClaimPay_Approve($dataf, $titol, $hores, $nom, $cognoms, $correu, $idpag, $pagament, $tipusInsc);
		}
		else {
			/* ##############          Donem per moros en la BD          ############## */
			echo "<p style='color: #28a79f; font-weight: bold' >#################### Donem per moros en la BD ####################</p>";
			$this->updCampInscripcioBaixaMorosBD($id, 'M', $motiuBaixa, $obsPag);

			$this->__sendMsgRespGrup_LastClaimPay($tipusInsc, $entitat, $dataf, $titol, $hores, $nom, $cognoms, $correu, $idpag, $pagament);
		}
		$mostrar = 'OK';
	}

	/**
	* @brief Enviem missatge  del tutor approvat
	* @return Enviem missatge  del tutor approvat id inscripció.
	*/
	public function __sendMsgTutor_LastClaimPay_Approve($dataf, $titol, $aula, $dniTutor, $nom, $cog) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		/* ##############         Enviem missatge al tutor         ##############  */

		/* Si el curs ha acabat i no han passat els 7 dies,
		enviem missatge al tutor de confirmació */
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarPersonal"] ) ) {
			$stmt->bind_param("s", $dniTutor);
			echo "DNI_TUTOR".$dniTutor."<br />";
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($nomTutor, $cognomsTutor, $mailPrsimaTutor, $mailTutor);
				$stmt->fetch();

				$date1 = new DateTime("now");
				$date2 = new DateTime($dataf);
				$diff = $date1->diff($date2);

				if ( $diff->invert == 0 || ($diff->invert==1 && $diff->days <= 15 ) ) {
					$to = $mailPrsimaTutor;

					require_once 'Date.php';
					$objDataF = new Date($dataf);
					$dataf = $objDataF->getPronomEl()."<strong>".$objDataF->getDataLlarga()."</strong>";

					$dateNow = new DateTime("now");
					$dataHoraAct = $dateNow->format('d/m/Y H:i');

					require_once 'Template.php';
					$templates = new Template();
					$msg = $templates->getTemplate_LastClaimPayApproveTut();

					$names_template = array("[DATAF]", "[TITOL]", "[AULA]", "[NOM_TUTOR]", "[NOM_ALUMNE]", "[COG_ALUMNE]");
					$names_function   = array($dataf, $titol, $aula, $nomTutor, $nom, $cog);

					$subject = "Suspensió de l’accés de l'alumne ".$nom." ".$cog." al curs ".$titol;
					$subjectCopiaResguard = "Suspensió de l’accés de l'alumne ".$nom." ".$cog." al curs ".$titol." ".$dataHoraAct;
					$missatge = str_replace($names_template, $names_function, $msg);

					echo $missatge."<br />";

					$qui = $this->usuari->getNom()->get()." ".$this->usuari->getCognom()->get();
					$depart = $this->usuari->getDepart()->get();

					require_once "MailSMTPComvive.php";

					/* ##############      Busquem dades internes de SMTP      ##############  */
					$authGest = $this->getAuthSMTP_Gestio();
					$userGest = $authGest[0];
					$passGest = $authGest[1];
					$nameUserGest = $authGest[2];

					$nomFromHead = $nameUserGest;
					$correuFromHead = $userGest;
					$nomReplyHead = $nomTutor." ".$cognomsTutor;
					$correuReplyHead = $mailPrsimaTutor;

					$nomTo = "PrisMa Gestió";
					$correuTo = "resguard.gestio@prisma.cat";
					$correuTo = "meriem.prisma.cat@gmail.com";

					//enviar un email  de confirmacio a la persona que ha fet la compra
					$mailCopiaResguard = new MailSMTPComvive($userGest, $passGest, $nomFromHead, $correuFromHead,
														$nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
														$subjectCopiaResguard, $missatge, $qui, $depart);

					$nomTo = $nomTutor." ".$cognomsTutor;
					$correuTo = $mailPrsimaTutor;
					$correuTo = "meriem.abjil.94@gmail.com";

					//enviar un email  de confirmacio a la persona que ha fet la compra
					$mailTut = new MailSMTPComvive($userGest, $passGest, $nomFromHead, $correuFromHead,
														$nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
														$subject, $missatge, $qui, $depart);
				}
			}
			else //no existeix el tutor/a a la taula personal
				throw new Exception('',4521);
			$conWeb->closeStmt();
		}
		else
			throw new Exception('',4520);

		$conWeb->desconectarBD();
	}

	/**
	* @brief Enviem missatge  del alumne approvat
	* @return Enviem missatge  del alumne approvat id inscripció.
	*/
	public function __sendMsgAlumnn_LastClaimPay_Approve($dataf, $titol, $hores, $nom, $cognoms, $correu, $idpag, $pagament, $tipusCurs) {
		$keyEncr = $this->getAuthKey();
		$despesesGestio = $this->__getParamsBD('despeses-gestio', $hores);

		$cipher = "AES-128-CBC";

		$ivlen = openssl_cipher_iv_length($cipher);
		$iv = openssl_random_pseudo_bytes($ivlen);
		$ciphertext_raw = openssl_encrypt($idpag, $cipher, $keyEncr, $options=OPENSSL_RAW_DATA, $iv);
		$hmac = hash_hmac('sha256', $ciphertext_raw, $keyEncr, $as_binary=true);
		$hashIdPag = base64_encode( $iv.$hmac.$ciphertext_raw );

		if ( $tipusCurs != 'G' ) $urlPagament = "https://www.prisma.cat/pagament/".$hashIdPag;
		else $urlPagament = "https://www.prisma.cat/pagaments/".$hashIdPag;

		require_once 'Template.php';
		$templates = new Template();

		require_once 'Date.php';
		$objDataF = new Date($dataf);
		$dataf = $objDataF->getPronomEl()."<strong>".$objDataF->getDataLlarga()."</strong>";

		$dateNow = new DateTime("now");
		$dataHoraAct = $dateNow->format('d/m/Y H:i');

		$msg = $templates->getTemplate_LastClaimPayApproveAlumn();
		$subject = "Pagament pendent per a la tramitació del certificat del curs ".$titol;
		$subjectCopiaResguard = "Pagament pendent per a la tramitació del certificat del curs ".$titol." ".$dataHoraAct;

		$names_template = array("[DATAF]", "[TITOL]", "[NOM_ALUMNE]", "[COG_ALUMNE]", "[CORREU_ALUMNE]", "[DESPESES_GESTIO]", "[PAGAMENT]", "[URL_PAGAMENT]");
		$names_function   = array($dataf, $titol, $nom, $cognoms, $correu, $despesesGestio, $pagament, $urlPagament );

		$missatge = str_replace($names_template, $names_function, $msg);

		echo $missatge."<br />";

		$qui = $this->usuari->getNom()->get()." ".$this->usuari->getCognom()->get();
		$depart = $this->usuari->getDepart()->get();

		$nomEnviar = $nom;
		$cogEnviar = $cognoms;
		$correuEnviar = $correu;

		/* ##############      Busquem dades internes de SMTP      ##############  */
		$authGest = $this->getAuthSMTP_Gestio();
		$userGest = $authGest[0];
		$passGest = $authGest[1];
		$nameUserGest = $authGest[2];

		$nomFromHead = $nameUserGest;
		$correuFromHead = $userGest;
		$nomReplyHead = $nomEnviar." ".$cogEnviar;
		$correuReplyHead = $correuEnviar;

		require_once "MailSMTPComvive.php";

		$nomTo = "PrisMa Gestió";
		$correuTo = "resguard.gestio@prisma.cat";
		$correuTo = "meriem.prisma.cat@gmail.com";

		//enviar un email de confirmacio a gestio@prisma.cat
		$mailCopiaResguard = new MailSMTPComvive($userGest, $passGest, $nomFromHead, $correuFromHead,
											$nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
											$subjectCopiaResguard, $missatge, $qui, $depart);

		$nomTo = $nomEnviar." ".$cogEnviar;
		$correuTo = $correuEnviar;
		$correuTo = "merimari051094@gmail.com";

		//enviar un email  de confirmacio a la persona que ha fet la compra
		$mailAlumne = new MailSMTPComvive($userGest, $passGest, $nomFromHead, $correuFromHead,
											$nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
											$subject, $missatge, $qui, $depart);
	}

	/* --------------------------------- ENTITAT ------------------------------- */

	/**
	* @brief Enviem missatge al responsable de l entitat si $entitat != null. Si no ho és al responsable del grup si $tipusInsc == 'G'
	* @return Enviem missatge del template getTemplate_LastClaimPay_Responsable
	* 			al responsable de l entitat si $entitat != null.
	*			Si no ho és, enviem el missatge al responsable del grup si $tipusInsc == 'G'
	*			Altrament, no fem res.
	*/
	public function __sendMsgRespGrup_LastClaimPay($tipusInsc, $entitat, $dataf, $titol, $hores, $nom, $cognoms, $correu, $idpag, $pagament) {
		$keyEncr = $this->getAuthKey();

		$cipher = "AES-128-CBC";

		$ivlen = openssl_cipher_iv_length($cipher);
		$iv = openssl_random_pseudo_bytes($ivlen);
		$ciphertext_raw = openssl_encrypt($idpag, $cipher, $keyEncr, $options=OPENSSL_RAW_DATA, $iv);
		$hmac = hash_hmac('sha256', $ciphertext_raw, $keyEncr, $as_binary=true);
		$hashIdPag = base64_encode( $iv.$hmac.$ciphertext_raw );

		if ( $tipusInsc != 'G' ) $urlPagament = "https://www.prisma.cat/pagament/".$hashIdPag;
		else $urlPagament = "https://www.prisma.cat/pagaments/".$hashIdPag;

		$qui = $this->usuari->getNom()->get()." ".$this->usuari->getCognom()->get();
		$depart = $this->usuari->getDepart()->get();

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		require_once 'Template.php';
		$templates = new Template();

		require_once 'Date.php';
		$objDataF = new Date($dataf);
		$dataf = $objDataF->getPronomEl()."<strong>".$objDataF->getDataLlarga()."</strong>";

		$dateNow = new DateTime("now");
		$dataHoraAct = $dateNow->format('d/m/Y H:i');

		$msg = $templates->getTemplate_LastClaimPay_Responsable();

		$subject = "Pagament pendent del curs ".$titol;
		$subjectCopiaResguard = "Pagament pendent del curs ".$titol." ".$dataHoraAct;

		if ( $entitat != null && $entitat != '' ) {
			//Busco el responsable de l'entitat
			$conIntra = new ConnexioIntranet();
			$conIntra->connectarBD();

			if ( $stmt=$conIntra->prepare( $this->consultesBD_Intra["buscarRespEntitatByCIF"] ) ) {
				$stmt->bind_param("s", $entitat);
				$stmt->execute();
				$stmt->store_result();
				if ( $stmt->num_rows() > 0 ) {
					$stmt->bind_result($nomEnt, $nomRespEnt, $cogRespEnt, $correuRespEnt);
					$stmt->fetch();
				}
				$conIntra->closeStmt();
			}

			//Buscar el nom, cognoms del responsable
			$nomEnviar = $nomRespEnt;
			$cogEnviar = $cogRespEnt;
			$correuEnviar = $correuRespEnt;
		}
		else if ( $tipusInsc == 'G' ) {
			//Busco el responsable de l'entitat
			if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarPersRespGrup"] ) ) {
				$stmt->bind_param("d", $idpag);
				$stmt->execute();
				$stmt->store_result();
				if ($stmt->num_rows() > 0) {
					$stmt->bind_result($nomResp, $cognomsResp, $dniResp, $emailResp,
						$adrecaResp, $cpResp, $pobleResp, $factRel, $fracc, $fraccio, $apagarTotal, $importPagatTotal);
					$stmt->fetch();
				}
				$conWeb->closeStmt();
			}
			//Buscar el nom, cognoms del responsable
			$nomEnviar = $nomResp;
			$cogEnviar = $cognomsResp;
			$correuEnviar = $emailResp;
		}

		$conWeb->desconectarBD();

		$names_template = array("[NOM_RESPONSABLE]","[DATAF]", "[TITOL]", "[NOM_ALUMNE]", "[COG_ALUMNE]", "[URL_PAGAMENT]");
		$names_function   = array($nomEnviar, $dataf, $titol, $nom, $cognoms, $urlPagament );

		$missatge = str_replace($names_template, $names_function, $msg);

		echo $missatge."<br />";

		/* ##############      Busquem dades internes de SMTP      ##############  */
		$authGest = $this->getAuthSMTP_Gestio();
		$userGest = $authGest[0];
		$passGest = $authGest[1];
		$nameUserGest = $authGest[2];

		$nomFromHead = $nameUserGest;
		$correuFromHead = $userGest;
		$nomReplyHead = $nomEnviar." ".$cogEnviar;
		$correuReplyHead = $correuEnviar;

		require_once "MailSMTPComvive.php";

		if ( $tipusInsc == 'G' || $entitat != null) {
		   $nomTo = "PrisMa Gestió";
		   $correuTo = "resguard.gestio@prisma.cat";
		   $correuTo = "meriem.prisma.cat@gmail.com";

		   //enviar un email de confirmacio a gestio@prisma.cat
		   $mailCopiaResguard = new MailSMTPComvive($userGest, $passGest, $nomFromHead, $correuFromHead,
		                              $nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
		                              $subjectCopiaResguard, $missatge, $qui, $depart);

		   $nomTo = $nomEnviar." ".$cogEnviar;
		   $correuTo = $correuEnviar;
		   $correuTo = "merimari051094@gmail.com";

		   //enviar un email  de confirmacio a la persona que ha fet la compra
		   $mailAlumne = new MailSMTPComvive($userGest, $passGest, $nomFromHead, $correuFromHead,
		                              $nomReplyHead, $correuReplyHead, $nomTo, $correuTo,
		                              $subject, $missatge, $qui, $depart);
		}
	}

	/* --------------------------------- ACTUALITZAT ------------------------------- */
	/**
	* @brief Actualitzem camp insc curs amb $insccurs i canviem a motiu de baixa $motiuBaixa i observacions de pagament $obsPag
	* @return Actualitzem camp insc curs amb $insccurs i canviem a motiu de baixa $motiuBaixa i observacions de pagament $obsPag
	*/
	public function updCampInscripcioBaixaMorosBD($id, $inscurs, $motiuBaixa, $obsPag) {
		/* Marquem el camp Inscripcio com a $inscurs de la inscripcio $id,
		   el motiu de la baixa com a $motiuBaixa, la persona qui la donat de baixa
			i la data de baixa */
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		$dateNow = new DateTime("now");
		$dataBaixa = $dateNow->format('Y-m-d H:i:s');

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["updInscCursBaixaiMoros"] ) ) {
			$stmt->bind_param("sssssd", $inscurs, $dataBaixa, $quiBaixa, $motiuBaixa, $obsPag, $id);
			$quiBaixa = $this->usuari->getNom()->get()." ".$this->usuari->getCognom()->get();
			$stmt->execute();
			$conWeb->closeStmt();
		}
		else
			throw new Exception('',4515);

		$conWeb->desconectarBD();
	}

