	/**
	* @brief Mostra els alumnes que són morosos i corresponen a una entitat
	* @return string Mostra els alumnes que són morosos i corresponen a una entitat
	*/
	public function __mostrarPage_Facturacio_Morosos_Entitat_contingut($orderBy, $asc) {
		$table = "";
		$infoTable = "";
		$button = "";
		$resultats = []; $i = 0;

		$titolsInscr[0] = "Any";
		$titolsInscr[1] = "Mes";
		$titolsInscr[2] = "Curs";
		$titolsInscr[3] = "Nom";
		$titolsInscr[4] = "Cognoms";
		$titolsInscr[5] = "Pendent";
		$titolsInscr[6] = "Reclamat";
		$titolsInscr[7] = "Data reclamat";
		$titolsInscr[8] = "Obs. pagament";
		$titolsInscr[9] = "Reclamar";

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["cnsAlumnClaimEntMoros"] ) ) {
				$stmt->execute();
				$stmt->store_result();
				if ( $stmt->num_rows() > 0 ) {
					$stmt->bind_result($idInsc, $any, $mes, $curs, $dni, $nom, $cognoms,
					$correu, $apagar, $pagament, $pendent, $dataReclamat, $reclamat, $obsPagament);
					while ( $stmt->fetch() ) {
						$resultats[$i][0] = $idInsc;
						$resultats[$i][1] = $any;
						$resultats[$i][2] = $mes;
						$resultats[$i][3] = $curs;
						$resultats[$i][4] = $nom;
						$resultats[$i][5] = $cognoms;
						$resultats[$i][6] = $pendent;
						$resultats[$i][7] = $reclamat;
						$resultats[$i][8] = $dataReclamat;
						$resultats[$i][9] = $obsPagament;
						$resultats[$i][10] = $dni;
						$resultats[$i][11] = $correu;

						// creem un label amb els diners pendents
						$labelPendent = $this->obtenirLabel('', 'red fw-bold', $pendent." €");

						if ( $dataReclamat != null) {
							require_once 'Date.php';
							$objData = new Date($dataReclamat);
							$dateReclamat = $objData->getDataFomatDDMMYYYY();
						}
						else $dateReclamat = '';

						$date1 = new DateTime("now");
						$date2 = new DateTime($dataReclamat);
						$diff = $date1->diff($date2);

						if ( $dataReclamat != null && $dataReclamat != '' ) {
							$buttonValidar = 	$this->obtenirLabel('', 'disableClaim pointer w-100', 'NO ES POT (FALTA '.(30-$diff->days).' DIES)', 'Encara no ha passat un mes des de la última reclamació');
							if ( $diff->invert == 1 && $diff->days >= 30 ) {
								$buttonValidar = 	$this->obtenirLabel('claimEnt-'.$idInsc, 'lightGreen fw-bold marcat pointer w-100', 'SÍ'.$this->obtenirIconaMaterials('', '', 'sentiment_satisfied_alt', 'Reclama'));
							}
						}
						else {
							$buttonValidar = 	$this->obtenirLabel('', 'red error pointer w-100', 'NO HI HA DATA DE RECLAMACIÓ');
						}

						$infoTable .= "<tr>
							".$this->mostrarFilaTaulaResponsive($titolsInscr[0], $any)."
							".$this->mostrarFilaTaulaResponsive($titolsInscr[1], $mes)."
							".$this->mostrarFilaTaulaResponsive($titolsInscr[2], $curs)."
							".$this->mostrarFilaTaulaResponsive($titolsInscr[3], $nom)."
							".$this->mostrarFilaTaulaResponsive($titolsInscr[4], $cognoms)."
							".$this->mostrarFilaTaulaResponsive($titolsInscr[5], $labelPendent)."
							".$this->mostrarFilaTaulaResponsive($titolsInscr[6], $reclamat)."
							".$this->mostrarFilaTaulaResponsive($titolsInscr[7], $dateReclamat)."
							".$this->mostrarFilaTaulaResponsive($titolsInscr[8], $obsPagament)."
							".$this->mostrarFilaTaulaResponsive($titolsInscr[9], $buttonValidar)."
						</tr>";
						$i++;
					}
					$conWeb->closeStmt();
				}
				else {
					$table = "";
				}
		}
		else {
			throw new Exception('', 4530);
		}
		$conWeb->desconectarBD();

		$classes = ['', '', '', ''];

		if ( $orderBy != '' ) {
			if ($orderBy == 'codi') $cntOrderBy = 0;
			else if ($orderBy == 'nom') $cntOrderBy = 1;
			else if ($orderBy == 'cog') $cntOrderBy = 2;

			if ($asc == 1) { //s'ordena ascendentment
				$inici = 0;
				$fi = count($resultats);
				$j = $inici;
				$condicio = $j < $fi;

				$classes[$cntOrderBy] = ' asc';
			}
			else { //s'ordena dsscendentment
				$inici = count($resultats);
				$fi = 0;
				$j = $inici-1;
				$condicio = $j >= $fi;

				$classes[$cntOrderBy] = ' desc';
			}
		}

		if ( count($resultats) > 0 ) {
			$table .= "<p class='text-center'>S'han trobat <strong class='badge bg-pris fs-6 mx-1'>".$i."</strong> resultats.</p>";

			$table .= "<table class='table table-claim-entitats table-striped table-hover table-order table-xl-responsive text-center mt-2 mb-0'>
			<thead><tr>
				<th>".$titolsInscr[0]."</th>
				<th>".$titolsInscr[1]."</th>
				<th id='th-codi' class='sorting".$classes[0]."'>".$titolsInscr[2]."</th>
				<th id='th-nom' class='sorting".$classes[1]."'>".$titolsInscr[3]."</th>
				<th id='th-cog' class='sorting".$classes[2]."'>".$titolsInscr[4]."</th>
				<th>".$titolsInscr[5]."</th>
				<th>".$titolsInscr[6]."</th>
				<th>".$titolsInscr[7]."</th>
				<th>".$titolsInscr[8]."</th>
				<th>".$titolsInscr[9]."</th>
			</tr></thead>
			<tbody>";
			if ( $orderBy != '' )
				$infoTable = $this->__resultsClaimMorosEntitatOrderBy($titolsInscr, $resultats, $orderBy, $asc);
			$table .= $infoTable;
			$table .= "</tbody></table>";
		}
		else {
			$table = "";
		}
		return $table;
	}

	/**
	* @brief Mostra una taula amb tota la informació necessària per la consulta «Control de morosos - Entitat»
	* @return Mostra una taula amb l'any, el mes, el curs, el nom, els cognoms,
	*			 els diners pendents, el camp reclamació, la data de Reclamació
	*			 les observacions de pagament i un label MARCAT de l'array resultats
	*			 amb la ordenació que dictamini $order i si $asc = 1, la ordenació és ascendent.
	*
	*/
	public function __resultsClaimMorosEntitatOrderBy($titolsInscr, $resultats, $orderBy, $asc) {
		function cmpCodi($a, $b) {
			 if ($a[3] == $b[3]) {
				if ($a[1] == $b[1]) {
					if ($a[2] == $b[2]) {
						if ($a[4] == $b[4]) {
							 return 0;
						}
						return ($a[4] < $b[4]) ? -1 : 1;
				  }
				  return ($a[2] < $b[2]) ? -1 : 1;
			  }
			  return ($a[1] < $b[1]) ? -1 : 1;
			}
			return ($a[3] < $b[3]) ? -1 : 1;
		}

		function cmpNom($a, $b) {
			 if ($a[4] == $b[4]) {
				if ($a[5] == $b[5]) {
					if ($a[1] == $b[1]) {
					  if ($a[2] == $b[2]) {
								return 0;
					 }
					 return ($a[2] < $b[2]) ? -1 : 1;
				  }
				  return ($a[4] < $b[4]) ? -1 : 1;
				}
				return ($a[5] < $b[5]) ? -1 : 1;
			 }
			 return ($a[4] < $b[4]) ? -1 : 1;
		}

		function cmpCognoms($a, $b) {
			 if ($a[5] == $b[5]) {
				 if ($a[4] == $b[4]) {
   				 if ($a[1] == $b[1]) {
   					if ($a[2] == $b[2]) {
   						if ($a[3] == $b[3]) {
   							 return 0;
   						}
   						return ($a[3] < $b[3]) ? -1 : 1;
   				  }
   				  return ($a[2] < $b[2]) ? -1 : 1;
   				}
   				return ($a[1] < $b[1]) ? -1 : 1;
   			 }
   			 return ($a[4] < $b[4]) ? -1 : 1;
			 }
			 return ($a[5] < $b[5]) ? -1 : 1;
		}

		$cntOrderBy = 0;
		if ($orderBy == 'codi') { usort($resultats, "cmpCodi"); $cntOrderBy = 0; }
		else if ($orderBy == 'nom') { usort($resultats, "cmpNom"); $cntOrderBy = 1; }
		else if ($orderBy == 'cog') { usort($resultats, "cmpCognoms"); $cntOrderBy = 2; }

		$classes = ['', '', '', ''];

		if ( $orderBy != '' ) {

			if ($asc == 1) { //s'ordena ascendentment
				$inici = 0;
				$fi = count($resultats);
				$i = $inici;
				$condicio = $i < $fi;

				$classes[$cntOrderBy] = 'asc';
			}
			else { //s'ordena dsscendentment
				$inici = count($resultats);
				$fi = 0;
				$i = $inici-1;
				$condicio = $i >= $fi;

				$classes[$cntOrderBy] = 'desc';
			}
		}

		$table = '';
		while ( $condicio ) {
			$idInsc = $resultats[$i][0];
			$any = $resultats[$i][1];
			$mes = $resultats[$i][2];
			$curs = $resultats[$i][3];
			$nom = $resultats[$i][4];
			$cognoms = $resultats[$i][5];
			$pendent = $resultats[$i][6];
			$reclamat = $resultats[$i][7];
			$dataReclamat = $resultats[$i][8];
			$obsPagament = $resultats[$i][9];
			$dni = $resultats[$i][10];
			$correu = $resultats[$i][11];

			// creem un label amb els diners pendents
			$labelPendent = $this->obtenirLabel('', 'red fw-bold', $pendent." €");

			if ( $dataReclamat != null) {
				require_once 'Date.php';
				$objData = new Date($dataReclamat);
				$dateReclamat = $objData->getDataFomatDDMMYYYY();
			}
			else $dateReclamat = '';

			$date1 = new DateTime("now");
			$date2 = new DateTime($dataReclamat);
			$diff = $date1->diff($date2);

			if ( $dataReclamat != null && $dataReclamat != '' ) {
				$buttonValidar = 	$this->obtenirLabel('', 'disableClaim pointer w-100', 'NO ES POT (FALTA '.(30-$diff->days).' DIES)', 'Encara no ha passat un mes des de la última reclamació');
				if ( $diff->invert == 1 && $diff->days >= 30 ) {
					$buttonValidar = 	$this->obtenirLabel('claimEnt-'.$idInsc, 'lightGreen marcat pointer w-100', 'SÍ'.$this->obtenirIconaMaterials('', '', 'sentiment_satisfied_alt', 'Reclama'));
				}
			}
			else {
				$buttonValidar = 	$this->obtenirLabel('', 'red error pointer w-100', 'NO HI HA DATA DE RECLAMACIÓ');
			}

			$table .= "<tr>
			".$this->mostrarFilaTaulaResponsive($titolsInscr[0], $any)."
			".$this->mostrarFilaTaulaResponsive($titolsInscr[1], $mes)."
			".$this->mostrarFilaTaulaResponsive($titolsInscr[2], $curs)."
			".$this->mostrarFilaTaulaResponsive($titolsInscr[3], $nom)."
			".$this->mostrarFilaTaulaResponsive($titolsInscr[4], $cognoms)."
			".$this->mostrarFilaTaulaResponsive($titolsInscr[5], $labelPendent)."
			".$this->mostrarFilaTaulaResponsive($titolsInscr[6], $reclamat)."
			".$this->mostrarFilaTaulaResponsive($titolsInscr[7], $dateReclamat)."
			".$this->mostrarFilaTaulaResponsive($titolsInscr[8], $obsPagament)."
			".$this->mostrarFilaTaulaResponsive($titolsInscr[9], $buttonValidar)."
			</tr>";
			if ( $asc == 1 ) {
				$i++;
				$condicio = $i < $fi;
			}
			else {
				$i--;
				$condicio = $i >= $fi;
			}
		}
		return $table;
	}

	/**
	* @brief Mostra les entitats morosos
	* @return string Mostra eles entitats mororsos
	*/
	public function __mostrarPage_Facturacio_Morosos_Entitats() {
		$table = "";
		$infoTable = "";
		$button = "";
		$resultats = []; $i = 0;

		$titolsInscr[0] = "Entitat";
		$titolsInscr[1] = "Nom Entitat";
		$titolsInscr[2] = "Pendent";
		$titolsInscr[3] = "Nom i cognoms (responsable)";
		$titolsInscr[4] = "Correu (responsable)";

		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();
		$conIntra = new ConnexioIntranet();
		$conIntra->connectarBD();
		//
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["cnsEntMoros"] ) ) {
			if ( $stmt2=$conIntra->prepare( $this->consultesBD_Intra["buscarRespEntitatByCIF"] ) ) {
				$stmt2->bind_param("s", $cif);
				$stmt->execute();
				$stmt->store_result();
				if ( $stmt->num_rows() > 0 ) {
					$stmt->bind_result($entitat, $pendent);
					while ( $stmt->fetch() ) {
						$cif = $entitat;
						$stmt2->execute();
						$stmt2->store_result();
						if ( $stmt2->num_rows() > 0 ) {
							$stmt2->bind_result($nomEnt, $nomRespEnt, $cogRespEnt, $correuRespEnt);
							while ( $stmt2->fetch() ) {
								$resultats[$i][0] = $entitat;
								$resultats[$i][1] = $pendent;
								$resultats[$i][2] = $nomEnt;
								$resultats[$i][3] = $nomRespEnt;
								$resultats[$i][4] = $cogRespEnt;
								$resultats[$i][5] = $correuRespEnt;

								// creem un label amb els diners pendents
								$labelPendent = $this->obtenirLabel('', 'red fw-bold', $pendent." €");

								$infoTable .= "<tr>
									".$this->mostrarFilaTaulaResponsive($titolsInscr[0], $entitat)."
									".$this->mostrarFilaTaulaResponsive($titolsInscr[1], $nomEnt)."
									".$this->mostrarFilaTaulaResponsive($titolsInscr[2], $labelPendent)."
									".$this->mostrarFilaTaulaResponsive($titolsInscr[3], $nomRespEnt." ".$cogRespEnt)."
									".$this->mostrarFilaTaulaResponsive($titolsInscr[4], $correuRespEnt)."
								</tr>";
								$i++;
							}
						}
						else {
							$table = "";
						}
					}
					$conIntra->closeStmt();
					$conWeb->closeStmt();
				}
				else {
					$table = "";
				}
			}
			else {
				throw new Exception('', 4528);
			}
		}
		else {
			throw new Exception('', 4529);
		}

		$conIntra->desconectarBD();
		$conWeb->desconectarBD();

		if ( count($resultats) > 0 ) {
			$table .= "<table class='table table-striped table-hover table-order table-xl-responsive text-center mt-2 mb-0'>
			<thead><tr>
				<th>".$titolsInscr[0]."</th>
				<th>".$titolsInscr[1]."</th>
				<th>".$titolsInscr[2]."</th>
				<th>".$titolsInscr[3]."</th>
				<th>".$titolsInscr[4]."</th>
			</tr></thead>
			<tbody>";
			$table .= $infoTable;
			$table .= "</tbody></table>";
		}
		else {
			$table = "";
		}
		return $table;
	}

	/**
	* @brief Actualitzem el registre de la data de reclamació i enviem un correu
	* @return string Actualitzem el registre de la data de reclamació amb la data d'avui
	* 			 i enviem un correu de reclamació a l'entitat corresponent i una copia
	*/
	public function updateSendMsg_EntityClaimPayDefaulter( $id ) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		echo "<p style='color: #28a79f; font-weight: bold' >#################### Busquem la informacio de la inscripcio ####################</p>";
		/* ##############  Busquem la informacio de la inscripcio  ############## */
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarInfoMostraInfo"] ) ) {
			$stmt->bind_param("d", $id);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($any, $mes, $curs, $aula, $nom, $cognoms, $dni, $correu,
				$telefon, $adreca, $cp, $poblacio, $perfil, $titulacio, $datainsc,
				$inscrit, $tipusInsc, $inscao, $inscmail, $certificat, $obscertificat,
				$generat, $obs, $comentaris, $databaixa, $motiubaixa, $quibaixa, $apagar,
				$pagament, $datapag, $idpag, $pagObs, $comHaPagat, $entitat, $fraccio,
				$comFraccio, $factura, $datarec, $reclamat, $usuari);
				$stmt->fetch();
			}
			else
				throw new Exception('',4532);
			$conWeb->closeStmt();
		}
		else
			throw new Exception('',4531);

		/* ##############  Busquem la informacio del curs  ############## */
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarCursSegEd"] ) ) {
			$stmt->bind_param("dss", $any, $mes, $curs);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($nomCurs, $datai, $dataf, $hores, $idPreu);
				$stmt->fetch();
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4533);
		}

		$dateNow = new DateTime("now");
		$newDateClaim = $dateNow->format('d/m/Y');

		$newReclamat = $reclamat." reclamat (".$newDateClaim.")";
		$newPagObs = $pagObs." reclamat (".$newDateClaim.")";

		/* ##############        Actualitzem la reclamació        ############## */
		echo "<p style='color: #28a79f; font-weight: bold' >#################### Actualitzar data de reclamació i reclamat ####################</p>";
		$this->updCampReclamatDefaulter($id, $newReclamat, $newPagObs);

		/* ##############        Construïm i enviem missatge        ############## */
		echo "<p style='color: #28a79f; font-weight: bold' >#################### MSG RESP ENTITAT ####################</p>";
		$this->__sendMsgRespEntity_EntityClaimPayDefaulter($nom, $cognoms, $correu,
		$nomCurs, $dataf, $idpag, $tipusInsc, $entitat);
	}

