	*			 els diners pendents, el camp reclamació, la data de Reclamació
	*			 les observacions de pagament i un label MARCAT de l'array resultats
	*			 amb la ordenació que dictamini $order i si $asc = 1, la ordenació és ascendent.
	*/
	public function __resultsClaimMorosAlumnesAprovatsSenseCertificatOrderBy($titolsInscr, $resultats, $orderBy, $asc) {
		function cmpCodi($a, $b) {
			 if ($a[3] == $b[3]) {
				if ($a[1] == $b[1]) {
					if ($a[2] == $b[2]) {
						if ($a[4] == $b[4]) {
							 return 0;
						}
						return ($a[4] < $b[4]) ? -1 : 1;
				  }
				  return ($a[2] < $b[2]) ? -1 : 1;
			  }
			  return ($a[1] < $b[1]) ? -1 : 1;
			}
			return ($a[3] < $b[3]) ? -1 : 1;
		}

		function cmpNom($a, $b) {
			 if ($a[4] == $b[4]) {
				if ($a[5] == $b[5]) {
					if ($a[1] == $b[1]) {
					  if ($a[2] == $b[2]) {
								return 0;
					 }
					 return ($a[2] < $b[2]) ? -1 : 1;
				  }
				  return ($a[4] < $b[4]) ? -1 : 1;
				}
				return ($a[5] < $b[5]) ? -1 : 1;
			 }
			 return ($a[4] < $b[4]) ? -1 : 1;
		}

		function cmpCognoms($a, $b) {
			 if ($a[5] == $b[5]) {
				 if ($a[4] == $b[4]) {
   				 if ($a[1] == $b[1]) {
   					if ($a[2] == $b[2]) {
   						if ($a[3] == $b[3]) {
   							 return 0;
   						}
   						return ($a[3] < $b[3]) ? -1 : 1;
   				  }
   				  return ($a[2] < $b[2]) ? -1 : 1;
   				}
   				return ($a[1] < $b[1]) ? -1 : 1;
   			 }
   			 return ($a[4] < $b[4]) ? -1 : 1;
			 }
			 return ($a[5] < $b[5]) ? -1 : 1;
		}

		$cntOrderBy = 0;
		if ($orderBy == 'codi') { usort($resultats, "cmpCodi"); $cntOrderBy = 0; }
		else if ($orderBy == 'nom') { usort($resultats, "cmpNom"); $cntOrderBy = 1; }
		else if ($orderBy == 'cog') { usort($resultats, "cmpCognoms"); $cntOrderBy = 2; }

		$classes = ['', '', '', ''];

		if ( $orderBy != '' ) {

			if ($asc == 1) { //s'ordena ascendentment
				$inici = 0;
				$fi = count($resultats);
				$i = $inici;
				$condicio = $i < $fi;

				$classes[$cntOrderBy] = 'asc';
			}
			else { //s'ordena dsscendentment
				$inici = count($resultats);
				$fi = 0;
				$i = $inici-1;
				$condicio = $i >= $fi;

				$classes[$cntOrderBy] = 'desc';
			}
		}

		$table = '';
		while ( $condicio ) {
			$idInsc = $resultats[$i][0];
			$any = $resultats[$i][1];
			$mes = $resultats[$i][2];
			$curs = $resultats[$i][3];
			$nom = $resultats[$i][4];
			$cognoms = $resultats[$i][5];
			$pendent = $resultats[$i][6];
			$reclamat = $resultats[$i][7];
			$dataReclamat = $resultats[$i][8];
			$obsPagament = $resultats[$i][9];
			$dni = $resultats[$i][10];
			$correu = $resultats[$i][11];

			// creem un label amb els diners pendents
			$labelPendent = $this->obtenirLabel('', 'red fw-bold', $pendent." €");

			if ( $dataReclamat != null) {
				require_once 'Date.php';
				$objData = new Date($dataReclamat);
				$dateReclamat = $objData->getDataFomatDDMMYYYY();
			}
			else $dateReclamat = '';

			$date1 = new DateTime("now");
			$date2 = new DateTime($dataReclamat);
			$diff = $date1->diff($date2);

			if ( $dataReclamat != null && $dataReclamat != '' ) {
				$buttonValidar = 	$this->obtenirLabel('', 'disableClaim pointer w-100', 'NO ES POT (FALTA '.(30-$diff->days).' DIES)', 'Encara no ha passat un mes des de la última reclamació');
				if ( $diff->invert == 1 && $diff->days >= 30 ) {
					$buttonValidar = 	$this->obtenirLabel('claimAlumnNoCert-'.$idInsc, 'lightGreen marcat pointer w-100', 'SÍ'.$this->obtenirIconaMaterials('', '', 'sentiment_satisfied_alt', 'Reclama'));
				}
			}
			else {
				$buttonValidar = 	$this->obtenirLabel('', 'red error pointer w-100', 'NO HI HA DATA DE RECLAMACIÓ');
			}

			$table .= "<tr>
			".$this->mostrarFilaTaulaResponsive($titolsInscr[0], $any)."
			".$this->mostrarFilaTaulaResponsive($titolsInscr[1], $mes)."
			".$this->mostrarFilaTaulaResponsive($titolsInscr[2], $curs)."
			".$this->mostrarFilaTaulaResponsive($titolsInscr[3], $nom)."
			".$this->mostrarFilaTaulaResponsive($titolsInscr[4], $cognoms)."
			".$this->mostrarFilaTaulaResponsive($titolsInscr[5], $labelPendent)."
			".$this->mostrarFilaTaulaResponsive($titolsInscr[6], $reclamat)."
			".$this->mostrarFilaTaulaResponsive($titolsInscr[7], $dateReclamat)."
			".$this->mostrarFilaTaulaResponsive($titolsInscr[8], $obsPagament)."
			".$this->mostrarFilaTaulaResponsive($titolsInscr[9], $buttonValidar)."
			</tr>";
			if ( $asc == 1 ) {
				$i++;
				$condicio = $i < $fi;
			}
			else {
				$i--;
				$condicio = $i >= $fi;
			}
		}
		return $table;
	}

	/**
	* @brief Actualitzem el registre de la data de reclamació i enviem un correu
	* @return string Actualitzem el registre de la data de reclamació amb la data d'avui
	* 			 i enviem un correu de reclamació a l'entitat corresponent i una copia
	*/
	public function updateSendMsg_AlumnNoCertClaimPayDefaulter( $id ) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();
		echo "<p style='color: #28a79f; font-weight: bold' >####################
		Busquem la informacio de la inscripcio ####################</p>";
		/* ##############  Busquem la informacio de la inscripcio  ############## */
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarInfoMostraInfo"] ) ) {
			$stmt->bind_param("d", $id);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($any, $mes, $curs, $aula, $nom, $cognoms, $dni, $correu,
				$telefon, $adreca, $cp, $poblacio, $perfil, $titulacio, $datainsc,
				$inscrit, $tipusInsc, $inscao, $inscmail, $certificat, $obscertificat,
				$generat, $obs, $comentaris, $databaixa, $motiubaixa, $quibaixa, $apagar,
				$pagament, $datapag, $idpag, $pagObs, $comHaPagat, $entitat, $fraccio,
				$comFraccio, $factura, $datarec, $reclamat, $usuari);
				$stmt->fetch();
			}
			else
				throw new Exception('',4552);
			$conWeb->closeStmt();
		}
		else
			throw new Exception('',4551);

		echo "<p style='color: #28a79f; font-weight: bold' >####################
		Actualitzar data de reclamació i reclamat ####################</p>";
		/* ##############  Busquem la informacio del curs  ############## */
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarCursSegEd"] ) ) {
			$stmt->bind_param("dss", $any, $mes, $curs);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($nomCurs, $datai, $dataf, $hores, $idPreu);
				$stmt->fetch();
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4553);
		}

		$dateNow = new DateTime("now");
		$newDateClaim = $dateNow->format('d/m/Y');

		if ( $reclamat == '' ) $newReclamat = "Reclamat (".$newDateClaim.")";
		else $newReclamat = $reclamat.". Reclamat (".$newDateClaim.")";

		if ( $pagObs == '' ) $newPagObs = "Reclamat (".$newDateClaim.")";
		else $newPagObs = $pagObs.". Reclamat (".$newDateClaim.")";

		/* ##############        Actualitzem la reclamació        ############## */
		echo "<p style='color: #28a79f; font-weight: bold' >####################
		Actualitzar data de reclamació i reclamat ####################</p>";
		$this->updCampReclamatDefaulter($id, $newReclamat, $newPagObs);

		if ( $tipusInsc != 'G' && $entitat == null) {
			echo "<p style='color: #28a79f; font-weight: bold' >####################
			MSG ALUMNE ####################</p>";
			$this->__sendMsgAlumnn_AlumnNoCertClaimPayDefaulter($dataf, $nomCurs,
			$hores, $nom, $cognoms, $correu, $idpag, $pagament, $tipusInsc);
		}
		else {
			echo "<p style='color: #28a79f; font-weight: bold' >####################
			MSG RESP ENTITAT ####################</p>";
			$this->__sendMsgRespEntity_EntityClaimPayDefaulter($nom, $cognoms,
			$correu, $titol, $dataf, $idpag, $tipusInsc, $entitat);
		}
	}

