	/**
	* @brief Actualitzem el registre de la data de reclamació i enviem un correu
	* @return string Actualitzem el registre de la data de reclamació amb la data d'avui
	* 			 i enviem un correu de reclamació a l'entitat corresponent i una copia
	*/
	public function updateSendMsg_AlumnCertClaimPayDefaulter( $id ) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();
		echo "<p style='color: #28a79f; font-weight: bold' >####################
		Busquem la informacio de la inscripcio ####################</p>";
		/* ##############  Busquem la informacio de la inscripcio  ############## */
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarInfoMostraInfo"] ) ) {
			$stmt->bind_param("d", $id);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($any, $mes, $curs, $aula, $nom, $cognoms, $dni, $correu,
				$telefon, $adreca, $cp, $poblacio, $perfil, $titulacio, $datainsc,
				$inscrit, $tipusInsc, $inscao, $inscmail, $certificat, $obscertificat,
				$generat, $obs, $comentaris, $databaixa, $motiubaixa, $quibaixa, $apagar,
				$pagament, $datapag, $idpag, $pagObs, $comHaPagat, $entitat, $fraccio,
				$comFraccio, $factura, $datarec, $reclamat, $usuari);
				$stmt->fetch();
			}
			else
				throw new Exception('',4556);
			$conWeb->closeStmt();
		}
		else
			throw new Exception('',4555);

		echo "<p style='color: #28a79f; font-weight: bold' >####################
		Busquem la informacio del curs ####################</p>";
		/* ##############  Busquem la informacio del curs  ############## */
		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["buscarCursSegEd"] ) ) {
			$stmt->bind_param("dss", $any, $mes, $curs);
			$stmt->execute();
			$stmt->store_result();
			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($nomCurs, $datai, $dataf, $hores, $idPreu);
				$stmt->fetch();
			}
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4557);
		}

		$dateNow = new DateTime("now");
		$newDateClaim = $dateNow->format('d/m/Y');

		if ( $reclamat == '' ) $newReclamat = "Reclamat (".$newDateClaim.")";
		else $newReclamat = $reclamat.". Reclamat (".$newDateClaim.")";

		if ( $pagObs == '' ) $newPagObs = "Reclamat (".$newDateClaim.")";
		else $newPagObs = $pagObs.". Reclamat (".$newDateClaim.")";

		/* ##############        Actualitzem la reclamació        ############## */
		echo "<p style='color: #28a79f; font-weight: bold' >####################
		Actualitzar data de reclamació i reclamat ####################</p>";
		$this->updCampReclamatDefaulter($id, $newReclamat, $newPagObs);

		if ( $tipusInsc != 'G' && $entitat == null) {
			echo "<p style='color: #28a79f; font-weight: bold' >####################
			MSG ALUMNE ####################</p>";
			$this->__sendMsgAlumnn_AlumnCertClaimPayDefaulter($dataf, $nomCurs,
			$hores, $nom, $cognoms, $correu, $idpag, $pagament, $tipusInsc);
		}
		else {
			echo "<p style='color: #28a79f; font-weight: bold' >####################
			MSG RESP ENTITAT ####################</p>";
			$this->__sendMsgRespEntity_EntityClaimPayDefaulter($nom, $cognoms,
			$correu, $titol, $dataf, $idpag, $tipusInsc, $entitat);
		}
	}

