	private function __modalAddElement() {
		$resTipus =  $this->__getListParamsBD( 'tipus-pendents' ); $labelTipus = '';

		function labelTypePendents($n) {
				$type = $n[0];
				$valorClass = explode('|', $n[1])[0];
				$valorName = explode('|', $n[1])[1];
				if ( $type == '10' ) $label = '';
				else $label = "<label id='tipus-".$type."' class='label tipus text-uppercase
				d-flex justify-content-center align-items-center position-relative
