	public function addElement($titol, $descripcio, $tipus,
	$prio, $motiuPrio, $dataEstimada) {
		$qui = $this->usuari->getUsuari()->get();

		$conIntra = new ConnexioIntranet();
		$conIntra->connectarBD();

		if ( $stmt=$conIntra->prepare( $this->consultesBD_Intra["insertPendent"] ) ) {
			$stmt->bind_param("sssssss", $titol, $descripcio, $tipus, $prio,
			$motiuPrio, $dataEstimada, $qui);
			$stmt->execute();
			$conIntra->closeStmt();
		}
		else {
			throw new Exception('', 4527);
		}

		$conIntra->desconectarBD();
	}

	/* ##############################    CALENDAR     ############################## */

	public function mostrarTaulaPendents_Calendari($orderBy, $asc, $tipus, $quiFiltre) {
		$table = "";
		$infoTable = "";
		$button = "";
		$resultats = []; $i = 0;

		$titolsInscr[0] = "Tipus";
		$titolsInscr[1] = "Títol";
		$titolsInscr[2] = "Descripció";
		$titolsInscr[3] = "Prioritat";
		$titolsInscr[4] = "Motiu";
		$titolsInscr[5] = "Url";
		$titolsInscr[6] = "Data Destimada";
		$titolsInscr[7] = "";

		$conIntra = new ConnexioIntranet();
		$conIntra->connectarBD();
		if ( $stmt=$conIntra->prepare( $this->consultesBD_Intra["cnsPendents"] ) ) {
			$stmt->bind_param("s", $tipus);
			$stmt->execute();
			$stmt->store_result();
			if ( $stmt->num_rows() > 0 ) {
				$stmt->bind_result($id, $tipusRes, $qui, $titol, $desc, $prio, $motiu_prio, $date_estimate, $url);
				while ( $stmt->fetch() ) {
					$resultats[$i][0] = $id;
					$resultats[$i][1] = $tipusRes;
					$resultats[$i][2] = $titol;
					$resultats[$i][3] = $desc;
					$resultats[$i][4] = $prio;
					$resultats[$i][5] = $motiu_prio;
					$resultats[$i][6] = $date_estimate;
					$resultats[$i][7] = $qui;
					$resultats[$i][8] = $url;

					// echo $id."<br />".$tipusRes."<br />".$qui."<br />".$titol."<br />".$desc."<br />".$prio."<br />".$motiu_prio."<br />".$date_estimate."<br />";
					$labelTipus = "<div class='d-flex justify-content-center flex-wrap'>";

					$resTipus = explode('|', $tipusRes); //omplir bd intranet amb tipus
					// print_r($resTipus);
					// echo "<br />";
					foreach ( $resTipus as $clau => $type  ) {
						if ( $type != '' ) {
							/* Obtinc un array on la columna 1 es la classe i la dos el nom del tipus.
							obtinc les dades de la taula params on param es tipus-pendents,
							tipus el ID_TIPUS i valor el nom del tipus */
							// echo " ######## TIPUS: ".$type."<br />";
							if ( $type == '10' || ( $tipus == '%01%' && $type == '01' ) ) $labelTipus == '';
							else {
								$arrayPendents = $this->__getLabelColorsPendents($type);
								$classTipus = 'mx-1 my-1 px-3 text-white fw-bold ';
								$classTipus .= $arrayPendents[0];
								$nameTipus = $arrayPendents[1];
								//Preparar labels de colors per els tipus
								$labelTipus .= $this->obtenirLabel('tipus-'.$id, $classTipus, $nameTipus);
							}
						}
					}
					$labelTipus .= '</div>';
					// echo " ######## PRIO: ".$prio."<br />";
					/* Obtinc un array on la columna 1 es la classe i la dos el nom de la prio.
					obtinc les dades de la taula params on param es prio-pendents,
					prio el ID_TIPUS i valor el nom del tipus */
					$arrayPendents = $this->__getLabelColorsPrio($prio);  //omplir bd intranet amb tipus
					$classPrio = 'mx-1 px-3 text-white fw-bold ';
					$classPrio .= $arrayPendents[0];
					$namePrio = $arrayPendents[1];
					//Preparar labels de colors per les prioritats
					$labelPrio = $this->obtenirLabel('prio-'.$id, $classPrio.' pointer w-100', $namePrio);

					$buttonValidar = 	$this->obtenirLabel('check-'.$id, ' check pointer w-100', 'FET '.$this->obtenirIconaMaterials('', '', 'verified', 'fet'));

					$classTr = '';
					//Transformar data
					if ( $date_estimate != null ) {
						$dataActual = date('Y')."-".date('m')."-".date('d');
						$date1 = new DateTime($dataActual);
						$date2 = new DateTime($date_estimate);
						$diff = $date1->diff($date2);

						if ( $diff->invert == 1 ) $classTr = 'dataPassada';
						else if ( $diff->invert == 0 && $diff->days <= 2 ) $classTr = 'diaVista';
						else if ( $diff->invert == 0 && $diff->days >= 3 && $diff->days <= 6 ) $classTr = 'setmanaVista';
						else if ( $diff->invert == 0 && $diff->days >= 7 && $diff->days <= 20 ) $classTr = 'dosSetmanesVista';

						if ( $classTr != '' ) $classTr = " class='".$classTr."'";

						$objData = new Date($date_estimate);
						$date_est = $objData->getDataFomatDDMMYYYY_HHMMSS();
					}
					else $date_est = '';
					// echo "---------------------<br />";

					if ( $url != '') $htmlUrl = "<a href='".$url."' target='_blank' class='fw-bold'>URL</a>";
					else {
						$htmlUrl = $this->__mostrarInput(0, '', '', 'd-none', 'url-'.$id, '', '');
						$htmlUrl .= $this->obtenirBoto('addUrl-'.$id, 'add-url fw-bold text-white border-0 ms-3',
						$this->obtenirIconaMaterials('', '', 'add_circle', 'ADD'));
					}

					$infoTable .= "<tr".$classTr.">
						".$this->mostrarFilaTaulaResponsive($titolsInscr[0], $labelTipus)."
						".$this->mostrarFilaTaulaResponsive($titolsInscr[1], $titol)."
						".$this->mostrarFilaTaulaResponsive($titolsInscr[2], $desc)."
						".$this->mostrarFilaTaulaResponsive($titolsInscr[3], $labelPrio)."
						".$this->mostrarFilaTaulaResponsive($titolsInscr[4], $motiu_prio)."
						".$this->mostrarFilaTaulaResponsive($titolsInscr[5], $htmlUrl)."
						".$this->mostrarFilaTaulaResponsive($titolsInscr[6], $date_est)."
						".$this->mostrarFilaTaulaResponsive($titolsInscr[7], $buttonValidar)."
					</tr>";
					$i++;
				}
			}
			else {
				$table = "";
			}
		}
		else {
			throw new Exception('', xxx);
		}

		$conIntra->desconectarBD();

		$classes = ['', '', '', ''];

		//Preparar funcions d'ordenació
		// if ( $orderBy != '' ) {
		//
		// 	if ($orderBy == 'codi') $cntOrderBy = 0;
		// 	else if ($orderBy == 'nom') $cntOrderBy = 1;
		// 	else if ($orderBy == 'dni') $cntOrderBy = 2;
		// 	else if ($orderBy == 'cog') $cntOrderBy = 3;
		//
		// 	if ($asc == 1) { //s'ordena ascendentment
		// 		$inici = 0;
		// 		$fi = count($resultats);
		// 		$i = $inici;
		// 		$condicio = $i < $fi;
		//
		// 		$classes[$cntOrderBy] = ' asc';
		// 	}
		// 	else { //s'ordena dsscendentment
		// 		$inici = count($resultats);
		// 		$fi = 0;
		// 		$i = $inici-1;
		// 		$condicio = $i >= $fi;
		//
		// 		$classes[$cntOrderBy] = ' desc';
		// 	}
		// }

		if ( count($resultats) > 0 ) {

			$table .= "<table class='table table-striped table-hover table-order table-xl-responsive text-center mt-2 mb-0'>
			<thead><tr>
				<th id='th-tipus' class='sorting".$classes[0]."'>".$titolsInscr[0]."</th>
				<th id='th-titol' class='sorting".$classes[1]."'>".$titolsInscr[1]."</th>
				<th>".$titolsInscr[2]."</th>
				<th id='th-prio' class='sorting".$classes[2]."'>".$titolsInscr[3]."</th>
				<th>".$titolsInscr[4]."</th>
				<th>".$titolsInscr[5]."</th>
				<th>".$titolsInscr[6]."</th>
				<th>".$titolsInscr[7]."</th>
			</tr></thead>
			<tbody>";
			if ( $orderBy != '' )
				$infoTable = $this->__mostrarResultatsLlegendaMRKTCalendariOrdenatsPerUnCamp($titolsInscr, $resultats, $orderBy, $asc);
			$table .= $infoTable;
			$table .= "</tbody></table>";
		}
		else {
			$table = "";
		}
		return $table;
	}

