	public function __getLabelColorsPendents( $type ) {
		/* Obtinc un array on la columna 1 es la classe i la dos el nom del tipus.
		obtinc les dades de la taula params on param es tipus-pendents,
		tipus el ID_TIPUS i valor el nom del tipus */
		$param = "tipus-pendents";
		$className = $this->__getParamsBD($param, $type);
		$results = explode('|', $className);
		// print_r($results);
		// ECHO "<BR />";
		return $results;
	}

	public function __getLabelColorsPrio( $prio ) {
		/* Obtinc un array on la columna 1 es la classe i la dos el nom de la prio.
		obtinc les dades de la taula params on param es prio-pendents,
		prio el ID_TIPUS i valor el nom del tipus */
		$param = "prio-pendents";
		$className = $this->__getParamsBD($param, $prio);
		$results = explode('|', $className);
		// print_r($results);
		// ECHO "<BR />";
		return $results;
	}

	public function checkCalendar($id) {
		$conIntra = new ConnexioIntranet();
		$conIntra->connectarBD();

		if ( $stmt=$conIntra->prepare( $this->consultesBD_Intra["updRegPendent"] ) ) {
			$stmt->bind_param("d", $id);
			$stmt->execute();
			$conIntra->closeStmt();
		}
		else {
			throw new Exception('', xxx);
		}

		$conIntra->desconectarBD();

	}

	public function addUrl($id, $url) {
