	         <th>".$titolsInscr[3]."</th>
	         <th>".$titolsInscr[4]."</th>
	         <th>".$titolsInscr[5]."</th>
	         <th>".$titolsInscr[6]."</th>
	         <th>".$titolsInscr[7]."</th>
	      </tr></thead>
	      <tbody>";
	      $table .= $infoTable;
	      $table .= "</tbody></table>";
	   }
	   else {
