   }

	public function insertPublicacio_Xarxes_Mensual($nomPost, $tipusPost, $descPost, $any, $mes, $dia ) {

		// TEMPLATE
		require_once 'Template.php';
		require_once 'Date.php';
		$templates = new Template();
		if ( $tipusPost == 'FRASE')
			$msg = $templates->viewTemplateFrase();
		else if ( $tipusPost == 'INICI')
			$msg = $templates->viewTemplateInici();
		else if ( $tipusPost == 'EDICIÓ')
			$msg = $templates->viewTemplateEdicio();
		else
			$msg = $templates->viewTemplatePublicacio();

		$objData = new Date($any."-".$mes."-".$dia);
		$textMesPub = $mes;
