			if ($stmt->num_rows() > 0) {
				$stmt->bind_result($idPost);
				$stmt->fetch();
				$idPost = intval($idPost)+1;
			}
			// else {
			// 	throw new Exception('', 4629);
			// }
			$conMdl->closeStmt();
		}
		// else {
		// 	throw new Exception('', 4625);
		// }

		$conMdl2 = new ConnexioMoodle();
		$conMdl2->connectarBD();

		if ( $stmt2=$conMdl2->prepare( $this->consultesBD_Moodle["insertForumPost"] ) ) {
			$stmt2->bind_param("dddddddssdddd", $idPost, $idDiscussion, $parent, $userId, $dateCreate,
				$dateModified, $mailed, $subject, $message, $messageformat, $messagetrust,
				$totalscore, $mailnow);
			$parent = $mailed = $totalscore = $mailnow = 0;
			$messageformat = $messagetrust = 1;
			$dateCreate = $dateModified = $time;

			$stmt2->execute();
			$conMdl2->closeStmt();
		}
		if ( $stmt=$conMdl->prepare( $this->consultesBD_Moodle["insertForumDiscussion"] ) ) {
			$stmt->bind_param("dddsdddddddd", $idDiscussion, $idCourseMdl, $idForum,
			$subject, $idPost, $userId, $groupId, $assessed, $timeModified,
			$userModified, $timeStart, $timeEnd);
			$groupId = $assessed = 1;
			$timeStart = $timeEnd = 0;
			$timeModified = $time;
			$userModified = $userId;
			$stmt->execute();
		}
		$conMdl->closeStmt();

		$conIntra = new ConnexioIntranet();
		$conIntra->connectarBD();

		// INSERT INTO PENDENTS
		// SI EXISTEIX, ACTUALITZAR REGISTRE AMB DATA D'AVUI AMB DOIT = 1 i data realitzada now
		// SI NO EXISTEIX, INSERIR REGISTRE

		// consulta si existeix a la taula pendents per actualizar o inserir registre
		if ( $stmt=$conIntra->prepare( $this->consultesBD_Intra["cnsElemPendentByDate"] ) ) {
		   $stmt->bind_param("sss", $tipus, $qui, $dataEstimada);
			$tipus = '%04%';
			$qui = 'meriem_developer';
			$dataEstimada = $any."-".$mes."-".$dia;
		   $stmt->execute();
		   $stmt->store_result();
		   if ($stmt->num_rows() > 0) {
				ECHO "p-existeix.<br />";
		      $conIntra->closeStmt();
		      // existeix, per tant, update
		      if ( $stmt=$conIntra->prepare( $this->consultesBD_Intra["updPendent"] ) ) {
		         $stmt->bind_param("dss", $doit, $dataEstimada, $tipus);
					$doit = 1;
		         $stmt->execute();
		      }
				echo $this->consultesBD_Intra['updPendent']."<br />";
				echo $doit."<br />";
				echo $dataEstimada."<br />";
				echo $tipus."<br />";
				$conIntra->closeStmt();
		   }
		   else {
		      $conIntra->closeStmt();
				ECHO "p-no existeix.<br />";
		      // no existeix, per tant, insert

				echo $this->consultesBD_Intra["insertPendents"]."<br />";
				echo $tipus." ".$titol." ".$descripcio." ".$url." ".$prioritat." ".$dataEstimada." ".$doit."</br>";

		      if ( $stmt=$conIntra->prepare( $this->consultesBD_Intra["insertPendents"] ) ) {
		         $stmt->bind_param("ssssdsd", $tipus, $titol, $descripcio, $url, $prioritat, $dataEstimada, $doit);
					$tipus = '04|01';
					$titol = $nomPost;
					$descripcio = 'publicació';
					$url = "https://campus.prisma.cat/mod/forum/discuss.php?d=".$idDiscussion;
					$prioritat = 0;
					$doit = 1;
		         $stmt->execute();
		      }
				$conIntra->closeStmt();
		   }
		}


		// SI EXISTEIX, ACTUALITZAR REGISTRE AMB DATA D'AVUI AMB IDPOST = idPost
		// SI NO EXISTEIX, INSERIR REGISTRE

		// consulta si existeix a la taula xarxes_dates per actualizar o inserir registre
		if ( $stmt=$conIntra->prepare( $this->consultesBD_Intra["cnsElemXarxesByDate"] ) ) {
		   $stmt->bind_param("s", $data);
			$data = $any."-".$mes."-".$dia;
		   $stmt->execute();
		   $stmt->store_result();
		   if ($stmt->num_rows() > 0) {
		      $conIntra->closeStmt();
				ECHO "xd-existeix.<br />";
		      // existeix, per tant, update
		      if ( $stmt=$conIntra->prepare( $this->consultesBD_Intra["updXarxesDates"] ) ) {
		         $stmt->bind_param("ds", $idDiscussion, $data );
					$data = $any."-".$mes."-".$dia;
		         $stmt->execute();
		      }
				$conIntra->closeStmt();
		   }
		   else {
		      $conIntra->closeStmt();
				ECHO "xd-no existeix.<br />";
				echo $this->consultesBD_Intra["insertXarxes"]."<br />";
				echo $nomPost." ".$tipusPost." ".$any."-".$mes."-".$dia." ".$descPost." ".$idDiscussion."<br />";
		      // no existeix, per tant, insert
		      if ( $stmt=$conIntra->prepare( $this->consultesBD_Intra["insertXarxes"] ) ) {
		         $stmt->bind_param("ssssd", $nom, $tipus, $data, $textPubli, $idDiscussion);
					$textPubli = $tipus = $nom = '';
					$nom = $nomPost;
					$tipus = $tipusPost;
					// $textPubli = $descPost;
					$data = $any."-".$mes."-".$dia;
		         $stmt->execute();
		      }
				$conIntra->closeStmt();
		   }
		}

		$conIntra->desconectarBD();
	}

