	public function comprovaAlumnaEsMoros( $dni ) {
		$conWeb = new ConnexioWeb();
		$conWeb->connectarBD();

		if ( $stmt=$conWeb->prepare( $this->consultesBD_Web["cnsExMoros"] ) ) {
			$stmt->bind_param("s", $dni);
			$stmt->execute();
			$stmt->store_result();
			$exMoros = $stmt->num_rows() > 0;
			$conWeb->closeStmt();
		}
		else {
			throw new Exception('',4526);
		}

		$conWeb->desconectarBD();

