	private function __getListParamsBD( $param ) {
		$resultats = []; $i = 0;

		$conIntra = new ConnexioIntranet();
		$conIntra->connectarBD();

 	  if ( $stmt=$conIntra->prepare( $this->consultesBD_Intra["buscarListParam"] ) ) {
 		  $stmt->bind_param("s", $param);
 		  $stmt->execute();
 		  $stmt->bind_result($tipus, $valor);
 		  while($stmt->fetch()) {
			  $resultats[$i][0] = $tipus;
			  $resultats[$i][1] = $valor;
			  $i++;
		  }
 		  $conIntra->closeStmt();
 	  }
 	  else
 		  throw new Exception('',xxx);

	  $conIntra->desconectarBD();
	  return $resultats;
	}

