		else if ( $tipus == 4 ) //Tipus fitxer
			$mostrar .= "<input type='file' accept='.csv' class='form-control ".$classInput."'
			".$textId." />";
		else
			$mostrar .= "<input type='text' class='form-control ".$classInput."'
